#[derive(Debug, Clone, PartialEq, Eq)]
enum RuntimeStatus {
    Starting,
    Ready,
    Failed { code: String, message: String },
}

/// A paired remote runtime driving this workbench. Holds the runtime's
/// registry id and the backend built from its credential; the workbench
/// consumes the same facade slots the native backend fills, so no view knows
/// which one is live.
struct DesktopRemoteClient {
    runtime_id: String,
    credential: DesktopRemoteCredential,
    backend: Arc<WebRemoteBackend>,
}

/// Which stage of the runtime manager panel is showing. The panel keeps one
/// floating surface and swaps its body, so management never stacks overlays.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum RuntimeManagerStage {
    List,
    Detail,
    /// Pairing a new runtime, filled in inside the panel rather than a dialog.
    Add,
}

/// Which pairing entry the add-runtime form is collecting.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
enum RuntimeAddTab {
    #[default]
    Code,
    Link,
}

/// Why a remote runtime is being connected: the first frame of a session, or
/// an operator switching authorities. Only the boot case may fall back to the
/// embedded runtime, because only the boot case has nothing installed yet.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum RuntimeConnectOrigin {
    Boot,
    Switch,
}

/// How the operator handed over the pairing entry: a typed address plus code,
/// or the connection link `vibex-server` printed.
enum RemotePairingEntry {
    Code {
        server_url: String,
        pairing_code: String,
    },
    Link {
        pairing_link: String,
    },
}

impl DesktopRemoteClient {
    /// Builds the backend from the credential and verifies the handshake. The
    /// caller writes the registry only after this succeeds, so a failed
    /// connect leaves no stored grant behind.
    async fn start(runtime_id: String, credential: DesktopRemoteCredential) -> BackendResult<Self> {
        let backend = credential.backend()?;
        backend.connect().await?;
        Ok(Self {
            runtime_id,
            credential,
            backend,
        })
    }
}

/// Sidebar authority key for a paired server, derived from the credential so
/// the arrangement survives reconnects to the same runtime.
fn remote_authority_key(credential: &DesktopRemoteCredential) -> String {
    format!("server:{}", credential.expected_server_id)
}

struct ForkSessionNotification;

struct AmbiguousMessageSubmissionNotification;

struct PersistenceNotification;

struct SettingsOperationNotification;

/// The tone a settings operation result is announced with.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SettingsOperationTone {
    Success,
    Error,
}

/// One settings operation result, announced as a light hint on the notification
/// layer.
///
/// The result answers something the user just asked for — an update check that
/// stopped, a proxy that was rejected, storage that was cleared — so it belongs
/// on the notification layer rather than in a page banner that the next
/// operation would have to remember to clear.
#[derive(Debug, Clone, PartialEq, Eq)]
struct SettingsOperationNotice {
    tone: SettingsOperationTone,
    message: String,
}

impl SettingsOperationNotice {
    fn success(message: impl Into<String>) -> Self {
        Self {
            tone: SettingsOperationTone::Success,
            message: message.into(),
        }
    }

    fn error(message: impl Into<String>) -> Self {
        Self {
            tone: SettingsOperationTone::Error,
            message: message.into(),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ReleaseChannel {
    Preview,
    ReleaseCandidate,
    Stable,
}

