fn touch_session_view_lru(lru: &mut VecDeque<String>, key: &str) {
    lru.retain(|cached| cached != key);
    lru.push_back(key.to_string());
}

/// The bound one session-view store keeps: how many views, and how many bytes.
struct SessionViewBudget {
    limit: usize,
    max_bytes: usize,
}

/// Stores a session view, evicting least-recently-used entries that are not
/// pinned.
///
/// The bound is a memory guard for sessions nobody is looking at. A pinned view
/// (the selected session, or any session a group workspace is showing) is never
/// evicted, because dropping it would blank a pane that is on screen.
fn insert_bounded_session_view_with_pins<T>(
    cache: &mut BTreeMap<String, T>,
    lru: &mut VecDeque<String>,
    key: String,
    entry: T,
    budget: SessionViewBudget,
    weight: impl Fn(&T) -> usize,
    pinned: &BTreeSet<String>,
) {
    let SessionViewBudget { limit, max_bytes } = budget;
    let entry_bytes = weight(&entry);
    cache.remove(&key);
    lru.retain(|cached| cached != &key);
    if limit == 0 || entry_bytes > max_bytes {
        return;
    }
    cache.insert(key.clone(), entry);
    touch_session_view_lru(lru, &key);
    let mut total_bytes = cache
        .values()
        .map(&weight)
        .fold(0_usize, usize::saturating_add);
    let mut index = 0;
    while (lru.len() > limit || total_bytes > max_bytes) && index < lru.len() {
        let candidate = lru[index].clone();
        if pinned.contains(&candidate) || candidate == key {
            index += 1;
            continue;
        }
        lru.remove(index);
        if let Some(entry) = cache.remove(&candidate) {
            total_bytes = total_bytes.saturating_sub(weight(&entry));
        }
    }
}

fn insert_bounded_timeline_projection<T>(
    cache: &mut BTreeMap<String, (i64, T)>,
    key: String,
    sequence: i64,
    value: T,
    max_entries: usize,
    max_bytes: usize,
    weight: impl Fn(&T) -> usize,
) {
    if max_entries == 0 {
        cache.clear();
        return;
    }
    cache.insert(key.clone(), (sequence, value));
    loop {
        let total_bytes = cache
            .values()
            .map(|(_, value)| weight(value))
            .sum::<usize>();
        if cache.len() <= max_entries && total_bytes <= max_bytes {
            break;
        }
        let evicted = cache
            .iter()
            .filter(|(candidate, _)| candidate.as_str() != key)
            .max_by_key(|(_, (candidate_sequence, _))| candidate_sequence.abs_diff(sequence))
            .map(|(candidate, _)| candidate.clone());
        let Some(evicted) = evicted else {
            // One visible entry may itself exceed the byte budget. Retain it so
            // the active Markdown row does not allocate its source every frame.
            break;
        };
        cache.remove(&evicted);
    }
}

#[derive(Clone)]
struct TimelineMarkdownSourceSnapshot {
    source: Arc<str>,
    refreshed_at: Instant,
}

#[derive(Clone)]
struct AgentReasoningSummary {
    plain: Arc<str>,
    preview: Arc<str>,
    tooltip: Arc<str>,
    has_more: bool,
}

// Collapsed reasoning rows sit inside an animated GPUI subtree. Keep their
// parsed projection outside the render closure so shimmer repaints do not
// reparse the streaming Markdown source.
#[derive(Clone)]
struct TimelineReasoningSummarySnapshot {
    source_len: usize,
    source_ptr: usize,
    refreshed_at: Instant,
    summary: AgentReasoningSummary,
}

fn timeline_reasoning_summary_cached_at(
    cache: &mut BTreeMap<String, (i64, TimelineReasoningSummarySnapshot)>,
    key: String,
    sequence: i64,
    source: &str,
    allow_throttle: bool,
    now: Instant,
) -> AgentReasoningSummary {
    let source_ptr = source.as_ptr() as usize;
    if let Some((cached_sequence, snapshot)) = cache.get(&key)
        && *cached_sequence == sequence
        && snapshot.source_len == source.len()
        && snapshot.source_ptr == source_ptr
    {
        return snapshot.summary.clone();
    }

    if allow_throttle
        && let Some((_, snapshot)) = cache.get(&key)
        && source.len() > snapshot.source_len
        && source_ptr == snapshot.source_ptr
        && now.saturating_duration_since(snapshot.refreshed_at)
            < TIMELINE_STREAMING_MARKDOWN_REFRESH_INTERVAL
        && source.len().saturating_sub(snapshot.source_len)
            < TIMELINE_STREAMING_MARKDOWN_REFRESH_BYTES
    {
        return snapshot.summary.clone();
    }

    let (plain, _) = agent_markdown_summary(source);
    let plain: Arc<str> = Arc::from(plain);
    let preview: Arc<str> = Arc::from(reasoning_preview_text(&plain));
    let tooltip: Arc<str> = Arc::from(plain.trim());
    let summary = AgentReasoningSummary {
        has_more: plain.chars().count() > AGENT_THINKING_LABEL_MAX_CHARS,
        plain,
        preview,
        tooltip,
    };
    insert_bounded_timeline_projection(
        cache,
        key,
        sequence,
        TimelineReasoningSummarySnapshot {
            source_len: source.len(),
            source_ptr,
            refreshed_at: now,
            summary: summary.clone(),
        },
        TIMELINE_REASONING_SUMMARY_CACHE_LIMIT,
        TIMELINE_REASONING_SUMMARY_CACHE_BYTES,
        |snapshot| {
            snapshot
                .summary
                .plain
                .len()
                .saturating_add(snapshot.summary.preview.len())
                .saturating_add(snapshot.summary.tooltip.len())
        },
    );
    summary
}

#[cfg(test)]
fn timeline_reasoning_summary_cached(
    cache: &mut BTreeMap<String, (i64, TimelineReasoningSummarySnapshot)>,
    key: String,
    sequence: i64,
    source: &str,
) -> AgentReasoningSummary {
    timeline_reasoning_summary_cached_at(cache, key, sequence, source, false, Instant::now())
}

/// Copy a streaming Markdown source at most once per time/byte window.
///
/// `sequence` is the caller's content revision. The returned sequence is the
/// revision that was actually snapshotted, so a throttled call keeps returning
/// the previous revision and the downstream `MarkdownView` does not reparse a
/// source it already holds. This is shared by timeline rows and the expanded
/// live reasoning body, which has no `TimelineRow` of its own.
fn timeline_markdown_source_snapshot(
    cache: &mut BTreeMap<String, (i64, TimelineMarkdownSourceSnapshot)>,
    key: &str,
    source: &str,
    sequence: i64,
    streaming: bool,
    now: Instant,
    allow_throttle: bool,
) -> (Arc<str>, i64) {
    if let Some((cached_sequence, snapshot)) = cache.get(key) {
        // A revision match means the caller handed back the same content. Only
        // an append can keep that revision while growing the text, so length is
        // enough to tell the two apart; comparing the bodies here would put a
        // full memcmp of every visible row body into every frame.
        if *cached_sequence == sequence && snapshot.source.len() == source.len() {
            return (snapshot.source.clone(), *cached_sequence);
        }
        if streaming && allow_throttle {
            let pending_bytes = source.len().abs_diff(snapshot.source.len());
            if source.len() > snapshot.source.len()
                && now.saturating_duration_since(snapshot.refreshed_at)
                    < TIMELINE_STREAMING_MARKDOWN_REFRESH_INTERVAL
                && pending_bytes < TIMELINE_STREAMING_MARKDOWN_REFRESH_BYTES
            {
                return (snapshot.source.clone(), *cached_sequence);
            }
        }
    }

    let source: Arc<str> = Arc::from(source);
    insert_bounded_timeline_projection(
        cache,
        key.to_string(),
        sequence,
        TimelineMarkdownSourceSnapshot {
            source: source.clone(),
            refreshed_at: now,
        },
        TIMELINE_MARKDOWN_SOURCE_CACHE_LIMIT,
        TIMELINE_MARKDOWN_SOURCE_CACHE_BYTES,
        |snapshot| snapshot.source.len(),
    );
    (source, sequence)
}

/// Cadence the selected session's fallback poll drops to while the workbench
/// window is in the background.
const AGENT_TIMELINE_INACTIVE_POLL_MS: u64 = 2_000;

fn agent_timeline_poll_interval(base_ms: u64, idle_poll_count: u16) -> Duration {
    let base_ms = base_ms.max(1);
    let exponent = idle_poll_count
        .saturating_sub(AGENT_TIMELINE_IDLE_POLL_THRESHOLD)
        .min(8) as u32;
    let multiplier = 1_u64.checked_shl(exponent).unwrap_or(u64::MAX);
    Duration::from_millis(
        base_ms
            .saturating_mul(multiplier)
            .min(AGENT_TIMELINE_IDLE_POLL_MAX_MS.max(base_ms)),
    )
}

fn agent_turn_completion_is_active(
    current_generation: u64,
    turn_generation: u64,
    selected_session_id: Option<&VibexSessionId>,
    turn_session_id: &VibexSessionId,
) -> bool {
    current_generation == turn_generation && selected_session_id == Some(turn_session_id)
}

fn composer_submission_status_is_actionable(status: MessageSubmissionStatus) -> bool {
    matches!(
        status,
        MessageSubmissionStatus::Failed | MessageSubmissionStatus::Cancelled
    )
}

/// A submission whose prompt already reached the provider and then failed in
/// the turn itself (retry exhaustion, terminal provider error, abnormal stop)
/// records `dispatched_at_ms`. That failure is owned by the timeline — error
/// items plus auto-continue — so it must not surface as a "message was not
/// sent" composer bar.
fn composer_submission_failure_reached_provider(state: &MessageSubmissionState) -> bool {
    state.status == MessageSubmissionStatus::Failed && state.dispatched_at_ms.is_some()
}

fn ambiguous_message_submission_notice() -> &'static str {
    locale::text(
        "There was a problem sending your message. Please try again shortly.",
        "消息发送遇到异常，请稍后再试。",
        "訊息傳送遇到異常，請稍後再試。",
    )
}

/// Deferred paint priority for the notification layer.
///
/// Tree order does not decide z-order in GPUI: the kit renders dialogs as
/// deferred draws at priority `10 + layer`, popups (menus, selects, popovers)
/// at `gpui_base::POPUP_PRIORITY` (100), and tooltips at 200. An inline layer
/// therefore paints under a dialog's backdrop, which is what dimmed every hint
/// pushed while a dialog was still open. The layer takes the gap between the
/// dialog band and the popup band: above every dialog backdrop, below the menus
/// and tooltips the user is actively pointing at.
const NOTIFICATION_LAYER_PRIORITY: usize = 99;

/// The workbench's top-centered hint layer.
///
/// The hints it hosts answer an action the user just took, and the dialog that
/// asked for the action is often still open, so the layer is deferred at
/// [`NOTIFICATION_LAYER_PRIORITY`] instead of relying on where the root happens
/// to mount it.
fn render_top_centered_notification_layer(window: &Window, cx: &App) -> impl IntoElement + use<> {
    deferred(
        div()
            .absolute()
            .top_0()
            .left_0()
            .right_0()
            .flex()
            .justify_center()
            .child(Root::read(window, cx).notification.clone()),
    )
    .with_priority(NOTIFICATION_LAYER_PRIORITY)
}

impl VibexWorkbench {
    fn present_persistence_note(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some(note) = self.persistence_note.take() else {
            return;
        };
        window.defer(cx, move |window, cx| {
            Theme::global_mut(cx).notification.placement = Anchor::TopCenter;
            window.push_notification(
                hint_notification(
                    NotificationType::Info,
                    locale::localize_ui_message(&note),
                    cx,
                )
                .id::<PersistenceNotification>()
                .autohide(true)
                .on_click(|_, _, _| {}),
                cx,
            );
        });
    }

    /// Queues a settings operation result for the notification layer.
    ///
    /// The settings page is a dialog, so a banner inside it competes with the
    /// controls it sits above; the result of an action is a light hint and rides
    /// the same top-centered layer as the workbench's other feedback.
    fn queue_settings_operation_notice(
        &mut self,
        notice: SettingsOperationNotice,
        cx: &mut Context<Self>,
    ) {
        self.settings_operation_notice = Some(notice);
        cx.notify();
    }

    fn present_settings_operation_notice(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some(notice) = self.settings_operation_notice.take() else {
            return;
        };
        window.defer(cx, move |window, cx| {
            Theme::global_mut(cx).notification.placement = Anchor::TopCenter;
            let notification = match notice.tone {
                SettingsOperationTone::Success => {
                    hint_notification(NotificationType::Success, notice.message, cx)
                }
                SettingsOperationTone::Error => {
                    hint_notification(NotificationType::Error, notice.message, cx)
                }
            };
            window.push_notification(
                notification
                    .id::<SettingsOperationNotification>()
                    .autohide(true)
                    .on_click(|_, _, _| {}),
                cx,
            );
        });
    }
}

fn runtime_status_banner_is_visible(status: SessionRuntimeSelectionStatus) -> bool {
    // Runtime preparation is deliberately presentation-transparent. The
    // composer keeps the desired selection visible while durable submission
    // waits in the background; only a failed switch needs an actionable row.
    status == SessionRuntimeSelectionStatus::FailedUsingPrevious
}

fn composer_surface_background(is_dark: bool) -> Hsla {
    theme::semantic_color("composer-surface", is_dark)
}

fn composer_queue_surface_background(is_dark: bool) -> Hsla {
    theme::semantic_color("composer-queue", is_dark).opacity(COMPOSER_EXTENSION_SURFACE_OPACITY)
}

fn composer_plan_progress_label(
    locale: locale::ResolvedLocale,
    current_step: usize,
    total_steps: usize,
) -> String {
    match locale {
        locale::ResolvedLocale::En => format!("Step {current_step} / {total_steps}"),
        locale::ResolvedLocale::ZhCn => format!("步骤 {current_step} / {total_steps}"),
        locale::ResolvedLocale::ZhTw => format!("步驟 {current_step} / {total_steps}"),
    }
}

fn composer_plan_completed_steps_label(
    locale: locale::ResolvedLocale,
    completed_steps: usize,
    total_steps: usize,
) -> String {
    match locale {
        locale::ResolvedLocale::En => format!("{completed_steps} of {total_steps} completed"),
        locale::ResolvedLocale::ZhCn => format!("已完成 {completed_steps} / {total_steps}"),
        locale::ResolvedLocale::ZhTw => format!("已完成 {completed_steps} / {total_steps}"),
    }
}

fn composer_plan_step_status_label(status: PlanStepStatus) -> &'static str {
    match status {
        PlanStepStatus::Pending => locale::text("Pending", "待处理", "待處理"),
        PlanStepStatus::Running => locale::text("Running", "进行中", "進行中"),
        PlanStepStatus::Completed => locale::text("Completed", "已完成", "已完成"),
        PlanStepStatus::Failed => locale::text("Failed", "失败", "失敗"),
    }
}

fn composer_plan_identity(
    session_id: &VibexSessionId,
    plan: &AgentPlanProjection,
    items: &[TimelineItem],
) -> ComposerPlanIdentity {
    let plan_sequence = items
        .iter()
        .rev()
        .filter(|item| item.sequence > plan.turn_anchor_sequence && item.sequence <= plan.sequence)
        .find_map(|item| match &item.payload {
            TimelinePayload::Plan(plan) if !plan.steps.is_empty() => Some(item.sequence),
            _ => None,
        })
        .or_else(|| {
            items
                .iter()
                .filter(|item| {
                    item.sequence > plan.turn_anchor_sequence && item.sequence <= plan.sequence
                })
                .find_map(|item| match &item.payload {
                    TimelinePayload::TodoUpdate(todo) if !todo.items.is_empty() => {
                        Some(item.sequence)
                    }
                    _ => None,
                })
        })
        .unwrap_or(plan.sequence);

    ComposerPlanIdentity {
        session_id: session_id.as_str().to_string(),
        plan_sequence,
    }
}

fn render_composer_plan_details(
    plan: &AgentPlanProjection,
    title: SharedString,
    completed_label: SharedString,
    surface_id: &'static str,
    width: Option<f32>,
    max_height: f32,
    cx: &App,
) -> AnyElement {
    // Clamp the scrolling element itself instead of a flex/percentage
    // viewport: inside this auto-height card those resolve to zero height or
    // full content height, while a max_h on the scroll container gives it a
    // real box to scroll within. Same idiom as the queued-message preview.
    let mut step_list = v_flex()
        .id(SharedString::from(format!(
            "composer-plan-steps-{surface_id}"
        )))
        .w_full()
        .max_h(px(max_height - 74.0))
        .overflow_y_scroll();
    for (index, step) in plan.steps.iter().enumerate() {
        let icon = match step.status {
            PlanStepStatus::Pending => div()
                .size(px(14.0))
                .rounded_full()
                .border_1()
                .border_color(cx.theme().muted_foreground.opacity(0.50))
                .into_any_element(),
            PlanStepStatus::Running => ProgressCircle::new(format!(
                "composer-plan-{surface_id}-running-{}-{index}",
                plan.turn_anchor_sequence
            ))
            .loading(true)
            .color(cx.theme().primary)
            .size(px(22.0))
            .into_any_element(),
            PlanStepStatus::Completed => Icon::new(IconName::CircleCheck)
                .size(px(17.0))
                .text_color(cx.theme().success)
                .into_any_element(),
            PlanStepStatus::Failed => Icon::new(IconName::CircleX)
                .size(px(17.0))
                .text_color(cx.theme().danger)
                .into_any_element(),
        };
        step_list = step_list.child(
            h_flex()
                .w_full()
                .min_w_0()
                .min_h(px(34.0))
                .items_start()
                .gap_2()
                .py_1()
                .child(
                    div()
                        .w(px(18.0))
                        .h(px(20.0))
                        .flex_none()
                        .flex()
                        .items_center()
                        .justify_center()
                        .child(icon),
                )
                .child(
                    div()
                        .min_w_0()
                        .flex_1()
                        .whitespace_normal()
                        .text_sm()
                        .line_height(gpui::relative(1.5))
                        .text_color(if step.status == PlanStepStatus::Pending {
                            cx.theme().muted_foreground
                        } else {
                            cx.theme().popover_foreground
                        })
                        .child(step.title.clone()),
                )
                .child(
                    div()
                        .flex_none()
                        .pt(px(2.0))
                        .text_xs()
                        .text_color(match step.status {
                            PlanStepStatus::Running => cx.theme().primary,
                            PlanStepStatus::Completed => cx.theme().success,
                            PlanStepStatus::Failed => cx.theme().danger,
                            PlanStepStatus::Pending => cx.theme().muted_foreground,
                        })
                        .child(composer_plan_step_status_label(step.status)),
                ),
        );
    }

    v_flex()
        .w_full()
        .when_some(width, |this, width| this.w(px(width)))
        .max_h(px(max_height))
        .gap_2()
        .p_2()
        .child(
            h_flex()
                .w_full()
                .min_w_0()
                .items_center()
                .gap_2()
                .child(
                    Icon::default()
                        .path("icons/vibex/list-checks.svg")
                        .size(px(16.0))
                        .text_color(cx.theme().primary),
                )
                .child(
                    div()
                        .min_w_0()
                        .flex_1()
                        .truncate()
                        .font_medium()
                        .child(title),
                )
                .child(
                    div()
                        .flex_none()
                        .text_xs()
                        .text_color(cx.theme().muted_foreground)
                        .child(completed_label),
                ),
        )
        .child(div().w_full().h(px(1.0)).bg(cx.theme().border))
        .child(step_list)
        .into_any_element()
}

fn partition_terminal_sessions(
    terminals: Vec<TerminalSession>,
    composer_terminal_ids: &[String],
) -> (Vec<TerminalSession>, Vec<TerminalSession>) {
    let composer_ids = composer_terminal_ids
        .iter()
        .map(String::as_str)
        .collect::<BTreeSet<_>>();
    terminals
        .into_iter()
        .partition(|terminal| composer_ids.contains(terminal.id.as_str()))
}

fn terminal_tab_title(terminal: &TerminalSession, overrides: &BTreeMap<String, String>) -> String {
    overrides
        .get(terminal.id.as_str())
        .map(|title| title.trim())
        .filter(|title| !title.is_empty())
        .unwrap_or(&terminal.title)
        .to_string()
}

fn order_terminal_sessions(
    mut terminals: Vec<TerminalSession>,
    order: &[String],
) -> Vec<TerminalSession> {
    let positions = order
        .iter()
        .enumerate()
        .map(|(index, terminal_id)| (terminal_id.as_str(), index))
        .collect::<BTreeMap<_, _>>();
    terminals.sort_by_key(|terminal| {
        positions
            .get(terminal.id.as_str())
            .copied()
            .unwrap_or(usize::MAX)
    });
    terminals
}

fn terminal_shell_label(shell: &str) -> String {
    std::path::Path::new(shell)
        .file_name()
        .and_then(|name| name.to_str())
        .filter(|name| !name.is_empty())
        .unwrap_or(shell)
        .to_string()
}

fn composer_terminal_shell_options(current_shell: Option<&str>) -> Vec<(String, String)> {
    let mut options = available_shells();
    if let Some(current_shell) = current_shell
        .map(str::trim)
        .filter(|shell| !shell.is_empty())
        && !options.iter().any(|(_, path)| path == current_shell)
    {
        options.insert(
            0,
            (
                terminal_shell_label(current_shell),
                current_shell.to_string(),
            ),
        );
    }
    options
}

fn toggle_exclusive_overlay(target_open: bool, competing_open: bool) -> (bool, bool) {
    let target_open = !target_open;
    (target_open, competing_open && !target_open)
}

fn resolved_right_rail_overlay_open(
    right_rail_docked: bool,
    right_rail_requested_open: bool,
    right_rail_suppressed: bool,
    preview_overlay_open: bool,
) -> bool {
    !right_rail_docked
        && right_rail_requested_open
        && !right_rail_suppressed
        && !preview_overlay_open
}

fn resized_right_panel_width(
    start_width: f32,
    start_window_x: f32,
    window_x: f32,
    min_width: f32,
    max_width: f32,
) -> f32 {
    (start_width - (window_x - start_window_x))
        .round()
        .clamp(min_width, max_width)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct WorkbenchAutoCollapseState {
    sidebar: bool,
}

fn calculate_workbench_auto_collapse(
    viewport_width: u32,
    sidebar_open: bool,
    right_rail_open: bool,
    preview_side_open: bool,
    sidebar_width: f32,
    right_rail_width: f32,
) -> WorkbenchAutoCollapseState {
    let right_rail_required_width = if right_rail_open {
        right_rail_width
    } else {
        RIGHT_ACTIVITY_BAR_WIDTH
    };
    let preview_required_width = if preview_side_open {
        PREVIEW_PANEL_MIN_WIDTH
    } else {
        0.0
    };
    let minimum_center_width = if preview_side_open {
        WORKBENCH_PREVIEW_MIN_CENTER_WIDTH
    } else {
        WORKBENCH_MIN_CENTER_WIDTH
    };
    let occupied_width = if sidebar_open { sidebar_width } else { 0.0 }
        + right_rail_required_width
        + preview_required_width;
    let sidebar = sidebar_open && viewport_width as f32 - occupied_width < minimum_center_width;

    WorkbenchAutoCollapseState { sidebar }
}

fn right_rail_mode_from_activity_id(activity_id: Option<&str>) -> RightRailMode {
    match activity_id {
        Some("rail_plugin_system_git") => RightRailMode::Git,
        _ => RightRailMode::Files,
    }
}

fn right_rail_activity_id(mode: RightRailMode) -> &'static str {
    match mode {
        RightRailMode::Files => "rail_plugin_system_files",
        RightRailMode::Git => "rail_plugin_system_git",
    }
}

fn route_right_rail_activity_id(value: &str) -> Option<String> {
    match value.trim() {
        "" => None,
        "files" => Some(right_rail_activity_id(RightRailMode::Files).to_string()),
        "git" => Some(right_rail_activity_id(RightRailMode::Git).to_string()),
        value => Some(value.to_string()),
    }
}

fn right_rail_mode_icon(mode: RightRailMode) -> Icon {
    match mode {
        RightRailMode::Files => Icon::new(IconName::Folder),
        RightRailMode::Git => Icon::default().path("icons/vibex/git-branch.svg"),
    }
}

fn right_rail_activity_button(id: impl Into<ElementId>, icon: Icon) -> Button {
    Button::new(id)
        .ghost()
        .size(px(RIGHT_ACTIVITY_BUTTON_SIZE))
        .icon(icon)
}

/// One button in the right rail's activity bar.
///
/// The ids are the keys of the persisted activity order, so they must stay
/// stable: a button that changes its id loses its place.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
enum RightRailActivity {
    Editor,
    Files,
    Git,
    Terminal,
    /// Opens the embedded-browser tool panel. The browser is a tool panel of
    /// the same rank as the terminal, not an application shell.
    Browser,
    ChildAgents,
}

impl RightRailActivity {
    /// Every button, in the order a fresh install shows them.
    const ALL: [Self; 6] = [
        Self::Editor,
        Self::Files,
        Self::Git,
        Self::Terminal,
        Self::Browser,
        Self::ChildAgents,
    ];

    fn id(self) -> &'static str {
        match self {
            Self::Editor => "rail_activity_editor",
            Self::Files => right_rail_activity_id(RightRailMode::Files),
            Self::Git => right_rail_activity_id(RightRailMode::Git),
            Self::Terminal => "rail_activity_terminal",
            Self::Browser => "rail_activity_browser",
            Self::ChildAgents => "rail_activity_child_agents",
        }
    }

    fn icon(self) -> Icon {
        match self {
            Self::Editor => Icon::default().path("icons/vibex/sidebar-right.svg"),
            Self::Files => right_rail_mode_icon(RightRailMode::Files),
            Self::Git => right_rail_mode_icon(RightRailMode::Git),
            Self::Terminal => Icon::new(IconName::SquareTerminal),
            Self::Browser => Icon::new(IconName::Globe),
            Self::ChildAgents => Icon::new(IconName::Bot),
        }
    }
}

/// Which side of the button under the pointer a dragged activity would land on.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum RightRailActivityDropPosition {
    Before,
    After,
}

/// The place a dragged activity button would land.
#[derive(Clone, Debug, PartialEq, Eq)]
struct RightRailActivityDropTarget {
    activity: RightRailActivity,
    position: RightRailActivityDropPosition,
}

/// An activity button being dragged along the bar.
#[derive(Clone)]
struct RightRailActivityDrag {
    activity: RightRailActivity,
}

impl Render for RightRailActivityDrag {
    fn render(&mut self, _window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        div()
            .size(px(RIGHT_ACTIVITY_BUTTON_SIZE))
            .flex()
            .flex_none()
            .items_center()
            .justify_center()
            .rounded(px(6.0))
            .border_1()
            .border_color(cx.theme().drag_border)
            .bg(cx.theme().background)
            .text_color(cx.theme().foreground)
            .shadow_lg()
            .opacity(0.94)
            .child(
                self.activity
                    .icon()
                    .size(px(RIGHT_ACTIVITY_BUTTON_SIZE * 0.75)),
            )
    }
}

/// The insertion line a dragged activity draws against the button it would land
/// beside.
fn right_rail_activity_drop_line(position: RightRailActivityDropPosition, cx: &App) -> AnyElement {
    div()
        .absolute()
        .left(px(4.0))
        .right(px(4.0))
        .h(px(2.0))
        .rounded_full()
        .bg(cx.theme().primary)
        .when(position == RightRailActivityDropPosition::Before, |this| {
            this.top(px(-2.0))
        })
        .when(position == RightRailActivityDropPosition::After, |this| {
            this.bottom(px(-2.0))
        })
        .into_any_element()
}

/// The activity bar buttons in the reader's order.
///
/// The persisted order leads; a button it does not name — a fresh install, or
/// one that predates the button — keeps its built-in place after the named
/// ones.
fn resolved_right_rail_activity_order(persisted: &[String]) -> Vec<RightRailActivity> {
    let mut order = Vec::with_capacity(RightRailActivity::ALL.len());
    for id in persisted {
        if let Some(activity) = RightRailActivity::ALL
            .into_iter()
            .find(|activity| activity.id() == id)
            && !order.contains(&activity)
        {
            order.push(activity);
        }
    }
    for activity in RightRailActivity::ALL {
        if !order.contains(&activity) {
            order.push(activity);
        }
    }
    order
}

/// Moves `dragged` beside `target`, returning the bar's new order.
fn reordered_right_rail_activities(
    order: &[RightRailActivity],
    dragged: RightRailActivity,
    target: RightRailActivity,
    position: RightRailActivityDropPosition,
) -> Vec<RightRailActivity> {
    let mut order = order.to_vec();
    if dragged == target {
        return order;
    }
    let Some(from) = order.iter().position(|activity| *activity == dragged) else {
        return order;
    };
    order.remove(from);
    let mut to = order
        .iter()
        .position(|activity| *activity == target)
        .unwrap_or(order.len());
    if position == RightRailActivityDropPosition::After {
        to += 1;
    }
    order.insert(to, dragged);
    order
}

fn git_activity_badge(count: u32, cx: &Context<VibexWorkbench>) -> AnyElement {
    div()
        .absolute()
        .top(px(-4.0))
        .right(px(-4.0))
        .min_w(px(16.0))
        .h(px(16.0))
        .px_1()
        .flex()
        .items_center()
        .justify_center()
        .rounded_full()
        .bg(cx.theme().success.opacity(0.10))
        .text_color(cx.theme().success)
        .font_family("monospace")
        .text_xs()
        .font_semibold()
        .child(count.to_string())
        .into_any_element()
}

fn toggled_sidebar_display(
    docked: bool,
    requested_open: bool,
    drawer_open: bool,
) -> SidebarDisplayState {
    if drawer_open {
        SidebarDisplayState {
            requested_open,
            drawer_open: false,
        }
    } else if docked {
        SidebarDisplayState {
            requested_open: !requested_open,
            drawer_open: false,
        }
    } else {
        SidebarDisplayState {
            requested_open: true,
            drawer_open: true,
        }
    }
}

fn sidebar_display_after_navigation(
    requested_open: bool,
    hover_preview_open: bool,
) -> SidebarDisplayState {
    SidebarDisplayState {
        requested_open: requested_open && !hover_preview_open,
        drawer_open: false,
    }
}

fn sidebar_floating_width(viewport_width: u32) -> f32 {
    (viewport_width as f32 * SIDEBAR_FLOATING_VIEWPORT_RATIO).min(SIDEBAR_FLOATING_MAX_WIDTH)
}

fn session_content_max_width(mode: SessionContentWidthMode) -> Option<f32> {
    match mode {
        SessionContentWidthMode::Narrow => Some(AGENT_CONTENT_NARROW_MAX_WIDTH),
        SessionContentWidthMode::Standard => Some(AGENT_CONTENT_STANDARD_MAX_WIDTH),
        SessionContentWidthMode::Full => None,
    }
}

/// The definite width a user message body may wrap at, in pixels.
///
/// The pill hugs its content, so taffy resolves its height from an intrinsic
/// pass that can wrap the body at a different width than the content box the
/// text finally paints in. When the intrinsic pass wraps wider, the pill ends
/// up a wrapped line short and the library's content surface clips that line.
/// Capping the body at the width the pill settles on keeps the measured height
/// and the painted wrap at one width, which is what the cap guarantees: the
/// body's width is `min(max-content, cap)` in every pass.
///
/// `None` means the width is unknown — the timeline has not reported its first
/// layout yet, or the child-agent panel owns its own width — and the body stays
/// unconstrained, exactly as it was before the cap existed.
fn user_message_body_max_width(timeline_width: f32, content_max_width: Option<f32>) -> Option<f32> {
    if !timeline_width.is_finite() || timeline_width <= 0.0 {
        return None;
    }
    let row_width = (timeline_width - AGENT_TIMELINE_LIST_PADDING_X_PX * 2.0)
        .min(content_max_width.unwrap_or(f32::INFINITY));
    // One pixel of slack keeps the cap inside the content box once taffy
    // rounds the fractional percentage widths on the way down.
    let body_width =
        row_width * USER_MESSAGE_COLUMN_WIDTH_RATIO - USER_MESSAGE_PILL_HORIZONTAL_INSET_PX - 1.0;
    (body_width >= USER_MESSAGE_BODY_MIN_MAX_WIDTH_PX).then_some(body_width)
}

fn sidebar_panel_max_width(viewport_width: u32) -> f32 {
    (viewport_width as f32 * SIDEBAR_PANEL_VIEWPORT_RATIO)
        .clamp(SIDEBAR_PANEL_MIN_WIDTH, SIDEBAR_PANEL_MAX_WIDTH)
}

fn clamp_sidebar_panel_width(width: f32, viewport_width: u32) -> f32 {
    width.round().clamp(
        SIDEBAR_PANEL_MIN_WIDTH,
        sidebar_panel_max_width(viewport_width),
    )
}

fn right_rail_panel_max_width(viewport_width: u32) -> f32 {
    (viewport_width as f32 * RIGHT_RAIL_PANEL_VIEWPORT_RATIO)
        .clamp(RIGHT_RAIL_PANEL_MIN_WIDTH, RIGHT_RAIL_PANEL_MAX_WIDTH)
}

fn docked_right_rail_content_width(total_width: f32) -> f32 {
    (total_width - RIGHT_ACTIVITY_BAR_WIDTH).max(0.0)
}

#[derive(Debug, Clone, Copy, PartialEq)]
struct SidebarAnimationState {
    from_value: f32,
    target_value: f32,
    from_opacity: f32,
    target_opacity: f32,
    render_child: bool,
    hide_scheduled: bool,
    hide_request: u64,
}

impl SidebarAnimationState {
    fn new(visible_value: f32, hidden_value: f32, visible: bool) -> Self {
        let target_value = if visible { visible_value } else { hidden_value };
        let target_opacity = if visible { 1.0 } else { 0.0 };
        Self {
            from_value: target_value,
            target_value,
            from_opacity: target_opacity,
            target_opacity,
            render_child: visible,
            hide_scheduled: false,
            hide_request: 0,
        }
    }

    fn needs_update(
        &self,
        visible_value: f32,
        hidden_value: f32,
        visible: bool,
        animate: bool,
    ) -> bool {
        let target_value = if visible { visible_value } else { hidden_value };
        let child_state_changed = if visible {
            !self.render_child || self.hide_scheduled
        } else if animate {
            self.render_child && !self.hide_scheduled
        } else {
            self.render_child
        };
        self.target_value != target_value || child_state_changed
    }

    fn update_target(
        &mut self,
        visible_value: f32,
        hidden_value: f32,
        visible: bool,
        animate: bool,
    ) -> Option<u64> {
        let target_value = if visible { visible_value } else { hidden_value };
        let target_opacity = if visible { 1.0 } else { 0.0 };

        if !animate {
            self.from_value = target_value;
            self.target_value = target_value;
            self.from_opacity = target_opacity;
            self.target_opacity = target_opacity;
            self.render_child = visible;
            if self.hide_scheduled {
                self.hide_request = self.hide_request.wrapping_add(1);
            }
            self.hide_scheduled = false;
            return None;
        }

        if self.target_value != target_value || self.target_opacity != target_opacity {
            self.from_value = self.target_value;
            self.target_value = target_value;
            self.from_opacity = self.target_opacity;
            self.target_opacity = target_opacity;
        }

        if visible {
            self.render_child = true;
            if self.hide_scheduled {
                self.hide_request = self.hide_request.wrapping_add(1);
            }
            self.hide_scheduled = false;
            None
        } else if self.render_child && !self.hide_scheduled {
            self.hide_scheduled = true;
            self.hide_request = self.hide_request.wrapping_add(1);
            Some(self.hide_request)
        } else {
            None
        }
    }

    fn finish_hide(&mut self, request: u64) -> bool {
        if self.render_child
            && self.hide_scheduled
            && self.hide_request == request
            && self.target_opacity == 0.0
        {
            self.render_child = false;
            self.hide_scheduled = false;
            true
        } else {
            false
        }
    }
}

/// Content fingerprint of the sidebar tree. Compact clients echo it back with
/// a drag so a layout that changed on the Desktop in the meantime rejects the
/// stale move instead of silently reordering something else.
///
/// Only layout-bearing state participates. A move is revalidated against the
/// full tree on the Desktop anyway, so folding pure display state — unread
/// badges, auto-continue markers, per-session activity timestamps that move a
/// row without the user arranging anything — into the revision would reject
/// moves that are still valid, surfacing errors during ordinary streaming.
fn sidebar_organization_revision(view: &SidebarOrganizationView) -> u64 {
    use std::hash::{Hash, Hasher};

    let mut hasher = std::collections::hash_map::DefaultHasher::new();
    view.organization.hash(&mut hasher);
    view.session_order.hash(&mut hasher);
    view.session_order_anchored_at_ms.hash(&mut hasher);
    view.project_order.hash(&mut hasher);
    view.workspace_order.hash(&mut hasher);
    view.hierarchy_mode.hash(&mut hasher);
    hasher.finish()
}

fn sidebar_mutation_error(rejection: SidebarMutationRejection) -> vibex_core::VibexError {
    vibex_core::VibexError::validation(rejection.stable_code(), rejection.message())
}

fn sidebar_animation_id(scope: &'static str, state: SidebarAnimationState) -> ElementId {
    ElementId::Name(
        format!(
            "{scope}-{}-{}-{}-{}",
            state.from_value.to_bits(),
            state.target_value.to_bits(),
            state.from_opacity.to_bits(),
            state.target_opacity.to_bits(),
        )
        .into(),
    )
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SidebarFloatingPresentation {
    HoverPreview,
    Drawer,
}

#[derive(Debug, Clone, Copy, PartialEq)]
struct SidebarFloatingAnimationState {
    animation: SidebarAnimationState,
    presentation: SidebarFloatingPresentation,
}

impl SidebarFloatingAnimationState {
    fn new(width: f32, presentation: Option<SidebarFloatingPresentation>) -> Self {
        Self {
            animation: SidebarAnimationState::new(0.0, -width, presentation.is_some()),
            presentation: presentation.unwrap_or(SidebarFloatingPresentation::HoverPreview),
        }
    }

    fn needs_update(
        &self,
        width: f32,
        presentation: Option<SidebarFloatingPresentation>,
        animate: bool,
    ) -> bool {
        self.animation
            .needs_update(0.0, -width, presentation.is_some(), animate)
            || presentation
                .map(|presentation| presentation != self.presentation)
                .unwrap_or(false)
    }

    fn update_target(
        &mut self,
        width: f32,
        presentation: Option<SidebarFloatingPresentation>,
        animate: bool,
    ) -> Option<u64> {
        if let Some(presentation) = presentation {
            self.presentation = presentation;
        }
        self.animation
            .update_target(0.0, -width, presentation.is_some(), animate)
    }

    fn finish_hide(&mut self, request: u64) -> bool {
        self.animation.finish_hide(request)
    }
}

