    /// The add-runtime dialog. It reuses the pairing claim path the manager
    /// calls, so there is exactly one implementation of pairing.
    /// The pairing form, as the panel's third stage. It is the same surface the
    /// list and a runtime's detail share, so pairing fills in where it was
    /// launched instead of opening a dialog over the manager.
    fn render_runtime_manager_add(&self, cx: &mut Context<Self>) -> AnyElement {
        let busy = self.runtime_add_busy;
        let code_tab = self.runtime_add_tab == RuntimeAddTab::Code;
        let mut fields = v_flex().w_full().gap_2().child(
            // Underline tabs: the two entries are the same form's two ways in,
            // so the bar draws one hairline under the active label instead of
            // boxing each entry into its own control.
            TabBar::new("runtime-add-tabs")
                .small()
                .underline()
                .selected_index(if code_tab { 0 } else { 1 })
                .on_click(cx.listener(|this, index: &usize, _, cx| {
                    this.runtime_add_tab = if *index == 0 {
                        RuntimeAddTab::Code
                    } else {
                        RuntimeAddTab::Link
                    };
                    this.runtime_note = None;
                    cx.notify();
                }))
                .child(Tab::new().label(locale::text("Pairing code", "配对码", "配對碼")))
                .child(Tab::new().label(locale::text("Connection string", "连接串", "連接串"))),
        );
        if code_tab {
            fields = fields
                .child(
                    v_flex()
                        .gap_1()
                        .child(
                            div()
                                .text_xs()
                                .text_color(cx.theme().muted_foreground)
                                .child(locale::text("Server address", "服务器地址", "伺服器位址")),
                        )
                        .child(
                            Input::new(&self.runtime_add_server_url_input)
                                .small()
                                .h(px(28.0)),
                        ),
                )
                .child(
                    v_flex()
                        .gap_1()
                        .child(
                            div()
                                .text_xs()
                                .text_color(cx.theme().muted_foreground)
                                .child(locale::text(
                                    "One-time pairing code",
                                    "一次性配对码",
                                    "一次性配對碼",
                                )),
                        )
                        .child(Input::new(&self.runtime_add_code_input).small().h(px(28.0))),
                )
                .child(runtime_add_hint(
                    locale::text(
                        "Run vibex-server on the host; it prints the pairing code at startup.",
                        "在服务器上运行 vibex-server，它会在启动时打印配对码。",
                        "在伺服器上執行 vibex-server，它會在啟動時列印配對碼。",
                    ),
                    cx,
                ));
        } else {
            fields = fields
                .child(
                    v_flex()
                        .gap_1()
                        .child(
                            div()
                                .text_xs()
                                .text_color(cx.theme().muted_foreground)
                                .child(locale::text("Connection string", "连接串", "連接串")),
                        )
                        .child(Input::new(&self.runtime_add_link_input).small().h(px(28.0))),
                )
                .child(runtime_add_hint(
                    locale::text(
                        "Paste the whole vibex:// link vibex-server printed. It also carries the certificate of a server that uses its own, so no system CA is needed.",
                        "粘贴 vibex-server 打印的完整 vibex:// 连接串。自签证书的服务器也通过它携带证书，无需系统 CA。",
                        "貼上 vibex-server 列印的完整 vibex:// 連接串。自簽憑證的伺服器也透過它攜帶憑證，無需系統 CA。",
                    ),
                    cx,
                ));
        }
        if let Some(note) = self.runtime_note.clone() {
            fields = fields.child(
                div()
                    .text_xs()
                    .text_color(cx.theme().danger)
                    .whitespace_normal()
                    .child(note),
            );
        }

        // Same scroll discipline as the other two stages: plain overflow plus
        // an explicitly tracked handle, because the panel's height is
        // content-sized.
        let fields = v_flex()
            .id("runtime-manager-add-scroll")
            .relative()
            .w_full()
            .min_h_0()
            .track_scroll(&self.runtime_manager_add_scroll)
            .overflow_y_scroll()
            .px_2()
            .child(fields)
            .vertical_scrollbar(&self.runtime_manager_add_scroll);

        v_flex()
            .w_full()
            .min_h_0()
            .child(
                h_flex()
                    .w_full()
                    .flex_none()
                    .gap_1()
                    .px_2()
                    .pt_1()
                    .pb_2()
                    .child(
                        Button::new("runtime-add-back")
                            .small()
                            .ghost()
                            .compact()
                            .size(px(24.0))
                            .px_0()
                            .tooltip(locale::text("Back", "返回", "返回"))
                            .accessibility_label(locale::text("Back", "返回", "返回"))
                            .disabled(busy)
                            .child(Icon::new(IconName::ChevronLeft).size(px(14.0)))
                            .on_click(cx.listener(|this, _, _, cx| this.close_runtime_add(cx))),
                    )
                    .child(
                        div()
                            .min_w_0()
                            .truncate()
                            .text_lg()
                            .font_medium()
                            .child(locale::text(
                                "Add runtime service",
                                "添加运行时服务",
                                "新增執行階段服務",
                            )),
                    ),
            )
            .child(fields)
            .child(
                // No horizontal inset: the submit plate lines up with the
                // list's add button, which is the same plate in the same panel.
                div().w_full().flex_none().pt_3().child(
                    Button::new("runtime-add-submit")
                        .w_full()
                        .label(locale::text("Pair", "配对", "配對"))
                        .disabled(busy)
                        .loading(busy)
                        .on_click(cx.listener(|this, _, _, cx| this.submit_runtime_add(cx))),
                ),
            )
            .into_any_element()
    }

    /// `locale::text` needs a `'static` string, so a title that interpolates
    /// the runtime's name writes each locale out.
    fn runtime_remove_title(&self, label: &str) -> String {
        match self.resolved_locale() {
            locale::ResolvedLocale::ZhCn => format!("移除“{label}”？"),
            locale::ResolvedLocale::ZhTw => format!("移除「{label}」？"),
            locale::ResolvedLocale::En => format!("Remove \u{201c}{label}\u{201d}?"),
        }
    }

    /// The embedded runtime's label: the name it publishes, which defaults to
    /// this machine's device name. The generic phrase is only a last resort for
    /// a runtime that never answered.
    fn local_runtime_label(&self) -> String {
        self.local_runtime_name
            .clone()
            .or_else(|| {
                self.config
                    .as_ref()
                    .map(|config| config.remote_gateway.service.service_name.clone())
            })
            .map(|name| name.trim().to_string())
            .filter(|name| !name.is_empty())
            .unwrap_or_else(|| locale::text("This device", "本机", "本機").to_string())
    }

    /// A row's second line carries identity only. The live state belongs to the
    /// row's status lane and the last connection to the detail stage, so
    /// repeating either here would say the same thing twice in one row.
    fn local_runtime_meta(&self) -> String {
        self.config
            .as_ref()
            .and_then(|config| config.home_dir.file_name())
            .map(|name| name.to_string_lossy().to_string())
            .unwrap_or_default()
    }

    fn remote_runtime_meta(&self, runtime: &RegisteredRuntime) -> String {
        let address = runtime.credential.record.server_url.clone();
        // A failed pairing is the one runtime fact with no other home on the
        // row: the status lane says `Not connected` either way, so the reason
        // has to ride the identity line or be lost until the detail stage.
        if self
            .runtime_connect_errors
            .contains_key(runtime.id.as_str())
        {
            return format!(
                "{address} · {}",
                locale::text("last attempt failed", "上次连接失败", "上次連線失敗")
            );
        }
        address
    }

    /// The active runtime's user-visible state, with a label that never relies
    /// on the dot's color alone.
    fn active_runtime_presentation(&self, _cx: &App) -> (RuntimeStatePresentation, String) {
        if self.runtime_registry.is_local_active() {
            let state = self.runtime_state(RuntimeTarget::Local);
            return (
                state,
                format!(
                    "{} · {}",
                    self.local_runtime_label(),
                    runtime_state_label(state)
                ),
            );
        }
        let id = self.runtime_registry.active_runtime_id().to_string();
        let state = self.runtime_state(RuntimeTarget::Remote(id.as_str()));
        let label = self
            .runtime_registry
            .remote(&id)
            .map(|runtime| runtime.display_label())
            .unwrap_or_default();
        (state, format!("{label} · {}", runtime_state_label(state)))
    }

    fn runtime_state(&self, target: RuntimeTarget<'_>) -> RuntimeStatePresentation {
        match target {
            RuntimeTarget::Local => {
                let running = self.runtime.is_some();
                match (&self.runtime_status, running) {
                    (RuntimeStatus::Starting, _) => RuntimeStatePresentation::Connecting,
                    (RuntimeStatus::Failed { .. }, _) => RuntimeStatePresentation::Failed,
                    (RuntimeStatus::Ready, true) => RuntimeStatePresentation::Ready,
                    (RuntimeStatus::Ready, false) => RuntimeStatePresentation::Stopped,
                }
            }
            RuntimeTarget::Remote(id) => {
                let is_active = self.runtime_registry.active_runtime_id() == id;
                if !is_active {
                    return RuntimeStatePresentation::Stopped;
                }
                if self.runtime_switch_pending.as_deref() == Some(id) {
                    return RuntimeStatePresentation::Connecting;
                }
                match self.remote_client.as_ref() {
                    Some(client) => match client.backend.connection_state().state {
                        RemoteConnectionState::Online => RuntimeStatePresentation::Ready,
                        RemoteConnectionState::Degraded => RuntimeStatePresentation::Degraded,
                        RemoteConnectionState::Reconnecting => {
                            RuntimeStatePresentation::Reconnecting
                        }
                        RemoteConnectionState::Offline => RuntimeStatePresentation::Offline,
                        RemoteConnectionState::Revoked => RuntimeStatePresentation::Revoked,
                        RemoteConnectionState::Incompatible => {
                            RuntimeStatePresentation::Incompatible
                        }
                        RemoteConnectionState::Idle
                        | RemoteConnectionState::Resolving
                        | RemoteConnectionState::Probing
                        | RemoteConnectionState::Connecting
                        | RemoteConnectionState::Authenticating
                        | RemoteConnectionState::Syncing => RuntimeStatePresentation::Connecting,
                    },
                    None => RuntimeStatePresentation::Stopped,
                }
            }
        }
    }

    /// Remote twin of [`Self::attach_event_stream`]: pumps backend events
    /// into the same coalesced signal channel. `Disconnected` maps to a
    /// reconnect note because the transport retries on its own; the pump
    /// exits only when the drain task is dropped with the workbench swap.
    fn attach_remote_event_stream(
        &mut self,
        backend: Arc<WebRemoteBackend>,
        cx: &mut Context<Self>,
    ) {
        let (signal_tx, mut signal_rx) = mpsc::channel(RUNTIME_UI_SIGNAL_QUEUE_CAPACITY);
        let agent_streaming_surface_visible = self.agent_streaming_surface_visible.clone();
        let pump_backend = backend.clone();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            let Ok(mut subscription) = pump_backend.subscribe() else {
                let _ = signal_tx.send(RuntimeUiSignal::RemoteReconnecting).await;
                return;
            };
            loop {
                match subscription.next().await {
                    Ok(Some(BackendEvent::Disconnected)) => {
                        if signal_tx
                            .send(RuntimeUiSignal::RemoteReconnecting)
                            .await
                            .is_err()
                        {
                            return;
                        }
                    }
                    Ok(Some(BackendEvent::Notification(_))) => {
                        // Desktop notifications surface from the authoritative
                        // timeline events; no separate push intent is needed.
                    }
                    Ok(Some(BackendEvent::RuntimeRenamed(renamed))) => {
                        // The authority published a new name for the runtime
                        // this shell is driving, so the runtime list follows it
                        // without a reconnect.
                        if signal_tx
                            .send(RuntimeUiSignal::RuntimeRenamed(renamed.display_name))
                            .await
                            .is_err()
                        {
                            return;
                        }
                    }
                    Ok(Some(BackendEvent::DeviceRenamed(_))) => {
                        // A device rename names the device, not the runtime.
                        // This shell's own device name is not a runtime-list
                        // fact, so there is nothing to re-render here.
                    }
                    Ok(Some(event)) => {
                        let Some(desktop_event) = map_backend_event(event) else {
                            continue;
                        };
                        if !agent_streaming_surface_visible.load(Ordering::Acquire)
                            && matches!(&desktop_event, DesktopEvent::Timeline(event) if timeline_live_event_is_streaming_only(event))
                        {
                            continue;
                        }
                        if signal_tx
                            .send(RuntimeUiSignal::Event(Box::new(desktop_event)))
                            .await
                            .is_err()
                        {
                            return;
                        }
                    }
                    Ok(None) | Err(_) => {
                        if signal_tx
                            .send(RuntimeUiSignal::RemoteReconnecting)
                            .await
                            .is_err()
                        {
                            return;
                        }
                        tokio::time::sleep(REMOTE_EVENT_RETRY_DELAY).await;
                    }
                }
            }
        });
        self.event_task = Some(cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                while let Some(signal) = signal_rx.recv().await {
                    let mut signals = vec![signal];
                    if !matches!(signals.first(), Some(RuntimeUiSignal::Shutdown)) {
                        cx.background_executor()
                            .timer(RUNTIME_UI_SIGNAL_COALESCE_DELAY)
                            .await;
                    }
                    while signals.len() < RUNTIME_UI_SIGNAL_BATCH_LIMIT {
                        match signal_rx.try_recv() {
                            Ok(signal) => signals.push(signal),
                            Err(_) => break,
                        }
                    }
                    let stopped = entity.update(cx, |this, cx| {
                        let dirty = this.apply_runtime_ui_signals(signals, cx);
                        if dirty {
                            cx.notify();
                        }
                        dirty
                    });
                    if stopped.is_err() {
                        break;
                    }
                }
                drop(signal_rx);
                let _ = runner.await;
            },
        ));
    }

    /// Applies a rename the runtime published while this shell was driving it.
    ///
    /// The embedded runtime owns the name directly; a remote runtime is
    /// recorded on its registry entry, which is also what a later reconnect
    /// reads back from the handshake.
    fn apply_runtime_rename(&mut self, display_name: &str, cx: &mut Context<Self>) -> bool {
        if self.remote_client.is_none() {
            let Some(name) = vibex_core::normalize_remote_display_name(display_name) else {
                return false;
            };
            if self.local_runtime_name.as_deref() == Some(name.as_str()) {
                return false;
            }
            self.local_runtime_name = Some(name);
            return true;
        }
        let Some(id) = self
            .remote_client
            .as_ref()
            .map(|client| client.runtime_id.clone())
        else {
            return false;
        };
        let Some(runtime) = self.runtime_registry.remote_mut(&id) else {
            return false;
        };
        // The runtime's own rename replaces a local pet name for the same
        // reason the confirming client clears it: one name, published by the
        // runtime, is what every client shows.
        let cleared = runtime.display_name.take().is_some();
        let named = runtime.observe_server_display_name(display_name);
        if !cleared && !named {
            return false;
        }
        self.persist_runtime_registry(cx);
        true
    }

    fn apply_runtime_ui_signals(
        &mut self,
        signals: Vec<RuntimeUiSignal>,
        cx: &mut Context<Self>,
    ) -> bool {
        let mut dirty = false;
        let mut timeline_events = Vec::new();
        // Attachment updates are published for every ACP message — far more
        // often than the token usage they carry actually changes. They are not
        // a batch barrier: collapsing them per session and applying them at the
        // tail lets the 16 ms timeline coalescing window do its job instead of
        // flushing a one-event batch per chunk. `SessionUpdated`,
        // `RuntimeSelection`, `Lagged`, `Shutdown` keep their barrier
        // semantics because the timeline's relative order matters to them.
        let mut attachment_sessions: Vec<VibexSessionId> = Vec::new();
        for signal in signals {
            match signal {
                RuntimeUiSignal::Event(event) => match *event {
                    DesktopEvent::Timeline(event) => timeline_events.push(event),
                    DesktopEvent::Runtime(event) => {
                        if !attachment_sessions.contains(&event.session_id) {
                            attachment_sessions.push(event.session_id);
                        }
                    }
                    event => {
                        if !timeline_events.is_empty() {
                            dirty |= self.apply_live_timeline_batch(
                                std::mem::take(&mut timeline_events),
                                cx,
                            );
                        }
                        dirty |= self.apply_desktop_event(event, cx);
                    }
                },
                RuntimeUiSignal::Shutdown => {
                    if !timeline_events.is_empty() {
                        self.apply_live_timeline_batch(std::mem::take(&mut timeline_events), cx);
                    }
                    self.runtime_note = Some("Runtime stopped".to_string());
                    dirty = true;
                }
                RuntimeUiSignal::RemoteReconnecting => {
                    if !timeline_events.is_empty() {
                        self.apply_live_timeline_batch(std::mem::take(&mut timeline_events), cx);
                    }
                    self.runtime_note =
                        Some("Remote runtime connection lost; reconnecting…".to_string());
                    dirty = true;
                }
                RuntimeUiSignal::RuntimeRenamed(display_name) => {
                    if !timeline_events.is_empty() {
                        self.apply_live_timeline_batch(std::mem::take(&mut timeline_events), cx);
                    }
                    dirty |= self.apply_runtime_rename(&display_name, cx);
                }
            }
        }
        if !timeline_events.is_empty() {
            dirty |= self.apply_live_timeline_batch(timeline_events, cx);
        }
        for session_id in attachment_sessions {
            dirty |= self.refresh_agent_token_usage(&session_id, cx);
        }
        dirty
    }

    fn load_agent_configured_catalog(&mut self, cx: &mut Context<Self>) {
        let Some(backend) = self.backend.clone() else {
            return;
        };
        self.agent_catalog_generation = self.agent_catalog_generation.wrapping_add(1);
        let generation = self.agent_catalog_generation;
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            let agents = backend
                .management()
                .list_agents(AgentListRequest {
                    include_disabled: false,
                })
                .await?
                .agents;
            let profiles = backend.management().list_profiles().await?;
            Ok::<_, vibex_backend::BackendError>((agents, profiles))
        });
        self.agent_catalog_task = Some(cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                let outcome = runner.await;
                let _ = entity.update(cx, |this, cx| {
                    if this.agent_catalog_generation != generation {
                        return;
                    }
                    match outcome {
                        Ok(Ok((agents, profiles))) => {
                            let preferred_new_session_agent =
                                this.new_session_agent_id.clone().or_else(|| {
                                    this.runtime_selection
                                        .as_ref()
                                        .map(|state| state.desired.agent_id.clone())
                                });
                            this.new_session_agent_id = default_new_session_agent_id(
                                &agents,
                                preferred_new_session_agent.as_ref(),
                            );
                            // Keep the last complete catalog visible while a
                            // profile-only refresh fetches the authoritative
                            // runtime snapshot. Replacing it with an empty
                            // evidence map would hide modes, effort and
                            // feature controls for the duration of the load.
                            if this.runtime_catalog.is_none() {
                                this.runtime_catalog =
                                    Some(Rc::new(build_runtime_option_catalog_for_agents(
                                        &agents,
                                        &profiles,
                                        &BTreeMap::new(),
                                    )));
                            }
                            this.runtime_provider_profiles = profiles;
                            this.agent_snapshots = agents
                                .into_iter()
                                .filter(|agent| vibex_core::is_user_visible_agent(&agent.id))
                                .collect();
                            if this.reconcile_new_session_runtime_selection()
                                && this.new_session_open
                            {
                                this.refresh_active_suggestions(ComposerTarget::NewSession, cx);
                            }
                            this.load_agent_runtime_catalog(cx);
                        }
                        Ok(Err(error)) => {
                            this.runtime_note = Some(format!(
                                "Configured runtime catalog unavailable ({}: {})",
                                error.code, error.message
                            ));
                        }
                        Err(error) => {
                            this.runtime_note =
                                Some(format!("configured runtime catalog task failed: {error}"));
                        }
                    }
                    cx.notify();
                });
            },
        ));
    }

    fn load_agent_overview(&mut self, cx: &mut Context<Self>) {
        let Some(backend) = self.backend.clone() else {
            return;
        };
        self.agent_overview_generation = self.agent_overview_generation.wrapping_add(1);
        let generation = self.agent_overview_generation;
        let reconciles_optimistic_session_deletions =
            self.optimistic_session_deletion_reconciliation_pending;
        let reconciles_optimistic_project_deletions =
            self.optimistic_project_deletion_reconciliation_pending;
        // A provider mutation makes every in-flight enriched catalog stale.
        self.agent_catalog_generation = self.agent_catalog_generation.wrapping_add(1);
        let catalog_generation = self.agent_catalog_generation;
        let shared_agent = self
            .shared_workflow
            .as_ref()
            .map(|workflow| workflow.agent.clone());
        self.agent_error = None;
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            let sessions = if let Some(shared_agent) = shared_agent {
                shared_agent.list_sessions(false).await?
            } else {
                backend.agent().list_sessions(false).await?
            };
            let workspaces: Vec<(ProjectRecord, WorkspaceRecord)> = backend
                .workspace()
                .list_workspaces()
                .await?
                .into_iter()
                .map(|summary| (summary.project, summary.workspace))
                .collect();
            let agents = backend
                .management()
                .list_agents(AgentListRequest {
                    include_disabled: false,
                })
                .await
                .map(|response| response.agents)
                .unwrap_or_default();
            let profiles = backend.management().list_profiles().await?;
            Ok::<_, vibex_backend::BackendError>((sessions, workspaces, agents, profiles))
        });
        self.agent_overview_task = Some(cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                let outcome = runner.await;
                let _ = entity.update(cx, |this, cx| {
                    if this.agent_overview_generation != generation {
                        return;
                    }
                    match outcome {
                        Ok(Ok((sessions, workspaces, agents, profiles))) => {
                            let mut sessions = if reconciles_optimistic_session_deletions {
                                this.optimistic_session_deletion_reconciliation_pending = false;
                                this.optimistically_removed_session_ids.clear();
                                sessions
                            } else {
                                sessions
                                    .into_iter()
                                    .filter(|session| {
                                        !this
                                            .optimistically_removed_session_ids
                                            .contains(session.id.as_str())
                                    })
                                    .collect()
                            };
                            // A project deleted optimistically (and its
                            // sessions) stays hidden while the authoritative
                            // deletion is still in flight. Once the deletion
                            // settles, the reconciliation flag lets the
                            // backend's authoritative rows win again — either
                            // confirming the deletion or restoring the rows
                            // after a failure.
                            if reconciles_optimistic_project_deletions {
                                this.optimistic_project_deletion_reconciliation_pending = false;
                                this.optimistically_removed_project_ids.clear();
                            } else if !this.optimistically_removed_project_ids.is_empty() {
                                sessions.retain(|session| {
                                    !this
                                        .optimistically_removed_project_ids
                                        .contains(session.project_id.as_str())
                                });
                            }
                            let pending_session =
                                this.pending_new_session.as_ref().and_then(|pending| {
                                    this.sessions
                                        .iter()
                                        .find(|session| session.id == pending.session_id)
                                        .cloned()
                                });
                            if let Some(pending_session) = pending_session
                                && !sessions
                                    .iter()
                                    .any(|session| session.id == pending_session.id)
                            {
                                sessions.insert(0, pending_session);
                            }
                            let sessions_empty = sessions.is_empty();
                            let preferred = this
                                .selected_session_id
                                .as_ref()
                                .filter(|selected| {
                                    sessions.iter().any(|session| &session.id == *selected)
                                })
                                .cloned()
                                .or_else(|| sessions.first().map(|session| session.id.clone()));
                            let preferred_new_session_agent =
                                this.new_session_agent_id.clone().or_else(|| {
                                    this.runtime_selection
                                        .as_ref()
                                        .map(|state| state.desired.agent_id.clone())
                                });
                            this.new_session_agent_id = default_new_session_agent_id(
                                &agents,
                                preferred_new_session_agent.as_ref(),
                            );
                            if this.agent_catalog_generation == catalog_generation
                                && this.runtime_catalog.is_none()
                            {
                                this.runtime_catalog =
                                    Some(Rc::new(build_runtime_option_catalog_for_agents(
                                        &agents,
                                        &profiles,
                                        &BTreeMap::new(),
                                    )));
                            }
                            this.runtime_provider_profiles = profiles;
                            this.agent_snapshots = agents
                                .into_iter()
                                .filter(|agent| vibex_core::is_user_visible_agent(&agent.id))
                                .collect();
                            this.sessions = sessions;
                            if this.ui_state.workbench.active_tab == "management" {
                                this.sync_management_agent_ordering(cx);
                            }
                            // Rehydrate both project defaults and explicit
                            // session overrides for every authoritative row.
                            // `restored_auto_continue_session_ids` only knows
                            // about persisted per-session `true` values, so a
                            // project-enabled session must be added here too.
                            this.auto_continue_session_ids = this
                                .sessions
                                .iter()
                                .filter(|session| {
                                    this.ui_state
                                        .session
                                        .auto_continue_session_overrides
                                        .get(session.id.as_str())
                                        .copied()
                                        .unwrap_or_else(|| {
                                            this.project_auto_continue_enabled(&session.project_id)
                                        })
                                })
                                .map(|session| session.id.as_str().to_string())
                                .collect();
                            // A persisted pause only applies while the
                            // auto-continue preference itself is still on.
                            this.auto_continue_paused_session_ids.retain(|session_id| {
                                this.auto_continue_session_ids.contains(session_id)
                            });
                            let workspaces = if reconciles_optimistic_project_deletions
                                || this.optimistically_removed_project_ids.is_empty()
                            {
                                workspaces
                            } else {
                                workspaces
                                    .into_iter()
                                    .filter(|(project, _)| {
                                        !this
                                            .optimistically_removed_project_ids
                                            .contains(project.id.as_str())
                                    })
                                    .collect()
                            };
                            this.workspaces = workspaces;
                            let auto_continue_sessions = this
                                .sessions
                                .iter()
                                .filter(|session| {
                                    this.auto_continue_session_ids.contains(session.id.as_str())
                                })
                                .map(|session| session.id.clone())
                                .collect::<Vec<_>>();
                            for session_id in auto_continue_sessions {
                                this.sync_auto_continue_for_session(&session_id, cx);
                            }
                            if this.ui_state.composer.queue_send_mode
                                == ComposerQueueSendMode::Manual
                            {
                                this.composer_queue_manual_session_ids = this
                                    .sessions
                                    .iter()
                                    .map(|session| session.id.as_str().to_string())
                                    .collect();
                            } else {
                                this.composer_queue_manual_session_ids.clear();
                            }
                            this.reconcile_sidebar_state();
                            this.publish_sidebar_invalidation();
                            this.refresh_workspace_contexts(cx);
                            if this.reconcile_new_session_runtime_selection()
                                && this.new_session_open
                            {
                                this.refresh_active_suggestions(ComposerTarget::NewSession, cx);
                            }
                            if !this.initial_new_session_panel_handled {
                                this.initial_new_session_panel_handled = true;
                                this.new_session_open = resolve_initial_new_session_open(
                                    this.new_session_open,
                                    sessions_empty,
                                    this.ui_state.desktop_behavior.startup_destination,
                                );
                                this.initial_new_session_setup_pending =
                                    this.new_session_open && !this.new_session_draft_initialized;
                            }
                            this.sync_agent_streaming_surface_visibility();
                            if this.new_session_open {
                                // The overview may finish after the user has opened the
                                // New Session home. Reconcile its data, but never let the
                                // background refresh navigate away from that explicit view.
                                if preferred.is_none() {
                                    this.selected_session_id = None;
                                    this.timeline = TimelineModel::default();
                                    this.timeline_row_sizes = Rc::new(Vec::new());
                                    this.invalidate_timeline_render_caches();
                                    this.runtime_selection = None;
                                    this.token_usage = None;
                                }
                                this.agent_loading = false;
                                this.finish_startup_loading(cx);
                            } else if let Some(session_id) = preferred {
                                this.select_session_with_history(session_id, false, cx);
                            } else {
                                this.selected_session_id = None;
                                this.timeline = TimelineModel::default();
                                this.timeline_row_sizes = Rc::new(Vec::new());
                                this.invalidate_timeline_render_caches();
                                this.runtime_selection = None;
                                this.token_usage = None;
                                this.agent_loading = false;
                                this.finish_startup_loading(cx);
                            }
                            if this.agent_catalog_generation == catalog_generation {
                                this.load_agent_runtime_catalog(cx);
                            }
                        }
                        Ok(Err(error)) => {
                            if this.sessions.is_empty() && this.timeline.session_id.is_none() {
                                this.agent_loading = false;
                            }
                            this.agent_error = Some(format!("{}: {}", error.code, error.message));
                            this.finish_startup_loading(cx);
                        }
                        Err(error) => {
                            if this.sessions.is_empty() && this.timeline.session_id.is_none() {
                                this.agent_loading = false;
                            }
                            this.agent_error = Some(format!("agent overview task failed: {error}"));
                            this.finish_startup_loading(cx);
                        }
                    }
                    cx.notify();
                });
            },
        ));
    }

    pub(crate) fn refresh_workspace_contexts(&mut self, cx: &mut Context<Self>) {
        let Some(backend) = self.backend.clone() else {
            return;
        };
        self.workspace_context_generation = self.workspace_context_generation.wrapping_add(1);
        let generation = self.workspace_context_generation;
        let capabilities = backend.capabilities();
        let can_read_worktrees = capabilities.git.supports(BackendOperation::GitWorktreeRead);
        let can_read_status = capabilities.git.supports(BackendOperation::GitStatus);
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            let summaries = backend.workspace().list_workspaces().await?;
            let mut contexts = BTreeMap::new();
            for summary in &summaries {
                let eligibility = if can_read_worktrees {
                    backend
                        .git()
                        .git_worktree_eligibility(summary.workspace.id.clone())
                        .await
                        .ok()
                } else {
                    None
                };
                let lifecycle = if can_read_worktrees {
                    backend
                        .git()
                        .git_worktree_snapshot(summary.workspace.id.clone())
                        .await
                        .ok()
                } else {
                    None
                };
                let status = if can_read_status {
                    backend
                        .git()
                        .git_status(summary.workspace.id.clone())
                        .await
                        .ok()
                } else {
                    None
                };
                let context = WorkspaceContextProjection::from_authoritative(
                    &summary.project,
                    &summary.workspace,
                    eligibility.as_ref(),
                    lifecycle.as_ref(),
                    status.as_ref().and_then(|status| status.branch.as_deref()),
                    status.as_ref().is_some_and(|status| status.dirty),
                    status.is_some(),
                );
                contexts.insert(summary.workspace.id.as_str().to_string(), context);
            }
            Ok::<_, vibex_backend::BackendError>((summaries, contexts))
        });
        self.workspace_context_task = Some(cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                let outcome = runner.await;
                let _ = entity.update(cx, |this, cx| {
                    if this.workspace_context_generation != generation {
                        return;
                    }
                    this.workspace_context_task = None;
                    match outcome {
                        Ok(Ok((summaries, contexts))) => {
                            let workspaces: Vec<(ProjectRecord, WorkspaceRecord)> = summaries
                                .into_iter()
                                .map(|summary| (summary.project, summary.workspace))
                                .collect();
                            // This refresh may have been captured before an
                            // optimistic project deletion, so its snapshot
                            // must not resurrect the removed rows.
                            let workspaces = if this.optimistically_removed_project_ids.is_empty() {
                                workspaces
                            } else {
                                workspaces
                                    .into_iter()
                                    .filter(|(project, _)| {
                                        !this
                                            .optimistically_removed_project_ids
                                            .contains(project.id.as_str())
                                    })
                                    .collect()
                            };
                            let workspaces_changed = this.workspaces != workspaces;
                            this.workspaces = workspaces;
                            this.workspace_contexts = contexts;
                            this.workspace_contexts.retain(|workspace_id, _| {
                                this.workspaces
                                    .iter()
                                    .any(|(_, workspace)| workspace.id.as_str() == workspace_id)
                            });
                            this.reconcile_sidebar_state();
                            if workspaces_changed {
                                this.publish_sidebar_invalidation();
                            }
                        }
                        Ok(Err(error)) => {
                            this.runtime_note = Some(format!(
                                "Workspace context refresh failed: {}: {}",
                                error.code, error.message
                            ));
                        }
                        Err(error) => {
                            this.runtime_note =
                                Some(format!("Workspace context task failed: {error}"));
                        }
                    }
                    cx.notify();
                });
            },
        ));
    }

    fn load_agent_runtime_catalog(&mut self, cx: &mut Context<Self>) {
        let Some(backend) = self.backend.clone() else {
            return;
        };
        self.agent_catalog_generation = self.agent_catalog_generation.wrapping_add(1);
        let generation = self.agent_catalog_generation;
        let shared_agent = self
            .shared_workflow
            .as_ref()
            .map(|workflow| workflow.agent.clone());
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            if let Some(shared_agent) = shared_agent {
                shared_agent.list_runtime_options().await
            } else {
                backend.agent().list_runtime_options().await
            }
        });
        self.agent_catalog_task = Some(cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                let outcome = runner.await;
                let _ = entity.update(cx, |this, cx| {
                    if this.agent_catalog_generation != generation {
                        return;
                    }
                    match outcome {
                        Ok(Ok(catalog)) => {
                            this.runtime_catalog = Some(Rc::new(catalog));
                            if this.reconcile_new_session_runtime_selection()
                                && this.new_session_open
                            {
                                this.refresh_active_suggestions(ComposerTarget::NewSession, cx);
                            }
                        }
                        Ok(Err(error)) => {
                            this.runtime_note = Some(format!(
                                "Runtime catalog unavailable ({}: {})",
                                error.code, error.message
                            ));
                        }
                        Err(error) => {
                            this.runtime_note =
                                Some(format!("Runtime catalog task failed: {error}"));
                        }
                    }
                    cx.notify();
                });
            },
        ));
    }

    fn reconcile_new_session_runtime_selection(&mut self) -> bool {
        let Some(catalog) = self.runtime_catalog.as_ref() else {
            return false;
        };
        let preferred = self
            .new_session_agent_id
            .as_ref()
            .and_then(|agent_id| self.preferred_new_session_runtime_for_agent(agent_id));
        let selection = new_session_runtime_selection_for_agent(
            catalog,
            self.new_session_agent_id.as_ref(),
            preferred.as_ref(),
        );
        self.set_new_session_runtime_selection(selection)
    }

    fn preferred_new_session_runtime_for_agent(
        &self,
        agent_id: &AgentId,
    ) -> Option<SessionRuntimeSelection> {
        if let Some(default) = self
            .ui_state
            .composer
            .default_runtime_selection
            .as_ref()
            .filter(|selection| &selection.agent_id == agent_id)
        {
            return Some(default.clone());
        }
        let selected_runtime = self.selected_runtime_selection();
        new_session_runtime_preference_for_agent(
            agent_id,
            self.new_session_runtime_selection.as_ref(),
            &self.ui_state.composer.runtime_selections_by_agent,
            selected_runtime.as_ref(),
        )
    }

    fn set_new_session_runtime_selection(
        &mut self,
        selection: Option<SessionRuntimeSelection>,
    ) -> bool {
        let changed = self.new_session_runtime_selection != selection;
        self.new_session_runtime_selection = selection;
        changed
    }

    fn remember_runtime_selection(&mut self, selection: &SessionRuntimeSelection) {
        self.runtime_preference_write_fence
            .begin(&selection.agent_id);
        self.ui_state.composer.default_runtime_selection = Some(selection.clone());
        self.persist_runtime_selection(selection);
    }

    fn remember_runtime_selection_if_current(
        &mut self,
        selection: &SessionRuntimeSelection,
        epoch: u64,
    ) {
        if self
            .runtime_preference_write_fence
            .is_current(&selection.agent_id, epoch)
        {
            self.persist_runtime_selection(selection);
        }
    }

    fn persist_runtime_selection(&mut self, selection: &SessionRuntimeSelection) {
        let selection = persisted_runtime_selection(self.runtime_catalog.as_deref(), selection);
        let mut changed = false;
        let selections_by_agent = &mut self.ui_state.composer.runtime_selections_by_agent;
        if selections_by_agent.get(&selection.agent_id) != Some(&selection) {
            selections_by_agent.insert(selection.agent_id.clone(), selection.clone());
            changed = true;
        }
        let selections_by_model = &mut self.ui_state.composer.runtime_selections_by_model;
        if let Some(existing) = selections_by_model
            .iter_mut()
            .find(|existing| runtime_selection_identity_matches(existing, &selection))
        {
            if *existing != selection {
                *existing = selection;
                changed = true;
            }
        } else {
            if selections_by_model.len() >= RUNTIME_SELECTION_PREFERENCE_LIMIT {
                selections_by_model.remove(0);
            }
            selections_by_model.push(selection);
            changed = true;
        }
        if changed {
            self.queue_ui_state();
        }
    }

    fn reconcile_sidebar_state(&mut self) {
        let valid_session_ids = self
            .sessions
            .iter()
            .map(|session| session.id.as_str().to_string())
            .collect::<BTreeSet<_>>();
        let mut seen = BTreeSet::new();
        self.sidebar_state
            .row_order
            .retain(|id| valid_session_ids.contains(id) && seen.insert(id.clone()));
        self.sidebar_state
            .pinned_ids
            .retain(|id| valid_session_ids.contains(id));
        self.sidebar_state
            .selected_ids
            .retain(|id| valid_session_ids.contains(id));
        self.pending_agent_turn_session_ids
            .retain(|id| valid_session_ids.contains(id));
        self.notified_timeline_sequences
            .retain(|id, _| valid_session_ids.contains(id));
        self.composer_queue
            .retain(|message| valid_session_ids.contains(message.session_id.as_str()));
        self.composer_queue_manual_session_ids
            .retain(|id| valid_session_ids.contains(id));
        self.composer_queue_paused_session_ids
            .retain(|id| valid_session_ids.contains(id));
        self.composer_queue_ready_after_continuation_session_ids
            .retain(|id| valid_session_ids.contains(id));
        self.composer_queue_interrupted_session_ids
            .retain(|id| valid_session_ids.contains(id));
        self.composer_queue_steering_session_ids
            .retain(|id| valid_session_ids.contains(id));
        if self.composer_queue_editing_id.is_some_and(|editing_id| {
            !self
                .composer_queue
                .iter()
                .any(|message| message.id == editing_id)
        }) {
            self.composer_queue_editing_id = None;
            self.composer_queue_edit_attachments.clear();
            self.composer_queue_edit_geometry.input_bounds = None;
        }
        self.auto_continue_session_ids
            .retain(|id| valid_session_ids.contains(id));
        self.auto_continue_paused_session_ids
            .retain(|id| valid_session_ids.contains(id));
        self.auto_continue_paused_turn_session_ids
            .retain(|id| valid_session_ids.contains(id));
        self.auto_continue_handled_turns
            .retain(|id, _| valid_session_ids.contains(id));
        self.auto_continue_turn_statuses
            .retain(|id, _| valid_session_ids.contains(id));
        self.auto_continue_probe_tasks
            .retain(|id, _| valid_session_ids.contains(id));
        self.auto_continue_countdowns
            .retain(|id, _| valid_session_ids.contains(id));
        self.auto_continue_countdown_tasks
            .retain(|id, _| valid_session_ids.contains(id));
        self.agent_turn_pending = self
            .selected_session_id
            .as_ref()
            .is_some_and(|id| self.pending_agent_turn_session_ids.contains(id.as_str()));

        let valid_project_ids = self
            .workspaces
            .iter()
            .map(|(project, _)| project.id.as_str().to_string())
            .collect::<BTreeSet<_>>();
        self.auto_continue_default_project_ids
            .retain(|id| valid_project_ids.contains(id));
        let mut seen = BTreeSet::new();
        self.ui_state
            .sidebar
            .project_order
            .retain(|id| valid_project_ids.contains(id) && seen.insert(id.clone()));
        self.sidebar_state
            .collapsed_ids
            .retain(|id| valid_project_ids.contains(id));
        self.ui_state
            .sidebar
            .project_location_preferences
            .retain(|id, _| valid_project_ids.contains(id));
        if let Some(snapshot) = self.collapsed_project_restore.as_mut() {
            snapshot.retain(|id| valid_project_ids.contains(id));
        }
        let valid_workspace_ids = self
            .workspaces
            .iter()
            .map(|(_, workspace)| workspace.id.as_str().to_string())
            .collect::<BTreeSet<_>>();
        self.ui_state
            .sidebar
            .collapsed_workspace_ids
            .retain(|id| valid_workspace_ids.contains(id));
        self.ui_state
            .sidebar
            .workspace_order
            .retain(|project_id, ids| {
                if !valid_project_ids.contains(project_id) {
                    return false;
                }
                ids.retain(|id| valid_workspace_ids.contains(id));
                !ids.is_empty()
            });
        let mut ordered_project_ids = self.ui_state.sidebar.project_order.clone();
        ordered_project_ids.extend(
            self.workspaces
                .iter()
                .map(|(project, _)| project.id.as_str().to_string()),
        );
        complete_string_order(
            &mut ordered_project_ids,
            valid_project_ids.iter().cloned().collect(),
        );
        let ordered_session_projects = self.ordered_sidebar_session_projects();
        self.ui_state
            .sidebar
            .organization
            .reconcile(&ordered_project_ids, &ordered_session_projects);
        let valid_group_ids = self
            .ui_state
            .sidebar
            .organization
            .groups
            .keys()
            .cloned()
            .collect::<BTreeSet<_>>();
        self.sidebar_move_selected_items.retain(|item| match item {
            SidebarOrganizationItem::Project(id) => valid_project_ids.contains(id),
            SidebarOrganizationItem::Session(id) => valid_session_ids.contains(id),
            SidebarOrganizationItem::Group(id) => valid_group_ids.contains(id),
            SidebarOrganizationItem::Folder(_) => false,
        });
        if self
            .sidebar_move_selection_anchor
            .as_ref()
            .is_some_and(|anchor| !self.sidebar_move_selected_items.contains(anchor))
        {
            self.sidebar_move_selection_anchor = None;
        }
        let rename_target_is_stale =
            self.sidebar_rename_target
                .as_ref()
                .is_some_and(|target| match target {
                    SidebarRenameTarget::Session(id) => !valid_session_ids.contains(id.as_str()),
                    SidebarRenameTarget::Folder(id) => {
                        !self.ui_state.sidebar.organization.folders.contains_key(id)
                    }
                    SidebarRenameTarget::Group(id) => {
                        !self.ui_state.sidebar.organization.groups.contains_key(id)
                    }
                });
        if rename_target_is_stale {
            self.sidebar_rename_target = None;
            self.sidebar_rename_error = None;
        }
        let archives_changed = self.apply_sidebar_scheduled_archives(unix_timestamp_ms());
        self.invalidate_sidebar_projection_cache();
        if archives_changed {
            self.publish_sidebar_invalidation();
        }
    }

    fn apply_sidebar_scheduled_archives(&mut self, now_ms: i64) -> bool {
        let changed = self.ui_state.sidebar.organization.apply_scheduled_archives(
            &self.sessions,
            &self.sidebar_state.pinned_ids,
            now_ms,
        );
        if changed {
            self.invalidate_sidebar_projection_cache();
            self.queue_ui_state();
        }
        changed
    }

    /// While a freshly created session is still awaiting its seeded or
    /// Agent-supplied title, snapshots carrying only the manager's default
    /// fallback title must not clobber the optimistic prompt-derived title
    /// the sidebar is already showing. `seed_auto_title` and ACP
    /// `session_info_update` broadcasts carry non-fallback titles and pass
    /// through unchanged; the first such authoritative update releases the
    /// recorded optimistic title so later manual renames and Agent titles
    /// always win. The optimistic row itself is also a non-fallback snapshot,
    /// but it is a fresh insert for a session the backend has never reported
    /// — releasing there would drop the record before the fallback ever
    /// arrives, so only snapshots that update an already-known row release it.
    fn reconcile_pending_new_session_title(&mut self, mut session: AgentSession) -> AgentSession {
        let is_fallback = session.title == agent_session_fallback_title(&session.agent_id);
        let known_row = self
            .sessions
            .iter()
            .any(|existing| existing.id == session.id);
        if !is_fallback {
            // An authoritative update (the seeded prompt title or an
            // Agent-supplied title) releases the record. The optimistic
            // new-session row is the first non-fallback snapshot for its id
            // and arrives as a fresh insert; releasing there would drop the
            // record before the manager's fallback snapshot ever arrives.
            if known_row {
                self.pending_new_session_titles.remove(session.id.as_str());
            }
            return session;
        }
        let Some(optimistic_title) = self
            .pending_new_session_titles
            .get(session.id.as_str())
            .cloned()
        else {
            return session;
        };
        session.title = optimistic_title;
        session
    }

    fn upsert_session_snapshot(&mut self, session: AgentSession) {
        if self
            .optimistically_removed_session_ids
            .contains(session.id.as_str())
            || self
                .optimistically_removed_project_ids
                .contains(session.project_id.as_str())
        {
            return;
        }
        let session = self.reconcile_pending_new_session_title(session);
        let previous_session = self
            .sessions
            .iter()
            .find(|existing| existing.id == session.id);
        let sidebar_changed = session_snapshot_sidebar_changed(previous_session, &session);
        let auto_continue_enabled = self
            .ui_state
            .session
            .auto_continue_session_overrides
            .get(session.id.as_str())
            .copied()
            .unwrap_or_else(|| self.project_auto_continue_enabled(&session.project_id));
        if let Some((existing_state, existing_updated_at_ms)) = self
            .sessions
            .iter()
            .find(|existing| existing.id == session.id)
            .map(|existing| (existing.state, existing.updated_at_ms))
        {
            if existing_state != session.state || existing_updated_at_ms != session.updated_at_ms {
                self.auto_continue_probe_attempts
                    .remove(session.id.as_str());
                self.auto_continue_turn_statuses.remove(session.id.as_str());
                self.auto_continue_probe_tasks.remove(session.id.as_str());
                self.cancel_auto_continue_countdown(&session.id);
                // The completion probe for the superseded revision can no longer
                // answer for this one. Re-arm a waiting auto-send queue so the
                // next frame probes the current revision instead of stranding it
                // on an unobserved turn boundary.
                self.mark_composer_queue_for_recheck(&session.id);
            }
            if let Some(existing) = self
                .sessions
                .iter_mut()
                .find(|existing| existing.id == session.id)
            {
                *existing = session;
            }
        } else {
            if auto_continue_enabled {
                self.auto_continue_session_ids
                    .insert(session.id.as_str().to_string());
            }
            self.sessions.insert(0, session);
        }
        if sidebar_changed {
            self.invalidate_sidebar_projection_cache();
        }
    }

    fn session_turn_pending(&self, session_id: &VibexSessionId) -> bool {
        self.pending_agent_turn_session_ids
            .contains(session_id.as_str())
    }

    fn set_session_turn_pending(&mut self, session_id: &VibexSessionId, pending: bool) {
        let was_pending = self
            .pending_agent_turn_session_ids
            .contains(session_id.as_str());
        if pending {
            self.pending_agent_turn_session_ids
                .insert(session_id.as_str().to_string());
            self.auto_continue_paused_turn_session_ids
                .remove(session_id.as_str());
            self.auto_continue_handled_turns.remove(session_id.as_str());
            self.auto_continue_probe_attempts
                .remove(session_id.as_str());
            self.auto_continue_turn_statuses.remove(session_id.as_str());
            self.auto_continue_probe_tasks.remove(session_id.as_str());
            self.cancel_auto_continue_countdown(session_id);
        } else {
            self.pending_agent_turn_session_ids
                .remove(session_id.as_str());
        }
        if self.selected_session_id.as_ref() == Some(session_id) {
            self.agent_turn_pending = pending;
            if !pending {
                self.agent_generation_stats = None;
            }
        }
        if was_pending != pending {
            self.invalidate_sidebar_projection_cache();
            self.publish_sidebar_invalidation();
        }
    }

    fn release_initial_turn_interrupt_lock(&mut self, interrupted: bool) {
        if interrupted {
            self.agent_action_pending = false;
        }
    }

    fn project_auto_continue_enabled(&self, project_id: &ProjectId) -> bool {
        self.auto_continue_default_project_ids
            .contains(project_id.as_str())
    }

    fn set_project_auto_continue_enabled(
        &mut self,
        project_id: ProjectId,
        enabled: bool,
        cx: &mut Context<Self>,
    ) {
        if enabled {
            self.auto_continue_default_project_ids
                .insert(project_id.as_str().to_string());
            let session_ids = self
                .sessions
                .iter()
                .filter(|session| session.project_id.as_str() == project_id.as_str())
                .map(|session| session.id.clone())
                .collect::<Vec<_>>();
            for session_id in session_ids {
                self.set_auto_continue_enabled(session_id, true, cx);
            }
        } else {
            self.auto_continue_default_project_ids
                .remove(project_id.as_str());
        }
        self.ui_state.session.auto_continue_project_ids =
            self.auto_continue_default_project_ids.clone();
        self.queue_ui_state();
        self.publish_sidebar_invalidation();
        cx.notify();
    }

    fn auto_continue_enabled(&self, session_id: &VibexSessionId) -> bool {
        self.auto_continue_session_ids.contains(session_id.as_str())
    }

    fn auto_continue_remaining_seconds(&self, session_id: &VibexSessionId) -> Option<u8> {
        self.auto_continue_countdowns
            .get(session_id.as_str())
            .map(|countdown| countdown.remaining_seconds)
    }

    fn cancel_auto_continue_countdown(&mut self, session_id: &VibexSessionId) {
        self.auto_continue_countdowns.remove(session_id.as_str());
        self.auto_continue_countdown_tasks
            .remove(session_id.as_str());
    }

    fn cached_auto_continue_turn_status(
        &self,
        session_id: &VibexSessionId,
        session_updated_at_ms: i64,
    ) -> Option<AutoContinueTurnStatus> {
        self.auto_continue_turn_statuses
            .get(session_id.as_str())
            .filter(|status| status.session_updated_at_ms == session_updated_at_ms)
            .copied()
    }

    fn cache_auto_continue_turn_status(
        &mut self,
        session_id: &VibexSessionId,
        session_updated_at_ms: i64,
        ended_normally: Option<bool>,
        cx: &mut Context<Self>,
    ) -> bool {
        let Some(session) = self
            .sessions
            .iter()
            .find(|session| &session.id == session_id)
        else {
            return false;
        };
        if session.updated_at_ms != session_updated_at_ms {
            // The probe answered for a revision that was superseded while it
            // ran. Let a waiting auto-send queue re-evaluate so it can probe the
            // current revision instead of waiting forever.
            self.mark_composer_queue_for_recheck(session_id);
            return false;
        }
        let changed = self
            .auto_continue_turn_statuses
            .insert(
                session_id.as_str().to_string(),
                AutoContinueTurnStatus {
                    session_updated_at_ms,
                    ended_normally,
                },
            )
            .is_none_or(|previous| {
                previous.session_updated_at_ms != session_updated_at_ms
                    || previous.ended_normally != ended_normally
            });
        if self
            .auto_continue_probe_tasks
            .get(session_id.as_str())
            .is_some_and(|probe| probe.session_updated_at_ms == session_updated_at_ms)
        {
            self.auto_continue_probe_tasks.remove(session_id.as_str());
        }
        self.sync_auto_continue_for_session(session_id, cx);
        // A freshly observed turn outcome can release an auto-send queue that
        // was waiting on an unobserved revision. Re-evaluate on the next frame,
        // where the dispatch path can honor the settled answer.
        self.mark_composer_queue_for_recheck(session_id);
        changed
    }

    /// Flags a waiting auto-send queue for a dispatch re-evaluation on the next
    /// frame. The dispatch path re-reads the completion probe, so a settled
    /// normal completion advances the queue while an abnormal stop keeps
    /// waiting. A queue the user paused is left paused: that state is cleared
    /// only by an explicit resume.
    fn mark_composer_queue_for_recheck(&mut self, session_id: &VibexSessionId) {
        if self
            .composer_queue
            .iter()
            .any(|message| message.session_id == *session_id)
        {
            self.composer_queue_ready_after_continuation_session_ids
                .insert(session_id.as_str().to_string());
        }
    }

    fn probe_auto_continue_turn_status(
        &mut self,
        session_id: VibexSessionId,
        session_updated_at_ms: i64,
        cx: &mut Context<Self>,
    ) {
        if self
            .auto_continue_probe_tasks
            .get(session_id.as_str())
            .is_some_and(|probe| probe.session_updated_at_ms == session_updated_at_ms)
        {
            return;
        }
        // One probe per revision per backoff window. A probe whose answer cannot
        // be cached (the session moved on while it ran) would otherwise be
        // re-issued by the next sync, which is how a single idle session kept a
        // repaint loop alive.
        if self
            .auto_continue_probe_attempts
            .get(session_id.as_str())
            .is_some_and(|(revision, attempted_at)| {
                *revision == session_updated_at_ms
                    && attempted_at.elapsed() < AUTO_CONTINUE_PROBE_RETRY_BACKOFF
            })
        {
            return;
        }
        let Some(backend) = self.backend.clone() else {
            return;
        };
        self.auto_continue_probe_attempts.insert(
            session_id.as_str().to_string(),
            (session_updated_at_ms, Instant::now()),
        );
        let probe_session_id = session_id.clone();
        let request_session_id = probe_session_id.clone();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            backend
                .agent()
                .fetch_timeline(FetchTimelineRequest {
                    session_id: request_session_id,
                    after_sequence: None,
                    limit: 500,
                })
                .await
        });
        let probe_key = session_id.as_str().to_string();
        let task_probe_key = probe_key.clone();
        let task = cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                let outcome = runner.await;
                let _ = entity.update(cx, |this, cx| {
                    let probe_is_current = this
                        .auto_continue_probe_tasks
                        .get(&task_probe_key)
                        .is_some_and(|probe| probe.session_updated_at_ms == session_updated_at_ms);
                    if !probe_is_current {
                        // The session moved on while this probe ran, so its
                        // answer cannot settle the current revision. Re-arm a
                        // waiting queue so the next frame probes the revision
                        // that is actually current instead of stranding it.
                        this.mark_composer_queue_for_recheck(&probe_session_id);
                        return;
                    }
                    this.auto_continue_probe_tasks.remove(&task_probe_key);

                    let ended_normally = match outcome {
                        Ok(Ok(page)) if page.session_id == probe_session_id => {
                            Some(latest_timeline_turn_ended_normally(&page.items))
                        }
                        _ => this
                            .timeline
                            .session_id
                            .as_ref()
                            .filter(|timeline_session_id| *timeline_session_id == &probe_session_id)
                            .map(|_| latest_timeline_turn_ended_normally(&this.timeline.items)),
                    };
                    let changed = this.cache_auto_continue_turn_status(
                        &probe_session_id,
                        session_updated_at_ms,
                        ended_normally.flatten(),
                        cx,
                    );
                    if changed {
                        cx.notify();
                    }
                });
            },
        );
        self.auto_continue_probe_tasks.insert(
            probe_key,
            AutoContinueProbeTask {
                session_updated_at_ms,
                _task: task,
            },
        );
    }

    fn set_auto_continue_enabled(
        &mut self,
        session_id: VibexSessionId,
        enabled: bool,
        cx: &mut Context<Self>,
    ) {
        if enabled {
            self.auto_continue_session_ids
                .insert(session_id.as_str().to_string());
            self.auto_continue_paused_turn_session_ids
                .remove(session_id.as_str());
            self.auto_continue_handled_turns.remove(session_id.as_str());
            self.auto_continue_paused_session_ids
                .remove(session_id.as_str());
            self.sync_auto_continue_for_session(&session_id, cx);
        } else {
            self.auto_continue_session_ids.remove(session_id.as_str());
            self.auto_continue_paused_turn_session_ids
                .remove(session_id.as_str());
            self.auto_continue_handled_turns.remove(session_id.as_str());
            self.auto_continue_paused_session_ids
                .remove(session_id.as_str());
            self.cancel_auto_continue_countdown(&session_id);
        }
        self.ui_state
            .session
            .auto_continue_session_overrides
            .insert(session_id.as_str().to_string(), enabled);
        self.ui_state
            .session
            .auto_continue_paused_session_ids
            .clone_from(&self.auto_continue_paused_session_ids);
        self.queue_ui_state();
        self.publish_sidebar_invalidation();
        cx.notify();
    }

    fn sync_auto_continue_for_session(
        &mut self,
        session_id: &VibexSessionId,
        cx: &mut Context<Self>,
    ) {
        let Some((session_state, session_updated_at_ms)) = self
            .sessions
            .iter()
            .find(|session| &session.id == session_id)
            .map(|session| (session.state, session.updated_at_ms))
        else {
            self.cancel_auto_continue_countdown(session_id);
            return;
        };
        let cached_status =
            self.cached_auto_continue_turn_status(session_id, session_updated_at_ms);
        if self.auto_continue_enabled(session_id)
            && matches!(
                session_state,
                AgentSessionState::Idle | AgentSessionState::Error
            )
            && cached_status.is_none()
        {
            self.cancel_auto_continue_countdown(session_id);
            self.probe_auto_continue_turn_status(session_id.clone(), session_updated_at_ms, cx);
            return;
        }
        if !matches!(
            session_state,
            AgentSessionState::Idle | AgentSessionState::Error
        ) {
            self.auto_continue_paused_turn_session_ids
                .remove(session_id.as_str());
            self.auto_continue_handled_turns.remove(session_id.as_str());
        }
        let should_start = auto_continue_should_start(
            self.auto_continue_enabled(session_id),
            session_state,
            cached_status.and_then(|status| status.ended_normally),
            self.session_turn_pending(session_id),
            self.auto_continue_paused_turn_session_ids
                .contains(session_id.as_str()),
            self.auto_continue_handled_turns
                .get(session_id.as_str())
                .copied(),
            session_updated_at_ms,
            self.auto_continue_paused_session_ids
                .contains(session_id.as_str()),
        );
        if !should_start {
            self.cancel_auto_continue_countdown(session_id);
            return;
        }
        if self
            .auto_continue_countdowns
            .get(session_id.as_str())
            .is_some_and(|countdown| countdown.session_updated_at_ms == session_updated_at_ms)
        {
            return;
        }
        self.start_auto_continue_countdown(session_id.clone(), session_updated_at_ms, cx);
    }

    fn start_auto_continue_countdown(
        &mut self,
        session_id: VibexSessionId,
        session_updated_at_ms: i64,
        cx: &mut Context<Self>,
    ) {
        self.cancel_auto_continue_countdown(&session_id);
        let session_key = session_id.as_str().to_string();
        self.auto_continue_countdowns.insert(
            session_key.clone(),
            AutoContinueCountdown {
                session_id: session_id.clone(),
                session_updated_at_ms,
                remaining_seconds: AUTO_CONTINUE_COUNTDOWN_SECONDS,
            },
        );
        let timer_session_id = session_id.clone();
        let task = cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                loop {
                    cx.background_executor()
                        .timer(AUTO_CONTINUE_TICK_INTERVAL)
                        .await;
                    let keep_ticking = entity
                        .update(cx, |this, cx| {
                            this.tick_auto_continue_countdown(&timer_session_id, cx)
                        })
                        .unwrap_or(false);
                    if !keep_ticking {
                        break;
                    }
                }
            },
        );
        self.auto_continue_countdown_tasks.insert(session_key, task);
    }

    fn tick_auto_continue_countdown(
        &mut self,
        session_id: &VibexSessionId,
        cx: &mut Context<Self>,
    ) -> bool {
        let Some(countdown) = self
            .auto_continue_countdowns
            .get(session_id.as_str())
            .cloned()
        else {
            self.auto_continue_countdown_tasks
                .remove(session_id.as_str());
            return false;
        };
        let current_session = self
            .sessions
            .iter()
            .find(|session| session.id == countdown.session_id);
        let countdown_is_current = current_session.is_some_and(|session| {
            let cached_status =
                self.cached_auto_continue_turn_status(session_id, session.updated_at_ms);
            auto_continue_should_start(
                self.auto_continue_enabled(session_id),
                session.state,
                cached_status.and_then(|status| status.ended_normally),
                self.session_turn_pending(session_id),
                self.auto_continue_paused_turn_session_ids
                    .contains(session_id.as_str()),
                self.auto_continue_handled_turns
                    .get(session_id.as_str())
                    .copied(),
                session.updated_at_ms,
                self.auto_continue_paused_session_ids
                    .contains(session_id.as_str()),
            ) && cached_status.is_some()
                && session.updated_at_ms == countdown.session_updated_at_ms
        });
        if !countdown_is_current {
            self.cancel_auto_continue_countdown(session_id);
            cx.notify();
            return false;
        }
        if countdown.remaining_seconds > 1 {
            if let Some(countdown) = self.auto_continue_countdowns.get_mut(session_id.as_str()) {
                countdown.remaining_seconds -= 1;
            }
            cx.notify();
            return true;
        }
        if self.agent_action_pending {
            return true;
        }

        self.auto_continue_countdowns.remove(session_id.as_str());
        self.auto_continue_countdown_tasks
            .remove(session_id.as_str());
        self.auto_continue_handled_turns.insert(
            session_id.as_str().to_string(),
            countdown.session_updated_at_ms,
        );
        self.continue_session_by_id(
            session_id.clone(),
            Some(countdown.session_updated_at_ms),
            cx,
        );
        false
    }

    fn pause_auto_continue(&mut self, session_id: &VibexSessionId, cx: &mut Context<Self>) {
        // A manual pause suspends this session's auto-continue without
        // discarding its persisted preference: the pause survives restarts and
        // clears only when the user resumes it or sends a new message.
        if self.auto_continue_enabled(session_id)
            && self
                .auto_continue_paused_session_ids
                .insert(session_id.as_str().to_string())
        {
            self.ui_state
                .session
                .auto_continue_paused_session_ids
                .clone_from(&self.auto_continue_paused_session_ids);
            self.queue_ui_state();
            self.invalidate_sidebar_projection_cache();
            self.publish_sidebar_invalidation();
        }
        if let Some(countdown) = self.auto_continue_countdowns.remove(session_id.as_str()) {
            self.auto_continue_paused_turn_session_ids
                .insert(session_id.as_str().to_string());
            self.auto_continue_handled_turns.insert(
                session_id.as_str().to_string(),
                countdown.session_updated_at_ms,
            );
        }
        self.auto_continue_countdown_tasks
            .remove(session_id.as_str());
        cx.notify();
    }

    /// Lifts the persisted auto-continue suspension the user installed by
    /// pausing the countdown or stopping the session.
    fn resume_auto_continue(&mut self, session_id: &VibexSessionId, cx: &mut Context<Self>) {
        if !self
            .auto_continue_paused_session_ids
            .remove(session_id.as_str())
        {
            return;
        }
        self.ui_state
            .session
            .auto_continue_paused_session_ids
            .clone_from(&self.auto_continue_paused_session_ids);
        self.auto_continue_handled_turns.remove(session_id.as_str());
        self.queue_ui_state();
        self.invalidate_sidebar_projection_cache();
        self.publish_sidebar_invalidation();
        self.sync_auto_continue_for_session(session_id, cx);
        cx.notify();
    }

    fn activate_continue_button(&mut self, cx: &mut Context<Self>) {
        let Some(session_id) = self.selected_session_id.clone() else {
            return;
        };
        if self
            .auto_continue_countdowns
            .contains_key(session_id.as_str())
        {
            self.pause_auto_continue(&session_id, cx);
        } else {
            self.continue_session(cx);
        }
    }

    fn invalidate_sidebar_projection_cache(&mut self) {
        self.sidebar_projection_revision = self.sidebar_projection_revision.wrapping_add(1);
        self.sidebar_projection_cache = None;
    }

    /// Parks the sidebar arrangement of the runtime authority the workbench is
    /// leaving and restores the arrangement remembered for `authority`.
    ///
    /// Sidebar order and folder ids only mean something inside the runtime that
    /// produced them.  Without this switch, connecting to a paired server would
    /// reconcile — and then persist — the embedded runtime's arrangement
    /// against the server's project list, deleting the user's project order and
    /// folders.
    fn activate_sidebar_authority(&mut self, authority: &str, cx: &mut Context<Self>) {
        if self.ui_state.sidebar.active_authority() == authority {
            return;
        }
        // Flush the live selection state into the arrangement being parked.
        self.queue_agent_ui_state();
        self.ui_state.sidebar.switch_authority(authority);
        self.sidebar_state.row_order = self.ui_state.sidebar.session_order.clone();
        self.sidebar_state.pinned_ids = self.ui_state.sidebar.pinned_session_ids.clone();
        self.sidebar_state.collapsed_ids = self.ui_state.sidebar.collapsed_project_ids.clone();
        self.sidebar_state.clear_selection();
        self.sidebar_move_selected_items.clear();
        self.sidebar_move_selection_anchor = None;
        self.invalidate_sidebar_projection_cache();
        self.queue_agent_ui_state();
        cx.notify();
    }

    fn sidebar_workspace_groups(&mut self, query: &str) -> Rc<Vec<SidebarProjectProjection>> {
        let normalized_query = query.trim().to_lowercase();
        if self.ui_state.sidebar.hierarchy_mode == SidebarHierarchyMode::Detailed
            && self.reconcile_legacy_sidebar_folder_worktree_owners()
        {
            self.invalidate_sidebar_projection_cache();
            self.queue_ui_state();
        }
        if normalized_query.is_empty()
            && let Some(cache) = self.sidebar_projection_cache.as_ref()
            && cache.revision == self.sidebar_projection_revision
        {
            return cache.groups.clone();
        }

        let groups = Rc::new(sidebar_project_projections_with_workspace_order(
            &self.workspaces,
            &self.sessions,
            &self.workspace_contexts,
            &self.ui_state.sidebar.project_order,
            &self.sidebar_state.row_order,
            self.ui_state.sidebar.session_order_anchored_at_ms,
            &self.ui_state.sidebar.workspace_order,
            &self.sidebar_state.pinned_ids,
            &normalized_query,
        ));
        if normalized_query.is_empty() {
            self.sidebar_projection_cache = Some(SidebarProjectionCache {
                revision: self.sidebar_projection_revision,
                groups: groups.clone(),
            });
        }
        groups
    }

    /// Older sidebar folders only carried a project id. When their complete
    /// contents belong to one worktree, attach them to that worktree so the
    /// detailed hierarchy does not strand the folder beside the worktree cards.
    /// Mixed-worktree folders remain project-scoped and are intentionally left
    /// unchanged.
    fn reconcile_legacy_sidebar_folder_worktree_owners(&mut self) -> bool {
        let inputs = (
            self.sidebar_projection_revision,
            self.sessions.len(),
            self.workspaces.len(),
            self.ui_state.sidebar.organization.folders.len(),
        );
        if self.legacy_folder_reconcile_inputs == Some(inputs) {
            return false;
        }
        self.legacy_folder_reconcile_inputs = Some(inputs);
        // This migration only ever acts on legacy folders, and a sidebar that
        // has none is the common case. Leave before building the indexes below.
        let legacy_folder_ids = self
            .ui_state
            .sidebar
            .organization
            .folders
            .iter()
            .filter_map(|(folder_id, folder)| {
                (folder.project_id.is_some() && folder.workspace_id.is_none())
                    .then_some(folder_id.clone())
            })
            .collect::<Vec<_>>();
        if legacy_folder_ids.is_empty() {
            return false;
        }

        let mut children = BTreeMap::<Option<String>, Vec<SidebarOrganizationItem>>::new();
        for placement in &self.ui_state.sidebar.organization.placements {
            children
                .entry(placement.parent_folder_id.clone())
                .or_default()
                .push(placement.item.clone());
        }

        // Index the workspaces once. Resolving a session's workspace by
        // rescanning the workspace list per session made this migration
        // quadratic in the number of sessions the sidebar holds.
        let mut workspaces_by_id = HashMap::<(String, String), String>::new();
        let mut workspaces_by_root =
            HashMap::<(String, String), Vec<(WorkspaceMode, String)>>::new();
        for (project, workspace) in &self.workspaces {
            let project_id = project.id.as_str().to_string();
            let workspace_id = workspace.id.as_str().to_string();
            workspaces_by_id.insert(
                (project_id.clone(), workspace_id.clone()),
                workspace_id.clone(),
            );
            workspaces_by_root
                .entry((project_id, workspace.root_path.clone()))
                .or_default()
                .push((workspace.mode, workspace_id));
        }

        let mut session_workspaces = BTreeMap::<String, String>::new();
        let session_projects = self
            .sessions
            .iter()
            .map(|session| {
                (
                    session.id.as_str().to_string(),
                    session.project_id.as_str().to_string(),
                )
            })
            .collect::<BTreeMap<_, _>>();
        for session in &self.sessions {
            let project_id = session.project_id.as_str();
            let workspace_id = workspaces_by_id
                .get(&(
                    project_id.to_string(),
                    session.workspace_id.as_str().to_string(),
                ))
                .cloned()
                .or_else(|| {
                    workspaces_by_root
                        .get(&(project_id.to_string(), session.workspace_root.clone()))
                        .and_then(|candidates| {
                            candidates
                                .iter()
                                .find(|(mode, _)| *mode == session.workspace_mode)
                                .map(|(_, workspace_id)| workspace_id.clone())
                        })
                });
            if let Some(workspace_id) = workspace_id {
                session_workspaces.insert(session.id.as_str().to_string(), workspace_id);
            }
        }

        fn collect_folder_sessions(
            folder_id: &str,
            children: &BTreeMap<Option<String>, Vec<SidebarOrganizationItem>>,
            visited_folders: &mut BTreeSet<String>,
            sessions: &mut BTreeSet<String>,
        ) {
            if !visited_folders.insert(folder_id.to_string()) {
                return;
            }
            let parent = Some(folder_id.to_string());
            for item in children.get(&parent).into_iter().flatten() {
                match item {
                    SidebarOrganizationItem::Session(session_id) => {
                        sessions.insert(session_id.clone());
                    }
                    SidebarOrganizationItem::Folder(child_id) => {
                        collect_folder_sessions(child_id, children, visited_folders, sessions);
                    }
                    // A group carries its own worktree owner, so it does not
                    // contribute to the folder's inferred owner.
                    SidebarOrganizationItem::Project(_) | SidebarOrganizationItem::Group(_) => {}
                }
            }
        }

        let mut inferred = BTreeMap::<String, String>::new();
        for folder_id in legacy_folder_ids {
            if !self
                .ui_state
                .sidebar
                .organization
                .folders
                .contains_key(&folder_id)
            {
                continue;
            }
            let folder_project_id = self
                .ui_state
                .sidebar
                .organization
                .folder(&folder_id)
                .and_then(|folder| folder.project_id.as_deref());
            let mut sessions = BTreeSet::new();
            collect_folder_sessions(&folder_id, &children, &mut BTreeSet::new(), &mut sessions);
            let known_session_count = sessions
                .iter()
                .filter(|session_id| session_workspaces.contains_key(*session_id))
                .count();
            let workspace_ids = sessions
                .iter()
                .filter_map(|session_id| session_workspaces.get(session_id))
                .cloned()
                .collect::<BTreeSet<_>>();
            if !sessions.is_empty()
                && known_session_count == sessions.len()
                && workspace_ids.len() == 1
                && sessions.iter().all(|session_id| {
                    session_projects.get(session_id).map(String::as_str) == folder_project_id
                })
            {
                inferred.insert(folder_id, workspace_ids.into_iter().next().unwrap());
            }
        }

        let mut changed = false;
        for (folder_id, workspace_id) in inferred {
            if let Some(folder) = self
                .ui_state
                .sidebar
                .organization
                .folders
                .get_mut(&folder_id)
                && folder.workspace_id.is_none()
            {
                folder.workspace_id = Some(workspace_id);
                changed = true;
            }
        }
        changed
    }

    fn ordered_sidebar_session_projects(&self) -> Vec<(String, String)> {
        let projected = sidebar_project_projections_with_workspace_order(
            &self.workspaces,
            &self.sessions,
            &self.workspace_contexts,
            &self.ui_state.sidebar.project_order,
            &self.sidebar_state.row_order,
            self.ui_state.sidebar.session_order_anchored_at_ms,
            &self.ui_state.sidebar.workspace_order,
            &self.sidebar_state.pinned_ids,
            "",
        );
        let mut projected_scopes = BTreeMap::new();
        let mut seen = BTreeSet::new();
        let mut ordered = Vec::new();
        for group in projected {
            let project_id = group.project.id.as_str().to_string();
            for session in group.compact_sessions {
                let session_id = session.id.as_str().to_string();
                projected_scopes
                    .entry(session_id.clone())
                    .or_insert_with(|| project_id.clone());
                if seen.insert(session_id.clone()) {
                    ordered.push((session_id, project_id.clone()));
                }
            }
        }
        ordered.extend(self.sessions.iter().filter_map(|session| {
            let session_id = session.id.as_str().to_string();
            seen.insert(session_id.clone()).then(|| {
                let project_id = projected_scopes
                    .get(&session_id)
                    .cloned()
                    .unwrap_or_else(|| session.project_id.as_str().to_string());
                (session_id, project_id)
            })
        }));
        ordered
    }

    /// Session -> owning Worktree, for validating group membership.
    fn sidebar_session_workspaces(&self) -> BTreeMap<String, String> {
        self.sessions
            .iter()
            .map(|session| {
                (
                    session.id.as_str().to_string(),
                    session.workspace_id.as_str().to_string(),
                )
            })
            .collect()
    }

    /// Group ids of one project, in sidebar order.
    fn sidebar_group_ids_for_project(&self, project_id: &str) -> Vec<String> {
        self.ui_state
            .sidebar
            .organization
            .groups_for_project(project_id)
            .into_iter()
            .map(|(id, _)| id)
            .collect()
    }

    /// Group ids anchored to one Worktree, in sidebar order.
    fn sidebar_group_ids_for_workspace(&self, project_id: &str, workspace_id: &str) -> Vec<String> {
        self.ui_state
            .sidebar
            .organization
            .groups_for_workspace(project_id, workspace_id)
            .into_iter()
            .map(|(id, _)| id)
            .collect()
    }

    /// The selected sessions as one group, when they can form one.
    ///
    /// A group is single-Worktree, so a selection spanning Worktrees cannot
    /// become one group; the action stays disabled instead of splitting it.
    fn sidebar_group_creation_candidates(&self) -> Option<(String, String, Vec<String>)> {
        self.sidebar_group_creation_candidates_for(&self.sidebar_state.selected_ids)
    }

    /// The shift/ctrl selection as one group, when it can form one.
    ///
    /// The multi-select a plain click builds is the same selection the drag
    /// gesture carries, so a right click on it can offer the group directly
    /// instead of sending the user through batch mode first.
    fn sidebar_move_group_creation_candidates(&self) -> Option<(String, String, Vec<String>)> {
        let selected = self
            .sidebar_move_selected_items
            .iter()
            .filter_map(|item| match item {
                SidebarOrganizationItem::Session(session_id) => Some(session_id.clone()),
                _ => None,
            })
            .collect::<BTreeSet<_>>();
        self.sidebar_group_creation_candidates_for(&selected)
    }

    fn sidebar_group_creation_candidates_for(
        &self,
        selected_ids: &BTreeSet<String>,
    ) -> Option<(String, String, Vec<String>)> {
        if selected_ids.is_empty() {
            return None;
        }
        let mut scope: Option<(String, String)> = None;
        let mut session_ids = Vec::new();
        for session in &self.sessions {
            let session_id = session.id.as_str();
            if !selected_ids.contains(session_id) {
                continue;
            }
            let candidate = (
                session.project_id.as_str().to_string(),
                session.workspace_id.as_str().to_string(),
            );
            match scope.as_ref() {
                Some(existing) if existing != &candidate => return None,
                Some(_) => {}
                None => scope = Some(candidate),
            }
            session_ids.push(session_id.to_string());
        }
        scope.map(|(project_id, workspace_id)| (project_id, workspace_id, session_ids))
    }

    /// Turns the current selection into a session group.
    fn create_session_group_from_selection(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some((project_id, workspace_id, session_ids)) =
            self.sidebar_group_creation_candidates()
        else {
            return;
        };
        self.create_session_group(&project_id, &workspace_id, &session_ids, window, cx);
    }

    /// Turns the shift/ctrl selection into a session group.
    fn create_session_group_from_move_selection(
        &mut self,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some((project_id, workspace_id, session_ids)) =
            self.sidebar_move_group_creation_candidates()
        else {
            return;
        };
        self.create_session_group(&project_id, &workspace_id, &session_ids, window, cx);
    }

    fn create_session_group(
        &mut self,
        project_id: &str,
        workspace_id: &str,
        session_ids: &[String],
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let name = self
            .ui_state
            .sidebar
            .organization
            .next_available_group_name(project_id, workspace_id, self.strings().sidebar_group_stem);
        let group_id = RequestId::new().to_string();
        let session_workspaces = self.sidebar_session_workspaces();
        if !self.ui_state.sidebar.organization.create_group(
            &group_id,
            name,
            project_id,
            workspace_id,
            session_ids,
            &session_workspaces,
            None,
        ) {
            return;
        }
        // Either selection may have started the group, and both stop meaning
        // anything once their sessions belong to it.
        self.sidebar_batch_mode = false;
        self.sidebar_state.clear_selection();
        self.clear_sidebar_move_selection();
        self.queue_ui_state();
        self.publish_sidebar_invalidation();
        // Naming happens in place: the new group is the only row the user is
        // looking at, so the rename field is the natural next step.
        self.begin_sidebar_group_rename(group_id, window, cx);
        cx.notify();
    }

    fn sidebar_session_projects(&self) -> BTreeMap<String, String> {
        let mut projects = self.sidebar_session_project_scopes();
        for session in &self.sessions {
            projects
                .entry(session.id.as_str().to_string())
                .or_insert_with(|| session.project_id.as_str().to_string());
        }
        projects
    }

    fn sidebar_session_project_scopes(&self) -> BTreeMap<String, String> {
        let mut projects = BTreeMap::new();
        for group in sidebar_project_projections_with_workspace_order(
            &self.workspaces,
            &self.sessions,
            &self.workspace_contexts,
            &self.ui_state.sidebar.project_order,
            &self.sidebar_state.row_order,
            self.ui_state.sidebar.session_order_anchored_at_ms,
            &self.ui_state.sidebar.workspace_order,
            &self.sidebar_state.pinned_ids,
            "",
        ) {
            let project_id = group.project.id.as_str().to_string();
            for session in group.compact_sessions {
                projects
                    .entry(session.id.as_str().to_string())
                    .or_insert_with(|| project_id.clone());
            }
        }
        projects
    }

    fn sidebar_root_organization_items(
        &self,
        groups: &[SidebarProjectProjection],
        parent_folder_id: Option<&str>,
    ) -> Vec<SidebarOrganizationItem> {
        let project_ids = groups
            .iter()
            .map(|group| group.project.id.as_str().to_string())
            .collect::<Vec<_>>();
        sidebar_root_items(
            &self.ui_state.sidebar.organization,
            &project_ids,
            parent_folder_id,
        )
    }

    fn sidebar_project_organization_items(
        &self,
        project_id: &str,
        sessions: &[AgentSession],
        parent_folder_id: Option<&str>,
    ) -> Vec<SidebarOrganizationItem> {
        let session_ids = sessions
            .iter()
            .map(|session| session.id.as_str().to_string())
            .collect::<Vec<_>>();
        sidebar_project_items(
            &self.ui_state.sidebar.organization,
            project_id,
            &session_ids,
            &self.sidebar_state.pinned_ids,
            parent_folder_id,
        )
    }

    fn sidebar_project_legacy_organization_items(
        &self,
        project_id: &str,
        sessions: &[AgentSession],
        parent_folder_id: Option<&str>,
    ) -> Vec<SidebarOrganizationItem> {
        let session_ids = sessions
            .iter()
            .map(|session| session.id.as_str().to_string())
            .collect::<Vec<_>>();
        sidebar_project_items_for_workspace(
            &self.ui_state.sidebar.organization,
            project_id,
            None,
            true,
            false,
            &session_ids,
            &self.sidebar_group_ids_for_project(project_id),
            &self.sidebar_state.pinned_ids,
            parent_folder_id,
        )
    }

    fn sidebar_session_is_organized(&self, session_id: &VibexSessionId) -> bool {
        self.ui_state
            .sidebar
            .organization
            .parent_of(&SidebarOrganizationItem::Session(
                session_id.as_str().to_string(),
            ))
            .is_some()
    }

    /// Whether two sidebar rows may be moved together.
    ///
    /// Only the project has to agree: a move is a placement inside one project,
    /// and the pinned band is an order the sidebar paints rather than a boundary
    /// a move cannot cross. Requiring the same pinned state here made a range
    /// that started on a pinned row and ended below it collapse to the row the
    /// user clicked last, so a multi-selection silently became one row — and
    /// only one session joined or left a group.
    fn sidebar_move_selection_scope_matches(
        &self,
        left: &SidebarOrganizationItem,
        right: &SidebarOrganizationItem,
    ) -> bool {
        match (left, right) {
            (SidebarOrganizationItem::Project(_), SidebarOrganizationItem::Project(_)) => true,
            (
                SidebarOrganizationItem::Session(left_id),
                SidebarOrganizationItem::Session(right_id),
            ) => {
                let project_scopes = self.sidebar_session_project_scopes();
                let left = self
                    .sessions
                    .iter()
                    .find(|session| session.id.as_str() == left_id);
                let right = self
                    .sessions
                    .iter()
                    .find(|session| session.id.as_str() == right_id);
                left.zip(right).is_some_and(|(left, right)| {
                    project_scopes.get(left_id) == project_scopes.get(right_id)
                        && left.project_id == right.project_id
                })
            }
            _ => false,
        }
    }

    fn collect_sidebar_move_selection_items(
        &self,
        available: &[SidebarOrganizationItem],
        parent_folder_id: Option<&str>,
        kind: SidebarMoveSelectionKind,
        output: &mut Vec<SidebarOrganizationItem>,
        depth: usize,
    ) {
        if depth > 32 {
            return;
        }
        let mut children = self
            .ui_state
            .sidebar
            .organization
            .ordered_children(parent_folder_id, available);
        if kind == SidebarMoveSelectionKind::Session {
            let (pinned, unpinned): (Vec<_>, Vec<_>) = children.into_iter().partition(|item| {
                matches!(item, SidebarOrganizationItem::Session(id) if self.sidebar_state.pinned_ids.contains(id))
            });
            children = pinned.into_iter().chain(unpinned).collect();
        }
        for item in children {
            match (&item, kind) {
                (SidebarOrganizationItem::Project(_), SidebarMoveSelectionKind::Project)
                | (SidebarOrganizationItem::Session(_), SidebarMoveSelectionKind::Session) => {
                    output.push(item);
                }
                (SidebarOrganizationItem::Folder(folder_id), _)
                    if !self
                        .ui_state
                        .sidebar
                        .organization
                        .collapsed_folder_ids
                        .contains(folder_id) =>
                {
                    self.collect_sidebar_move_selection_items(
                        available,
                        Some(folder_id),
                        kind,
                        output,
                        depth + 1,
                    );
                }
                _ => {}
            }
        }
    }

    fn sidebar_move_selection_order(
        &self,
        target: &SidebarOrganizationItem,
    ) -> Vec<SidebarOrganizationItem> {
        let (kind, available) = match target {
            SidebarOrganizationItem::Project(_) => {
                let groups = sidebar_project_projections_with_workspace_order(
                    &self.workspaces,
                    &self.sessions,
                    &self.workspace_contexts,
                    &self.ui_state.sidebar.project_order,
                    &self.sidebar_state.row_order,
                    self.ui_state.sidebar.session_order_anchored_at_ms,
                    &self.ui_state.sidebar.workspace_order,
                    &self.sidebar_state.pinned_ids,
                    "",
                );
                let mut available = self
                    .ui_state
                    .sidebar
                    .organization
                    .folders
                    .iter()
                    .filter(|(_, folder)| folder.project_id.is_none())
                    .map(|(id, _)| SidebarOrganizationItem::Folder(id.clone()))
                    .collect::<Vec<_>>();
                available.extend(groups.iter().map(|group| {
                    SidebarOrganizationItem::Project(group.project.id.as_str().to_string())
                }));
                (SidebarMoveSelectionKind::Project, available)
            }
            SidebarOrganizationItem::Session(session_id) => {
                let Some(session) = self
                    .sessions
                    .iter()
                    .find(|session| session.id.as_str() == session_id)
                else {
                    return vec![target.clone()];
                };
                let project_scopes = self.sidebar_session_project_scopes();
                let project_id = project_scopes
                    .get(session_id)
                    .map(String::as_str)
                    .unwrap_or(session.project_id.as_str());
                let groups = sidebar_project_projections_with_workspace_order(
                    &self.workspaces,
                    &self.sessions,
                    &self.workspace_contexts,
                    &self.ui_state.sidebar.project_order,
                    &self.sidebar_state.row_order,
                    self.ui_state.sidebar.session_order_anchored_at_ms,
                    &self.ui_state.sidebar.workspace_order,
                    &self.sidebar_state.pinned_ids,
                    "",
                );
                let Some(group) = groups
                    .iter()
                    .find(|group| group.project.id.as_str() == project_id)
                else {
                    return vec![target.clone()];
                };
                let mut available = self
                    .ui_state
                    .sidebar
                    .organization
                    .folders
                    .iter()
                    .filter(|(_, folder)| folder.project_id.as_deref() == Some(project_id))
                    .map(|(id, _)| SidebarOrganizationItem::Folder(id.clone()))
                    .collect::<Vec<_>>();
                available.extend(group.compact_sessions.iter().map(|session| {
                    SidebarOrganizationItem::Session(session.id.as_str().to_string())
                }));
                (SidebarMoveSelectionKind::Session, available)
            }
            SidebarOrganizationItem::Group(group_id) => {
                let Some(project_id) = self
                    .ui_state
                    .sidebar
                    .organization
                    .group(group_id)
                    .map(|group| group.project_id.clone())
                else {
                    return vec![target.clone()];
                };
                let projections = sidebar_project_projections_with_workspace_order(
                    &self.workspaces,
                    &self.sessions,
                    &self.workspace_contexts,
                    &self.ui_state.sidebar.project_order,
                    &self.sidebar_state.row_order,
                    self.ui_state.sidebar.session_order_anchored_at_ms,
                    &self.ui_state.sidebar.workspace_order,
                    &self.sidebar_state.pinned_ids,
                    "",
                );
                let Some(projection) = projections
                    .iter()
                    .find(|group| group.project.id.as_str() == project_id)
                else {
                    return vec![target.clone()];
                };
                let mut available = self
                    .ui_state
                    .sidebar
                    .organization
                    .folders
                    .iter()
                    .filter(|(_, folder)| folder.project_id.as_deref() == Some(project_id.as_str()))
                    .map(|(id, _)| SidebarOrganizationItem::Folder(id.clone()))
                    .collect::<Vec<_>>();
                available.extend(projection.compact_sessions.iter().map(|session| {
                    SidebarOrganizationItem::Session(session.id.as_str().to_string())
                }));
                available.extend(
                    self.sidebar_group_ids_for_project(&project_id)
                        .into_iter()
                        .map(SidebarOrganizationItem::Group),
                );
                (SidebarMoveSelectionKind::Session, available)
            }
            SidebarOrganizationItem::Folder(_) => return Vec::new(),
        };
        let mut ordered = Vec::new();
        self.collect_sidebar_move_selection_items(&available, None, kind, &mut ordered, 0);
        if ordered.iter().any(|item| item == target) {
            ordered
        } else {
            vec![target.clone()]
        }
    }

    /// Whether a move selection is on screen.
    ///
    /// The current session only joins a move while a selection exists: on its
    /// own it is just the session the workbench is showing, and dragging its row
    /// moves that row alone.
    fn sidebar_move_selection_is_active(&self) -> bool {
        !self.sidebar_move_selected_items.is_empty()
    }

    /// Whether a row is part of the move the user is assembling.
    ///
    /// The current session's row carries a wash the user cannot tell apart from
    /// a move-selected row (`sidebar_selected_session_background` and
    /// `sidebar_move_selected_background` are the same accent at nearly the same
    /// strength), so it counts as selected while a selection is on screen. The
    /// rows the sidebar paints highlighted are exactly the rows a drag carries
    /// and a group drop acts on.
    fn sidebar_row_is_move_selected(&self, item: &SidebarOrganizationItem) -> bool {
        if self.sidebar_move_selected_items.contains(item) {
            return true;
        }
        let SidebarOrganizationItem::Session(session_id) = item else {
            return false;
        };
        self.sidebar_move_selection_is_active()
            && self
                .selected_session_id
                .as_ref()
                .is_some_and(|selected| selected.as_str() == session_id)
    }

    /// The rows a move acts on, in a stable order.
    ///
    /// This is the shift/ctrl selection plus the current session's row while a
    /// selection is on screen — the set the sidebar shows as selected. Reading
    /// the clicked selection alone moved fewer rows than the user could see.
    fn sidebar_move_selection_items(&self) -> Vec<SidebarOrganizationItem> {
        let mut items = self
            .sidebar_move_selected_items
            .iter()
            .cloned()
            .collect::<Vec<_>>();
        if self.sidebar_move_selection_is_active()
            && let Some(selected) = self.selected_session_id.as_ref()
        {
            let item = SidebarOrganizationItem::Session(selected.as_str().to_string());
            if !items.contains(&item) {
                items.push(item);
            }
        }
        items
    }

    /// The items a drag carries: the whole selection, in sidebar order.
    ///
    /// The order comes from the placement tree, which does not list every row the
    /// sidebar paints — a group draws its members from the group, so a member
    /// whose placement sits inside a collapsed folder is on screen without being
    /// in that order. Reading the payload out of the order alone therefore
    /// dropped those rows and shrank a multi-selection to the one row the drag
    /// started on, so only one session joined or left the group. Anything the
    /// order does not know is appended instead.
    fn sidebar_drag_items(
        &self,
        primary: &SidebarOrganizationItem,
    ) -> Vec<SidebarOrganizationItem> {
        if !self.sidebar_row_is_move_selected(primary) {
            return vec![primary.clone()];
        }
        let selected = self.sidebar_move_selection_items();
        let mut items = self
            .sidebar_move_selection_order(primary)
            .into_iter()
            .filter(|item| {
                selected.contains(item) && self.sidebar_move_selection_scope_matches(primary, item)
            })
            .collect::<Vec<_>>();
        for item in &selected {
            if !items.contains(item) && self.sidebar_move_selection_scope_matches(primary, item) {
                items.push(item.clone());
            }
        }
        if !items.iter().any(|item| item == primary) {
            items.insert(0, primary.clone());
        }
        items
    }

    fn update_sidebar_move_selection(
        &mut self,
        item: SidebarOrganizationItem,
        shift: bool,
        toggle: bool,
        cx: &mut Context<Self>,
    ) -> bool {
        let selection_only = shift || toggle;
        if shift {
            let anchor = self.sidebar_move_selection_anchor.clone();
            let compatible = anchor
                .as_ref()
                .is_some_and(|anchor| self.sidebar_move_selection_scope_matches(anchor, &item));
            if !compatible {
                self.sidebar_move_selected_items.clear();
                self.sidebar_move_selected_items.insert(item.clone());
                self.sidebar_move_selection_anchor = Some(item);
            } else if let Some(anchor) = anchor {
                let order = self.sidebar_move_selection_order(&item);
                let Some(anchor_index) = order.iter().position(|candidate| candidate == &anchor)
                else {
                    self.sidebar_move_selected_items.clear();
                    self.sidebar_move_selected_items.insert(item.clone());
                    self.sidebar_move_selection_anchor = Some(item);
                    cx.notify();
                    return selection_only;
                };
                let Some(item_index) = order.iter().position(|candidate| candidate == &item) else {
                    return selection_only;
                };
                if !toggle {
                    self.sidebar_move_selected_items.clear();
                }
                let range = if anchor_index <= item_index {
                    &order[anchor_index..=item_index]
                } else {
                    &order[item_index..=anchor_index]
                };
                self.sidebar_move_selected_items
                    .extend(range.iter().cloned());
            }
        } else if toggle {
            if self
                .sidebar_move_selected_items
                .iter()
                .any(|selected| !self.sidebar_move_selection_scope_matches(selected, &item))
            {
                self.sidebar_move_selected_items.clear();
            }
            if !self.sidebar_move_selected_items.remove(&item) {
                self.sidebar_move_selected_items.insert(item.clone());
            }
            self.sidebar_move_selection_anchor = Some(item);
        } else {
            self.sidebar_move_selected_items.clear();
            self.sidebar_move_selected_items.insert(item.clone());
            self.sidebar_move_selection_anchor = Some(item);
        }
        cx.notify();
        selection_only
    }

    fn clear_sidebar_move_selection(&mut self) {
        self.sidebar_move_selected_items.clear();
        self.sidebar_move_selection_anchor = None;
    }

    fn toggle_sidebar_batch_mode(&mut self, cx: &mut Context<Self>) {
        self.sidebar_batch_mode = !self.sidebar_batch_mode;
        self.clear_sidebar_move_selection();
        if !self.sidebar_batch_mode {
            self.sidebar_state.clear_selection();
        }
        cx.notify();
    }

    fn toggle_all_batch_sessions(&mut self, cx: &mut Context<Self>) {
        let all_ids = self
            .sessions
            .iter()
            .map(|session| session.id.as_str().to_string())
            .collect::<BTreeSet<_>>();
        if !all_ids.is_empty() && self.sidebar_state.selected_ids == all_ids {
            self.sidebar_state.clear_selection();
        } else {
            self.sidebar_state.selected_ids = all_ids;
        }
        cx.notify();
    }

    fn toggle_project_batch_sessions(&mut self, session_ids: Vec<String>, cx: &mut Context<Self>) {
        let all_selected = !session_ids.is_empty()
            && session_ids
                .iter()
                .all(|id| self.sidebar_state.selected_ids.contains(id));
        for session_id in session_ids {
            if all_selected {
                self.sidebar_state.selected_ids.remove(&session_id);
            } else {
                self.sidebar_state.selected_ids.insert(session_id);
            }
        }
        cx.notify();
    }

    fn activate_workspace(&mut self, workspace: WorkspaceRecord, cx: &mut Context<Self>) {
        self.ui_state.workbench.selected_workspace_id = Some(workspace.id.as_str().to_string());
        let state_owner = self.workspace_state_owner_for_workspace(&workspace.id);
        self.switch_workspace_layout_owner(state_owner.clone(), cx);
        if let Some(backend) = self.backend.clone() {
            self.code_workbench.update(cx, |workbench, cx| {
                workbench.sync_workspace(
                    backend,
                    workspace.id,
                    std::path::PathBuf::from(workspace.root_path),
                    state_owner,
                    cx,
                )
            });
        }
        self.queue_ui_state();
    }

    pub(crate) fn focus_worktree_operation_target(
        &mut self,
        workspace_id: vibex_core::WorkspaceId,
        cx: &mut Context<Self>,
    ) {
        let Some(workspace) = self
            .workspaces
            .iter()
            .find(|(_, workspace)| workspace.id == workspace_id)
            .map(|(_, workspace)| workspace.clone())
        else {
            self.runtime_note = Some("worktree_target_workspace_not_found".to_string());
            cx.notify();
            return;
        };
        self.activate_workspace(workspace, cx);
        self.open_right_rail_mode(RightRailMode::Git, cx);
        self.code_workbench.update(cx, |workbench, cx| {
            workbench.set_git_mode(vibex_desktop_model::GitWorkbenchMode::Changes, cx)
        });
    }

    pub(crate) fn assist_worktree_merge(
        &mut self,
        operation: GitWorktreeOperationRecord,
        cx: &mut Context<Self>,
    ) {
        if !matches!(
            operation.status,
            GitWorktreeOperationStatus::NeedsResolution
                | GitWorktreeOperationStatus::NeedsAttention
        ) {
            self.agent_error = Some("worktree_assistance_operation_inactive".to_string());
            cx.notify();
            return;
        }
        if self.worktree_assistance_task.is_some() {
            if self.worktree_assistance_operation_id.as_ref() != Some(&operation.operation_id) {
                self.runtime_note = Some("Another Worktree assistance action is starting".into());
            }
            cx.notify();
            return;
        }
        let Some(backend) = self.backend.clone() else {
            self.agent_error = Some("backend_unavailable".to_string());
            cx.notify();
            return;
        };
        if !backend
            .capabilities()
            .agent
            .supports(BackendOperation::AgentCreateSession)
            || !backend
                .capabilities()
                .git
                .supports(BackendOperation::GitWorktreeLifecycleMutate)
        {
            self.agent_error = Some("worktree_assistance_unsupported".to_string());
            cx.notify();
            return;
        }
        let Some(target_workspace_id) = operation.target_workspace_id.clone() else {
            self.agent_error = Some("worktree_target_workspace_missing".to_string());
            cx.notify();
            return;
        };
        let Some(target_workspace) = self
            .workspaces
            .iter()
            .find(|(_, workspace)| workspace.id == target_workspace_id)
            .map(|(_, workspace)| workspace.clone())
        else {
            self.agent_error = Some("worktree_target_workspace_not_found".to_string());
            cx.notify();
            return;
        };
        let runtime_selection = self
            .selected_runtime_selection()
            .or_else(|| self.new_session_runtime_selection.clone())
            .or_else(|| {
                self.runtime_catalog.as_ref().and_then(|catalog| {
                    catalog
                        .options
                        .iter()
                        .find(|option| {
                            option.availability == vibex_core::RuntimeOptionAvailability::Available
                        })
                        .map(|option| option.selection.clone())
                })
            });
        if operation.detail.assistance_session_id.is_none() && runtime_selection.is_none() {
            self.agent_error = Some("worktree_assistance_runtime_unavailable".to_string());
            cx.notify();
            return;
        }

        let operation_id = operation.operation_id.clone();
        let prompt = worktree_assistance_prompt(&operation);
        let source_branch = operation.branch.as_deref().unwrap_or("source").to_string();
        let target_branch = operation
            .detail
            .target_branch
            .as_deref()
            .unwrap_or("target")
            .to_string();
        let title = format!("Resolve merge: {source_branch} -> {target_branch}");
        let bound_session_id = operation.detail.assistance_session_id.clone();
        let target_root = target_workspace.root_path.clone();
        let target_mode = target_workspace.mode;
        let target_id = target_workspace.id.clone();
        let (session_tx, mut session_rx) = mpsc::unbounded_channel();
        self.worktree_assistance_operation_id = Some(operation_id.clone());
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            let session = if let Some(session_id) = bound_session_id {
                match backend.agent().open_session(session_id).await {
                    Ok(session)
                        if session.workspace_id == target_id
                            && session.archived_at_ms.is_none()
                            && session.deleted_at_ms.is_none() =>
                    {
                        session
                    }
                    Ok(_) => {
                        return Err(BackendError::conflict(
                            "worktree_assistance_session_workspace_mismatch",
                            "bound assistance Session is not active in the target Workspace",
                        ));
                    }
                    Err(_) => {
                        let selection = runtime_selection.clone().ok_or_else(|| {
                            BackendError::unsupported(
                                "worktree_assistance_runtime_unavailable",
                                "no Agent runtime is available for a replacement Session",
                            )
                        })?;
                        backend
                            .agent()
                            .create_session(
                                MutationRequest::new(CreateAgentSessionRequest {
                                    session_id: None,
                                    defer_runtime_materialization: false,
                                    runtime: selection,
                                    workspace_root: target_root.clone(),
                                    workspace_mode: target_mode,
                                    title: Some(title.clone()),
                                    safety: None,
                                })
                                .with_idempotency_key(format!(
                                    "worktree-assistance-session:{}",
                                    operation_id.as_str()
                                )),
                            )
                            .await?
                    }
                }
            } else {
                let selection = runtime_selection.clone().ok_or_else(|| {
                    BackendError::unsupported(
                        "worktree_assistance_runtime_unavailable",
                        "no Agent runtime is available for an assistance Session",
                    )
                })?;
                backend
                    .agent()
                    .create_session(
                        MutationRequest::new(CreateAgentSessionRequest {
                            session_id: None,
                            defer_runtime_materialization: false,
                            runtime: selection,
                            workspace_root: target_root,
                            workspace_mode: target_mode,
                            title: Some(title),
                            safety: None,
                        })
                        .with_idempotency_key(format!(
                            "worktree-assistance-session:{}",
                            operation_id.as_str()
                        )),
                    )
                    .await?
            };
            backend
                .git()
                .git_worktree_bind_assistance_session(
                    MutationRequest::new(GitWorktreeAssistanceSessionRequest {
                        operation_id: operation_id.clone(),
                        workspace_id: target_id,
                        session_id: session.id.clone(),
                    })
                    .with_idempotency_key(format!(
                        "worktree-assistance-bind:{}",
                        operation_id.as_str()
                    )),
                )
                .await?;
            let _ = session_tx.send(session.clone());
            let selection = backend
                .agent()
                .runtime_selection(session.id.clone())
                .await?
                .effective;
            backend
                .agent()
                .send_message(
                    MutationRequest::new(SendAgentMessageRequest {
                        session_id: session.id.clone(),
                        message_idempotency_key: format!(
                            "worktree-assistance-context:{}",
                            operation_id.as_str()
                        ),
                        reasoning_effort: selection.reasoning_effort.clone(),
                        desired_runtime: selection,
                        text: prompt,
                        attachments: Vec::new(),
                        correlation_id: None,
                        delivery: UserMessageDelivery::Prompt,
                    })
                    .with_idempotency_key(format!(
                        "worktree-assistance-context:{}",
                        operation_id.as_str()
                    )),
                )
                .await?;
            backend.agent().open_session(session.id).await
        });
        self.agent_error = None;
        self.worktree_assistance_task = Some(cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                let announced = session_rx.recv().await;
                if let Some(session) = announced.as_ref() {
                    let _ = entity.update(cx, |this, cx| {
                        this.upsert_session_snapshot(session.clone());
                        this.set_session_turn_pending(&session.id, true);
                        this.reconcile_sidebar_state();
                        this.publish_sidebar_invalidation();
                        this.select_session_with_history(session.id.clone(), false, cx);
                        this.refresh_workspace_contexts(cx);
                        cx.notify();
                    });
                }
                let outcome = runner.await;
                let _ = entity.update(cx, |this, cx| {
                    if let Some(session) = announced.as_ref() {
                        this.set_session_turn_pending(&session.id, false);
                    }
                    this.worktree_assistance_task = None;
                    this.worktree_assistance_operation_id = None;
                    match outcome {
                        Ok(Ok(session)) => {
                            let session_id = session.id.clone();
                            this.upsert_session_snapshot(session);
                            this.reconcile_sidebar_state();
                            this.publish_sidebar_invalidation();
                            if this.selected_session_id.as_ref() == Some(&session_id) {
                                this.refresh_selected_agent_timeline(cx);
                            }
                            this.code_workbench
                                .update(cx, |workbench, cx| workbench.refresh_git(cx));
                            this.refresh_workspace_contexts(cx);
                        }
                        Ok(Err(error)) => {
                            this.agent_error = Some(format!("{}: {}", error.code, error.message));
                        }
                        Err(error) => {
                            this.agent_error =
                                Some(format!("Worktree assistance task failed: {error}"));
                        }
                    }
                    cx.notify();
                });
            },
        ));
        cx.notify();
    }

    /// Collapses or expands a sidebar project row.
    ///
    /// The row is a disclosure control, not a navigation target. The center
    /// timeline, the right rail, and the file/git panels all follow the selected
    /// Session, so only clicking a Session row may move that focus; activating
    /// the project's Workspace here left the rail pointing at a project the
    /// on-screen Session does not belong to.
    fn activate_and_toggle_project(&mut self, project_id: ProjectId, cx: &mut Context<Self>) {
        let project_id = project_id.as_str().to_string();
        if !self.sidebar_state.collapsed_ids.remove(&project_id) {
            self.sidebar_state.collapsed_ids.insert(project_id);
        }
        self.collapsed_project_restore = None;
        self.queue_agent_ui_state();
        self.publish_sidebar_invalidation();
        cx.notify();
    }

    fn toggle_sidebar_project(&mut self, project_id: &str, cx: &mut Context<Self>) {
        if !self.sidebar_state.collapsed_ids.remove(project_id) {
            self.sidebar_state
                .collapsed_ids
                .insert(project_id.to_string());
        }
        self.collapsed_project_restore = None;
        self.queue_agent_ui_state();
        self.publish_sidebar_invalidation();
        cx.notify();
    }

    /// Collapses or expands a sidebar workspace row.
    ///
    /// Like the project row, this is a disclosure control: it never selects a
    /// Session and never moves the Workspace focus, so the right rail keeps
    /// following the Session on screen.
    fn activate_and_toggle_sidebar_workspace(
        &mut self,
        workspace: WorkspaceRecord,
        cx: &mut Context<Self>,
    ) {
        let workspace_id = workspace.id.as_str().to_string();
        let project_id = workspace.project_id.clone();
        let was_collapsed = self
            .ui_state
            .sidebar
            .collapsed_workspace_ids
            .contains(&workspace_id);
        if was_collapsed {
            for (_, candidate) in &self.workspaces {
                if candidate.project_id == project_id {
                    self.ui_state
                        .sidebar
                        .collapsed_workspace_ids
                        .insert(candidate.id.as_str().to_string());
                }
            }
            self.ui_state
                .sidebar
                .collapsed_workspace_ids
                .remove(&workspace_id);
        } else {
            self.ui_state
                .sidebar
                .collapsed_workspace_ids
                .insert(workspace_id);
        }
        self.queue_ui_state();
        self.publish_sidebar_invalidation();
        cx.notify();
    }

    fn set_sidebar_organization_drop_target(
        &mut self,
        moving: Vec<SidebarOrganizationItem>,
        target: SidebarOrganizationItem,
        position: SidebarOrganizationDropPosition,
        cx: &mut Context<Self>,
    ) {
        let session_projects = self.sidebar_session_projects();
        let project_reorder = moving
            .iter()
            .all(|item| matches!(item, SidebarOrganizationItem::Project(_)))
            && matches!(&target, SidebarOrganizationItem::Project(_));
        let session_reorder = moving
            .iter()
            .all(|item| matches!(item, SidebarOrganizationItem::Session(_)))
            && matches!(&target, SidebarOrganizationItem::Session(_));
        let valid = match position {
            SidebarOrganizationDropPosition::Before | SidebarOrganizationDropPosition::After => {
                self.ui_state.sidebar.organization.can_move_many_relative(
                    &moving,
                    &target,
                    &session_projects,
                )
            }
            SidebarOrganizationDropPosition::Into => match &target {
                SidebarOrganizationItem::Folder(folder_id) => self
                    .ui_state
                    .sidebar
                    .organization
                    .can_move_many_into(&moving, folder_id, &session_projects),
                SidebarOrganizationItem::Project(_)
                | SidebarOrganizationItem::Session(_)
                | SidebarOrganizationItem::Group(_) => false,
            },
        };
        if !valid {
            // Keep the last valid target while the pointer crosses a gap or an
            // animated row. GPUI dispatches typed drag-move listeners beyond
            // the row that currently contains the pointer.
            return;
        }
        self.sidebar_organization_root_drop_target = None;
        if !project_reorder {
            self.sidebar_project_drop_target = None;
        }
        if !session_reorder {
            self.sidebar_session_drop_target = None;
        }
        let next = valid.then_some(SidebarOrganizationDropTarget {
            moving,
            target,
            position,
        });
        if self.sidebar_organization_drop_target != next {
            self.sidebar_organization_drop_target = next;
            cx.notify();
        }
    }

    fn set_sidebar_organization_root_drop_target(
        &mut self,
        moving: Vec<SidebarOrganizationItem>,
        scope: SidebarOrganizationScope,
        cx: &mut Context<Self>,
    ) {
        let session_projects = self.sidebar_session_projects();
        let next = self
            .ui_state
            .sidebar
            .organization
            .can_move_many_to_scope_root(&moving, &scope, &session_projects)
            .then_some((moving, scope));
        if next.is_none() {
            return;
        }
        let changed = self.sidebar_organization_root_drop_target != next
            || self.sidebar_organization_drop_target.is_some();
        self.sidebar_organization_drop_target = None;
        self.sidebar_project_drop_target = None;
        self.sidebar_session_drop_target = None;
        self.sidebar_organization_root_drop_target = next;
        if changed {
            cx.notify();
        }
    }

    fn apply_sidebar_organization_drop(
        &mut self,
        moving: &[SidebarOrganizationItem],
        cx: &mut Context<Self>,
    ) -> bool {
        let target = self
            .sidebar_organization_drop_target
            .take()
            .filter(|target| target.moving.as_slice() == moving);
        let session_projects = self.sidebar_session_projects();
        if target.is_none() {
            let Some((_, scope)) = self
                .sidebar_organization_root_drop_target
                .take()
                .filter(|(target_moving, _)| target_moving.as_slice() == moving)
            else {
                return false;
            };
            let changed = self
                .ui_state
                .sidebar
                .organization
                .move_many_to_scope_root_end(moving, &scope, &session_projects);
            if changed {
                self.queue_ui_state();
                self.invalidate_sidebar_projection_cache();
                self.publish_sidebar_invalidation();
            }
            cx.notify();
            return true;
        }
        self.sidebar_organization_root_drop_target = None;
        let target = target.expect("sidebar organization target checked above");
        let organization_changed = match target.position {
            SidebarOrganizationDropPosition::Before | SidebarOrganizationDropPosition::After => {
                self.ui_state.sidebar.organization.move_many_relative(
                    moving,
                    &target.target,
                    target.position == SidebarOrganizationDropPosition::After,
                    &session_projects,
                )
            }
            SidebarOrganizationDropPosition::Into => match &target.target {
                SidebarOrganizationItem::Folder(folder_id) => self
                    .ui_state
                    .sidebar
                    .organization
                    .move_many_into(moving, folder_id, &session_projects),
                SidebarOrganizationItem::Project(_)
                | SidebarOrganizationItem::Session(_)
                | SidebarOrganizationItem::Group(_) => false,
            },
        };

        // Root Project/Session order predates organization folders and remains
        // the compatibility source for flat sidebar ordering.
        let legacy_order_changed = match (&target.target, target.position) {
            (
                SidebarOrganizationItem::Project(target_id),
                SidebarOrganizationDropPosition::Before | SidebarOrganizationDropPosition::After,
            ) if moving
                .iter()
                .all(|item| matches!(item, SidebarOrganizationItem::Project(_))) =>
            {
                let original_order = self.ui_state.sidebar.project_order.clone();
                let project_ids = self
                    .workspaces
                    .iter()
                    .map(|(project, _)| project.id.as_str().to_string())
                    .collect::<Vec<_>>();
                complete_string_order(&mut self.ui_state.sidebar.project_order, project_ids);
                let moving_ids = moving
                    .iter()
                    .filter_map(|item| match item {
                        SidebarOrganizationItem::Project(id) => Some(id.clone()),
                        _ => None,
                    })
                    .collect::<Vec<_>>();
                let _ = move_strings_relative(
                    &mut self.ui_state.sidebar.project_order,
                    &moving_ids,
                    target_id,
                    target.position == SidebarOrganizationDropPosition::After,
                );
                self.ui_state.sidebar.project_order != original_order
            }
            (
                SidebarOrganizationItem::Session(target_id),
                SidebarOrganizationDropPosition::Before | SidebarOrganizationDropPosition::After,
            ) if moving
                .iter()
                .all(|item| matches!(item, SidebarOrganizationItem::Session(_))) =>
            {
                let original_order = self.sidebar_state.row_order.clone();
                // Re-snapshot the manual band to the order the user currently
                // sees before applying the move; appending missing sessions to
                // the tail of a stale band instead would demote the visible
                // top cluster (often the running sessions) to the bottom of
                // the sidebar.
                self.sidebar_state.row_order = self
                    .ordered_sidebar_session_projects()
                    .into_iter()
                    .map(|(session_id, _)| session_id)
                    .collect::<Vec<_>>();
                let moving_ids = moving
                    .iter()
                    .filter_map(|item| match item {
                        SidebarOrganizationItem::Session(id) => Some(id.clone()),
                        _ => None,
                    })
                    .collect::<Vec<_>>();
                let _ = move_strings_relative(
                    &mut self.sidebar_state.row_order,
                    &moving_ids,
                    target_id,
                    target.position == SidebarOrganizationDropPosition::After,
                );
                let changed = self.sidebar_state.row_order != original_order
                    || self.ui_state.sidebar.session_order != self.sidebar_state.row_order;
                self.ui_state.sidebar.session_order = self.sidebar_state.row_order.clone();
                if changed {
                    self.ui_state.sidebar.session_order_anchored_at_ms = unix_timestamp_ms();
                }
                changed
            }
            _ => false,
        };

        if organization_changed || legacy_order_changed {
            self.queue_ui_state();
            self.invalidate_sidebar_projection_cache();
            self.publish_sidebar_invalidation();
        }
        cx.notify();
        true
    }

    fn sidebar_organization_drop_position(
        &self,
        target: &SidebarOrganizationItem,
    ) -> Option<SidebarOrganizationDropPosition> {
        self.sidebar_organization_drop_target
            .as_ref()
            .filter(|drop_target| &drop_target.target == target)
            .map(|drop_target| drop_target.position)
    }

    fn sidebar_organization_root_drop_active(&self, scope: &SidebarOrganizationScope) -> bool {
        self.sidebar_organization_root_drop_target
            .as_ref()
            .is_some_and(|(_, target_scope)| target_scope == scope)
    }

    fn start_sidebar_workspace_drag(
        &mut self,
        drag: &SidebarWorkspaceDrag,
        cursor_offset_y: f32,
        cx: &mut Context<Self>,
    ) {
        self.session_group_tab_removal_active = false;
        let groups = self.sidebar_workspace_groups("");
        let Some(group) = groups
            .iter()
            .find(|group| group.project.id.as_str() == drag.project_id)
        else {
            return;
        };
        let original_ids = group
            .workspaces
            .iter()
            .map(|workspace| workspace.workspace.id.as_str().to_string())
            .collect::<Vec<_>>();
        if !original_ids.iter().any(|id| id == &drag.workspace_id) {
            return;
        }
        let initial_target = reorder_target_from_cursor_offset(
            &original_ids,
            &drag.workspace_id,
            cursor_offset_y,
            SIDEBAR_WORKSPACE_ROW_HEIGHT,
            SIDEBAR_WORKSPACE_REORDER_GAP,
        )
        .filter(|(target_id, _)| target_id != &drag.workspace_id);
        let preview_ids = initial_target
            .as_ref()
            .map(|(target_id, after)| {
                reordered_string_ids_many(
                    &original_ids,
                    std::slice::from_ref(&drag.workspace_id),
                    target_id,
                    *after,
                )
            })
            .unwrap_or_else(|| original_ids.clone());
        self.sidebar_workspace_drag_state = Some(SidebarWorkspaceDragState {
            workspace_id: drag.workspace_id.clone(),
            project_id: drag.project_id.clone(),
            original_ids,
            preview_ids,
        });
        self.sidebar_workspace_drop_target =
            initial_target.map(|(workspace_id, after)| SidebarWorkspaceDropTarget {
                workspace_id,
                after,
            });
        self.sidebar_project_drop_target = None;
        self.sidebar_session_drop_target = None;
        self.sidebar_organization_drop_target = None;
        self.sidebar_organization_root_drop_target = None;
        cx.notify();
    }

    fn preview_sidebar_workspace_reorder(
        &mut self,
        drag: &SidebarWorkspaceDrag,
        target_id: &str,
        after: bool,
        cx: &mut Context<Self>,
    ) {
        let Some(state) = self.sidebar_workspace_drag_state.as_mut().filter(|state| {
            state.workspace_id == drag.workspace_id && state.project_id == drag.project_id
        }) else {
            return;
        };
        state.preview_ids = reordered_string_ids_many(
            &state.original_ids,
            std::slice::from_ref(&drag.workspace_id),
            target_id,
            after,
        );
        let next_target = SidebarWorkspaceDropTarget {
            workspace_id: target_id.to_string(),
            after,
        };
        if self.sidebar_workspace_drop_target.as_ref() != Some(&next_target) {
            self.sidebar_workspace_drop_target = Some(next_target);
            cx.notify();
        }
    }

    fn finish_sidebar_workspace_drag(
        &mut self,
        project_id: &str,
        workspace_id: &str,
        cx: &mut Context<Self>,
    ) {
        let Some(state) = self
            .sidebar_workspace_drag_state
            .take()
            .filter(|state| state.project_id == project_id && state.workspace_id == workspace_id)
        else {
            return;
        };
        let direct_target = self.sidebar_workspace_drop_target.take();
        let fallback_target = direct_target
            .map(|target| (target.workspace_id, target.after))
            .or_else(|| {
                reorder_target_from_preview_many(
                    &state.original_ids,
                    &state.preview_ids,
                    std::slice::from_ref(&state.workspace_id),
                )
            });
        if let Some((target_id, after)) = fallback_target {
            self.move_workspace_order_relative(
                project_id,
                &state.workspace_id,
                &target_id,
                after,
                cx,
            );
        } else {
            cx.notify();
        }
    }

    fn move_workspace_order_relative(
        &mut self,
        project_id: &str,
        moving_id: &str,
        target_id: &str,
        after: bool,
        cx: &mut Context<Self>,
    ) {
        let ids = self
            .sidebar_workspace_groups("")
            .iter()
            .find(|group| group.project.id.as_str() == project_id)
            .map(|group| {
                group
                    .workspaces
                    .iter()
                    .map(|workspace| workspace.workspace.id.as_str().to_string())
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        if ids.is_empty() {
            return;
        }
        let order = self
            .ui_state
            .sidebar
            .workspace_order
            .entry(project_id.to_string())
            .or_default();
        complete_string_order(order, ids);
        if move_string_relative(order, moving_id, target_id, after) {
            self.queue_ui_state();
            self.invalidate_sidebar_projection_cache();
            self.publish_sidebar_invalidation();
            cx.notify();
        }
    }

    fn start_sidebar_project_drag(
        &mut self,
        drag: &SidebarProjectDrag,
        cursor_offset_y: f32,
        source_was_collapsed: bool,
        cx: &mut Context<Self>,
    ) {
        self.session_group_tab_removal_active = false;
        let project_id = drag.project_id.as_str();
        if !self
            .sidebar_move_selected_items
            .contains(&SidebarOrganizationItem::Project(project_id.to_string()))
        {
            self.update_sidebar_move_selection(
                SidebarOrganizationItem::Project(project_id.to_string()),
                false,
                false,
                cx,
            );
        }
        let groups = self.sidebar_workspace_groups("");
        let moving = drag
            .project_ids
            .iter()
            .cloned()
            .map(SidebarOrganizationItem::Project)
            .collect::<Vec<_>>();
        let primary = SidebarOrganizationItem::Project(project_id.to_string());
        let parent = self.ui_state.sidebar.organization.parent_of(&primary);
        let sibling_items = self.sidebar_root_organization_items(&groups, parent.as_deref());
        let flat_preview_enabled = sibling_items
            .iter()
            .all(|item| matches!(item, SidebarOrganizationItem::Project(_)));
        let original_ids = sibling_items
            .into_iter()
            .filter_map(|item| match item {
                SidebarOrganizationItem::Project(id) => Some(id),
                SidebarOrganizationItem::Folder(_)
                | SidebarOrganizationItem::Session(_)
                | SidebarOrganizationItem::Group(_) => None,
            })
            .collect::<Vec<_>>();
        if !original_ids.iter().any(|id| id == project_id) {
            return;
        }
        let flat_preview_enabled = flat_preview_enabled
            && drag
                .project_ids
                .iter()
                .all(|project_id| original_ids.contains(project_id));
        let initial_target = if source_was_collapsed {
            reorder_target_from_cursor_offset(
                &original_ids,
                project_id,
                cursor_offset_y,
                SIDEBAR_REORDER_ROW_HEIGHT,
                SIDEBAR_PROJECT_REORDER_GAP,
            )
        } else {
            let moving_index = original_ids.iter().position(|id| id == project_id);
            let displacement = cursor_offset_y - SIDEBAR_REORDER_ROW_HEIGHT / 2.0;
            let index_delta = if displacement > SIDEBAR_REORDER_ROW_HEIGHT {
                1
            } else if displacement < -SIDEBAR_REORDER_ROW_HEIGHT {
                -1
            } else {
                0
            };
            moving_index.and_then(|moving_index| {
                let target_index = moving_index
                    .saturating_add_signed(index_delta)
                    .min(original_ids.len().saturating_sub(1));
                (target_index != moving_index).then(|| {
                    (
                        original_ids[target_index].clone(),
                        target_index > moving_index,
                    )
                })
            })
        }
        .filter(|(target_id, _)| !drag.project_ids.contains(target_id));
        let preview_ids = initial_target
            .as_ref()
            .map(|(target_id, after)| {
                reordered_string_ids_many(&original_ids, &drag.project_ids, target_id, *after)
            })
            .unwrap_or_else(|| original_ids.clone());
        self.sidebar_project_drag_state = Some(SidebarProjectDragState {
            project_id: project_id.to_string(),
            project_ids: drag.project_ids.clone(),
            preview_ids,
            original_ids,
            flat_preview_enabled,
        });
        self.sidebar_project_drop_target = initial_target
            .map(|(project_id, after)| SidebarProjectDropTarget { project_id, after });
        self.sidebar_organization_drop_target = None;
        self.sidebar_organization_root_drop_target = None;
        if let Some(target) = self.sidebar_project_drop_target.clone() {
            self.set_sidebar_organization_drop_target(
                moving,
                SidebarOrganizationItem::Project(target.project_id),
                if target.after {
                    SidebarOrganizationDropPosition::After
                } else {
                    SidebarOrganizationDropPosition::Before
                },
                cx,
            );
        }
        cx.notify();
    }

    fn preview_sidebar_project_reorder(
        &mut self,
        drag: &SidebarProjectDrag,
        target_id: &str,
        after: bool,
        cx: &mut Context<Self>,
    ) {
        let next_ids = {
            let Some(state) = self.sidebar_project_drag_state.as_mut().filter(|state| {
                state.project_id == drag.project_id && state.project_ids == drag.project_ids
            }) else {
                return;
            };
            let next_ids =
                reordered_string_ids_many(&state.original_ids, &drag.project_ids, target_id, after);
            state.preview_ids = next_ids.clone();
            next_ids
        };
        let next_target = SidebarProjectDropTarget {
            project_id: target_id.to_string(),
            after,
        };
        let target_changed = self.sidebar_project_drop_target.as_ref() != Some(&next_target);
        self.sidebar_project_drop_target = Some(next_target);
        self.set_sidebar_organization_drop_target(
            drag.project_ids
                .iter()
                .cloned()
                .map(SidebarOrganizationItem::Project)
                .collect(),
            SidebarOrganizationItem::Project(target_id.to_string()),
            if after {
                SidebarOrganizationDropPosition::After
            } else {
                SidebarOrganizationDropPosition::Before
            },
            cx,
        );
        if target_changed || !next_ids.is_empty() {
            cx.notify();
        }
    }

    fn finish_sidebar_project_drag(&mut self, project_id: &str, cx: &mut Context<Self>) {
        let valid_drag = self
            .sidebar_project_drag_state
            .as_ref()
            .is_some_and(|state| state.project_id == project_id);
        if !valid_drag {
            return;
        }
        let direct_target = self.sidebar_project_drop_target.take();
        let state = self
            .sidebar_project_drag_state
            .take()
            .expect("validated sidebar project drag state above");
        let moving = state
            .project_ids
            .iter()
            .cloned()
            .map(SidebarOrganizationItem::Project)
            .collect::<Vec<_>>();
        if self.apply_sidebar_organization_drop(&moving, cx) {
            return;
        }
        let fallback_target = direct_target
            .map(|target| (target.project_id, target.after))
            .or_else(|| {
                reorder_target_from_preview_many(
                    &state.original_ids,
                    &state.preview_ids,
                    &state.project_ids,
                )
            });
        if let Some((target_id, after)) = fallback_target {
            self.move_project_order_relative(&state.project_ids, &target_id, after, cx);
        } else {
            cx.notify();
        }
    }

    fn start_sidebar_session_drag(
        &mut self,
        drag: &SidebarSessionDrag,
        cursor_offset_y: f32,
        cx: &mut Context<Self>,
    ) {
        // A new drag owns the sidebar's drop affordances; a tab drag that ended
        // somewhere else must not keep claiming them.
        self.session_group_tab_removal_active = false;
        let primary = SidebarOrganizationItem::Session(drag.session_id.as_str().to_string());
        if !self.sidebar_move_selected_items.contains(&primary) {
            if self.sidebar_row_is_move_selected(&primary) {
                // The row is painted as part of the selection, so the drag has
                // to keep the rest of it: adding the row is what the user sees.
                self.sidebar_move_selected_items.insert(primary.clone());
                self.sidebar_move_selection_anchor = Some(primary.clone());
                cx.notify();
            } else {
                self.update_sidebar_move_selection(primary.clone(), false, false, cx);
            }
        }
        let groups = self.sidebar_workspace_groups("");
        let moving = drag
            .session_ids
            .iter()
            .cloned()
            .map(SidebarOrganizationItem::Session)
            .collect::<Vec<_>>();
        let parent = self.ui_state.sidebar.organization.parent_of(&primary);
        let (mut original_ids, flat_preview_enabled) = if parent.is_some() {
            groups
                .iter()
                .find(|group| group.project.id.as_str() == drag.project_id)
                .map(|group| {
                    let sibling_items = self.sidebar_project_organization_items(
                        &drag.project_id,
                        &group.compact_sessions,
                        parent.as_deref(),
                    );
                    let flat_preview_enabled = sibling_items
                        .iter()
                        .all(|item| !matches!(item, SidebarOrganizationItem::Folder(_)));
                    let ids = sibling_items
                        .into_iter()
                        .filter_map(|item| match item {
                            SidebarOrganizationItem::Session(id)
                                if self.sidebar_state.pinned_ids.contains(&id) == drag.pinned =>
                            {
                                Some(id)
                            }
                            SidebarOrganizationItem::Folder(_)
                            | SidebarOrganizationItem::Project(_)
                            | SidebarOrganizationItem::Session(_)
                            | SidebarOrganizationItem::Group(_) => None,
                        })
                        .collect::<Vec<_>>();
                    (ids, flat_preview_enabled)
                })
                .unwrap_or_default()
        } else {
            let ids = groups
                .iter()
                .flat_map(|group| &group.workspaces)
                // A projection may merge workspace aliases that share the same
                // checkout. The session's persisted workspace id can therefore
                // differ from the canonical row id used by the projection.
                .find(|workspace| {
                    workspace.workspace.id.as_str() == drag.workspace_id
                        || workspace
                            .sessions
                            .iter()
                            .any(|session| session.id == drag.session_id)
                })
                .map(|workspace| {
                    workspace
                        .sessions
                        .iter()
                        .filter(|session| !self.sidebar_session_is_organized(&session.id))
                        .filter(|session| {
                            self.sidebar_state.pinned_ids.contains(session.id.as_str())
                                == drag.pinned
                        })
                        .map(|session| session.id.as_str().to_string())
                        .collect::<Vec<_>>()
                })
                .unwrap_or_default();
            let flat_preview_enabled =
                if self.ui_state.sidebar.hierarchy_mode == SidebarHierarchyMode::Detailed {
                    true
                } else {
                    groups
                        .iter()
                        .find(|group| group.project.id.as_str() == drag.project_id)
                        .is_none_or(|group| {
                            self.sidebar_project_organization_items(
                                &drag.project_id,
                                &group.compact_sessions,
                                None,
                            )
                            .iter()
                            .all(|item| !matches!(item, SidebarOrganizationItem::Folder(_)))
                        })
                };
            (ids, flat_preview_enabled)
        };
        if !original_ids.iter().any(|id| id == drag.session_id.as_str()) {
            // The sibling order can be missing the row the drag started on: a
            // group paints its members from the group, and the placement tree
            // does not list a session whose placement sits in a collapsed
            // folder. Returning here would drop the drag on the floor, and the
            // drop is what takes the session out of its group.
            original_ids.push(drag.session_id.as_str().to_string());
        }
        let flat_preview_enabled = flat_preview_enabled
            && drag
                .session_ids
                .iter()
                .all(|session_id| original_ids.contains(session_id));
        let initial_target = reorder_target_from_cursor_offset(
            &original_ids,
            drag.session_id.as_str(),
            cursor_offset_y,
            SIDEBAR_REORDER_ROW_HEIGHT,
            SIDEBAR_SESSION_REORDER_GAP,
        )
        .filter(|(target_id, _)| !drag.session_ids.contains(target_id));
        let preview_ids = initial_target
            .as_ref()
            .map(|(target_id, after)| {
                reordered_string_ids_many(&original_ids, &drag.session_ids, target_id, *after)
            })
            .unwrap_or_else(|| original_ids.clone());
        self.sidebar_session_drag_state = Some(SidebarSessionDragState {
            workspace_id: drag.workspace_id.clone(),
            project_id: drag.project_id.clone(),
            session_id: drag.session_id.clone(),
            session_ids: drag.session_ids.clone(),
            preview_ids,
            original_ids,
            flat_preview_enabled,
        });
        self.sidebar_session_drop_target = initial_target.and_then(|(session_id, after)| {
            VibexSessionId::parse(session_id)
                .ok()
                .map(|session_id| SidebarSessionDropTarget { session_id, after })
        });
        self.sidebar_organization_drop_target = None;
        self.sidebar_organization_root_drop_target = None;
        if let Some(target) = self.sidebar_session_drop_target.clone() {
            self.set_sidebar_organization_drop_target(
                moving,
                SidebarOrganizationItem::Session(target.session_id.as_str().to_string()),
                if target.after {
                    SidebarOrganizationDropPosition::After
                } else {
                    SidebarOrganizationDropPosition::Before
                },
                cx,
            );
        }
        cx.notify();
    }

    fn preview_sidebar_session_reorder(
        &mut self,
        drag: &SidebarSessionDrag,
        target_id: &VibexSessionId,
        after: bool,
        cx: &mut Context<Self>,
    ) {
        let next_ids = {
            let Some(state) = self.sidebar_session_drag_state.as_mut().filter(|state| {
                state.project_id == drag.project_id
                    && state.session_id == drag.session_id
                    && state.session_ids == drag.session_ids
            }) else {
                return;
            };
            let next_ids = reordered_string_ids_many(
                &state.original_ids,
                &drag.session_ids,
                target_id.as_str(),
                after,
            );
            state.preview_ids = next_ids.clone();
            next_ids
        };
        let next_target = SidebarSessionDropTarget {
            session_id: target_id.clone(),
            after,
        };
        let target_changed = self.sidebar_session_drop_target.as_ref() != Some(&next_target);
        self.sidebar_session_drop_target = Some(next_target);
        self.set_sidebar_organization_drop_target(
            drag.session_ids
                .iter()
                .cloned()
                .map(SidebarOrganizationItem::Session)
                .collect(),
            SidebarOrganizationItem::Session(target_id.as_str().to_string()),
            if after {
                SidebarOrganizationDropPosition::After
            } else {
                SidebarOrganizationDropPosition::Before
            },
            cx,
        );
        if target_changed || !next_ids.is_empty() {
            cx.notify();
        }
    }

    fn finish_sidebar_session_drag(
        &mut self,
        workspace_id: &str,
        session_id: &VibexSessionId,
        landed_on: Option<&str>,
        cx: &mut Context<Self>,
    ) {
        let valid_drag = self
            .sidebar_session_drag_state
            .as_ref()
            .is_some_and(|state| {
                state.workspace_id == workspace_id && state.session_id == *session_id
            });
        if !valid_drag {
            return;
        }
        let direct_target = self.sidebar_session_drop_target.take();
        let state = self
            .sidebar_session_drag_state
            .take()
            .expect("validated sidebar session drag state above");
        let moving = state
            .session_ids
            .iter()
            .cloned()
            .map(SidebarOrganizationItem::Session)
            .collect::<Vec<_>>();
        // The row the pointer released on decides which group keeps the
        // sessions, not the last row the pointer happened to hover: a drop on
        // one of the dragged rows themselves never updates the hover target, so
        // reading it there kept a member of the group the sessions just left and
        // turned "leave the group" into a no-op join.
        let keep_group = landed_on.and_then(|session_id| {
            self.ui_state
                .sidebar
                .organization
                .group_of_session(session_id)
                .map(str::to_string)
        });
        let group_ids = self.dragged_group_session_ids(&state.session_ids);
        if self.apply_sidebar_organization_drop(&moving, cx) {
            self.apply_sidebar_session_group_drop(&group_ids, keep_group.as_deref(), cx);
            return;
        }
        let fallback_target = direct_target
            .map(|target| (target.session_id.as_str().to_string(), target.after))
            .or_else(|| {
                reorder_target_from_preview_many(
                    &state.original_ids,
                    &state.preview_ids,
                    &state.session_ids,
                )
            });
        if let Some((target_id, after)) = fallback_target {
            self.move_session_order_relative(&state.session_ids, &target_id, after, cx);
            self.apply_sidebar_session_group_drop(&group_ids, keep_group.as_deref(), cx);
        } else {
            cx.notify();
        }
    }

    /// Applies the group half of a session drop: sessions dropped inside a group
    /// join it, sessions dropped outside the group they came from leave it.
    ///
    /// A group lists its members under its own row and nowhere else, so the
    /// landing zone is the whole answer — there is no third case to weigh.
    fn apply_sidebar_session_group_drop(
        &mut self,
        session_ids: &[String],
        keep_group_id: Option<&str>,
        cx: &mut Context<Self>,
    ) {
        // A drop inside a group either joins it or is refused — a group holds
        // one Worktree — and neither outcome takes the sessions out of the
        // group they came from. Only a drop outside every group does that.
        if let Some(group_id) = keep_group_id {
            self.join_dragged_sessions_to_group(group_id, session_ids, cx);
            return;
        }
        self.release_dragged_sessions_from_groups(session_ids, cx);
    }

    /// Adds dragged sessions to the group the drop landed in.
    ///
    /// The group row is a small target, and a collapsed group shows nothing but
    /// that row, so a member row accepts the drop too: both mean "these sessions
    /// belong to this group". A group holds one Worktree, so a drop from another
    /// one is refused and leaves every session where it was.
    fn join_dragged_sessions_to_group(
        &mut self,
        group_id: &str,
        session_ids: &[String],
        cx: &mut Context<Self>,
    ) {
        let session_workspaces = self.sidebar_session_workspaces();
        if !self.ui_state.sidebar.organization.add_sessions_to_group(
            group_id,
            session_ids,
            &session_workspaces,
        ) {
            return;
        }
        self.ui_state
            .sidebar
            .organization
            .collapsed_group_ids
            .remove(group_id);
        self.queue_ui_state();
        self.publish_sidebar_invalidation();
        cx.notify();
    }

    /// The sessions a drop applies to the group it joins or leaves.
    ///
    /// The drag payload is captured when the row renders, so it can be older
    /// than the selection on screen; the drop is the moment that matters. Every
    /// selected session of the primary's project belongs to this drag, and
    /// `start_sidebar_session_drag` narrows the selection to the row the drag
    /// began on when that row was not part of it — so this cannot widen a drag
    /// the user did not make.
    fn dragged_group_session_ids(&self, payload_ids: &[String]) -> Vec<String> {
        let Some(primary) = payload_ids.first() else {
            return Vec::new();
        };
        let primary_item = SidebarOrganizationItem::Session(primary.clone());
        let mut ids = payload_ids.to_vec();
        for selected in self.sidebar_move_selection_items() {
            let SidebarOrganizationItem::Session(session_id) = &selected else {
                continue;
            };
            if !ids.iter().any(|id| id == session_id)
                && self.sidebar_move_selection_scope_matches(&primary_item, &selected)
            {
                ids.push(session_id.clone());
            }
        }
        ids
    }

    /// Takes dragged sessions out of whatever group holds them.
    ///
    /// Dropping a member row outside its group is the drag path for "leave the
    /// session group", so it runs after the drop resolved rather than as part of
    /// the organization move: the placement move says where the row lands, this
    /// says which group it stops belonging to.
    fn release_dragged_sessions_from_groups(
        &mut self,
        session_ids: &[String],
        cx: &mut Context<Self>,
    ) {
        let mut leaving: BTreeMap<String, Vec<String>> = BTreeMap::new();
        for session_id in session_ids {
            let Some(group_id) = self
                .ui_state
                .sidebar
                .organization
                .group_of_session(session_id)
            else {
                continue;
            };
            leaving
                .entry(group_id.to_string())
                .or_default()
                .push(session_id.clone());
        }
        let mut changed = false;
        for (group_id, members) in leaving {
            if self
                .ui_state
                .sidebar
                .organization
                .remove_sessions_from_group(&group_id, &members)
            {
                self.release_group_session_views(&members);
                changed = true;
            }
        }
        if changed {
            self.queue_ui_state();
            self.publish_sidebar_invalidation();
            cx.notify();
        }
    }

    fn start_sidebar_folder_drag(&mut self, drag: &SidebarFolderDrag, cx: &mut Context<Self>) {
        self.session_group_tab_removal_active = false;
        if self
            .ui_state
            .sidebar
            .organization
            .folder_scope(&drag.folder_id)
            != Some(drag.scope.clone())
        {
            return;
        }
        self.sidebar_folder_drag_state = Some(SidebarFolderDragState {
            folder_id: drag.folder_id.clone(),
            scope: drag.scope.clone(),
        });
        self.sidebar_organization_drop_target = None;
        self.sidebar_organization_root_drop_target = None;
        cx.notify();
    }

    fn finish_sidebar_folder_drag(&mut self, folder_id: &str, cx: &mut Context<Self>) {
        let valid_drag = self
            .sidebar_folder_drag_state
            .as_ref()
            .is_some_and(|state| state.folder_id == folder_id);
        if !valid_drag {
            return;
        }
        self.sidebar_folder_drag_state = None;
        let moving = [SidebarOrganizationItem::Folder(folder_id.to_string())];
        let _ = self.apply_sidebar_organization_drop(&moving, cx);
        cx.notify();
    }

    fn start_sidebar_group_drag(&mut self, drag: &SidebarGroupDrag, cx: &mut Context<Self>) {
        self.session_group_tab_removal_active = false;
        let Some(scope) = self
            .ui_state
            .sidebar
            .organization
            .group_scope(&drag.group_id)
        else {
            return;
        };
        self.sidebar_group_drag_state = Some(SidebarGroupDragState {
            group_id: drag.group_id.clone(),
            scope,
        });
        cx.notify();
    }

    fn finish_sidebar_group_drag(&mut self, group_id: &str, cx: &mut Context<Self>) {
        let valid_drag = self
            .sidebar_group_drag_state
            .as_ref()
            .is_some_and(|state| state.group_id == group_id);
        if !valid_drag {
            return;
        }
        self.sidebar_group_drag_state = None;
        let moving = [SidebarOrganizationItem::Group(group_id.to_string())];
        let _ = self.apply_sidebar_organization_drop(&moving, cx);
        cx.notify();
    }

    /// Drops dragged sessions into a group.
    ///
    /// A group is single-Worktree, so a drag from another Worktree is refused
    /// with an explicit message rather than silently splitting the group.
    fn finish_sidebar_session_drag_into_group(
        &mut self,
        drag_workspace_id: &str,
        session_ids: &[String],
        group_id: &str,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(group) = self.ui_state.sidebar.organization.group(group_id).cloned() else {
            return;
        };
        self.sidebar_session_drag_state = None;
        if group.workspace_id != drag_workspace_id {
            window.push_notification(
                hint_notification(
                    NotificationType::Error,
                    self.strings().sidebar_group_other_worktree,
                    cx,
                ),
                cx,
            );
            cx.notify();
            return;
        }
        let session_workspaces = self.sidebar_session_workspaces();
        let session_ids = self.dragged_group_session_ids(session_ids);
        if !self.ui_state.sidebar.organization.add_sessions_to_group(
            group_id,
            &session_ids,
            &session_workspaces,
        ) {
            return;
        }
        self.ui_state
            .sidebar
            .organization
            .collapsed_group_ids
            .remove(group_id);
        self.queue_ui_state();
        self.publish_sidebar_invalidation();
        cx.notify();
    }

    /// Adds one session to a group from the session's own menu.
    fn add_session_to_group_from_menu(
        &mut self,
        group_id: &str,
        session_id: &str,
        cx: &mut Context<Self>,
    ) {
        let session_workspaces = self.sidebar_session_workspaces();
        if !self.ui_state.sidebar.organization.add_sessions_to_group(
            group_id,
            std::slice::from_ref(&session_id.to_string()),
            &session_workspaces,
        ) {
            return;
        }
        self.ui_state
            .sidebar
            .organization
            .collapsed_group_ids
            .remove(group_id);
        self.queue_ui_state();
        self.publish_sidebar_invalidation();
        cx.notify();
    }

    /// Removes one session from whatever group holds it.
    fn remove_session_from_group_from_menu(
        &mut self,
        group_id: &str,
        session_id: &str,
        cx: &mut Context<Self>,
    ) {
        if !self
            .ui_state
            .sidebar
            .organization
            .remove_sessions_from_group(group_id, std::slice::from_ref(&session_id.to_string()))
        {
            return;
        }
        self.release_group_session_views(std::slice::from_ref(&session_id.to_string()));
        self.queue_ui_state();
        self.publish_sidebar_invalidation();
        cx.notify();
    }

    fn toggle_sidebar_group(&mut self, group_id: &str, cx: &mut Context<Self>) {
        if self
            .ui_state
            .sidebar
            .organization
            .toggle_group_collapsed(group_id)
            .is_none()
        {
            return;
        }
        self.queue_ui_state();
        self.publish_sidebar_invalidation();
        cx.notify();
    }

    fn begin_sidebar_group_rename(
        &mut self,
        group_id: String,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(name) = self
            .ui_state
            .sidebar
            .organization
            .group(&group_id)
            .map(|group| group.name.clone())
        else {
            return;
        };
        self.retain_sidebar_hover_preview();
        self.sidebar_rename_target = Some(SidebarRenameTarget::Group(group_id));
        self.sidebar_rename_error = None;
        self.sidebar_rename_input.update(cx, |input, cx| {
            input.set_value(name.clone(), window, cx);
            input.set_selected_range(0..name.len(), cx);
            input.focus(window, cx);
        });
        cx.notify();
    }

    fn toggle_session_group_pin(&mut self, group_id: &str, cx: &mut Context<Self>) {
        let pinned = self.ui_state.sidebar.organization.group_is_pinned(group_id);
        if !self
            .ui_state
            .sidebar
            .organization
            .set_group_pinned(group_id, !pinned)
        {
            return;
        }
        self.queue_ui_state();
        self.publish_sidebar_invalidation();
        cx.notify();
    }

    /// Applies a group-level auto continue to every member.
    ///
    /// The runtime loop reads the per-session override, so the group flag fans
    /// out into it; the group flag itself is what the menu renders.
    fn set_session_group_auto_continue(
        &mut self,
        group_id: &str,
        enabled: bool,
        cx: &mut Context<Self>,
    ) {
        let Some(members) = self
            .ui_state
            .sidebar
            .organization
            .group(group_id)
            .map(|group| group.member_session_ids.clone())
        else {
            return;
        };
        if !self
            .ui_state
            .sidebar
            .organization
            .set_group_auto_continue(group_id, Some(enabled))
        {
            return;
        }
        for session_id in members {
            let Ok(session_id) = VibexSessionId::parse(&session_id) else {
                continue;
            };
            self.set_auto_continue_enabled(session_id, enabled, cx);
        }
        self.queue_ui_state();
        self.publish_sidebar_invalidation();
        cx.notify();
    }

    /// Dissolves a group. The member sessions stay authoritative and simply
    /// become ungrouped again.
    fn dissolve_session_group(&mut self, group_id: &str, cx: &mut Context<Self>) {
        let members = self
            .ui_state
            .sidebar
            .organization
            .group(group_id)
            .map(|group| group.member_session_ids.clone())
            .unwrap_or_default();
        if !self.ui_state.sidebar.organization.delete_group(group_id) {
            return;
        }
        self.release_group_session_views(&members);
        self.clear_sidebar_context_menu_target(cx);
        self.queue_ui_state();
        self.publish_sidebar_invalidation();
        cx.notify();
    }

    /// Deletes a group together with every session it holds.
    ///
    /// Session deletion is irreversible, so the dialog names the count rather
    /// than offering an undo the runtime cannot honour.
    fn confirm_delete_session_group(
        &mut self,
        group_id: String,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(members) = self
            .ui_state
            .sidebar
            .organization
            .group(&group_id)
            .map(|group| group.member_session_ids.clone())
        else {
            return;
        };
        if members.is_empty() {
            self.dissolve_session_group(&group_id, cx);
            return;
        }
        let locale = self.resolved_locale();
        let strings = self.strings();
        let entity = cx.weak_entity();
        let count = members.len();
        window.open_dialog(cx, move |dialog, _, _| {
            let entity = entity.clone();
            let group_id = group_id.clone();
            dialog
                .title(sidebar_delete_sessions_title(locale, count))
                .child(sidebar_delete_group_description(locale, count))
                .footer(
                    DialogFooter::new()
                        .child(
                            DialogClose::new().child(
                                Button::new("cancel-group-delete")
                                    .outline()
                                    .label(strings.sidebar_cancel),
                            ),
                        )
                        .child(
                            DialogAction::new().child(
                                Button::new("confirm-group-delete")
                                    .danger()
                                    .label(strings.sidebar_delete),
                            ),
                        ),
                )
                .on_ok(move |_, _, cx| {
                    let _ = entity.update(cx, |this, cx| this.delete_session_group(&group_id, cx));
                    true
                })
        });
    }

    fn delete_session_group(&mut self, group_id: &str, cx: &mut Context<Self>) {
        let Some(members) = self
            .ui_state
            .sidebar
            .organization
            .group(group_id)
            .map(|group| group.member_session_ids.clone())
        else {
            return;
        };
        // The group row goes with its sessions, so the user never sees a group
        // pointing at rows that are already being deleted.
        if self.ui_state.sidebar.organization.delete_group(group_id) {
            self.queue_ui_state();
            self.publish_sidebar_invalidation();
        }
        self.clear_sidebar_context_menu_target(cx);
        let session_ids = members
            .into_iter()
            .filter_map(|session_id| VibexSessionId::parse(&session_id).ok())
            .filter(|session_id| {
                !self
                    .pending_session_deletion_ids
                    .contains(session_id.as_str())
            })
            .collect::<Vec<_>>();
        if session_ids.is_empty() {
            cx.notify();
            return;
        }
        let Some(backend) = self.backend.clone() else {
            cx.notify();
            return;
        };
        let session_id_set = session_ids
            .iter()
            .map(|session_id| session_id.as_str().to_string())
            .collect::<BTreeSet<_>>();
        self.pending_session_deletion_ids
            .extend(session_id_set.iter().cloned());
        self.optimistically_remove_sessions(&session_id_set);
        self.queue_agent_ui_state();
        cx.notify();
        let generation = self.session_generation;
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            let mut first_error = None;
            for session_id in session_ids {
                if let Err(error) = backend
                    .agent()
                    .delete_session(MutationRequest::new(session_id))
                    .await
                    && first_error.is_none()
                {
                    first_error = Some(remote_error_into_vibex(error));
                }
            }
            if let Some(error) = first_error {
                return Err(error);
            }
            Ok::<(), vibex_core::VibexError>(())
        });
        self.finish_optimistic_session_deletion(generation, session_id_set, runner, cx);
    }

    fn move_project_order_relative(
        &mut self,
        moving_ids: &[String],
        target_id: &str,
        after: bool,
        cx: &mut Context<Self>,
    ) {
        let groups = self.sidebar_workspace_groups("");
        let ids = groups
            .iter()
            .map(|group| group.project.id.as_str().to_string())
            .collect::<Vec<_>>();
        complete_string_order(&mut self.ui_state.sidebar.project_order, ids);
        let changed = move_strings_relative(
            &mut self.ui_state.sidebar.project_order,
            moving_ids,
            target_id,
            after,
        );
        if changed {
            self.queue_ui_state();
            self.publish_sidebar_invalidation();
        }
        self.invalidate_sidebar_projection_cache();
        cx.notify();
    }

    fn move_session_order_relative(
        &mut self,
        moving_ids: &[String],
        target_id: &str,
        after: bool,
        cx: &mut Context<Self>,
    ) {
        // Re-snapshot the manual band to the order the user currently sees
        // before applying the move. Appending missing sessions to the tail of
        // a stale band instead would demote the visible top cluster (often
        // the running sessions) to the bottom of the sidebar.
        let original_order = self.sidebar_state.row_order.clone();
        self.sidebar_state.row_order = self
            .ordered_sidebar_session_projects()
            .into_iter()
            .map(|(session_id, _)| session_id)
            .collect::<Vec<_>>();
        let changed = move_strings_relative(
            &mut self.sidebar_state.row_order,
            moving_ids,
            target_id,
            after,
        ) || self.sidebar_state.row_order != original_order;
        if changed {
            self.ui_state.sidebar.session_order_anchored_at_ms = unix_timestamp_ms();
            self.queue_agent_ui_state();
            self.publish_sidebar_invalidation();
        }
        self.invalidate_sidebar_projection_cache();
        cx.notify();
    }

    fn move_new_session_agent_order_relative(
        &mut self,
        moving_id: &str,
        target_id: &str,
        after: bool,
        cx: &mut Context<Self>,
    ) {
        let entries = self
            .agent_snapshots
            .iter()
            .filter(|agent| is_new_session_agent_available(agent))
            .map(|agent| AgentOrderEntry {
                id: agent.id.as_str().to_string(),
                label: agent.label.clone(),
            })
            .collect::<Vec<_>>();
        // Complete against the order the user currently sees so a single drag
        // keeps the relative position of every other agent.
        let visible_ids = ordered_agent_ids(&entries, &self.agent_ordering());
        complete_string_order(&mut self.ui_state.agent_tab_order, visible_ids);
        if move_string_relative(
            &mut self.ui_state.agent_tab_order,
            moving_id,
            target_id,
            after,
        ) {
            self.queue_ui_state();
        }
        self.sync_management_agent_ordering(cx);
        cx.notify();
    }

    /// Ordering inputs shared by the new-session Agent selector and the
    /// Management Center Agent sidebar.
    fn agent_ordering(&self) -> AgentOrdering {
        AgentOrdering::new(
            self.ui_state.agent_sort_strategy,
            self.ui_state.agent_tab_order.clone(),
        )
        .with_usage_counts(self.agent_usage_counts())
    }

    /// Enabled Agents in the shared ordering, consumed by the new-session home
    /// selector and the provider/model Agent row.
    fn runtime_agent_choices(&self) -> Vec<AgentSnapshotEntry> {
        ordered_runtime_agent_choices(&self.agent_snapshots, &self.agent_ordering())
    }

    fn agent_usage_counts(&self) -> BTreeMap<String, u64> {
        let mut counts = BTreeMap::new();
        for session in &self.sessions {
            if session.deleted_at_ms.is_some() {
                continue;
            }
            *counts
                .entry(session.agent_id.as_str().to_string())
                .or_insert(0) += 1;
        }
        counts
    }

    fn set_agent_sort_strategy(&mut self, strategy: AgentSortStrategy, cx: &mut Context<Self>) {
        self.ui_state.agent_sort_strategy = strategy;
        self.ui_state.agent_tab_order.clear();
        self.queue_ui_state();
        self.sync_management_agent_ordering(cx);
        cx.notify();
    }

    fn sync_management_agent_ordering(&mut self, cx: &mut Context<Self>) {
        let ordering = self.agent_ordering();
        self.management_view.update(cx, |management, cx| {
            management.set_agent_ordering(ordering, cx)
        });
    }

    /// Makes `session_id`'s view the borrowed one.
    ///
    /// Every session that is on screen owns a persistent entry in
    /// [`Self::session_views`]. Borrowing moves that entry into `self.view` and
    /// puts the previously borrowed entry back where it came from, so a view is
    /// never copied, merged or dropped by a switch: it is the same allocation
    /// before and after. That is what makes several panes independent — the
    /// state of a pane that is not being rendered simply stays in the store.
    ///
    /// Returns whether the session already had a view. A `false` answer means
    /// the caller is looking at a fresh, still-empty view and should load one.
    fn borrow_session_view(&mut self, session_id: &VibexSessionId) -> bool {
        self.borrow_session_view_weighed(session_id, true)
    }

    /// Borrows a view for work that runs outside the render pass, cheaply.
    ///
    /// Layout and prepaint run after the render pass handed every pane's view
    /// back, so a pane that renders a row there has to borrow its own view
    /// again. That swap happens many times per frame, and re-weighing either
    /// side of it would walk a whole timeline each time for a number the render
    /// pass refreshes anyway. The entry keeps the footprint it was last stored
    /// with; only the map move and the LRU touch are paid here.
    fn borrow_session_view_unweighed(&mut self, session_id: &VibexSessionId) -> bool {
        self.borrow_session_view_weighed(session_id, false)
    }

    fn borrow_session_view_weighed(&mut self, session_id: &VibexSessionId, weigh: bool) -> bool {
        if self.view_session_id.as_ref() == Some(session_id) {
            return self.timeline.session_id.as_ref() == Some(session_id);
        }
        let key = session_id.as_str().to_string();
        let previous_key = self.view_session_id.take();
        let previous = std::mem::replace(
            &mut self.view,
            SessionView::new(self.ui_state.session.content_width),
        );
        if let Some(previous_key) = previous_key {
            let previous_key = previous_key.as_str().to_string();
            if weigh {
                self.store_session_view(previous_key, previous);
            } else {
                self.insert_session_view(previous_key, previous);
            }
        }
        self.view_session_id = Some(session_id.clone());
        match self.session_views.remove(&key) {
            Some(entry) => {
                self.session_view_lru.retain(|cached| cached != &key);
                self.view = entry;
                self.timeline.session_id.as_ref() == Some(session_id)
            }
            None => false,
        }
    }

    /// The session whose view is currently borrowed.
    ///
    /// The composer renders for the borrowed view, so a group pane composes for
    /// its own session while the sidebar keeps its selection.
    fn view_session(&self) -> Option<&AgentSession> {
        let session_id = self.view_session_id.as_ref()?;
        self.sessions
            .iter()
            .find(|session| &session.id == session_id)
    }

    /// Borrows `session_id`'s view for an input event.
    ///
    /// Returns whether the borrowed view changed, so the caller can hand it
    /// back. A keystroke must be handled against the session that owns the
    /// textarea, not against whichever session the sidebar happens to show.
    fn focus_view_for_input(&mut self, session_id: &VibexSessionId) -> bool {
        if self.view_session_id.as_ref() == Some(session_id) {
            return false;
        }
        let _ = self.borrow_session_view(session_id);
        true
    }

    /// The Agent a session's row should show, from that session's own view.
    ///
    /// A view that is borrowed for rendering is not in the store, so reading
    /// only the store made the row of a pane that lost focus fall back to the
    /// session's original Agent and drop the one the user had picked.
    fn session_desired_agent_id(&self, session_id: &str) -> Option<&AgentId> {
        if self.view_session_id.as_ref().map(VibexSessionId::as_str) == Some(session_id) {
            return self
                .runtime_selection
                .as_ref()
                .map(|state| &state.desired.agent_id);
        }
        self.session_views
            .get(session_id)
            .and_then(|view| view.runtime_selection.as_ref())
            .map(|state| &state.desired.agent_id)
    }

    /// The borrowed view's composer textarea, if it has one yet.
    fn composer_input_entity(&self) -> Option<Entity<TextareaState>> {
        self.composer_input.clone()
    }

    /// The borrowed view's composer textarea, created and wired on first use.
    ///
    /// Every session owns its own textarea, so a pane's draft, cursor and IME
    /// state belong to that session alone. That is what lets a pane render the
    /// same composer as the main workbench without typing into it.
    fn ensure_composer_input(
        &mut self,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> Entity<TextareaState> {
        if let Some(input) = self.composer_input.as_ref() {
            return input.clone();
        }
        let placeholder = self.strings().message_agent;
        let input = cx.new(|cx| {
            TextareaState::new(window, cx)
                .auto_grow(2, 8)
                .submit_on_enter(true)
                .placeholder(placeholder)
        });
        let session_id = self.view_session_id.clone();
        self.composer_subscription = Some(subscribe_composer_input(&input, session_id, window, cx));
        self.composer_input = Some(input.clone());
        input
    }

    /// Whether `session_id` already owns a view, borrowed or stored.
    fn session_view_exists(&self, session_id: &VibexSessionId) -> bool {
        self.view_session_id.as_ref() == Some(session_id)
            || self.session_views.contains_key(session_id.as_str())
    }

    /// The authoritative end sequence of a session's view, whichever view is
    /// currently borrowed.
    fn session_view_end_sequence(&self, session_id: &VibexSessionId) -> Option<i64> {
        if self.view_session_id.as_ref() == Some(session_id) {
            return self.timeline.authoritative_end_sequence;
        }
        self.session_views
            .get(session_id.as_str())
            .and_then(|view| view.timeline.authoritative_end_sequence)
    }

    /// Makes sure `session_id` has a view, without caring whether it is the one
    /// currently borrowed.
    ///
    /// A group pane calls this before it renders: the pane owns its session's
    /// view for the whole time the session is a member, whether or not the
    /// session is the one the sidebar selected.
    fn ensure_session_view(&mut self, session_id: &VibexSessionId) -> bool {
        if self.view_session_id.as_ref() == Some(session_id) {
            return true;
        }
        // Look the key up borrowed: this runs for every group member on every
        // frame, and only a view that is actually missing needs an owned key.
        if self.session_views.contains_key(session_id.as_str()) {
            return true;
        }
        self.store_session_view(
            session_id.as_str().to_string(),
            SessionView::new(self.ui_state.session.content_width),
        );
        false
    }

    /// Stores a view under its session id, bounded by the shared view budget.
    ///
    /// Group members are pinned, so a pane never loses the conversation it is
    /// showing to an unrelated session's memory pressure.
    fn store_session_view(&mut self, key: String, mut entry: SessionView) {
        // Refresh this entry's footprint once, on the way in. Everything already
        // in the store is frozen (a cached view is not mutated), so the eviction
        // pass can sum these numbers instead of re-walking every stored view's
        // timeline on every borrow/release — which a split paid twice per pane,
        // per frame.
        entry.resident_bytes = entry
            .calculate_estimated_resident_bytes()
            .saturating_mul(AGENT_SESSION_VIEW_ALLOCATION_OVERHEAD)
            / 2;
        let stored_bytes = self
            .session_views
            .values()
            .map(|view| view.resident_bytes)
            .fold(0_usize, usize::saturating_add);
        // Building the pinned set walks every grouped session. It is only read
        // when the store actually has to evict, so a store that cannot evict
        // must not pay for it.
        let may_evict = self.session_views.len() >= AGENT_SESSION_VIEW_CACHE_LIMIT
            || stored_bytes.saturating_add(entry.resident_bytes) > AGENT_SESSION_VIEW_CACHE_BYTES;
        let pinned = if may_evict {
            self.pinned_session_view_ids()
        } else {
            BTreeSet::new()
        };
        insert_bounded_session_view_with_pins(
            &mut self.session_views,
            &mut self.session_view_lru,
            key,
            entry,
            SessionViewBudget {
                limit: AGENT_SESSION_VIEW_CACHE_LIMIT,
                max_bytes: AGENT_SESSION_VIEW_CACHE_BYTES,
            },
            |entry| entry.resident_bytes,
            &pinned,
        );
    }

    /// Puts a view back into the store under its session id, keeping the
    /// footprint it was last weighed at.
    ///
    /// The transient borrows layout and prepaint make to render a pane against
    /// its own view come through here, and they run once per rendered row, so
    /// this path must not re-walk a timeline, sum every stored footprint or
    /// build the pinned set. The budget stays enforced by
    /// [`Self::store_session_view`], which is what the render pass hands every
    /// pane's view back through.
    fn insert_session_view(&mut self, key: String, entry: SessionView) {
        self.session_views.remove(&key);
        self.session_view_lru.retain(|cached| cached != &key);
        if AGENT_SESSION_VIEW_CACHE_LIMIT == 0
            || entry.resident_bytes > AGENT_SESSION_VIEW_CACHE_BYTES
        {
            return;
        }
        self.session_views.insert(key.clone(), entry);
        touch_session_view_lru(&mut self.session_view_lru, &key);
    }

    /// Sessions whose view must survive eviction: the selected session and
    /// every session a group workspace is currently showing.
    fn pinned_session_view_ids(&self) -> BTreeSet<String> {
        let mut pinned = BTreeSet::new();
        if let Some(selected) = self.selected_session_id.as_ref() {
            pinned.insert(selected.as_str().to_string());
        }
        if let Some(live) = self.view_session_id.as_ref() {
            pinned.insert(live.as_str().to_string());
        }
        pinned.extend(self.ui_state.sidebar.organization.grouped_session_ids());
        pinned
    }

    /// Drops a session's stored view. The borrowed view is left alone; callers
    /// that need it gone borrow another session first.
    fn forget_session_view(&mut self, session_id: &str) {
        self.session_views.remove(session_id);
        self.session_view_lru.retain(|cached| cached != session_id);
    }

    /// Borrows `session_id`'s view, runs `body`, and hands the view back.
    ///
    /// This is the only way render code may touch another session's view. The
    /// closure receives `&mut Self` with the target view borrowed, so it can use
    /// the ordinary `self.timeline` / `self.conversation_turns_cache` accesses.
    fn with_session_view<R>(
        &mut self,
        session_id: &VibexSessionId,
        body: impl FnOnce(&mut Self) -> R,
    ) -> R {
        let had_view = self.borrow_session_view(session_id);
        if !had_view && self.timeline.session_id.is_none() {
            // A view with no timeline yet still has to be the borrowed one while
            // the body runs, so a pane can render its loading state.
            self.timeline.session_id = Some(session_id.clone());
        }
        let outcome = body(self);
        self.release_session_view();
        outcome
    }

    /// Borrows `session_id`'s view for work that runs after the render pass.
    ///
    /// A session group builds its panes during the render pass but lays them
    /// out and paints them afterwards, when the borrowed view already belongs
    /// to the focused pane. Every row a pane paints there — its payloads, its
    /// expansion state, its measured heights — would otherwise be resolved
    /// against the focused session's view, which froze a working pane's
    /// timeline and left blank bands in it. The same holds for an input event
    /// that reaches a pane the keyboard does not: a wheel event clears the
    /// follow state of the pane under the pointer, not of the focused one.
    ///
    /// This borrow makes the pane's own view current for the duration of
    /// `body`, and hands the primary back afterwards so the invariant
    /// [`Self::release_session_view`] protects still holds for whatever runs
    /// next.
    ///
    /// A view that is missing is deliberately left without a session id: naming
    /// its session there would mark it loaded, and the pane loader skips a view
    /// whose timeline is already named, so it would never fetch one.
    ///
    /// The swap is unweighed: it happens once per rendered row, and the render
    /// pass already weighs a view when it hands it back.
    fn with_session_view_for_render<R>(
        &mut self,
        session_id: Option<&VibexSessionId>,
        body: impl FnOnce(&mut Self) -> R,
    ) -> R {
        let Some(session_id) = session_id else {
            // No session to route by means the borrowed view is the only
            // candidate left.
            return body(self);
        };
        let _ = self.borrow_session_view_unweighed(session_id);
        let outcome = body(self);
        self.release_session_view_unweighed();
        outcome
    }

    /// Hands the borrowed view back to the store and re-borrows the session the
    /// primary workbench renders.
    ///
    /// The primary workbench must always find the selected session's view
    /// borrowed, because every non-pane code path reads `self.timeline` as "the
    /// selected session's timeline".
    fn release_session_view(&mut self) {
        self.release_session_view_weighed(true)
    }

    /// Hands back a view borrowed for layout or prepaint, without re-weighing
    /// either side of the swap.
    fn release_session_view_unweighed(&mut self) {
        self.release_session_view_weighed(false)
    }

    fn release_session_view_weighed(&mut self, weigh: bool) {
        let primary = self.selected_session_id.clone();
        match primary {
            Some(primary) => {
                if weigh {
                    let _ = self.borrow_session_view(&primary);
                } else {
                    let _ = self.borrow_session_view_unweighed(&primary);
                }
            }
            None => {
                if let Some(previous_key) = self.view_session_id.take() {
                    let previous = std::mem::replace(
                        &mut self.view,
                        SessionView::new(self.ui_state.session.content_width),
                    );
                    let previous_key = previous_key.as_str().to_string();
                    if weigh {
                        self.store_session_view(previous_key, previous);
                    } else {
                        self.insert_session_view(previous_key, previous);
                    }
                }
            }
        }
    }

    /// Applies a newly loaded authoritative timeline to a session's view,
    /// whether or not that view is the borrowed one.
    fn adopt_session_view_timeline(
        &mut self,
        session_id: VibexSessionId,
        items: Vec<vibex_core::TimelineItem>,
    ) {
        let _ = self.ensure_session_view(&session_id);
        self.with_session_view(&session_id, |this| {
            let content_changed = this.timeline.session_id.as_ref() != Some(&session_id)
                || this.timeline.items != items;
            if content_changed {
                this.view.invalidate_render_caches();
            }
            reset_pending_user_requests(&mut this.pending_user_request_ids, &session_id, &items);
            this.timeline
                .replace_authoritative(session_id.clone(), items);
            this.agent_loading = false;
            this.reconcile_optimistic_user_message();
            this.rebuild_timeline_sizes();
        });
    }

    /// Re-derives the geometry of the borrowed view after it changed shape.
    ///
    /// A view that was measured against another width (or another content width
    /// setting) has to re-estimate its rows, otherwise a pane that just joined a
    /// split would paint the previous layout's row heights.
    fn refresh_borrowed_view_geometry(&mut self) {
        let cached_timeline_layout_width = self.timeline_layout_width;
        let layout_width_changed =
            timeline_layout_width_changed(self.timeline_layout_width, cached_timeline_layout_width);
        let content_width_changed = self.view.content_width != self.ui_state.session.content_width;
        self.view.content_width = self.ui_state.session.content_width;
        let turns_cache_changed = self.conversation_turns_cache_key.as_ref()
            != Some(&self.current_conversation_turns_cache_key());
        let geometry_changed = layout_width_changed || content_width_changed;
        if geometry_changed {
            self.invalidate_timeline_layout_measurements();
        }
        if geometry_changed || turns_cache_changed {
            self.rebuild_timeline_sizes();
        }
        // The streaming preserve policy keeps the largest measured extent while
        // an in-flight turn keeps the same layout signature and body length.
        // That extent can outlive the transient layout it captured, so a
        // switched-to session would keep a blank band under its last row until
        // the turn reshaped. Drop the measurement so the first paint re-measures
        // the freshly rendered content instead of preserving it.
        let streaming_last_turn_id = self.conversation_turns_cache.last().and_then(|turn| {
            self.streaming_timeline_row_state(turn)
                .map(|_| turn.id.clone())
        });
        if let Some(turn_id) = streaming_last_turn_id {
            self.invalidate_timeline_turn_measurement(&turn_id);
            self.timeline_estimated_turn_heights.remove(&turn_id);
            self.rebuild_timeline_sizes();
        }
        // A reader who was not following the bottom gets the anchored row back
        // under the viewport once the render has rebuilt the row table.
        self.timeline_scroll_anchor_pending =
            !self.timeline_follow.following_bottom && self.timeline_follow.anchor_row_id.is_some();
    }

    fn refresh_agent_token_usage(
        &mut self,
        session_id: &VibexSessionId,
        cx: &mut Context<Self>,
    ) -> bool {
        if self.selected_session_id.as_ref() != Some(session_id) {
            return false;
        }
        let Some(runtime) = self.runtime.clone() else {
            // A paired runtime serves the same snapshot over Remote v2. The
            // read is asynchronous, so the indicator updates when it lands
            // instead of reporting an immediate change.
            self.request_remote_token_usage(session_id.clone(), cx);
            return false;
        };
        // Every streamed chunk publishes an attachment update, and a cold
        // binding resolves the snapshot by opening and migrating the database.
        // The read therefore runs on the background executor — the UI thread
        // only sees the finished value — and a session only ever has one read
        // in flight.
        let tracked_session_id = session_id.clone();
        if !self
            .token_usage_reads_in_flight
            .insert(tracked_session_id.clone())
        {
            return false;
        }
        let request_session_id = tracked_session_id.clone();
        cx.spawn(
            async move |this: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                let usage = cx
                    .background_spawn(async move {
                        runtime_token_usage_snapshot(&runtime, &request_session_id)
                            .ok()
                            .flatten()
                    })
                    .await;
                let _ = this.update(cx, |this, cx| {
                    this.token_usage_reads_in_flight.remove(&tracked_session_id);
                    if this.selected_session_id.as_ref() != Some(&tracked_session_id) {
                        return;
                    }
                    if this.token_usage == usage {
                        return;
                    }
                    this.token_usage = usage;
                    cx.notify();
                });
            },
        )
        .detach();
        false
    }

    /// Reads the live token snapshot from the paired runtime. Only one request
    /// per session is in flight so a burst of runtime events cannot queue
    /// duplicate RPCs.
    fn request_remote_token_usage(&mut self, session_id: VibexSessionId, cx: &mut Context<Self>) {
        if self.remote_token_usage_in_flight.as_ref() == Some(&session_id) {
            return;
        }
        let Some(backend) = self.backend.clone() else {
            return;
        };
        self.remote_token_usage_in_flight = Some(session_id.clone());
        let request_session_id = session_id.clone();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            backend
                .agent()
                .session_token_usage(request_session_id)
                .await
        });
        self.remote_token_usage_task = Some(cx.spawn(async move |entity: WeakEntity<Self>, cx| {
            let outcome = runner.await;
            let _ = entity.update(cx, |this, cx| {
                this.remote_token_usage_task = None;
                if this.remote_token_usage_in_flight.as_ref() == Some(&session_id) {
                    this.remote_token_usage_in_flight = None;
                }
                let Ok(Ok(usage)) = outcome else {
                    return;
                };
                if this.selected_session_id.as_ref() != Some(&session_id) {
                    return;
                }
                if this.token_usage != usage {
                    this.token_usage = usage;
                    cx.notify();
                }
            });
        }));
    }

    fn sync_agent_generation_stats(&mut self, turn: &TimelineConversationTurn) {
        let now = Instant::now();
        let output_tokens = self
            .token_usage
            .as_ref()
            .and_then(|usage| usage.output_tokens);
        let should_reset = self
            .agent_generation_stats
            .as_ref()
            .is_none_or(|stats| stats.turn_id != turn.id);
        if should_reset {
            let compaction_count = agent_generation_compaction_count(turn, &self.timeline.items);
            self.agent_generation_stats = Some(AgentGenerationStats::new(
                turn.id.clone(),
                turn.started_at_ms,
                output_tokens,
                compaction_count,
            ));
        }

        let refreshed_compaction_count = self
            .agent_generation_stats
            .as_ref()
            .filter(|stats| stats.turn_id == turn.id)
            .and_then(|stats| {
                stats
                    .compaction_count
                    .is_none()
                    .then(|| agent_generation_compaction_count(turn, &self.timeline.items))
            });

        let Some(stats) = self.agent_generation_stats.as_mut() else {
            return;
        };
        if let Some(compaction_count) = refreshed_compaction_count {
            stats.compaction_count = Some(compaction_count);
        }
        let reported_tokens = match (output_tokens, stats.output_token_baseline) {
            (Some(current), Some(baseline)) => {
                current.checked_sub(baseline).filter(|tokens| *tokens > 0)
            }
            (Some(current), None) if current > 0 => Some(current),
            _ => None,
        };
        let generated_tokens = if let Some(reported_tokens) = reported_tokens {
            Some(reported_tokens)
        } else {
            let estimated_output_chars = stats
                .estimated_output_chars
                .get_or_insert_with(|| estimated_agent_output_chars(turn).unwrap_or_default());
            (*estimated_output_chars > 0)
                .then_some((*estimated_output_chars as u64).saturating_add(3) / 4)
        };
        if generated_tokens == stats.last_generated_tokens {
            return;
        }
        if let Some(rate) = agent_generation_token_rate(
            stats.last_generated_tokens,
            generated_tokens,
            now.saturating_duration_since(stats.last_token_sample_at),
        ) {
            stats.tokens_per_second = Some(rate);
        }
        stats.last_generated_tokens = generated_tokens;
        stats.last_token_sample_at = now;
    }

    fn record_agent_generation_streaming_delta(&mut self, update: &AgentStreamingCacheUpdate) {
        let Some(stats) = self.agent_generation_stats.as_mut() else {
            return;
        };
        if stats.turn_id != update.turn_id {
            return;
        }
        if let Some(estimated_output_chars) = stats.estimated_output_chars.as_mut() {
            *estimated_output_chars =
                estimated_output_chars.saturating_add(update.output_char_delta);
        }
    }

    fn invalidate_agent_generation_output_estimate(&mut self) {
        if let Some(stats) = self.agent_generation_stats.as_mut() {
            stats.estimated_output_chars = None;
        }
    }

    fn invalidate_agent_generation_compaction_count(&mut self) {
        if let Some(stats) = self.agent_generation_stats.as_mut() {
            stats.compaction_count = None;
        }
    }

    fn render_agent_generation_status(
        &mut self,
        session_running: bool,
        cx: &mut Context<Self>,
    ) -> Option<AnyElement> {
        if !self.ui_state.session.show_agent_generation_status {
            self.agent_generation_stats = None;
            return None;
        }
        if !session_running {
            self.agent_generation_stats = None;
            return None;
        }
        let Some(turn) = self
            .conversation_turns_cache
            .iter()
            .rev()
            .find(|turn| !timeline_turn_finished(turn))
            .cloned()
        else {
            self.agent_generation_stats = None;
            return None;
        };
        self.sync_agent_generation_stats(&turn);
        let (started_at_ms, tokens_per_second) = self
            .agent_generation_stats
            .as_ref()
            .map(|stats| (stats.started_at_ms, stats.tokens_per_second))?;
        let locale = self.resolved_locale();
        let phase = agent_generation_phase(&turn);
        let phase_label = agent_generation_phase_label(phase, locale);
        let duration = format_compact_duration(started_at_ms, None);
        let tool_count = agent_generation_tool_call_count(&turn);
        let compaction_count = self
            .agent_generation_stats
            .as_ref()
            .and_then(|stats| stats.compaction_count)
            .unwrap_or_default();
        let mut file_changes = self.agent_turn_file_changes_cached(&turn).as_ref().clone();
        if let Some(session) = self.view_session().cloned()
            && let Some(status) = self.code_workbench.read(cx).git_status()
            && status.workspace_id == session.workspace_id
        {
            apply_git_status_to_turn_file_changes(&mut file_changes, status);
        }
        let (added_lines, removed_lines) =
            turn_file_changes_line_counts(&file_changes).unwrap_or_default();
        let agent_id = self
            .view_runtime_selection()
            .map(|selection| selection.agent_id)
            .or_else(|| self.view_session().map(|session| session.agent_id.clone()))?;
        let agent_label = runtime_agent_label(&self.agent_snapshots, &agent_id);
        let agent_identity = self
            .agent_snapshots
            .iter()
            .find(|agent| agent.id == agent_id)
            .map(agent_brand_identity)
            .unwrap_or_else(|| agent_id.to_string());
        let muted_foreground = cx.theme().muted_foreground;
        let separator = || {
            div()
                .flex_none()
                .text_color(muted_foreground.opacity(0.72))
                .child("·")
        };
        let tool_label = match locale {
            locale::ResolvedLocale::En => format!("{tool_count} tool calls"),
            locale::ResolvedLocale::ZhCn => format!("{tool_count} 次工具调用"),
            locale::ResolvedLocale::ZhTw => format!("{tool_count} 次工具呼叫"),
        };
        let compaction_label = match locale {
            locale::ResolvedLocale::En => format!(
                "{compaction_count} {}",
                if compaction_count == 1 {
                    "compaction"
                } else {
                    "compactions"
                }
            ),
            locale::ResolvedLocale::ZhCn => format!("{compaction_count} 次压缩"),
            locale::ResolvedLocale::ZhTw => format!("{compaction_count} 次壓縮"),
        };
        let tokens_per_second = tokens_per_second.map(|speed| format!("{speed:.1} t/s"));
        let (input_tokens, output_tokens, cache_rate) = self.agent_token_usage_metrics();
        Some(
            h_flex()
                .id("agent-generation-status")
                .w_full()
                .h(px(24.0))
                .flex_none()
                .items_center()
                .justify_center()
                .gap(px(6.0))
                .text_xs()
                .text_color(muted_foreground)
                .child(
                    div()
                        .id(SharedString::from(format!(
                            "agent-generation-logo:{}",
                            turn.id
                        )))
                        .size(px(16.0))
                        .flex_none()
                        .child(runtime_agent_icon(&agent_identity))
                        .tooltip(move |window, cx| {
                            Tooltip::new(agent_label.clone()).build(window, cx)
                        }),
                )
                .child(phase_label)
                .child(separator())
                .child(duration)
                .when(tool_count > 0, |this| {
                    this.child(separator()).child(tool_label)
                })
                .when(added_lines > 0 || removed_lines > 0, |this| {
                    this.child(separator())
                        .when(added_lines > 0, |this| {
                            this.child(
                                div()
                                    .text_color(cx.theme().success)
                                    .child(format!("+{added_lines}")),
                            )
                        })
                        .when(removed_lines > 0, |this| {
                            this.child(
                                div()
                                    .text_color(cx.theme().danger)
                                    .child(format!("-{removed_lines}")),
                            )
                        })
                })
                .when(compaction_count > 0, |this| {
                    this.child(separator()).child(compaction_label)
                })
                .when_some(input_tokens, |this, tokens| {
                    this.child(separator()).child(
                        h_flex()
                            .items_center()
                            .gap(px(2.0))
                            .child(Icon::new(IconName::ArrowUp).size(px(12.0)))
                            .child(format_compact_tokens(tokens)),
                    )
                })
                .when_some(output_tokens, |this, tokens| {
                    this.child(separator()).child(
                        h_flex()
                            .items_center()
                            .gap(px(2.0))
                            .child(Icon::new(IconName::ArrowDown).size(px(12.0)))
                            .child(format_compact_tokens(tokens)),
                    )
                })
                .when_some(cache_rate, |this, rate| {
                    this.child(separator()).child(format!("{rate}%"))
                })
                .when_some(tokens_per_second, |this, speed| {
                    this.child(separator()).child(speed)
                })
                .into_any_element(),
        )
    }

    fn agent_token_usage_metrics(&self) -> (Option<u64>, Option<u64>, Option<u32>) {
        let usage = self.token_usage.as_ref();
        let input_tokens = usage.and_then(|usage| usage.input_tokens);
        let output_tokens = usage.and_then(|usage| usage.output_tokens);
        let cache_rate = usage.and_then(cache_hit_fraction).map(token_usage_percent);
        (input_tokens, output_tokens, cache_rate)
    }

    /// The cascade projection for `selection`, rebuilt only when the catalog or
    /// the selection it describes actually changed.
    ///
    /// A session group renders a composer per pane, and every pane whose session
    /// shares a selection wants the same projection. Deriving it allocates a
    /// label for every choice in the catalog, so it is worth sharing.
    ///
    /// The memo holds one entry per distinct selection a split is showing. A
    /// single slot thrashed as soon as two panes selected different runtimes:
    /// each pane replaced the other's entry and every pane rebuilt the whole
    /// projection on every frame.
    fn runtime_cascade_projection_for(
        &mut self,
        catalog: &Rc<SessionRuntimeOptionCatalog>,
        selection: &SessionRuntimeSelection,
    ) -> Rc<RuntimeCascadeProjection> {
        if let Some(index) = self.runtime_cascade_projection.iter().position(
            |(cached_catalog, cached_selection, _)| {
                Rc::ptr_eq(cached_catalog, catalog) && cached_selection == selection
            },
        ) {
            let entry = self.runtime_cascade_projection.remove(index);
            let projection = entry.2.clone();
            self.runtime_cascade_projection.push(entry);
            return projection;
        }
        let projection = Rc::new(RuntimeCascadeProjection::from_catalog(catalog, selection));
        self.runtime_cascade_projection.push((
            catalog.clone(),
            selection.clone(),
            projection.clone(),
        ));
        if self.runtime_cascade_projection.len() > RUNTIME_CASCADE_PROJECTION_MEMO_LIMIT {
            self.runtime_cascade_projection.remove(0);
        }
        projection
    }

    fn selected_runtime_selection(&self) -> Option<SessionRuntimeSelection> {
        let session_id = self.selected_session_id.clone()?;
        self.runtime_selection_for_session(&session_id)
    }

    /// The runtime selection the borrowed view renders.
    ///
    /// A group pane renders its own session's runtime controls while the
    /// sidebar still selects the focused pane's session, so the lookup has to
    /// follow the borrowed view rather than the selection.
    fn view_runtime_selection(&self) -> Option<SessionRuntimeSelection> {
        let session_id = self.view_session_id.clone()?;
        self.runtime_selection_for_session(&session_id)
    }

    /// The runtime selection a session renders, selected or not.
    fn runtime_selection_for_session(
        &self,
        session_id: &VibexSessionId,
    ) -> Option<SessionRuntimeSelection> {
        self.optimistic_runtime_selections
            .get(session_id.as_str())
            .cloned()
            .or_else(|| {
                // The live selection lives in the view that owns the session:
                // the borrowed one for the session being rendered, the stored
                // one otherwise. Reading the borrowed view for any other
                // session would hand a pane the focused pane's Agent.
                if self.view_session_id.as_ref() == Some(session_id) {
                    self.runtime_selection
                        .as_ref()
                        .map(|state| state.desired.clone())
                } else {
                    self.session_views
                        .get(session_id.as_str())
                        .and_then(|view| view.runtime_selection.as_ref())
                        .map(|state| state.desired.clone())
                }
            })
            .or_else(|| {
                // Imported sessions predate runtime selection state. They are
                // still usable: synthesize a choice from the catalog so the
                // composer renders the cascade and sending initializes the
                // session with the displayed selection.
                if self
                    .runtime_selection_uninitialized_sessions
                    .contains(session_id.as_str())
                {
                    self.fallback_runtime_selection_for(session_id)
                } else {
                    None
                }
            })
    }

    fn selected_session_runtime_uninitialized(&self) -> bool {
        self.selected_session_id.as_ref().is_some_and(|session_id| {
            self.runtime_selection_uninitialized_sessions
                .contains(session_id.as_str())
        })
    }

    fn fallback_runtime_selection_for(
        &self,
        session_id: &VibexSessionId,
    ) -> Option<SessionRuntimeSelection> {
        let session = self
            .sessions
            .iter()
            .find(|session| &session.id == session_id)?;
        let agent_id = session.agent_id.clone();
        let catalog = self.runtime_catalog.as_ref()?;
        if let Some(selection) = self
            .ui_state
            .composer
            .runtime_selections_by_agent
            .get(&agent_id)
            .cloned()
            .filter(|selection| {
                catalog.options.iter().any(|option| {
                    option.selection.agent_id == selection.agent_id
                        && option.selection.auth_source == selection.auth_source
                        && option.selection.model == selection.model
                })
            })
        {
            return Some(selection);
        }
        catalog
            .options
            .iter()
            .find(|option| option.selection.agent_id == agent_id)
            .map(|option| option.selection.clone())
    }

    fn active_runtime_controls_pending(&self) -> bool {
        runtime_selection_cancellation_is_pending(
            self.selected_session_id.as_ref(),
            &self.runtime_selection_cancellations_in_flight,
        )
    }

    fn install_optimistic_user_message(&mut self, message: OptimisticUserMessage) {
        let session_id = message.session_id.clone();
        self.optimistic_user_messages
            .insert(session_id.as_str().to_string(), message);
        if self.selected_session_id.as_ref() == Some(&session_id) {
            self.invalidate_timeline_render_caches();
            self.rebuild_timeline_sizes();
            self.request_timeline_scroll_to_latest();
        }
    }

    fn discard_optimistic_user_message(&mut self, session_id: &VibexSessionId) -> bool {
        if self
            .optimistic_user_messages
            .remove(session_id.as_str())
            .is_none()
        {
            return false;
        }
        if self.selected_session_id.as_ref() == Some(session_id) {
            self.invalidate_timeline_render_caches();
            self.rebuild_timeline_sizes();
        }
        true
    }

    fn reconcile_optimistic_user_message(&mut self) -> bool {
        let Some(session_id) = self.selected_session_id.clone() else {
            return false;
        };
        let confirmed = self
            .optimistic_user_messages
            .get(session_id.as_str())
            .is_some_and(|message| message.is_confirmed_by(&self.timeline));
        if !confirmed {
            return false;
        }
        self.optimistic_user_messages.remove(session_id.as_str());
        self.invalidate_timeline_render_caches();
        true
    }

    fn optimistic_user_message_attachments_for_row(
        &self,
        row: &TimelineRow,
    ) -> Option<Vec<MessageAttachment>> {
        let session_id = self.selected_session_id.as_ref()?;
        let message = self.optimistic_user_messages.get(session_id.as_str())?;
        row.item_ids
            .iter()
            .any(|item_id| item_id == message.item_id.as_str())
            .then(|| message.attachments.clone())
    }

    fn apply_runtime_selection_state(
        &mut self,
        session_id: &VibexSessionId,
        state: AgentSessionRuntimeSelectionState,
        cx: &mut Context<Self>,
    ) -> bool {
        let selected = self.selected_session_id.as_ref() == Some(session_id);
        let changed = if selected {
            if self.runtime_selection.as_ref() == Some(&state) {
                false
            } else {
                self.runtime_selection = Some(state.clone());
                self.refresh_active_suggestions(ComposerTarget::Session, cx);
                true
            }
        } else if self.session_view_exists(session_id) {
            self.with_session_view(session_id, |this| {
                let changed = this.runtime_selection.as_ref() != Some(&state);
                this.runtime_selection = Some(state.clone());
                changed
            })
        } else {
            false
        };
        self.reconcile_optimistic_runtime_selection(session_id, &state, cx);
        if state.status == SessionRuntimeSelectionStatus::Ready {
            self.maybe_probe_native_steering(session_id, state.activation_generation, cx);
        }
        changed
    }

    /// Probes the session's live runtime for native steering support once per
    /// activation generation. The queue uses the cached answer to decide
    /// whether to expose the native steer action.
    fn maybe_probe_native_steering(
        &mut self,
        session_id: &VibexSessionId,
        activation_generation: i64,
        cx: &mut Context<Self>,
    ) {
        let session_key = session_id.as_str().to_string();
        if self
            .native_steering_probed_generations
            .get(&session_key)
            .is_some_and(|probed| *probed == activation_generation)
        {
            return;
        }
        let Some(backend) = self.backend.clone() else {
            return;
        };
        self.native_steering_probed_generations
            .insert(session_key.clone(), activation_generation);
        let probe_session_id = session_id.clone();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            backend
                .agent()
                .native_steering_supported(probe_session_id)
                .await
        });
        cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                let outcome = runner.await;
                let _ = entity.update(cx, |this, cx| {
                    let supported = matches!(outcome, Ok(Ok(true)));
                    let changed = if supported {
                        this.native_steering_supported_session_ids
                            .insert(session_key.clone())
                    } else {
                        this.native_steering_supported_session_ids
                            .remove(&session_key)
                    };
                    if changed {
                        cx.notify();
                    }
                });
            },
        )
        .detach();
    }

    fn reconcile_optimistic_runtime_selection(
        &mut self,
        session_id: &VibexSessionId,
        state: &AgentSessionRuntimeSelectionState,
        cx: &mut Context<Self>,
    ) {
        let Some(desired) = self
            .optimistic_runtime_selections
            .get(session_id.as_str())
            .cloned()
        else {
            return;
        };
        if desired == state.desired
            && !self
                .runtime_selection_requests_in_flight
                .contains(session_id.as_str())
        {
            self.optimistic_runtime_selections
                .remove(session_id.as_str());
            return;
        }
        self.request_pending_runtime_selection(session_id, state, false, cx);
    }

    fn request_pending_runtime_selection(
        &mut self,
        session_id: &VibexSessionId,
        state: &AgentSessionRuntimeSelectionState,
        force: bool,
        cx: &mut Context<Self>,
    ) {
        if self
            .runtime_selection_requests_in_flight
            .contains(session_id.as_str())
        {
            return;
        }
        let Some(desired) = self
            .optimistic_runtime_selections
            .get(session_id.as_str())
            .cloned()
        else {
            return;
        };
        if !force && desired == state.desired {
            self.optimistic_runtime_selections
                .remove(session_id.as_str());
            return;
        }
        let Some(backend) = self.backend.clone() else {
            return;
        };

        let session_key = session_id.as_str().to_string();
        let requested_session_id = session_id.clone();
        let runner_session_id = requested_session_id.clone();
        let requested_desired = desired.clone();
        let expected_revision = state.session_revision;
        let expected_selection_revision = state.selection_revision;
        let preference_epoch = self.runtime_preference_write_fence.begin(&desired.agent_id);
        self.runtime_selection_requests_in_flight
            .insert(session_key.clone());
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            let outcome = backend
                .agent()
                .set_desired_runtime(MutationRequest::new(SetDesiredAgentSessionRuntimeRequest {
                    session_id: runner_session_id.clone(),
                    idempotency_key: format!("desktop-runtime:{}", unix_timestamp_ms()),
                    expected_revision,
                    expected_selection_revision,
                    desired,
                    interaction: RuntimeSelectionInteraction::Seamless,
                }))
                .await;
            // The native path also re-reads a cached selection state as an
            // error fallback; remote clients re-render from the next
            // authoritative RuntimeSelection event instead.
            (outcome, None)
        });
        cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                let result = runner.await;
                let _ = entity.update(cx, |this, cx| {
                    this.runtime_selection_requests_in_flight
                        .remove(&session_key);
                    match result {
                        Ok((outcome, observed)) => match outcome {
                            Ok(state) => {
                                let persisted = state.desired.clone();
                                this.apply_runtime_selection_state(
                                    &requested_session_id,
                                    state,
                                    cx,
                                );
                                this.remember_runtime_selection_if_current(
                                    &persisted,
                                    preference_epoch,
                                );
                            }
                            Err(error) => {
                                if let Some(state) = observed {
                                    this.apply_runtime_selection_state(
                                        &requested_session_id,
                                        state,
                                        cx,
                                    );
                                }
                                let target_is_still_current = this
                                    .optimistic_runtime_selections
                                    .get(requested_session_id.as_str())
                                    == Some(&requested_desired);
                                if target_is_still_current
                                    && !matches!(
                                        error.code.as_str(),
                                        "runtime_switch_revision_conflict"
                                            | "desired_selection_revision_conflict"
                                    )
                                {
                                    this.optimistic_runtime_selections
                                        .remove(requested_session_id.as_str());
                                    if this.selected_session_id.as_ref()
                                        == Some(&requested_session_id)
                                    {
                                        this.agent_error =
                                            Some(format!("{}: {}", error.code, error.message));
                                        this.refresh_active_suggestions(
                                            ComposerTarget::Session,
                                            cx,
                                        );
                                    }
                                }
                            }
                        },
                        Err(error) => {
                            if this
                                .optimistic_runtime_selections
                                .get(requested_session_id.as_str())
                                == Some(&requested_desired)
                            {
                                this.optimistic_runtime_selections
                                    .remove(requested_session_id.as_str());
                                if this.selected_session_id.as_ref() == Some(&requested_session_id)
                                {
                                    this.agent_error =
                                        Some(format!("runtime switch failed: {error}"));
                                    this.refresh_active_suggestions(ComposerTarget::Session, cx);
                                }
                            }
                        }
                    }
                    cx.notify();
                });
            },
        )
        .detach();
    }

    fn selected_agent_session_state(&self) -> Option<AgentSessionState> {
        let state = if self.agent_turn_pending {
            Some(AgentSessionState::Running)
        } else {
            self.selected_session().map(|session| session.state)
        };
        timeline_session_state_for_render(
            self.selected_session_id.as_ref(),
            self.timeline.session_id.as_ref(),
            self.agent_loading,
            state,
        )
    }

    /// The lifecycle state of the session whose view is live.
    ///
    /// A session group pane renders another session's parked view while the
    /// selection still names the focused pane, so the conversation projection
    /// must read the view's session. When the focused pane is the one rendering
    /// the two are the same session and this matches
    /// [`Self::selected_agent_session_state`].
    fn live_agent_session_state(&self) -> Option<AgentSessionState> {
        let timeline_session_id = self.timeline.session_id.clone();
        let turn_pending = self.live_turn_pending();
        let state = if turn_pending {
            Some(AgentSessionState::Running)
        } else {
            timeline_session_id
                .as_ref()
                .and_then(|session_id| {
                    self.sessions
                        .iter()
                        .find(|session| &session.id == session_id)
                })
                .map(|session| session.state)
        };
        timeline_session_state_for_render(
            timeline_session_id.as_ref(),
            self.timeline.session_id.as_ref(),
            self.agent_loading,
            state,
        )
    }

    /// Whether the live view's session has an Agent turn in flight.
    /// Whether the borrowed view's session has a turn in flight.
    ///
    /// A row's `streaming` flag says "this row is the unfinished tail of a
    /// turn"; it stays set when a turn was interrupted, because nothing ever
    /// finalizes those items. Anything that *animates* while a row streams has
    /// to ask the session instead: an interrupted turn left a repeating shimmer
    /// running in every pane holding that session, which kept the whole
    /// workbench repainting at frame rate with no work in flight.
    fn borrowed_session_turn_is_live(&self) -> bool {
        agent_turn_is_active(self.live_turn_pending(), self.live_agent_session_state())
    }

    fn live_turn_pending(&self) -> bool {
        self.timeline
            .session_id
            .as_ref()
            .map_or(self.agent_turn_pending, |session_id| {
                self.session_turn_pending(session_id)
            })
    }

    fn conversation_turns(&self) -> Vec<TimelineConversationTurn> {
        if let Some(items) = self
            .pending_user_message_edit
            .as_ref()
            .and_then(|edit| edit.projected_items(&self.timeline))
        {
            return timeline_conversation_turns_with_reasoning_mode(
                &items,
                Some(AgentSessionState::Running),
                true,
                self.ui_state.session.reasoning_display_mode,
            );
        }
        if let Some(items) = optimistic_user_message_for_view(
            &self.timeline,
            &self.optimistic_user_messages,
            self.view_session_id.as_ref(),
        )
        .and_then(|message| message.projected_items(&self.timeline))
        {
            return timeline_conversation_turns_with_reasoning_mode(
                &items,
                self.live_agent_session_state(),
                self.live_turn_pending(),
                self.ui_state.session.reasoning_display_mode,
            );
        }
        self.timeline.conversation_turns_with_reasoning_mode(
            self.live_agent_session_state(),
            self.live_turn_pending(),
            self.ui_state.session.reasoning_display_mode,
        )
    }

    fn current_conversation_turns_cache_key(&self) -> ConversationTurnsCacheKey {
        ConversationTurnsCacheKey {
            session_id: self.timeline.session_id.clone(),
            timeline_revision: self.timeline.revision,
            item_count: self.timeline.items.len(),
            end_sequence: self.timeline.authoritative_end_sequence,
            session_state: self.live_agent_session_state(),
            agent_turn_pending: self.live_turn_pending(),
            pending_edit: self
                .pending_user_message_edit
                .as_ref()
                .map(PendingUserMessageEdit::cache_key),
            optimistic_message: optimistic_user_message_for_view(
                &self.timeline,
                &self.optimistic_user_messages,
                self.view_session_id.as_ref(),
            )
            .map(OptimisticUserMessage::cache_key),
            reasoning_display_mode: self.ui_state.session.reasoning_display_mode,
        }
    }

    fn sync_conversation_turns_render_cache(&self) {
        *self.conversation_turns_render_cache.borrow_mut() = self.conversation_turns_cache.clone();
    }

    fn conversation_turns_cached(&mut self) -> Rc<Vec<Rc<TimelineConversationTurn>>> {
        let key = self.current_conversation_turns_cache_key();
        if self.view.conversation_turns_cache_key.as_ref() != Some(&key) {
            let previous_key = self.view.conversation_turns_cache_key.clone();
            let incrementally_refreshed = previous_key.as_ref().is_some_and(|previous_key| {
                refresh_conversation_turns_cache_incrementally(
                    &mut self.view.conversation_turns_cache,
                    previous_key,
                    &key,
                    &self.view.timeline,
                )
            });
            if !incrementally_refreshed {
                self.conversation_turns_cache =
                    Rc::new(self.conversation_turns().into_iter().map(Rc::new).collect());
            }
            let turns = self.conversation_turns_cache.as_slice();
            self.conversation_turns_summary = ConversationTurnsSummary::from_turns(turns);
            self.conversation_turns_cache_key = Some(key);
            // The projection just moved, so every memoized render fingerprint
            // describes a turn shape that no longer exists.
            self.timeline_turn_layout_signature_cache.clear();
            self.sync_conversation_turns_render_cache();
        }
        self.conversation_turns_cache.clone()
    }

    fn select_session(&mut self, session_id: VibexSessionId, cx: &mut Context<Self>) {
        self.dismiss_sidebar_for_navigation();
        let primary_tab_changed = self.ui_state.workbench.active_tab != "agent";
        if primary_tab_changed {
            self.sync_current_navigation_entry();
            self.usage_session_filter = None;
            self.ui_state.workbench.active_tab = "agent".to_string();
            self.queue_ui_state();
        }
        self.select_session_with_history(session_id, !primary_tab_changed, cx);
        if primary_tab_changed {
            self.push_current_navigation_entry();
        }
        cx.notify();
    }

    /// Selects the session named by a clicked system notification. The
    /// notification tag carries the session id, so a click returns the user to
    /// the agent that raised it. Unknown ids (for example a session closed
    /// after the notification was posted) are ignored.
    pub(crate) fn focus_session_from_notification(
        &mut self,
        session_id: &str,
        cx: &mut Context<Self>,
    ) {
        let Ok(session_id) = VibexSessionId::parse(session_id) else {
            return;
        };
        if !self.sessions.iter().any(|session| session.id == session_id) {
            return;
        }
        self.select_session(session_id, cx);
    }

    fn clear_child_agent_context(&mut self) {
        self.child_agent_timelines.clear();
        self.child_agent_expanded_delegations.clear();
        self.child_agent_tabs.clear();
        self.child_agent_active_tab = None;
        if self.child_agent_panel_active {
            self.child_agent_panel_active = false;
            self.ui_state.workbench.right_rail_visible = false;
            self.right_rail_overlay_open = false;
        }
    }

    fn select_session_with_history(
        &mut self,
        session_id: VibexSessionId,
        record_history: bool,
        cx: &mut Context<Self>,
    ) {
        self.clear_sidebar_move_selection();
        self.new_session_open = false;
        self.new_session_error = None;
        self.sync_agent_streaming_surface_visibility();
        if mark_agent_session_read(&mut self.unread_agent_completion_session_ids, &session_id) {
            self.publish_sidebar_invalidation();
        }
        let runtime = self.runtime.clone();
        if runtime.is_none() && self.backend.is_none() {
            return;
        }
        let navigation_changed = self.selected_session_id.as_ref() != Some(&session_id);
        if navigation_changed {
            // The inline goal editor belongs to the session it was opened on.
            self.composer_goal_editing = false;
        }
        let runtime_initializing = self
            .sessions
            .iter()
            .find(|session| session.id == session_id)
            .is_some_and(|session| session.state == AgentSessionState::Initializing);
        if record_history && navigation_changed {
            self.sync_current_navigation_entry();
        }
        let state_owner = self
            .sessions
            .iter()
            .find(|session| session.id == session_id)
            .map(|session| self.workspace_state_owner(session));
        if let Some(owner) = state_owner.clone() {
            self.switch_workspace_layout_owner(Some(owner), cx);
        }
        if let (Some(backend), Some(session)) = (
            self.backend.clone(),
            self.sessions
                .iter()
                .find(|session| session.id == session_id)
                .cloned(),
        ) {
            self.ui_state.workbench.selected_workspace_id =
                Some(session.workspace_id.as_str().to_string());
            self.code_workbench.update(cx, |workbench, cx| {
                workbench.sync_workspace(
                    backend,
                    session.workspace_id,
                    std::path::PathBuf::from(session.workspace_root),
                    state_owner,
                    cx,
                )
            });
        }
        if !navigation_changed
            && !should_defer_timeline_streaming_work(
                &self.ui_state.workbench.active_tab,
                self.new_session_open,
            )
        {
            self.refresh_deferred_child_agent_timelines(cx);
        }
        if self.selected_session_id.as_ref() == Some(&session_id)
            && self.timeline.session_id.as_ref() == Some(&session_id)
            && !self.timeline.needs_authoritative_refetch
        {
            return;
        }
        if navigation_changed && let Some(edit) = self.inline_user_message_edit.take() {
            self.invalidate_timeline_turn_measurement(&edit.turn_id);
            self.rebuild_timeline_sizes();
        }
        if navigation_changed {
            // Child tabs and expanded previews are scoped to the parent
            // session currently shown in the center timeline. Do not leave a
            // previous parent's child session visible after navigation.
            self.clear_child_agent_context();
        }
        self.session_generation = self.session_generation.saturating_add(1);
        let generation = self.session_generation;
        let previous_session_id = self.selected_session_id.clone();
        self.selected_session_id = Some(session_id.clone());
        self.sync_session_group_focus(&session_id);
        // Selecting a session borrows the view that session already owns. The
        // view keeps its timeline, its scroll position and its expansion state,
        // so switching back is instant and cannot show another session's
        // conversation. A session that was never opened gets a fresh view here
        // and is loaded below.
        let had_view = self.borrow_session_view(&session_id);
        self.sync_management_pairing_context(cx);
        self.queue_agent_ui_state();
        if record_history && navigation_changed {
            self.push_current_navigation_entry();
        }
        self.agent_turn_pending = self.session_turn_pending(&session_id);
        self.agent_error = None;
        self.timeline_scroll_to_latest_pending = false;
        self.timeline_scroll_anchor_pending = false;
        self.timeline_scroll_wheel_idle_task = None;
        self.timeline_bottom_control_visible = false;
        self.timeline_bottom_control_mounted = false;
        self.timeline_bottom_control_close_task = None;
        self.timeline_duration_tick_task = None;
        self.timeline_scrollbar_interaction_active = false;
        self.composer_terminals.clear();
        self.selected_composer_terminal_id = None;
        self.composer_terminal_mode = false;
        self.composer_terminal_expanded = false;
        self.composer_terminal_resize_drag = None;
        self.composer_terminal_drop_target = None;
        self.composer_terminal_surfaces.clear();
        self.active_composer_terminal_surface_id = None;
        if had_view {
            self.agent_loading = false;
            self.refresh_borrowed_view_geometry();
        } else {
            self.agent_loading = true;
        }
        self.refresh_agent_token_usage(&session_id, cx);
        if navigation_changed {
            self.clear_suggestions();
        } else {
            match self
                .suggestion_context
                .as_ref()
                .map(|context| context.target)
            {
                Some(ComposerTarget::Session) => {
                    self.refresh_active_suggestions(ComposerTarget::Session, cx)
                }
                Some(ComposerTarget::NewSession) => self.clear_suggestions(),
                None => {}
            }
        }
        if self
            .pending_new_session
            .as_ref()
            .is_some_and(|pending| pending.session_id == session_id)
        {
            self.agent_loading = false;
            return;
        }
        let workspace_id = self
            .sessions
            .iter()
            .find(|session| session.id == session_id)
            .map(|session| session.workspace_id.clone());
        if let Some(runtime) = runtime.clone() {
            self.load_agent_session_timeline(
                runtime.clone(),
                session_id.clone(),
                workspace_id.clone(),
                generation,
                cx,
            );
            if let Some(backend) = self.backend.clone() {
                self.load_agent_session_terminals(
                    backend,
                    session_id.clone(),
                    workspace_id,
                    generation,
                    cx,
                );
            }
            if runtime_initializing {
                self.agent_projection_task = None;
                self.runtime_heartbeat_task = None;
                self.load_agent_session_projection(
                    runtime.clone(),
                    session_id.clone(),
                    generation,
                    cx,
                );
                if let Some(previous_session_id) = previous_session_id
                    && previous_session_id != session_id
                {
                    let runtime_client_id = self.runtime_client_id.clone();
                    gpui_tokio::Tokio::spawn(cx, async move {
                        runtime
                            .agent()
                            .runtime_lifecycle()
                            .detach_runtime(
                                DetachRuntimeRequest {
                                    session_id: previous_session_id,
                                    client_id: runtime_client_id,
                                },
                                "desktop",
                            )
                            .await
                    })
                    .detach();
                }
            } else {
                self.load_agent_session_projection(
                    runtime.clone(),
                    session_id.clone(),
                    generation,
                    cx,
                );
                self.start_runtime_heartbeat(
                    runtime,
                    previous_session_id,
                    session_id,
                    generation,
                    cx,
                );
            }
        } else {
            // Remote-client mode: the authoritative timeline arrives over the
            // backend RPC; terminals, the projection cache, and the heartbeat
            // are authority-local concerns.
            self.load_agent_session_timeline_remote(session_id, generation, cx);
        }
    }

    /// Remote twin of [`Self::load_agent_session_timeline`]: pages the
    /// authoritative timeline through the backend and applies the same
    /// replacement bookkeeping the native loader performs.
    fn load_agent_session_timeline_remote(
        &mut self,
        session_id: VibexSessionId,
        generation: u64,
        cx: &mut Context<Self>,
    ) {
        let Some(backend) = self.backend.clone() else {
            return;
        };
        let request_session_id = session_id.clone();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            let mut items = Vec::new();
            let mut after_sequence = 0_i64;
            loop {
                let page = backend
                    .agent()
                    .fetch_timeline(FetchTimelineRequest {
                        session_id: request_session_id.clone(),
                        after_sequence: Some(after_sequence),
                        limit: AGENT_TIMELINE_FETCH_PAGE_LIMIT,
                    })
                    .await?;
                let next_cursor =
                    next_authoritative_timeline_cursor(&request_session_id, after_sequence, &page)
                        .map_err(TimelineRestoreError::into_vibex_error)?;
                items.extend(page.items);
                let Some(next_cursor) = next_cursor else {
                    break;
                };
                after_sequence = next_cursor;
            }
            BackendResult::Ok(items)
        });
        self.agent_load_task = Some(cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                let outcome = runner.await;
                let _ = entity.update(cx, |this, cx| {
                    if this.session_generation != generation
                        || this.selected_session_id.as_ref() != Some(&session_id)
                    {
                        return;
                    }
                    this.agent_loading = false;
                    match outcome {
                        Ok(Ok(items)) => {
                            // Capture the reader's position against the extents
                            // that are still on screen before the replacement
                            // invalidates every measured row.
                            this.capture_timeline_scroll_anchor();
                            let content_changed = this.timeline.session_id.as_ref()
                                != Some(&session_id)
                                || this.timeline.items != items;
                            if content_changed {
                                this.invalidate_timeline_render_caches();
                                this.invalidate_agent_generation_output_estimate();
                                this.invalidate_agent_generation_compaction_count();
                            }
                            reset_pending_user_requests(
                                &mut this.pending_user_request_ids,
                                &session_id,
                                &items,
                            );
                            this.timeline
                                .replace_authoritative(session_id.clone(), items);
                            this.reconcile_optimistic_user_message();
                            this.auto_continue_probe_tasks.remove(session_id.as_str());
                            if this.timeline_follow.following_bottom {
                                this.request_timeline_scroll_to_latest();
                            } else {
                                this.timeline_scroll_anchor_pending = true;
                            }
                        }
                        Ok(Err(error)) => {
                            this.agent_error = Some(format!("{}: {}", error.code, error.message));
                        }
                        Err(error) => {
                            this.agent_error = Some(format!("Agent action failed: {error}"));
                        }
                    }
                    cx.notify();
                });
            },
        ));
    }

    fn load_agent_session_timeline(
        &mut self,
        runtime: Arc<DesktopRuntime>,
        session_id: VibexSessionId,
        workspace_id: Option<vibex_core::WorkspaceId>,
        generation: u64,
        cx: &mut Context<Self>,
    ) {
        let poll_runtime = runtime.clone();
        let request_session_id = session_id.clone();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            fetch_authoritative_timeline(runtime, request_session_id).await
        });
        self.agent_load_task = Some(cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                let outcome = runner.await;
                let _ = entity.update(cx, |this, cx| {
                    if this.session_generation != generation
                        || this.selected_session_id.as_ref() != Some(&session_id)
                    {
                        return;
                    }
                    this.agent_loading = false;
                    match outcome {
                        Ok(Ok(items)) => {
                            // Capture the reader's position against the extents
                            // that are still on screen before the replacement
                            // invalidates every measured row.
                            this.capture_timeline_scroll_anchor();
                            let content_changed = this.timeline.session_id.as_ref()
                                != Some(&session_id)
                                || this.timeline.items != items;
                            if content_changed {
                                this.invalidate_timeline_render_caches();
                                this.invalidate_agent_generation_output_estimate();
                                this.invalidate_agent_generation_compaction_count();
                            }
                            reset_pending_user_requests(
                                &mut this.pending_user_request_ids,
                                &session_id,
                                &items,
                            );
                            this.timeline
                                .replace_authoritative(session_id.clone(), items);
                            this.reconcile_optimistic_user_message();
                            if let Some(session_updated_at_ms) = this
                                .sessions
                                .iter()
                                .find(|session| session.id == session_id)
                                .map(|session| session.updated_at_ms)
                            {
                                let ended_normally =
                                    latest_timeline_turn_ended_normally(&this.timeline.items);
                                this.cache_auto_continue_turn_status(
                                    &session_id,
                                    session_updated_at_ms,
                                    ended_normally,
                                    cx,
                                );
                            }
                            if !should_defer_timeline_streaming_work(
                                &this.ui_state.workbench.active_tab,
                                this.new_session_open,
                            ) {
                                this.rebuild_timeline_sizes();
                            }
                            if !should_defer_timeline_streaming_work(
                                &this.ui_state.workbench.active_tab,
                                this.new_session_open,
                            ) {
                                this.start_agent_poll(
                                    poll_runtime.clone(),
                                    session_id.clone(),
                                    workspace_id.clone(),
                                    generation,
                                    this.timeline.authoritative_end_sequence.or(Some(0)),
                                    cx,
                                );
                            }
                            let search_jump_applied = this.apply_pending_session_search_jump(cx);
                            if !search_jump_applied {
                                if this.timeline_follow.following_bottom {
                                    this.request_timeline_scroll_to_latest();
                                } else {
                                    this.timeline_scroll_anchor_pending = true;
                                }
                            }
                        }
                        Ok(Err(error)) => {
                            this.agent_error = Some(format!("{}: {}", error.code, error.message));
                        }
                        Err(error) => {
                            this.agent_error = Some(format!("session load task failed: {error}"));
                        }
                    }
                    this.finish_startup_loading(cx);
                    cx.notify();
                });
            },
        ));
    }

    fn child_agent_timeline_snapshot(
        &self,
        session_id: &VibexSessionId,
    ) -> Option<ChildAgentTimelineSnapshot> {
        self.child_agent_timelines
            .get(session_id.as_str())
            .map(|state| {
                let session_state = state.session.as_ref().map(|session| session.state);
                ChildAgentTimelineSnapshot {
                    loading: state.loading,
                    loaded: state.loaded,
                    error: state.error.clone(),
                    rows: state
                        .timeline
                        .rows()
                        .into_iter()
                        .map(|row| ChildAgentTimelineRowProjection {
                            delegation: timeline_row_delegation(&row, &state.timeline.items),
                            row,
                        })
                        .collect(),
                    turns: timeline_conversation_turns_with_reasoning_mode(
                        &state.timeline.items,
                        session_state,
                        matches!(session_state, Some(AgentSessionState::Running)),
                        self.ui_state.session.reasoning_display_mode,
                    ),
                }
            })
    }

    fn ensure_child_agent_timeline(
        &mut self,
        session_id: VibexSessionId,
        force_reload: bool,
        cx: &mut Context<Self>,
    ) {
        let key = session_id.as_str().to_string();
        let load_generation = {
            let state = self
                .child_agent_timelines
                .entry(key.clone())
                .or_insert_with(|| ChildAgentTimelineState::new(session_id.clone()));
            if state.loading
                || (!force_reload && state.loaded && !state.timeline.needs_authoritative_refetch)
            {
                return;
            }
            state.loading = true;
            state.error = None;
            state.load_generation = state.load_generation.wrapping_add(1);
            state.load_generation
        };
        let Some(backend) = self.backend.clone() else {
            if let Some(state) = self.child_agent_timelines.get_mut(&key) {
                state.loading = false;
                state.error = Some("Agent runtime is not available".to_string());
            }
            cx.notify();
            return;
        };
        let request_session_id = session_id.clone();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            fetch_child_agent_session_snapshot_via_backend(backend, request_session_id).await
        });
        cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                let outcome = runner.await;
                let _ = entity.update(cx, |this, cx| {
                    let Some(state) = this.child_agent_timelines.get_mut(&key) else {
                        return;
                    };
                    if state.load_generation != load_generation {
                        return;
                    }
                    state.loading = false;
                    match outcome {
                        Ok(Ok((session, items))) => {
                            let fetched_end_sequence = items.last().map(|item| item.sequence);
                            let live_tail = state
                                .timeline
                                .items
                                .iter()
                                .filter(|item| {
                                    fetched_end_sequence
                                        .is_none_or(|sequence| item.sequence > sequence)
                                })
                                .cloned()
                                .collect::<Vec<_>>();
                            state
                                .timeline
                                .replace_authoritative(session_id.clone(), items);
                            state.session = Some(session);
                            for item in live_tail {
                                state.timeline.apply_live(TimelineLiveEvent {
                                    session_id: session_id.clone(),
                                    sequence: item.sequence,
                                    item,
                                });
                            }
                            state.loaded = true;
                            state.error = None;
                        }
                        Ok(Err(error)) => {
                            state.error = Some(format!("{}: {}", error.code, error.message));
                        }
                        Err(error) => {
                            state.error = Some(format!("child session load task failed: {error}"));
                        }
                    }
                    cx.notify();
                });
            },
        )
        .detach();
    }

    fn apply_child_agent_timeline_events(
        &mut self,
        selected_session_id: Option<&VibexSessionId>,
        batches: &BTreeMap<String, Vec<TimelineLiveEvent>>,
        cx: &mut Context<Self>,
    ) -> bool {
        let mut changed = false;
        let mut reloads = Vec::new();
        for event in batches.values().flatten() {
            if selected_session_id == Some(&event.session_id) {
                continue;
            }
            let Some(state) = self
                .child_agent_timelines
                .get_mut(event.session_id.as_str())
            else {
                continue;
            };
            changed |= state.timeline.apply_live(event.clone());
            if state.timeline.needs_authoritative_refetch && !state.loading {
                reloads.push(event.session_id.clone());
            }
        }
        reloads.sort();
        reloads.dedup();
        for session_id in reloads {
            self.ensure_child_agent_timeline(session_id, true, cx);
        }
        changed
    }

    fn defer_child_agent_timeline_events(&mut self, events: &[TimelineLiveEvent]) {
        for event in events {
            if !timeline_live_event_is_well_formed(event) {
                continue;
            }
            if let Some(state) = self
                .child_agent_timelines
                .get_mut(event.session_id.as_str())
            {
                state.timeline.mark_lagged();
            }
        }
    }

    fn refresh_deferred_child_agent_timelines(&mut self, cx: &mut Context<Self>) {
        let reloads = self
            .child_agent_timelines
            .values()
            .filter(|state| state.timeline.needs_authoritative_refetch && !state.loading)
            .filter_map(|state| state.timeline.session_id.clone())
            .collect::<Vec<_>>();
        for session_id in reloads {
            self.ensure_child_agent_timeline(session_id, true, cx);
        }
    }

    fn toggle_child_agent_delegation(
        &mut self,
        delegation: &TimelineDelegationProjection,
        cx: &mut Context<Self>,
    ) {
        let delegation_id = delegation.delegation_id.as_str().to_string();
        if !self.child_agent_expanded_delegations.remove(&delegation_id) {
            self.child_agent_expanded_delegations.insert(delegation_id);
            self.ensure_child_agent_timeline(delegation.child_session_id.clone(), false, cx);
        }
        cx.notify();
    }

    fn refresh_selected_agent_timeline(&mut self, cx: &mut Context<Self>) {
        let (runtime, session_id) = (self.runtime.clone(), self.selected_session_id.clone());
        let (Some(runtime), Some(session_id)) = (runtime, session_id) else {
            if let Some(session_id) = self.selected_session_id.clone() {
                self.timeline.mark_lagged();
                let generation = self.session_generation;
                self.load_agent_session_timeline_remote(session_id, generation, cx);
            }
            return;
        };
        let workspace_id = self
            .sessions
            .iter()
            .find(|session| session.id == session_id)
            .map(|session| session.workspace_id.clone());
        self.timeline.mark_lagged();
        self.load_agent_session_timeline(
            runtime,
            session_id,
            workspace_id,
            self.session_generation,
            cx,
        );
    }

    fn load_agent_session_projection(
        &mut self,
        runtime: Arc<DesktopRuntime>,
        session_id: VibexSessionId,
        generation: u64,
        cx: &mut Context<Self>,
    ) {
        let request_session_id = session_id.clone();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            runtime
                .agent()
                .runtime_selection()
                .get_selection_state(&request_session_id)
        });
        self.agent_projection_task = Some(cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                let outcome = runner.await;
                let _ = entity.update(cx, |this, cx| {
                    if this.session_generation != generation
                        || this.selected_session_id.as_ref() != Some(&session_id)
                    {
                        return;
                    }
                    match outcome {
                        Ok(Ok(selection)) => {
                            this.runtime_selection_uninitialized_sessions
                                .remove(session_id.as_str());
                            this.apply_runtime_selection_state(&session_id, selection, cx);
                        }
                        Ok(Err(error))
                            if error.code == "session_runtime_selection_uninitialized" =>
                        {
                            // Imported sessions predate runtime selection
                            // state; the composer offers initialization
                            // instead of surfacing this as an error.
                            this.runtime_selection_uninitialized_sessions
                                .insert(session_id.as_str().to_string());
                            this.runtime_selection = None;
                        }
                        Ok(Err(error)) => {
                            this.agent_error = Some(format!("{}: {}", error.code, error.message));
                        }
                        Err(error) => {
                            this.agent_error =
                                Some(format!("session projection task failed: {error}"));
                        }
                    }
                    cx.notify();
                });
            },
        ));
    }

    fn load_agent_session_terminals(
        &mut self,
        backend: BackendFacade,
        session_id: VibexSessionId,
        workspace_id: Option<vibex_core::WorkspaceId>,
        generation: u64,
        cx: &mut Context<Self>,
    ) {
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            if let Some(workspace_id) = workspace_id.as_ref() {
                backend
                    .terminal()
                    .list_terminals(workspace_id.clone())
                    .await
                    .map(running_terminal_sessions)
                    .unwrap_or_default()
            } else {
                Vec::new()
            }
        });
        self.agent_terminal_task = Some(cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                let outcome = runner.await;
                let _ = entity.update(cx, |this, cx| {
                    if this.session_generation != generation
                        || this.selected_session_id.as_ref() != Some(&session_id)
                    {
                        return;
                    }
                    let dirty = match outcome {
                        Ok(terminals) => this.sync_terminal_sessions(terminals, cx),
                        Err(error) => {
                            this.runtime_note =
                                Some(format!("session terminal task failed: {error}"));
                            true
                        }
                    };
                    if dirty {
                        cx.notify();
                    }
                });
            },
        ));
    }

    fn start_runtime_heartbeat(
        &mut self,
        runtime: Arc<DesktopRuntime>,
        previous_session_id: Option<VibexSessionId>,
        session_id: VibexSessionId,
        generation: u64,
        cx: &mut Context<Self>,
    ) {
        let client_id = self.runtime_client_id.clone();
        let heartbeat_ms = runtime.polling_policy().attach_heartbeat_ms;
        let heartbeat_session_id = session_id.clone();
        let (warning_tx, mut warning_rx) = mpsc::unbounded_channel();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            if let Some(previous_session_id) = previous_session_id
                && previous_session_id != heartbeat_session_id
            {
                let _ = runtime
                    .agent()
                    .runtime_lifecycle()
                    .detach_runtime(
                        DetachRuntimeRequest {
                            session_id: previous_session_id,
                            client_id: client_id.clone(),
                        },
                        "desktop",
                    )
                    .await;
            }
            loop {
                let warning = runtime_attachment_warning(
                    runtime
                        .agent()
                        .runtime_lifecycle()
                        .attach_runtime(
                            AttachRuntimeRequest {
                                session_id: heartbeat_session_id.clone(),
                                client_id: client_id.clone(),
                                // Selecting history is read-only. A Viewer lease keeps an
                                // existing runtime warm without spawning one; message and
                                // command dispatch materialize the runtime when work begins.
                                role: RuntimeLeaseRole::Viewer,
                            },
                            "desktop",
                        )
                        .await,
                );
                if let Some(warning) = warning {
                    let _ = warning_tx.send(warning);
                }
                tokio::time::sleep(Duration::from_millis(heartbeat_ms)).await;
            }
        });
        self.runtime_heartbeat_task = Some(cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                while let Some(warning) = warning_rx.recv().await {
                    let active = entity
                        .update(cx, |this, cx| {
                            if this.session_generation != generation
                                || this.selected_session_id.as_ref() != Some(&session_id)
                            {
                                return false;
                            }
                            this.runtime_note = Some(format!(
                                "Session runtime attachment needs recovery ({warning})"
                            ));
                            cx.notify();
                            true
                        })
                        .unwrap_or(false);
                    if !active {
                        break;
                    }
                }
                drop(runner);
            },
        ));
    }

    fn start_agent_poll(
        &mut self,
        runtime: Arc<DesktopRuntime>,
        session_id: VibexSessionId,
        workspace_id: Option<vibex_core::WorkspaceId>,
        generation: u64,
        after_sequence: Option<i64>,
        cx: &mut Context<Self>,
    ) {
        let policy = runtime.polling_policy();
        let (signal_tx, mut signal_rx) = mpsc::unbounded_channel();
        let poll_session_id = session_id.clone();
        let runner_session_id = poll_session_id.clone();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            let mut after_sequence = after_sequence;
            let mut idle_poll_count = 0_u16;
            let mut last_runtime_poll = Instant::now();
            let mut last_terminal_poll = Instant::now();
            loop {
                // The live event stream is what keeps an active window current;
                // this poll is the fallback for a missing or lagged stream. A
                // window nobody is looking at has no use for either, so it
                // drops to the slow cadence and skips the reads entirely — the
                // next tick after the window returns catches up from
                // `after_sequence`.
                let window_inactive = motion::window_is_inactive();
                let interval = if window_inactive {
                    Duration::from_millis(AGENT_TIMELINE_INACTIVE_POLL_MS)
                } else {
                    agent_timeline_poll_interval(policy.timeline_fallback_ms, idle_poll_count)
                };
                tokio::time::sleep(interval).await;
                if window_inactive {
                    continue;
                }
                let mut received_items = false;
                if let Ok(page) = runtime
                    .agent()
                    .fetch_timeline(FetchTimelineRequest {
                        session_id: session_id.clone(),
                        after_sequence,
                        limit: 500,
                    })
                    .await
                {
                    after_sequence = page.end_sequence.or(after_sequence);
                    if !page.items.is_empty() {
                        received_items = true;
                        let _ = signal_tx.send(AgentPollSignal::Timeline(page));
                        if let Ok(session) =
                            runtime.agent().manager().get_session(&session_id).await
                        {
                            let _ = signal_tx.send(AgentPollSignal::Session(session));
                        }
                    }
                }
                idle_poll_count = if received_items {
                    0
                } else {
                    idle_poll_count.saturating_add(1)
                };
                let now = Instant::now();
                if now.duration_since(last_runtime_poll)
                    >= Duration::from_millis(policy.runtime_events_ms)
                {
                    last_runtime_poll = now;
                    if let Ok(state) = runtime
                        .agent()
                        .runtime_selection()
                        .get_selection_state(&session_id)
                    {
                        let _ = signal_tx.send(AgentPollSignal::RuntimeSelection(Box::new(state)));
                    }
                    if let Ok(usage) = runtime_token_usage_snapshot(&runtime, &session_id) {
                        let _ = signal_tx.send(AgentPollSignal::RuntimeUsage {
                            session_id: runner_session_id.clone(),
                            usage,
                        });
                    }
                }
                if now.duration_since(last_terminal_poll)
                    >= Duration::from_millis(policy.terminal_list_ms)
                    && let Some(workspace_id) = workspace_id.as_ref()
                    && let Ok(terminals) = runtime.list_terminals(workspace_id)
                {
                    last_terminal_poll = now;
                    let _ = signal_tx.send(AgentPollSignal::Terminals(running_terminal_sessions(
                        terminals,
                    )));
                }
            }
        });
        self.agent_poll_task = Some(cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                while let Some(signal) = signal_rx.recv().await {
                    let active = entity
                        .update(cx, |this, cx| {
                            if this.session_generation != generation {
                                return false;
                            }
                            let dirty = match signal {
                                AgentPollSignal::Timeline(page) => this.apply_live_timeline_batch(
                                    page.items
                                        .into_iter()
                                        .map(|item| TimelineLiveEvent {
                                            session_id: page.session_id.clone(),
                                            sequence: item.sequence,
                                            item,
                                        })
                                        .collect(),
                                    cx,
                                ),
                                AgentPollSignal::Session(session) => {
                                    let previous_session = this
                                        .sessions
                                        .iter()
                                        .find(|existing| existing.id == session.id);
                                    let sidebar_changed = session_snapshot_sidebar_changed(
                                        previous_session,
                                        &session,
                                    );
                                    let selected_projection_changed = this
                                        .selected_session_id
                                        .as_ref()
                                        .is_some_and(|selected| selected == &session.id)
                                        && previous_session
                                            .is_none_or(|existing| existing.state != session.state);
                                    let changed = this
                                        .sessions
                                        .iter()
                                        .find(|existing| existing.id == session.id)
                                        .is_none_or(|existing| existing != &session);
                                    if changed {
                                        let session_id = session.id.clone();
                                        this.upsert_session_snapshot(session);
                                        if sidebar_changed {
                                            this.reconcile_sidebar_state();
                                            this.publish_sidebar_invalidation();
                                        }
                                        if selected_projection_changed {
                                            this.sync_auto_continue_for_session(&session_id, cx);
                                        }
                                    }
                                    if selected_projection_changed
                                        && !should_defer_timeline_streaming_work(
                                            &this.ui_state.workbench.active_tab,
                                            this.new_session_open,
                                        )
                                    {
                                        this.refresh_last_timeline_size();
                                    }
                                    session_update_should_repaint(
                                        &this.ui_state.workbench.active_tab,
                                        this.new_session_open,
                                        changed,
                                        sidebar_changed,
                                    )
                                }
                                AgentPollSignal::RuntimeSelection(state) => {
                                    let changed = this.apply_runtime_selection_state(
                                        &poll_session_id,
                                        *state,
                                        cx,
                                    );
                                    agent_projection_should_repaint(
                                        &this.ui_state.workbench.active_tab,
                                        changed,
                                    )
                                }
                                AgentPollSignal::RuntimeUsage { session_id, usage } => {
                                    let changed = if this.selected_session_id.as_ref()
                                        != Some(&session_id)
                                        || this.token_usage == usage
                                    {
                                        false
                                    } else {
                                        this.token_usage = usage;
                                        true
                                    };
                                    agent_projection_should_repaint(
                                        &this.ui_state.workbench.active_tab,
                                        changed,
                                    )
                                }
                                AgentPollSignal::Terminals(terminals) => {
                                    let changed = this.sync_terminal_sessions(terminals, cx);
                                    agent_projection_should_repaint(
                                        &this.ui_state.workbench.active_tab,
                                        changed,
                                    )
                                }
                            };
                            if dirty {
                                cx.notify();
                            }
                            true
                        })
                        .unwrap_or(false);
                    if !active {
                        break;
                    }
                }
                drop(runner);
            },
        ));
    }

    fn apply_live_timeline_batch(
        &mut self,
        events: Vec<TimelineLiveEvent>,
        cx: &mut Context<Self>,
    ) -> bool {
        let defer_streaming_work = should_defer_timeline_streaming_work(
            &self.ui_state.workbench.active_tab,
            self.new_session_open,
        );
        let mut sidebar_changed = false;
        for event in &events {
            if timeline_live_event_updates_sidebar_timestamp(event)
                && let Some(session) = self
                    .sessions
                    .iter_mut()
                    .find(|session| session.id == event.session_id)
                && event.item.timestamp_ms > session.last_message_at_ms
            {
                session.last_message_at_ms = event.item.timestamp_ms;
                sidebar_changed = true;
            }
        }
        if sidebar_changed {
            self.invalidate_sidebar_projection_cache();
        }
        let unread_changed = update_unread_agent_completions(
            &mut self.unread_agent_completion_session_ids,
            self.selected_session_id.as_ref(),
            &events,
        );
        // The pending-request index feeds the sidebar rows directly, so it only
        // needs a repaint and an invalidation broadcast, not a projection
        // rebuild.
        if update_pending_user_requests(&mut self.pending_user_request_ids, &events) {
            sidebar_changed = true;
        }
        if sidebar_changed || unread_changed {
            self.publish_sidebar_invalidation();
        }
        // Group the batch by session. Every session on screen owns its own view,
        // so the batch has to be routed per session instead of being filtered
        // down to whichever one the sidebar selected: that filter is what used
        // to freeze every non-focused pane while its session kept working.
        let mut batches = BTreeMap::<String, Vec<TimelineLiveEvent>>::new();
        for event in events {
            batches
                .entry(event.session_id.as_str().to_string())
                .or_default()
                .push(event);
        }
        for batch in batches.values() {
            self.notify_for_timeline_events(batch, cx);
        }
        let selected_session_id = self.selected_session_id.clone();
        if defer_streaming_work {
            // The authoritative timelines are deliberately left untouched while
            // the Agent surface is hidden. Reconcile every affected view once
            // the surface is visible again instead of projecting each chunk.
            for (key, batch) in &batches {
                if !batch.iter().any(timeline_live_event_is_well_formed) {
                    continue;
                }
                if selected_session_id
                    .as_ref()
                    .is_some_and(|selected| selected.as_str() == key)
                {
                    self.timeline.mark_lagged();
                } else if let Some(view) = self.session_views.get_mut(key) {
                    view.timeline.mark_lagged();
                }
            }
            self.defer_child_agent_timeline_events(
                &batches
                    .values()
                    .flat_map(|batch| batch.iter().cloned())
                    .collect::<Vec<_>>(),
            );
            return timeline_batch_should_repaint(
                &self.ui_state.workbench.active_tab,
                unread_changed || sidebar_changed,
                false,
                false,
            );
        }
        let child_timeline_changed =
            self.apply_child_agent_timeline_events(selected_session_id.as_ref(), &batches, cx);
        let mut timeline_changed = false;
        let mut refetch_pending = false;
        for (key, batch) in batches {
            let Ok(session_id) = VibexSessionId::parse(&key) else {
                continue;
            };
            if !self.session_view_exists(&session_id) {
                // Nothing on screen shows this session; the sidebar bookkeeping
                // above is all it needs.
                continue;
            }
            // The swap is unweighed: weighing a view walks its whole timeline
            // and every derived projection, and this path runs once per batch
            // per streaming session. The render pass weighs the view when it
            // hands it back, which is where the budget is enforced.
            if !self.borrow_session_view_unweighed(&session_id) {
                // The view was never loaded, so there is nothing to apply the
                // events to. The group loader owns bringing it up.
                self.release_session_view_unweighed();
                continue;
            }
            let (changed, needs_refetch) =
                self.apply_timeline_events_to_borrowed_view(&session_id, batch, cx);
            self.release_session_view_unweighed();
            timeline_changed |= changed;
            if needs_refetch {
                refetch_pending = true;
                self.refresh_session_view_timeline(&session_id, cx);
            }
        }
        timeline_batch_should_repaint(
            &self.ui_state.workbench.active_tab,
            unread_changed || sidebar_changed || child_timeline_changed,
            timeline_changed || child_timeline_changed,
            refetch_pending,
        )
    }

    /// Applies one session's live events to the view currently borrowed.
    ///
    /// The caller has already made `session_id`'s view the borrowed one, so the
    /// ordinary `self.timeline` / `self.conversation_turns_cache` accesses below
    /// operate on that session and no other. Returns whether the projection
    /// changed and whether the view needs an authoritative refetch.
    fn apply_timeline_events_to_borrowed_view(
        &mut self,
        session_id: &VibexSessionId,
        events: Vec<TimelineLiveEvent>,
        cx: &mut Context<Self>,
    ) -> (bool, bool) {
        debug_assert_eq!(self.timeline.session_id.as_ref(), Some(session_id));
        let output_stream_changed = events.iter().any(|event| {
            matches!(
                &event.item.payload,
                TimelinePayload::AgentMessageDelta(_)
                    | TimelinePayload::AgentMessage(_)
                    | TimelinePayload::Reasoning(_)
            )
        });
        let compaction_count_changed = events.iter().any(|event| {
            matches!(
                &event.item.payload,
                TimelinePayload::SystemNotice(notice) if notice.is_context_compaction()
            )
        });

        let previous_end_sequence = self.timeline.authoritative_end_sequence;
        let updates_existing_item = previous_end_sequence
            .is_some_and(|end| events.iter().any(|event| event.sequence <= end));
        let text_append_tail = (!updates_existing_item && agent_text_append_batch(&events))
            .then(|| {
                let turns = self.conversation_turns_cached();
                turns.last().map(|turn| (turns.len(), turn.id.clone()))
            })
            .flatten();
        let streaming_updates = (!updates_existing_item)
            .then(|| agent_streaming_delta_updates(&events))
            .flatten();
        let reasoning_updates = (!updates_existing_item && streaming_updates.is_none())
            .then(|| agent_reasoning_delta_updates(&events))
            .flatten();
        let auto_continue_refresh = timeline_batch_requires_auto_continue_refresh(&events);
        let reasoning_display_mode = self.ui_state.session.reasoning_display_mode;
        let changed = self.timeline.apply_live_batch(events);
        let optimistic_reconciled = changed > 0 && self.reconcile_optimistic_user_message();
        if changed > 0 {
            if auto_continue_refresh
                && let Some(session_updated_at_ms) = self
                    .sessions
                    .iter()
                    .find(|session| &session.id == session_id)
                    .map(|session| session.updated_at_ms)
            {
                let ended_normally = latest_timeline_turn_ended_normally(&self.timeline.items);
                self.cache_auto_continue_turn_status(
                    session_id,
                    session_updated_at_ms,
                    ended_normally,
                    cx,
                );
            }
            let mut streaming_cache_update = None;
            if updates_existing_item || optimistic_reconciled {
                self.invalidate_timeline_render_caches();
            } else if !self.view.timeline.needs_authoritative_refetch
                && let Some(updates) = streaming_updates.as_deref()
                && let Some(update) = with_detached_conversation_turns_render_cache(
                    &mut self.view.conversation_turns_cache,
                    &self.view.conversation_turns_render_cache,
                    |cache| {
                        append_agent_streaming_deltas_to_cache(
                            cache,
                            &mut self.view.streaming_row_state,
                            updates,
                        )
                    },
                )
            {
                self.conversation_turns_cache_key =
                    Some(self.current_conversation_turns_cache_key());
                streaming_cache_update = Some(update);
            } else if !self.view.timeline.needs_authoritative_refetch
                && let Some(updates) = reasoning_updates.as_deref()
                && let Some(update) = with_detached_conversation_turns_render_cache(
                    &mut self.view.conversation_turns_cache,
                    &self.view.conversation_turns_render_cache,
                    |cache| {
                        append_agent_reasoning_deltas_to_cache(
                            cache,
                            &mut self.view.streaming_row_state,
                            reasoning_display_mode,
                            previous_end_sequence,
                            updates,
                        )
                    },
                )
            {
                self.conversation_turns_cache_key =
                    Some(self.current_conversation_turns_cache_key());
                streaming_cache_update = Some(update);
            }
            if let Some(update) = streaming_cache_update.as_ref() {
                self.record_agent_generation_streaming_delta(update);
            } else if output_stream_changed {
                self.invalidate_agent_generation_output_estimate();
            }
            if updates_existing_item || compaction_count_changed {
                self.invalidate_agent_generation_compaction_count();
            }
            if !self.timeline_follow.following_bottom {
                let appended_messages = timeline_agent_message_count_after_sequence(
                    &self.timeline.items,
                    previous_end_sequence,
                );
                self.timeline_follow.content_appended(appended_messages);
            }
            let content_extent_changed = if let Some(update) = streaming_cache_update.as_ref() {
                self.refresh_last_timeline_size_incrementally(update)
            } else if let Some((previous_turn_count, previous_turn_id)) = text_append_tail.as_ref()
            {
                self.streaming_row_state = None;
                self.preserve_last_timeline_size_after_text_append(
                    *previous_turn_count,
                    previous_turn_id,
                )
            } else {
                self.refresh_last_timeline_size()
            };
            if timeline_should_auto_follow_content(
                self.timeline_follow.following_bottom,
                self.timeline_scroll_wheel_idle_task.is_some(),
                self.timeline_scrollbar_interaction_active,
                content_extent_changed,
            ) {
                self.request_timeline_scroll_to_latest();
            }
        }
        (changed > 0, self.timeline.needs_authoritative_refetch)
    }

    /// Refetches one session's authoritative timeline, selected or not.
    fn refresh_session_view_timeline(
        &mut self,
        session_id: &VibexSessionId,
        cx: &mut Context<Self>,
    ) {
        if self.selected_session_id.as_ref() == Some(session_id) {
            self.refresh_selected_agent_timeline(cx);
            return;
        }
        self.with_session_view(session_id, |this| this.timeline.mark_lagged());
        self.load_session_group_view(session_id, true, cx);
    }

    fn notify_for_timeline_events(&mut self, events: &[TimelineLiveEvent], cx: &mut Context<Self>) {
        let Some(session_id) = events.first().map(|event| event.session_id.as_str()) else {
            return;
        };
        let session_id = session_id.to_string();
        // The same committed item reaches the workbench twice: once over the
        // live event stream and once from the polling fallback. The timeline
        // dedups the second copy, but this path runs before that, so the same
        // high-water mark has to be kept here or one completion raises two
        // identical hints. The mark advances even while notifications are off
        // so re-enabling them cannot replay an already-seen completion.
        let (fresh, watermark) = new_timeline_notification_events(
            events,
            self.notified_timeline_sequences.get(&session_id).copied(),
        );
        if let Some(watermark) = watermark {
            self.notified_timeline_sequences
                .insert(session_id.clone(), watermark);
        }
        if fresh.is_empty()
            || !self.ui_state.desktop_behavior.notifications_enabled
            || self
                .notification_suppressed_session_ids
                .contains(&session_id)
        {
            return;
        }
        let agent_id = self
            .sessions
            .iter()
            .find(|session| session.id.as_str() == session_id.as_str())
            .map(|session| &session.agent_id);
        let agent_label = agent_id
            .map(|agent_id| runtime_agent_label(&self.agent_snapshots, agent_id))
            .unwrap_or_else(|| "Agent".to_string());
        let kind = timeline_notification_kind(&fresh, &self.ui_state.desktop_behavior);
        let Some(body) = timeline_notification_body(kind, &agent_label) else {
            return;
        };
        // Route by window focus: an app the user is already looking at gets an
        // in-app hint instead of an OS-level toast, while a backgrounded or
        // minimized app raises a system notification that can reach the user
        // outside the window. Windows Focus Assist (and the macOS/Linux
        // equivalents) still suppress the system notification on their own.
        if let Some(kind) = kind
            && let Some(handle) = cx.active_window()
        {
            let tone = timeline_notification_tone(kind);
            let message = SharedString::from(body.clone());
            let delivered = cx
                .update_window(handle, move |_, window, cx| {
                    window.push_notification(hint_notification(tone, message, cx), cx);
                })
                .is_ok();
            if delivered {
                return;
            }
        }
        // Reusing the session id as the tag makes a newer notification for the
        // same session replace the older one instead of stacking up.
        cx.show_system_notification(SystemNotification {
            tag: SharedString::from(session_id),
            title: SharedString::from("Vibex"),
            body: SharedString::from(body),
            actions: Vec::new(),
        });
    }

    fn apply_desktop_event(&mut self, event: DesktopEvent, cx: &mut Context<Self>) -> bool {
        match event {
            DesktopEvent::Timeline(event) => self.apply_live_timeline_batch(vec![event], cx),
            DesktopEvent::SessionUpdated(session) => {
                let previous_session = self
                    .sessions
                    .iter()
                    .find(|existing| existing.id == session.id);
                let sidebar_changed = session_snapshot_sidebar_changed(previous_session, &session);
                let selected_projection_changed = self
                    .selected_session_id
                    .as_ref()
                    .is_some_and(|selected| selected == &session.id)
                    && previous_session.is_none_or(|existing| existing.state != session.state);
                let changed = self
                    .sessions
                    .iter()
                    .find(|existing| existing.id == session.id)
                    .is_none_or(|existing| existing != &session);
                // A turn boundary is what auto-continue reacts to, and it belongs
                // to the session that changed — not only to the selected one.
                // The render path used to pick up a background session's
                // finished turn because a pane happened to show it; that made a
                // repaint decide whether a countdown started. The sync only
                // reads cached state and probes on a backoff, so an ordinary
                // field change costs a couple of map lookups.
                let turn_revision_changed = previous_session.is_none_or(|existing| {
                    existing.state != session.state
                        || existing.updated_at_ms != session.updated_at_ms
                });
                if changed {
                    let session_id = session.id.clone();
                    self.upsert_session_snapshot(session);
                    if sidebar_changed {
                        self.reconcile_sidebar_state();
                    }
                    if selected_projection_changed
                        || (turn_revision_changed && self.auto_continue_enabled(&session_id))
                    {
                        self.sync_auto_continue_for_session(&session_id, cx);
                    }
                }
                if selected_projection_changed
                    && !should_defer_timeline_streaming_work(
                        &self.ui_state.workbench.active_tab,
                        self.new_session_open,
                    )
                {
                    self.refresh_last_timeline_size();
                }
                session_update_should_repaint(
                    &self.ui_state.workbench.active_tab,
                    self.new_session_open,
                    changed,
                    sidebar_changed,
                )
            }
            DesktopEvent::Runtime(event) => {
                let changed = self
                    .selected_session_id
                    .as_ref()
                    .is_some_and(|selected| selected == &event.session_id)
                    && self.refresh_agent_token_usage(&event.session_id, cx);
                agent_projection_should_repaint(&self.ui_state.workbench.active_tab, changed)
            }
            DesktopEvent::RuntimeSelection(event) => {
                let changed = if self.selected_session_id.as_ref() == Some(&event.session_id) {
                    let session_id = event.session_id.clone();
                    self.apply_runtime_selection_state(&session_id, event.state, cx)
                } else {
                    false
                };
                agent_projection_should_repaint(&self.ui_state.workbench.active_tab, changed)
            }
            DesktopEvent::ProviderConfigChanged(event) => {
                self.management_view
                    .update(cx, |management, cx| management.refresh(cx));
                match event.phase {
                    ProviderConfigChangePhase::ProfilesChanged => {
                        self.load_agent_configured_catalog(cx)
                    }
                    ProviderConfigChangePhase::RuntimeOptionsChanged => {
                        self.load_agent_runtime_catalog(cx)
                    }
                }
                false
            }
            DesktopEvent::UsageInvalidated => {
                let visible = self.ui_state.workbench.active_tab == "usage";
                self.usage_view
                    .update(cx, |usage, cx| usage.invalidate(visible, cx));
                visible
            }
            DesktopEvent::Lagged {
                stream,
                skipped,
                refetch,
            } => {
                let defer_streaming_work = should_defer_timeline_streaming_work(
                    &self.ui_state.workbench.active_tab,
                    self.new_session_open,
                );
                self.runtime_note = Some(format!(
                    "{stream:?} stream lagged by {skipped}; authoritative refetch required"
                ));
                if refetch.timeline {
                    self.timeline.mark_lagged();
                }
                if refetch.runtime
                    && let Some(session_id) = self.selected_session_id.clone()
                {
                    self.refresh_agent_token_usage(&session_id, cx);
                }
                if refetch.timeline || refetch.runtime_selection {
                    self.timeline.mark_lagged();
                    if !defer_streaming_work {
                        self.refresh_selected_agent_timeline(cx);
                    }
                }
                if refetch.usage {
                    let visible = self.ui_state.workbench.active_tab == "usage";
                    self.usage_view
                        .update(cx, |usage, cx| usage.invalidate(visible, cx));
                }
                true
            }
            DesktopEvent::Shutdown => false,
        }
    }

    fn rebuild_timeline_sizes(&mut self) -> bool {
        self.timeline_pending_turn_heights.clear();
        let turns = self.conversation_turns_cached();
        self.streaming_row_state = turns
            .last()
            .and_then(|turn| self.streaming_timeline_row_state(turn));
        let active_turn_ids = turns
            .iter()
            .map(|turn| turn.id.as_str())
            .collect::<BTreeSet<_>>();
        self.timeline_measured_turn_heights
            .retain(|turn_id, _| active_turn_ids.contains(turn_id.as_str()));
        self.timeline_measured_turn_layout_signatures
            .retain(|turn_id, _| active_turn_ids.contains(turn_id.as_str()));
        self.timeline_streaming_shrink_candidates
            .retain(|turn_id, _| active_turn_ids.contains(turn_id.as_str()));
        self.timeline_estimated_turn_heights
            .retain(|turn_id, _| active_turn_ids.contains(turn_id.as_str()));
        let content_width = session_content_max_width(self.ui_state.session.content_width)
            .unwrap_or(AGENT_CONTENT_STANDARD_MAX_WIDTH);
        let mut row_sizes = Vec::with_capacity(turns.len());
        for turn in turns.iter() {
            // Measured turns already know their real extent; re-estimating them
            // would rescan every row body for nothing.
            let height = match self.timeline_measured_turn_heights.get(&turn.id).copied() {
                Some(measured) => measured,
                None => self.estimated_timeline_turn_height_cached(turn),
            };
            row_sizes.push(size(px(content_width), px(height)));
        }
        if self.timeline_row_sizes.as_ref() == &row_sizes {
            return false;
        }
        self.timeline_row_sizes = Rc::new(row_sizes);
        true
    }

    fn invalidate_timeline_layout_measurements(&mut self) {
        self.timeline_measured_turn_heights.clear();
        self.timeline_measured_turn_layout_signatures.clear();
        self.timeline_streaming_shrink_candidates.clear();
        self.timeline_pending_turn_heights.clear();
        self.timeline_estimated_turn_heights.clear();
        self.timeline_turn_layout_signature_cache.clear();
        self.timeline_row_sizes = Rc::new(Vec::new());
        // A height prepaint parked for this view was measured against the layout
        // being dropped, so replaying it would restore the old extent.
        self.invalidate_deferred_timeline_turn_heights();
    }

    /// Records the width a pane measured against the view that painted it.
    ///
    /// The borrowed view usually is the measured one, but a pane can paint after
    /// the swap has already handed the borrowed slot back, so the width has to
    /// be routed by session id rather than by "whatever is borrowed now".
    fn sync_session_view_layout_width(
        &mut self,
        session_id: Option<&VibexSessionId>,
        width: f32,
        cx: &mut Context<Self>,
    ) {
        if !width.is_finite() || width <= 0.0 {
            return;
        }
        let width = width.round();
        let Some(session_id) = session_id else {
            self.sync_timeline_layout_width(width, cx);
            return;
        };
        if self.view_session_id.as_ref() == Some(session_id) {
            self.sync_timeline_layout_width(width, cx);
            return;
        }
        let current = self
            .session_views
            .get(session_id.as_str())
            .and_then(|view| view.timeline_layout_width);
        if !timeline_layout_width_changed(current, Some(width)) {
            return;
        }
        let session_id = session_id.clone();
        self.with_session_view(&session_id, |this| {
            this.sync_timeline_layout_width(width, cx)
        });
    }

    fn sync_timeline_layout_width(&mut self, width: f32, cx: &mut Context<Self>) {
        if !width.is_finite() || width <= 0.0 {
            return;
        }
        let width = width.round();
        let previous = self.timeline_layout_width;
        self.timeline_layout_width = Some(width);
        if !timeline_layout_width_changed(previous, Some(width)) {
            return;
        }
        self.invalidate_timeline_layout_measurements();
        self.rebuild_timeline_sizes();
        cx.notify();
    }

    fn streaming_timeline_row_state(
        &self,
        turn: &TimelineConversationTurn,
    ) -> Option<StreamingRowStateCache> {
        if let Some(row) = turn
            .conclusion_row
            .iter()
            .chain(turn.process_rows.iter().rev())
            .find(|row| {
                row.streaming
                    && matches!(
                        row.kind,
                        TimelineRowKind::AgentMessage | TimelineRowKind::Reasoning
                    )
            })
        {
            return Some(StreamingRowStateCache {
                turn_id: turn.id.clone(),
                row_id: row.id.clone(),
                body_len: row.body.len(),
            });
        }

        (self.ui_state.session.reasoning_display_mode == ReasoningDisplayMode::LatestAtBottom)
            .then_some(())
            .and(turn.live_status.as_ref())
            .map(|body| StreamingRowStateCache {
                turn_id: turn.id.clone(),
                row_id: format!("reasoning-live:{}", turn.id),
                body_len: body.len(),
            })
    }

    fn refresh_last_timeline_size(&mut self) -> bool {
        // Apply queued measurement corrections instead of dropping them: the
        // streaming branch below intentionally keeps the current virtual
        // extent, so a cleared batch would never be re-recorded and a
        // switched-to session could keep a blank band under its last row.
        self.apply_pending_timeline_row_heights();
        let turns = self.conversation_turns_cached();
        let Some(turn) = turns.last().cloned() else {
            self.streaming_row_state = None;
            return self.rebuild_timeline_sizes();
        };
        self.streaming_row_state = self.streaming_timeline_row_state(&turn);
        if self.timeline_row_sizes.len() != turns.len() {
            return self.rebuild_timeline_sizes();
        }
        if self.streaming_row_state.is_some() {
            let Some(current_height) = self
                .timeline_row_sizes
                .last()
                .map(|row_size| f32::from(row_size.height))
            else {
                return self.rebuild_timeline_sizes();
            };
            let process_expansion = self.timeline_process_expansion.get(&turn.id).copied();
            let signature = self.timeline_turn_estimate_signature(&turn, process_expansion);
            self.timeline_estimated_turn_heights
                .insert(turn.id.clone(), (signature, current_height));
            return false;
        }
        self.invalidate_timeline_turn_measurement(&turn.id);
        let process_expansion = self.timeline_process_expansion.get(&turn.id).copied();
        let signature = self.timeline_turn_estimate_signature(&turn, process_expansion);
        let height = self.estimated_timeline_turn_height_projected(&turn, process_expansion);
        self.timeline_estimated_turn_heights
            .insert(turn.id.clone(), (signature, height));
        let content_width = session_content_max_width(self.ui_state.session.content_width)
            .unwrap_or(AGENT_CONTENT_STANDARD_MAX_WIDTH);
        let row_size = size(px(content_width), px(height));
        let row_sizes = Rc::make_mut(&mut self.timeline_row_sizes);
        let Some(previous) = row_sizes.last_mut() else {
            return false;
        };
        if *previous == row_size {
            return false;
        }
        *previous = row_size;
        true
    }

    fn preserve_last_timeline_size_after_text_append(
        &mut self,
        previous_turn_count: usize,
        previous_turn_id: &str,
    ) -> bool {
        let turns = self.conversation_turns_cached();
        let Some(turn) = turns.last().cloned() else {
            return self.rebuild_timeline_sizes();
        };
        if turns.len() != previous_turn_count
            || turn.id != previous_turn_id
            || self.timeline_row_sizes.len() != turns.len()
        {
            return self.refresh_last_timeline_size();
        }
        let Some(current_height) = self
            .timeline_row_sizes
            .last()
            .map(|row_size| f32::from(row_size.height))
        else {
            return self.refresh_last_timeline_size();
        };

        // A text-only append may still change presentation structure, such as
        // commentary transitioning into the final answer or a final message
        // reconciling the streaming row. Keep the current virtual extent for
        // this frame, but let the new rendered structure establish its next
        // intrinsic measurement without an estimated-height detour.
        self.invalidate_timeline_turn_measurement(&turn.id);
        let process_expansion = self.timeline_process_expansion.get(&turn.id).copied();
        let signature = self.timeline_turn_estimate_signature(&turn, process_expansion);
        self.timeline_estimated_turn_heights
            .insert(turn.id.clone(), (signature, current_height));
        false
    }

    fn refresh_last_timeline_size_incrementally(
        &mut self,
        update: &AgentStreamingCacheUpdate,
    ) -> bool {
        let Some(turn) = self.conversation_turns_cache.last().cloned() else {
            return self.rebuild_timeline_sizes();
        };
        let state = StreamingRowStateCache {
            turn_id: update.turn_id.clone(),
            row_id: update.row_id.clone(),
            body_len: update.body_len,
        };
        let Some(body_len) = streaming_timeline_row_body_len(&turn, &state) else {
            return self.rebuild_timeline_sizes();
        };
        if turn.id != update.turn_id
            || update.body_len < update.previous_body_len
            || body_len != update.body_len
            || self.timeline_row_sizes.len() != self.conversation_turns_cache.len()
        {
            return self.rebuild_timeline_sizes();
        }

        let Some(current_height) = self
            .timeline_row_sizes
            .last()
            .map(|row_size| f32::from(row_size.height))
        else {
            return self.refresh_last_timeline_size();
        };

        // Streaming Markdown is parsed in the background. Keep the virtual row
        // at the height of the document that is actually on screen; predicting
        // from newer source would expand the row before parsing and contract it
        // again when prepaint measures the previous document. The Markdown view
        // will report its new intrinsic height after the parse is applied.
        let process_expansion = self.timeline_process_expansion.get(&turn.id).copied();
        let signature = self.timeline_turn_estimate_signature(&turn, process_expansion);
        self.timeline_estimated_turn_heights
            .insert(turn.id.clone(), (signature, current_height));
        false
    }

    fn invalidate_timeline_render_caches(&mut self) {
        self.timeline_item_index.get_mut().invalidate();
        self.timeline_measured_turn_heights.clear();
        self.timeline_measured_turn_layout_signatures.clear();
        self.timeline_streaming_shrink_candidates.clear();
        self.timeline_pending_turn_heights.clear();
        self.timeline_estimated_turn_heights.clear();
        self.timeline_turn_layout_signature_cache.clear();
        self.timeline_process_unit_heights.clear();
        // The row table is derived from the measurements just cleared. Drop it
        // so a caller that cannot rebuild immediately still cannot reuse stale
        // heights against a different turn projection; the next render rebuilds
        // from the estimator because the lengths no longer match.
        self.timeline_row_sizes = Rc::new(Vec::new());
        self.timeline_markdown_sources.clear();
        self.timeline_reasoning_summaries.clear();
        self.timeline_tool_card_projections.clear();
        self.timeline_file_diff_previews.clear();
        self.timeline_file_diff_scrolls.clear();
        self.timeline_turn_file_changes.clear();
        self.conversation_turns_cache = Rc::new(Vec::new());
        self.conversation_turns_cache_key = None;
        self.conversation_turns_summary = ConversationTurnsSummary::default();
        self.streaming_row_state = None;
        self.sync_conversation_turns_render_cache();
    }

    fn invalidate_timeline_turn_measurement(&mut self, turn_id: &str) {
        self.timeline_measured_turn_heights.remove(turn_id);
        self.timeline_measured_turn_layout_signatures
            .remove(turn_id);
        self.timeline_streaming_shrink_candidates.remove(turn_id);
        self.timeline_turn_layout_signature_cache.remove(turn_id);
        self.timeline_pending_turn_heights
            .retain(|_, (pending_turn_id, _)| pending_turn_id != turn_id);
    }

    /// Height estimation walks every row body, so the result is memoized per
    /// turn and only recomputed when the turn's content or expansion changes.
    fn estimated_timeline_turn_height_cached(&mut self, turn: &TimelineConversationTurn) -> f32 {
        let process_expansion = self.timeline_process_expansion.get(&turn.id).copied();
        let signature = self.timeline_turn_estimate_signature(turn, process_expansion);
        if let Some((cached_signature, height)) = self.timeline_estimated_turn_heights.get(&turn.id)
            && *cached_signature == signature
        {
            return *height;
        }
        let height = self.estimated_timeline_turn_height_projected(turn, process_expansion);
        self.timeline_estimated_turn_heights
            .insert(turn.id.clone(), (signature, height));
        height
    }

    /// Fingerprint the rendered shape of a turn without including body lengths.
    /// Streaming text can grow every frame, while row projection changes must
    /// invalidate a stale measured virtual-list extent so it can shrink.
    ///
    /// The fingerprint reads every row of the turn, including a substring scan
    /// of each body, and prepaint re-records the same turn on every frame. It
    /// is therefore memoized against [`Self::timeline_turn_shape_key`]: a cheap
    /// digest of the turn-level inputs that change the rendered shape while the
    /// body text keeps streaming.
    fn timeline_turn_layout_signature(
        &mut self,
        turn: &TimelineConversationTurn,
        process_expansion: Option<bool>,
    ) -> u64 {
        let shape_key = self.timeline_turn_shape_key(turn, process_expansion);
        if let Some((cached_key, signature)) =
            self.timeline_turn_layout_signature_cache.get(&turn.id)
            && *cached_key == shape_key
        {
            return *signature;
        }
        let signature = self.timeline_turn_layout_signature_uncached(turn, process_expansion);
        self.timeline_turn_layout_signature_cache
            .insert(turn.id.clone(), (shape_key, signature));
        signature
    }

    /// The turn-level half of [`Self::timeline_turn_layout_signature`].
    ///
    /// Every field here is O(1) to read. Body text and row bodies are
    /// deliberately absent: an append that only grows a row keeps the shape —
    /// and therefore the memoized fingerprint — intact.
    fn timeline_turn_shape_key(
        &self,
        turn: &TimelineConversationTurn,
        process_expansion: Option<bool>,
    ) -> u64 {
        let mut hasher = std::collections::hash_map::DefaultHasher::new();
        let file_changes_present = self
            .timeline_turn_file_changes
            .get(&turn.id)
            .is_some_and(|(_, summary)| !summary.files.is_empty());
        turn.complete.hash(&mut hasher);
        turn.superseded.hash(&mut hasher);
        turn.failed.hash(&mut hasher);
        turn.pending_permission.hash(&mut hasher);
        timeline_turn_process_expanded(turn, process_expansion).hash(&mut hasher);
        turn.user_row.is_some().hash(&mut hasher);
        turn.live_status
            .as_ref()
            .map(|body| body.is_empty())
            .hash(&mut hasher);
        turn.conclusion_row.is_some().hash(&mut hasher);
        turn.runtime_attribution.is_some().hash(&mut hasher);
        file_changes_present.hash(&mut hasher);
        (file_changes_present
            && self
                .timeline_file_changes_expansion
                .get(&turn.id)
                .copied()
                .unwrap_or(false))
        .hash(&mut hasher);
        self.ui_state
            .session
            .reasoning_display_mode
            .hash(&mut hasher);
        self.ui_state
            .session
            .reasoning_expanded_by_default
            .hash(&mut hasher);
        self.reasoning_expansion
            .get(&format!("reasoning-live:{}", turn.id))
            .copied()
            .hash(&mut hasher);
        self.ui_state
            .session
            .enhanced_command_execution_display
            .hash(&mut hasher);
        self.ui_state
            .session
            .enhanced_file_operation_display
            .hash(&mut hasher);
        turn.process_rows.len().hash(&mut hasher);
        turn.process_activity_groups.len().hash(&mut hasher);
        turn.process_activity_groups_with_commands
            .len()
            .hash(&mut hasher);
        turn.process_activity_groups_with_file_operations
            .len()
            .hash(&mut hasher);
        turn.process_activity_groups_with_commands_and_file_operations
            .len()
            .hash(&mut hasher);
        hasher.finish()
    }

    fn timeline_turn_layout_signature_uncached(
        &self,
        turn: &TimelineConversationTurn,
        process_expansion: Option<bool>,
    ) -> u64 {
        let mut hasher = std::collections::hash_map::DefaultHasher::new();
        let process_expanded = timeline_turn_process_expanded(turn, process_expansion);
        let conclusion_visible = timeline_turn_conclusion_row(turn).is_some();
        let file_changes_present = self
            .timeline_turn_file_changes
            .get(&turn.id)
            .is_some_and(|(_, summary)| !summary.files.is_empty());

        turn.complete.hash(&mut hasher);
        turn.superseded.hash(&mut hasher);
        turn.failed.hash(&mut hasher);
        turn.pending_permission.hash(&mut hasher);
        process_expanded.hash(&mut hasher);
        turn.user_row.is_some().hash(&mut hasher);
        turn.live_status
            .as_ref()
            .map(|body| body.is_empty())
            .hash(&mut hasher);
        turn.conclusion_row.is_some().hash(&mut hasher);
        conclusion_visible.hash(&mut hasher);
        turn.runtime_attribution.is_some().hash(&mut hasher);
        file_changes_present.hash(&mut hasher);
        (file_changes_present
            && self
                .timeline_file_changes_expansion
                .get(&turn.id)
                .copied()
                .unwrap_or(false))
        .hash(&mut hasher);
        self.ui_state
            .session
            .reasoning_display_mode
            .hash(&mut hasher);
        self.ui_state
            .session
            .reasoning_expanded_by_default
            .hash(&mut hasher);
        self.reasoning_expansion
            .get(&format!("reasoning-live:{}", turn.id))
            .copied()
            .hash(&mut hasher);
        self.ui_state
            .session
            .enhanced_command_execution_display
            .hash(&mut hasher);
        self.ui_state
            .session
            .enhanced_file_operation_display
            .hash(&mut hasher);

        turn.process_rows.len().hash(&mut hasher);
        {
            let mut hash_row_shape = |row: &TimelineRow| {
                row.id.hash(&mut hasher);
                std::mem::discriminant(&row.kind).hash(&mut hasher);
                row.turn_id.is_some().hash(&mut hasher);
                row.conclusion.hash(&mut hasher);
                row.streaming.hash(&mut hasher);
                row.collapsible.hash(&mut hasher);
                row.pending_permission.hash(&mut hasher);
                row.failed.hash(&mut hasher);
                row.turn_failed.hash(&mut hasher);
                row.turn_pending_permission.hash(&mut hasher);
                row.file_path.is_some().hash(&mut hasher);
                row.runtime_attribution.is_some().hash(&mut hasher);
                row.body.is_empty().hash(&mut hasher);
                row.body.contains("](").hash(&mut hasher);
                row.title.is_empty().hash(&mut hasher);
                row.title.len().hash(&mut hasher);
                row.title.contains('\n').hash(&mut hasher);
                self.reasoning_expansion
                    .get(&row.id)
                    .copied()
                    .hash(&mut hasher);
                self.timeline_command_expansion
                    .get(&row.id)
                    .copied()
                    .hash(&mut hasher);
                self.inline_user_message_edit
                    .as_ref()
                    .is_some_and(|edit| edit.matches(&row.id, self.selected_session_id.as_ref()))
                    .hash(&mut hasher);
            };

            if let Some(row) = turn.user_row.as_ref() {
                hash_row_shape(row);
            }
            for row in &turn.process_rows {
                hash_row_shape(row);
            }
            if let Some(row) = turn.conclusion_row.as_ref() {
                hash_row_shape(row);
            }
        }

        for pair in turn.process_rows.windows(2) {
            self.command_permission_rows_are_linked(&pair[0], &pair[1])
                .hash(&mut hasher);
        }

        {
            let mut hash_groups = |groups: &[TimelineProcessActivityGroup]| {
                groups.len().hash(&mut hasher);
                for group in groups {
                    group.id.hash(&mut hasher);
                    group.start_row.hash(&mut hasher);
                    group.end_row.hash(&mut hasher);
                    self.timeline_command_expansion
                        .get(&group.id)
                        .copied()
                        .hash(&mut hasher);
                }
            };
            hash_groups(&turn.process_activity_groups);
            hash_groups(&turn.process_activity_groups_with_commands);
            hash_groups(&turn.process_activity_groups_with_file_operations);
            hash_groups(&turn.process_activity_groups_with_commands_and_file_operations);
        }

        hasher.finish()
    }

    /// Cheap fingerprint of every input the height estimate reads, computed in
    /// row count rather than body length.
    fn timeline_turn_estimate_signature(
        &self,
        turn: &TimelineConversationTurn,
        process_expansion: Option<bool>,
    ) -> u64 {
        let mut hasher = std::collections::hash_map::DefaultHasher::new();
        turn.complete.hash(&mut hasher);
        turn.superseded.hash(&mut hasher);
        process_expansion.hash(&mut hasher);
        self.ui_state
            .session
            .reasoning_display_mode
            .hash(&mut hasher);
        self.ui_state
            .session
            .reasoning_expanded_by_default
            .hash(&mut hasher);
        self.reasoning_expansion
            .get(&format!("reasoning-live:{}", turn.id))
            .copied()
            .hash(&mut hasher);
        self.timeline_file_changes_expansion
            .get(&turn.id)
            .copied()
            .hash(&mut hasher);
        self.ui_state
            .session
            .enhanced_command_execution_display
            .hash(&mut hasher);
        self.ui_state
            .session
            .enhanced_file_operation_display
            .hash(&mut hasher);
        for row in turn
            .user_row
            .iter()
            .chain(turn.process_rows.iter())
            .chain(turn.conclusion_row.iter())
        {
            row.id.hash(&mut hasher);
            std::mem::discriminant(&row.kind).hash(&mut hasher);
            row.last_sequence.hash(&mut hasher);
            row.body.len().hash(&mut hasher);
            row.title.len().hash(&mut hasher);
            row.pending_permission.hash(&mut hasher);
            row.failed.hash(&mut hasher);
            row.streaming.hash(&mut hasher);
            row.file_path.is_some().hash(&mut hasher);
            self.reasoning_expansion
                .get(&row.id)
                .copied()
                .hash(&mut hasher);
            self.timeline_command_expansion
                .get(&row.id)
                .copied()
                .hash(&mut hasher);
            self.inline_user_message_edit
                .as_ref()
                .is_some_and(|edit| edit.matches(&row.id, self.selected_session_id.as_ref()))
                .hash(&mut hasher);
        }
        for group in &turn.process_activity_groups {
            group.id.hash(&mut hasher);
            group.start_row.hash(&mut hasher);
            group.end_row.hash(&mut hasher);
            self.timeline_command_expansion
                .get(&group.id)
                .copied()
                .hash(&mut hasher);
        }
        for group in &turn.process_activity_groups_with_commands {
            group.id.hash(&mut hasher);
            group.start_row.hash(&mut hasher);
            group.end_row.hash(&mut hasher);
            self.timeline_command_expansion
                .get(&group.id)
                .copied()
                .hash(&mut hasher);
        }
        for group in &turn.process_activity_groups_with_file_operations {
            group.id.hash(&mut hasher);
            group.start_row.hash(&mut hasher);
            group.end_row.hash(&mut hasher);
            self.timeline_command_expansion
                .get(&group.id)
                .copied()
                .hash(&mut hasher);
        }
        for group in &turn.process_activity_groups_with_commands_and_file_operations {
            group.id.hash(&mut hasher);
            group.start_row.hash(&mut hasher);
            group.end_row.hash(&mut hasher);
            self.timeline_command_expansion
                .get(&group.id)
                .copied()
                .hash(&mut hasher);
        }
        hasher.finish()
    }

    /// Parks a turn height prepaint observed, under the session that painted it.
    ///
    /// Prepaint runs after the whole element tree is built, so it cannot know
    /// which view it measured for. Parking the raw measurement by session id
    /// lets the pane's own render replay it while that session's view is the
    /// borrowed one — the same routing [`Self::sync_session_view_layout_width`]
    /// already does for width.
    fn defer_timeline_turn_height(
        &mut self,
        session_id: Option<&str>,
        turn_index: usize,
        turn_id: String,
        measured_height: f32,
        cx: &mut Context<Self>,
    ) {
        let Some(session_id) = session_id else {
            // No session to route by means no pane owns the measurement, so the
            // borrowed view is the only candidate left.
            self.record_timeline_turn_height(turn_index, turn_id, measured_height, cx);
            return;
        };
        self.pending_timeline_turn_measurements
            .entry(session_id.to_string())
            .or_default()
            .insert(turn_index, (turn_id, measured_height));
    }

    /// Replays the heights prepaint parked for the borrowed view's session.
    ///
    /// Only the borrowed session's entry is taken, so the store stays bounded by
    /// the number of sessions that actually painted a timeline.
    fn flush_deferred_timeline_turn_heights(&mut self, cx: &mut Context<Self>) {
        let Some(session_id) = self.timeline.session_id.clone() else {
            return;
        };
        let Some(measurements) = self
            .pending_timeline_turn_measurements
            .remove(session_id.as_str())
        else {
            return;
        };
        if measurements.is_empty() {
            return;
        }
        // The layout signature reads the projection, so make it current before
        // replaying against turn indices.
        self.conversation_turns_cached();
        for (turn_index, (turn_id, measured_height)) in measurements {
            // The projection can move between prepaint and this render. A height
            // measured against another turn at that index cannot be trusted.
            if self
                .conversation_turns_cache
                .get(turn_index)
                .is_none_or(|turn| turn.id != turn_id)
            {
                continue;
            }
            self.record_timeline_turn_height(turn_index, turn_id, measured_height, cx);
        }
    }

    /// Drops parked measurements for sessions that no longer paint a timeline.
    fn invalidate_deferred_timeline_turn_heights(&mut self) {
        // Clone the id out first: the key would otherwise borrow the view the
        // parked map is about to be mutated beside.
        let Some(session_id) = self.timeline.session_id.clone() else {
            return;
        };
        self.pending_timeline_turn_measurements
            .remove(session_id.as_str());
    }

    fn record_timeline_turn_height(
        &mut self,
        turn_index: usize,
        turn_id: String,
        measured_height: f32,
        cx: &mut Context<Self>,
    ) {
        if !measured_height.is_finite() || measured_height <= 0.0 {
            return;
        }
        let measured_height = measured_height.ceil().max(72.0);
        let previous_height = self.timeline_measured_turn_heights.get(&turn_id).copied();
        let process_expansion = self.timeline_process_expansion.get(&turn_id).copied();
        // Prepaint records the same turn on every frame while it streams, so
        // the fingerprint is memoized. It keys on the turn's rendered shape,
        // and every toggle that changes that shape — plus every projection
        // rebuild — drops the memoized entry.
        let measured_turn = self
            .conversation_turns_cache
            .get(turn_index)
            .filter(|turn| turn.id == turn_id)
            .cloned();
        let layout_signature =
            measured_turn.map(|turn| self.timeline_turn_layout_signature(&turn, process_expansion));
        let previous_layout_signature = self
            .timeline_measured_turn_layout_signatures
            .get(&turn_id)
            .copied();
        let preserve_streaming_extent = self.streaming_row_state.as_ref().is_some_and(|state| {
            state.turn_id == turn_id
                && self
                    .conversation_turns_cache
                    .get(turn_index)
                    .and_then(|turn| streaming_timeline_row_body_len(turn, state))
                    .is_some_and(|body_len| body_len == state.body_len)
        });
        let extent_preserved = streaming_extent_is_preserved(
            preserve_streaming_extent,
            previous_layout_signature,
            layout_signature,
        );
        let stable_height = stable_streaming_timeline_height_for_layout(
            previous_height,
            measured_height,
            preserve_streaming_extent,
            previous_layout_signature,
            layout_signature,
        );
        // A streaming turn must not follow every shorter Markdown reparse, but a
        // repeatable smaller measurement is real content reduction. Accept the
        // settled one so the held extent cannot leave permanent slack - the
        // blank band bottom-follow would otherwise park the viewport on.
        let (measured_height, shrink_candidate) = settle_streaming_timeline_shrink(
            previous_height,
            measured_height,
            stable_height,
            extent_preserved,
            self.timeline_streaming_shrink_candidates
                .get(&turn_id)
                .copied(),
            Instant::now(),
        );
        if let Some(candidate) = shrink_candidate {
            self.timeline_streaming_shrink_candidates
                .insert(turn_id.clone(), candidate);
        } else {
            self.timeline_streaming_shrink_candidates.remove(&turn_id);
        }
        if let Some(layout_signature) = layout_signature {
            self.timeline_measured_turn_layout_signatures
                .insert(turn_id.clone(), layout_signature);
        } else {
            self.timeline_measured_turn_layout_signatures
                .remove(&turn_id);
        }
        // The cached measurement alone does not prove the virtual row
        // converged: a streaming refresh can drop a pending height batch
        // before it is applied, leaving the slot at a stale estimate. Requeue
        // the correction whenever the slot disagrees, otherwise a switched-to
        // session would keep an empty band under its last row until an
        // unrelated event invalidated the turn again.
        //
        // A confirmed shrink candidate also needs frames: the settle window has
        // to elapse before its smaller extent is accepted. Unconfirmed ones do
        // not ask for a repaint, so an oscillating measurement cannot spin the
        // workbench on its own.
        let shrink_awaiting_settle = shrink_candidate.is_some_and(|candidate| {
            candidate.confirmations >= AGENT_TIMELINE_STREAMING_SHRINK_CONFIRMATIONS
        });
        if previous_height.is_some_and(|current| (current - measured_height).abs() < 1.0)
            && self
                .timeline_row_sizes
                .get(turn_index)
                .is_some_and(|row_size| (f32::from(row_size.height) - measured_height).abs() < 1.0)
            && !shrink_awaiting_settle
        {
            return;
        }
        self.timeline_measured_turn_heights
            .insert(turn_id.clone(), measured_height);
        let indexed_turn_matches = self
            .conversation_turns_cache
            .get(turn_index)
            .is_some_and(|turn| turn.id == turn_id);
        let content_extent_changed = !indexed_turn_matches
            || self
                .timeline_row_sizes
                .get(turn_index)
                .is_none_or(|row_size| row_size.height != px(measured_height));
        self.timeline_pending_turn_heights
            .insert(turn_index, (turn_id, measured_height));
        if timeline_should_auto_follow_content(
            self.timeline_follow.following_bottom,
            self.timeline_scroll_wheel_idle_task.is_some(),
            self.timeline_scrollbar_interaction_active,
            content_extent_changed,
        ) {
            self.request_timeline_scroll_to_latest();
        }
        cx.notify();
    }

    /// Apply every height observed during the prior prepaint in one pass.
    /// The active element tree holds the previous `Rc<Vec<_>>`; mutating once
    /// on the next render avoids cloning the full size table per visible row.
    fn apply_pending_timeline_row_heights(&mut self) -> bool {
        if self.timeline_pending_turn_heights.is_empty() {
            return false;
        }
        let pending = std::mem::take(&mut self.timeline_pending_turn_heights);
        let valid = pending.iter().all(|(turn_index, (turn_id, _))| {
            *turn_index < self.timeline_row_sizes.len()
                && self
                    .conversation_turns_cache
                    .get(*turn_index)
                    .is_some_and(|turn| turn.id == *turn_id)
        });
        if !valid {
            return self.rebuild_timeline_sizes();
        }

        let row_sizes = Rc::make_mut(&mut self.timeline_row_sizes);
        let mut changed = false;
        for (turn_index, (_, height)) in pending {
            let height = px(height);
            if row_sizes[turn_index].height != height {
                row_sizes[turn_index].height = height;
                changed = true;
            }
        }
        changed
    }

    fn timeline_distance_to_bottom(&self) -> f32 {
        timeline_distance_to_bottom(
            f32::from(self.timeline_scroll.offset().y),
            f32::from(self.timeline_scroll.max_offset().y),
        )
    }

    fn timeline_is_near_bottom(&self) -> bool {
        self.timeline_distance_to_bottom() <= AGENT_TIMELINE_NEAR_BOTTOM_THRESHOLD_PX
    }

    fn sync_timeline_bottom_control(&mut self, scrollable: bool, cx: &mut Context<Self>) {
        let should_be_visible = timeline_should_show_bottom_control(
            scrollable,
            self.timeline_follow.following_bottom,
            self.timeline_distance_to_bottom(),
            self.timeline_bottom_control_visible,
        );
        if self.timeline_bottom_control_visible == should_be_visible {
            if !should_be_visible
                && self.timeline_bottom_control_mounted
                && self.ui_state.appearance.reduced_motion
            {
                self.timeline_bottom_control_close_task = None;
                self.timeline_bottom_control_mounted = false;
            }
            return;
        }

        self.timeline_bottom_control_close_task = None;
        self.timeline_bottom_control_visible = should_be_visible;
        if should_be_visible {
            self.timeline_bottom_control_mounted = true;
        } else if self.ui_state.appearance.reduced_motion {
            self.timeline_bottom_control_mounted = false;
        } else if self.timeline_bottom_control_mounted {
            self.timeline_bottom_control_close_task = Some(cx.spawn(async move |entity, cx| {
                cx.background_executor()
                    .timer(AGENT_TIMELINE_BOTTOM_CONTROL_TRANSITION_DURATION)
                    .await;
                let _ = entity.update(cx, |this, cx| {
                    this.timeline_bottom_control_close_task = None;
                    if !this.timeline_bottom_control_visible {
                        this.timeline_bottom_control_mounted = false;
                        cx.notify();
                    }
                });
            }));
        }
    }

    fn sync_timeline_duration_tick(&mut self, has_incomplete_turn: bool, cx: &mut Context<Self>) {
        if !has_incomplete_turn {
            self.timeline_duration_tick_task = None;
            return;
        }
        if self.timeline_duration_tick_task.is_some() {
            return;
        }

        let generation = self.session_generation;
        self.timeline_duration_tick_task = Some(cx.spawn(async move |entity, cx| {
            cx.background_executor()
                .timer(AGENT_TURN_DURATION_TICK_INTERVAL)
                .await;
            let _ = entity.update(cx, |this, cx| {
                if this.session_generation != generation {
                    return;
                }
                this.timeline_duration_tick_task = None;
                if motion::window_is_inactive() {
                    // Nobody can see the elapsed-time label while the window is
                    // in the background: keep the tick armed but skip the
                    // repaint. Coming back to the window repaints anyway, and
                    // the label is rebuilt from wall time.
                    this.sync_timeline_duration_tick(true, cx);
                    return;
                }
                cx.notify();
            });
        }));
    }

    fn request_timeline_scroll_to_latest(&mut self) {
        self.timeline_scroll_to_latest_pending = true;
    }

    fn apply_pending_timeline_scroll(&mut self) {
        if std::mem::take(&mut self.timeline_scroll_to_latest_pending)
            && self.timeline_follow.following_bottom
            && self.timeline_scroll_wheel_idle_task.is_none()
            && !self.timeline_scrollbar_interaction_active
        {
            self.scroll_timeline_to_latest();
            return;
        }
        // A pending anchor resolves after the row table is current, so a
        // switched-to session paints the anchored content in its first frame.
        if std::mem::take(&mut self.timeline_scroll_anchor_pending) {
            self.apply_timeline_scroll_anchor();
        }
    }

    fn timeline_row_heights(&self) -> Vec<f32> {
        self.timeline_row_sizes
            .iter()
            .map(|row_size| f32::from(row_size.height))
            .collect()
    }

    /// Remember the row under the viewport top while the reader is not
    /// following the bottom, so the same conversation content can be restored
    /// after a session switch or an authoritative replacement.
    fn capture_timeline_scroll_anchor(&mut self) {
        if self.timeline_follow.following_bottom
            || self.timeline_row_sizes.len() != self.conversation_turns_cache.len()
        {
            return;
        }
        let row_heights = self.timeline_row_heights();
        let Some((row_index, offset_in_row)) = timeline_scroll_anchor_from_offset(
            &row_heights,
            f32::from(self.timeline_scroll.offset().y),
            self.timeline_list_padding_top_px,
        ) else {
            return;
        };
        let Some(turn_id) = self
            .conversation_turns_cache
            .get(row_index)
            .map(|turn| turn.id.clone())
        else {
            return;
        };
        self.timeline_follow
            .preserve_anchor(turn_id, offset_in_row.round() as i32);
    }

    /// Put the captured anchor back under the viewport top against the current
    /// row table. Returns whether an anchor was applied.
    fn apply_timeline_scroll_anchor(&mut self) -> bool {
        if self.timeline_follow.following_bottom {
            return false;
        }
        let Some(turn_id) = self.timeline_follow.anchor_row_id.clone() else {
            return false;
        };
        let Some(row_index) = self
            .conversation_turns_cache
            .iter()
            .position(|turn| turn.id == turn_id)
        else {
            return false;
        };
        let row_heights = self.timeline_row_heights();
        let Some(offset_y) = timeline_scroll_offset_for_anchor(
            &row_heights,
            row_index,
            self.timeline_follow.anchor_offset_px as f32,
            self.timeline_list_padding_top_px,
        ) else {
            return false;
        };
        self.timeline_scroll
            .set_offset(point(px(0.0), px(offset_y)));
        true
    }

    fn handle_timeline_scroll_wheel(&mut self, event: &ScrollWheelEvent, cx: &mut Context<Self>) {
        let delta_y = match event.delta {
            ScrollDelta::Lines(point) => point.y,
            ScrollDelta::Pixels(point) => f32::from(point.y),
        };
        if delta_y == 0.0 || self.timeline_scroll.max_offset().y <= px(0.0) {
            return;
        }

        self.timeline_scroll_wheel_idle_task = None;
        self.timeline_scroll_to_latest_pending = false;
        self.timeline_scroll_anchor_pending = false;
        // A manual scroll outranks a reveal that never landed, so a match the
        // user scrolled away from is not yanked back into view later.
        self.pending_session_search_reveal_item_id = None;
        self.pending_permission_reveal_item_id = None;
        self.timeline_follow.set_following_bottom(false);
        let scrolled_toward_bottom = delta_y < 0.0;
        // A wheel event is routed to the pane under the pointer, which is not
        // necessarily the focused one, so the follow state just cleared above
        // belongs to the session this handler was borrowed for. Carry it into
        // the idle task: applying the resume to whichever view is borrowed when
        // the timer fires is what let a pane the reader scrolled away from snap
        // itself back to the bottom as its session kept streaming.
        let session_id = self.view_session_id.clone();
        // Trackpad inertia emits more wheel events after the gesture; resume only once it is idle.
        self.timeline_scroll_wheel_idle_task = Some(cx.spawn(async move |entity, cx| {
            cx.background_executor()
                .timer(AGENT_TIMELINE_SCROLL_IDLE_DELAY)
                .await;
            let _ = entity.update(cx, |this, cx| {
                this.with_session_view_for_render(session_id.as_ref(), |this| {
                    this.timeline_scroll_wheel_idle_task = None;
                    let should_follow = timeline_should_resume_follow_after_scroll_idle(
                        scrolled_toward_bottom,
                        this.timeline_distance_to_bottom(),
                        this.timeline_scrollbar_interaction_active,
                    );
                    this.timeline_follow.set_following_bottom(should_follow);
                    if should_follow {
                        this.request_timeline_scroll_to_latest();
                    }
                    cx.notify();
                });
            });
        }));
    }

    fn begin_timeline_scrollbar_interaction(
        &mut self,
        event: &MouseDownEvent,
        cx: &mut Context<Self>,
    ) {
        let bounds = self.timeline_scroll.bounds();
        if event.button != MouseButton::Left
            || self.timeline_scroll.max_offset().y <= px(0.0)
            || !bounds.contains(&event.position)
            || event.position.x < bounds.right() - px(AGENT_TIMELINE_SCROLLBAR_HIT_WIDTH_PX)
        {
            return;
        }

        self.timeline_scroll_wheel_idle_task = None;
        self.timeline_scrollbar_interaction_active = true;
        self.timeline_scroll_to_latest_pending = false;
        self.timeline_scroll_anchor_pending = false;
        self.pending_session_search_reveal_item_id = None;
        self.pending_permission_reveal_item_id = None;
        self.timeline_follow.set_following_bottom(false);
        cx.notify();
    }

    fn finish_timeline_scrollbar_interaction(&mut self, cx: &mut Context<Self>) {
        if !self.timeline_scrollbar_interaction_active {
            return;
        }
        self.timeline_scrollbar_interaction_active = false;
        let should_follow = self.timeline_is_near_bottom();
        self.timeline_follow.set_following_bottom(should_follow);
        if should_follow {
            self.request_timeline_scroll_to_latest();
        }
        cx.notify();
    }

    fn scroll_to_timeline_turn_top(&mut self, turn_id: &str, cx: &mut Context<Self>) {
        let Some(turn_index) = self
            .conversation_turns()
            .iter()
            .position(|turn| turn.id == turn_id)
        else {
            return;
        };

        self.timeline_scroll_wheel_idle_task = None;
        self.timeline_follow.set_following_bottom(false);
        self.timeline_scroll_to_latest_pending = false;
        self.timeline_scroll_anchor_pending = false;
        self.timeline_scroll
            .scroll_to_item(turn_index, ScrollStrategy::Top);
        cx.notify();
    }

    /// Scrolls the timeline to the card the permission alert points at.
    ///
    /// The alert names a request rather than a row: its card can sit inside a
    /// collapsed process section and, in a long conversation, outside the
    /// rendered window. The turn is expanded and centered first, then the row
    /// itself is revealed once it has been laid out.
    fn reveal_pending_permission_card(&mut self, cx: &mut Context<Self>) {
        let Some(target) = self.pending_permission_reveal_target() else {
            return;
        };
        self.timeline_scroll_wheel_idle_task = None;
        self.timeline_follow.set_following_bottom(false);
        self.timeline_scroll_to_latest_pending = false;
        self.timeline_scroll_anchor_pending = false;
        self.pending_session_search_reveal_item_id = None;
        self.timeline_process_expansion
            .insert(target.turn_id.clone(), true);
        self.invalidate_timeline_turn_measurement(&target.turn_id);
        self.rebuild_timeline_sizes();
        self.pending_permission_reveal_item_id = Some(target.item_id);
        self.timeline_scroll
            .scroll_to_item(target.turn_index, ScrollStrategy::Center);
        cx.notify();
    }

    /// The newest pending request the alert covers, as a scroll target.
    ///
    /// The turns come from the same projection the virtual list renders, so the
    /// index it returns addresses the row table the scroll is resolved against.
    fn pending_permission_reveal_target(&mut self) -> Option<PendingPermissionRevealTarget> {
        let turns = self.conversation_turns_cached();
        turns
            .iter()
            .enumerate()
            .rev()
            .find_map(|(turn_index, turn)| {
                if !turn.pending_permission {
                    return None;
                }
                let row = turn
                    .process_rows
                    .iter()
                    .rev()
                    .find(|row| row.pending_permission)?;
                let item_id = row.item_ids.last()?.clone();
                Some(PendingPermissionRevealTarget {
                    turn_id: turn.id.clone(),
                    turn_index,
                    item_id,
                })
            })
    }

    /// Hides the permission alert for the live session and refreshes the state
    /// the sidebar shows for it.
    ///
    /// Dismissing the alert is a view decision: the request stays pending and
    /// the Agent stays parked. It is persisted with the rest of the UI state,
    /// so acknowledging a request survives a restart. The refresh keeps the
    /// sidebar row honest — it reads the session's latest state instead of the
    /// state the alert was raised against.
    fn dismiss_pending_permission_alert(&mut self, cx: &mut Context<Self>) {
        let Some(session_id) = self.timeline.session_id.clone() else {
            return;
        };
        if let Some(signature) = self.pending_permission_alert_signature() {
            self.ui_state
                .session
                .dismissed_permission_alerts
                .insert(session_id.as_str().to_string(), signature);
            self.queue_ui_state();
        }
        self.load_agent_overview(cx);
        if self.selected_session_id.as_ref() == Some(&session_id) {
            self.refresh_selected_agent_timeline(cx);
        }
        cx.notify();
    }

    /// Whether the alert stays hidden for the requests currently pending.
    ///
    /// A dismissal only holds while the same set is pending: answering one
    /// request and receiving the next changes the signature, so the alert comes
    /// back rather than staying dismissed for the rest of the session.
    fn permission_alert_is_dismissed(&self, session_id: Option<&VibexSessionId>) -> bool {
        let Some(session_id) = session_id else {
            return false;
        };
        let Some(dismissed) = self
            .ui_state
            .session
            .dismissed_permission_alerts
            .get(session_id.as_str())
        else {
            return false;
        };
        self.pending_permission_alert_signature().as_deref() == Some(dismissed.as_str())
    }

    /// The pending-request set the alert covers, as one comparable string.
    fn pending_permission_alert_signature(&self) -> Option<String> {
        let pending = self.timeline.pending_permission_ids();
        (!pending.is_empty()).then(|| pending.into_iter().collect::<Vec<_>>().join("|"))
    }

    fn scroll_timeline_to_latest(&self) {
        if !self.timeline_row_sizes.is_empty() {
            // The base handle resolves the bottom from the freshly computed extent during layout.
            self.timeline_scroll.base_handle().scroll_to_bottom();
        }
    }

    fn clear_suggestions(&mut self) {
        self.suggestions.clear();
        self.suggestion_selection.dismiss();
        self.suggestion_context = None;
        self.suggestion_loading = false;
        self.suggestion_request_serial = self.suggestion_request_serial.saturating_add(1);
    }

    /// The textarea a composer target writes into.
    ///
    /// The session target is the *borrowed* view's textarea, so a group pane
    /// reads and writes the composer of the session it is showing.
    fn input_for_composer_target(&self, target: ComposerTarget) -> Option<Entity<TextareaState>> {
        match target {
            ComposerTarget::Session => self.composer_input_entity(),
            ComposerTarget::NewSession => Some(self.new_session_input.clone()),
        }
    }

    fn sync_composer_command_entry(&mut self, target: ComposerTarget, cx: &App) {
        let Some(input) = self.input_for_composer_target(target) else {
            return;
        };
        let raw_text = input.read(cx).value().to_string();
        let (text, _) = composer_submission_payload(
            &raw_text,
            match target {
                ComposerTarget::Session => &self.composer_attachments,
                ComposerTarget::NewSession => &self.new_session_attachments,
            },
        );
        let entry = match target {
            ComposerTarget::Session => self.composer_command_entry.as_ref(),
            ComposerTarget::NewSession => self.new_session_command_entry.as_ref(),
        };
        if !command_entry_matches_draft(&text, entry) {
            match target {
                ComposerTarget::Session => self.composer_command_entry = None,
                ComposerTarget::NewSession => self.new_session_command_entry = None,
            }
        }
    }

    fn refresh_suggestions(
        &mut self,
        target: ComposerTarget,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(input) = self.input_for_composer_target(target) else {
            return;
        };
        let composition_active = input.update(cx, |input, cx| {
            EntityInputHandler::marked_text_range(input, window, cx).is_some()
        });
        if composition_active {
            if self
                .suggestion_context
                .as_ref()
                .is_some_and(|context| context.target == target)
            {
                self.clear_suggestions();
                cx.notify();
            }
            return;
        }

        self.refresh_suggestions_for_current_token(target, cx);
    }

    fn refresh_suggestions_for_current_token(
        &mut self,
        target: ComposerTarget,
        cx: &mut Context<Self>,
    ) {
        let Some(input) = self.input_for_composer_target(target) else {
            return;
        };

        let value = input.read(cx).value().to_string();
        let selection = input.read(cx).selected_range();
        let Some(trigger) = composer_trigger_for_selection(&value, selection) else {
            if self
                .suggestion_context
                .as_ref()
                .is_some_and(|context| context.target == target)
            {
                self.clear_suggestions();
                cx.notify();
            }
            return;
        };
        self.request_composer_suggestions(target, trigger, cx);
    }

    fn refresh_active_suggestions(&mut self, target: ComposerTarget, cx: &mut Context<Self>) {
        if self
            .suggestion_context
            .as_ref()
            .is_some_and(|context| context.target == target)
        {
            self.refresh_suggestions_for_current_token(target, cx);
        }
    }

    fn request_composer_suggestions(
        &mut self,
        target: ComposerTarget,
        trigger: ComposerTrigger,
        cx: &mut Context<Self>,
    ) {
        let trigger_kind = match trigger.kind {
            vibex_desktop_model::ComposerTriggerKind::Command => AgentCommandTrigger::Slash,
            vibex_desktop_model::ComposerTriggerKind::File => AgentCommandTrigger::Mention,
            vibex_desktop_model::ComposerTriggerKind::Skill => AgentCommandTrigger::Dollar,
        };
        let (agent_id, provider_profile_id, session_id, workspace_id) = match target {
            ComposerTarget::Session => {
                let Some(session) = self.selected_session().cloned() else {
                    self.suggestion_loading = false;
                    cx.notify();
                    return;
                };
                let selection = self.selected_runtime_selection();
                (
                    selection
                        .as_ref()
                        .map(|selection| selection.agent_id.clone()),
                    selection
                        .as_ref()
                        .and_then(|selection| selection.provider_profile_id().cloned()),
                    Some(session.id),
                    Some(session.workspace_id),
                )
            }
            ComposerTarget::NewSession => {
                let workspace_id = self
                    .new_session_workspace
                    .selected_workspace()
                    .map(|workspace| workspace.id.clone())
                    .or_else(|| self.new_session_workspace.origin_workspace_id.clone());
                (
                    self.new_session_runtime_selection
                        .as_ref()
                        .map(|selection| selection.agent_id.clone()),
                    self.new_session_runtime_selection
                        .as_ref()
                        .and_then(|selection| selection.provider_profile_id().cloned()),
                    None,
                    workspace_id,
                )
            }
        };
        let request = AgentCommandDiscoverRequest {
            agent_id,
            provider_profile_id,
            session_id,
            workspace_id,
            trigger: Some(trigger_kind),
            query: Some(trigger.query),
            limit: Some(10),
        };
        let context = ComposerSuggestionContext {
            target,
            request: request.clone(),
            character_range: trigger.character_range,
        };
        if self.suggestion_context.as_ref() == Some(&context) {
            return;
        }
        let preserve_rows = self
            .suggestion_context
            .as_ref()
            .is_some_and(|current| composer_suggestion_collection_matches(current, &context));

        self.suggestion_request_serial = self.suggestion_request_serial.saturating_add(1);
        let request_serial = self.suggestion_request_serial;
        let request_session_id = self.view_session_id.clone();
        self.suggestion_context = Some(context.clone());
        if !preserve_rows {
            self.suggestions.clear();
            self.suggestion_selection.dismiss();
        }
        self.suggestion_loading = true;

        let Some(backend) = self.backend.clone() else {
            self.suggestions.clear();
            self.suggestion_selection.dismiss();
            self.suggestion_loading = false;
            cx.notify();
            return;
        };

        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            discover_desktop_composer_commands(backend, request).await
        });
        self.suggestion_task = Some(cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                let outcome = runner.await;
                let _ = entity.update(cx, |this, cx| {
                    if this.suggestion_request_serial != request_serial
                        || this.suggestion_context.as_ref() != Some(&context)
                        || this.view_session_id.as_ref() != request_session_id.as_ref()
                    {
                        return;
                    }
                    this.suggestion_loading = false;
                    this.suggestions = match outcome {
                        Ok(Ok(response)) => response.entries,
                        _ => Vec::new(),
                    };
                    let suggestion_count = this.suggestions.len().min(10);
                    this.suggestion_selection.replace_items(suggestion_count);
                    cx.notify();
                });
            },
        ));
        cx.notify();
    }

    /// `Up`/`Down` on the session composer: the suggestion popup owns the keys
    /// while it is open, history recall owns them while the composer is empty
    /// or already showing a recalled message, and everything else falls through
    /// to the textarea's own caret movement.
    fn capture_composer_arrow_action(
        &mut self,
        action: ComposerSuggestionAction,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let previous = match action {
            ComposerSuggestionAction::Previous => true,
            ComposerSuggestionAction::Next => false,
            ComposerSuggestionAction::Apply | ComposerSuggestionAction::Dismiss => return,
        };
        // An in-progress IME composition owns every arrow key, and a suggestion
        // popup opened by the recalled text keeps its own selection keys.
        let composing = self.composer_input_entity().is_some_and(|input| {
            input.update(cx, |input, cx| {
                EntityInputHandler::marked_text_range(input, window, cx).is_some()
            })
        });
        if composing {
            return;
        }
        if self.composer_suggestions_active(ComposerTarget::Session) {
            self.capture_composer_suggestion_action(ComposerTarget::Session, action, window, cx);
            return;
        }
        if self.navigate_composer_history(previous, window, cx) {
            cx.stop_propagation();
        }
    }

    /// Escape on the session composer. The suggestion popup dismisses first;
    /// only once it is gone does Escape end a history recall and put the
    /// preserved draft back.
    fn capture_composer_escape_action(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if self.composer_suggestions_active(ComposerTarget::Session) {
            self.capture_composer_suggestion_action(
                ComposerTarget::Session,
                ComposerSuggestionAction::Dismiss,
                window,
                cx,
            );
            return;
        }
        if self.cancel_composer_history_recall(window, cx) {
            cx.stop_propagation();
        }
    }

    /// Whether the suggestion popup currently owns the composer's arrow keys.
    fn composer_suggestions_active(&self, target: ComposerTarget) -> bool {
        self.suggestion_context
            .as_ref()
            .is_some_and(|context| context.target == target)
    }

    /// Whether the composer is showing a message recalled from history rather
    /// than live text. A cursor left over from another session does not count.
    fn composer_history_recall_active(&self) -> bool {
        self.composer_history.index.is_some()
            && self.composer_history.session_id == self.selected_session_id
    }

    /// Forget any in-flight recall. Called wherever the composer text changes
    /// out from under the walk — a session switch, a send, or a user edit.
    fn reset_composer_history(&mut self) {
        self.composer_history = ComposerHistoryState::default();
    }

    /// The selected session's earlier user messages, oldest first — the pool
    /// the composer's `Up`/`Down` walk draws from. Messages that carry no text
    /// (attachment only) have nothing to recall and are skipped; a message
    /// still waiting for its authoritative row is appended so the newest send
    /// is recallable at once.
    fn composer_history_entries(&self, session_id: &VibexSessionId) -> Vec<String> {
        if self.timeline.session_id.as_ref() != Some(session_id) {
            return Vec::new();
        }
        let mut entries = self
            .timeline
            .items
            .iter()
            .filter_map(|item| match &item.payload {
                TimelinePayload::UserMessage(message) => Some(message.text.clone()),
                _ => None,
            })
            .filter(|text| !text.trim().is_empty())
            .collect::<Vec<_>>();
        if let Some(pending) = self.optimistic_user_messages.get(session_id.as_str())
            && !pending.is_confirmed_by(&self.timeline)
            && !pending.text.trim().is_empty()
        {
            entries.push(pending.text.clone());
        }
        entries
    }

    /// Walk the selected session's user messages, one step per arrow press.
    /// Returns whether the key was consumed; an unconsumed key keeps its normal
    /// meaning inside the textarea.
    fn navigate_composer_history(
        &mut self,
        previous: bool,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> bool {
        let composer_input = self.ensure_composer_input(window, cx);
        let Some(session_id) = self.selected_session_id.clone() else {
            return false;
        };
        let active = self.composer_history_recall_active();
        let empty = composer_input.read(cx).value().trim().is_empty();
        // `Up` is the way in, and only from an empty composer. `Down` only ever
        // walks back toward that empty state.
        if !active && !(previous && empty) {
            return false;
        }
        let entries = self.composer_history_entries(&session_id);
        let current = active.then_some(self.composer_history.index).flatten();
        if let Some(index) = current
            && index >= entries.len()
        {
            // The recalled message left the timeline — the session was cleared
            // or reloaded. End the walk rather than pointing at nothing.
            self.reset_composer_history();
            return false;
        }
        let next = if previous {
            composer_history_previous(current, entries.len())
        } else {
            composer_history_next(current, entries.len())
        };
        let Some(index) = next else {
            if !active {
                return false;
            }
            // Past the newest message: the walk ends and the draft returns.
            let draft = std::mem::take(&mut self.composer_history.draft);
            self.composer_history.index = None;
            self.composer_history.session_id = None;
            self.apply_composer_history_text(draft, window, cx);
            return true;
        };
        if Some(index) == current {
            // The oldest message is sticky; consume the key so the caret does
            // not wander inside a recalled message instead.
            return true;
        }
        let Some(text) = entries.get(index).cloned() else {
            return false;
        };
        if !active {
            self.composer_history.draft = composer_input.read(cx).value().to_string();
            self.composer_history.session_id = Some(session_id);
        }
        self.composer_history.index = Some(index);
        self.apply_composer_history_text(text, window, cx);
        true
    }

    /// End a history recall without sending anything, restoring the draft the
    /// composer held before the walk started. Returns whether one was running.
    fn cancel_composer_history_recall(
        &mut self,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> bool {
        if !self.composer_history_recall_active() {
            return false;
        }
        let draft = std::mem::take(&mut self.composer_history.draft);
        self.composer_history.index = None;
        self.composer_history.session_id = None;
        self.apply_composer_history_text(draft, window, cx);
        true
    }

    /// Write recalled history — or the restored draft — into the composer,
    /// leaving the caret at the end so the next arrow press keeps walking.
    fn apply_composer_history_text(
        &mut self,
        text: String,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let composer_input = self.ensure_composer_input(window, cx);
        composer_input.update(cx, |input, cx| {
            input.set_value(text, window, cx);
            let end = input.value().len();
            input.set_selected_range(end..end, cx);
            input.focus(window, cx);
        });
        self.sync_inline_composer_attachments(false, cx);
        self.sync_composer_command_entry(ComposerTarget::Session, cx);
        self.refresh_suggestions(ComposerTarget::Session, window, cx);
        cx.notify();
    }

    fn capture_composer_suggestion_action(
        &mut self,
        target: ComposerTarget,
        action: ComposerSuggestionAction,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if self
            .suggestion_context
            .as_ref()
            .is_none_or(|context| context.target != target)
            || self.input_for_composer_target(target).is_none_or(|input| {
                input.update(cx, |input, cx| {
                    EntityInputHandler::marked_text_range(input, window, cx).is_some()
                })
            })
        {
            return;
        }
        match action {
            ComposerSuggestionAction::Previous => {
                self.suggestion_selection.select_previous();
                cx.stop_propagation();
                cx.notify();
            }
            ComposerSuggestionAction::Next => {
                self.suggestion_selection.select_next();
                cx.stop_propagation();
                cx.notify();
            }
            ComposerSuggestionAction::Apply => {
                if let Some(index) = self.suggestion_selection.selected_index
                    && let Some(entry) = self.suggestions.get(index).cloned()
                {
                    self.apply_suggestion(target, entry, window, cx);
                }
                cx.stop_propagation();
            }
            ComposerSuggestionAction::Dismiss => {
                self.clear_suggestions();
                cx.stop_propagation();
                cx.notify();
            }
        }
    }

    fn hover_composer_suggestion(
        &mut self,
        target: ComposerTarget,
        index: usize,
        cx: &mut Context<Self>,
    ) {
        if self
            .suggestion_context
            .as_ref()
            .is_some_and(|context| context.target == target)
            && index < self.suggestions.len().min(10)
            && self.suggestion_selection.selected_index != Some(index)
        {
            self.suggestion_selection.selected_index = Some(index);
            cx.notify();
        }
    }

    fn apply_suggestion(
        &mut self,
        target: ComposerTarget,
        entry: AgentCommandEntry,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(input) = self.input_for_composer_target(target) else {
            return;
        };
        let value = input.read(cx).value().to_string();
        let selection = input.read(cx).selected_range();
        let Some(trigger) = composer_trigger_for_selection(&value, selection) else {
            return;
        };
        let start_byte = character_offset_to_byte(&value, trigger.character_range.start);
        let end_byte = character_offset_to_byte(&value, trigger.character_range.end);
        let mut replacement = String::with_capacity(value.len() + entry.insertion_text.len());
        replacement.push_str(&value[..start_byte]);
        replacement.push_str(&entry.insertion_text);
        replacement.push_str(&value[end_byte..]);
        let cursor = start_byte + entry.insertion_text.len();
        input.update(cx, |input, cx| {
            input.replace_all(replacement, window, cx);
            input.set_selected_range(cursor..cursor, cx);
            input.focus(window, cx);
        });
        match target {
            ComposerTarget::Session => {
                self.composer_command_entry =
                    is_executable_command_source(&entry).then_some(entry.clone())
            }
            ComposerTarget::NewSession => {
                self.new_session_command_entry =
                    is_executable_command_source(&entry).then_some(entry.clone())
            }
        }
        self.clear_suggestions();
        cx.notify();
    }

    fn remove_inline_composer_attachment(
        &mut self,
        attachment_id: &str,
        new_session: bool,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let input = if new_session {
            self.new_session_input.clone()
        } else {
            self.ensure_composer_input(window, cx)
        };
        let marker = if new_session {
            self.new_session_attachments
                .iter()
                .find(|item| item.attachment.id == attachment_id)
                .map(|item| item.marker.clone())
        } else {
            self.composer_attachments
                .iter()
                .find(|item| item.attachment.id == attachment_id)
                .map(|item| item.marker.clone())
        };
        let Some(marker) = marker else {
            return;
        };
        let text = input.read(cx).value().to_string();
        if let Some(start) = text.find(&marker) {
            let range = inline_composer_attachment_padded_range(&text, start..start + marker.len());
            input.update(cx, |input, cx| {
                input.set_selected_range(range, cx);
                input.replace("", window, cx);
                input.focus(window, cx);
            });
        }
        // Keep the metadata in memory so InputState undo can restore the marker
        // and its image overlay after this explicit deletion.
        cx.notify();
    }

    fn remove_queue_inline_composer_attachment(
        &mut self,
        attachment_id: &str,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(marker) = self
            .composer_queue_edit_attachments
            .iter()
            .find(|item| item.attachment.id == attachment_id)
            .map(|item| item.marker.clone())
        else {
            return;
        };
        let text = self.composer_queue_edit_input.read(cx).value().to_string();
        if let Some(start) = text.find(&marker) {
            let range = inline_composer_attachment_padded_range(&text, start..start + marker.len());
            self.composer_queue_edit_input.update(cx, |input, cx| {
                input.set_selected_range(range, cx);
                input.replace("", window, cx);
                input.focus(window, cx);
            });
        }
        cx.notify();
    }

    fn remove_user_message_inline_attachment(
        &mut self,
        attachment_id: &str,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(marker) = self
            .inline_user_message_edit
            .as_ref()
            .and_then(|edit| {
                edit.attachments
                    .iter()
                    .find(|item| item.attachment.id == attachment_id)
            })
            .map(|item| item.marker.clone())
        else {
            return;
        };
        let text = self.user_message_edit_input.read(cx).value().to_string();
        if let Some(start) = text.find(&marker) {
            let range = inline_composer_attachment_padded_range(&text, start..start + marker.len());
            self.user_message_edit_input.update(cx, |input, cx| {
                input.set_selected_range(range, cx);
                input.replace("", window, cx);
                input.focus(window, cx);
            });
        }
        cx.notify();
    }

    fn inline_attachment_key_action(
        &self,
        edit: InlineAttachmentEdit,
        input: &Entity<TextareaState>,
        attachments: &[InlineComposerAttachment],
        cx: &mut Context<Self>,
    ) -> InlineAttachmentKeyAction {
        if attachments.is_empty() {
            return InlineAttachmentKeyAction::None;
        }
        let text = input.read(cx).value().to_string();
        let selection = input.read(cx).selected_range();
        let ranges = attachments
            .iter()
            .filter_map(|item| {
                item.range_in(&text)
                    .map(|range| (item.attachment.id.clone(), range))
            })
            .collect::<Vec<_>>();
        if !selection.is_empty()
            && matches!(
                edit,
                InlineAttachmentEdit::Backspace | InlineAttachmentEdit::Delete
            )
        {
            let mut expanded = selection.clone();
            for (_, range) in &ranges {
                if expanded.start < range.end && expanded.end > range.start {
                    expanded.start = expanded.start.min(range.start);
                    expanded.end = expanded.end.max(range.end);
                }
            }
            if expanded != selection {
                input.update(cx, |input, cx| input.set_selected_range(expanded, cx));
            }
            return InlineAttachmentKeyAction::None;
        }

        let cursor = selection.end;
        for (attachment_id, range) in ranges {
            let inside = cursor > range.start && cursor < range.end;
            match edit {
                InlineAttachmentEdit::Backspace if inside || cursor == range.end => {
                    return InlineAttachmentKeyAction::Remove(attachment_id);
                }
                InlineAttachmentEdit::Delete if inside || cursor == range.start => {
                    return InlineAttachmentKeyAction::Remove(attachment_id);
                }
                InlineAttachmentEdit::Left if inside || cursor == range.end => {
                    input.update(cx, |input, cx| {
                        input.set_selected_range(range.start..range.start, cx)
                    });
                    return InlineAttachmentKeyAction::Handled;
                }
                InlineAttachmentEdit::Right if inside || cursor == range.start => {
                    input.update(cx, |input, cx| {
                        input.set_selected_range(range.end..range.end, cx)
                    });
                    return InlineAttachmentKeyAction::Handled;
                }
                _ if inside => {
                    input.update(cx, |input, cx| {
                        input.set_selected_range(range.end..range.end, cx)
                    });
                    return InlineAttachmentKeyAction::None;
                }
                _ => {}
            }
        }
        InlineAttachmentKeyAction::None
    }

    fn handle_inline_attachment_key(
        &mut self,
        edit: InlineAttachmentEdit,
        new_session: bool,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> bool {
        let input = if new_session {
            self.new_session_input.clone()
        } else {
            self.ensure_composer_input(window, cx)
        };
        let attachments = if new_session {
            self.new_session_attachments.clone()
        } else {
            self.composer_attachments.clone()
        };
        match self.inline_attachment_key_action(edit, &input, &attachments, cx) {
            InlineAttachmentKeyAction::Remove(attachment_id) => {
                self.remove_inline_composer_attachment(&attachment_id, new_session, window, cx);
                true
            }
            InlineAttachmentKeyAction::Handled => true,
            InlineAttachmentKeyAction::None => false,
        }
    }

    fn capture_inline_attachment_edit(
        &mut self,
        edit: InlineAttachmentEdit,
        new_session: bool,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if self.handle_inline_attachment_key(edit, new_session, window, cx) {
            cx.stop_propagation();
        }
    }

    fn capture_queue_inline_attachment_edit(
        &mut self,
        edit: InlineAttachmentEdit,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let input = self.composer_queue_edit_input.clone();
        let attachments = self.composer_queue_edit_attachments.clone();
        match self.inline_attachment_key_action(edit, &input, &attachments, cx) {
            InlineAttachmentKeyAction::Remove(attachment_id) => {
                self.remove_queue_inline_composer_attachment(&attachment_id, window, cx);
                cx.stop_propagation();
            }
            InlineAttachmentKeyAction::Handled => cx.stop_propagation(),
            InlineAttachmentKeyAction::None => {}
        }
    }

    fn capture_user_message_inline_attachment_edit(
        &mut self,
        edit: InlineAttachmentEdit,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(attachments) = self
            .inline_user_message_edit
            .as_ref()
            .map(|edit| edit.attachments.clone())
        else {
            return;
        };
        let input = self.user_message_edit_input.clone();
        match self.inline_attachment_key_action(edit, &input, &attachments, cx) {
            InlineAttachmentKeyAction::Remove(attachment_id) => {
                self.remove_user_message_inline_attachment(&attachment_id, window, cx);
                cx.stop_propagation();
            }
            InlineAttachmentKeyAction::Handled => cx.stop_propagation(),
            InlineAttachmentKeyAction::None => {}
        }
    }

    fn capture_composer_paste(
        &mut self,
        new_session: bool,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let input = if new_session {
            self.new_session_input.clone()
        } else {
            self.ensure_composer_input(window, cx)
        };
        let composition_active = input.update(cx, |input, cx| {
            EntityInputHandler::marked_text_range(input, window, cx).is_some()
        });
        if composition_active {
            return;
        }

        let captured = self.paste_composer_clipboard_to(new_session, window, cx);
        reveal_composer_cursor_after_layout(input, window);
        if captured {
            cx.stop_propagation();
        }
    }

    fn capture_user_message_edit_paste(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if self.user_message_edit_input.update(cx, |input, cx| {
            EntityInputHandler::marked_text_range(input, window, cx).is_some()
        }) {
            return;
        }
        let Some(clipboard) = cx.read_from_clipboard() else {
            return;
        };
        let mut captured = false;
        for entry in clipboard.into_entries() {
            match entry {
                ClipboardEntry::Image(image) => {
                    captured |= self.add_user_message_edit_image(&image, window, cx);
                }
                ClipboardEntry::ExternalPaths(paths) => {
                    for path in paths.paths() {
                        captured |= self.add_user_message_edit_path(path, None, window, cx);
                    }
                }
                ClipboardEntry::String(string) => {
                    if let Some(metadata) = string.metadata_json::<VibexMessageClipboard>()
                        && self.add_user_message_edit_clipboard(metadata, window, cx)
                    {
                        captured = true;
                        continue;
                    }
                    if let Some((format, bytes)) = decode_html_data_image(&string.text) {
                        captured |= self.add_user_message_edit_image(
                            &Image::from_bytes(format, bytes),
                            window,
                            cx,
                        );
                    }
                    if let Some(metadata) = string.metadata.as_deref()
                        && let Some((format, bytes)) = decode_html_data_image(metadata)
                    {
                        captured |= self.add_user_message_edit_image(
                            &Image::from_bytes(format, bytes),
                            window,
                            cx,
                        );
                    }
                }
            }
        }
        if captured {
            reveal_composer_cursor_after_layout(self.user_message_edit_input.clone(), window);
            cx.stop_propagation();
        }
    }

    fn capture_composer_copy(
        &mut self,
        new_session: bool,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let input = if new_session {
            self.new_session_input.clone()
        } else {
            self.ensure_composer_input(window, cx)
        };
        let (text, selection) = {
            let input = input.read(cx);
            (input.value().to_string(), input.selected_range())
        };
        let attachments = if new_session {
            &self.new_session_attachments
        } else {
            &self.composer_attachments
        };
        let Some(clipboard) = inline_composer_clipboard_item(&text, attachments, selection) else {
            return;
        };
        cx.write_to_clipboard(clipboard);
        cx.stop_propagation();
    }

    fn handle_composer_enter(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if !self.composer_expanded {
            self.submit_composer(window, cx);
            return;
        }

        let composer_input = self.ensure_composer_input(window, cx);
        composer_input.update(cx, |input, cx| input.replace("\n", window, cx));
        self.sync_inline_composer_attachments(false, cx);
        self.sync_composer_command_entry(ComposerTarget::Session, cx);
        self.refresh_suggestions(ComposerTarget::Session, window, cx);
    }

    fn submit_composer(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let session_running = self
            .view_session_id
            .as_ref()
            .is_some_and(|session_id| self.agent_session_is_active(session_id));
        if self.agent_action_pending && !session_running {
            return;
        }
        let Some(message) = self.take_composer_message(window, cx) else {
            return;
        };
        let session_id = message.session_id.clone();
        let queue_paused = self
            .composer_queue_paused_session_ids
            .contains(session_id.as_str());
        let queue_has_messages = self
            .composer_queue
            .iter()
            .any(|queued| queued.session_id == session_id);
        if session_running || queue_paused || queue_has_messages {
            self.composer_queue.push(message);
            cx.notify();
            if !session_running && !queue_paused {
                // The user sent from the composer while the session is idle, so
                // this is an explicit instruction to advance the queue even when
                // its latest turn stopped abnormally. Auto/Manual send mode still
                // decides whether that is allowed.
                self.maybe_dispatch_next_composer_queue_message(
                    &session_id,
                    ComposerQueueDispatchBehavior::ExplicitSend,
                    window,
                    cx,
                );
            }
            return;
        }
        self.dispatch_composer_message(
            message,
            ComposerQueueDispatchBehavior::Automatic,
            window,
            cx,
        );
    }

    fn take_composer_message(
        &mut self,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> Option<ComposerQueueMessage> {
        let composer_input = self.ensure_composer_input(window, cx);
        if composer_input.update(cx, |input, cx| {
            EntityInputHandler::marked_text_range(input, window, cx).is_some()
        }) {
            return None;
        }
        let Some(runtime) = self.runtime.clone() else {
            // Remote-client mode: command discovery is an authority-local
            // capability, so manual slash expansion stays disabled and typed
            // text is submitted verbatim.
            return self.take_composer_message_remote(window, cx);
        };
        let session_id = self.view_session_id.clone()?;
        let Some(selection) = self.selected_runtime_selection() else {
            self.agent_error = Some("Runtime selection is not ready".into());
            return None;
        };
        let raw_text = composer_input.read(cx).value().to_string();
        let (text, attachments) =
            composer_submission_payload(&raw_text, &self.composer_attachments);
        if text.trim().is_empty() && attachments.is_empty() {
            return None;
        }
        self.sync_composer_command_entry(ComposerTarget::Session, cx);
        let allow_manual_provider_slash = runtime
            .agent()
            .manager()
            .command_discovery_capabilities(&AgentCommandDiscoverRequest {
                agent_id: Some(selection.agent_id.clone()),
                provider_profile_id: selection.provider_profile_id().cloned(),
                session_id: Some(session_id.clone()),
                workspace_id: None,
                trigger: Some(AgentCommandTrigger::Slash),
                query: None,
                limit: Some(1),
            })
            .map(|capabilities| capabilities.slash_commands)
            .unwrap_or(false);
        let command_invocation = resolve_composer_command_invocation(
            &text,
            self.composer_command_entry.as_ref(),
            allow_manual_provider_slash,
        );
        self.composer_queue_serial = self.composer_queue_serial.saturating_add(1).max(1);
        let message = ComposerQueueMessage {
            id: self.composer_queue_serial,
            session_id,
            desired_runtime: selection,
            text,
            attachments,
            command_invocation,
        };
        // Clear the captured draft before queueing or dispatch so completion can
        // never erase text the user typed for a later message.
        composer_input.update(cx, |input, cx| input.set_value("", window, cx));
        self.composer_attachments.clear();
        self.composer_command_entry = None;
        self.clear_suggestions();
        // The sent message becomes the newest history entry; a walk that was
        // still pointing at the previous timeline is stale from here on.
        self.reset_composer_history();
        Some(message)
    }

    /// Remote twin of [`Self::take_composer_message`]: identical payload
    /// assembly without the authority-local command discovery. Manual slash
    /// expansion stays off; catalog commands ride the remote send path.
    fn take_composer_message_remote(
        &mut self,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> Option<ComposerQueueMessage> {
        let composer_input = self.ensure_composer_input(window, cx);
        let session_id = self.view_session_id.clone()?;
        let Some(selection) = self.selected_runtime_selection() else {
            self.agent_error = Some("Runtime selection is not ready".into());
            return None;
        };
        let raw_text = composer_input.read(cx).value().to_string();
        let (text, attachments) =
            composer_submission_payload(&raw_text, &self.composer_attachments);
        if text.trim().is_empty() && attachments.is_empty() {
            return None;
        }
        self.composer_queue_serial = self.composer_queue_serial.saturating_add(1).max(1);
        let message = ComposerQueueMessage {
            id: self.composer_queue_serial,
            session_id,
            desired_runtime: selection,
            text,
            attachments,
            command_invocation: None,
        };
        composer_input.update(cx, |input, cx| input.set_value("", window, cx));
        self.composer_attachments.clear();
        self.composer_command_entry = None;
        self.clear_suggestions();
        // The sent message becomes the newest history entry; a walk that was
        // still pointing at the previous timeline is stale from here on.
        self.reset_composer_history();
        Some(message)
    }

    /// Remote twin of the composer dispatch: optimistic message plus a
    /// single `send_message` RPC. Durable-submission locators and command
    /// execution stay authority-local; live updates arrive through events.
    fn dispatch_composer_message_remote(
        &mut self,
        message: ComposerQueueMessage,
        backend: BackendFacade,
        delivery: UserMessageDelivery,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let session_id = message.session_id.clone();
        let ComposerQueueMessage {
            id: message_id,
            desired_runtime: selection,
            text,
            attachments,
            ..
        } = message;
        self.notification_suppressed_session_ids
            .remove(session_id.as_str());
        let generation = self.session_generation;
        let submitted_session_id = session_id.clone();
        let idempotency_key = format!(
            "gpui-remote:{}:{}:{}:{}",
            session_id.as_str(),
            generation,
            message_id,
            unix_timestamp_ms()
        );
        let after_sequence = self.session_view_end_sequence(&session_id).unwrap_or(0);
        self.install_optimistic_user_message(OptimisticUserMessage {
            session_id: session_id.clone(),
            item_id: TimelineItemId::new(),
            after_sequence,
            submitted_at_ms: unix_timestamp_ms(),
            text: text.clone(),
            attachments: attachments.clone(),
        });
        self.set_session_turn_pending(&session_id, true);
        if self.auto_continue_enabled(&session_id) {
            self.resume_auto_continue(&session_id, cx);
        }
        if self.view_session_id.as_ref() == Some(&session_id) {
            self.agent_error = None;
        }
        cx.notify();
        let submit_key = idempotency_key.clone();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            let outcome = backend
                .agent()
                .send_message(MutationRequest::new(SendAgentMessageRequest {
                    session_id: session_id.clone(),
                    message_idempotency_key: idempotency_key,
                    desired_runtime: selection,
                    text,
                    attachments,
                    reasoning_effort: None,
                    correlation_id: None,
                    delivery,
                }))
                .await
                .map(|_| ());
            let session = backend.agent().open_session(session_id.clone()).await.ok();
            (outcome, session)
        });
        cx.spawn_in(window, async move |entity, cx| {
            let outcome = runner.await;
            let _ = entity.update_in(cx, |this, window, cx| {
                let completed = matches!(&outcome, Ok((Ok(_), _)));
                if let Ok((_, Some(session))) = &outcome {
                    this.upsert_session_snapshot(session.clone());
                    this.reconcile_sidebar_state();
                    this.publish_sidebar_invalidation();
                }
                if completed {
                    this.composer_submission_locators
                        .retain(|locator| locator.message_idempotency_key != submit_key);
                    this.composer_submission_states
                        .retain(|state| state.message_idempotency_key != submit_key);
                }
                this.set_session_turn_pending(&submitted_session_id, false);
                this.sync_auto_continue_for_session(&submitted_session_id, cx);
                let active = agent_turn_completion_is_active(
                    this.session_generation,
                    generation,
                    this.selected_session_id.as_ref(),
                    &submitted_session_id,
                );
                if active {
                    match &outcome {
                        Ok((Ok(_), _)) => this.refresh_selected_agent_timeline(cx),
                        Ok((Err(error), _)) => {
                            this.agent_error = Some(format!("{}: {}", error.code, error.message));
                        }
                        Err(error) => {
                            this.agent_error = Some(format!("Agent action failed: {error}"));
                        }
                    }
                }
                let _ = window;
                cx.notify();
            });
        })
        .detach();
    }

    fn agent_session_is_active(&self, session_id: &VibexSessionId) -> bool {
        self.session_turn_pending(session_id)
            || self.sessions.iter().any(|session| {
                session.id == *session_id
                    && matches!(
                        session.state,
                        AgentSessionState::Running | AgentSessionState::NeedsInput
                    )
            })
    }

    fn dispatch_composer_message(
        &mut self,
        message: ComposerQueueMessage,
        behavior: ComposerQueueDispatchBehavior,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let session_id = message.session_id.clone();
        let delivery = composer_queue_message_delivery(behavior);
        let session = self
            .sessions
            .iter()
            .find(|session| session.id == session_id);
        let session_state = session.map(|session| session.state);
        let cached_turn_status = session.and_then(|session| {
            self.cached_auto_continue_turn_status(&session_id, session.updated_at_ms)
        });
        let waits_for_continuation = composer_queue_waits_for_continuation(
            behavior,
            session_state,
            cached_turn_status.map(|status| status.ended_normally),
        );
        if composer_queue_session_blocks_dispatch(
            behavior,
            self.session_turn_pending(&session_id),
            session_state,
        ) || waits_for_continuation
        {
            let insert_at = self
                .composer_queue
                .iter()
                .position(|queued| queued.session_id == session_id)
                .unwrap_or(self.composer_queue.len());
            self.composer_queue.insert(insert_at, message);
            if waits_for_continuation && cached_turn_status.is_none() {
                // An unobserved revision is not proof of a normal completion:
                // probe it so a later frame can release the queue once the
                // latest turn is known. Waiting never pauses the queue — only
                // an explicit user interrupt does.
                self.probe_composer_queue_turn_status(&session_id, cx);
            }
            cx.notify();
            return;
        }
        let Some(runtime) = self.runtime.clone() else {
            let Some(backend) = self.backend.clone() else {
                let insert_at = self
                    .composer_queue
                    .iter()
                    .position(|queued| queued.session_id == session_id)
                    .unwrap_or(self.composer_queue.len());
                self.composer_queue.insert(insert_at, message);
                self.composer_queue_paused_session_ids
                    .insert(session_id.as_str().to_string());
                self.agent_error = Some("Local runtime is not ready".into());
                cx.notify();
                return;
            };
            self.dispatch_composer_message_remote(message, backend, delivery, window, cx);
            return;
        };
        let ComposerQueueMessage {
            id: message_id,
            desired_runtime: selection,
            text,
            attachments,
            command_invocation,
            ..
        } = message;
        self.notification_suppressed_session_ids
            .remove(session_id.as_str());
        let is_command = command_invocation.is_some();
        let generation = self.session_generation;
        let submitted_session_id = session_id.clone();
        let idempotency_key = format!(
            "gpui:{}:{}:{}:{}",
            session_id.as_str(),
            generation,
            message_id,
            unix_timestamp_ms()
        );
        let optimistic_message = (!is_command).then(|| OptimisticUserMessage {
            session_id: session_id.clone(),
            item_id: TimelineItemId::new(),
            after_sequence: self.session_view_end_sequence(&session_id).unwrap_or(0),
            submitted_at_ms: unix_timestamp_ms(),
            text: text.clone(),
            attachments: attachments.clone(),
        });
        self.set_session_turn_pending(&session_id, true);
        // The new user turn reactivates the session, so a pause that the user
        // installed while stopping or pausing auto-continue is lifted again —
        // unless the auto-continue preference itself was turned off.
        if self.auto_continue_enabled(&session_id) {
            self.resume_auto_continue(&session_id, cx);
        }
        if let Some(optimistic_message) = optimistic_message {
            self.install_optimistic_user_message(optimistic_message);
        }
        if self.view_session_id.as_ref() == Some(&session_id) {
            self.agent_error = None;
        }
        cx.notify();
        if !is_command {
            // Keep a durable-submission locator so background delivery and terminal
            // failure states remain reconciled even though transient states are hidden.
            self.composer_submission_locators
                .push(ComposerSubmissionLocator {
                    session_id: session_id.clone(),
                    message_idempotency_key: idempotency_key.clone(),
                });
            self.start_submission_poll(window, cx);
        }
        let submit_key = idempotency_key.clone();
        let reasoning_effort = selection.reasoning_effort.clone();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            let outcome = if let Some(invocation) = command_invocation {
                runtime
                    .agent()
                    .manager()
                    .execute_command(AgentCommandExecuteRequest {
                        session_id: session_id.clone(),
                        command_id: invocation.command_id,
                        trigger: invocation.trigger,
                        source_kind: invocation.source_kind,
                        command_text: invocation.command_text,
                        command_name: invocation.command_name,
                        arguments: invocation.arguments,
                        prompt_id: invocation.prompt_id,
                        attachments,
                        // Commands execute against the manager's durable effective
                        // runtime. Do not fence them with a composer snapshot that
                        // may have been superseded by runtime normalization.
                        reasoning_effort: None,
                        correlation_id: None,
                    })
                    .await
                    .map(|_| ())
            } else {
                runtime
                    .agent()
                    .message_submission()
                    .submit(SendAgentMessageRequest {
                        session_id: session_id.clone(),
                        message_idempotency_key: idempotency_key,
                        desired_runtime: selection,
                        text,
                        attachments,
                        reasoning_effort,
                        correlation_id: None,
                        delivery,
                    })
                    .await
                    .map(|_| ())
            };
            let session = runtime
                .agent()
                .manager()
                .get_session(&session_id)
                .await
                .ok();
            (outcome, session)
        });
        cx.spawn_in(window, async move |entity, cx| {
            let outcome = runner.await;
            let _ = entity.update_in(cx, |this, window, cx| {
                let completed = matches!(&outcome, Ok((Ok(_), _)));
                if let Ok((_, Some(session))) = &outcome {
                    this.upsert_session_snapshot(session.clone());
                    this.reconcile_sidebar_state();
                    this.publish_sidebar_invalidation();
                }
                if completed {
                    this.composer_submission_locators
                        .retain(|locator| locator.message_idempotency_key != submit_key);
                    this.composer_submission_states
                        .retain(|state| state.message_idempotency_key != submit_key);
                }
                this.set_session_turn_pending(&submitted_session_id, false);
                this.sync_auto_continue_for_session(&submitted_session_id, cx);
                let active = agent_turn_completion_is_active(
                    this.session_generation,
                    generation,
                    this.selected_session_id.as_ref(),
                    &submitted_session_id,
                );
                if active {
                    match &outcome {
                        Ok((Ok(_), _)) => this.refresh_selected_agent_timeline(cx),
                        Ok((Err(error), _))
                            if !is_command
                                && error.code == "message_submission_prompt_dispatch_ambiguous" =>
                        {
                            // The submission poll owns this presentation so the same
                            // delivery issue does not also become a persistent error row.
                        }
                        Ok((Err(error), _)) => {
                            this.agent_error = Some(format!("{}: {}", error.code, error.message));
                        }
                        Err(error) => {
                            this.agent_error = Some(format!(
                                "{} failed: {error}",
                                if is_command {
                                    "command execution"
                                } else {
                                    "message submission"
                                }
                            ));
                        }
                    }
                }
                let steering = this
                    .composer_queue_steering_session_ids
                    .remove(submitted_session_id.as_str());
                let interrupted = this
                    .composer_queue_interrupted_session_ids
                    .remove(submitted_session_id.as_str());
                if completed || steering || interrupted {
                    this.maybe_dispatch_next_composer_queue_message(
                        &submitted_session_id,
                        if steering {
                            ComposerQueueDispatchBehavior::AfterInterrupt
                        } else if completed {
                            // The submission has durably completed, but the
                            // sidebar session snapshot may still say Running
                            // until its next refresh. The local pending flag
                            // remains the completion fence.
                            ComposerQueueDispatchBehavior::AfterCompletion
                        } else {
                            ComposerQueueDispatchBehavior::Automatic
                        },
                        window,
                        cx,
                    );
                }
                // A failed or cancelled submission only skips this dispatch.
                // The queue stays armed (never paused) and is re-evaluated once
                // a later turn is confirmed to have completed normally.
                cx.notify();
            });
        })
        .detach();
    }

    /// Probes the latest turn outcome when the composer queue is waiting on an
    /// unobserved session revision. The probe caches the answer and marks the
    /// waiting queue for re-evaluation on the next frame, so a normal completion
    /// still advances the queue without user action.
    fn probe_composer_queue_turn_status(
        &mut self,
        session_id: &VibexSessionId,
        cx: &mut Context<Self>,
    ) {
        let Some(session_updated_at_ms) = self
            .sessions
            .iter()
            .find(|session| &session.id == session_id)
            .map(|session| session.updated_at_ms)
        else {
            return;
        };
        if self
            .cached_auto_continue_turn_status(session_id, session_updated_at_ms)
            .is_some()
        {
            return;
        }
        self.probe_auto_continue_turn_status(session_id.clone(), session_updated_at_ms, cx);
    }

    /// Dispatches the front queued message for `session_id` when the session is
    /// settled enough to accept it.
    ///
    /// Returns whether a message was handed to the submission path. Waiting for
    /// an unobserved or abnormal turn boundary never pauses the queue: the
    /// message is only deferred and the queue is re-evaluated once a later turn
    /// is confirmed to have completed normally. The paused state is reserved for
    /// an explicit user interrupt.
    fn maybe_dispatch_next_composer_queue_message(
        &mut self,
        session_id: &VibexSessionId,
        behavior: ComposerQueueDispatchBehavior,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> bool {
        let session = self
            .sessions
            .iter()
            .find(|session| &session.id == session_id);
        let session_state = session.map(|session| session.state);
        let cached_turn_status = session.and_then(|session| {
            self.cached_auto_continue_turn_status(session_id, session.updated_at_ms)
        });
        let waits_for_continuation = composer_queue_waits_for_continuation(
            behavior,
            session_state,
            cached_turn_status.map(|status| status.ended_normally),
        );
        if !composer_queue_dispatch_enabled(
            &self.composer_queue_manual_session_ids,
            session_id,
            behavior,
        ) || self.agent_action_pending
            || composer_queue_session_blocks_dispatch(
                behavior,
                self.session_turn_pending(session_id),
                session_state,
            )
            || waits_for_continuation
            || self
                .composer_queue_paused_session_ids
                .contains(session_id.as_str())
        {
            // An unobserved revision is not proof of a normal completion: probe
            // it so a later frame can release the queue once the latest turn is
            // known.
            if waits_for_continuation && cached_turn_status.is_none() {
                self.probe_composer_queue_turn_status(session_id, cx);
            }
            return false;
        }
        let Some(index) = self
            .composer_queue
            .iter()
            .position(|message| &message.session_id == session_id)
        else {
            return false;
        };
        let message = self.composer_queue.remove(index);
        self.dispatch_composer_message(message, behavior, window, cx);
        true
    }

    /// Re-evaluates armed auto-send queues whose latest turn outcome just became
    /// known. A queue the user paused by interrupting stays paused until they
    /// explicitly resume it; a queue that is still waiting is re-armed so a
    /// transient block (action lock, running turn) cannot strand it.
    fn flush_composer_queue_dispatches_after_continuation(
        &mut self,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let session_ids =
            std::mem::take(&mut self.composer_queue_ready_after_continuation_session_ids);
        for session_id in session_ids {
            let Ok(session_id) = VibexSessionId::parse(&session_id) else {
                continue;
            };
            let Some(session_state) = self
                .sessions
                .iter()
                .find(|session| session.id == session_id)
                .map(|session| session.state)
            else {
                continue;
            };
            if !self
                .composer_queue
                .iter()
                .any(|message| message.session_id == session_id)
            {
                continue;
            }
            if self
                .composer_queue_paused_session_ids
                .contains(session_id.as_str())
            {
                continue;
            }
            // Only the completion handoff may ignore a lagging `Running`
            // snapshot, because it just cleared the local turn-pending fence. A
            // background re-evaluation has no such proof, so it never pushes a
            // queued message into a turn that is genuinely still running.
            if !matches!(
                session_state,
                AgentSessionState::Idle | AgentSessionState::Error
            ) {
                continue;
            }
            let dispatched = self.maybe_dispatch_next_composer_queue_message(
                &session_id,
                ComposerQueueDispatchBehavior::AfterCompletion,
                window,
                cx,
            );
            let still_queued = self
                .composer_queue
                .iter()
                .any(|message| message.session_id == session_id);
            if !dispatched && still_queued {
                self.composer_queue_ready_after_continuation_session_ids
                    .insert(session_id.as_str().to_string());
            }
        }
    }

    fn begin_composer_queue_edit(
        &mut self,
        message_id: u64,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(message) = self
            .composer_queue
            .iter()
            .find(|message| message.id == message_id)
            .cloned()
        else {
            return;
        };
        let (text, attachments, serial) = composer_queue_edit_insertion(
            &message.text,
            &message.attachments,
            self.composer_attachment_serial,
        );
        self.composer_attachment_serial = serial;
        self.composer_queue_editing_id = Some(message_id);
        self.composer_queue_edit_attachments = attachments;
        self.composer_queue_edit_geometry.input_bounds = None;
        self.composer_queue_edit_input.update(cx, |input, cx| {
            input.set_value(text, window, cx);
            input.focus(window, cx);
        });
        cx.notify();
    }

    /// Opens the inline goal editor seeded with the live objective.
    ///
    /// Editing stays inside the goal bar: the composer keeps whatever draft the
    /// user was writing, and saving issues a goal control instead of a prompt.
    fn begin_composer_goal_edit(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some(active) = current_active_goal(&self.timeline.items) else {
            return;
        };
        let objective = active.goal.objective.clone();
        self.composer_goal_editing = true;
        self.composer_goal_edit_input.update(cx, |input, cx| {
            input.set_value(objective, window, cx);
            input.focus(window, cx);
        });
        cx.notify();
    }

    fn cancel_composer_goal_edit(&mut self, cx: &mut Context<Self>) {
        if !self.composer_goal_editing {
            return;
        }
        self.composer_goal_editing = false;
        cx.notify();
    }

    /// Applies the edited objective through the goal control surface.
    ///
    /// `set` re-objectives the goal on the neutral surface; adapters that spell
    /// it `edit` are honored when they advertise only that verb.
    fn save_composer_goal_edit(&mut self, cx: &mut Context<Self>) {
        if !self.composer_goal_editing {
            return;
        }
        let objective = self
            .composer_goal_edit_input
            .read(cx)
            .value()
            .trim()
            .to_string();
        if objective.is_empty() {
            return;
        }
        let Some(active) = current_active_goal(&self.timeline.items) else {
            self.composer_goal_editing = false;
            cx.notify();
            return;
        };
        let action = if active.actions.contains(&GoalAction::Set) {
            GoalAction::Set
        } else if active.actions.contains(&GoalAction::Edit) {
            GoalAction::Edit
        } else {
            return;
        };
        self.composer_goal_editing = false;
        self.control_session_goal(action, Some(objective), cx);
    }

    fn save_composer_queue_edit(&mut self, cx: &mut Context<Self>) {
        let Some(message_id) = self.composer_queue_editing_id else {
            return;
        };
        let raw_text = self.composer_queue_edit_input.read(cx).value().to_string();
        let (text, attachments) =
            composer_submission_payload(&raw_text, &self.composer_queue_edit_attachments);
        let Some(message) = self
            .composer_queue
            .iter_mut()
            .find(|message| message.id == message_id)
        else {
            self.composer_queue_editing_id = None;
            self.composer_queue_edit_attachments.clear();
            self.composer_queue_edit_geometry.input_bounds = None;
            cx.notify();
            return;
        };
        if text.trim().is_empty() && attachments.is_empty() {
            return;
        }
        message.text = text;
        message.attachments = attachments;
        message.command_invocation = None;
        self.composer_queue_editing_id = None;
        self.composer_queue_edit_attachments.clear();
        self.composer_queue_edit_geometry.input_bounds = None;
        cx.notify();
    }

    fn cancel_composer_queue_edit(&mut self, cx: &mut Context<Self>) {
        self.composer_queue_editing_id = None;
        self.composer_queue_edit_attachments.clear();
        self.composer_queue_edit_geometry.input_bounds = None;
        cx.notify();
    }

    fn render_composer_queue_attachment_chip(
        &self,
        message_id: u64,
        attachment_index: usize,
        attachment: &MessageAttachment,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let composer_attachment = composer_attachment_from_message(
            attachment,
            format!("queue-attachment:{message_id}:{attachment_index}"),
        );
        let is_image = composer_attachment.is_image();
        let label = if attachment.label.trim().is_empty() {
            locale::text_for(self.resolved_locale(), "Image", "图片", "圖片").to_string()
        } else {
            attachment.label.clone()
        };
        let tooltip = if is_image {
            locale::text("Preview image", "预览图片", "預覽圖片")
        } else {
            locale::text("Open attachment", "打开附件", "開啟附件")
        };
        let preview_attachment = composer_attachment.clone();
        let tab_path = (!is_image)
            .then(|| self.composer_attachment_tab_path(&composer_attachment))
            .flatten();
        let chip = h_flex()
            .id(format!(
                "composer-queue-attachment-{message_id}-{attachment_index}"
            ))
            .flex_none()
            .min_w_0()
            .max_w(px(180.0))
            .h(px(24.0))
            .items_center()
            .gap(px(5.5))
            .overflow_hidden()
            .rounded(px(6.0))
            .border_1()
            .border_color(cx.theme().border)
            .bg(cx.theme().muted)
            .px(px(7.0))
            .text_xs()
            .font_weight(FontWeight(600.0))
            .text_color(cx.theme().foreground)
            .aria_label(tooltip)
            .child(
                if is_image {
                    Icon::default().path("icons/vibex/image.svg")
                } else {
                    Icon::new(IconName::File)
                }
                .size(px(13.0))
                .text_color(cx.theme().foreground.opacity(0.80)),
            )
            .child(div().min_w_0().flex_1().truncate().child(label));
        if is_image {
            chip.cursor_pointer()
                .on_click(cx.listener(move |this, _, window, cx| {
                    this.open_attachment_preview(preview_attachment.clone(), true, window, cx)
                }))
                .into_any_element()
        } else if tab_path.is_some() {
            let tab_attachment = composer_attachment.clone();
            chip.cursor_pointer()
                .on_click(cx.listener(move |this, _, window, cx| {
                    this.open_composer_attachment_in_tab(&tab_attachment, window, cx)
                }))
                .into_any_element()
        } else {
            chip.into_any_element()
        }
    }

    fn render_composer_queue_inline_content(
        &self,
        message_id: u64,
        text: &str,
        attachments: &[MessageAttachment],
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let mut used_attachments = vec![false; attachments.len()];
        let mut content = h_flex()
            .min_w_0()
            .flex_1()
            .flex_wrap()
            .items_center()
            .gap_1();

        for segment in user_message_inline_segments(text, attachments) {
            match segment {
                UserMessageInlineSegment::Text(value) if !value.is_empty() => {
                    content = content.child(
                        div()
                            .min_w_0()
                            .max_w_full()
                            .flex_shrink(1.0)
                            .text_sm()
                            .line_height(gpui::relative(1.5))
                            .whitespace_normal()
                            .overflow_hidden()
                            .child(value),
                    );
                }
                UserMessageInlineSegment::Attachment(attachment) => {
                    let Some(attachment_index) =
                        attachments
                            .iter()
                            .enumerate()
                            .find_map(|(index, candidate)| {
                                (!used_attachments[index] && candidate == &attachment)
                                    .then_some(index)
                            })
                    else {
                        continue;
                    };
                    used_attachments[attachment_index] = true;
                    content = content.child(self.render_composer_queue_attachment_chip(
                        message_id,
                        attachment_index,
                        &attachment,
                        cx,
                    ));
                }
                UserMessageInlineSegment::Text(_) => {}
            }
        }

        // The three-line preview viewport clips long messages; hovering the
        // content lets the wheel scroll the remaining lines into view.
        div()
            .id(format!("composer-queue-content-{message_id}"))
            .min_w_0()
            .flex_1()
            .max_h(px(COMPOSER_QUEUE_PREVIEW_MAX_HEIGHT))
            .overflow_hidden()
            .overflow_y_scroll()
            .child(content)
            .into_any_element()
    }

    fn delete_composer_queue_message(
        &mut self,
        message_id: u64,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(index) = self
            .composer_queue
            .iter()
            .position(|message| message.id == message_id)
        else {
            return;
        };
        let session_id = self.composer_queue[index].session_id.clone();
        self.composer_queue.remove(index);
        if self.composer_queue_editing_id == Some(message_id) {
            self.composer_queue_editing_id = None;
            self.composer_queue_edit_attachments.clear();
            self.composer_queue_edit_geometry.input_bounds = None;
        }
        if !self
            .composer_queue
            .iter()
            .any(|message| message.session_id == session_id)
        {
            self.composer_queue_paused_session_ids
                .remove(session_id.as_str());
            self.composer_queue_ready_after_continuation_session_ids
                .remove(session_id.as_str());
        } else {
            self.maybe_dispatch_next_composer_queue_message(
                &session_id,
                ComposerQueueDispatchBehavior::Automatic,
                window,
                cx,
            );
        }
        cx.notify();
    }

    fn move_composer_queue_message_relative(
        &mut self,
        message_id: u64,
        target_id: u64,
        after: bool,
        cx: &mut Context<Self>,
    ) {
        if reorder_composer_queue_message(&mut self.composer_queue, message_id, target_id, after) {
            cx.notify();
        }
    }

    fn move_composer_queue_message_to_front(&mut self, message_id: u64) -> Option<VibexSessionId> {
        promote_composer_queue_message(&mut self.composer_queue, message_id)
    }

    fn resume_composer_queue(
        &mut self,
        session_id: VibexSessionId,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.composer_queue_paused_session_ids
            .remove(session_id.as_str());
        self.maybe_dispatch_next_composer_queue_message(
            &session_id,
            ComposerQueueDispatchBehavior::ForceNext,
            window,
            cx,
        );
        cx.notify();
    }

    fn steer_composer_queue_message(
        &mut self,
        message_id: u64,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(session_id) = self.move_composer_queue_message_to_front(message_id) else {
            return;
        };
        self.composer_queue_paused_session_ids
            .remove(session_id.as_str());
        if self.agent_session_is_active(&session_id) {
            if !self.agent_action_pending && self.selected_session_id.as_ref() == Some(&session_id)
            {
                self.interrupt_session_with_queue_behavior(
                    ComposerQueueInterruptBehavior::Steer,
                    window,
                    cx,
                );
            }
        } else {
            self.maybe_dispatch_next_composer_queue_message(
                &session_id,
                ComposerQueueDispatchBehavior::ForceNext,
                window,
                cx,
            );
        }
        cx.notify();
    }

    fn toggle_composer_queue_send_mode(
        &mut self,
        session_id: VibexSessionId,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if composer_queue_auto_send_enabled(&self.composer_queue_manual_session_ids, &session_id) {
            self.composer_queue_manual_session_ids
                .insert(session_id.as_str().to_string());
        } else {
            self.composer_queue_manual_session_ids
                .remove(session_id.as_str());
            self.maybe_dispatch_next_composer_queue_message(
                &session_id,
                ComposerQueueDispatchBehavior::Automatic,
                window,
                cx,
            );
        }
        cx.notify();
    }

    fn clear_composer_queue(&mut self, session_id: VibexSessionId, cx: &mut Context<Self>) {
        let editing_id = self.composer_queue_editing_id;
        self.composer_queue
            .retain(|message| message.session_id != session_id);
        if editing_id.is_some_and(|message_id| {
            !self
                .composer_queue
                .iter()
                .any(|message| message.id == message_id)
        }) {
            self.composer_queue_editing_id = None;
            self.composer_queue_edit_attachments.clear();
            self.composer_queue_edit_geometry.input_bounds = None;
        }
        self.composer_queue_drop_target = None;
        self.composer_queue_paused_session_ids
            .remove(session_id.as_str());
        self.composer_queue_ready_after_continuation_session_ids
            .remove(session_id.as_str());
        self.composer_queue_interrupted_session_ids
            .remove(session_id.as_str());
        self.composer_queue_steering_session_ids
            .remove(session_id.as_str());
        cx.notify();
    }

    fn start_submission_poll(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if self.submission_poll_task.is_some() {
            return;
        }
        self.submission_poll_task = Some(cx.spawn_in(
            window,
            async move |entity: WeakEntity<Self>, cx| {
                loop {
                    cx.background_executor()
                        .timer(SUBMISSION_POLL_INTERVAL)
                        .await;
                    let Ok(gathered) = entity.update_in(cx, |this, _, _| {
                        if this.composer_submission_locators.is_empty() {
                            return None;
                        }
                        // The submission record lives with whichever runtime
                        // accepted the message, so the poll asks the backend.
                        let backend = this.backend.clone()?;
                        let session_id = this.selected_session_id.clone()?;
                        let locators = this
                            .composer_submission_locators
                            .iter()
                            .filter(|locator| locator.session_id == session_id)
                            .cloned()
                            .collect::<Vec<_>>();
                        Some((backend, locators))
                    }) else {
                        break;
                    };
                    let Some((backend, locators)) = gathered else {
                        let stop = entity
                            .update_in(cx, |this, _, _| {
                                this.composer_submission_locators.is_empty()
                            })
                            .unwrap_or(true);
                        if stop {
                            break;
                        }
                        continue;
                    };
                    if locators.is_empty() {
                        continue;
                    }
                    let Ok(fetch) = entity.update_in(cx, |_, _, cx| {
                        gpui_tokio::Tokio::spawn(cx, async move {
                            let mut states = Vec::new();
                            for locator in locators {
                                if let Ok(state) = backend
                                    .agent()
                                    .agent_message_submission(GetMessageSubmissionRequest {
                                        session_id: locator.session_id.clone(),
                                        message_idempotency_key: locator
                                            .message_idempotency_key
                                            .clone(),
                                    })
                                    .await
                                {
                                    states.push(state);
                                }
                            }
                            states
                        })
                    }) else {
                        break;
                    };
                    let Ok(states) = fetch.await else {
                        continue;
                    };
                    if entity
                        .update_in(cx, |this, window, cx| {
                            this.apply_submission_states(states, window, cx)
                        })
                        .is_err()
                    {
                        break;
                    }
                }
                let _ = entity.update_in(cx, |this, _, _| {
                    this.submission_poll_task = None;
                });
            },
        ));
    }

    fn apply_submission_states(
        &mut self,
        states: Vec<MessageSubmissionState>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let mut completed_session_ids = BTreeSet::new();
        let mut ambiguous_any = false;
        for state in &states {
            if matches!(
                state.status,
                MessageSubmissionStatus::Completed
                    | MessageSubmissionStatus::AmbiguousPromptDispatch
            ) || composer_submission_failure_reached_provider(state)
            {
                self.composer_submission_locators.retain(|locator| {
                    !(locator.session_id == state.session_id
                        && locator.message_idempotency_key == state.message_idempotency_key)
                });
            }
            if state.status == MessageSubmissionStatus::Completed {
                completed_session_ids.insert(state.session_id.as_str().to_string());
            }
            ambiguous_any |= state.status == MessageSubmissionStatus::AmbiguousPromptDispatch;
        }
        if ambiguous_any {
            window.push_notification(
                hint_notification(
                    NotificationType::Warning,
                    ambiguous_message_submission_notice(),
                    cx,
                )
                .id::<AmbiguousMessageSubmissionNotification>()
                .autohide(true)
                .on_click(|_, _, _| {}),
                cx,
            );
        }
        let mut visible = states
            .into_iter()
            .filter(|state| {
                !matches!(
                    state.status,
                    MessageSubmissionStatus::Completed
                        | MessageSubmissionStatus::AmbiguousPromptDispatch
                ) && !composer_submission_failure_reached_provider(state)
            })
            .collect::<Vec<_>>();
        visible.sort_by_key(|state| state.submission_sequence);
        if self.composer_submission_states != visible {
            self.composer_submission_states = visible;
            cx.notify();
        }
        let selected_session_completed = self
            .selected_session_id
            .as_ref()
            .is_some_and(|session_id| completed_session_ids.contains(session_id.as_str()));
        if selected_session_completed {
            self.timeline.mark_lagged();
            if self.ui_state.workbench.active_tab == "agent" && !self.new_session_open {
                self.refresh_selected_agent_timeline(cx);
            }
        }
        if !completed_session_ids.is_empty() {
            cx.notify();
        }
    }

    fn dismiss_submission_status(
        &mut self,
        message_idempotency_key: String,
        cx: &mut Context<Self>,
    ) {
        self.composer_submission_locators
            .retain(|locator| locator.message_idempotency_key != message_idempotency_key);
        self.composer_submission_states
            .retain(|state| state.message_idempotency_key != message_idempotency_key);
        cx.notify();
    }

    fn submission_runtime_label(&self, selection: &SessionRuntimeSelection) -> String {
        self.runtime_catalog
            .as_ref()
            .and_then(|catalog| {
                catalog.options.iter().find(|option| {
                    option.selection.agent_id == selection.agent_id
                        && option.selection.auth_source == selection.auth_source
                        && option.selection.model == selection.model
                })
            })
            .map(|option| {
                format!(
                    "{} / {} / {}",
                    option.agent_label,
                    runtime_auth_source_selection_label(
                        &selection.auth_source,
                        &option.auth_source_label,
                    ),
                    option.model_label
                )
            })
            .unwrap_or_else(|| {
                format!(
                    "{} / {} / {}",
                    selection.agent_id.as_str(),
                    selection.auth_source.id(),
                    runtime_model_selection_label(&selection.model)
                )
            })
    }

    fn render_submission_statuses(&self, cx: &mut Context<Self>) -> Option<AnyElement> {
        let session_id = self.selected_session_id.clone()?;
        let rows = self
            .composer_submission_states
            .iter()
            .filter(|state| state.session_id == session_id)
            // Transient queue/dispatch states are already represented by the
            // pending composer action. Only keep actionable terminal outcomes
            // visible in the composer area.
            .filter(|state| composer_submission_status_is_actionable(state.status))
            // Post-dispatch failures were delivered; the timeline (with
            // auto-continue) owns them, so only genuinely unsent messages
            // surface here.
            .filter(|state| !composer_submission_failure_reached_provider(state))
            .cloned()
            .collect::<Vec<_>>();
        if rows.is_empty() {
            return None;
        }
        Some(
            v_flex()
                .w_full()
                .min_w_0()
                .gap(px(6.0))
                .children(rows.into_iter().map(|state| {
                    let terminal = state.status == MessageSubmissionStatus::Cancelled;
                    let label = match state.status {
                        MessageSubmissionStatus::AwaitingRuntime
                        | MessageSubmissionStatus::ReadyToDispatch => {
                            let runtime_label =
                                self.submission_runtime_label(&state.desired_runtime);
                            match self.resolved_locale() {
                                locale::ResolvedLocale::En => {
                                    format!("Queued for {runtime_label}")
                                }
                                locale::ResolvedLocale::ZhCn => {
                                    format!("已排队，目标为 {runtime_label}")
                                }
                                locale::ResolvedLocale::ZhTw => {
                                    format!("已排隊，目標為 {runtime_label}")
                                }
                            }
                        }
                        MessageSubmissionStatus::AboutToPrompt
                        | MessageSubmissionStatus::Dispatched => {
                            locale::text("Sending", "正在发送", "正在傳送").to_string()
                        }
                        _ => locale::text("Message was not sent", "消息未发送", "訊息未傳送")
                            .to_string(),
                    };
                    let dismiss_key = state.message_idempotency_key.clone();
                    h_flex()
                        .w_full()
                        .min_w_0()
                        .min_h(px(32.0))
                        .items_center()
                        .gap_2()
                        .rounded(px(6.0))
                        .border_1()
                        .border_color(cx.theme().border.opacity(0.7))
                        .bg(cx.theme().muted.opacity(0.25))
                        .px(px(10.0))
                        .py(px(6.0))
                        .text_xs()
                        .child(if terminal {
                            Icon::default()
                                .path("icons/vibex/shield-alert.svg")
                                .size(px(14.0))
                                .text_color(cx.theme().danger)
                                .into_any_element()
                        } else {
                            Spinner::new()
                                .icon(Icon::new(IconName::LoaderCircle))
                                .color(cx.theme().muted_foreground)
                                .xsmall()
                                .into_any_element()
                        })
                        .child(
                            div()
                                .min_w_0()
                                .flex_1()
                                .text_color(cx.theme().muted_foreground)
                                .child(label),
                        )
                        .when(terminal, |this| {
                            this.child(
                                Button::new(SharedString::from(format!(
                                    "dismiss-submission-{}",
                                    state.message_idempotency_key
                                )))
                                .xsmall()
                                .ghost()
                                .compact()
                                .size(px(24.0))
                                .icon(IconName::Close)
                                .tooltip(locale::text(
                                    "Dismiss submission status",
                                    "关闭提交状态",
                                    "關閉提交狀態",
                                ))
                                .on_click(cx.listener(
                                    move |this, _, _, cx| {
                                        this.dismiss_submission_status(dismiss_key.clone(), cx)
                                    },
                                )),
                            )
                        })
                        .into_any_element()
                }))
                .into_any_element(),
        )
    }

    fn sync_inline_composer_attachments(&mut self, new_session: bool, cx: &App) {
        // InputState owns undo/redo history for the marker text. Keep attachment
        // metadata while editing so undoing a deletion can restore its overlay;
        // submission and draft persistence filter metadata against current text.
        let _ = (new_session, cx);
    }

    fn add_user_message_edit_path(
        &mut self,
        path: &std::path::Path,
        label: Option<String>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> bool {
        let serial = self.composer_attachment_serial.saturating_add(1);
        self.composer_attachment_serial = serial;
        let Some(edit) = self.view.inline_user_message_edit.as_mut() else {
            return false;
        };
        let label = label.unwrap_or_else(|| {
            path.file_name()
                .and_then(|name| name.to_str())
                .unwrap_or("attachment")
                .to_string()
        });
        let marker = inline_composer_attachment_marker(serial);
        edit.attachments.push(InlineComposerAttachment {
            attachment: ComposerAttachment {
                id: format!("attachment:{serial}"),
                label,
                path: Some(path.to_string_lossy().into_owned()),
                mime_type: attachment_mime_type(path),
            },
            marker: marker.clone(),
        });
        self.user_message_edit_input.update(cx, |input, cx| {
            input.replace(inline_composer_attachment_insertion(&marker), window, cx);
            input.focus(window, cx);
        });
        cx.notify();
        true
    }

    fn add_user_message_edit_image(
        &mut self,
        image: &Image,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> bool {
        match self.persist_composer_image(image) {
            Ok(path) => self.add_user_message_edit_path(
                &path,
                Some(format!(
                    "{}.{}",
                    locale::text("Pasted image", "粘贴的图片", "貼上的圖片"),
                    image.format().extension()
                )),
                window,
                cx,
            ),
            Err(error) => {
                self.agent_error = Some(format!("clipboard image capture failed: {error}"));
                cx.notify();
                false
            }
        }
    }

    fn add_user_message_edit_clipboard(
        &mut self,
        clipboard: VibexMessageClipboard,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> bool {
        if !clipboard.is_supported() {
            return false;
        }
        let Some((insertion, attachments, serial)) = vibex_message_composer_insertion(
            &clipboard.text,
            &clipboard.attachments,
            self.composer_attachment_serial,
        ) else {
            return false;
        };
        self.composer_attachment_serial = serial;
        let Some(edit) = self.view.inline_user_message_edit.as_mut() else {
            return false;
        };
        edit.attachments.extend(attachments);
        self.user_message_edit_input.update(cx, |input, cx| {
            input.replace(insertion, window, cx);
            input.focus(window, cx);
        });
        cx.notify();
        true
    }

    fn add_composer_path(
        &mut self,
        path: &std::path::Path,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.add_composer_path_to(path, None, self.new_session_open, window, cx);
    }

    fn add_composer_path_to(
        &mut self,
        path: &std::path::Path,
        label: Option<String>,
        new_session: bool,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let label = label.unwrap_or_else(|| {
            path.file_name()
                .and_then(|name| name.to_str())
                .unwrap_or("attachment")
                .to_string()
        });
        let path_string = path.to_string_lossy().to_string();
        let mime_type = attachment_mime_type(path);
        self.composer_attachment_serial = self.composer_attachment_serial.saturating_add(1);
        let serial = self.composer_attachment_serial;
        let marker = inline_composer_attachment_marker(serial);
        let inline_attachment = InlineComposerAttachment {
            attachment: ComposerAttachment {
                id: format!("attachment:{serial}"),
                label,
                path: Some(path_string),
                mime_type,
            },
            marker: marker.clone(),
        };
        let input = if new_session {
            self.new_session_attachments.push(inline_attachment);
            self.new_session_input.clone()
        } else {
            self.composer_attachments.push(inline_attachment);
            self.ensure_composer_input(window, cx)
        };
        input.update(cx, |input, cx| {
            input.replace(inline_composer_attachment_insertion(&marker), window, cx);
            input.focus(window, cx);
        });
        cx.notify();
    }

    fn add_composer_paths(
        &mut self,
        paths: &ExternalPaths,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        for path in paths.paths() {
            self.add_composer_path(path, window, cx);
        }
        cx.notify();
    }

    fn persist_composer_image(&self, image: &Image) -> std::io::Result<std::path::PathBuf> {
        const MAX_CLIPBOARD_IMAGE_BYTES: usize = 32 * 1024 * 1024;
        if image.bytes().is_empty() {
            return Err(std::io::Error::new(
                std::io::ErrorKind::InvalidData,
                "clipboard image is empty",
            ));
        }
        if image.bytes().len() > MAX_CLIPBOARD_IMAGE_BYTES {
            return Err(std::io::Error::new(
                std::io::ErrorKind::InvalidData,
                "clipboard image exceeds 32 MiB",
            ));
        }
        let Some(config) = self.config.as_ref() else {
            return Err(std::io::Error::new(
                std::io::ErrorKind::NotFound,
                "isolated desktop home is unavailable",
            ));
        };
        let root = config.home_dir.join("clipboard-attachments");
        std::fs::create_dir_all(&root)?;
        let digest = Sha256::digest(image.bytes());
        let digest = digest
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<String>();
        let destination = root.join(format!(
            "clipboard-image-{digest}.{}",
            image.format().extension()
        ));
        if !destination.exists() {
            std::fs::write(&destination, image.bytes())?;
        }
        Ok(destination)
    }

    fn add_composer_image_to(
        &mut self,
        image: &Image,
        new_session: bool,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        match self.persist_composer_image(image) {
            Ok(path) => self.add_composer_path_to(
                &path,
                Some(format!(
                    "{}.{}",
                    locale::text("Pasted image", "粘贴的图片", "貼上的圖片"),
                    image.format().extension()
                )),
                new_session,
                window,
                cx,
            ),
            Err(error) => {
                let message = format!("clipboard image capture failed: {error}");
                if new_session {
                    self.new_session_error = Some(message);
                } else {
                    self.agent_error = Some(message);
                }
            }
        }
        cx.notify();
    }

    fn add_composer_html_data_image(
        &mut self,
        html: &str,
        new_session: bool,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> bool {
        let Some((format, bytes)) = decode_html_data_image(html) else {
            return false;
        };
        self.add_composer_image_to(&Image::from_bytes(format, bytes), new_session, window, cx);
        true
    }

    fn add_vibex_message_clipboard_to(
        &mut self,
        clipboard: VibexMessageClipboard,
        new_session: bool,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> bool {
        if !clipboard.is_supported() {
            return false;
        }
        let Some((insertion, attachments, serial)) = vibex_message_composer_insertion(
            &clipboard.text,
            &clipboard.attachments,
            self.composer_attachment_serial,
        ) else {
            return false;
        };
        self.composer_attachment_serial = serial;
        let input = if new_session {
            self.new_session_attachments.extend(attachments);
            self.new_session_input.clone()
        } else {
            self.composer_attachments.extend(attachments);
            self.ensure_composer_input(window, cx)
        };
        input.update(cx, |input, cx| {
            input.replace(insertion, window, cx);
            input.focus(window, cx);
        });
        cx.notify();
        true
    }

    fn paste_composer_clipboard_to(
        &mut self,
        new_session: bool,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> bool {
        let Some(clipboard) = cx.read_from_clipboard() else {
            return false;
        };
        let mut captured = false;
        for entry in clipboard.into_entries() {
            match entry {
                ClipboardEntry::Image(image) => {
                    self.add_composer_image_to(&image, new_session, window, cx);
                    captured = true;
                }
                ClipboardEntry::ExternalPaths(paths) => {
                    for path in paths.paths() {
                        self.add_composer_path_to(path, None, new_session, window, cx);
                    }
                    captured = true;
                }
                ClipboardEntry::String(string) => {
                    if let Some(metadata) = string.metadata_json::<VibexMessageClipboard>()
                        && self.add_vibex_message_clipboard_to(metadata, new_session, window, cx)
                    {
                        captured = true;
                        continue;
                    }
                    captured |=
                        self.add_composer_html_data_image(&string.text, new_session, window, cx);
                    if let Some(metadata) = string.metadata.as_deref() {
                        captured |=
                            self.add_composer_html_data_image(metadata, new_session, window, cx);
                    }
                }
            }
        }
        captured
    }

    fn choose_composer_attachments(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if self.composer_attachment_task.is_some() {
            return;
        }
        let new_session = self.new_session_open;
        let picker = gpui_tokio::Tokio::spawn(cx, async move {
            rfd::AsyncFileDialog::new()
                .set_title(locale::text("Attach files", "添加附件", "新增附件"))
                .pick_files()
                .await
        });
        self.composer_attachment_task = Some(cx.spawn_in(window, async move |entity, cx| {
            let paths = picker.await.ok().flatten();
            let _ = entity.update_in(cx, |this, window, cx| {
                this.composer_attachment_task = None;
                if let Some(paths) = paths {
                    for path in paths {
                        this.add_composer_path_to(path.path(), None, new_session, window, cx);
                    }
                }
                cx.notify();
            });
        }));
    }

    fn choose_attachment_save_copy(
        &mut self,
        source: String,
        label: String,
        cx: &mut Context<Self>,
    ) {
        if self.composer_attachment_task.is_some() {
            return;
        }
        let suggested_name = safe_attachment_file_name(&label, &source);
        let save_task = gpui_tokio::Tokio::spawn(cx, async move {
            let destination = rfd::AsyncFileDialog::new()
                .set_title("Save image")
                .set_file_name(&suggested_name)
                .save_file()
                .await;
            let Some(destination) = destination else {
                return Ok(None);
            };
            std::fs::copy(&source, destination.path())?;
            Ok::<_, std::io::Error>(Some(destination.path().to_path_buf()))
        });
        self.composer_attachment_task = Some(cx.spawn(async move |entity, cx| {
            let outcome = save_task.await;
            let _ = entity.update(cx, |this, cx| {
                this.composer_attachment_task = None;
                match outcome {
                    Ok(Ok(Some(destination))) => {
                        this.persistence_note = Some(format!(
                            "Saved image copy to {}",
                            destination.to_string_lossy()
                        ));
                    }
                    Ok(Ok(None)) => {}
                    Ok(Err(error)) => {
                        this.agent_error = Some(format!("image save failed: {error}"));
                    }
                    Err(error) => {
                        this.agent_error = Some(format!("image save task failed: {error}"));
                    }
                }
                cx.notify();
            });
        }));
    }

    fn open_attachment_preview(
        &mut self,
        attachment: ComposerAttachment,
        editable: bool,
        _window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(path) = attachment.path.clone().filter(|_| attachment.is_image()) else {
            return;
        };
        let Some(_format) =
            attachment_preview_image_format(Path::new(&path), attachment.mime_type.as_deref())
        else {
            return;
        };
        let edit_buffer = editable
            .then(|| {
                decode_attachment_editor_image(Path::new(&path))
                    .ok()
                    .map(Arc::new)
            })
            .flatten();
        let can_edit = editable && edit_buffer.is_some();
        let confirmed_image = edit_buffer.as_ref().and_then(|buffer| {
            encode_editor_image(buffer)
                .ok()
                .map(|bytes| Arc::new(Image::from_bytes(ImageFormat::Png, bytes)))
        });
        let intrinsic_size = image::image_dimensions(&path).ok();
        self.attachment_image_preview = Some(AttachmentImagePreviewState {
            attachment,
            image_source: Arc::<std::path::Path>::from(
                std::path::PathBuf::from(path).into_boxed_path(),
            ),
            confirmed_image,
            edited_image: None,
            edit_buffer,
            edit_session: None,
            intrinsic_size,
            zoom: 1.0,
            pan_x: 0.0,
            pan_y: 0.0,
            drag: None,
            editable: can_edit,
            editing: false,
            tool: ImageEditTool::Brush,
            edit_drag: None,
            edit_drag_base: None,
        });
        self.composer_runtime_menu_open = false;
        cx.notify();
    }

    fn toggle_attachment_editor(&mut self, cx: &mut Context<Self>) {
        let Some(preview) = self.attachment_image_preview.as_ref() else {
            return;
        };
        if !preview.editable {
            return;
        }
        if preview.editing {
            let Some(session) = preview.edit_session.as_ref() else {
                return;
            };
            let changed = preview
                .edit_buffer
                .as_deref()
                .is_none_or(|confirmed| confirmed != session.current());
            if !changed {
                if let Some(preview) = self.attachment_image_preview.as_mut() {
                    preview.edit_session = None;
                    preview.edited_image = preview.confirmed_image.clone();
                    preview.editing = false;
                    preview.edit_drag = None;
                    preview.edit_drag_base = None;
                    preview.drag = None;
                }
                cx.notify();
                return;
            }
            let buffer = session.current_clone();
            if !self.commit_attachment_editor_buffer(buffer, cx) {
                return;
            }
        } else {
            let Some(buffer) = preview.edit_buffer.as_deref().cloned() else {
                return;
            };
            if let Some(preview) = self.attachment_image_preview.as_mut() {
                preview.edit_session = Some(Arc::new(ImageEditSession::new(buffer)));
                preview.editing = true;
                preview.edited_image = preview.confirmed_image.clone();
                preview.edit_drag = None;
                preview.edit_drag_base = None;
                preview.drag = None;
            }
        }
        cx.notify();
    }

    fn cancel_attachment_editor(&mut self, cx: &mut Context<Self>) {
        let viewport_width = self.last_visibility.layout.viewport_width as f32;
        let viewport_height = self.last_visibility.layout.viewport_height as f32;
        let Some(preview) = self.attachment_image_preview.as_mut() else {
            return;
        };
        if !preview.editing {
            return;
        }
        preview.edit_session = None;
        preview.edited_image = preview.confirmed_image.clone();
        preview.intrinsic_size = preview
            .edit_buffer
            .as_deref()
            .map(|image| image.dimensions());
        preview.editing = false;
        preview.edit_drag = None;
        preview.edit_drag_base = None;
        preview.drag = None;
        let layout = attachment_image_preview_layout(
            preview.intrinsic_size,
            preview.zoom,
            viewport_width,
            viewport_height,
        );
        (preview.pan_x, preview.pan_y) = layout.clamp_pan(preview.pan_x, preview.pan_y);
        cx.notify();
    }

    fn update_attachment_editor_render(&mut self, cx: &mut Context<Self>) {
        let Some(buffer) = self.attachment_image_preview.as_ref().and_then(|preview| {
            preview
                .edit_session
                .as_ref()
                .map(|session| session.current_clone())
        }) else {
            return;
        };
        let Ok(bytes) = encode_editor_image(&buffer) else {
            self.agent_error = Some(
                locale::text(
                    "Edited image could not be encoded",
                    "编辑后的图片无法编码",
                    "編輯後的圖片無法編碼",
                )
                .to_string(),
            );
            cx.notify();
            return;
        };
        let image = Arc::new(Image::from_bytes(ImageFormat::Png, bytes));
        let dimensions = buffer.dimensions();
        let viewport_width = self.last_visibility.layout.viewport_width as f32;
        let viewport_height = self.last_visibility.layout.viewport_height as f32;
        if let Some(preview) = self.attachment_image_preview.as_mut() {
            preview.edited_image = Some(image);
            preview.intrinsic_size = Some(dimensions);
            let layout = attachment_image_preview_layout(
                preview.intrinsic_size,
                preview.zoom,
                viewport_width,
                viewport_height,
            );
            (preview.pan_x, preview.pan_y) = layout.clamp_pan(preview.pan_x, preview.pan_y);
        }
        cx.notify();
    }

    fn undo_attachment_edit(&mut self, cx: &mut Context<Self>) {
        let changed = self
            .attachment_image_preview
            .as_mut()
            .filter(|preview| preview.editing)
            .and_then(|preview| {
                preview.edit_drag = None;
                preview.edit_drag_base = None;
                preview
                    .edit_session
                    .as_mut()
                    .map(|session| Arc::make_mut(session).undo())
            })
            .unwrap_or(false);
        if changed {
            self.update_attachment_editor_render(cx);
        }
    }

    fn redo_attachment_edit(&mut self, cx: &mut Context<Self>) {
        let changed = self
            .attachment_image_preview
            .as_mut()
            .filter(|preview| preview.editing)
            .and_then(|preview| {
                preview.edit_drag = None;
                preview.edit_drag_base = None;
                preview
                    .edit_session
                    .as_mut()
                    .map(|session| Arc::make_mut(session).redo())
            })
            .unwrap_or(false);
        if changed {
            self.update_attachment_editor_render(cx);
        }
    }

    /// The undo/redo chords stay shared with the text input, so the image editor only claims them
    /// while the overlay is in editing mode and its caption field does not hold focus.
    fn attachment_edit_shortcuts_active(&self, window: &Window, cx: &App) -> bool {
        self.attachment_image_preview
            .as_ref()
            .is_some_and(|preview| preview.editing)
            && !self
                .image_editor_text_input
                .read(cx)
                .focus_handle(cx)
                .is_focused(window)
    }

    fn on_undo_image_edit(
        &mut self,
        _: &UndoImageEdit,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if !self.attachment_edit_shortcuts_active(window, cx) {
            cx.propagate();
            return;
        }
        self.undo_attachment_edit(cx);
    }

    fn on_redo_image_edit(
        &mut self,
        _: &RedoImageEdit,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if !self.attachment_edit_shortcuts_active(window, cx) {
            cx.propagate();
            return;
        }
        self.redo_attachment_edit(cx);
    }

    fn select_attachment_edit_tool(&mut self, tool: ImageEditTool, cx: &mut Context<Self>) {
        let Some(preview) = self.attachment_image_preview.as_mut() else {
            return;
        };
        if preview.editable && preview.editing {
            preview.tool = tool;
            preview.edit_drag = None;
            cx.notify();
        }
    }

    fn attachment_preview_point(
        &self,
        preview: &AttachmentImagePreviewState,
        pointer_x: f32,
        pointer_y: f32,
    ) -> Option<(u32, u32)> {
        let (source_width, source_height) = preview.intrinsic_size?;
        let layout = attachment_image_preview_layout(
            preview.intrinsic_size,
            preview.zoom,
            self.last_visibility.layout.viewport_width as f32,
            self.last_visibility.layout.viewport_height as f32,
        );
        if layout.image_width <= 0.0 || layout.image_height <= 0.0 {
            return None;
        }
        // The centered image lives inside the padded viewport child. Pointer
        // events are reported in overlay coordinates, so include that inset
        // before converting back to source pixels.
        let origin_x = IMAGE_PREVIEW_HORIZONTAL_PADDING
            + (layout.viewport_width - layout.image_width) / 2.0
            + preview.pan_x;
        let origin_y = IMAGE_PREVIEW_VERTICAL_PADDING
            + (layout.viewport_height - layout.image_height) / 2.0
            + preview.pan_y;
        let x = ((pointer_x - origin_x) / layout.image_width * source_width as f32).round();
        let y = ((pointer_y - origin_y) / layout.image_height * source_height as f32).round();
        if x < 0.0 || y < 0.0 || x >= source_width as f32 || y >= source_height as f32 {
            return None;
        }
        Some((x as u32, y as u32))
    }

    fn persist_attachment_editor_buffer(&self, bytes: &[u8]) -> std::io::Result<PathBuf> {
        let Some(config) = self.config.as_ref() else {
            return Err(std::io::Error::new(
                std::io::ErrorKind::NotFound,
                "isolated desktop home is unavailable",
            ));
        };
        let root = config.home_dir.join("composer-edits");
        fs::create_dir_all(&root)?;
        let digest = Sha256::digest(bytes);
        let digest = digest
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<String>();
        let destination = root.join(format!("{digest}.png"));
        if !destination.exists() {
            fs::write(&destination, bytes)?;
        }
        Ok(destination)
    }

    fn commit_attachment_editor_buffer(
        &mut self,
        buffer: image::RgbaImage,
        cx: &mut Context<Self>,
    ) -> bool {
        let Ok(bytes) = encode_editor_image(&buffer) else {
            self.agent_error = Some(
                locale::text(
                    "Edited image could not be encoded",
                    "编辑后的图片无法编码",
                    "編輯後的圖片無法編碼",
                )
                .to_string(),
            );
            cx.notify();
            return false;
        };
        let Ok(path) = self.persist_attachment_editor_buffer(&bytes) else {
            self.agent_error = Some(
                locale::text(
                    "Edited image could not be saved",
                    "编辑后的图片无法保存",
                    "編輯後的圖片無法儲存",
                )
                .to_string(),
            );
            cx.notify();
            return false;
        };
        let image = Arc::new(Image::from_bytes(ImageFormat::Png, bytes));
        let dimensions = buffer.dimensions();
        let viewport_width = self.last_visibility.layout.viewport_width as f32;
        let viewport_height = self.last_visibility.layout.viewport_height as f32;
        let (attachment_id, updated_attachment) = {
            let Some(preview) = self.attachment_image_preview.as_mut() else {
                return false;
            };
            if !preview.editable {
                return false;
            }
            preview.attachment.label = edited_attachment_file_name(&preview.attachment.label);
            preview.attachment.path = Some(path.to_string_lossy().into_owned());
            preview.attachment.mime_type = Some("image/png".to_string());
            preview.image_source = Arc::<Path>::from(path.clone().into_boxed_path());
            preview.confirmed_image = Some(image.clone());
            preview.edited_image = Some(image);
            preview.edit_buffer = Some(Arc::new(buffer));
            preview.edit_session = None;
            preview.intrinsic_size = Some(dimensions);
            preview.editing = false;
            preview.edit_drag = None;
            preview.edit_drag_base = None;
            preview.drag = None;
            let layout = attachment_image_preview_layout(
                preview.intrinsic_size,
                preview.zoom,
                viewport_width,
                viewport_height,
            );
            (preview.pan_x, preview.pan_y) = layout.clamp_pan(preview.pan_x, preview.pan_y);
            (preview.attachment.id.clone(), preview.attachment.clone())
        };
        if let Some(attachment) = self
            .composer_attachments
            .iter_mut()
            .find(|attachment| attachment.attachment.id == attachment_id)
        {
            attachment.attachment = updated_attachment.clone();
        }
        if let Some(attachment) = self
            .new_session_attachments
            .iter_mut()
            .find(|attachment| attachment.attachment.id == attachment_id)
        {
            attachment.attachment = updated_attachment;
        }
        cx.notify();
        true
    }

    fn begin_attachment_edit_gesture(
        &mut self,
        pointer_x: f32,
        pointer_y: f32,
        cx: &mut Context<Self>,
    ) {
        let Some(snapshot) = self.attachment_image_preview.clone() else {
            return;
        };
        if !snapshot.editable || !snapshot.editing {
            return;
        }
        let Some(point) = self.attachment_preview_point(&snapshot, pointer_x, pointer_y) else {
            return;
        };
        if snapshot.tool == ImageEditTool::Text {
            let text = self.image_editor_text_input.read(cx).value().to_string();
            if text.trim().is_empty() {
                return;
            }
            let Some(session) = snapshot.edit_session else {
                return;
            };
            let mut buffer = session.current_clone();
            apply_text(&mut buffer, point, &text);
            if let Some(preview) = self.attachment_image_preview.as_mut() {
                Arc::make_mut(
                    preview
                        .edit_session
                        .get_or_insert_with(|| Arc::new(ImageEditSession::new(buffer.clone()))),
                )
                .commit(buffer);
            }
            self.update_attachment_editor_render(cx);
            return;
        }
        if let Some(preview) = self.attachment_image_preview.as_mut() {
            preview.edit_drag = Some(AttachmentImageEditDragState {
                start_x: point.0,
                start_y: point.1,
                current_x: point.0,
                current_y: point.1,
            });
            preview.edit_drag_base = preview
                .edit_session
                .as_ref()
                .map(|session| Arc::new(session.current_clone()));
            preview.drag = None;
            cx.notify();
        }
    }

    fn update_attachment_edit_gesture(
        &mut self,
        pointer_x: f32,
        pointer_y: f32,
        cx: &mut Context<Self>,
    ) {
        let Some(snapshot) = self.attachment_image_preview.clone() else {
            return;
        };
        let Some(mut point) = self.attachment_preview_point(&snapshot, pointer_x, pointer_y) else {
            return;
        };
        let Some(gesture) = snapshot.edit_drag else {
            return;
        };
        point.0 = point.0.min(
            snapshot
                .intrinsic_size
                .map_or(point.0, |size| size.0.saturating_sub(1)),
        );
        point.1 = point.1.min(
            snapshot
                .intrinsic_size
                .map_or(point.1, |size| size.1.saturating_sub(1)),
        );
        if let Some(preview) = self.attachment_image_preview.as_mut() {
            preview.edit_drag = Some(AttachmentImageEditDragState {
                current_x: point.0,
                current_y: point.1,
                ..gesture
            });
        }
        let Some(base) = snapshot.edit_drag_base else {
            return;
        };
        let Some(session) = snapshot.edit_session else {
            return;
        };
        let mut buffer = if matches!(snapshot.tool, ImageEditTool::Brush | ImageEditTool::Mosaic) {
            session.current_clone()
        } else {
            base.as_ref().clone()
        };
        match snapshot.tool {
            ImageEditTool::Brush => {
                apply_brush(&mut buffer, (gesture.current_x, gesture.current_y), point)
            }
            ImageEditTool::Mosaic => {
                apply_mosaic(&mut buffer, (gesture.current_x, gesture.current_y), point)
            }
            ImageEditTool::Rectangle => {
                apply_rectangle(&mut buffer, (gesture.start_x, gesture.start_y), point)
            }
            ImageEditTool::Circle => {
                apply_circle(&mut buffer, (gesture.start_x, gesture.start_y), point)
            }
            ImageEditTool::Arrow => {
                apply_arrow(&mut buffer, (gesture.start_x, gesture.start_y), point)
            }
            ImageEditTool::Crop | ImageEditTool::Text => {}
        }
        if let Some(preview) = self.attachment_image_preview.as_mut()
            && let Some(session) = preview.edit_session.as_mut()
        {
            Arc::make_mut(session).preview(buffer);
        }
        self.update_attachment_editor_render(cx);
    }

    fn finish_attachment_edit_gesture(&mut self, cx: &mut Context<Self>) {
        let Some(snapshot) = self.attachment_image_preview.clone() else {
            return;
        };
        let Some(gesture) = snapshot.edit_drag else {
            return;
        };
        let Some(base) = snapshot.edit_drag_base else {
            return;
        };
        let Some(session) = snapshot.edit_session else {
            return;
        };
        let mut committed = false;
        if snapshot.tool == ImageEditTool::Crop {
            if let Some(cropped) = apply_crop(
                session.current(),
                (gesture.start_x, gesture.start_y),
                (gesture.current_x, gesture.current_y),
            ) && let Some(preview) = self.attachment_image_preview.as_mut()
                && let Some(session) = preview.edit_session.as_mut()
            {
                committed = Arc::make_mut(session).commit(cropped);
            }
        } else if let Some(preview) = self.attachment_image_preview.as_mut()
            && let Some(session) = preview.edit_session.as_mut()
        {
            let _ = base;
            committed = Arc::make_mut(session).commit_gesture(base.as_ref().clone());
        }
        if let Some(preview) = self.attachment_image_preview.as_mut() {
            preview.edit_drag = None;
            preview.edit_drag_base = None;
        }
        if committed {
            self.update_attachment_editor_render(cx);
        } else {
            cx.notify();
        }
    }

    fn close_attachment_preview(&mut self, cx: &mut Context<Self>) {
        self.attachment_image_preview = None;
        cx.notify();
    }

    fn copy_attachment_preview_image(
        &mut self,
        source: &str,
        mime_type: Option<&str>,
        cx: &mut Context<Self>,
    ) {
        let result = (|| {
            let bytes = std::fs::read(source)?;
            if bytes.is_empty() {
                return Err(std::io::Error::new(
                    std::io::ErrorKind::InvalidData,
                    "image is empty",
                ));
            }
            let format = attachment_preview_image_format(std::path::Path::new(source), mime_type)
                .ok_or_else(|| {
                std::io::Error::new(
                    std::io::ErrorKind::InvalidData,
                    "image format is unsupported",
                )
            })?;
            Ok(Image::from_bytes(format, bytes))
        })();

        match result {
            Ok(image) => cx.write_to_clipboard(ClipboardItem::new_image(&image)),
            Err(error) => {
                self.agent_error = Some(format!("image copy failed: {error}"));
                cx.notify();
            }
        }
    }

    fn set_attachment_preview_zoom(&mut self, zoom: f32, cx: &mut Context<Self>) {
        let viewport_width = self.last_visibility.layout.viewport_width as f32;
        let viewport_height = self.last_visibility.layout.viewport_height as f32;
        let Some(preview) = self.attachment_image_preview.as_mut() else {
            return;
        };
        preview.zoom = clamp_attachment_preview_zoom(zoom);
        let layout = attachment_image_preview_layout(
            preview.intrinsic_size,
            preview.zoom,
            viewport_width,
            viewport_height,
        );
        (preview.pan_x, preview.pan_y) = layout.clamp_pan(preview.pan_x, preview.pan_y);
        preview.drag = None;
        cx.notify();
    }

    fn adjust_attachment_preview_zoom(&mut self, delta: f32, cx: &mut Context<Self>) {
        let Some(zoom) = self
            .attachment_image_preview
            .as_ref()
            .map(|preview| preview.zoom)
        else {
            return;
        };
        self.set_attachment_preview_zoom(zoom + delta, cx);
    }

    fn begin_attachment_preview_drag(
        &mut self,
        pointer_x: f32,
        pointer_y: f32,
        cx: &mut Context<Self>,
    ) {
        let Some(preview) = self.attachment_image_preview.as_mut() else {
            return;
        };
        preview.drag = Some(AttachmentImagePreviewDragState {
            start_pointer_x: pointer_x,
            start_pointer_y: pointer_y,
            start_pan_x: preview.pan_x,
            start_pan_y: preview.pan_y,
        });
        cx.notify();
    }

    fn update_attachment_preview_drag(
        &mut self,
        pointer_x: f32,
        pointer_y: f32,
        cx: &mut Context<Self>,
    ) {
        let viewport_width = self.last_visibility.layout.viewport_width as f32;
        let viewport_height = self.last_visibility.layout.viewport_height as f32;
        let Some(preview) = self.attachment_image_preview.as_mut() else {
            return;
        };
        let Some(drag) = preview.drag else {
            return;
        };
        let layout = attachment_image_preview_layout(
            preview.intrinsic_size,
            preview.zoom,
            viewport_width,
            viewport_height,
        );
        let requested_x = drag.start_pan_x + pointer_x - drag.start_pointer_x;
        let requested_y = drag.start_pan_y + pointer_y - drag.start_pointer_y;
        let (pan_x, pan_y) = layout.clamp_pan(requested_x, requested_y);
        if preview.pan_x != pan_x || preview.pan_y != pan_y {
            preview.pan_x = pan_x;
            preview.pan_y = pan_y;
            cx.notify();
        }
    }

    fn finish_attachment_preview_drag(&mut self, cx: &mut Context<Self>) {
        let Some(preview) = self.attachment_image_preview.as_mut() else {
            return;
        };
        if preview.drag.take().is_some() {
            cx.notify();
        }
    }

    fn sync_terminal_sessions(
        &mut self,
        terminals: Vec<TerminalSession>,
        cx: &mut Context<Self>,
    ) -> bool {
        let (composer_terminals, workbench_terminals) =
            partition_terminal_sessions(terminals, &self.ui_state.composer.terminal_ids);
        let composer_ids = composer_terminals
            .iter()
            .map(|terminal| terminal.id.as_str().to_string())
            .collect::<Vec<_>>();
        let previous_order = self.ui_state.terminal.tab_order.clone();
        complete_string_order(&mut self.ui_state.terminal.tab_order, composer_ids);
        let composer_terminals =
            order_terminal_sessions(composer_terminals, &self.ui_state.terminal.tab_order);
        let previous_selection = self.selected_composer_terminal_id.clone();
        if self
            .selected_composer_terminal_id
            .as_ref()
            .is_some_and(|selected| {
                !composer_terminals
                    .iter()
                    .any(|terminal| &terminal.id == selected)
            })
        {
            self.selected_composer_terminal_id = composer_terminals
                .first()
                .map(|terminal| terminal.id.clone());
        } else if self.selected_composer_terminal_id.is_none() {
            self.selected_composer_terminal_id = composer_terminals
                .first()
                .map(|terminal| terminal.id.clone());
        }
        let composer_changed = self.view.composer_terminals != composer_terminals;
        self.view.composer_terminals = composer_terminals;
        let live_terminals = &self.view.composer_terminals;
        self.view
            .composer_terminal_surfaces
            .retain(|terminal_id, _| {
                live_terminals
                    .iter()
                    .any(|terminal| terminal.id.as_str() == terminal_id)
            });
        self.sync_composer_terminal_surface_activity(cx);
        if self.ui_state.terminal.tab_order != previous_order {
            self.queue_ui_state();
        }
        let workbench_changed = self.code_workbench.update(cx, |workbench, cx| {
            workbench.sync_terminals(workbench_terminals, cx)
        });
        composer_changed
            || self.selected_composer_terminal_id != previous_selection
            || self.ui_state.terminal.tab_order != previous_order
            || workbench_changed
    }

    fn move_composer_terminal_relative(
        &mut self,
        moving_id: &str,
        target_id: &str,
        after: bool,
        cx: &mut Context<Self>,
    ) {
        let terminal_ids = self
            .composer_terminals
            .iter()
            .map(|terminal| terminal.id.as_str().to_string())
            .collect::<Vec<_>>();
        complete_string_order(&mut self.ui_state.terminal.tab_order, terminal_ids);
        if move_string_relative(
            &mut self.ui_state.terminal.tab_order,
            moving_id,
            target_id,
            after,
        ) {
            self.composer_terminals = order_terminal_sessions(
                std::mem::take(&mut self.composer_terminals),
                &self.ui_state.terminal.tab_order,
            );
            self.queue_ui_state();
        }
        self.composer_terminal_drop_target = None;
        cx.notify();
    }

    /// Terminal transport for the current authority, owned by the workbench so
    /// every terminal view shares one set of remote pump tasks.
    fn terminal_transport(
        &self,
        cx: &gpui::App,
    ) -> Option<crate::code_workbench::TerminalSurfaceTransport> {
        self.code_workbench.read(cx).terminal_surface_transport()
    }

    fn ensure_composer_terminal_surface(
        &mut self,
        terminal: TerminalSession,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> Option<Entity<TerminalSurface>> {
        let transport = self.terminal_transport(cx)?;
        let terminal_id = terminal.id.as_str().to_string();
        let workspace_root = self
            .selected_session()
            .filter(|session| session.workspace_id == terminal.workspace_id)
            .map(|session| std::path::PathBuf::from(&session.workspace_root))
            .unwrap_or_else(|| std::path::PathBuf::from(&terminal.cwd));
        let surface = self
            .composer_terminal_surfaces
            .entry(terminal_id)
            .or_insert_with(|| {
                cx.new(|cx| {
                    TerminalSurface::from_embedded_shared_session_with_transport(
                        transport.transport,
                        workspace_root,
                        terminal,
                        window,
                        cx,
                    )
                })
            })
            .clone();
        self.sync_composer_terminal_surface_activity(cx);
        Some(surface)
    }

    fn sync_composer_terminal_surface_activity(&mut self, cx: &mut Context<Self>) {
        let desired = (self.ui_state.workbench.active_tab == "agent"
            && !self.new_session_open
            && self.composer_terminal_mode)
            .then_some(self.selected_composer_terminal_id.as_ref())
            .flatten()
            .map(|terminal_id| terminal_id.as_str().to_string())
            .filter(|terminal_id| self.composer_terminal_surfaces.contains_key(terminal_id));
        if desired == self.active_composer_terminal_surface_id {
            return;
        }

        if let Some(active_id) = self.active_composer_terminal_surface_id.take()
            && let Some(surface) = self.composer_terminal_surfaces.get(&active_id)
        {
            surface.update(cx, |surface, cx| surface.set_active(false, cx));
        }
        if let Some(desired_id) = desired {
            if let Some(surface) = self.composer_terminal_surfaces.get(&desired_id) {
                surface.update(cx, |surface, cx| surface.set_active(true, cx));
            }
            self.active_composer_terminal_surface_id = Some(desired_id);
        }
    }

    fn set_code_preview_visible(&mut self, visible: bool, cx: &mut Context<Self>) {
        // A detached panel is still the open panel: the workbench column stops
        // drawing it, but its terminals and editors keep running in the window
        // that does.
        let visible = visible || self.preview_window.is_some();
        if self.code_preview_visible == visible {
            return;
        }
        self.code_preview_visible = visible;
        self.code_workbench.update(cx, |workbench, cx| {
            workbench.set_preview_visible(visible, cx)
        });
    }

    /// Moves the editor panel between the workbench column and its
    /// own window. The panel entity changes host instead of being rebuilt, so
    /// open tabs, editor buffers, and terminals travel with it and there is
    /// never more than one panel.
    pub(crate) fn set_preview_window_detached(
        &mut self,
        origin_window: AnyWindowHandle,
        detached: bool,
        cx: &mut Context<Self>,
    ) {
        // The button and the setting are two views of one choice: whichever the
        // user reaches for, the next preview opens the same way.
        self.set_preview_window_mode(
            if detached {
                PreviewWindowMode::Window
            } else {
                PreviewWindowMode::Inline
            },
            cx,
        );
        if detached {
            self.detach_preview_window(origin_window, cx);
        } else {
            self.dock_preview_window(cx);
        }
    }

    /// Records where the editor panel opens, and moves a panel that is already
    /// open so the change is visible immediately instead of on the next open.
    pub(crate) fn set_preview_window_mode(
        &mut self,
        mode: PreviewWindowMode,
        cx: &mut Context<Self>,
    ) {
        if self.ui_state.workbench.preview_window_mode != mode {
            self.ui_state.workbench.preview_window_mode = mode;
            self.queue_ui_state();
        }
        if mode.is_window() {
            // Only a panel that is actually open travels; choosing the window
            // mode with the preview closed leaves it closed until it is opened.
            if self.code_preview_visible
                && let Some(window_handle) = self.window_handle
            {
                self.detach_preview_window(window_handle, cx);
            }
        } else {
            self.dock_preview_window(cx);
        }
        cx.notify();
    }

    fn detach_preview_window(&mut self, origin_window: AnyWindowHandle, cx: &mut Context<Self>) {
        if let Some(existing) = self.preview_window {
            // One panel, one window: a second pop-out request raises the window
            // that already hosts it rather than opening another.
            let _ = existing.update(cx, |_, window, cx| {
                window.activate_window();
                cx.activate(true);
            });
            return;
        }
        // The panel is what travels, so make sure it is open before the move.
        self.show_code_preview_inline(cx);
        self.code_workbench
            .update(cx, |workbench, cx| workbench.exit_fullscreen(cx));
        let window_bounds = WindowBounds::Windowed(Bounds::centered(
            None,
            size(px(PREVIEW_WINDOW_WIDTH), px(PREVIEW_WINDOW_HEIGHT)),
            cx,
        ));
        let options = WindowOptions {
            window_bounds: Some(window_bounds),
            titlebar: Some(TitlebarOptions {
                title: Some(locale::text("Editor", "编辑器", "編輯器").into()),
                ..Default::default()
            }),
            app_id: release_application_id().ok().map(str::to_string),
            icon: window_icon().ok(),
            window_min_size: Some(size(
                px(PREVIEW_WINDOW_MIN_WIDTH),
                px(PREVIEW_WINDOW_MIN_HEIGHT),
            )),
            ..Default::default()
        };
        let code_workbench = self.code_workbench.clone();
        let appearance = self.ui_state.appearance.clone();
        let opened = cx.open_window(options, move |window, cx| {
            theme::apply_appearance(&appearance, Some(window), cx);
            let host = cx.new(|cx| PreviewWindowHost::new(code_workbench, window, cx));
            cx.new(|cx| Root::new(host, window, cx).bordered(false))
        });
        let handle = match opened {
            Ok(handle) => handle,
            Err(error) => {
                // Nothing moved, so the panel stays exactly where it was.
                self.code_workbench.update(cx, |workbench, cx| {
                    workbench.set_preview_detached(false, cx)
                });
                let message = format!("failed to open the preview window: {error}");
                eprintln!("{message}");
                let _ = origin_window.update(cx, |_, window, cx| {
                    window.push_notification(
                        hint_notification(NotificationType::Error, message.clone(), cx),
                        cx,
                    );
                });
                cx.notify();
                return;
            }
        };
        let handle: AnyWindowHandle = handle.into();
        self.preview_window = Some(handle);
        self.code_workbench
            .update(cx, |workbench, cx| workbench.set_preview_detached(true, cx));
        cx.notify();
    }

    /// Closes the detached window and hands the panel back to the workbench
    /// column. Every path that takes the panel down uses this, so the panel
    /// never ends up with no host.
    fn dock_preview_window(&mut self, cx: &mut Context<Self>) {
        let Some(handle) = self.take_preview_window(cx) else {
            return;
        };
        self.remove_preview_window(handle, cx);
        // Docking back is a move, not a close: the panel has to be visible in
        // the workbench again.
        self.show_code_preview_inline(cx);
        self.activate_workbench_window(cx);
    }

    /// Drops the detached window without reopening the panel inline, for the
    /// paths where the panel itself is being closed.
    fn close_preview_window(&mut self, cx: &mut Context<Self>) {
        let Some(handle) = self.take_preview_window(cx) else {
            return;
        };
        self.remove_preview_window(handle, cx);
    }

    /// Removes a window the workbench owns. The window-closed observer fires
    /// while this runs, so the closing marker tells it the close is accounted
    /// for and the hand-back is not needed.
    fn remove_preview_window(&mut self, handle: AnyWindowHandle, cx: &mut Context<Self>) {
        self.preview_window_closing.set(Some(handle.window_id()));
        let _ = handle.update(cx, |_, window, _| window.remove_window());
        self.preview_window_closing.set(None);
    }

    fn take_preview_window(&mut self, cx: &mut Context<Self>) -> Option<AnyWindowHandle> {
        let handle = self.preview_window.take()?;
        self.code_workbench.update(cx, |workbench, cx| {
            workbench.set_preview_detached(false, cx)
        });
        Some(handle)
    }

    /// A window this workbench owns was closed without it asking.
    ///
    /// The detached preview window hands the panel back inline, so it cannot
    /// disappear with the window. The workbench window going away takes the
    /// detached window with it instead, because the shell that owns the panel
    /// is the only surface that can host it inline.
    fn handle_window_closed(&mut self, window_id: WindowId, cx: &mut Context<Self>) {
        if self.preview_window.map(|handle| handle.window_id()) == Some(window_id) {
            self.preview_window = None;
            self.code_workbench.update(cx, |workbench, cx| {
                workbench.set_preview_detached(false, cx)
            });
            // Closing the window is a request to work inline, not a one-off
            // move: leaving the setting on the window mode would pop the panel
            // straight back out the next time it opens.
            if self.ui_state.workbench.preview_window_mode.is_window() {
                self.ui_state.workbench.preview_window_mode = PreviewWindowMode::Inline;
                self.queue_ui_state();
            }
            self.show_code_preview_inline(cx);
            self.activate_workbench_window(cx);
            cx.notify();
            return;
        }
        if self.window_handle.map(|handle| handle.window_id()) == Some(window_id) {
            self.window_handle = None;
            // The tabs survive: the panel is only rehosted, and the next
            // workbench window renders it inline again.
            self.close_preview_window(cx);
        }
    }

    fn activate_workbench_window(&mut self, cx: &mut Context<Self>) {
        let Some(handle) = self.window_handle else {
            return;
        };
        if handle
            .update(cx, |_, window, _| window.activate_window())
            .is_err()
        {
            self.window_handle = None;
            return;
        }
        cx.activate(true);
    }

    fn set_code_workspace_surface_visibility(
        &mut self,
        files_visible: bool,
        git_visible: bool,
        cx: &mut Context<Self>,
    ) {
        if self.code_files_surface_visible == files_visible
            && self.code_git_surface_visible == git_visible
        {
            return;
        }
        self.code_files_surface_visible = files_visible;
        self.code_git_surface_visible = git_visible;
        self.code_workbench.update(cx, |workbench, cx| {
            workbench.set_workspace_surface_visibility(files_visible, git_visible, cx)
        });
    }

    fn select_composer_terminal(
        &mut self,
        terminal_id: TerminalId,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if !self
            .composer_terminals
            .iter()
            .any(|terminal| terminal.id == terminal_id)
        {
            return;
        }
        let terminal = self
            .composer_terminals
            .iter()
            .find(|terminal| terminal.id == terminal_id)
            .cloned();
        self.selected_composer_terminal_id = Some(terminal_id.clone());
        self.composer_terminal_mode = true;
        self.clear_suggestions();
        if let Some(terminal) = terminal
            && let Some(surface) = self.ensure_composer_terminal_surface(terminal, window, cx)
        {
            self.sync_composer_terminal_surface_activity(cx);
            surface.update(cx, |surface, cx| surface.focus_input(window, cx));
        }
        cx.notify();
    }

    fn switch_to_composer_terminal(
        &mut self,
        window_handle: AnyWindowHandle,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let terminal_id = self
            .selected_composer_terminal_id
            .clone()
            .filter(|selected| {
                self.composer_terminals
                    .iter()
                    .any(|terminal| &terminal.id == selected)
            })
            .or_else(|| {
                self.composer_terminals
                    .first()
                    .map(|terminal| terminal.id.clone())
            });
        if let Some(terminal_id) = terminal_id {
            self.select_composer_terminal(terminal_id, window, cx);
        } else {
            self.composer_terminal_mode = true;
            self.clear_suggestions();
            self.create_composer_terminal(window_handle, cx);
        }
    }

    fn open_code_file(&mut self, path: String, window: &mut Window, cx: &mut Context<Self>) {
        self.reveal_code_preview(cx);
        self.code_workbench.update(cx, |workbench, cx| {
            workbench.open_file(path, false, window, cx)
        });
    }

    fn composer_attachment_workspace_root(&self) -> Option<String> {
        if self.new_session_open {
            return self
                .new_session_workspace
                .selected_workspace()
                .map(|workspace| workspace.root_path.clone())
                .or_else(|| {
                    let workspace_id = self.new_session_workspace.origin_workspace_id.as_ref()?;
                    self.workspaces
                        .iter()
                        .find(|(_, workspace)| &workspace.id == workspace_id)
                        .map(|(_, workspace)| workspace.root_path.clone())
                })
                .or_else(|| {
                    (!self.new_session_workspace.project_root.trim().is_empty())
                        .then(|| self.new_session_workspace.project_root.clone())
                });
        }
        self.selected_session()
            .map(|session| session.workspace_root.clone())
    }

    fn composer_attachment_tab_path(&self, attachment: &ComposerAttachment) -> Option<String> {
        let workspace_root = self.composer_attachment_workspace_root()?;
        agent_file_operation_preview_path(
            attachment.path.as_deref()?,
            Some(workspace_root.as_str()),
        )
    }

    fn open_composer_attachment_in_tab(
        &mut self,
        attachment: &ComposerAttachment,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(workspace_root) = self.composer_attachment_workspace_root() else {
            return;
        };
        let Some(path) = agent_file_operation_preview_path(
            attachment.path.as_deref().unwrap_or_default(),
            Some(workspace_root.as_str()),
        ) else {
            return;
        };
        if let Some(workspace) = self
            .workspaces
            .iter()
            .find(|(_, workspace)| {
                std::path::Path::new(&workspace.root_path) == std::path::Path::new(&workspace_root)
            })
            .map(|(_, workspace)| workspace.clone())
        {
            self.activate_workspace(workspace, cx);
        }
        self.open_code_file(path, window, cx);
    }

    fn open_markdown_resource(
        &mut self,
        resource: ResolvedResource,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        match resource.kind {
            ResourceKind::Workspace => {
                let workspace_root = self
                    .selected_session()
                    .map(|session| session.workspace_root.as_str());
                if let Some(target) = agent_markdown_preview_path(&resource, workspace_root) {
                    self.open_code_file(target, window, cx);
                }
            }
            ResourceKind::Http => {
                let Some(target) = resource.resolved else {
                    return;
                };
                if let Err(error) = validate_external_open_url(&target)
                    .and_then(|validated| crate::platform::open_external_url(&validated.url))
                {
                    self.agent_error = Some(format!("{}: {}", error.code, error.message));
                    cx.notify();
                }
            }
            ResourceKind::DataImage | ResourceKind::Fragment | ResourceKind::Blocked => {}
        }
    }

    pub(crate) fn create_composer_terminal(
        &mut self,
        window_handle: AnyWindowHandle,
        cx: &mut Context<Self>,
    ) {
        if self.agent_action_pending {
            return;
        }
        let (Some(transport), Some(session)) = (
            self.terminal_transport(cx),
            self.selected_session().cloned(),
        ) else {
            self.agent_error = Some("Select a session before creating a terminal".into());
            cx.notify();
            return;
        };
        self.agent_action_pending = true;
        self.agent_error = None;
        let generation = self.session_generation;
        let terminal_number = self.composer_terminals.len().saturating_add(1);
        let project_root = (session.workspace_mode == WorkspaceMode::CurrentCheckout)
            .then(|| {
                self.workspaces
                    .iter()
                    .find(|(project, _)| project.id == session.project_id)
                    .map(|(project, _)| project.root_path.as_str())
            })
            .flatten();
        let selected_file_path = self.ui_state.workbench.selected_file_path.clone();
        let (terminal_root, cwd) = terminal_preference_target(
            &session.workspace_root,
            project_root,
            selected_file_path.as_deref(),
            &self.ui_state.terminal_preferences.working_directory,
        );
        let request = TerminalCreateRequest {
            workspace_id: session.workspace_id,
            title: Some(format!(
                "{} {terminal_number}",
                locale::text("Terminals", "终端", "終端")
            )),
            shell: this_terminal_shell(&self.ui_state.terminal_preferences.shell),
            cwd,
            rows: 18,
            cols: 100,
        };
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            transport
                .transport
                .create_terminal(std::path::Path::new(&terminal_root), request)
                .await
                .map_err(|error| {
                    vibex_core::VibexError::new(
                        vibex_core::ErrorCategory::Storage,
                        error.code,
                        error.message,
                    )
                })
        });
        let entity = cx.weak_entity();
        self.agent_action_task = Some(cx.spawn(async move |_, cx| {
            let outcome = runner.await;
            let _ = cx.update_window(window_handle, |_, window, cx| {
                let _ = entity.update(cx, |this, cx| {
                    this.agent_action_pending = false;
                    if this.session_generation != generation {
                        return;
                    }
                    match outcome {
                        Ok(Ok(terminal)) => {
                            let terminal_id = terminal.id.clone();
                            this.selected_composer_terminal_id = Some(terminal_id.clone());
                            this.composer_terminal_mode = true;
                            this.composer_terminals
                                .retain(|item| item.id != terminal_id);
                            this.composer_terminals.push(terminal.clone());
                            let terminal_id = terminal_id.as_str().to_string();
                            let mut terminal_state_changed = false;
                            if !this.ui_state.composer.terminal_ids.contains(&terminal_id) {
                                this.ui_state
                                    .composer
                                    .terminal_ids
                                    .push(terminal_id.clone());
                                terminal_state_changed = true;
                            }
                            if !this.ui_state.terminal.tab_order.contains(&terminal_id) {
                                this.ui_state.terminal.tab_order.push(terminal_id);
                                terminal_state_changed = true;
                            }
                            if terminal_state_changed {
                                this.queue_ui_state();
                            }
                            this.ensure_composer_terminal_surface(terminal, window, cx);
                            this.sync_composer_terminal_surface_activity(cx);
                        }
                        Ok(Err(error)) => {
                            this.agent_error = Some(format!(
                                "terminal create failed: {}: {}",
                                error.code, error.message
                            ));
                        }
                        Err(error) => {
                            this.agent_error =
                                Some(format!("terminal create task failed: {error}"));
                        }
                    }
                    cx.notify();
                });
            });
        }));
    }

    pub(crate) fn create_preview_terminal(
        &mut self,
        window_handle: AnyWindowHandle,
        pane_id: Option<String>,
        cwd_source: Option<(String, FileEntryKind)>,
        cx: &mut Context<Self>,
    ) {
        if self.agent_action_pending {
            return;
        }
        let (Some(transport), Some(session)) = (
            self.terminal_transport(cx),
            self.selected_session().cloned(),
        ) else {
            self.agent_error = Some("Select a session before creating a terminal".into());
            cx.notify();
            return;
        };
        self.agent_action_pending = true;
        self.agent_error = None;
        let generation = self.session_generation;
        let project_root = (session.workspace_mode == WorkspaceMode::CurrentCheckout)
            .then(|| {
                self.workspaces
                    .iter()
                    .find(|(project, _)| project.id == session.project_id)
                    .map(|(project, _)| project.root_path.as_str())
            })
            .flatten();
        let selected_file_path = self.ui_state.workbench.selected_file_path.clone();
        let explicit_cwd = cwd_source
            .as_ref()
            .and_then(|(path, kind)| terminal_cwd_for_workspace_target(path, *kind));
        let (terminal_root, preferred_cwd) = terminal_preference_target(
            &session.workspace_root,
            project_root,
            selected_file_path.as_deref(),
            &self.ui_state.terminal_preferences.working_directory,
        );
        let cwd = explicit_cwd.or(preferred_cwd);
        let request = TerminalCreateRequest {
            workspace_id: session.workspace_id,
            title: Some(PREVIEW_TERMINAL_TITLE.into()),
            shell: this_terminal_shell(&self.ui_state.terminal_preferences.shell),
            cwd,
            rows: 28,
            cols: 100,
        };
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            transport
                .transport
                .create_terminal(std::path::Path::new(&terminal_root), request)
                .await
                .map_err(|error| {
                    vibex_core::VibexError::new(
                        vibex_core::ErrorCategory::Storage,
                        error.code,
                        error.message,
                    )
                })
        });
        let entity = cx.weak_entity();
        self.agent_action_task = Some(cx.spawn(async move |_, cx| {
            let outcome = runner.await;
            let _ = cx.update_window(window_handle, |_, window, cx| {
                let _ = entity.update(cx, |this, cx| {
                    this.agent_action_pending = false;
                    if this.session_generation != generation {
                        return;
                    }
                    match outcome {
                        Ok(Ok(terminal)) => {
                            let terminal_id = terminal.id.clone();
                            this.code_workbench.update(cx, |workbench, cx| {
                                workbench.register_terminal(terminal, cx);
                                workbench.open_terminal_in_pane(
                                    terminal_id,
                                    pane_id.clone(),
                                    window,
                                    cx,
                                );
                            });
                            this.reveal_code_preview(cx);
                        }
                        Ok(Err(error)) => {
                            this.agent_error = Some(format!(
                                "terminal create failed: {}: {}",
                                error.code, error.message
                            ));
                        }
                        Err(error) => {
                            this.agent_error =
                                Some(format!("terminal create task failed: {error}"));
                        }
                    }
                    cx.notify();
                });
            });
        }));
    }

    fn kill_composer_terminal(&mut self, terminal_id: TerminalId, cx: &mut Context<Self>) {
        self.kill_composer_terminals(vec![terminal_id], cx);
    }

    fn kill_composer_terminals(&mut self, terminal_ids: Vec<TerminalId>, cx: &mut Context<Self>) {
        if self.agent_action_pending {
            return;
        }
        let Some(transport) = self.terminal_transport(cx) else {
            return;
        };
        let composer_ids = self
            .composer_terminals
            .iter()
            .map(|terminal| terminal.id.as_str().to_string())
            .collect::<BTreeSet<_>>();
        let mut seen = BTreeSet::new();
        let terminal_ids = terminal_ids
            .into_iter()
            .filter(|terminal_id| {
                composer_ids.contains(terminal_id.as_str())
                    && seen.insert(terminal_id.as_str().to_string())
            })
            .collect::<Vec<_>>();
        if terminal_ids.is_empty() {
            return;
        }
        self.agent_action_pending = true;
        self.agent_error = None;
        let generation = self.session_generation;
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            let mut closed = Vec::new();
            let mut errors = Vec::new();
            for terminal_id in terminal_ids {
                match transport.transport.close_terminal(&terminal_id).await {
                    Ok(_) => closed.push(terminal_id),
                    Err(error) if error.code == "terminal_not_found" => closed.push(terminal_id),
                    Err(error) => errors.push(format!("{}: {}", error.code, error.message)),
                }
            }
            (closed, errors)
        });
        let entity = cx.weak_entity();
        self.agent_action_task = Some(cx.spawn(async move |_, cx| {
            let outcome = runner.await;
            let _ = entity.update(cx, |this, cx| {
                this.agent_action_pending = false;
                if this.session_generation != generation {
                    return;
                }
                match outcome {
                    Ok((closed, errors)) => {
                        let closed_ids = closed
                            .iter()
                            .map(|terminal_id| terminal_id.as_str().to_string())
                            .collect::<BTreeSet<_>>();
                        this.composer_terminals
                            .retain(|terminal| !closed_ids.contains(terminal.id.as_str()));
                        this.ui_state
                            .composer
                            .terminal_ids
                            .retain(|id| !closed_ids.contains(id));
                        this.ui_state
                            .terminal
                            .tab_order
                            .retain(|id| !closed_ids.contains(id));
                        this.ui_state
                            .terminal_tab_titles
                            .retain(|id, _| !closed_ids.contains(id));
                        for terminal_id in &closed_ids {
                            this.composer_terminal_surfaces.remove(terminal_id);
                        }
                        if this
                            .selected_composer_terminal_id
                            .as_ref()
                            .is_some_and(|selected| closed_ids.contains(selected.as_str()))
                        {
                            this.selected_composer_terminal_id = this
                                .composer_terminals
                                .first()
                                .map(|terminal| terminal.id.clone());
                        }
                        if this.selected_composer_terminal_id.is_none() {
                            this.composer_terminal_mode = false;
                            this.composer_terminal_expanded = false;
                        }
                        this.sync_composer_terminal_surface_activity(cx);
                        if !errors.is_empty() {
                            this.agent_error =
                                Some(format!("terminal close failed: {}", errors.join("; ")));
                        }
                        this.queue_ui_state();
                    }
                    Err(error) => {
                        this.agent_error = Some(format!("terminal close task failed: {error}"));
                    }
                }
                cx.notify();
            });
        }));
    }

    fn switch_composer_terminal_shell(
        &mut self,
        terminal_id: TerminalId,
        shell: String,
        cx: &mut Context<Self>,
    ) {
        if self.agent_action_pending
            || self
                .composer_terminals
                .iter()
                .find(|terminal| terminal.id == terminal_id)
                .is_none_or(|terminal| terminal.shell == shell)
        {
            return;
        }
        let Some(transport) = self.terminal_transport(cx) else {
            return;
        };
        self.agent_action_pending = true;
        self.agent_error = None;
        let generation = self.session_generation;
        let request = TerminalSwitchShellRequest {
            terminal_id: terminal_id.clone(),
            shell,
        };
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            transport
                .transport
                .switch_shell(request)
                .await
                .map_err(|error| {
                    vibex_core::VibexError::new(
                        vibex_core::ErrorCategory::Storage,
                        error.code,
                        error.message,
                    )
                })
        });
        let entity = cx.weak_entity();
        self.agent_action_task = Some(cx.spawn(async move |_, cx| {
            let outcome = runner.await;
            let _ = entity.update(cx, |this, cx| {
                this.agent_action_pending = false;
                if this.session_generation != generation {
                    return;
                }
                match outcome {
                    Ok(Ok(session)) => {
                        if let Some(terminal) = this
                            .composer_terminals
                            .iter_mut()
                            .find(|terminal| terminal.id == terminal_id)
                        {
                            *terminal = session.clone();
                        }
                        if let Some(surface) =
                            this.composer_terminal_surfaces.get(terminal_id.as_str())
                        {
                            surface.update(cx, |surface, cx| {
                                surface.replace_embedded_session(session.clone(), cx)
                            });
                        }
                    }
                    Ok(Err(error)) => {
                        this.agent_error = Some(format!(
                            "terminal shell switch failed: {}: {}",
                            error.code, error.message
                        ));
                    }
                    Err(error) => {
                        this.agent_error =
                            Some(format!("terminal shell switch task failed: {error}"));
                    }
                }
                cx.notify();
            });
        }));
    }

    fn prompt_rename_composer_terminal(
        &mut self,
        terminal_id: TerminalId,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if window.has_active_dialog(cx) {
            return;
        }
        let Some(terminal) = self
            .composer_terminals
            .iter()
            .find(|terminal| terminal.id == terminal_id)
            .cloned()
        else {
            return;
        };
        let initial = terminal_tab_title(&terminal, &self.ui_state.terminal_tab_titles);
        let terminal_name_placeholder = locale::text("Terminal name", "终端名称", "終端機名稱");
        let rename_title = locale::text("Rename terminal", "重命名终端", "重新命名終端機");
        let cancel_label = locale::text("Cancel", "取消", "取消");
        let rename_label = locale::text("Rename", "重命名", "重新命名");
        let entity = cx.weak_entity();
        // Keep the input outside the dialog builder. A builder is evaluated
        // again on every repaint, so an input created inside one would be
        // replaced — along with its focus handle and its text — while the user
        // types.
        let input = cx.new(|cx| {
            InputState::new(window, cx)
                .default_value(initial.clone())
                .placeholder(terminal_name_placeholder)
        });
        let input_for_focus = input.clone();
        let selection_end = initial.len();
        window.open_dialog(cx, move |dialog, _window, _cx| {
            let rename_input = input.clone();
            let entity = entity.clone();
            let terminal_id = terminal_id.clone();
            let default_title = terminal.title.clone();
            dialog
                .title(rename_title)
                .child(Input::new(&input))
                .footer(
                    DialogFooter::new()
                        .child(
                            DialogClose::new().child(
                                Button::new("cancel-terminal-rename")
                                    .outline()
                                    .label(cancel_label),
                            ),
                        )
                        .child(
                            DialogAction::new().child(
                                Button::new("confirm-terminal-rename")
                                    .primary()
                                    .label(rename_label),
                            ),
                        ),
                )
                .on_ok(move |_, _, cx| {
                    let title = rename_input.read(cx).value().trim().to_string();
                    if !title.is_empty() {
                        let _ = entity.update(cx, |this, cx| {
                            if title == default_title {
                                this.ui_state
                                    .terminal_tab_titles
                                    .remove(terminal_id.as_str());
                            } else {
                                this.ui_state
                                    .terminal_tab_titles
                                    .insert(terminal_id.as_str().to_string(), title.clone());
                            }
                            this.queue_ui_state();
                            cx.notify();
                        });
                    }
                    true
                })
        });
        // The dialog's focus trap claims focus while it mounts; request the
        // field on the next frame and select the current title so typing
        // replaces it.
        window.on_next_frame(move |window, cx| {
            input_for_focus.update(cx, |input, cx| {
                input.set_selected_range(0..selection_end, cx);
                input.focus(window, cx);
            });
        });
    }

    fn open_local_history_import_dialog(
        &mut self,
        workspace: Option<(String, WorkspaceMode)>,
        initial_search: Option<String>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if window.has_active_dialog(cx) {
            return;
        }
        let locale_mode = self.ui_state.appearance.locale;
        let focus_workspace = workspace.as_ref().map(|(root, _)| root.clone());
        let workbench = cx.weak_entity();
        let dialog_view: Entity<LocalHistoryImportDialog> = cx.new(|cx| {
            LocalHistoryImportDialog::new(
                self.runtime.clone(),
                workbench.clone(),
                focus_workspace.clone(),
                initial_search.clone(),
                locale_mode,
                window,
                cx,
            )
        });
        let title = self.strings().sidebar_import_sessions.to_string();
        let viewport = window.viewport_size();
        let dialog_width = (f32::from(viewport.width) - 32.0).clamp(280.0, 760.0);
        // The picker body scrolls internally via its own tracked handle, while
        // the action bar lives in the dialog footer slot, fixed below it.
        let dialog_height = (f32::from(viewport.height) - 32.0).clamp(1.0, 672.0);
        let dialog_entity = dialog_view.downgrade();
        window.open_dialog(cx, move |dialog, _, cx| {
            let is_dark = cx.theme().is_dark();
            let popover = theme::semantic_color("popover", is_dark);
            let popover_foreground = theme::semantic_color("popover-foreground", is_dark);
            // Rebuilt on every dialog render so the footer always reflects
            // the picker's live selection/pending state.
            let footer = dialog_entity
                .update(cx, |picker, cx| picker.render_footer(cx).into_any_element())
                .unwrap_or_else(|_| div().into_any_element());
            let content_view = dialog_view.clone();
            dialog
                .title(title.clone())
                .w(px(dialog_width))
                .max_w(px(dialog_width))
                .h(px(dialog_height))
                .rounded(px(14.0))
                .bg(popover)
                .text_color(popover_foreground)
                .border_color(popover_foreground.opacity(0.10))
                .overlay(true)
                .overlay_closable(true)
                .content(move |content, _, _| {
                    // `min_h_0` + `overflow_hidden` are load-bearing: the dialog
                    // content column is a `flex_1` item without a minimum, so
                    // taffy would otherwise grow it to its min-content height
                    // (the full session list), clip the overflow inside the
                    // dialog, and leave the bottom rows unreachable even with
                    // the list's own scrollbar bottomed out.
                    content
                        .min_h_0()
                        .overflow_hidden()
                        .pt(px(4.0))
                        .child(content_view.clone())
                })
                .footer(footer)
        });
        cx.notify();
    }

    pub(crate) fn complete_local_history_import(
        &mut self,
        session_id: Option<VibexSessionId>,
        cx: &mut Context<Self>,
    ) {
        if let Some(session_id) = session_id {
            self.selected_session_id = Some(session_id);
        }
        self.load_agent_overview(cx);
        cx.notify();
    }

    fn reset_new_session_project_menu(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.new_session_project_menu_close_task = None;
        self.new_session_project_menu_open = false;
        self.new_session_project_menu_mounted = false;
        self.new_session_project_search
            .update(cx, |input, cx| input.set_value("", window, cx));
    }

    fn set_new_session_project_menu_open(
        &mut self,
        open: bool,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.new_session_project_menu_close_task = None;
        self.new_session_project_menu_open = open;
        if open {
            self.new_session_project_menu_mounted = true;
            self.new_session_project_menu_focus.focus(window, cx);
        } else if self.ui_state.appearance.reduced_motion {
            self.new_session_project_menu_mounted = false;
        } else if self.new_session_project_menu_mounted {
            self.new_session_project_menu_close_task = Some(cx.spawn(async move |entity, cx| {
                cx.background_executor()
                    .timer(NEW_SESSION_PROJECT_MENU_TRANSITION_DURATION)
                    .await;
                let _ = entity.update(cx, |this, cx| {
                    this.new_session_project_menu_close_task = None;
                    if !this.new_session_project_menu_open {
                        this.new_session_project_menu_mounted = false;
                        cx.notify();
                    }
                });
            }));
        }
        cx.notify();
    }

    fn open_new_project_session(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.open_new_session(None, window, cx);
        if self.new_session_open {
            self.set_new_session_project_menu_open(true, window, cx);
        }
    }

    fn choose_project_for_new_session(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if self.sidebar_picker_task.is_some() || self.agent_action_pending {
            return;
        }
        if !self.new_session_open {
            self.open_new_session(None, window, cx);
        }
        self.set_new_session_project_menu_open(false, window, cx);
        self.open_project_directory_picker(window, cx);
    }

    /// Opens the in-app folder browser used to pick a project directory for
    /// a new session. The picker only resolves a path; the workspace is
    /// opened by [`Self::open_picked_project_workspace`] once the user
    /// confirms.
    fn open_project_directory_picker(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if window.has_active_dialog(cx) {
            return;
        }
        let locale_mode = self.ui_state.appearance.locale;
        let workbench = cx.weak_entity();
        // A paired authority owns the directories an Agent can run in, so the
        // picker browses the runtime instead of this machine. An authority
        // that predates the browse capability keeps the local picker.
        let source = match &self.backend {
            Some(backend)
                if self.remote_client.is_some()
                    && backend
                        .capabilities()
                        .workspace
                        .supports(BackendOperation::WorkspaceBrowseDirectories) =>
            {
                DirectoryBrowseTarget::Authority(backend.clone())
            }
            _ => DirectoryBrowseTarget::Local,
        };
        let remote = source.is_authority();
        // Start at the selected project's root when there is one, so the
        // common "sibling of the current project" case is one step away. A
        // remote root is only known to exist on the authority, which answers
        // the first listing either way, so it is never pre-checked here.
        let initial_dir = {
            let project_root = self.new_session_workspace.project_root.trim();
            (!project_root.is_empty() && (remote || Path::new(project_root).is_dir()))
                .then(|| PathBuf::from(project_root))
        };
        let on_pick: DirectoryPickHandler = Arc::new(move |root_path, window, cx| {
            workbench
                .update(cx, |workbench, cx| {
                    workbench.open_picked_project_workspace(root_path, window, cx);
                })
                .is_ok()
        });
        // The picker repaints its own stars; the workbench owns the preference,
        // so every star lands in the persisted UI state.
        let favorites = self.ui_state.workbench.favorite_project_directories.clone();
        let favorites_workbench = cx.weak_entity();
        let on_favorites_change: DirectoryFavoritesHandler = Arc::new(move |favorites, cx| {
            let _ = favorites_workbench.update(cx, |workbench, cx| {
                workbench.set_favorite_project_directories(favorites, cx);
            });
        });
        let dialog_view: Entity<DirectoryPickerDialog> = cx.new(|cx| {
            DirectoryPickerDialog::new(
                locale_mode,
                initial_dir,
                favorites,
                source,
                on_pick,
                on_favorites_change,
                window,
                cx,
            )
        });
        let title = locale::text("Choose project directory", "选择项目目录", "選擇專案目錄");
        let viewport = window.viewport_size();
        let dialog_width = (f32::from(viewport.width) - 48.0).clamp(420.0, 640.0);
        let dialog_height = (f32::from(viewport.height) - 48.0).clamp(1.0, 520.0);
        let dialog_entity = dialog_view.downgrade();
        window.open_dialog(cx, move |dialog, _, cx| {
            let is_dark = cx.theme().is_dark();
            let popover = theme::semantic_color("popover", is_dark);
            let popover_foreground = theme::semantic_color("popover-foreground", is_dark);
            // Rebuilt on every dialog render so the footer always reflects
            // the picker's live browse position.
            let footer = dialog_entity
                .update(cx, |picker, cx| picker.render_footer(cx).into_any_element())
                .unwrap_or_else(|_| div().into_any_element());
            let content_view = dialog_view.clone();
            dialog
                .title(title)
                .w(px(dialog_width))
                .max_w(px(dialog_width))
                .h(px(dialog_height))
                .rounded(px(14.0))
                .bg(popover)
                .text_color(popover_foreground)
                .border_color(popover_foreground.opacity(0.10))
                // The picker owns Enter/Escape through its own key handler;
                // the dialog defaults would confirm on every propagated
                // keystroke before the browser sees it.
                .keyboard(false)
                .overlay(true)
                .overlay_closable(true)
                .content(move |content, _, _| {
                    // `min_h_0` + `overflow_hidden` keep the dialog content
                    // column from growing to its min-content height, the
                    // same load-bearing combo the session importer uses.
                    content
                        .min_h_0()
                        .overflow_hidden()
                        .pt(px(4.0))
                        .child(content_view.clone())
                })
                .footer(footer)
        });
        cx.notify();
    }

    fn open_picked_project_workspace(
        &mut self,
        root_path: String,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(backend) = self.backend.clone() else {
            self.new_session_error = Some("Local backend is not ready".into());
            cx.notify();
            return;
        };
        if !self.new_session_open {
            self.open_new_session(None, window, cx);
        }
        let entity = cx.weak_entity();
        let picker = gpui_tokio::Tokio::spawn(cx, async move {
            backend
                .workspace()
                .open_workspace(
                    MutationRequest::new(OpenWorkspaceRequest {
                        root_path,
                        mode: Some(WorkspaceMode::CurrentCheckout),
                    })
                    .with_idempotency_key(format!(
                        "new-session-open-workspace:{}",
                        RequestId::new()
                    )),
                )
                .await
                .map(Some)
        });
        self.sidebar_picker_task = Some(cx.spawn_in(window, async move |_, cx| {
            let outcome = picker.await;
            let _ = entity.update_in(cx, |this, window, cx| {
                this.sidebar_picker_task = None;
                match outcome {
                    Ok(Ok(Some(summary))) => {
                        let project_id = summary.project.id.clone();
                        let is_new_project = this
                            .workspaces
                            .iter()
                            .all(|(project, _)| project.id != project_id);
                        if is_new_project {
                            this.store_sidebar_project_appearance(
                                project_id.as_str().to_string(),
                                SidebarProjectAppearance {
                                    logo: SidebarProjectLogo::default(),
                                    color: sidebar_project_logo_color_for_new_project(&project_id),
                                    custom_logo_file: None,
                                },
                                cx,
                            );
                        }
                        this.workspaces
                            .retain(|(_, workspace)| workspace.id != summary.workspace.id);
                        this.workspaces.push((summary.project, summary.workspace));
                        this.reconcile_sidebar_state();
                        this.select_new_session_target(
                            NewSessionOpenTarget::Project(project_id),
                            window,
                            cx,
                        );
                        this.new_session_project_search
                            .update(cx, |input, cx| input.set_value("", window, cx));
                        this.refresh_workspace_contexts(cx);
                    }
                    Ok(Ok(None)) => {}
                    Ok(Err(error)) => {
                        this.new_session_error = Some(format!("{}: {}", error.code, error.message));
                    }
                    Err(error) => {
                        this.new_session_error = Some(format!("project selection failed: {error}"));
                    }
                }
                this.new_session_input
                    .update(cx, |input, cx| input.focus(window, cx));
                cx.notify();
            });
        }));
    }

    /// Replaces the starred project directories the directory picker offers as
    /// quick locations. The picker has already repainted its own stars; this
    /// only records the preference so the next picker opens with it.
    fn set_favorite_project_directories(&mut self, favorites: Vec<String>, cx: &mut Context<Self>) {
        if self.ui_state.workbench.favorite_project_directories == favorites {
            return;
        }
        self.ui_state.workbench.favorite_project_directories = favorites;
        self.queue_ui_state();
        cx.notify();
    }

    fn resolve_permission(
        &mut self,
        session_id: VibexSessionId,
        request_id: String,
        response: PermissionResponseKind,
        provider_resolution_id: Option<String>,
        cx: &mut Context<Self>,
    ) {
        if self.agent_action_pending {
            return;
        }
        let Some(backend) = self.backend.clone() else {
            return;
        };
        let Ok(request_id) = RequestId::parse(request_id) else {
            return;
        };
        self.agent_action_pending = true;
        let generation = self.session_generation;
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            backend
                .agent()
                .resolve_permission(MutationRequest::new(ResolvePermissionRequest {
                    session_id: session_id.clone(),
                    request_id: request_id.clone(),
                    resolution: PermissionResolution {
                        request_id,
                        session_id,
                        response,
                        responder_device_id: None,
                        provider_resolution_id,
                        note: None,
                        resolved_at_ms: unix_timestamp_ms(),
                    },
                }))
                .await
        });
        self.agent_action_task = Some(cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                let outcome = runner.await;
                let _ = entity.update(cx, |this, cx| {
                    this.agent_action_pending = false;
                    if this.session_generation != generation {
                        return;
                    }
                    if let Ok(Err(error)) = outcome {
                        this.agent_error = Some(format!("{}: {}", error.code, error.message));
                    }
                    cx.notify();
                });
            },
        ));
    }

    fn elicitation_input_key(request_id: &str, field_id: &str) -> String {
        format!("{request_id}:{field_id}")
    }

    fn prune_elicitation_forms(&mut self) {
        let mut pending = BTreeSet::new();
        for item in &self.timeline.items {
            match &item.payload {
                TimelinePayload::ElicitationRequest(request)
                    if request.status == vibex_core::ElicitationRequestStatus::Pending =>
                {
                    pending.insert(request.id.to_string());
                }
                TimelinePayload::ElicitationResolution(resolution) => {
                    pending.remove(resolution.request_id.as_str());
                }
                _ => {}
            }
        }
        self.elicitation_drafts
            .retain(|request_id, _| pending.contains(request_id));
        self.elicitation_inputs.retain(|key, _| {
            key.split_once(':')
                .is_some_and(|(request_id, _)| pending.contains(request_id))
        });
    }

    fn ensure_elicitation_form(
        &mut self,
        request: &ElicitationRequest,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.elicitation_drafts
            .entry(request.id.to_string())
            .or_insert_with(|| ElicitationFormDraft::from_request(request));
        for field in &request.fields {
            let uses_input = matches!(
                &field.kind,
                ElicitationFieldKind::Text { options, .. } if options.is_empty()
            ) || matches!(
                &field.kind,
                ElicitationFieldKind::Number { .. } | ElicitationFieldKind::Integer { .. }
            );
            if !uses_input {
                continue;
            }
            let key = Self::elicitation_input_key(request.id.as_str(), &field.id);
            if self.elicitation_inputs.contains_key(&key) {
                continue;
            }
            let initial_value = self
                .elicitation_drafts
                .get(request.id.as_str())
                .and_then(|draft| draft.text(&field.id))
                .unwrap_or_default()
                .to_string();
            let placeholder = field.title.clone();
            let input = cx.new(|cx| {
                let mut input = InputState::new(window, cx).placeholder(placeholder);
                if !initial_value.is_empty() {
                    input.set_value(initial_value, window, cx);
                }
                input
            });
            self.elicitation_inputs.insert(key, input);
        }
    }

    fn resolve_elicitation(
        &mut self,
        request: ElicitationRequest,
        action: ElicitationResolutionAction,
        cx: &mut Context<Self>,
    ) {
        if self.agent_action_pending {
            return;
        }
        // Elicitation resolution is an authoritative session mutation, so it
        // rides the backend facade. The local runtime used to own this path,
        // which made the Approve/Decline controls silently inert whenever the
        // workbench was paired with a remote runtime.
        let Some(backend) = self.backend.clone() else {
            return;
        };
        let request_id = request.id.to_string();
        let text_values = request
            .fields
            .iter()
            .filter_map(|field| {
                let key = Self::elicitation_input_key(request.id.as_str(), &field.id);
                self.elicitation_inputs
                    .get(&key)
                    .map(|input| (field.id.clone(), input.read(cx).value().to_string()))
            })
            .collect::<Vec<_>>();
        let draft = self
            .elicitation_drafts
            .entry(request_id.clone())
            .or_insert_with(|| ElicitationFormDraft::from_request(&request));
        for (field_id, value) in text_values {
            if request
                .fields
                .iter()
                .find(|field| field.id == field_id)
                .is_some_and(|field| field.required || !value.is_empty())
            {
                draft.set_text(field_id, value);
            } else {
                draft.values.remove(&field_id);
            }
        }
        let resolution = match draft.resolve_request(&request, action, unix_timestamp_ms()) {
            Ok(request) => request,
            Err(error) => {
                self.agent_error = Some(format!("{}: {}", error.code, error.message));
                cx.notify();
                return;
            }
        };
        self.agent_action_pending = true;
        let generation = self.session_generation;
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            backend
                .agent()
                .resolve_elicitation(MutationRequest::new(resolution))
                .await
        });
        self.agent_action_task = Some(cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                let outcome = runner.await;
                let _ = entity.update(cx, |this, cx| {
                    this.agent_action_pending = false;
                    if this.session_generation != generation {
                        return;
                    }
                    match outcome {
                        Ok(Ok(_)) => {
                            this.elicitation_drafts.remove(&request_id);
                            let prefix = format!("{request_id}:");
                            this.elicitation_inputs
                                .retain(|key, _| !key.starts_with(&prefix));
                        }
                        Ok(Err(error)) => {
                            this.agent_error = Some(format!("{}: {}", error.code, error.message));
                        }
                        Err(error) => {
                            this.agent_error = Some(format!("elicitation failed: {error}"));
                        }
                    }
                    cx.notify();
                });
            },
        ));
    }

    fn interrupt_session(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.interrupt_session_with_queue_behavior(
            ComposerQueueInterruptBehavior::Pause,
            window,
            cx,
        );
    }

    fn interrupt_session_with_queue_behavior(
        &mut self,
        queue_behavior: ComposerQueueInterruptBehavior,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if self.agent_action_pending {
            return;
        }
        let (Some(backend), Some(session_id)) =
            (self.backend.clone(), self.view_session_id.clone())
        else {
            return;
        };
        // An explicit user interrupt suspends this session's auto-continue
        // without discarding its persisted preference. The pause survives
        // restarts and clears when the user resumes it or sends a new message.
        self.pause_auto_continue(&session_id, cx);
        self.notification_suppressed_session_ids
            .insert(session_id.as_str().to_string());
        let has_queued_messages = self
            .composer_queue
            .iter()
            .any(|message| message.session_id == session_id);
        let turn_was_locally_pending = self.session_turn_pending(&session_id);
        match queue_behavior {
            ComposerQueueInterruptBehavior::Pause if has_queued_messages => {
                self.composer_queue_paused_session_ids
                    .insert(session_id.as_str().to_string());
                if turn_was_locally_pending {
                    self.composer_queue_interrupted_session_ids
                        .insert(session_id.as_str().to_string());
                }
            }
            ComposerQueueInterruptBehavior::Steer => {
                self.composer_queue_paused_session_ids
                    .remove(session_id.as_str());
                self.composer_queue_steering_session_ids
                    .insert(session_id.as_str().to_string());
            }
            ComposerQueueInterruptBehavior::Pause => {}
        }
        if let Some(cancel) = self
            .pending_initial_turn_interrupts
            .get(session_id.as_str())
        {
            if cancel.send(true).is_ok() {
                // The initial session task owns the durable submission and will
                // invoke AgentManager::interrupt after that fence exists.
                self.agent_action_pending = true;
                self.agent_error = None;
                cx.notify();
                return;
            }
            self.pending_initial_turn_interrupts
                .remove(session_id.as_str());
        }
        self.agent_action_pending = true;
        self.agent_error = None;
        let generation = self.session_generation;
        let interrupted_session_id = session_id.clone();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            backend
                .agent()
                .interrupt(MutationRequest::new(session_id.clone()))
                .await
                .map_err(crate::app::remote_error_into_vibex)?;
            Ok::<_, vibex_core::VibexError>(backend.agent().open_session(session_id).await.ok())
        });
        self.agent_action_task = Some(cx.spawn_in(
            window,
            async move |entity: WeakEntity<Self>, cx| {
                let outcome = runner.await;
                let _ = entity.update_in(cx, |this, window, cx| {
                    if let Ok(Ok(session)) = &outcome {
                        if let Some(session) = session {
                            this.upsert_session_snapshot(session.clone());
                        }
                        this.reconcile_sidebar_state();
                        if !turn_was_locally_pending {
                            this.set_session_turn_pending(&interrupted_session_id, false);
                        }
                        this.publish_sidebar_invalidation();
                        this.sync_auto_continue_for_session(&interrupted_session_id, cx);
                    }
                    this.agent_action_pending = false;
                    if this.session_generation != generation
                        || this.selected_session_id.as_ref() != Some(&interrupted_session_id)
                    {
                        cx.notify();
                        return;
                    }
                    match &outcome {
                        Ok(Ok(_)) => {
                            if queue_behavior == ComposerQueueInterruptBehavior::Steer
                                && !this.session_turn_pending(&interrupted_session_id)
                            {
                                this.composer_queue_steering_session_ids
                                    .remove(interrupted_session_id.as_str());
                                this.maybe_dispatch_next_composer_queue_message(
                                    &interrupted_session_id,
                                    ComposerQueueDispatchBehavior::AfterInterrupt,
                                    window,
                                    cx,
                                );
                            }
                        }
                        Ok(Err(error)) => {
                            this.agent_error = Some(format!("{}: {}", error.code, error.message));
                            this.notification_suppressed_session_ids
                                .remove(interrupted_session_id.as_str());
                            this.composer_queue_interrupted_session_ids
                                .remove(interrupted_session_id.as_str());
                            if queue_behavior == ComposerQueueInterruptBehavior::Steer {
                                this.composer_queue_steering_session_ids
                                    .remove(interrupted_session_id.as_str());
                                this.composer_queue_paused_session_ids
                                    .insert(interrupted_session_id.as_str().to_string());
                            }
                        }
                        Err(error) => {
                            this.agent_error = Some(format!("Agent interrupt failed: {error}"));
                            this.notification_suppressed_session_ids
                                .remove(interrupted_session_id.as_str());
                            this.composer_queue_interrupted_session_ids
                                .remove(interrupted_session_id.as_str());
                            if queue_behavior == ComposerQueueInterruptBehavior::Steer {
                                this.composer_queue_steering_session_ids
                                    .remove(interrupted_session_id.as_str());
                                this.composer_queue_paused_session_ids
                                    .insert(interrupted_session_id.as_str().to_string());
                            }
                        }
                    }
                    cx.notify();
                });
            },
        ));
    }

    /// Sends a queued message into the running turn through the Agent's native
    /// steering path. Falls back to the universal interrupt + resend path when
    /// the turn ended first or the native request fails.
    fn native_steer_composer_queue_message(
        &mut self,
        message_id: u64,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(session_id) = self.move_composer_queue_message_to_front(message_id) else {
            return;
        };
        let Some(backend) = self.backend.clone() else {
            self.steer_composer_queue_message(message_id, window, cx);
            return;
        };
        let Some(message) = self
            .composer_queue
            .iter()
            .find(|message| message.id == message_id)
            .cloned()
        else {
            return;
        };
        if !self.agent_session_is_active(&session_id) {
            self.steer_composer_queue_message(message_id, window, cx);
            return;
        }
        self.composer_queue_paused_session_ids
            .remove(session_id.as_str());
        let after_sequence = self.session_view_end_sequence(&session_id).unwrap_or(0);
        self.install_optimistic_user_message(OptimisticUserMessage {
            session_id: session_id.clone(),
            item_id: TimelineItemId::new(),
            after_sequence,
            submitted_at_ms: unix_timestamp_ms(),
            text: message.text.clone(),
            attachments: message.attachments.clone(),
        });
        self.agent_action_pending = true;
        self.agent_error = None;
        let generation = self.session_generation;
        let request = SteerAgentMessageRequest {
            session_id: session_id.clone(),
            text: message.text.clone(),
            attachments: message.attachments.clone(),
            correlation_id: None,
        };
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            backend
                .agent()
                .steer_message(MutationRequest::new(request))
                .await
                .map_err(crate::app::remote_error_into_vibex)
        });
        self.agent_action_task = Some(cx.spawn_in(
            window,
            async move |entity: WeakEntity<Self>, cx| {
                let outcome = runner.await;
                let _ = entity.update_in(cx, |this, window, cx| {
                    this.agent_action_pending = false;
                    if this.session_generation != generation
                        || this.selected_session_id.as_ref() != Some(&session_id)
                    {
                        cx.notify();
                        return;
                    }
                    let injected = matches!(
                        &outcome,
                        Ok(Ok(result)) if result.outcome == SteerMessageOutcome::Injected
                    );
                    if injected {
                        this.composer_queue.retain(|queued| queued.id != message_id);
                        this.set_session_turn_pending(&session_id, true);
                        this.reconcile_sidebar_state();
                        this.publish_sidebar_invalidation();
                        cx.notify();
                        return;
                    }
                    // `PromptRequired` and transport failures keep the
                    // universal cancel + resend fallback, which owns idle
                    // dispatch and pause state.
                    this.steer_composer_queue_message(message_id, window, cx);
                });
            },
        ));
        cx.notify();
    }

    fn continue_session(&mut self, cx: &mut Context<Self>) {
        let Some(session_id) = self.selected_session_id.clone() else {
            return;
        };
        self.continue_session_by_id(session_id, None, cx);
    }

    fn continue_session_by_id(
        &mut self,
        session_id: VibexSessionId,
        expected_turn_updated_at_ms: Option<i64>,
        cx: &mut Context<Self>,
    ) {
        if self.agent_action_pending || self.session_turn_pending(&session_id) {
            return;
        }
        let Some((session_state, turn_updated_at_ms)) = self
            .sessions
            .iter()
            .find(|session| session.id == session_id)
            .map(|session| (session.state, session.updated_at_ms))
        else {
            return;
        };
        let latest_turn_ended_normally = self
            .cached_auto_continue_turn_status(&session_id, turn_updated_at_ms)
            .and_then(|status| status.ended_normally);
        if !agent_session_turn_requires_continuation(session_state, latest_turn_ended_normally) {
            return;
        }
        if expected_turn_updated_at_ms.is_some_and(|expected| expected != turn_updated_at_ms) {
            return;
        }
        let Some(backend) = self.backend.clone() else {
            return;
        };
        self.cancel_auto_continue_countdown(&session_id);
        self.auto_continue_handled_turns
            .insert(session_id.as_str().to_string(), turn_updated_at_ms);
        self.notification_suppressed_session_ids
            .remove(session_id.as_str());
        self.set_session_turn_pending(&session_id, true);
        // An explicit manual continuation is also a user reactivation.
        if self.auto_continue_enabled(&session_id) {
            self.resume_auto_continue(&session_id, cx);
        }
        if self.view_session_id.as_ref() == Some(&session_id) {
            self.agent_error = None;
        }
        cx.notify();
        let generation = self.session_generation;
        let continued_session_id = session_id.clone();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            let outcome = backend
                .agent()
                .continue_turn(MutationRequest::new(ContinueAgentTurnRequest {
                    session_id: session_id.clone(),
                    correlation_id: None,
                }))
                .await
                .map(|_| ());
            let session = backend.agent().open_session(session_id.clone()).await.ok();
            (outcome, session)
        });
        cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                let outcome = runner.await;
                let _ = entity.update(cx, |this, cx| {
                    if let Ok((_, Some(session))) = &outcome {
                        this.upsert_session_snapshot(session.clone());
                        this.reconcile_sidebar_state();
                    }
                    this.set_session_turn_pending(&continued_session_id, false);
                    this.sync_auto_continue_for_session(&continued_session_id, cx);
                    this.publish_sidebar_invalidation();
                    if matches!(&outcome, Ok((Ok(_), _)))
                        && this
                            .composer_queue
                            .iter()
                            .any(|message| message.session_id == continued_session_id)
                    {
                        // The queue was fenced while the previous turn needed
                        // continuation. Let the next frame dispatch it only
                        // after the continuation has completed successfully.
                        this.composer_queue_ready_after_continuation_session_ids
                            .insert(continued_session_id.as_str().to_string());
                    }
                    if !agent_turn_completion_is_active(
                        this.session_generation,
                        generation,
                        this.selected_session_id.as_ref(),
                        &continued_session_id,
                    ) {
                        cx.notify();
                        return;
                    }
                    match outcome {
                        Ok((Ok(_), _)) => this.refresh_selected_agent_timeline(cx),
                        Ok((Err(error), _)) => {
                            this.agent_error = Some(format!("{}: {}", error.code, error.message));
                        }
                        Err(error) => {
                            this.agent_error = Some(format!("Agent action failed: {error}"));
                        }
                    }
                    cx.notify();
                });
            },
        )
        .detach();
    }

    fn fork_session_at(
        &mut self,
        through_sequence: i64,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if self.agent_action_pending || self.fork_session_pending || through_sequence <= 0 {
            return;
        }
        let (Some(runtime), Some(source_session_id)) =
            (self.runtime.clone(), self.selected_session_id.clone())
        else {
            if let (Some(backend), Some(source_session_id)) =
                (self.backend.clone(), self.selected_session_id.clone())
            {
                self.fork_session_at_remote(
                    backend,
                    source_session_id,
                    through_sequence,
                    window,
                    cx,
                );
            }
            return;
        };
        self.agent_action_pending = true;
        self.fork_session_pending = true;
        self.agent_error = None;
        window.push_notification(
            hint_notification(
                NotificationType::Info,
                locale::text(
                    "Creating forked session...",
                    "正在创建分叉会话...",
                    "正在建立分支會話...",
                ),
                cx,
            )
            .id::<ForkSessionNotification>()
            .autohide(false),
            cx,
        );
        let generation = self.session_generation;
        let selected_source_session_id = source_session_id.clone();
        let completion_runtime = runtime.clone();
        let (created_tx, mut created_rx) = mpsc::unbounded_channel();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            let manager = runtime.agent().manager();
            let mut created_session_id = None;
            let result = manager
                .fork_session_with_created_callback(
                    ForkAgentSessionRequest {
                        source_session_id,
                        through_sequence,
                        expected_source_end_sequence: None,
                    },
                    |session| {
                        created_session_id = Some(session.id.clone());
                        let _ = created_tx.send(session);
                    },
                )
                .await;
            let persisted_session = if result.is_err() {
                match created_session_id {
                    Some(session_id) => manager.get_session(&session_id).await.ok(),
                    None => None,
                }
            } else {
                None
            };
            (result, persisted_session)
        });
        self.fork_session_task = Some(cx.spawn_in(
            window,
            async move |entity: WeakEntity<Self>, cx| {
                let announced_session_id = match created_rx.recv().await {
                    Some(session) => {
                        let session_id = session.id.clone();
                        let announced_session_id = session_id.clone();
                        let _ = entity.update_in(cx, |this, window, cx| {
                            this.upsert_session_snapshot(session);
                            this.reconcile_sidebar_state();
                            this.publish_sidebar_invalidation();
                            let source_still_selected = this.session_generation == generation
                                && this.selected_session_id.as_ref()
                                    == Some(&selected_source_session_id);
                            if source_still_selected {
                                this.select_session_with_history(session_id, false, cx);
                            }
                            window.push_notification(
                                hint_notification(
                                    NotificationType::Info,
                                    locale::text(
                                        "Fork created. Preparing its runtime...",
                                        "分叉会话已创建，正在准备运行时...",
                                        "分支會話已建立，正在準備執行環境...",
                                    ),
                                    cx,
                                )
                                .id::<ForkSessionNotification>()
                                .autohide(false),
                                cx,
                            );
                            cx.notify();
                        });
                        Some(announced_session_id)
                    }
                    None => None,
                };
                let outcome = runner.await;
                let _ = entity.update_in(cx, |this, window, cx| {
                    this.fork_session_pending = false;
                    // The fork owns the window-wide short action lock until its
                    // runtime settles, and nothing else can take the lock while
                    // it is held. Releasing it must therefore never be fenced to
                    // the announcement or to the session the user is looking at:
                    // the announced path navigates to the forked session, which
                    // bumps `session_generation`, so a fenced release left the
                    // lock set forever and pinned every composer and the
                    // new-session controls in their loading state until restart.
                    this.agent_action_pending = false;
                    match outcome {
                        Ok((Ok(session), _)) => {
                            let session_id = session.id.clone();
                            this.upsert_session_snapshot(session);
                            this.reconcile_sidebar_state();
                            this.publish_sidebar_invalidation();
                            if this.selected_session_id.as_ref() == Some(&session_id) {
                                let generation = this.session_generation;
                                this.load_agent_session_projection(
                                    completion_runtime.clone(),
                                    session_id.clone(),
                                    generation,
                                    cx,
                                );
                                this.start_runtime_heartbeat(
                                    completion_runtime.clone(),
                                    None,
                                    session_id,
                                    generation,
                                    cx,
                                );
                                this.refresh_selected_agent_timeline(cx);
                            }
                            window.push_notification(
                                hint_notification(
                                    NotificationType::Success,
                                    locale::text(
                                        "Forked session is ready",
                                        "分叉会话已就绪",
                                        "分支會話已就緒",
                                    ),
                                    cx,
                                )
                                .id::<ForkSessionNotification>(),
                                cx,
                            );
                        }
                        Ok((Err(error), persisted_session)) => {
                            if let Some(session) = persisted_session {
                                this.upsert_session_snapshot(session);
                                this.reconcile_sidebar_state();
                                this.publish_sidebar_invalidation();
                            }
                            if announced_session_id.as_ref().is_some_and(|session_id| {
                                this.selected_session_id.as_ref() == Some(session_id)
                            }) {
                                this.agent_error =
                                    Some(format!("{}: {}", error.code, error.message));
                            }
                            let message = if announced_session_id.is_some() {
                                locale::text(
                                    "Fork created, but its runtime could not start",
                                    "分叉会话已创建，但运行时启动失败",
                                    "分支會話已建立，但執行環境啟動失敗",
                                )
                            } else {
                                locale::text(
                                    "Could not create the forked session",
                                    "无法创建分叉会话",
                                    "無法建立分支會話",
                                )
                            };
                            window.push_notification(
                                hint_notification(NotificationType::Error, message, cx)
                                    .id::<ForkSessionNotification>()
                                    .autohide(false),
                                cx,
                            );
                        }
                        Err(error) => {
                            if announced_session_id.as_ref().is_some_and(|session_id| {
                                this.selected_session_id.as_ref() == Some(session_id)
                            }) {
                                this.agent_error =
                                    Some(format!("session fork task failed: {error}"));
                            }
                            window.push_notification(
                                hint_notification(
                                    NotificationType::Error,
                                    locale::text(
                                        "Forked session setup was interrupted",
                                        "分叉会话设置已中断",
                                        "分支會話設定已中斷",
                                    ),
                                    cx,
                                )
                                .id::<ForkSessionNotification>()
                                .autohide(false),
                                cx,
                            );
                        }
                    }
                    cx.notify();
                });
            },
        ));
    }

    #[allow(clippy::too_many_arguments)]
    fn begin_inline_user_message_edit(
        &mut self,
        turn_id: String,
        row_id: String,
        source_session_id: VibexSessionId,
        user_sequence: i64,
        expected_source_end_sequence: i64,
        initial: String,
        attachments: Vec<MessageAttachment>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if self.agent_action_pending || self.session_turn_pending(&source_session_id) {
            return;
        }
        let measured_turn_id = turn_id.clone();
        let (initial, attachments, serial) =
            composer_queue_edit_insertion(&initial, &attachments, self.composer_attachment_serial);
        self.composer_attachment_serial = serial;
        self.inline_user_message_edit = Some(InlineUserMessageEdit {
            turn_id,
            row_id,
            source_session_id,
            user_sequence,
            expected_source_end_sequence,
            attachments,
            geometry: ComposerGeometry::default(),
        });
        self.invalidate_timeline_turn_measurement(&measured_turn_id);
        self.rebuild_timeline_sizes();
        let selection_end = initial.len();
        self.user_message_edit_input.update(cx, move |input, cx| {
            input.set_value(initial, window, cx);
            input.set_selected_range(0..selection_end, cx);
            input.focus(window, cx);
        });
        cx.notify();
    }

    fn cancel_inline_user_message_edit(&mut self, cx: &mut Context<Self>) {
        let Some(edit) = self.inline_user_message_edit.take() else {
            return;
        };
        self.invalidate_timeline_turn_measurement(&edit.turn_id);
        self.rebuild_timeline_sizes();
        cx.notify();
    }

    fn submit_inline_user_message_edit(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if self.user_message_edit_input.update(cx, |input, cx| {
            EntityInputHandler::marked_text_range(input, window, cx).is_some()
        }) {
            return;
        }
        let Some(edit) = self.inline_user_message_edit.clone() else {
            return;
        };
        if self.agent_action_pending || self.session_turn_pending(&edit.source_session_id) {
            return;
        }
        let raw_text = self.user_message_edit_input.read(cx).value().to_string();
        let (text, attachments) = composer_submission_payload(&raw_text, &edit.attachments);
        if text.trim().is_empty() && attachments.is_empty() {
            return;
        }
        self.replace_latest_user_message(
            edit.source_session_id,
            edit.user_sequence,
            edit.expected_source_end_sequence,
            text,
            attachments,
            cx,
        );
    }

    fn replace_latest_user_message(
        &mut self,
        source_session_id: VibexSessionId,
        user_sequence: i64,
        expected_source_end_sequence: i64,
        text: String,
        attachments: Vec<MessageAttachment>,
        cx: &mut Context<Self>,
    ) {
        if self.agent_action_pending
            || self.session_turn_pending(&source_session_id)
            || self.selected_session_id.as_ref() != Some(&source_session_id)
            || user_sequence <= 0
            || expected_source_end_sequence < user_sequence
        {
            return;
        }
        // Rewriting the last user message is an authoritative timeline
        // mutation, so it rides the backend facade. The local runtime used to
        // own this path, which made the inline editor silently inert whenever
        // the workbench was paired with a remote runtime.
        let Some(backend) = self.backend.clone() else {
            return;
        };
        let submitted_at_ms = unix_timestamp_ms();
        let editing_turn_id = self
            .inline_user_message_edit
            .take()
            .map(|edit| edit.turn_id);
        self.pending_user_message_edit = Some(PendingUserMessageEdit {
            source_session_id: source_session_id.clone(),
            user_sequence,
            submitted_at_ms,
            text: text.clone(),
            attachments: attachments.clone(),
        });
        self.set_session_turn_pending(&source_session_id, true);
        self.agent_error = None;
        if let Some(turn_id) = editing_turn_id {
            self.invalidate_timeline_turn_measurement(&turn_id);
        }
        self.rebuild_timeline_sizes();
        self.request_timeline_scroll_to_latest();
        cx.notify();
        let generation = self.session_generation;
        let selected_source_session_id = source_session_id.clone();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            let selection = backend
                .agent()
                .runtime_selection(source_session_id.clone())
                .await;
            let outcome = match selection {
                Ok(selection) => {
                    let selection = selection.effective;
                    let reasoning_effort = selection.reasoning_effort.clone();
                    backend
                        .agent()
                        .replace_user_message(MutationRequest::new(ReplaceUserMessagePayload {
                            user_sequence,
                            expected_end_sequence: expected_source_end_sequence,
                            message: SendAgentMessageRequest {
                                session_id: source_session_id.clone(),
                                message_idempotency_key: format!(
                                    "gpui:edit:{}:{user_sequence}:{submitted_at_ms}",
                                    source_session_id.as_str()
                                ),
                                desired_runtime: selection,
                                text,
                                attachments,
                                reasoning_effort,
                                correlation_id: None,
                                delivery: UserMessageDelivery::Prompt,
                            },
                        }))
                        .await
                        .map_err(remote_error_into_vibex)
                }
                Err(error) => Err(remote_error_into_vibex(error)),
            };
            let session = backend
                .agent()
                .open_session(source_session_id.clone())
                .await
                .ok();
            (outcome, session)
        });
        cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                let outcome = runner.await;
                let _ = entity.update(cx, |this, cx| {
                    this.set_session_turn_pending(&selected_source_session_id, false);
                    this.pending_user_message_edit = None;
                    this.rebuild_timeline_sizes();
                    match outcome {
                        Ok((result, session)) => {
                            if let Some(session) = session {
                                this.upsert_session_snapshot(session);
                                this.reconcile_sidebar_state();
                                this.publish_sidebar_invalidation();
                            }
                            if let Err(error) = result {
                                this.agent_error =
                                    Some(format!("{}: {}", error.code, error.message));
                            }
                        }
                        Err(error) => {
                            this.agent_error =
                                Some(format!("edited message submission failed: {error}"));
                        }
                    }
                    if this.session_generation == generation
                        && this.selected_session_id.as_ref() == Some(&selected_source_session_id)
                    {
                        this.refresh_selected_agent_timeline(cx);
                    }
                    cx.notify();
                });
            },
        )
        .detach();
    }

    fn open_new_session(
        &mut self,
        target: Option<NewSessionOpenTarget>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.cancel_inline_user_message_edit(cx);
        self.reset_new_session_project_menu(window, cx);
        self.dismiss_sidebar_for_navigation();
        let primary_tab_changed = self.ui_state.workbench.active_tab != "agent";
        if primary_tab_changed {
            self.sync_current_navigation_entry();
            self.usage_session_filter = None;
            self.ui_state.workbench.active_tab = "agent".to_string();
            self.queue_ui_state();
        }
        let initialize_draft = !self.new_session_draft_initialized;
        self.new_session_open = true;
        self.sync_agent_streaming_surface_visibility();
        self.new_session_runtime_menu_open = false;
        self.runtime_choice_menu_open = None;
        self.new_session_runtime_menu_view = ComposerRuntimeMenuView::AuthSource;
        self.new_session_runtime_menu_auth_source = None;
        self.new_session_error = None;
        self.clear_suggestions();
        let explicit_target = target.is_some();
        if initialize_draft {
            self.new_session_attachments.clear();
            self.new_session_command_entry = None;
            let preferred_agent = self
                .selected_runtime_selection()
                .map(|selection| selection.agent_id)
                .or_else(|| self.new_session_agent_id.clone());
            self.new_session_agent_id =
                default_new_session_agent_id(&self.agent_snapshots, preferred_agent.as_ref());
            let preferred_runtime = self
                .new_session_agent_id
                .as_ref()
                .and_then(|agent_id| self.preferred_new_session_runtime_for_agent(agent_id));
            let selection = self.runtime_catalog.as_ref().and_then(|catalog| {
                new_session_runtime_selection_for_agent(
                    catalog,
                    self.new_session_agent_id.as_ref(),
                    preferred_runtime.as_ref(),
                )
            });
            self.set_new_session_runtime_selection(selection);
            self.new_session_input
                .update(cx, |input, cx| input.set_value("", window, cx));
            self.new_session_workspace.clear(
                RequestId::new().to_string(),
                self.new_session_managed_root(),
            );
            self.new_session_workspace.preference =
                self.ui_state.workbench.default_new_session_location;
            self.new_session_draft_initialized = true;
        }
        let target = target.or_else(|| {
            initialize_draft
                .then(|| self.inferred_new_session_target())
                .flatten()
        });
        if (initialize_draft || explicit_target)
            && let Some(target) = target
        {
            self.select_new_session_target(target, window, cx);
        }
        self.new_session_input
            .update(cx, |input, cx| input.focus(window, cx));
        self.sync_composer_command_entry(ComposerTarget::NewSession, cx);
        self.refresh_active_suggestions(ComposerTarget::NewSession, cx);
        if primary_tab_changed {
            self.push_current_navigation_entry();
        }
        cx.notify();
    }

    fn clear_submitted_new_session_draft(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.clear_new_session_message_draft(window, cx);
        self.new_session_draft_initialized = false;
        self.new_session_workspace.reset_after_success();
    }

    fn clear_new_session_message_draft(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.new_session_attachments.clear();
        self.new_session_command_entry = None;
        self.new_session_input
            .update(cx, |input, cx| input.set_value("", window, cx));
    }

    fn restore_new_session_message_draft(
        &mut self,
        text: String,
        attachments: Vec<InlineComposerAttachment>,
        command_entry: Option<AgentCommandEntry>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.new_session_input
            .update(cx, |input, cx| input.set_value(text, window, cx));
        self.new_session_attachments = attachments;
        self.new_session_command_entry = command_entry;
    }

    fn open_pending_new_session(
        &mut self,
        session: AgentSession,
        selection: SessionRuntimeSelection,
        optimistic_message: Option<OptimisticUserMessage>,
        has_initial_message: bool,
        initial_turn_interrupt: watch::Sender<bool>,
        cx: &mut Context<Self>,
    ) -> u64 {
        let session_id = session.id.clone();
        self.pending_new_session = Some(PendingNewSession {
            session_id: session_id.clone(),
            previous_session_id: self.selected_session_id.clone(),
        });
        self.upsert_session_snapshot(session);
        self.reconcile_sidebar_state();
        self.publish_sidebar_invalidation();
        self.optimistic_runtime_selections
            .insert(session_id.as_str().to_string(), selection);
        if has_initial_message {
            self.pending_initial_turn_interrupts
                .insert(session_id.as_str().to_string(), initial_turn_interrupt);
            self.set_session_turn_pending(&session_id, true);
        }
        self.select_session_with_history(session_id, false, cx);
        if let Some(message) = optimistic_message {
            self.install_optimistic_user_message(message);
        }
        self.agent_loading = false;
        self.session_generation
    }

    fn update_pending_new_session_workspace(&mut self, workspace: &WorkspaceRecord) {
        let Some(session_id) = self
            .pending_new_session
            .as_ref()
            .map(|pending| pending.session_id.clone())
        else {
            return;
        };
        let Some(session) = self
            .sessions
            .iter_mut()
            .find(|session| session.id == session_id)
        else {
            return;
        };
        session.project_id = workspace.project_id.clone();
        session.workspace_id = workspace.id.clone();
        session.workspace_root.clone_from(&workspace.root_path);
        session.workspace_mode = workspace.mode;
        session.updated_at_ms = workspace.updated_at_ms;
        self.invalidate_sidebar_projection_cache();
        self.publish_sidebar_invalidation();
    }

    fn fail_pending_new_session(
        &mut self,
        session_id: &VibexSessionId,
        generation: u64,
        draft: SubmittedNewSessionDraft,
        failure: NewSessionFailure,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if self
            .pending_new_session
            .as_ref()
            .is_none_or(|pending| pending.session_id != *session_id)
        {
            return;
        }
        let pending = self
            .pending_new_session
            .take()
            .expect("pending new session should still match");
        let active = self.session_generation == generation
            && self.selected_session_id.as_ref() == Some(session_id);

        self.sessions.retain(|session| session.id != *session_id);
        self.optimistic_runtime_selections
            .remove(session_id.as_str());
        self.pending_new_session_titles.remove(session_id.as_str());
        let interrupted = self
            .pending_initial_turn_interrupts
            .remove(session_id.as_str())
            .is_some_and(|interrupt| *interrupt.borrow());
        if interrupted {
            self.agent_action_pending = false;
        }
        self.discard_optimistic_user_message(session_id);
        self.set_session_turn_pending(session_id, false);
        self.session_views.remove(session_id.as_str());
        self.session_view_lru
            .retain(|cached_session_id| cached_session_id != session_id.as_str());
        self.reconcile_sidebar_state();

        if active && !self.new_session_open {
            self.restore_new_session_message_draft(
                draft.raw_text,
                draft.attachments,
                draft.command_entry,
                window,
                cx,
            );
            self.new_session_draft_initialized = true;
            self.new_session_workspace.mark_failed(failure.code);
            self.new_session_error = Some(failure.message);
            if let Some(previous_session_id) =
                pending.previous_session_id.filter(|previous_session_id| {
                    self.sessions
                        .iter()
                        .any(|session| session.id == *previous_session_id)
                })
            {
                self.select_session_with_history(previous_session_id, false, cx);
            } else {
                self.session_generation = self.session_generation.saturating_add(1);
                self.selected_session_id = None;
                self.timeline = TimelineModel::default();
                self.timeline_row_sizes = Rc::new(Vec::new());
                self.invalidate_timeline_render_caches();
                self.runtime_selection = None;
                self.token_usage = None;
                self.agent_loading = false;
                self.agent_turn_pending = false;
                self.queue_agent_ui_state();
            }
            self.new_session_open = true;
            self.sync_agent_streaming_surface_visibility();
            self.new_session_input
                .update(cx, |input, cx| input.focus(window, cx));
            self.sync_composer_command_entry(ComposerTarget::NewSession, cx);
            self.refresh_active_suggestions(ComposerTarget::NewSession, cx);
        }
        cx.notify();
    }

    fn current_checkout_for_project(
        &self,
        project_id: &ProjectId,
    ) -> Option<(ProjectRecord, WorkspaceRecord)> {
        self.workspaces
            .iter()
            .find(|(project, workspace)| {
                project.id == *project_id && workspace.mode == WorkspaceMode::CurrentCheckout
            })
            .or_else(|| {
                self.workspaces
                    .iter()
                    .find(|(project, _)| project.id == *project_id)
            })
            .cloned()
    }

    fn inferred_new_session_target(&self) -> Option<NewSessionOpenTarget> {
        self.selected_session()
            .map(|session| NewSessionOpenTarget::Project(session.project_id.clone()))
            .or_else(|| {
                let selected_workspace_id =
                    self.ui_state.workbench.selected_workspace_id.as_deref()?;
                self.workspaces
                    .iter()
                    .find(|(_, workspace)| workspace.id.as_str() == selected_workspace_id)
                    .map(|(project, _)| NewSessionOpenTarget::Project(project.id.clone()))
            })
            .or_else(|| {
                self.workspaces
                    .iter()
                    .find(|(_, workspace)| workspace.mode == WorkspaceMode::CurrentCheckout)
                    .map(|(project, _)| NewSessionOpenTarget::Project(project.id.clone()))
            })
    }

    fn new_session_managed_root(&self) -> std::path::PathBuf {
        self.config
            .as_ref()
            .map(|config| config.home_dir.clone())
            .unwrap_or_default()
    }

    fn new_session_prompt_title(&self, cx: &App) -> Option<String> {
        session_title_from_first_message(self.new_session_input.read(cx).value().as_ref())
    }

    fn select_new_session_target(
        &mut self,
        target: NewSessionOpenTarget,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let prompt_title = self.new_session_prompt_title(cx);
        let nonce = RequestId::new().to_string();
        let managed_root = self.new_session_managed_root();
        let ticket = match target {
            NewSessionOpenTarget::Project(project_id) => {
                let Some((project, origin_workspace)) =
                    self.current_checkout_for_project(&project_id)
                else {
                    return;
                };
                let preference = self
                    .ui_state
                    .sidebar
                    .project_location_preferences
                    .get(project.id.as_str())
                    .copied()
                    .unwrap_or(self.ui_state.workbench.default_new_session_location);
                self.new_session_workspace.select_project(
                    &project,
                    &origin_workspace,
                    preference,
                    nonce,
                    managed_root,
                    prompt_title.as_deref(),
                )
            }
            NewSessionOpenTarget::Workspace(workspace_id) => {
                let Some((project, workspace)) = self
                    .workspaces
                    .iter()
                    .find(|(_, workspace)| workspace.id == workspace_id)
                    .cloned()
                else {
                    return;
                };
                let Some((_, origin_workspace)) = self.current_checkout_for_project(&project.id)
                else {
                    return;
                };
                self.new_session_workspace.select_existing_workspace(
                    &project,
                    &origin_workspace,
                    &workspace,
                    nonce,
                    managed_root,
                    prompt_title.as_deref(),
                )
            }
        };
        self.new_session_error = None;
        self.new_session_eligibility_error = None;
        self.sync_new_session_worktree_inputs(window, cx);
        self.probe_new_session_eligibility(ticket, window, cx);
        self.refresh_active_suggestions(ComposerTarget::NewSession, cx);
        cx.notify();
    }

    fn probe_new_session_eligibility(
        &mut self,
        ticket: NewSessionProjectTicket,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.new_session_eligibility_task = None;
        let Some(backend) = self.backend.clone() else {
            self.new_session_eligibility_error = Some("backend_unavailable".into());
            return;
        };
        if !backend
            .capabilities()
            .git
            .supports(BackendOperation::GitWorktreeRead)
        {
            self.new_session_eligibility_error = Some("worktree_read_unsupported".into());
            return;
        }
        self.new_session_eligibility_error = None;
        let workspace_id = ticket.origin_workspace_id.clone();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            backend.git().git_worktree_eligibility(workspace_id).await
        });
        self.new_session_eligibility_task = Some(cx.spawn_in(
            window,
            async move |entity: WeakEntity<Self>, cx| {
                let outcome = runner.await;
                let _ = entity.update_in(cx, |this, window, cx| {
                    if this.new_session_workspace.ticket().as_ref() != Some(&ticket) {
                        return;
                    }
                    this.new_session_eligibility_task = None;
                    match outcome {
                        Ok(Ok(eligibility)) => {
                            if this
                                .new_session_workspace
                                .apply_eligibility(&ticket, eligibility)
                            {
                                this.new_session_eligibility_error = None;
                                this.sync_new_session_worktree_inputs(window, cx);
                            }
                        }
                        Ok(Err(error)) => {
                            this.new_session_eligibility_error = Some(error.code);
                        }
                        Err(error) => {
                            this.new_session_eligibility_error =
                                Some(format!("worktree_probe_failed: {error}"));
                        }
                    }
                    cx.notify();
                });
            },
        ));
    }

    fn sync_new_session_worktree_inputs(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let name = self.new_session_workspace.worktree_name.clone();
        let path = self.new_session_workspace.worktree_path.clone();
        self.new_session_worktree_input_syncing = true;
        self.new_session_worktree_name_input
            .update(cx, |input, cx| input.set_value(name, window, cx));
        self.new_session_worktree_path_input
            .update(cx, |input, cx| input.set_value(path, window, cx));
        self.new_session_worktree_input_syncing = false;
    }

    fn refresh_new_session_worktree_suggestions(
        &mut self,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let prompt_title = self.new_session_prompt_title(cx);
        self.new_session_workspace
            .refresh_auto_values(prompt_title.as_deref());
        self.sync_new_session_worktree_inputs(window, cx);
    }

    fn select_new_session_worktree(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if self.new_session_workspace.select_new_worktree() {
            self.new_session_error = None;
            self.sync_new_session_worktree_inputs(window, cx);
            cx.notify();
        }
    }

    fn set_new_session_base_ref(&mut self, base_ref: String, cx: &mut Context<Self>) {
        if self.new_session_workspace.set_base_ref(base_ref) {
            self.new_session_error = None;
            cx.notify();
        }
    }

    fn restore_new_session_worktree_auto_values(
        &mut self,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let prompt_title = self.new_session_prompt_title(cx);
        self.new_session_workspace
            .restore_auto_values(prompt_title.as_deref());
        self.sync_new_session_worktree_inputs(window, cx);
        cx.notify();
    }

    fn set_new_session_default_worktree(&mut self, enabled: bool, cx: &mut Context<Self>) {
        let Some(project_id) = self.new_session_workspace.project_id.as_ref() else {
            return;
        };
        if enabled {
            self.ui_state.sidebar.project_location_preferences.insert(
                project_id.as_str().to_string(),
                NewSessionLocation::NewWorktree,
            );
            self.new_session_workspace.preference = NewSessionLocation::NewWorktree;
        } else {
            self.ui_state
                .sidebar
                .project_location_preferences
                .remove(project_id.as_str());
            self.new_session_workspace.preference = NewSessionLocation::CurrentCheckout;
        }
        self.queue_ui_state();
        self.publish_sidebar_invalidation();
        cx.notify();
    }

    fn choose_new_session_runtime(
        &mut self,
        selection: SessionRuntimeSelection,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.new_session_agent_id = Some(selection.agent_id.clone());
        self.clear_runtime_provider_keyboard_selection();
        self.runtime_choice_menu_open = None;
        self.new_session_runtime_menu_auth_source = None;
        self.begin_runtime_menu_close(window, cx);
        self.set_new_session_runtime_selection(Some(selection.clone()));
        self.remember_runtime_selection(&selection);
        self.new_session_error = None;
        self.refresh_active_suggestions(ComposerTarget::NewSession, cx);
        cx.notify();
    }

    fn set_runtime_feature_value(
        &mut self,
        target: RuntimeFeatureTarget,
        feature_id: &str,
        value: String,
        cx: &mut Context<Self>,
    ) {
        let blocked = match target {
            RuntimeFeatureTarget::NewSession => self.agent_action_pending,
            RuntimeFeatureTarget::ActiveSession => self.active_runtime_controls_pending(),
        };
        if blocked {
            return;
        }
        let selection = match target {
            RuntimeFeatureTarget::NewSession => self.new_session_runtime_selection.clone(),
            RuntimeFeatureTarget::ActiveSession => self.selected_runtime_selection(),
        };
        let (Some(catalog), Some(selection)) = (self.runtime_catalog.as_ref(), selection) else {
            return;
        };
        let Some(feature) = runtime_feature_for_selection(catalog, &selection, feature_id) else {
            return;
        };
        if !feature.accepts_value(&value) {
            return;
        }
        self.runtime_choice_menu_open = None;
        let mut next = selection;
        next.config_values.insert(feature.id.clone(), value);
        match target {
            RuntimeFeatureTarget::NewSession => {
                self.set_new_session_runtime_selection(Some(next.clone()));
                self.remember_runtime_selection(&next);
                self.new_session_error = None;
                self.refresh_active_suggestions(ComposerTarget::NewSession, cx);
                cx.notify();
            }
            RuntimeFeatureTarget::ActiveSession => {
                self.request_runtime_selection(next, false, cx);
            }
        }
    }

    fn prompt_runtime_feature_value(
        &mut self,
        target: RuntimeFeatureTarget,
        feature: SessionRuntimeFeature,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let blocked = match target {
            RuntimeFeatureTarget::NewSession => self.agent_action_pending,
            RuntimeFeatureTarget::ActiveSession => self.active_runtime_controls_pending(),
        };
        if window.has_active_dialog(cx) || blocked {
            return;
        }
        let initial = feature
            .current_value
            .as_ref()
            .map(|value| value.value.clone())
            .unwrap_or_default();
        let title = feature.label.clone();
        let description = feature.description.clone();
        let feature_id = feature.id.clone();
        let cancel_label = locale::text("Cancel", "取消", "取消");
        let apply_label = locale::text("Apply", "应用", "套用");
        let entity = cx.weak_entity();
        // Keep the input outside the dialog builder. A builder is evaluated
        // again on every repaint, so an input created inside one would be
        // replaced — along with its focus handle and its text — while the user
        // types.
        let input = cx.new(|cx| {
            InputState::new(window, cx)
                .default_value(initial.clone())
                .placeholder(title.clone())
        });
        let input_for_focus = input.clone();
        let selection_end = initial.len();
        window.open_dialog(cx, move |dialog, _window, cx| {
            let feature_input = input.clone();
            let feature_id = feature_id.clone();
            let entity = entity.clone();
            dialog
                .title(title.clone())
                .when_some(description.clone(), |dialog, description| {
                    dialog.child(
                        v_flex()
                            .gap_2()
                            .child(
                                div()
                                    .text_sm()
                                    .text_color(cx.theme().muted_foreground)
                                    .child(description),
                            )
                            .child(Input::new(&input)),
                    )
                })
                .when(description.is_none(), |dialog| {
                    dialog.child(Input::new(&input))
                })
                .footer(
                    DialogFooter::new()
                        .child(
                            DialogClose::new().child(
                                Button::new("cancel-runtime-feature")
                                    .outline()
                                    .label(cancel_label),
                            ),
                        )
                        .child(
                            DialogAction::new().child(
                                Button::new("apply-runtime-feature")
                                    .primary()
                                    .label(apply_label),
                            ),
                        ),
                )
                .on_ok(move |_, _, cx| {
                    let value = feature_input.read(cx).value().trim().to_string();
                    if value.is_empty() || value.len() > 256 {
                        return false;
                    }
                    let _ = entity.update(cx, |this, cx| {
                        this.set_runtime_feature_value(target, &feature_id, value.clone(), cx)
                    });
                    true
                })
        });
        // The dialog's focus trap claims focus while it mounts; request the
        // field on the next frame and select the current value so typing
        // replaces it.
        window.on_next_frame(move |window, cx| {
            input_for_focus.update(cx, |input, cx| {
                input.set_selected_range(0..selection_end, cx);
                input.focus(window, cx);
            });
        });
    }

    fn choose_new_session_agent(
        &mut self,
        agent_id: AgentId,
        _window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if self.agent_action_pending {
            return;
        }
        self.apply_new_session_agent(agent_id, cx);
        self.new_session_runtime_menu_open = false;
        self.new_session_runtime_menu_view = ComposerRuntimeMenuView::AuthSource;
        self.new_session_runtime_menu_auth_source = None;
        cx.notify();
    }

    /// Draft-local Agent switch shared by the new-session home chips and the
    /// provider/model Agent row, so both surfaces derive the same provider and
    /// model preference for the chosen Agent.
    fn apply_new_session_agent(&mut self, agent_id: AgentId, cx: &mut Context<Self>) {
        let preferred = self.preferred_new_session_runtime_for_agent(&agent_id);
        let selection = self.runtime_catalog.as_ref().and_then(|catalog| {
            new_session_runtime_selection_for_agent(catalog, Some(&agent_id), preferred.as_ref())
        });
        self.set_new_session_runtime_selection(selection);
        self.new_session_agent_id = Some(agent_id);
        self.new_session_error = None;
        self.refresh_active_suggestions(ComposerTarget::NewSession, cx);
    }

    fn submit_new_session(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if !self.new_session_open || self.agent_action_pending || self.pending_new_session.is_some()
        {
            return;
        }
        if self.new_session_input.update(cx, |input, cx| {
            EntityInputHandler::marked_text_range(input, window, cx).is_some()
        }) {
            return;
        }
        // Creation is an authority operation: the local runtime is not required
        // because the backend facade also serves a paired remote runtime.
        let (Some(catalog), Some(selection)) = (
            self.runtime_catalog.as_ref(),
            self.new_session_runtime_selection.clone(),
        ) else {
            self.new_session_error = Some("No available Agent runtime is configured".into());
            cx.notify();
            return;
        };
        if !self
            .agent_snapshots
            .iter()
            .any(|agent| is_new_session_agent_available(agent) && agent.id == selection.agent_id)
        {
            self.new_session_error = Some("No enabled Agent is available".into());
            cx.notify();
            return;
        }
        if !catalog_has_runtime_selection(catalog, &selection) {
            self.new_session_error =
                Some("The selected Agent runtime is no longer available".into());
            cx.notify();
            return;
        }
        let selected_workspace = self.new_session_workspace.selected_workspace().cloned();
        let origin_workspace = self
            .new_session_workspace
            .origin_workspace_id
            .as_ref()
            .and_then(|workspace_id| {
                self.workspaces
                    .iter()
                    .find(|(_, workspace)| workspace.id == *workspace_id)
                    .map(|(_, workspace)| workspace.clone())
            });
        let create_worktree = self.new_session_workspace.location
            == NewSessionLocation::NewWorktree
            && selected_workspace.is_none();
        let worktree_mutation = if create_worktree {
            let Some(backend) = self.backend.as_ref() else {
                self.new_session_error = Some("Local backend is not ready".into());
                cx.notify();
                return;
            };
            if !backend
                .capabilities()
                .git
                .supports(BackendOperation::GitWorktreeCreate)
            {
                self.new_session_error = Some("worktree_create_unsupported".into());
                cx.notify();
                return;
            }
            let payload = match self.new_session_workspace.worktree_create_request() {
                Ok(payload) => payload,
                Err(code) => {
                    self.new_session_error = Some(code.into());
                    cx.notify();
                    return;
                }
            };
            let mut request = MutationRequest::new(payload).with_idempotency_key(
                self.new_session_workspace
                    .submission
                    .idempotency_key
                    .clone(),
            );
            if let Some(revision) = self.new_session_workspace.expected_revision() {
                request = request.with_expected_revision(revision.to_string());
            }
            Some(request)
        } else {
            None
        };
        let raw_text = self.new_session_input.read(cx).value().to_string();
        let draft = SubmittedNewSessionDraft {
            raw_text: raw_text.clone(),
            attachments: self.new_session_attachments.clone(),
            command_entry: self.new_session_command_entry.clone(),
        };
        let (text, attachments) =
            composer_submission_payload(&raw_text, &self.new_session_attachments);
        self.sync_composer_command_entry(ComposerTarget::NewSession, cx);
        // Manual slash expansion reads the authority's discovery capability.
        // A paired runtime resolves explicit command selections through the
        // facade below; an unmatched typed `/…` stays verbatim, matching the
        // remote composer path.
        let allow_manual_provider_slash = self
            .runtime
            .as_ref()
            .map(|runtime| {
                runtime
                    .agent()
                    .manager()
                    .command_discovery_capabilities(&AgentCommandDiscoverRequest {
                        agent_id: Some(selection.agent_id.clone()),
                        provider_profile_id: selection.provider_profile_id().cloned(),
                        session_id: None,
                        workspace_id: None,
                        trigger: Some(AgentCommandTrigger::Slash),
                        query: None,
                        limit: Some(1),
                    })
                    .map(|capabilities| capabilities.slash_commands)
                    .unwrap_or(false)
            })
            .unwrap_or(false);
        let command_invocation = resolve_composer_command_invocation(
            &text,
            self.new_session_command_entry.as_ref(),
            allow_manual_provider_slash,
        );
        let title = session_title_from_first_message(&text);
        let has_initial_message = !text.trim().is_empty() || !attachments.is_empty();
        let deferred_creation = command_invocation.is_none();
        let optimistic_submitted_at_ms = unix_timestamp_ms();
        let optimistic_session_id = VibexSessionId::new();
        let (initial_turn_interrupt_tx, mut initial_turn_interrupt_rx) = watch::channel(false);
        let optimistic_workspace = selected_workspace
            .as_ref()
            .or(origin_workspace.as_ref())
            .cloned();
        let optimistic_session = AgentSession {
            id: optimistic_session_id.clone(),
            title: title
                .clone()
                .unwrap_or_else(|| agent_session_fallback_title(&selection.agent_id)),
            project_id: optimistic_workspace
                .as_ref()
                .map(|workspace| workspace.project_id.clone())
                .or_else(|| self.new_session_workspace.project_id.clone())
                .unwrap_or_default(),
            workspace_id: optimistic_workspace
                .as_ref()
                .map(|workspace| workspace.id.clone())
                .or_else(|| self.new_session_workspace.origin_workspace_id.clone())
                .unwrap_or_default(),
            workspace_root: optimistic_workspace
                .as_ref()
                .map(|workspace| workspace.root_path.clone())
                .unwrap_or_else(|| self.new_session_workspace.project_root.clone()),
            workspace_mode: optimistic_workspace
                .as_ref()
                .map(|workspace| workspace.mode)
                .unwrap_or(if create_worktree {
                    WorkspaceMode::VibexWorktree
                } else {
                    WorkspaceMode::CurrentCheckout
                }),
            agent_id: selection.agent_id.clone(),
            state: AgentSessionState::Initializing,
            safety: AgentSessionSafety::workspace_write_ask_on_risk(),
            created_at_ms: optimistic_submitted_at_ms,
            updated_at_ms: optimistic_submitted_at_ms,
            last_message_at_ms: optimistic_submitted_at_ms,
            archived_at_ms: None,
            deleted_at_ms: None,
        };
        if optimistic_session.title != agent_session_fallback_title(&selection.agent_id) {
            self.pending_new_session_titles.insert(
                optimistic_session_id.as_str().to_string(),
                optimistic_session.title.clone(),
            );
        }
        let optimistic_message = has_initial_message.then(|| OptimisticUserMessage {
            session_id: optimistic_session_id.clone(),
            item_id: TimelineItemId::new(),
            after_sequence: 0,
            submitted_at_ms: optimistic_submitted_at_ms,
            text: text.clone(),
            attachments: attachments.clone(),
        });
        self.new_session_workspace.begin_submission();
        self.new_session_error = None;
        self.clear_new_session_message_draft(window, cx);
        self.clear_suggestions();
        let generation = self.open_pending_new_session(
            optimistic_session,
            selection.clone(),
            optimistic_message,
            has_initial_message,
            initial_turn_interrupt_tx,
            cx,
        );
        let pending_session_id = optimistic_session_id.clone();
        let backend = self.backend.clone();
        let (created_tx, mut created_rx) = mpsc::unbounded_channel();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            // Every step of new-session creation is an authority operation, so
            // the flow drives the same facade a paired remote runtime fills.
            let backend = backend.ok_or_else(|| {
                vibex_backend::BackendError::offline(
                    "backend_unavailable",
                    "the authoritative runtime is unavailable for session creation",
                )
            })?;
            let workspace = if let Some(workspace) = selected_workspace {
                Some(workspace)
            } else if let Some(request) = worktree_mutation {
                let result = backend.git().git_worktree_create(request).await?;
                let workspace = result.workspace;
                let _ = created_tx.send(NewSessionCreateSignal::WorkspaceReady(workspace.clone()));
                Some(workspace)
            } else {
                origin_workspace
            };
            let (workspace_root, workspace_mode) = match workspace.as_ref() {
                Some(workspace) => (workspace.root_path.clone(), workspace.mode),
                // A temporary session has no published workspace, so the
                // authority creates the root on the machine that runs the Agent.
                None => (
                    backend.workspace().ensure_temporary_session_root().await?,
                    WorkspaceMode::CurrentCheckout,
                ),
            };
            let create_request = CreateAgentSessionRequest {
                session_id: Some(optimistic_session_id.clone()),
                defer_runtime_materialization: deferred_creation,
                runtime: selection.clone(),
                workspace_root,
                workspace_mode,
                // The prompt-derived title is an optimistic presentation value.
                // The manager persists it as an unlocked automatic fallback after
                // the first user message, so a later ACP title can replace it.
                title: None,
                safety: None,
            };
            let recovery_session_id = optimistic_session_id.clone();
            let creation =
                backend
                    .agent()
                    .create_session(MutationRequest::new(create_request).with_idempotency_key(
                        format!("gpui:new-session:create:{}", optimistic_session_id.as_str()),
                    ))
                    .await;
            let session = match creation {
                Ok(session) => session,
                Err(error) => {
                    // The authority persists the Logical Session before runtime
                    // materialization. Surface that durable error session so
                    // the optimistic first message is never discarded when
                    // initialization fails after persistence.
                    if let Ok(session) = backend.agent().open_session(recovery_session_id).await {
                        let _ = created_tx.send(NewSessionCreateSignal::SessionReady(
                            session,
                            list_workspace_records(&backend).await,
                            has_initial_message,
                        ));
                    }
                    return Err(error);
                }
            };
            let workspaces = list_workspace_records(&backend).await;
            let session_id = session.id.clone();
            let message_backend = backend.clone();
            let initial_message = if has_initial_message {
                let initial_attachments = attachments;
                Some(async move {
                    let desired_runtime = message_backend
                        .agent()
                        .runtime_selection(session_id.clone())
                        .await
                        .map(|state| state.effective)
                        .unwrap_or_else(|_| selection.clone());
                    if let Some(invocation) = command_invocation {
                        if *initial_turn_interrupt_rx.borrow() {
                            return Err(initial_message_interrupted_error());
                        }
                        let command = message_backend.agent().execute_agent_command(
                            MutationRequest::new(AgentCommandExecuteRequest {
                                session_id: session_id.clone(),
                                command_id: invocation.command_id,
                                trigger: invocation.trigger,
                                source_kind: invocation.source_kind,
                                command_text: invocation.command_text,
                                command_name: invocation.command_name,
                                arguments: invocation.arguments,
                                prompt_id: invocation.prompt_id,
                                attachments: initial_attachments.clone(),
                                // The newly committed session runtime is authoritative;
                                // command admission must not compare it with the draft.
                                reasoning_effort: None,
                                correlation_id: None,
                            })
                            .with_idempotency_key(format!(
                                "gpui:new-session:command:{}:{}",
                                session_id.as_str(),
                                unix_timestamp_ms()
                            )),
                        );
                        tokio::pin!(command);
                        let mut interrupt_sent = false;
                        loop {
                            tokio::select! {
                                outcome = &mut command => {
                                    break outcome.map(|_| ()).map_err(backend_error_to_vibex);
                                }
                                changed = initial_turn_interrupt_rx.changed(), if !interrupt_sent => {
                                    if changed.is_err() || !*initial_turn_interrupt_rx.borrow() {
                                        interrupt_sent = true;
                                        continue;
                                    }
                                    message_backend
                                        .agent()
                                        .interrupt(MutationRequest::new(session_id.clone()))
                                        .await
                                        .map_err(backend_error_to_vibex)?;
                                    interrupt_sent = true;
                                }
                            }
                        }
                    } else {
                        if *initial_turn_interrupt_rx.borrow() {
                            message_backend
                                .agent()
                                .interrupt(MutationRequest::new(session_id.clone()))
                                .await
                                .map_err(backend_error_to_vibex)?;
                        }
                        let submission = message_backend.agent().send_message(
                            MutationRequest::new(SendAgentMessageRequest {
                                session_id: session_id.clone(),
                                message_idempotency_key: format!(
                                    "gpui:new-session:{}:{}",
                                    session_id.as_str(),
                                    unix_timestamp_ms()
                                ),
                                desired_runtime: desired_runtime.clone(),
                                text: text.clone(),
                                attachments: initial_attachments.clone(),
                                reasoning_effort: desired_runtime.reasoning_effort.clone(),
                                correlation_id: None,
                                delivery: UserMessageDelivery::Prompt,
                            })
                            .with_idempotency_key(format!(
                                "gpui:new-session:message:{}",
                                session_id.as_str()
                            )),
                        );
                        tokio::pin!(submission);
                        let mut interrupt_sent = false;
                        loop {
                            tokio::select! {
                                outcome = &mut submission => {
                                    break outcome.map(|_| ()).map_err(backend_error_to_vibex);
                                }
                                changed = initial_turn_interrupt_rx.changed(), if !interrupt_sent => {
                                    if changed.is_err() || !*initial_turn_interrupt_rx.borrow() {
                                        interrupt_sent = true;
                                        continue;
                                    }
                                    message_backend
                                        .agent()
                                        .interrupt(MutationRequest::new(session_id.clone()))
                                        .await
                                        .map_err(backend_error_to_vibex)?;
                                    interrupt_sent = true;
                                }
                            }
                        }
                    }
                })
            } else {
                None
            };
            let initial_message_error = announce_created_session_before_initial_message(
                created_tx,
                NewSessionCreateSignal::SessionReady(
                    session.clone(),
                    workspaces,
                    has_initial_message,
                ),
                initial_message,
            )
            .await;
            let refreshed_session = backend.agent().open_session(session.id.clone()).await.ok();
            Ok::<_, vibex_backend::BackendError>((
                session.id,
                has_initial_message,
                initial_message_error,
                refreshed_session,
            ))
        });
        cx.spawn_in(window, async move |entity: WeakEntity<Self>, cx| {
            let mut created_session_id = None;
            let mut turn_generation = None;
            while let Some(signal) = created_rx.recv().await {
                match signal {
                    NewSessionCreateSignal::WorkspaceReady(workspace) => {
                        let _ = entity.update_in(cx, |this, _window, cx| {
                            this.new_session_workspace
                                .mark_workspace_ready(workspace.clone());
                            this.update_pending_new_session_workspace(&workspace);
                            if let Some(project) =
                                this.new_session_workspace.project_id.as_ref().and_then(
                                    |project_id| {
                                        this.workspaces
                                            .iter()
                                            .find(|(project, _)| project.id == *project_id)
                                            .map(|(project, _)| project.clone())
                                    },
                                )
                            {
                                this.workspaces
                                    .retain(|(_, current)| current.id != workspace.id);
                                this.workspaces.push((project, workspace.clone()));
                            }
                            this.activate_workspace(workspace, cx);
                            this.reconcile_sidebar_state();
                            this.refresh_workspace_contexts(cx);
                            cx.notify();
                        });
                    }
                    NewSessionCreateSignal::SessionReady(
                        session,
                        workspaces,
                        has_initial_message,
                    ) => {
                        let update = entity.update_in(cx, |this, window, cx| {
                            if let Some(workspaces) = workspaces {
                                this.workspaces = workspaces;
                            }
                            let session_id = session.id.clone();
                            if this
                                .pending_new_session
                                .as_ref()
                                .is_some_and(|pending| pending.session_id == session_id)
                            {
                                this.pending_new_session = None;
                            }
                            this.upsert_session_snapshot(session);
                            if has_initial_message {
                                this.set_session_turn_pending(&session_id, true);
                            }
                            this.reconcile_sidebar_state();
                            this.publish_sidebar_invalidation();
                            let created_session_id = session_id.clone();
                            let turn_generation = if this.session_generation == generation
                                && this.selected_session_id.as_ref() == Some(&session_id)
                            {
                                this.new_session_workspace
                                    .mark_stage(if has_initial_message {
                                        NewSessionSubmissionStage::SendingPrompt
                                    } else {
                                        NewSessionSubmissionStage::StartingAgent
                                    });
                                this.select_session_with_history(session_id.clone(), false, cx);
                                if has_initial_message {
                                    this.rebuild_timeline_sizes();
                                    Some(this.session_generation)
                                } else {
                                    None
                                }
                            } else {
                                None
                            };
                            // A user may have already opened and started a fresh draft while
                            // this request was in flight. Do not erase that draft when the
                            // earlier creation becomes authoritative.
                            if !this.new_session_open {
                                this.clear_submitted_new_session_draft(window, cx);
                            }
                            this.refresh_workspace_contexts(cx);
                            cx.notify();
                            (created_session_id, turn_generation)
                        });
                        if let Ok((session_id, generation)) = update {
                            created_session_id = Some(session_id);
                            turn_generation = generation;
                        }
                        break;
                    }
                }
            }
            let outcome = runner.await;
            let _ = entity.update_in(cx, |this, window, cx| {
                let initial_turn_interrupted = created_session_id
                    .as_ref()
                    .and_then(|session_id| {
                        this.pending_initial_turn_interrupts
                            .remove(session_id.as_str())
                    })
                    .is_some_and(|interrupt| *interrupt.borrow());
                this.release_initial_turn_interrupt_lock(initial_turn_interrupted);
                if let Some(session_id) = created_session_id.as_ref() {
                    this.set_session_turn_pending(session_id, false);
                }
                match outcome {
                    Ok(Ok((
                        session_id,
                        initial_message_sent,
                        initial_message_error,
                        refreshed_session,
                    ))) => {
                        let initial_message_completed =
                            initial_message_sent && initial_message_error.is_none();
                        if let Some(session) = refreshed_session {
                            this.upsert_session_snapshot(session);
                        }
                        this.sync_auto_continue_for_session(&session_id, cx);
                        if turn_generation.is_some_and(|turn_generation| {
                            agent_turn_completion_is_active(
                                this.session_generation,
                                turn_generation,
                                this.selected_session_id.as_ref(),
                                &session_id,
                            )
                        }) && initial_message_sent
                        {
                            this.refresh_selected_agent_timeline(cx);
                        }
                        if let Some(error) = initial_message_error
                            && let Some(note) = initial_message_failure_note(&error)
                        {
                            this.runtime_note = Some(note);
                        }
                        this.reconcile_sidebar_state();
                        this.publish_sidebar_invalidation();
                        this.refresh_workspace_contexts(cx);
                        let steering = this
                            .composer_queue_steering_session_ids
                            .remove(session_id.as_str());
                        let interrupted = this
                            .composer_queue_interrupted_session_ids
                            .remove(session_id.as_str());
                        if initial_message_completed || steering || interrupted {
                            this.maybe_dispatch_next_composer_queue_message(
                                &session_id,
                                if steering {
                                    ComposerQueueDispatchBehavior::AfterInterrupt
                                } else if initial_message_completed {
                                    ComposerQueueDispatchBehavior::AfterCompletion
                                } else {
                                    ComposerQueueDispatchBehavior::Automatic
                                },
                                window,
                                cx,
                            );
                        }
                        // A failed or cancelled initial turn only skips this
                        // dispatch: the queue stays armed (never paused) and is
                        // re-evaluated once a later turn completes normally.
                    }
                    Ok(Err(error)) => {
                        if created_session_id.is_some() {
                            this.runtime_note = Some(format!(
                                "Session created; runtime initialization failed: {}",
                                error
                            ));
                            this.reconcile_sidebar_state();
                            this.refresh_workspace_contexts(cx);
                        } else {
                            this.fail_pending_new_session(
                                &pending_session_id,
                                generation,
                                draft.clone(),
                                NewSessionFailure {
                                    code: error.code.clone(),
                                    message: format!("{}: {}", error.code, error.message),
                                },
                                window,
                                cx,
                            );
                        }
                    }
                    Err(error) => {
                        if created_session_id.is_some() {
                            this.runtime_note = Some(format!(
                                "Session created; runtime initialization failed: {}",
                                error
                            ));
                            this.reconcile_sidebar_state();
                            this.refresh_workspace_contexts(cx);
                        } else {
                            this.fail_pending_new_session(
                                &pending_session_id,
                                generation,
                                draft,
                                NewSessionFailure {
                                    code: "new_session_task_failed".to_string(),
                                    message: format!("session creation failed: {error}"),
                                },
                                window,
                                cx,
                            );
                        }
                    }
                }
                cx.notify();
            });
        })
        .detach();
    }

    fn clear_runtime_provider_keyboard_selection(&mut self) {
        self.runtime_provider_keyboard_selection = None;
        self.runtime_provider_reveal_selection = None;
    }

    /// Drop the provider/model query together with the popover that owned it.
    ///
    /// The query only ever filters the list that was on screen, so it must not
    /// outlive the panel: a later visit would otherwise open on a narrowed list
    /// whose term the user can no longer see or edit. The composer and the
    /// new-session home share one popover shape, so both fields are reset.
    fn clear_runtime_provider_search(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.composer_runtime_search
            .update(cx, |input, cx| input.set_value("", window, cx));
        self.new_session_runtime_search
            .update(cx, |input, cx| input.set_value("", window, cx));
    }

    /// Whether the Agent row is locked to the Agent it already has.
    ///
    /// A runtime switch in flight (or a pending new-session action) owns the
    /// selection until it settles; the other chips dim and go inert rather
    /// than queueing a second switch behind the first.
    fn runtime_agent_row_locked(&self) -> bool {
        self.active_runtime_controls_pending() || self.action_pending_for_runtime_menu()
    }

    /// The pending flag that gates the popover the caller is rendering.
    fn action_pending_for_runtime_menu(&self) -> bool {
        self.agent_action_pending
    }

    /// Scope the provider/model layer to starred models across every Agent, or
    /// back to the selected Agent's providers.
    fn toggle_runtime_provider_favorites_view(&mut self, cx: &mut Context<Self>) {
        self.runtime_provider_favorites_view = !self.runtime_provider_favorites_view;
        self.clear_runtime_provider_keyboard_selection();
        self.runtime_provider_scroll_to_selection = true;
        self.runtime_agent_row_reveal_pending = true;
        cx.notify();
    }

    /// Star/unstar one model and re-home the keyboard cursor.
    ///
    /// Starring reorders the list — stars float to the top of their group and
    /// leave the favorites view — so the cursor is re-anchored onto the
    /// selected row. Following the starred row instead would park its wash
    /// beside the selected row's ring, reading as two highlighted rows.
    fn toggle_runtime_model_favorite(
        &mut self,
        agent_id: &AgentId,
        model_key: &str,
        cx: &mut Context<Self>,
    ) {
        self.ui_state
            .composer
            .toggle_runtime_model_favorite(agent_id, model_key);
        self.clear_runtime_provider_keyboard_selection();
        self.runtime_provider_scroll_to_selection = true;
        self.queue_ui_state();
        cx.notify();
    }

    /// Hand focus back to the composer once the picker leaves.
    ///
    /// The popover owns focus while it is up, and gpui releases it on unmount
    /// without choosing a successor — without this the next keystroke goes
    /// nowhere.
    fn return_composer_focus(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let target = if self.new_session_open {
            ComposerTarget::NewSession
        } else {
            ComposerTarget::Session
        };
        if let Some(input) = self.input_for_composer_target(target) {
            input.update(cx, |input, cx| input.focus(window, cx));
        }
    }

    /// Start the popover's exit animation.
    ///
    /// The panel stays mounted for [`motion::MENU_OUT`] so the fade can play;
    /// the state is cleared by [`Self::finish_runtime_menu_close`]. A second
    /// call while the exit is already running is a no-op, so a stray
    /// `on_open_change(false)` cannot restart the timeline.
    fn begin_runtime_menu_close(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if self.runtime_menu_closing_since.is_some() {
            return;
        }
        self.runtime_menu_closing_since = Some(Instant::now());
        self.runtime_provider_search_focus_pending = false;
        cx.notify();
        cx.spawn_in(window, async move |this, cx| {
            cx.background_executor()
                .timer(motion::MENU_OUT.total())
                .await;
            let _ = this.update_in(cx, |this, window, cx| {
                this.finish_runtime_menu_close(window, cx);
            });
        })
        .detach();
    }

    /// Unmount the popover once the exit timeline has elapsed.
    fn finish_runtime_menu_close(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if self.runtime_menu_closing_since.take().is_none() {
            return;
        }
        let was_mounted = self.new_session_runtime_menu_open || self.composer_runtime_menu_open;
        self.new_session_runtime_menu_open = false;
        self.composer_runtime_menu_open = false;
        self.runtime_provider_favorites_view = false;
        self.runtime_provider_scroll_to_selection = false;
        self.runtime_agent_row_reveal_pending = false;
        // Unconditional: a teardown path may have dropped the flags above
        // before the timeline reached here, and the query still has to go.
        self.clear_runtime_provider_search(window, cx);
        if was_mounted {
            self.return_composer_focus(window, cx);
        }
        cx.notify();
    }

    fn choose_runtime_selection(
        &mut self,
        selection: SessionRuntimeSelection,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if self.active_runtime_controls_pending() {
            return;
        }
        self.clear_runtime_provider_keyboard_selection();
        self.runtime_choice_menu_open = None;
        self.composer_runtime_menu_agent_id = None;
        self.composer_runtime_menu_auth_source = None;
        self.begin_runtime_menu_close(window, cx);
        if self.selected_session_runtime_uninitialized() {
            self.initialize_uninitialized_session_runtime(selection, cx);
            return;
        }
        self.request_runtime_selection(selection, false, cx);
    }

    fn initialize_uninitialized_session_runtime(
        &mut self,
        selection: SessionRuntimeSelection,
        cx: &mut Context<Self>,
    ) {
        let (Some(runtime), Some(session_id)) =
            (self.runtime.clone(), self.selected_session_id.clone())
        else {
            return;
        };
        let session_key = session_id.as_str().to_string();
        if !self
            .runtime_selection_uninitialized_sessions
            .contains(&session_key)
            || self
                .runtime_selection_initializations_in_flight
                .contains(&session_key)
        {
            return;
        }
        self.optimistic_runtime_selections
            .insert(session_key.clone(), selection.clone());
        self.runtime_selection_initializations_in_flight
            .insert(session_key.clone());
        let generation = self.session_generation;
        let requested_session_id = session_id.clone();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            runtime
                .agent()
                .manager()
                .initialize_imported_session_runtime(&session_id, selection)
                .await
        });
        cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                let outcome = runner.await;
                let _ = entity.update(cx, |this, cx| {
                    this.runtime_selection_initializations_in_flight
                        .remove(&session_key);
                    let active = this.session_generation == generation
                        && this.selected_session_id.as_ref() == Some(&requested_session_id);
                    match outcome {
                        Ok(Ok(session)) => {
                            this.upsert_session_snapshot(session);
                            this.reconcile_sidebar_state();
                            if active {
                                this.load_agent_session_projection(
                                    this.runtime.clone().expect("runtime should stay installed"),
                                    requested_session_id.clone(),
                                    generation,
                                    cx,
                                );
                            }
                        }
                        Ok(Err(error)) => {
                            this.optimistic_runtime_selections.remove(&session_key);
                            if active {
                                this.agent_error =
                                    Some(format!("{}: {}", error.code, error.message));
                            }
                        }
                        Err(error) => {
                            this.optimistic_runtime_selections.remove(&session_key);
                            if active {
                                this.agent_error =
                                    Some(format!("runtime initialization failed: {error}"));
                            }
                        }
                    }
                    cx.notify();
                });
            },
        )
        .detach();
    }

    fn set_composer_runtime_menu_open(
        &mut self,
        open: bool,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if !open {
            // A press that lands while the exit is already playing re-opens:
            // the popover's own toggle still reads the panel as open during
            // the timeline, so without this the press would be swallowed.
            if std::mem::take(&mut self.runtime_menu_trigger_press_was_open) {
                self.runtime_menu_closing_since = None;
                cx.notify();
                return;
            }
            // Otherwise this is either the user dismissing the popover or the
            // popover echoing our own unmount; a logically closed menu has
            // nothing left to play.
            if self.composer_runtime_menu_open {
                self.begin_runtime_menu_close(window, cx);
            }
            return;
        }
        let open = !self.active_runtime_controls_pending();
        if !open {
            return;
        }
        self.runtime_menu_closing_since = None;
        self.composer_runtime_menu_open = true;
        self.clear_runtime_provider_keyboard_selection();
        // See `clear_runtime_provider_search`: a sibling chip's menu, Configure
        // Agent and the attachment preview all tear the popover down without
        // running the exit timeline, so the reset is repeated on the way back.
        self.clear_runtime_provider_search(window, cx);
        self.runtime_provider_search_focus_pending = true;
        self.runtime_choice_menu_open = None;
        self.runtime_provider_scroll_to_selection = true;
        self.runtime_agent_row_reveal_pending = true;
        let selection = self.selected_runtime_selection();
        // Reopen at the selected provider/model group so an active session
        // does not make the user repeat the Agent selection step.
        self.composer_runtime_menu_view = ComposerRuntimeMenuView::AuthSource;
        self.composer_runtime_menu_agent_id = selection
            .as_ref()
            .map(|selection| selection.agent_id.clone());
        self.composer_runtime_menu_auth_source = selection
            .as_ref()
            .map(|selection| selection.auth_source.clone());
        cx.notify();
    }

    fn navigate_composer_runtime_menu(
        &mut self,
        view: ComposerRuntimeMenuView,
        agent_id: Option<AgentId>,
        auth_source: Option<RuntimeAuthSource>,
        cx: &mut Context<Self>,
    ) {
        self.composer_runtime_menu_agent_id = agent_id;
        self.composer_runtime_menu_auth_source = auth_source;
        self.composer_runtime_menu_view = view;
        self.clear_runtime_provider_keyboard_selection();
        self.runtime_provider_search_focus_pending =
            matches!(view, ComposerRuntimeMenuView::AuthSource);
        cx.notify();
    }

    /// Activate an Agent logo inside the provider/model layer.
    ///
    /// The current-session menu re-scopes the whole cascade to the chosen Agent
    /// while staying on the provider/model layer, and the new-session menu
    /// applies the draft Agent switch without dismissing the popup, so both
    /// surfaces keep Agent and provider/model in one step.
    fn choose_runtime_menu_agent(
        &mut self,
        agent_id: AgentId,
        new_session: bool,
        cx: &mut Context<Self>,
    ) {
        self.runtime_agent_row_reveal_pending = true;
        // Picking an Agent is also how the user leaves the starred-models
        // scope: the row's Agent chips only mean something per Agent.
        self.runtime_provider_favorites_view = false;
        // The chosen Agent's provider/model list must reveal its own selected
        // model the same way the menu did when it opened.
        self.runtime_provider_scroll_to_selection = true;
        if new_session {
            if self.agent_action_pending {
                return;
            }
            self.apply_new_session_agent(agent_id, cx);
            self.new_session_runtime_menu_view = ComposerRuntimeMenuView::AuthSource;
            self.new_session_runtime_menu_auth_source = None;
            // The popover hands focus to its own panel when it opens, and the
            // Agent row lives inside that panel; keep the search field as the
            // keyboard owner so arrow-key model navigation still works after a
            // switch.
            self.runtime_provider_search_focus_pending = true;
            cx.notify();
            return;
        }
        self.navigate_composer_runtime_menu(
            ComposerRuntimeMenuView::AuthSource,
            Some(agent_id),
            None,
            cx,
        );
    }

    fn set_new_session_runtime_menu_open(
        &mut self,
        open: bool,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if !open {
            // See `set_composer_runtime_menu_open` for both branches.
            if std::mem::take(&mut self.runtime_menu_trigger_press_was_open) {
                self.runtime_menu_closing_since = None;
                cx.notify();
                return;
            }
            if self.new_session_runtime_menu_open {
                self.begin_runtime_menu_close(window, cx);
            }
            return;
        }
        if self.agent_action_pending || self.new_session_agent_id.is_none() {
            return;
        }
        self.runtime_menu_closing_since = None;
        self.new_session_runtime_menu_open = true;
        self.clear_runtime_provider_keyboard_selection();
        // See `clear_runtime_provider_search`.
        self.clear_runtime_provider_search(window, cx);
        self.runtime_provider_search_focus_pending = true;
        self.runtime_choice_menu_open = None;
        self.runtime_provider_scroll_to_selection = true;
        self.runtime_agent_row_reveal_pending = true;
        self.new_session_runtime_menu_view = ComposerRuntimeMenuView::AuthSource;
        self.new_session_runtime_menu_auth_source = self
            .new_session_runtime_selection
            .as_ref()
            .map(|selection| selection.auth_source.clone());
        cx.notify();
    }

    fn set_runtime_choice_menu_open(
        &mut self,
        menu_id: String,
        open: bool,
        cx: &mut Context<Self>,
    ) {
        let blocked = if menu_id.starts_with("new-session-") {
            self.agent_action_pending
        } else {
            self.active_runtime_controls_pending()
        };
        let open = open && !blocked;
        if open {
            self.clear_runtime_provider_keyboard_selection();
            self.runtime_provider_search_focus_pending = false;
            self.new_session_runtime_menu_open = false;
            self.composer_runtime_menu_open = false;
            self.runtime_choice_menu_open = Some(menu_id);
        } else if self.runtime_choice_menu_open.as_deref() == Some(menu_id.as_str()) {
            self.clear_runtime_provider_keyboard_selection();
            self.runtime_provider_search_focus_pending = false;
            self.runtime_choice_menu_open = None;
        }
        cx.notify();
    }

    fn navigate_new_session_runtime_menu(
        &mut self,
        view: ComposerRuntimeMenuView,
        auth_source: Option<RuntimeAuthSource>,
        cx: &mut Context<Self>,
    ) {
        self.new_session_runtime_menu_view = view;
        self.new_session_runtime_menu_auth_source = auth_source;
        self.clear_runtime_provider_keyboard_selection();
        self.runtime_provider_search_focus_pending =
            matches!(view, ComposerRuntimeMenuView::AuthSource);
        cx.notify();
    }

    fn load_runtime_authentication_menu(
        &mut self,
        agent_id: AgentId,
        auth_source: RuntimeAuthSource,
        cx: &mut Context<Self>,
    ) {
        let Some(backend) = self.backend.clone() else {
            return;
        };
        let RuntimeAuthSource::AgentAccount { auth_context_id } = &auth_source else {
            return;
        };
        self.runtime_authentication_generation =
            self.runtime_authentication_generation.wrapping_add(1);
        let generation = self.runtime_authentication_generation;
        self.runtime_authentication_menu = Some(RuntimeAuthenticationMenuState {
            agent_id: agent_id.clone(),
            auth_source: auth_source.clone(),
            context: None,
            catalog: None,
            loading: true,
            pending: false,
            error: None,
        });
        let expected_context_id = auth_context_id.clone();
        let expected_agent_id = agent_id.clone();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            let context = backend
                .agent()
                .list_agent_auth_contexts()
                .await?
                .into_iter()
                .find(|context| {
                    context.id == expected_context_id && context.agent_id == expected_agent_id
                })
                .ok_or_else(|| {
                    BackendError::failed(
                        "agent_auth_context_not_found",
                        "Agent authentication context was not found",
                    )
                })?;
            let catalog = backend
                .agent()
                .list_agent_auth_methods(expected_agent_id)
                .await?;
            Ok::<_, BackendError>((context, catalog))
        });
        self.runtime_authentication_task = Some(cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                let outcome = runner.await;
                let _ = entity.update(cx, |this, cx| {
                    if this.runtime_authentication_generation != generation {
                        return;
                    }
                    let Some(state) = this.runtime_authentication_menu.as_mut() else {
                        return;
                    };
                    state.loading = false;
                    match outcome {
                        Ok(Ok((context, catalog))) => {
                            state.context = Some(context);
                            state.catalog = Some(catalog);
                            state.error = None;
                        }
                        Ok(Err(error)) => {
                            state.error = Some(format!("{}: {}", error.code, error.message));
                        }
                        Err(error) => {
                            state.error = Some(format!("Authentication task failed: {error}"));
                        }
                    }
                    cx.notify();
                });
            },
        ));
        cx.notify();
    }

    fn authenticate_runtime_auth_method(&mut self, method_id: String, cx: &mut Context<Self>) {
        let Some(state) = self.runtime_authentication_menu.clone() else {
            return;
        };
        let Some(method) = state
            .catalog
            .as_ref()
            .and_then(|catalog| catalog.methods.iter().find(|method| method.id == method_id))
            .cloned()
        else {
            return;
        };
        if method.kind == AgentAuthMethodKind::Terminal
            || method.kind == AgentAuthMethodKind::Environment
            || method.effect == AgentAuthMethodEffect::RequiresProviderProfile
        {
            self.open_agent_auth_management(state.agent_id, cx);
            return;
        }
        let (Some(backend), Some(context)) = (self.backend.clone(), state.context) else {
            return;
        };
        if state.pending {
            return;
        }
        self.runtime_authentication_generation =
            self.runtime_authentication_generation.wrapping_add(1);
        let generation = self.runtime_authentication_generation;
        if let Some(current) = self.runtime_authentication_menu.as_mut() {
            current.pending = true;
            current.error = None;
        }
        let operation_id = AgentAuthenticationOperationId::new();
        let request = AgentAuthContextAuthenticateRequest {
            operation_id,
            auth_context_id: context.id,
            expected_context_revision: context.revision,
            method_id,
        };
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            backend
                .agent()
                .authenticate_agent_context(MutationRequest::new(request))
                .await
        });
        self.runtime_authentication_task = Some(cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                let outcome = runner.await;
                let _ = entity.update(cx, |this, cx| {
                    if this.runtime_authentication_generation != generation {
                        return;
                    }
                    let mut authenticated = false;
                    if let Some(state) = this.runtime_authentication_menu.as_mut() {
                        state.pending = false;
                        match outcome {
                            Ok(Ok(result)) if result.terminal.is_none() => {
                                state.context = Some(result.context);
                                state.error = None;
                                authenticated = true;
                            }
                            Ok(Ok(_)) => {
                                state.error = Some(
                                    locale::text(
                                        "Continue terminal sign-in in Config Center",
                                        "请在配置中心继续终端登录",
                                        "請在配置中心繼續終端登入",
                                    )
                                    .to_string(),
                                );
                            }
                            Ok(Err(error)) => {
                                state.error = Some(format!("{}: {}", error.code, error.message));
                            }
                            Err(error) => {
                                state.error = Some(format!("Authentication task failed: {error}"));
                            }
                        }
                    }
                    if authenticated {
                        if this.new_session_runtime_menu_open {
                            this.new_session_runtime_menu_view =
                                ComposerRuntimeMenuView::AuthSource;
                        }
                        if this.composer_runtime_menu_open {
                            this.composer_runtime_menu_view = ComposerRuntimeMenuView::AuthSource;
                        }
                        this.load_agent_runtime_catalog(cx);
                    }
                    cx.notify();
                });
            },
        ));
        cx.notify();
    }

    fn verify_runtime_authentication_menu(&mut self, cx: &mut Context<Self>) {
        let Some(state) = self.runtime_authentication_menu.clone() else {
            return;
        };
        let (Some(backend), Some(context)) = (self.backend.clone(), state.context) else {
            return;
        };
        if state.pending {
            return;
        }
        self.runtime_authentication_generation =
            self.runtime_authentication_generation.wrapping_add(1);
        let generation = self.runtime_authentication_generation;
        if let Some(current) = self.runtime_authentication_menu.as_mut() {
            current.pending = true;
            current.error = None;
        }
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            backend
                .agent()
                .verify_agent_auth_context(MutationRequest::new(AgentAuthContextVerifyRequest {
                    auth_context_id: context.id,
                    expected_context_revision: context.revision,
                    operation_id: None,
                }))
                .await
        });
        self.runtime_authentication_task = Some(cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                let outcome = runner.await;
                let _ = entity.update(cx, |this, cx| {
                    if this.runtime_authentication_generation != generation {
                        return;
                    }
                    let mut verified = false;
                    if let Some(state) = this.runtime_authentication_menu.as_mut() {
                        state.pending = false;
                        match outcome {
                            Ok(Ok(result)) => {
                                state.context = Some(result.context);
                                state.error = None;
                                verified = true;
                            }
                            Ok(Err(error)) => {
                                state.error = Some(format!("{}: {}", error.code, error.message));
                            }
                            Err(error) => {
                                state.error = Some(format!("Verification task failed: {error}"));
                            }
                        }
                    }
                    if verified {
                        if this.new_session_runtime_menu_open {
                            this.new_session_runtime_menu_view =
                                ComposerRuntimeMenuView::AuthSource;
                        }
                        if this.composer_runtime_menu_open {
                            this.composer_runtime_menu_view = ComposerRuntimeMenuView::AuthSource;
                        }
                        this.load_agent_runtime_catalog(cx);
                    }
                    cx.notify();
                });
            },
        ));
        cx.notify();
    }

    fn open_agent_auth_management(&mut self, agent_id: AgentId, cx: &mut Context<Self>) {
        self.new_session_runtime_menu_open = false;
        self.composer_runtime_menu_open = false;
        self.open_management(cx);
        self.management_view.update(cx, |management, cx| {
            management.show_agent_authentication(agent_id, cx)
        });
    }

    fn retry_runtime_selection(&mut self, cx: &mut Context<Self>) {
        let Some(desired) = self
            .runtime_selection
            .as_ref()
            .map(|state| state.desired.clone())
        else {
            return;
        };
        self.request_runtime_selection(desired, true, cx);
    }

    fn reset_runtime_selection(&mut self, cx: &mut Context<Self>) {
        let Some(effective) = self
            .runtime_selection
            .as_ref()
            .map(|state| state.effective.clone())
        else {
            return;
        };
        self.request_runtime_selection(effective, false, cx);
    }

    fn request_runtime_selection(
        &mut self,
        desired: SessionRuntimeSelection,
        retry_same_desired: bool,
        cx: &mut Context<Self>,
    ) {
        let (Some(session_id), Some(state)) = (
            self.selected_session_id.clone(),
            self.runtime_selection.clone(),
        ) else {
            return;
        };
        let request_in_flight = self
            .runtime_selection_requests_in_flight
            .contains(session_id.as_str());
        if !retry_same_desired && desired == state.desired && !request_in_flight {
            self.remember_runtime_selection(&desired);
            return;
        }
        self.optimistic_runtime_selections
            .insert(session_id.as_str().to_string(), desired);
        self.refresh_active_suggestions(ComposerTarget::Session, cx);
        self.request_pending_runtime_selection(&session_id, &state, retry_same_desired, cx);
        cx.notify();
    }

    /// Remote twin of [`Self::fork_session_at`]: a single fork RPC without
    /// the creation announcement channel; the new session is navigated to
    /// from the RPC result and sidebar updates arrive through events.
    fn fork_session_at_remote(
        &mut self,
        backend: BackendFacade,
        source_session_id: VibexSessionId,
        through_sequence: i64,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.agent_action_pending = true;
        self.fork_session_pending = true;
        self.agent_error = None;
        window.push_notification(
            hint_notification(
                NotificationType::Info,
                locale::text(
                    "Creating forked session...",
                    "正在创建分叉会话...",
                    "正在建立分支會話...",
                ),
                cx,
            )
            .id::<ForkSessionNotification>()
            .autohide(false),
            cx,
        );
        let generation = self.session_generation;
        let selected_source_session_id = source_session_id.clone();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            backend
                .agent()
                .fork_session(MutationRequest::new(ForkAgentSessionRequest {
                    source_session_id,
                    through_sequence,
                    expected_source_end_sequence: None,
                }))
                .await
        });
        self.fork_session_task = Some(cx.spawn_in(
            window,
            async move |entity: WeakEntity<Self>, cx| {
                let outcome = runner.await;
                let _ = entity.update_in(cx, |this, window, cx| {
                    this.fork_session_pending = false;
                    this.agent_action_pending = false;
                    match outcome {
                        Ok(Ok(session)) => {
                            this.upsert_session_snapshot(session.clone());
                            this.reconcile_sidebar_state();
                            window.push_notification(
                                hint_notification(
                                    NotificationType::Info,
                                    locale::text(
                                        "Fork created. Preparing its runtime...",
                                        "分叉会话已创建，正在准备运行时...",
                                        "分支會話已建立，正在準備執行環境...",
                                    ),
                                    cx,
                                )
                                .id::<ForkSessionNotification>()
                                .autohide(false),
                                cx,
                            );
                            if this.session_generation == generation {
                                this.select_session_with_history(session.id.clone(), false, cx);
                            }
                        }
                        Ok(Err(error)) => {
                            this.agent_error = Some(format!("{}: {}", error.code, error.message));
                        }
                        Err(error) => {
                            this.agent_error = Some(format!("Agent action failed: {error}"));
                        }
                    }
                    let _ = selected_source_session_id;
                    cx.notify();
                });
            },
        ));
    }

    fn cancel_runtime_switch(&mut self, cx: &mut Context<Self>) {
        let (Some(backend), Some(session_id), Some(switch_id)) = (
            self.backend.clone(),
            self.selected_session_id.clone(),
            self.runtime_selection
                .as_ref()
                .and_then(|state| state.pending_switch_id.clone()),
        ) else {
            return;
        };
        let session_key = session_id.as_str().to_string();
        if self
            .runtime_selection_cancellations_in_flight
            .contains(&session_key)
        {
            return;
        }
        self.optimistic_runtime_selections
            .remove(session_id.as_str());
        self.runtime_selection_cancellations_in_flight
            .insert(session_key.clone());
        let generation = self.session_generation;
        let requested_session_id = session_id.clone();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            backend
                .agent()
                .cancel_runtime_switch(MutationRequest::new(
                    CancelAgentSessionRuntimeSwitchRequest {
                        session_id,
                        switch_id,
                    },
                ))
                .await
        });
        cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                let outcome = runner.await;
                let _ = entity.update(cx, |this, cx| {
                    this.runtime_selection_cancellations_in_flight
                        .remove(&session_key);
                    let active = this.session_generation == generation
                        && this.selected_session_id.as_ref() == Some(&requested_session_id);
                    match outcome {
                        Ok(Ok(state)) => {
                            this.apply_runtime_selection_state(&requested_session_id, state, cx);
                        }
                        Ok(Err(error)) if active => {
                            this.agent_error = Some(format!("{}: {}", error.code, error.message));
                        }
                        Err(error) if active => {
                            this.agent_error = Some(format!("runtime cancel failed: {error}"));
                        }
                        Ok(Err(_)) | Err(_) => {}
                    }
                    cx.notify();
                });
            },
        )
        .detach();
    }

    fn begin_sidebar_rename(
        &mut self,
        session_id: VibexSessionId,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(title) = self
            .sessions
            .iter()
            .find(|session| session.id == session_id)
            .map(|session| session.title.clone())
        else {
            return;
        };
        self.retain_sidebar_hover_preview();
        self.sidebar_rename_target = Some(SidebarRenameTarget::Session(session_id));
        self.sidebar_rename_error = None;
        self.sidebar_rename_input.update(cx, |input, cx| {
            input.set_value(title.clone(), window, cx);
            input.set_selected_range(0..title.len(), cx);
            input.focus(window, cx);
        });
        cx.notify();
    }

    fn begin_sidebar_folder_rename(
        &mut self,
        folder_id: String,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(name) = self
            .ui_state
            .sidebar
            .organization
            .folder(&folder_id)
            .map(|folder| folder.name.clone())
        else {
            return;
        };
        self.retain_sidebar_hover_preview();
        self.sidebar_rename_target = Some(SidebarRenameTarget::Folder(folder_id));
        self.sidebar_rename_error = None;
        self.sidebar_rename_input.update(cx, |input, cx| {
            input.set_value(name.clone(), window, cx);
            input.set_selected_range(0..name.len(), cx);
            input.focus(window, cx);
        });
        cx.notify();
    }

    fn create_sidebar_folder(
        &mut self,
        project_id: Option<String>,
        workspace_id: Option<String>,
        parent_folder_id: Option<String>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let folder_id = RequestId::new().to_string();
        let project_id_to_reveal = project_id.clone();
        let preferred_name = locale::text("New Folder", "新建文件夹", "新建資料夾");
        let Some(default_name) = self
            .ui_state
            .sidebar
            .organization
            .next_available_folder_name_for_workspace(
                preferred_name,
                project_id.as_deref(),
                workspace_id.as_deref(),
                parent_folder_id.as_deref(),
            )
        else {
            return;
        };
        if !self
            .ui_state
            .sidebar
            .organization
            .create_folder_with_workspace(
                folder_id.clone(),
                default_name,
                project_id,
                workspace_id,
                parent_folder_id.clone(),
            )
        {
            return;
        }
        if let Some(parent_folder_id) = parent_folder_id {
            self.ui_state
                .sidebar
                .organization
                .collapsed_folder_ids
                .remove(&parent_folder_id);
        }
        if let Some(project_id) = project_id_to_reveal
            && self.sidebar_state.collapsed_ids.remove(&project_id)
        {
            self.queue_agent_ui_state();
        }
        self.queue_ui_state();
        self.publish_sidebar_invalidation();
        self.begin_sidebar_folder_rename(folder_id, window, cx);
    }

    fn delete_sidebar_folder(&mut self, folder_id: &str, cx: &mut Context<Self>) {
        if !self.ui_state.sidebar.organization.delete_folder(folder_id) {
            return;
        }
        let rename_target_is_stale =
            self.sidebar_rename_target
                .as_ref()
                .is_some_and(|target| match target {
                    SidebarRenameTarget::Session(_) => false,
                    SidebarRenameTarget::Folder(target_id) => !self
                        .ui_state
                        .sidebar
                        .organization
                        .folders
                        .contains_key(target_id),
                    SidebarRenameTarget::Group(target_id) => !self
                        .ui_state
                        .sidebar
                        .organization
                        .groups
                        .contains_key(target_id),
                });
        if rename_target_is_stale {
            self.sidebar_rename_target = None;
            self.sidebar_rename_error = None;
        }
        self.clear_sidebar_context_menu_target(cx);
        self.queue_ui_state();
        self.publish_sidebar_invalidation();
        cx.notify();
    }

    fn set_sidebar_folder_auto_archive_after_days(
        &mut self,
        folder_id: &str,
        days: Option<u8>,
        cx: &mut Context<Self>,
    ) {
        if !self
            .ui_state
            .sidebar
            .organization
            .set_folder_auto_archive_after_days(folder_id, days)
        {
            return;
        }
        self.queue_ui_state();
        self.apply_sidebar_scheduled_archives(unix_timestamp_ms());
        self.invalidate_sidebar_projection_cache();
        self.publish_sidebar_invalidation();
        cx.notify();
    }

    fn confirm_delete_sidebar_folder(
        &mut self,
        folder_id: String,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if !self
            .ui_state
            .sidebar
            .organization
            .folder_contains_items(&folder_id)
        {
            self.delete_sidebar_folder(&folder_id, cx);
            return;
        }
        let Some(folder_name) = self
            .ui_state
            .sidebar
            .organization
            .folder(&folder_id)
            .map(|folder| folder.name.clone())
        else {
            return;
        };
        let title = match self.resolved_locale() {
            locale::ResolvedLocale::En => format!("Delete '{folder_name}'?"),
            locale::ResolvedLocale::ZhCn => format!("删除“{folder_name}”？"),
            locale::ResolvedLocale::ZhTw => format!("刪除「{folder_name}」？"),
        };
        let description = locale::text(
            "Projects and sessions inside will return to their default locations. Nested folders will also be deleted.",
            "其中的项目和会话将回到默认位置，嵌套文件夹也会一并删除。",
            "其中的專案和工作階段將回到預設位置，巢狀資料夾也會一併刪除。",
        );
        let strings = self.strings();
        let entity = cx.weak_entity();
        window.open_dialog(cx, move |dialog, _, _| {
            let entity = entity.clone();
            let folder_id = folder_id.clone();
            dialog
                .title(title.clone())
                .child(description)
                .footer(
                    DialogFooter::new()
                        .child(
                            DialogClose::new().child(
                                Button::new("cancel-delete-sidebar-folder")
                                    .outline()
                                    .label(strings.sidebar_cancel),
                            ),
                        )
                        .child(
                            DialogAction::new().child(
                                Button::new("confirm-delete-sidebar-folder")
                                    .danger()
                                    .label(strings.sidebar_delete),
                            ),
                        ),
                )
                .on_ok(move |_, _, cx| {
                    let _ =
                        entity.update(cx, |this, cx| this.delete_sidebar_folder(&folder_id, cx));
                    true
                })
        });
    }

    fn toggle_sidebar_folder(&mut self, folder_id: &str, cx: &mut Context<Self>) {
        if self
            .ui_state
            .sidebar
            .organization
            .toggle_collapsed(folder_id)
            .is_some()
        {
            self.queue_ui_state();
            self.publish_sidebar_invalidation();
            cx.notify();
        }
    }

    fn cancel_sidebar_rename(&mut self, cx: &mut Context<Self>) {
        self.sidebar_rename_target = None;
        self.sidebar_rename_error = None;
        cx.notify();
    }

    /// The session a sidebar rename is editing, if any. Session rows change
    /// height while they hold the rename input, so the sidebar's windowed row
    /// runs need to know which one to lay out in flow instead.
    fn sidebar_renaming_session_id(&self) -> Option<&str> {
        match self.sidebar_rename_target.as_ref() {
            Some(SidebarRenameTarget::Session(session_id)) => Some(session_id.as_str()),
            Some(SidebarRenameTarget::Folder(_) | SidebarRenameTarget::Group(_)) | None => None,
        }
    }

    fn finish_sidebar_rename_on_blur(&mut self, cx: &mut Context<Self>) {
        let Some(target) = self.sidebar_rename_target.clone() else {
            return;
        };
        let value = self
            .sidebar_rename_input
            .read(cx)
            .value()
            .trim()
            .to_string();
        let valid = !value.is_empty()
            && match &target {
                SidebarRenameTarget::Session(_) => true,
                SidebarRenameTarget::Folder(folder_id) => self
                    .ui_state
                    .sidebar
                    .organization
                    .folder_name_available(folder_id, &value),
                SidebarRenameTarget::Group(group_id) => self
                    .ui_state
                    .sidebar
                    .organization
                    .group(group_id)
                    .is_some_and(|group| {
                        self.ui_state
                            .sidebar
                            .organization
                            .group_name_is_available_at(
                                Some(group_id),
                                &value,
                                &group.project_id,
                                &group.workspace_id,
                                self.ui_state
                                    .sidebar
                                    .organization
                                    .parent_of(&SidebarOrganizationItem::Group(group_id.clone()))
                                    .as_deref(),
                            )
                    }),
            };
        if valid {
            self.commit_sidebar_rename(cx);
        } else {
            self.cancel_sidebar_rename(cx);
        }
    }

    fn commit_sidebar_rename(&mut self, cx: &mut Context<Self>) {
        let Some(target) = self.sidebar_rename_target.clone() else {
            return;
        };
        let value = self
            .sidebar_rename_input
            .read(cx)
            .value()
            .trim()
            .to_string();
        if value.is_empty() {
            self.sidebar_rename_error = Some(match target {
                SidebarRenameTarget::Session(_) => self.strings().sidebar_rename_empty.to_string(),
                SidebarRenameTarget::Folder(_) => locale::text(
                    "Enter a folder name.",
                    "请输入文件夹名称。",
                    "請輸入資料夾名稱。",
                )
                .to_string(),
                SidebarRenameTarget::Group(_) => {
                    self.strings().sidebar_group_rename_empty.to_string()
                }
            });
            cx.notify();
            return;
        }
        match target {
            SidebarRenameTarget::Session(session_id) => {
                if self.agent_action_pending {
                    return;
                }
                if self
                    .sessions
                    .iter()
                    .find(|session| session.id == session_id)
                    .is_some_and(|session| session.title == value)
                {
                    self.cancel_sidebar_rename(cx);
                    return;
                }
                self.rename_session(session_id, value, cx);
            }
            SidebarRenameTarget::Folder(folder_id) => {
                if !self
                    .ui_state
                    .sidebar
                    .organization
                    .folder_name_available(&folder_id, &value)
                {
                    self.sidebar_rename_error = Some(
                        locale::text(
                            "A folder with this name already exists here.",
                            "同级目录下已存在同名文件夹。",
                            "同層目錄下已存在同名資料夾。",
                        )
                        .to_string(),
                    );
                    cx.notify();
                    return;
                }
                let changed = self
                    .ui_state
                    .sidebar
                    .organization
                    .rename_folder(&folder_id, &value);
                self.sidebar_rename_target = None;
                self.sidebar_rename_error = None;
                if changed {
                    self.queue_ui_state();
                    self.publish_sidebar_invalidation();
                }
                cx.notify();
            }
            SidebarRenameTarget::Group(group_id) => {
                let available = self
                    .ui_state
                    .sidebar
                    .organization
                    .group(&group_id)
                    .is_some_and(|group| {
                        self.ui_state
                            .sidebar
                            .organization
                            .group_name_is_available_at(
                                Some(&group_id),
                                &value,
                                &group.project_id,
                                &group.workspace_id,
                                self.ui_state
                                    .sidebar
                                    .organization
                                    .parent_of(&SidebarOrganizationItem::Group(group_id.clone()))
                                    .as_deref(),
                            )
                    });
                if !available {
                    self.sidebar_rename_error = Some(
                        locale::text(
                            "A session group with this name already exists here.",
                            "同级目录下已存在同名会话组。",
                            "同層目錄下已存在同名會話組。",
                        )
                        .to_string(),
                    );
                    cx.notify();
                    return;
                }
                let changed = self
                    .ui_state
                    .sidebar
                    .organization
                    .rename_group(&group_id, &value);
                self.sidebar_rename_target = None;
                self.sidebar_rename_error = None;
                if changed {
                    self.queue_ui_state();
                    self.publish_sidebar_invalidation();
                }
                cx.notify();
            }
        }
    }

    fn on_sidebar_rename_key_down(
        &mut self,
        event: &KeyDownEvent,
        _: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if event.keystroke.key == "escape" {
            self.cancel_sidebar_rename(cx);
            cx.stop_propagation();
        }
    }

    fn rename_session(
        &mut self,
        session_id: VibexSessionId,
        title: String,
        cx: &mut Context<Self>,
    ) {
        if self.agent_action_pending {
            return;
        }
        let title = title.trim().to_string();
        if title.is_empty() {
            if self.sidebar_rename_target == Some(SidebarRenameTarget::Session(session_id.clone()))
            {
                self.sidebar_rename_error = Some(self.strings().sidebar_rename_empty.to_string());
            } else {
                self.agent_error = Some(self.strings().sidebar_rename_empty.to_string());
            }
            cx.notify();
            return;
        }
        let Some(backend) = self.backend.clone() else {
            return;
        };
        let renamed_session_id = session_id.clone();
        let inline_rename =
            self.sidebar_rename_target == Some(SidebarRenameTarget::Session(session_id.clone()));
        self.agent_action_pending = true;
        let generation = self.session_generation;
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            backend
                .agent()
                .rename_session(MutationRequest::new(RenameAgentSessionRequest {
                    session_id,
                    title,
                }))
                .await
        });
        self.agent_action_task = Some(cx.spawn(
            async move |entity: WeakEntity<Self>, cx: &mut gpui::AsyncApp| {
                let outcome = runner.await;
                let _ = entity.update(cx, |this, cx| {
                    this.agent_action_pending = false;
                    let active = this.session_generation == generation;
                    match outcome {
                        Ok(Ok(updated)) => {
                            if let Some(session) = this
                                .sessions
                                .iter_mut()
                                .find(|session| session.id == updated.id)
                            {
                                *session = updated;
                                this.invalidate_sidebar_projection_cache();
                                this.publish_sidebar_invalidation();
                            }
                            if this.sidebar_rename_target
                                == Some(SidebarRenameTarget::Session(renamed_session_id.clone()))
                            {
                                this.sidebar_rename_target = None;
                                this.sidebar_rename_error = None;
                            }
                        }
                        Ok(Err(error)) if active => {
                            if inline_rename {
                                this.sidebar_rename_error =
                                    Some(format!("{}: {}", error.code, error.message));
                            } else {
                                this.agent_error =
                                    Some(format!("{}: {}", error.code, error.message));
                            }
                        }
                        Err(error) if active => {
                            if inline_rename {
                                this.sidebar_rename_error =
                                    Some(format!("session rename failed: {error}"));
                            } else {
                                this.agent_error = Some(format!("session rename failed: {error}"));
                            }
                        }
                        Ok(Err(_)) | Err(_) => {}
                    }
                    cx.notify();
                });
            },
        ));
    }

