    fn clear_runtime_selection_preferences(&mut self, cx: &mut Context<Self>) {
        let mut agent_ids = self
            .ui_state
            .composer
            .runtime_selections_by_agent
            .keys()
            .cloned()
            .collect::<BTreeSet<_>>();
        agent_ids.extend(
            self.ui_state
                .composer
                .runtime_selections_by_model
                .iter()
                .map(|selection| selection.agent_id.clone()),
        );
        if let Some(selection) = &self.ui_state.composer.default_runtime_selection {
            agent_ids.insert(selection.agent_id.clone());
        }
        for agent_id in agent_ids {
            self.runtime_preference_write_fence.begin(&agent_id);
        }
        self.ui_state.composer.default_runtime_selection = None;
        self.ui_state.composer.runtime_selections_by_agent.clear();
        self.ui_state.composer.runtime_selections_by_model.clear();
        if self.reconcile_new_session_runtime_selection() && self.new_session_open {
            self.refresh_active_suggestions(ComposerTarget::NewSession, cx);
        }
    }

    fn restore_settings_changes(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some(snapshot) = self.settings_snapshot.clone() else {
            return;
        };
        let application_id = self
            .config
            .as_ref()
            .map(|config| config.application_id.as_str())
            .unwrap_or("com.vibex.desktop");
        let launch_at_login = snapshot.desktop_behavior.launch_at_login;
        if let Err(error) = set_launch_at_login(launch_at_login, application_id) {
            self.queue_settings_operation_notice(
                SettingsOperationNotice::error(format!("{}: {}", error.code, error.message)),
                cx,
            );
        }

        let auto_continue_default_project_ids = snapshot.session.auto_continue_project_ids.clone();
        let auto_continue_session_ids = restored_auto_continue_session_ids(&snapshot.session);
        let auto_continue_paused_session_ids =
            snapshot.session.auto_continue_paused_session_ids.clone();
        let selected_session_id = snapshot
            .workbench
            .selected_session_id
            .as_deref()
            .and_then(|id| VibexSessionId::parse(id).ok());
        let code_font_family = snapshot
            .appearance
            .code_font
            .family
            .clone()
            .unwrap_or_else(|| crate::platform::default_code_font_family().to_string());
        let code_font_size = snapshot.appearance.code_font.size;
        let preview = snapshot.preview.layout.clone();
        let parked_previews = snapshot.preview.layout_scopes.clone();
        let preview_owner = if snapshot.workbench.workspace_state_scope.is_session() {
            selected_session_id
                .as_ref()
                .map(|session_id| session_id.as_str().to_string())
        } else {
            snapshot.workbench.selected_workspace_id.clone()
        };
        self.workspace_layout_owner = preview_owner.clone();
        let recovery = snapshot.preview.editor_recovery.clone();
        let editor_soft_wrap = snapshot.preview.editor_soft_wrap;
        let editor_show_whitespaces = snapshot.preview.editor_show_whitespaces;
        let editor_autosave = snapshot.preview.editor_autosave;
        let editor_autosave_delay_ms = snapshot.preview.editor_autosave_delay_ms;
        let workspace_id = snapshot.workbench.selected_workspace_id.clone();
        let right_rail_mode =
            right_rail_mode_from_activity_id(snapshot.right_rail.selected_activity_id.as_deref());

        let restored_proxy =
            match vibex_desktop_runtime::network_proxy::configure(&snapshot.network_proxy) {
                Ok(settings) => settings,
                Err(error) => {
                    self.queue_settings_operation_notice(
                        SettingsOperationNotice::error(locale::localize_ui_message(&error)),
                        cx,
                    );
                    NetworkProxyUiState::default()
                }
            };

        self.ui_state = snapshot;
        self.ui_state.network_proxy = restored_proxy;
        self.auto_continue_default_project_ids = auto_continue_default_project_ids;
        self.auto_continue_session_ids = auto_continue_session_ids;
        self.auto_continue_paused_session_ids = auto_continue_paused_session_ids;
        self.sidebar_state.row_order = self.ui_state.sidebar.session_order.clone();
        self.sidebar_state.pinned_ids = self.ui_state.sidebar.pinned_session_ids.clone();
        self.sidebar_state.collapsed_ids = self.ui_state.sidebar.collapsed_project_ids.clone();
        self.sidebar_state.selected_ids.clear();
        self.invalidate_sidebar_projection_cache();
        self.selected_session_id = selected_session_id;
        self.right_rail_mode = right_rail_mode;
        self.appearance_reload_pending = true;
        self.preview_overlay_open = false;
        self.right_rail_overlay_open = false;
        self.sidebar_hover_preview_open = false;
        self.code_workbench.update(cx, |workbench, cx| {
            workbench.restore_persisted_state(
                preview,
                preview_owner,
                parked_previews,
                recovery,
                workspace_id,
                code_font_family.clone(),
                code_font_size,
                editor_soft_wrap,
                editor_show_whitespaces,
                editor_autosave,
                editor_autosave_delay_ms,
                cx,
            );
            workbench.right_rail_mode = right_rail_mode;
            workbench.set_code_font(code_font_family, code_font_size, cx);
        });
        self.code_right_rail.update(cx, |right_rail, cx| {
            right_rail.set_mode(right_rail_mode, cx)
        });
        theme::apply_appearance(&self.ui_state.appearance, Some(window), cx);
        locale::apply_locale(self.ui_state.appearance.locale);
        self.sync_locale_dependents(window, cx);
        crate::system_tray::update_locale(self.resolved_locale(), cx);

        let appearance = self.ui_state.appearance.clone();
        let session = self.ui_state.session.clone();
        let terminal_preferences = self.ui_state.terminal_preferences.clone();
        let network_proxy = self.ui_state.network_proxy.clone();
        let settings_view = self.settings_view.clone();
        window.defer(cx, move |window, cx| {
            settings_view.update(cx, |settings, cx| {
                settings.sync_controls(
                    &appearance,
                    &session,
                    &terminal_preferences,
                    &network_proxy,
                    window,
                    cx,
                )
            });
        });
        self.rebuild_timeline_sizes();
        self.sync_update_panel(cx);
        self.queue_ui_state();
        cx.notify();
    }

    fn toggle_settings(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if self.settings_open {
            if window.has_active_dialog(cx) {
                window.close_dialog(cx);
            }
            if !window.has_active_dialog(cx) {
                self.settings_open = false;
                self.settings_view.update(cx, |settings, cx| {
                    settings.shortcut_note = None;
                    cx.notify();
                });
            }
            cx.notify();
        } else {
            self.open_settings(window, cx);
        }
    }

    fn open_settings(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if self.settings_open || window.has_active_dialog(cx) || window.has_active_sheet(cx) {
            return;
        }
        self.settings_snapshot = Some(self.ui_state.clone());
        self.settings_view.update(cx, |settings, cx| {
            settings.active_section = SettingsSection::General;
            settings.shortcut_note = None;
            settings.search_selected_index = 0;
            settings
                .search
                .update(cx, |input, cx| input.set_value("", window, cx));
            settings
                .settings_render_context
                .target_title
                .borrow_mut()
                .take();
            settings
                .settings_render_context
                .highlighted_title
                .borrow_mut()
                .take();
            settings
                .settings_render_context
                .target_anchor
                .borrow_mut()
                .take();
            settings
                .settings_render_context
                .scroll
                .set_offset(point(px(0.0), px(0.0)));
            cx.notify();
        });
        self.settings_open = true;
        eprintln!("vibex-foundation: settings-dialog-open");
        let settings = self.settings_view.clone();
        let workbench = cx.weak_entity();
        let viewport = window.viewport_size();
        let viewport_width = f32::from(viewport.width);
        let viewport_height = f32::from(viewport.height);
        let dialog_width = (viewport_width - 32.0).clamp(1.0, SETTINGS_DIALOG_MAX_WIDTH);
        let dialog_height = (viewport_height - 32.0).clamp(1.0, SETTINGS_DIALOG_MAX_HEIGHT);
        let dialog_margin_top = ((viewport_height - dialog_height) / 2.0).max(8.0);
        window.open_dialog(cx, move |dialog, _, cx| {
            let on_close = workbench.clone();
            let is_dark = cx.theme().is_dark();
            let popover = theme::semantic_color("popover", is_dark);
            let popover_foreground = theme::semantic_color("popover-foreground", is_dark);
            let settings_for_content = settings.clone();
            dialog
                .w(px(dialog_width))
                .max_w(px(dialog_width))
                .h(px(dialog_height))
                .margin_top(px(dialog_margin_top))
                .p_0()
                .rounded(px(SETTINGS_DIALOG_RADIUS))
                .bg(popover)
                .text_color(popover_foreground)
                .border_color(popover_foreground.opacity(0.16))
                .overlay(true)
                .overlay_closable(true)
                .on_close(move |_, _, cx| {
                    let _ = on_close.update(cx, |this, cx| {
                        this.settings_open = false;
                        this.settings_snapshot = None;
                        this.settings_view.update(cx, |settings, cx| {
                            settings.shortcut_note = None;
                            cx.notify();
                        });
                        cx.notify();
                    });
                })
                .content(move |content, _, _| content.min_h_0().child(settings_for_content.clone()))
        });
        cx.notify();
    }

    /// Open About and scroll to the update card, which carries the full
    /// release notes for the release the title-bar panel describes.
    fn open_update_settings(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if !self.settings_open {
            self.open_settings(window, cx);
        }
        let title = locale::text("Software update", "软件更新", "軟體更新");
        self.settings_view.update(cx, |settings, cx| {
            settings.activate_settings_section(SettingsSection::About, cx);
            settings.shortcut_note = None;
            settings
                .settings_render_context
                .target_title
                .borrow_mut()
                .replace(title.to_string());
            settings
                .settings_render_context
                .highlighted_title
                .borrow_mut()
                .replace(title.to_string());
            cx.notify();
        });
        cx.notify();
    }

    /// The title-bar update entry: an arrow that toggles the update panel.
    ///
    /// `Popover` owns the toggle from its mouse-down handler and applies the
    /// trigger's selected state itself, so the trigger must not add its own
    /// click handler.
    fn render_update_entry(&mut self, version: &str, cx: &mut Context<Self>) -> AnyElement {
        let panel = self.render_update_panel(cx);
        let tooltip = if version.is_empty() {
            locale::text("Update available", "有可用更新", "有可用更新").to_string()
        } else {
            format!(
                "{} {version}",
                locale::text("Update available", "有可用更新", "有可用更新")
            )
        };
        let trigger = Button::new("open-update")
            .small()
            .ghost()
            .compact()
            .size(px(32.0))
            .px_0()
            .tooltip(tooltip)
            // Green marks the entry as "an update is waiting", which is the only
            // state this trigger is rendered in.
            .child(
                Icon::new(IconName::ArrowDown)
                    .size(px(18.0))
                    .text_color(cx.theme().success),
            );
        div()
            .flex_none()
            .child(
                Popover::new("update-popover")
                    .anchor(Anchor::TopRight)
                    .appearance(false)
                    // The panel reports progress and offers the install; it
                    // stays until the user closes it instead of disappearing
                    // on the next click elsewhere.
                    .overlay_closable(false)
                    .open(self.update_panel_open)
                    .on_open_change(cx.listener(|this, open: &bool, _, cx| {
                        this.set_update_panel_open(*open, cx);
                    }))
                    .trigger(trigger)
                    .child(panel)
                    .top(px(6.0)),
            )
            .into_any_element()
    }

    fn strings(&self) -> &'static Strings {
        locale::strings(self.resolved_locale())
    }

    /// The locale this workbench renders in.
    ///
    /// `System` reads the value `apply_locale` resolved once at startup;
    /// re-parsing the system tag here allocated twice per call and this runs
    /// per rendered row.
    fn resolved_locale(&self) -> locale::ResolvedLocale {
        match self.ui_state.appearance.locale {
            LocaleMode::System => locale::current_locale(),
            mode => locale::resolve_locale(mode, None),
        }
    }

    fn open_pairing(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some(runtime) = self.runtime.clone() else {
            return;
        };
        open_remote_access_pairing(runtime, window, cx);
    }

    /// The rounded panel below the title-bar arrow.
    ///
    /// It reports what the updater is doing and offers the one valid next
    /// action for the current state. With automatic updates on the download
    /// already runs, so the panel only reports progress; otherwise it asks
    /// before downloading. Release notes stay on About, which the footer
    /// opens.
    fn render_update_panel(&mut self, cx: &mut Context<Self>) -> AnyElement {
        let state = self.update_snapshot.state.clone();
        let release = state.release().cloned();
        let auto_update = self.ui_state.desktop_behavior.auto_update;
        let muted_foreground = cx.theme().muted_foreground;

        let (description, control): (SharedString, AnyElement) = match &state {
            UpdateState::Idle | UpdateState::Checking => (
                locale::text(
                    "Checking for a signed release…",
                    "正在检查已签名版本…",
                    "正在檢查已簽署版本…",
                )
                .into(),
                div().into_any_element(),
            ),
            UpdateState::Available { .. } => {
                if auto_update {
                    (
                        locale::text("Starting the download…", "正在开始下载…", "正在開始下載…")
                            .into(),
                        Progress::new("update-panel-progress")
                            .small()
                            .loading(true)
                            .into_any_element(),
                    )
                } else {
                    (
                        locale::text(
                            "A newer signed release is available.",
                            "发现新的已签名版本。",
                            "發現新的已簽署版本。",
                        )
                        .into(),
                        Button::new("update-panel-download")
                            .small()
                            .primary()
                            .icon(IconName::ArrowDown)
                            .label(locale::text("Update", "更新", "更新"))
                            .on_click(
                                cx.listener(|this, _, _, cx| this.request_update_download(cx)),
                            )
                            .into_any_element(),
                    )
                }
            }
            UpdateState::Downloading {
                downloaded_bytes,
                total_bytes,
                ..
            } => {
                let percent = downloaded_bytes
                    .saturating_mul(100)
                    .checked_div(*total_bytes)
                    .unwrap_or(0);
                let progress = v_flex()
                    .w_full()
                    .min_w_0()
                    .gap_2()
                    .child(
                        Progress::new("update-panel-progress")
                            .small()
                            .value(percent as f32),
                    )
                    .child(div().text_xs().text_color(muted_foreground).child(format!(
                        "{} / {} ({percent}%)",
                        format_bytes(*downloaded_bytes),
                        format_bytes(*total_bytes)
                    )));
                (
                    locale::text(
                        "Downloading the signed update…",
                        "正在下载已签名的更新…",
                        "正在下載已簽署的更新…",
                    )
                    .into(),
                    progress.into_any_element(),
                )
            }
            UpdateState::Verifying { .. } => (
                locale::text(
                    "Verifying the download…",
                    "正在验证下载内容…",
                    "正在驗證下載內容…",
                )
                .into(),
                Progress::new("update-panel-progress")
                    .small()
                    .loading(true)
                    .into_any_element(),
            ),
            UpdateState::Staged { .. } => (
                locale::text(
                    "Downloaded and verified. Installing restarts Vibex.",
                    "已下载并通过验证，安装后将重启 Vibex。",
                    "已下載並通過驗證，安裝後將重新啟動 Vibex。",
                )
                .into(),
                Button::new("update-panel-install")
                    .small()
                    .primary()
                    .label(locale::text(
                        "Install and restart",
                        "安装并重启",
                        "安裝並重新啟動",
                    ))
                    .on_click(cx.listener(|this, _, _, cx| this.install_update_and_restart(cx)))
                    .into_any_element(),
            ),
            UpdateState::Installing { .. } => (
                locale::text(
                    "The system installer is open. Complete its confirmation steps.",
                    "系统安装器已打开，请完成确认步骤。",
                    "系統安裝器已開啟，請完成確認步驟。",
                )
                .into(),
                Button::new("update-panel-installer")
                    .small()
                    .outline()
                    .disabled(true)
                    .label(locale::text(
                        "Installer open",
                        "安装器已打开",
                        "安裝器已開啟",
                    ))
                    .into_any_element(),
            ),
            UpdateState::RestartRequired { .. } => (
                locale::text(
                    "Installed. Restart to run the new version.",
                    "已安装，重启后运行新版本。",
                    "已安裝，重新啟動後執行新版本。",
                )
                .into(),
                Button::new("update-panel-restart")
                    .small()
                    .primary()
                    .label(locale::text("Restart now", "立即重启", "立即重新啟動"))
                    .on_click(cx.listener(|this, _, _, cx| this.restart_after_update(cx)))
                    .into_any_element(),
            ),
            UpdateState::Unsupported { release, reason } => {
                let notes_url = release.notes_url.to_string();
                (
                    reason.clone().into(),
                    Button::new("update-panel-release")
                        .small()
                        .outline()
                        .label(locale::text("Open release", "打开发行版", "開啟發行版"))
                        .on_click(move |_, _, _| {
                            let _ = open_external_url(&notes_url);
                        })
                        .into_any_element(),
                )
            }
            UpdateState::Error { failure, release } => {
                let verification_unavailable =
                    failure.code == "app_update_verification_key_unavailable";
                let retry_download = release.is_some();
                let description: SharedString = if verification_unavailable {
                    locale::text(
                        "This build does not include the release verification key, so update checks are unavailable.",
                        "当前构建未包含发行验签密钥，因此无法检查更新。",
                        "目前建置未包含發行驗簽金鑰，因此無法檢查更新。",
                    )
                    .into()
                } else {
                    format!("{}: {}", failure.code, failure.message).into()
                };
                let control = if verification_unavailable {
                    Button::new("update-panel-unavailable")
                        .small()
                        .outline()
                        .disabled(true)
                        .label(locale::text("Unavailable", "不可用", "不可用"))
                        .into_any_element()
                } else {
                    Button::new("update-panel-retry")
                        .small()
                        .outline()
                        .label(locale::text("Retry", "重试", "重試"))
                        .on_click(cx.listener(move |this, _, _, cx| {
                            if retry_download {
                                this.request_update_download(cx);
                            } else {
                                this.request_update_check(cx);
                            }
                        }))
                        .into_any_element()
                };
                (description, control)
            }
        };

        let mut body = v_flex().w_full().min_w_0().gap_3();
        if let Some(release) = release.as_ref() {
            body = body.child(
                v_flex()
                    .w_full()
                    .min_w_0()
                    .gap_1()
                    .child(
                        div()
                            .text_sm()
                            .font_medium()
                            .child(format!("Vibex {}", release.version)),
                    )
                    .child(
                        div()
                            .text_xs()
                            .whitespace_normal()
                            .text_color(muted_foreground)
                            .child(description),
                    )
                    .child(control),
            );
        }

        v_flex()
            .id("update-panel")
            .w_80()
            .min_w_0()
            .rounded(cx.theme().radius)
            .border_1()
            .border_color(cx.theme().border.opacity(0.70))
            .bg(cx.theme().popover)
            .text_color(cx.theme().popover_foreground)
            .shadow_lg()
            .p_3()
            .gap_3()
            .child(
                h_flex()
                    .w_full()
                    .min_w_0()
                    .items_center()
                    .justify_between()
                    .gap_2()
                    .child(div().text_sm().font_medium().child(locale::text(
                        "Software update",
                        "软件更新",
                        "軟體更新",
                    )))
                    .child(
                        Button::new("close-update-panel")
                            .small()
                            .ghost()
                            .compact()
                            .size(px(24.0))
                            .px_0()
                            .tooltip(locale::text("Close", "关闭", "關閉"))
                            .icon(IconName::Close)
                            .on_click(
                                cx.listener(|this, _, _, cx| this.set_update_panel_open(false, cx)),
                            ),
                    ),
            )
            .child(body)
            .child(
                h_flex().w_full().min_w_0().justify_end().child(
                    Button::new("open-update-notes")
                        .small()
                        .ghost()
                        .icon(IconName::BookOpen)
                        .label(locale::text("Release notes", "更新日志", "更新日誌"))
                        .on_click(cx.listener(|this, _, window, cx| {
                            this.set_update_panel_open(false, cx);
                            this.open_update_settings(window, cx);
                        })),
                ),
            )
            .into_any_element()
    }

    fn render_title_bar(&mut self, window: &mut Window, cx: &mut Context<Self>) -> AnyElement {
        let strings = self.strings();
        let selected_session = self.selected_session().cloned();
        let show_session_context = title_bar_session_context_visible(
            &self.ui_state.workbench.active_tab,
            self.new_session_open,
            self.settings_open,
            selected_session.is_some(),
        );
        let management_open = self.ui_state.workbench.active_tab == "management";
        let usage_open = self.ui_state.workbench.active_tab == "usage";
        let usage_loading = usage_open && self.usage_refresh_in_flight;
        let session_title = selected_session
            .as_ref()
            .filter(|_| show_session_context)
            .map(|session| session.title.clone())
            .unwrap_or_else(|| strings.agent_select_session.to_string());
        let title_session_menu = selected_session
            .as_ref()
            .filter(|_| show_session_context)
            .map(|session| {
                let entity = cx.weak_entity();
                let session_id = session.id.clone();
                let session_title = truncate_title_bar_session_menu_title(&session.title);
                let pinned = self.sidebar_state.pinned_ids.contains(session.id.as_str());
                let deletion_pending = self
                    .pending_session_deletion_ids
                    .contains(session.id.as_str());
                div()
                    .id("title-session-actions")
                    .on_mouse_down(MouseButton::Left, |_, _, cx| cx.stop_propagation())
                    .child(
                        Button::new("title-session-menu")
                            .small()
                            .ghost()
                            .compact()
                            .size(px(24.0))
                            .px_0()
                            .tooltip(locale::text("Session actions", "会话操作", "會話操作"))
                            .icon(IconName::Ellipsis)
                            .dropdown_menu(move |menu, window, menu_cx| {
                                Self::build_title_session_menu(
                                    menu,
                                    session_id.clone(),
                                    session_title.clone(),
                                    pinned,
                                    deletion_pending,
                                    strings,
                                    entity.clone(),
                                    window,
                                    menu_cx,
                                )
                            })
                            .anchor(Anchor::TopRight),
                    )
                    .into_any_element()
            });
        let sidebar_selected = if self.last_visibility.sidebar_docked {
            self.ui_state.workbench.sidebar_visible
        } else {
            self.sidebar_overlay_open
        };
        let sidebar_inline_open =
            self.last_visibility.sidebar_docked && self.ui_state.workbench.sidebar_visible;
        let sidebar_width = if sidebar_inline_open {
            self.sidebar_panel_width(self.last_visibility)
        } else {
            TITLE_BAR_COLLAPSED_SIDEBAR_WIDTH
        };
        // The closing hairline spans the workbench only: while the docked
        // sidebar is open its surface runs up through the band, so no line
        // separates the rail from the chrome.
        let hairline_left = if sidebar_inline_open {
            sidebar_width
        } else {
            0.0
        };
        let can_go_back = self.navigation_history.can_go_back();
        let can_go_forward = self.navigation_history.can_go_forward();
        let sidebar_tooltip = if sidebar_selected {
            strings.collapse_sidebar
        } else {
            strings.expand_sidebar
        };
        // One glyph in both states: the rail beside it already shows whether the
        // sidebar is open, and the tooltip names the action.
        let sidebar_toggle_icon = Icon::default().path("icons/vibex/sidebar-left.svg");
        let is_linux = cfg!(target_os = "linux");
        let is_macos = cfg!(target_os = "macos");
        let is_web = cfg!(target_family = "wasm");
        let is_client_decorated = matches!(window.window_decorations(), Decorations::Client { .. });
        let drag_state = window.use_state(cx, |_, _| WorkbenchTitleBarState { should_move: false });
        let wide_window_controls = self.last_visibility.layout.viewport_width >= 760;
        // Which caption buttons exist is a platform decision: macOS and a
        // server-decorated Linux window draw none, Windows keeps its
        // system-backed trio, and a client-decorated Linux window follows the
        // desktop's own layout.
        let window_controls = window_control_layout(window);
        let window_controls_maximized = window.is_maximized();
        let show_update_entry =
            self.update_surfaces_enabled() && self.update_snapshot.state.should_show_update_entry();
        let update_version = self
            .update_snapshot
            .state
            .release()
            .map(|release| release.version.to_string())
            .unwrap_or_default();
        let update_entry = show_update_entry.then(|| self.render_update_entry(&update_version, cx));

        // The bar floats above the shell instead of taking a row of it: every
        // column keeps its full height underneath, and each one that must not
        // underlap the chrome reserves `TITLE_BAR_HEIGHT` at its top. Only the
        // workbench end of the strip carries a surface and the hairline that
        // closes it; the sidebar end stays transparent so the rail's own tone
        // reaches the window edge.
        div()
            .id("title-bar")
            .absolute()
            .top_0()
            .left_0()
            .right_0()
            .flex()
            .flex_row()
            .items_center()
            .h(px(TITLE_BAR_HEIGHT))
            .overflow_hidden()
            .text_color(cx.theme().foreground)
            .when(is_linux, |this| {
                this.on_double_click(|_, window, _| window.zoom_window())
            })
            .when(is_macos, |this| {
                this.on_double_click(|_, window, _| window.titlebar_double_click())
            })
            .on_mouse_down_out(window.listener_for(&drag_state, |state, _, _, _| {
                state.should_move = false;
            }))
            .on_mouse_down(
                MouseButton::Left,
                window.listener_for(&drag_state, |state, _, _, _| {
                    state.should_move = true;
                }),
            )
            .on_mouse_up(
                MouseButton::Left,
                window.listener_for(&drag_state, |state, _, _, _| {
                    state.should_move = false;
                }),
            )
            .on_mouse_move(window.listener_for(&drag_state, |state, _, window, _| {
                if state.should_move {
                    state.should_move = false;
                    window.start_window_move();
                }
            }))
            .when(!window_controls.left.is_empty(), |this| {
                this.child(workbench_window_controls(
                    WindowControlSide::Left,
                    &window_controls.left,
                    wide_window_controls,
                    window_controls_maximized,
                    cx,
                ))
            })
            .child(
                h_flex()
                    .min_w_0()
                    .h_full()
                    .flex_1()
                    .items_center()
                    .when(!is_web, |this| {
                        this.window_control_area(WindowControlArea::Drag).when(
                            is_linux && is_client_decorated,
                            |this| {
                                this.on_mouse_down(MouseButton::Right, |event, window, _| {
                                    window.show_window_menu(event.position)
                                })
                            },
                        )
                    })
                    .child(
                        h_flex()
                            .id("title-bar-sidebar")
                            .h_full()
                            .w(px(sidebar_width))
                            .flex_none()
                            .items_center()
                            // The cluster sits on the chrome instead of owning a
                            // surface: opening the sidebar lets the rail's tone
                            // and seam run up behind these controls, and a
                            // collapsed rail leaves the corner plain.
                            .px(px(TITLE_BAR_CLUSTER_PAD))
                            .when(cfg!(target_os = "macos"), |this| this.pl(px(80.0)))
                            .child(
                                h_flex()
                                    .items_center()
                                    .on_mouse_down(MouseButton::Left, |_, _, cx| {
                                        cx.stop_propagation()
                                    })
                                    .child(
                                        div()
                                            .id("toggle-sidebar-hover-trigger")
                                            .on_hover(cx.listener(|this, hovered, _, cx| {
                                                this.handle_sidebar_hover(*hovered, cx)
                                            }))
                                            .child(
                                                Button::new("toggle-sidebar")
                                                    .small()
                                                    .ghost()
                                                    .compact()
                                                    .size(px(TITLE_BAR_CONTROL_SIZE))
                                                    .px_0()
                                                    .tooltip(sidebar_tooltip)
                                                    .child(
                                                        sidebar_toggle_icon
                                                            .size(px(TITLE_BAR_CONTROL_ICON_SIZE)),
                                                    )
                                                    .on_click(cx.listener(|this, _, _, cx| {
                                                        this.toggle_sidebar(cx)
                                                    })),
                                            ),
                                    )
                                    .child(
                                        h_flex()
                                            .items_center()
                                            .gap(px(TITLE_BAR_CONTROL_GAP))
                                            .ml(px(TITLE_BAR_GROUP_GAP))
                                            .child(
                                                Button::new("navigate-back")
                                                    .small()
                                                    .ghost()
                                                    .compact()
                                                    .size(px(TITLE_BAR_CONTROL_SIZE))
                                                    .px_0()
                                                    .tooltip(strings.go_back)
                                                    .disabled(!can_go_back)
                                                    .child(
                                                        Icon::new(IconName::ArrowLeft)
                                                            .size(px(TITLE_BAR_CONTROL_ICON_SIZE)),
                                                    )
                                                    .on_click(cx.listener(
                                                        |this, _, window, cx| {
                                                            this.navigate_back(window, cx);
                                                        },
                                                    )),
                                            )
                                            .child(
                                                Button::new("navigate-forward")
                                                    .small()
                                                    .ghost()
                                                    .compact()
                                                    .size(px(TITLE_BAR_CONTROL_SIZE))
                                                    .px_0()
                                                    .tooltip(strings.go_forward)
                                                    .disabled(!can_go_forward)
                                                    .child(
                                                        Icon::new(IconName::ArrowRight)
                                                            .size(px(TITLE_BAR_CONTROL_ICON_SIZE)),
                                                    )
                                                    .on_click(cx.listener(
                                                        |this, _, window, cx| {
                                                            this.navigate_forward(window, cx);
                                                        },
                                                    )),
                                            ),
                                    ),
                            ),
                    )
                    .child(
                        v_flex()
                            .id("title-bar-main")
                            .h_full()
                            .min_w_0()
                            .flex_1()
                            .justify_center()
                            .gap_0()
                            .py_1()
                            .px_3()
                            // The workbench end of the strip owns its surface,
                            // so panels below never show through the chrome.
                            .bg(cx.theme().background)
                            .text_color(cx.theme().foreground)
                            .when(management_open, |this| {
                                this.child(
                                    h_flex()
                                        .min_w_0()
                                        .items_center()
                                        .gap_2()
                                        .child(
                                            h_flex()
                                                .size(px(24.0))
                                                .flex_none()
                                                .items_center()
                                                .justify_center()
                                                .rounded(px(6.0))
                                                .bg(cx.theme().primary.opacity(0.08))
                                                .child(
                                                    Icon::new(IconName::Settings2)
                                                        .size(px(14.0))
                                                        .text_color(cx.theme().primary),
                                                ),
                                        )
                                        .child(
                                            div()
                                                .min_w_0()
                                                .truncate()
                                                .text_sm()
                                                .font_medium()
                                                .child(strings.sidebar_providers),
                                        ),
                                )
                            })
                            .when(usage_open, |this| {
                                this.child(
                                    h_flex()
                                        .min_w_0()
                                        .w_full()
                                        .items_center()
                                        .justify_between()
                                        .gap_2()
                                        .child(
                                            h_flex()
                                                .min_w_0()
                                                .items_center()
                                                .gap_2()
                                                .child(
                                                    h_flex()
                                                        .size(px(24.0))
                                                        .flex_none()
                                                        .items_center()
                                                        .justify_center()
                                                        .rounded(px(6.0))
                                                        .bg(cx.theme().primary.opacity(0.08))
                                                        .child(
                                                            Icon::default()
                                                                .path("icons/vibex/activity.svg")
                                                                .size(px(15.0))
                                                                .text_color(cx.theme().primary),
                                                        ),
                                                )
                                                .child(
                                                    div()
                                                        .min_w_0()
                                                        .truncate()
                                                        .text_sm()
                                                        .font_semibold()
                                                        .child(locale::text(
                                                            "Usage Statistics",
                                                            "用量统计",
                                                            "用量統計",
                                                        )),
                                                ),
                                        )
                                        .child(
                                            div()
                                                .id("title-usage-refresh")
                                                .on_mouse_down(MouseButton::Left, |_, _, cx| {
                                                    cx.stop_propagation()
                                                })
                                                .child(
                                                    Button::new("usage-refresh")
                                                        .small()
                                                        .ghost()
                                                        .compact()
                                                        .size(px(28.0))
                                                        .px_0()
                                                        .loading(usage_loading)
                                                        .tooltip(locale::text(
                                                            "Refresh",
                                                            "刷新",
                                                            "重新整理",
                                                        ))
                                                        .child(
                                                            Icon::default()
                                                                .path("icons/vibex/rotate-ccw.svg")
                                                                .size(px(15.0)),
                                                        )
                                                        .on_click(cx.listener(|this, _, _, cx| {
                                                            this.usage_view
                                                                .update(cx, |usage, cx| {
                                                                    usage.refresh(cx)
                                                                });
                                                        })),
                                                ),
                                        ),
                                )
                            })
                            .when(show_session_context, |this| {
                                this.child(
                                    h_flex()
                                        .id("title-session-heading")
                                        .w_auto()
                                        .max_w(px(TITLE_BAR_SESSION_TITLE_MAX_WIDTH + 32.0))
                                        .flex_none()
                                        .items_center()
                                        .gap(px(1.0))
                                        .child(
                                            div()
                                                .id("title-session-title")
                                                .min_w_0()
                                                .max_w(px(TITLE_BAR_SESSION_TITLE_MAX_WIDTH))
                                                .truncate()
                                                .text_sm()
                                                .font_medium()
                                                .child(session_title),
                                        )
                                        .when_some(title_session_menu, |this, menu| {
                                            this.child(menu)
                                        }),
                                )
                            }),
                    )
                    .child(
                        h_flex()
                            .h_full()
                            .flex_none()
                            .items_center()
                            .gap_2()
                            .px_2()
                            // Carries the strip's surface to the window edge so
                            // the rail beneath cannot bleed into the band.
                            .bg(cx.theme().background)
                            .on_mouse_down(MouseButton::Left, |_, _, cx| cx.stop_propagation())
                            .when_some(update_entry, |this, entry| this.child(entry))
                            .child(
                                Button::new("open-command-palette")
                                    .small()
                                    .ghost()
                                    .compact()
                                    .size(px(32.0))
                                    .px_0()
                                    .tooltip(strings.command_palette_open)
                                    .child(Icon::new(IconName::Search).size(px(18.0)))
                                    .on_click(cx.listener(|this, _, window, cx| {
                                        this.toggle_command_palette(window, cx)
                                    })),
                            )
                            .child(
                                div()
                                    .id("runtime-manager-hover")
                                    .child(self.render_runtime_manager_trigger(cx)),
                            )
                            .child(
                                div()
                                    .id("pair-mobile-hover")
                                    .on_hover(cx.listener(|this, hovered: &bool, _, cx| {
                                        if this.pair_button_hovered != *hovered {
                                            this.pair_button_hovered = *hovered;
                                            cx.notify();
                                        }
                                    }))
                                    .child(
                                        Button::new("pair-mobile")
                                            .small()
                                            .ghost()
                                            .compact()
                                            .size(px(32.0))
                                            .px_0()
                                            .tooltip(strings.pair_mobile)
                                            .child(mobile_pair_icon(self.pair_button_hovered, cx))
                                            .on_click(cx.listener(|this, _, window, cx| {
                                                this.open_pairing(window, cx)
                                            })),
                                    ),
                            )
                            .child(
                                Button::new("open-settings")
                                    .small()
                                    .ghost()
                                    .compact()
                                    .size(px(32.0))
                                    .px_0()
                                    .tooltip(strings.open_settings)
                                    .child(Icon::new(IconName::Settings).size(px(18.0)))
                                    .on_click(cx.listener(|this, _, window, cx| {
                                        this.toggle_settings(window, cx)
                                    })),
                            ),
                    ),
            )
            .when(!window_controls.right.is_empty(), |this| {
                this.child(workbench_window_controls(
                    WindowControlSide::Right,
                    &window_controls.right,
                    wide_window_controls,
                    window_controls_maximized,
                    cx,
                ))
            })
            // The chrome's closing hairline, a child rather than a border so it
            // can start past the sidebar instead of crossing it. It paints last,
            // over the segments it closes.
            .child(
                div()
                    .absolute()
                    .bottom_0()
                    .left(px(hairline_left))
                    .right_0()
                    .h(px(1.0))
                    .bg(cx.theme().border),
            )
            .into_any_element()
    }

    #[allow(clippy::too_many_arguments)]
    fn build_title_session_menu(
        menu: PopupMenu,
        session_id: VibexSessionId,
        session_title: String,
        pinned: bool,
        deletion_pending: bool,
        strings: &'static Strings,
        entity: WeakEntity<Self>,
        window: &mut Window,
        cx: &mut Context<PopupMenu>,
    ) -> PopupMenu {
        let menu_entity = cx.entity();
        let _ = entity.update(cx, |this, cx| this.begin_sidebar_menu_hover(cx));
        Self::hold_sidebar_hover_preview_for_menu(&menu_entity, &entity, window, cx);
        let rename_entity = entity.clone();
        let pin_entity = entity.clone();
        let delete_entity = entity;
        let rename_id = session_id.clone();
        let pin_id = session_id.clone();
        let delete_id = session_id;
        let delete_label = strings.sidebar_delete;
        let pin_label = if pinned {
            strings.sidebar_unpin
        } else {
            strings.sidebar_pin
        };

        menu.min_w(px(TITLE_BAR_SESSION_MENU_WIDTH))
            .max_w(px(TITLE_BAR_SESSION_MENU_WIDTH))
            .item(PopupMenuItem::label(session_title))
            .separator()
            .item(
                PopupMenuItem::new(strings.sidebar_rename)
                    .icon(sidebar_icon("icons/vibex/pencil.svg"))
                    .on_click(move |_, window, cx| {
                        let _ = rename_entity.update(cx, |this, cx| {
                            this.begin_sidebar_rename(rename_id.clone(), window, cx)
                        });
                    }),
            )
            .item(
                PopupMenuItem::new(pin_label)
                    .icon(sidebar_icon("icons/vibex/pin.svg"))
                    .on_click(move |_, _, cx| {
                        let _ =
                            pin_entity.update(cx, |this, cx| this.toggle_session_pin(&pin_id, cx));
                    }),
            )
            .item(
                PopupMenuItem::new(delete_label)
                    .icon(sidebar_icon("icons/vibex/trash-2.svg"))
                    .disabled(deletion_pending)
                    .on_click(move |_, window, cx| {
                        let _ = delete_entity.update(cx, |this, cx| {
                            this.confirm_delete_session(delete_id.clone(), window, cx)
                        });
                    }),
            )
    }

    fn render_agent_sidebar(&mut self, cx: &mut Context<Self>) -> AnyElement {
        let strings = self.strings();
        let groups = self.sidebar_workspace_groups("");
        let reorder_enabled = !self.sidebar_batch_mode;
        // "All selected" only means something while the batch bar is up. It
        // used to allocate a `String` per session on every frame, visible or
        // not; the count comparison needs no allocation at all.
        let all_sessions_selected = self.sidebar_batch_mode
            && !self.sessions.is_empty()
            && self.sessions.iter().all(|session| {
                self.sidebar_state
                    .selected_ids
                    .contains(session.id.as_str())
            });
        let selected_workspace_id = self
            .ui_state
            .workbench
            .selected_workspace_id
            .clone()
            .or_else(|| {
                self.selected_session()
                    .map(|session| session.workspace_id.as_str().to_string())
            });
        let group_elements = self.render_sidebar_root_children(
            &groups,
            None,
            selected_workspace_id,
            reorder_enabled,
            strings,
            0,
            cx,
        );
        let selected_count = self.sidebar_state.selected_ids.len();
        let group_creation = self.sidebar_group_creation_candidates();
        let total_count = self.sessions.len();
        let selected_count_label =
            sidebar_selected_count_label(self.resolved_locale(), selected_count, total_count);
        let collapse_label = if self.collapsed_project_restore.is_some() {
            strings.sidebar_restore
        } else {
            strings.sidebar_collapse_all
        };
        let management_selected = self.ui_state.workbench.active_tab == "management";
        let usage_selected = self.ui_state.workbench.active_tab == "usage";
        let root_drop_active =
            self.sidebar_organization_root_drop_active(&SidebarOrganizationScope::Root);
        // Only a live drag may light the sidebar up: the flag outlives a drag
        // that ended somewhere the sidebar never heard about.
        let session_group_tab_removal_active =
            cx.has_active_drag() && self.session_group_tab_removal_active;
        let root_menu_entity = cx.weak_entity();
        let toolbar_more_entity = cx.weak_entity();
        let toolbar_more_state = SidebarToolbarMoreMenuState {
            strings,
            hierarchy_mode: self.ui_state.sidebar.hierarchy_mode,
            batch_mode: self.sidebar_batch_mode,
            sessions_empty: self.sessions.is_empty(),
            import_disabled: self.agent_action_pending || self.sidebar_picker_task.is_some(),
        };

        v_flex()
            .id("agent-sidebar")
            .size_full()
            .min_w_0()
            .overflow_hidden()
            .bg(cx.theme().sidebar)
            .text_color(cx.theme().sidebar_foreground)
            .on_mouse_down(
                MouseButton::Left,
                cx.listener(|this, _, _, cx| this.finish_sidebar_rename_on_blur(cx)),
            )
            .child(
                v_flex()
                    .flex_none()
                    .gap_1()
                    .px_4()
                    .pt_3()
                    .child(
                        Button::new("sidebar-new-session")
                            .small()
                            .ghost()
                            .w_full()
                            .h(px(32.0))
                            .justify_start()
                            .rounded(gpui_component::button::ButtonRounded::Size(px(8.0)))
                            .icon(Icon::new(IconName::Plus).mr_2())
                            .label(strings.sidebar_new_session)
                            .child(div().flex_1())
                            .on_click(cx.listener(|this, _, window, cx| {
                                this.open_new_session(None, window, cx)
                            })),
                    )
                    .child(
                        Button::new("sidebar-config-center")
                            .small()
                            .ghost()
                            .w_full()
                            .h(px(32.0))
                            .justify_start()
                            .rounded(gpui_component::button::ButtonRounded::Size(px(8.0)))
                            .selected(management_selected)
                            .icon(Icon::new(IconName::Settings).mr_2())
                            .label(strings.sidebar_providers)
                            .child(div().flex_1())
                            .on_click(cx.listener(|this, _, _, cx| this.open_management(cx))),
                    )
                    .child(
                        Button::new("sidebar-usage-statistics")
                            .small()
                            .ghost()
                            .w_full()
                            .h(px(32.0))
                            .justify_start()
                            .rounded(gpui_component::button::ButtonRounded::Size(px(8.0)))
                            .selected(usage_selected)
                            .icon(
                                Icon::default()
                                    .path("icons/vibex/activity.svg")
                                    .size(px(16.0))
                                    .mr_2(),
                            )
                            .label(locale::text("Usage Statistics", "用量统计", "用量統計"))
                            .child(div().flex_1())
                            .on_click(cx.listener(|this, _, _, cx| this.open_usage(None, cx))),
                    ),
            )
            .child(
                div()
                    .mx_4()
                    .mt_3()
                    .h(px(1.0))
                    .flex_none()
                    .bg(cx.theme().sidebar_border.opacity(0.70)),
            )
            .child(
                h_flex()
                    .min_h(px(24.0))
                    .flex_none()
                    .items_center()
                    .justify_between()
                    .px_4()
                    .pt_3()
                    .child(
                        div()
                            .text_sm()
                            .font_medium()
                            .text_color(cx.theme().sidebar_foreground.opacity(0.52))
                            .child(strings.sidebar_projects),
                    )
                    .child(
                        h_flex()
                            .items_center()
                            .gap_1()
                            .child(
                                Button::new("sidebar-toolbar-more")
                                    .small()
                                    .ghost()
                                    .compact()
                                    .w(px(28.0))
                                    .h(px(28.0))
                                    .icon(IconName::Ellipsis)
                                    .tooltip(locale::text("More", "更多", "更多"))
                                    .dropdown_menu(move |menu, window, cx| {
                                        Self::build_sidebar_toolbar_more_menu(
                                            menu,
                                            toolbar_more_entity.clone(),
                                            toolbar_more_state,
                                            window,
                                            cx,
                                        )
                                    })
                                    .anchor(gpui::Anchor::TopRight),
                            )
                            .child(
                                Button::new("sidebar-collapse-all")
                                    .small()
                                    .ghost()
                                    .compact()
                                    .w(px(28.0))
                                    .h(px(28.0))
                                    .icon(if self.collapsed_project_restore.is_some() {
                                        sidebar_icon("icons/vibex/chevrons-left-right.svg")
                                    } else {
                                        sidebar_icon("icons/vibex/chevrons-right-left.svg")
                                    })
                                    .tooltip(collapse_label)
                                    .disabled(self.workspaces.is_empty())
                                    .on_click(cx.listener(|this, _, _, cx| {
                                        this.toggle_collapse_all_projects(cx)
                                    })),
                            )
                            .child(
                                Button::new("sidebar-locate-session")
                                    .small()
                                    .ghost()
                                    .compact()
                                    .w(px(28.0))
                                    .h(px(28.0))
                                    .icon(sidebar_icon("icons/vibex/crosshair.svg"))
                                    .tooltip(locale::text(
                                        "Locate Current Session",
                                        "定位当前会话",
                                        "定位目前工作階段",
                                    ))
                                    .disabled(self.selected_session_id.is_none())
                                    .on_click(cx.listener(|this, _, window, cx| {
                                        this.locate_selected_session(window, cx)
                                    })),
                            )
                            .child(
                                Button::new("sidebar-new-project")
                                    .small()
                                    .ghost()
                                    .compact()
                                    .w(px(28.0))
                                    .h(px(28.0))
                                    .icon(IconName::Plus)
                                    .tooltip(strings.sidebar_new_project)
                                    .disabled(
                                        self.agent_action_pending
                                            || self.sidebar_picker_task.is_some(),
                                    )
                                    .on_click(cx.listener(|this, _, window, cx| {
                                        this.open_new_project_session(window, cx)
                                    })),
                            ),
                    ),
            )
            .when(self.sidebar_batch_mode, |this| {
                this.child(
                    v_flex()
                        .flex_none()
                        .gap_2()
                        .mx_4()
                        .mt_2()
                        .rounded(px(12.0))
                        .border_1()
                        .border_color(cx.theme().sidebar_border.opacity(0.70))
                        .bg(cx.theme().background.opacity(0.35))
                        .p_2()
                        .child(
                            h_flex()
                                .items_center()
                                .justify_between()
                                .gap_2()
                                .text_xs()
                                .font_medium()
                                .text_color(cx.theme().sidebar_foreground.opacity(0.60))
                                .child(selected_count_label.clone())
                                .child(
                                    h_flex()
                                        .gap_1()
                                        .flex_none()
                                        .child(
                                            Button::new("sidebar-clear-batch")
                                                .xsmall()
                                                .ghost()
                                                .compact()
                                                .label(strings.sidebar_clear)
                                                .disabled(selected_count == 0)
                                                .on_click(cx.listener(|this, _, _, cx| {
                                                    this.sidebar_state.clear_selection();
                                                    cx.notify();
                                                })),
                                        )
                                        .child(
                                            Button::new("sidebar-exit-batch")
                                                .xsmall()
                                                .ghost()
                                                .compact()
                                                .icon(IconName::Close)
                                                .tooltip(strings.sidebar_exit_batch)
                                                .on_click(cx.listener(|this, _, _, cx| {
                                                    this.toggle_sidebar_batch_mode(cx)
                                                })),
                                        ),
                                ),
                        )
                        .child(
                            Button::new("sidebar-create-group")
                                .small()
                                .secondary()
                                .w_full()
                                .justify_center()
                                .icon(sidebar_icon("icons/vibex/layers.svg"))
                                .label(strings.sidebar_group_new_from_selection)
                                .disabled(group_creation.is_none())
                                .tooltip(strings.sidebar_group_other_worktree)
                                .on_click(cx.listener(|this, _, window, cx| {
                                    this.create_session_group_from_selection(window, cx)
                                })),
                        )
                        .child(
                            h_flex()
                                .gap(px(6.0))
                                .child(
                                    Button::new("sidebar-select-all")
                                        .small()
                                        .secondary()
                                        .flex_1()
                                        .justify_center()
                                        .label(if all_sessions_selected {
                                            strings.sidebar_clear
                                        } else {
                                            strings.sidebar_select_all
                                        })
                                        .disabled(self.sessions.is_empty())
                                        .on_click(cx.listener(|this, _, _, cx| {
                                            this.toggle_all_batch_sessions(cx)
                                        })),
                                )
                                .child(
                                    Button::new("sidebar-delete-selected")
                                        .small()
                                        .danger()
                                        .flex_1()
                                        .justify_center()
                                        .icon(sidebar_icon("icons/vibex/trash-2.svg"))
                                        .label(strings.sidebar_delete_selected)
                                        .disabled(selected_count == 0)
                                        .on_click(cx.listener(|this, _, window, cx| {
                                            this.confirm_delete_selected_sessions(window, cx)
                                        })),
                                ),
                        ),
                )
            })
            .child(
                div()
                    .id("sidebar-session-list-container")
                    .flex_1()
                    .min_h_0()
                    .relative()
                    .child(
                        v_flex()
                            .id("sidebar-session-list")
                            .size_full()
                            // Keep the boundary from the previous project's last
                            // worktree/session row to the next project row distinct
                            // from the tighter spacing inside one project.
                            .gap(px(SIDEBAR_PROJECT_GROUP_GAP))
                            .track_scroll(&self.sidebar_scroll)
                            .overflow_y_scroll()
                            .bg(if root_drop_active {
                                cx.theme().sidebar_accent.opacity(0.20)
                            } else if session_group_tab_removal_active {
                                cx.theme().tokens.drop_target.into()
                            } else {
                                cx.theme().transparent
                            })
                            .on_drop(cx.listener(|this, drag: &SidebarProjectDrag, _, cx| {
                                this.finish_sidebar_project_drag(&drag.project_id, cx);
                                cx.stop_propagation();
                            }))
                            .on_drop(cx.listener(|this, drag: &SidebarFolderDrag, _, cx| {
                                this.finish_sidebar_folder_drag(&drag.folder_id, cx);
                                cx.stop_propagation();
                            }))
                            .on_drop(cx.listener(|this, drag: &SidebarSessionDrag, _, cx| {
                                this.finish_sidebar_session_drag(
                                    &drag.workspace_id,
                                    &drag.session_id,
                                    None,
                                    cx,
                                );
                                cx.stop_propagation();
                            }))
                            .on_drop(cx.listener(|this, drag: &SidebarWorkspaceDrag, _, cx| {
                                this.finish_sidebar_workspace_drag(
                                    &drag.project_id,
                                    &drag.workspace_id,
                                    cx,
                                );
                                cx.stop_propagation();
                            }))
                            // A group pane's tab dragged onto the sidebar leaves
                            // the group: the sidebar is the surface the group's
                            // members also live on, so dragging a tab out of the
                            // workspace and dropping it here is the gesture that
                            // takes the session back out.
                            .on_drag_move(cx.listener(
                                |this, event: &DragMoveEvent<SessionGroupTabDrag>, _, cx| {
                                    let inside = event.bounds.contains(&event.event.position);
                                    if this.session_group_tab_removal_active != inside {
                                        this.session_group_tab_removal_active = inside;
                                        cx.notify();
                                    }
                                },
                            ))
                            .on_drop(cx.listener(|this, drag: &SessionGroupTabDrag, _, cx| {
                                this.session_group_tab_removal_active = false;
                                this.remove_session_from_group_from_menu(
                                    &drag.group_id,
                                    &drag.session_id,
                                    cx,
                                );
                                cx.stop_propagation();
                            }))
                            .px_4()
                            .py_3()
                            .when(group_elements.is_empty(), |this| {
                                this.child(
                                    solid_empty_border(
                                        EmptyState::new()
                                            .flex_none()
                                            .items_start()
                                            .text_left()
                                            .rounded(px(8.0))
                                            .border_1()
                                            .border_color(cx.theme().sidebar_border.opacity(0.70))
                                            .bg(cx.theme().background.opacity(0.30))
                                            .p_3(),
                                    )
                                    .header(
                                        EmptyHeader::new().items_start().max_w_full().description(
                                            EmptyDescription::new()
                                                .text_color(
                                                    cx.theme().sidebar_foreground.opacity(0.55),
                                                )
                                                .child(strings.sidebar_no_matching_sessions),
                                        ),
                                    ),
                                )
                            })
                            .children(group_elements)
                            // Keep root-only drops and the root context menu on a
                            // sibling hitbox instead of an ancestor of every row.
                            .child(
                                div()
                                    .id("sidebar-root-drop-target")
                                    .w_full()
                                    .flex_1()
                                    .min_h(px(24.0))
                                    .rounded(px(8.0))
                                    .bg(if root_drop_active {
                                        cx.theme().sidebar_accent.opacity(0.20)
                                    } else {
                                        cx.theme().transparent
                                    })
                                    .on_drag_move(cx.listener(
                                        |this, event: &DragMoveEvent<SidebarProjectDrag>, _, cx| {
                                            if !event.bounds.contains(&event.event.position) {
                                                return;
                                            }
                                            let drag = event.drag(cx);
                                            this.set_sidebar_organization_root_drop_target(
                                                drag.project_ids
                                                    .iter()
                                                    .cloned()
                                                    .map(SidebarOrganizationItem::Project)
                                                    .collect(),
                                                SidebarOrganizationScope::Root,
                                                cx,
                                            );
                                        },
                                    ))
                                    .on_drag_move(cx.listener(
                                        |this, event: &DragMoveEvent<SidebarFolderDrag>, _, cx| {
                                            if !event.bounds.contains(&event.event.position) {
                                                return;
                                            }
                                            let drag = event.drag(cx);
                                            this.set_sidebar_organization_root_drop_target(
                                                vec![SidebarOrganizationItem::Folder(
                                                    drag.folder_id.clone(),
                                                )],
                                                SidebarOrganizationScope::Root,
                                                cx,
                                            );
                                        },
                                    ))
                                    .on_drag_move(cx.listener(
                                        |this, event: &DragMoveEvent<SidebarSessionDrag>, _, cx| {
                                            if !event.bounds.contains(&event.event.position) {
                                                return;
                                            }
                                            let drag = event.drag(cx);
                                            this.set_sidebar_organization_root_drop_target(
                                                drag.session_ids
                                                    .iter()
                                                    .cloned()
                                                    .map(SidebarOrganizationItem::Session)
                                                    .collect(),
                                                SidebarOrganizationScope::Root,
                                                cx,
                                            );
                                        },
                                    ))
                                    .context_menu(move |menu, window, cx| {
                                        Self::build_sidebar_root_menu(
                                            menu,
                                            root_menu_entity.clone(),
                                            window,
                                            cx,
                                        )
                                    }),
                            ),
                    )
                    // Keep the scrollbar outside the scrolling node. GPUI applies
                    // that node's offset to all of its children during prepaint.
                    .vertical_scrollbar(&self.sidebar_scroll),
            )
            .into_any_element()
    }

    fn build_sidebar_toolbar_more_menu(
        menu: PopupMenu,
        entity: WeakEntity<Self>,
        state: SidebarToolbarMoreMenuState,
        window: &mut Window,
        cx: &mut Context<PopupMenu>,
    ) -> PopupMenu {
        let menu_entity = cx.entity();
        let _ = entity.update(cx, |this, cx| this.begin_sidebar_menu_hover(cx));
        Self::hold_sidebar_hover_preview_for_menu(&menu_entity, &entity, window, cx);
        let new_folder_entity = entity.clone();
        let hierarchy_entity = entity.clone();
        let batch_entity = entity.clone();
        let import_entity = entity;
        let hierarchy_label = if state.hierarchy_mode == SidebarHierarchyMode::Detailed {
            locale::text("Switch to session view", "切换为会话视图", "切換為會話視圖")
        } else {
            locale::text(
                "Switch to workspace view",
                "切换为工作区视图",
                "切換為工作區視圖",
            )
        };

        menu.item(
            PopupMenuItem::new(locale::text("New Folder", "新建文件夹", "新建資料夾"))
                .icon(sidebar_icon("icons/vibex/folder-plus.svg"))
                .disabled(state.batch_mode)
                .on_click(move |_, window, cx| {
                    let _ = new_folder_entity.update(cx, |this, cx| {
                        this.create_sidebar_folder(None, None, None, window, cx)
                    });
                }),
        )
        .item(
            PopupMenuItem::new(hierarchy_label)
                .icon(IconName::Folder)
                .on_click(move |_, _, cx| {
                    let _ = hierarchy_entity
                        .update(cx, |this, cx| this.toggle_sidebar_hierarchy_mode(cx));
                }),
        )
        .item(
            PopupMenuItem::new(if state.batch_mode {
                state.strings.sidebar_exit_batch
            } else {
                state.strings.sidebar_batch
            })
            .icon(sidebar_icon("icons/vibex/list-checks.svg"))
            .checked(state.batch_mode)
            .disabled(!state.batch_mode && state.sessions_empty)
            .on_click(move |_, _, cx| {
                let _ = batch_entity.update(cx, |this, cx| this.toggle_sidebar_batch_mode(cx));
            }),
        )
        .separator()
        .item(
            PopupMenuItem::new(state.strings.sidebar_import_sessions)
                .icon(sidebar_icon("icons/vibex/import.svg"))
                .disabled(state.import_disabled)
                .on_click(move |_, window, cx| {
                    let _ = import_entity.update(cx, |this, cx| {
                        this.open_local_history_import_dialog(None, None, window, cx)
                    });
                }),
        )
    }

