/// How far past the visible edge a session run still builds rows, so a scroll
/// step never uncovers a row that has not been built yet.
const SIDEBAR_SESSION_RUN_OVERSCAN_PX: f32 = 480.0;
/// Rows a run lays out in flow rather than windowing. Below this the run costs
/// less to build outright than to place row by row.
const SIDEBAR_SESSION_RUN_FLOW_LIMIT: usize = 24;
/// The vertical pitch of one session row: the row plus the gap its container
/// inserts between it and the next row.
const SIDEBAR_SESSION_ROW_STRIDE: f32 = SIDEBAR_SESSION_ROW_HEIGHT + SIDEBAR_SESSION_CONTENT_GAP;

/// The session rows one [`SidebarSessionRun`] stands for.
///
/// The sidebar renders a cached projection behind an `Rc`, so a run can hold
/// that projection and resolve its own sessions while it lays them out instead
/// of copying any of them.
struct SidebarSessionRunSource {
    groups: Rc<Vec<SidebarProjectProjection>>,
    project_index: usize,
    /// `Some` when the rows belong to one worktree of the project.
    workspace_index: Option<usize>,
    /// Indices into the source slice, in display order.
    session_indices: Vec<usize>,
    project_scope_id: String,
    reorder_enabled: bool,
    show_worktree_identity: bool,
    strings: &'static Strings,
}

impl SidebarSessionRunSource {
    fn sessions(&self) -> &[AgentSession] {
        let group = &self.groups[self.project_index];
        match self.workspace_index {
            Some(index) => &group.workspaces[index].sessions,
            None => &group.compact_sessions,
        }
    }

    fn session(&self, row: usize) -> Option<&AgentSession> {
        let index = *self.session_indices.get(row)?;
        self.sessions().get(index)
    }

    /// Whether the session being renamed sits in this run. The rename row is a
    /// different height from a session row, so a run holding it lays out in flow
    /// where its measured height is always the real one.
    fn renames_a_row(&self, rename_target: Option<&str>) -> bool {
        let Some(rename_target) = rename_target else {
            return false;
        };
        let sessions = self.sessions();
        self.session_indices
            .iter()
            .any(|index| sessions[*index].id.as_str() == rename_target)
    }
}

/// One contiguous band of session rows inside a sidebar container.
///
/// Project, worktree, and folder containers are ordinary flex columns, so a
/// folder holding hundreds of sessions used to build, lay out, and paint every
/// one of its rows on every frame the sidebar redrew — the sidebar's per-frame
/// cost grew with the number of sessions it held, not with the number it
/// showed. A run keeps the height its rows occupy in the flow and builds only
/// the ones the sidebar's scroll container actually shows, placing each at its
/// own origin. It is the same shape `MarkdownVirtualFlow` uses inside the
/// timeline.
/// Builds one row of a [`SidebarSessionRun`] on demand.
///
/// Runs are built during layout and prepaint, after the view's render has
/// returned, so the builder may update the workbench to reach the row's current
/// state.
type SidebarSessionRowBuilder = Box<dyn Fn(usize, &mut Window, &mut App) -> AnyElement>;

struct SidebarSessionRun {
    /// Rows this run stands for, in display order.
    row_count: usize,
    /// Whether to window the rows; a short run lays out in flow instead.
    windowed: bool,
    /// The row holding the selected session, which is built even when it is
    /// outside the window: it carries the scroll anchor the workbench uses to
    /// locate the current session.
    selected_row: Option<usize>,
    /// Builds row `index` on demand.
    build_row: SidebarSessionRowBuilder,
}

impl SidebarSessionRun {
    /// The height the rows occupy, gaps included.
    fn flow_height(&self) -> f32 {
        if self.row_count == 0 {
            return 0.0;
        }
        self.row_count as f32 * SIDEBAR_SESSION_ROW_HEIGHT
            + (self.row_count - 1) as f32 * SIDEBAR_SESSION_CONTENT_GAP
    }

    /// Where row `index` starts, relative to the run's own origin.
    fn row_origin(&self, index: usize) -> f32 {
        index as f32 * SIDEBAR_SESSION_ROW_STRIDE
    }

    /// The rows the content mask can see, widened by
    /// [`SIDEBAR_SESSION_RUN_OVERSCAN_PX`].
    ///
    /// Rows are one fixed height, so the range is arithmetic rather than a
    /// scan: row `i` covers `[i * stride, i * stride + row_height]`, and both
    /// edges are divided by the same stride.
    fn visible_rows(&self, bounds: Bounds<Pixels>, viewport: Bounds<Pixels>) -> Range<usize> {
        if self.row_count == 0 {
            return 0..0;
        }
        let top =
            f32::from(viewport.top()) - SIDEBAR_SESSION_RUN_OVERSCAN_PX - f32::from(bounds.top());
        let bottom = f32::from(viewport.bottom()) + SIDEBAR_SESSION_RUN_OVERSCAN_PX
            - f32::from(bounds.top());
        let first = if top <= 0.0 {
            0
        } else {
            (((top - SIDEBAR_SESSION_ROW_HEIGHT) / SIDEBAR_SESSION_ROW_STRIDE)
                .ceil()
                .max(0.0) as usize)
                .min(self.row_count)
        };
        let end = if bottom < 0.0 {
            0
        } else {
            ((bottom / SIDEBAR_SESSION_ROW_STRIDE).floor().max(0.0) as usize + 1)
                .min(self.row_count)
        };
        first..end.max(first)
    }
}

/// The flow child a run reserves its height with, or the column a run that
/// lays out in flow holds its rows in.
struct SidebarSessionRunLayout {
    spacer: Option<AnyElement>,
    column: Option<AnyElement>,
    rows: Vec<AnyElement>,
}

impl IntoElement for SidebarSessionRun {
    type Element = Self;

    fn into_element(self) -> Self::Element {
        self
    }
}

impl Element for SidebarSessionRun {
    type RequestLayoutState = SidebarSessionRunLayout;
    type PrepaintState = ();

    fn id(&self) -> Option<ElementId> {
        None
    }

    fn source_location(&self) -> Option<&'static std::panic::Location<'static>> {
        None
    }

    fn request_layout(
        &mut self,
        _: Option<&GlobalElementId>,
        _: Option<&InspectorElementId>,
        window: &mut Window,
        cx: &mut App,
    ) -> (LayoutId, Self::RequestLayoutState) {
        if !self.windowed {
            let mut column = v_flex()
                .w_full()
                .min_w_0()
                .gap(px(SIDEBAR_SESSION_CONTENT_GAP));
            for index in 0..self.row_count {
                column = column.child((self.build_row)(index, window, cx));
            }
            let mut column = column.into_any_element();
            let layout_id = column.request_layout(window, cx);
            return (
                layout_id,
                SidebarSessionRunLayout {
                    spacer: None,
                    column: Some(column),
                    rows: Vec::new(),
                },
            );
        }
        // The rows are placed by hand during prepaint, so the run only has to
        // reserve the height they would have taken in the flow.
        let mut spacer = div()
            .w_full()
            .min_w_0()
            .h(px(self.flow_height()))
            .flex_none()
            .into_any_element();
        let layout_id = spacer.request_layout(window, cx);
        (
            layout_id,
            SidebarSessionRunLayout {
                spacer: Some(spacer),
                column: None,
                rows: Vec::new(),
            },
        )
    }

    fn prepaint(
        &mut self,
        _: Option<&GlobalElementId>,
        _: Option<&InspectorElementId>,
        bounds: Bounds<Pixels>,
        layout: &mut Self::RequestLayoutState,
        window: &mut Window,
        cx: &mut App,
    ) {
        if let Some(column) = layout.column.as_mut() {
            column.prepaint(window, cx);
            return;
        }
        let Some(spacer) = layout.spacer.as_mut() else {
            return;
        };
        spacer.prepaint(window, cx);
        layout.rows.clear();
        if bounds.size.width <= px(0.0) {
            return;
        }
        let viewport = window.content_mask().bounds;
        let available_space = size(
            AvailableSpace::Definite(bounds.size.width),
            AvailableSpace::MinContent,
        );
        let visible = self.visible_rows(bounds, viewport);
        // The selected row keeps its anchor even when it is scrolled out of the
        // window, so `locate current session` still has somewhere to scroll to.
        let selected = self
            .selected_row
            .filter(|index| !visible.contains(index))
            .into_iter();
        for index in visible.chain(selected) {
            let mut row = (self.build_row)(index, window, cx);
            row.layout_as_root(available_space, window, cx);
            row.prepaint_at(
                bounds.origin + point(px(0.0), px(self.row_origin(index))),
                window,
                cx,
            );
            layout.rows.push(row);
        }
    }

    fn paint(
        &mut self,
        _: Option<&GlobalElementId>,
        _: Option<&InspectorElementId>,
        _: Bounds<Pixels>,
        layout: &mut Self::RequestLayoutState,
        _: &mut Self::PrepaintState,
        window: &mut Window,
        cx: &mut App,
    ) {
        if let Some(column) = layout.column.as_mut() {
            column.paint(window, cx);
            return;
        }
        if let Some(spacer) = layout.spacer.as_mut() {
            spacer.paint(window, cx);
        }
        for row in &mut layout.rows {
            row.paint(window, cx);
        }
    }
}

/// One painted unit of a turn's process section.
///
/// Runs of tool activity collapse into a single summary row and a command can
/// pair with the permission prompt that follows it, so the unit — not the raw
/// row — is what the renderer paints and what the windowed run culls.
struct TimelineProcessUnit {
    /// Rows this unit covers, as indices into `turn.process_rows`.
    rows: Range<usize>,
    /// Element id and height-table key.
    id: String,
    /// Content revision the measured height belongs to.
    revision: i64,
    /// Whether any row of this unit is still streaming.
    streaming: bool,
    /// Height the unit takes before it has been measured.
    estimated_height: f32,
    /// What the renderer paints for this unit.
    kind: TimelineProcessUnitKind,
}

enum TimelineProcessUnitKind {
    /// A single row painted on its own.
    Row,
    /// A collapsed run of tool activity, painted as one summary row.
    Group(TimelineProcessActivityGroup),
    /// A command and the permission prompt that follows it.
    CommandPair,
}

/// Builds one unit of a [`TimelineProcessRun`] on demand.
///
/// Runs are built during prepaint, after the view's render has returned, so the
/// builder may update the workbench to reach the unit's current state.
type TimelineProcessUnitBuilder = Box<dyn Fn(usize, &mut Window, &mut App) -> AnyElement>;

/// One contiguous band of a turn's process rows.
///
/// The timeline virtualizes by turn, so one virtual row is a whole turn and an
/// expanded turn used to build, lay out and paint every one of its process rows
/// on every frame — a session that ran for hours is a single turn with hundreds
/// of them, and a running turn keeps its process expanded. The run keeps the
/// height its units occupy in the flow and builds only the ones the timeline
/// viewport shows, placing each at its own origin. It is the same shape
/// `SidebarSessionRun` uses for a folder's sessions and `MarkdownVirtualFlow`
/// uses inside a single Markdown document.
struct TimelineProcessRun {
    /// Units this run stands for, in paint order.
    units: Rc<Vec<TimelineProcessUnit>>,
    /// Origin of each unit, relative to the run's own origin.
    origins: Arc<Vec<Pixels>>,
    /// The height the units occupy in the flow, gaps included.
    total_height: Pixels,
    /// Unit holding the pending find-in-conversation reveal, built even when it
    /// falls outside the window so the match can still be scrolled to.
    pinned_unit: Option<usize>,
    /// The session whose view this run's units belong to.
    ///
    /// Prepaint borrows it back before building or measuring a unit, so a run
    /// that is not the focused pane's own still reads its own expansions and
    /// records its own measurements.
    session_id: Option<VibexSessionId>,
    /// The workbench, for recording what the run measured.
    entity: WeakEntity<VibexWorkbench>,
    /// Builds unit `index` on demand.
    build_unit: TimelineProcessUnitBuilder,
}

impl TimelineProcessRun {
    /// The units the content mask can see, widened by
    /// [`TIMELINE_PROCESS_RUN_OVERSCAN_PX`].
    fn visible_units(&self, bounds: Bounds<Pixels>, viewport: Bounds<Pixels>) -> Range<usize> {
        if bounds.size.width <= px(0.0) {
            return 0..0;
        }
        timeline_process_visible_units(&self.origins, self.total_height, bounds, viewport)
    }
}

/// The height a process unit settles at after a measurement.
///
/// While a unit is still streaming it never shrinks: incomplete Markdown lays
/// out shorter between parses, and the outer timeline measures the run's total,
/// so following a transient dip makes the whole turn — and the viewport
/// following it — bounce. A settled unit takes the measurement as it is.
fn stable_process_unit_height(current: Option<f32>, measured: f32, streaming: bool) -> f32 {
    match current {
        Some(height) if (height - measured).abs() < 1.0 => height,
        Some(height) if streaming && measured < height => height,
        _ => measured,
    }
}

/// The units of a process run the viewport shows, widened by
/// [`TIMELINE_PROCESS_RUN_OVERSCAN_PX`].
///
/// Unit heights differ — a reasoning row is hundreds of pixels, a tool line is
/// one — so the range comes from the cumulative origins rather than from
/// arithmetic on a single stride. The origins are sorted, which keeps the two
/// lookups logarithmic even for a turn holding hundreds of units.
fn timeline_process_visible_units(
    origins: &[Pixels],
    total_height: Pixels,
    bounds: Bounds<Pixels>,
    viewport: Bounds<Pixels>,
) -> Range<usize> {
    let unit_count = origins.len();
    if unit_count == 0 {
        return 0..0;
    }
    let visible_top = viewport.top() - px(TIMELINE_PROCESS_RUN_OVERSCAN_PX);
    let visible_bottom = viewport.bottom() + px(TIMELINE_PROCESS_RUN_OVERSCAN_PX);
    let local_top = visible_top - bounds.top();
    let first = if local_top < px(0.0) {
        0
    } else if local_top >= total_height {
        unit_count
    } else {
        origins
            .partition_point(|origin| *origin <= local_top)
            .saturating_sub(1)
    };
    let end = origins[first..]
        .partition_point(|origin| bounds.top() + *origin < visible_bottom)
        .saturating_add(first)
        .min(unit_count);
    first..end.max(first)
}

/// The flow child a run reserves its height with, and the units it placed.
struct TimelineProcessRunLayout {
    spacer: AnyElement,
    units: Vec<AnyElement>,
}

impl IntoElement for TimelineProcessRun {
    type Element = Self;

    fn into_element(self) -> Self::Element {
        self
    }
}

impl Element for TimelineProcessRun {
    type RequestLayoutState = TimelineProcessRunLayout;
    type PrepaintState = ();

    fn id(&self) -> Option<ElementId> {
        None
    }

    fn source_location(&self) -> Option<&'static std::panic::Location<'static>> {
        None
    }

    fn request_layout(
        &mut self,
        _: Option<&GlobalElementId>,
        _: Option<&InspectorElementId>,
        window: &mut Window,
        cx: &mut App,
    ) -> (LayoutId, Self::RequestLayoutState) {
        // The units are placed by hand during prepaint, so the run only has to
        // reserve the height they would have taken in the flow.
        let mut spacer = div()
            .w_full()
            .min_w_0()
            .h(self.total_height)
            .flex_none()
            .into_any_element();
        let layout_id = spacer.request_layout(window, cx);
        (
            layout_id,
            TimelineProcessRunLayout {
                spacer,
                units: Vec::new(),
            },
        )
    }

    fn prepaint(
        &mut self,
        _: Option<&GlobalElementId>,
        _: Option<&InspectorElementId>,
        bounds: Bounds<Pixels>,
        layout: &mut Self::RequestLayoutState,
        window: &mut Window,
        cx: &mut App,
    ) {
        layout.spacer.prepaint(window, cx);
        layout.units.clear();
        if bounds.size.width <= px(0.0) {
            return;
        }
        let viewport = window.content_mask().bounds;
        let available_space = size(
            AvailableSpace::Definite(bounds.size.width),
            AvailableSpace::MinContent,
        );
        let visible = self.visible_units(bounds, viewport);
        let pinned = self
            .pinned_unit
            .filter(|index| !visible.contains(index))
            .into_iter();
        let mut measurements = Vec::new();
        for index in visible.chain(pinned) {
            let Some(origin) = self.origins.get(index).copied() else {
                continue;
            };
            let mut unit = (self.build_unit)(index, window, cx);
            let measured = unit.layout_as_root(available_space, window, cx);
            unit.prepaint_at(bounds.origin + point(px(0.0), origin), window, cx);
            measurements.push((index, f32::from(measured.height)));
            layout.units.push(unit);
        }
        if !measurements.is_empty() {
            let units = self.units.clone();
            let session_id = self.session_id.clone();
            let _ = self.entity.update(cx, |this, cx| {
                this.with_session_view_for_render(session_id.as_ref(), |this| {
                    this.record_timeline_process_unit_heights(&units, &measurements, cx)
                })
            });
        }
    }

    fn paint(
        &mut self,
        _: Option<&GlobalElementId>,
        _: Option<&InspectorElementId>,
        _: Bounds<Pixels>,
        layout: &mut Self::RequestLayoutState,
        _: &mut Self::PrepaintState,
        window: &mut Window,
        cx: &mut App,
    ) {
        layout.spacer.paint(window, cx);
        for unit in &mut layout.units {
            unit.paint(window, cx);
        }
    }
}

/// One sidebar element standing for `source`'s rows.
fn sidebar_session_run(
    entity: WeakEntity<VibexWorkbench>,
    source: Rc<SidebarSessionRunSource>,
    rename_target: Option<&str>,
    selected_session: Option<&str>,
) -> AnyElement {
    let windowed = !source.renames_a_row(rename_target)
        && source.session_indices.len() > SIDEBAR_SESSION_RUN_FLOW_LIMIT;
    let row_count = source.session_indices.len();
    let selected_row = selected_session.and_then(|selected| {
        let sessions = source.sessions();
        source
            .session_indices
            .iter()
            .position(|index| sessions[*index].id.as_str() == selected)
    });
    let build_source = source;
    SidebarSessionRun {
        row_count,
        windowed,
        selected_row,
        build_row: Box::new(move |index, _window, cx| {
            let Some(session) = build_source.session(index) else {
                return Empty.into_any_element();
            };
            entity
                .update(cx, |this, cx| {
                    this.render_sidebar_session(
                        session,
                        &build_source.project_scope_id,
                        build_source.reorder_enabled,
                        build_source.show_worktree_identity,
                        build_source.strings,
                        cx,
                    )
                })
                .unwrap_or_else(|_| Empty.into_any_element())
        }),
    }
    .into_any_element()
}

/// Flushes the pending band of session rows into one run element.
#[allow(clippy::too_many_arguments)]
fn push_sidebar_session_run(
    elements: &mut Vec<AnyElement>,
    run: &mut Vec<usize>,
    entity: &WeakEntity<VibexWorkbench>,
    groups: &Rc<Vec<SidebarProjectProjection>>,
    project_index: usize,
    workspace_index: Option<usize>,
    project_scope_id: &str,
    reorder_enabled: bool,
    show_worktree_identity: bool,
    rename_target: Option<&str>,
    selected_session: Option<&str>,
    strings: &'static Strings,
) {
    if run.is_empty() {
        return;
    }
    elements.push(sidebar_session_run(
        entity.clone(),
        Rc::new(SidebarSessionRunSource {
            groups: groups.clone(),
            project_index,
            workspace_index,
            session_indices: std::mem::take(run),
            project_scope_id: project_scope_id.to_string(),
            reorder_enabled,
            show_worktree_identity,
            strings,
        }),
        rename_target,
        selected_session,
    ));
}

fn sidebar_workspace_branch_name(branch: &str) -> &str {
    branch
        .rsplit_once('/')
        .map(|(_, name)| name)
        .filter(|name| !name.is_empty())
        .unwrap_or(branch)
}

fn sidebar_worktree_branch_for_title(current_branch: &str, title: &str) -> String {
    let slug = managed_worktree_name_slug(title.trim());
    current_branch
        .rsplit_once('/')
        .map(|(prefix, _)| format!("{prefix}/{slug}"))
        .unwrap_or(slug)
}

fn new_session_worktree_unavailable_reason(
    locale: locale::ResolvedLocale,
    state: &NewSessionWorkspaceState,
    probe_error: Option<&str>,
    mutation_supported: bool,
) -> Option<String> {
    let localized = |en: &str, zh_cn: &str, zh_tw: &str| match locale {
        locale::ResolvedLocale::En => en.to_string(),
        locale::ResolvedLocale::ZhCn => zh_cn.to_string(),
        locale::ResolvedLocale::ZhTw => zh_tw.to_string(),
    };
    if !mutation_supported {
        return Some(localized(
            "Worktree creation is unavailable on this client",
            "此客户端不支持创建 Worktree",
            "此用戶端不支援建立 Worktree",
        ));
    }
    if state.project_id.is_none() {
        return Some(localized(
            "Choose a Project first",
            "请先选择项目",
            "請先選擇專案",
        ));
    }
    if probe_error.is_some() {
        return Some(localized(
            "Git status could not be checked",
            "无法检查 Git 状态",
            "無法檢查 Git 狀態",
        ));
    }
    let eligibility = state.eligibility.as_ref()?;
    match eligibility.state {
        GitProjectEligibilityState::Probing => None,
        GitProjectEligibilityState::Eligible if eligibility.is_eligible() => None,
        GitProjectEligibilityState::Eligible => Some(localized(
            "No valid base branch is available",
            "没有可用的基线分支",
            "沒有可用的基線分支",
        )),
        GitProjectEligibilityState::Ineligible | GitProjectEligibilityState::Unknown => {
            let reason = match eligibility.disabled_reason {
                Some(GitProjectIneligibleReason::PathMissing) => localized(
                    "Project path does not exist",
                    "项目路径不存在",
                    "專案路徑不存在",
                ),
                Some(GitProjectIneligibleReason::PathNotDirectory) => localized(
                    "Project path is not a directory",
                    "项目路径不是目录",
                    "專案路徑不是目錄",
                ),
                Some(GitProjectIneligibleReason::GitUnavailable) => {
                    localized("Git is unavailable", "Git 不可用", "Git 不可用")
                }
                Some(GitProjectIneligibleReason::NotWorkingTree) => localized(
                    "Project is not a Git working tree",
                    "项目不是 Git 工作目录",
                    "專案不是 Git 工作目錄",
                ),
                Some(GitProjectIneligibleReason::BareRepository) => localized(
                    "Bare repositories cannot create Worktrees here",
                    "裸仓库无法在此创建 Worktree",
                    "裸儲存庫無法在此建立 Worktree",
                ),
                Some(GitProjectIneligibleReason::UnbornHead) => localized(
                    "Create the first commit before using Worktrees",
                    "首次提交后才能使用 Worktree",
                    "首次提交後才能使用 Worktree",
                ),
                Some(GitProjectIneligibleReason::BaseRefUnavailable) => localized(
                    "No valid base branch is available",
                    "没有可用的基线分支",
                    "沒有可用的基線分支",
                ),
                Some(GitProjectIneligibleReason::RepositoryIdentityUnavailable) => localized(
                    "Git repository identity is unavailable",
                    "无法识别 Git 仓库",
                    "無法識別 Git 儲存庫",
                ),
                Some(GitProjectIneligibleReason::Unknown) | None => localized(
                    "Project is not eligible for Worktrees",
                    "此项目无法使用 Worktree",
                    "此專案無法使用 Worktree",
                ),
            };
            Some(reason)
        }
    }
}

fn toggle_sidebar_project_collapse_all(
    collapsed_ids: &mut BTreeSet<String>,
    restore_snapshot: &mut Option<BTreeSet<String>>,
    project_ids: &BTreeSet<String>,
) {
    if let Some(snapshot) = restore_snapshot.take() {
        *collapsed_ids = snapshot.intersection(project_ids).cloned().collect();
    } else {
        *restore_snapshot = Some(collapsed_ids.intersection(project_ids).cloned().collect());
        collapsed_ids.extend(project_ids.iter().cloned());
    }
}

fn reveal_sidebar_session(
    collapsed_project_ids: &mut BTreeSet<String>,
    collapsed_workspace_ids: &mut BTreeSet<String>,
    project_id: &str,
    workspace_id: &str,
    hierarchy_mode: SidebarHierarchyMode,
) -> bool {
    let project_revealed = collapsed_project_ids.remove(project_id);
    let workspace_revealed = hierarchy_mode == SidebarHierarchyMode::Detailed
        && collapsed_workspace_ids.remove(workspace_id);
    project_revealed || workspace_revealed
}

fn sidebar_project_uses_detailed_hierarchy(
    hierarchy_mode: SidebarHierarchyMode,
    workspaces: &[SidebarWorkspaceProjection],
) -> bool {
    hierarchy_mode == SidebarHierarchyMode::Detailed
        && workspaces.iter().any(|workspace| {
            workspace.context.git_available
                || workspace.workspace.mode == WorkspaceMode::VibexWorktree
        })
}

fn sidebar_selected_session_background(accent: Hsla, is_dark: bool) -> Hsla {
    if is_dark {
        accent.lighten(0.24)
    } else {
        accent.darken(0.04)
    }
}

fn sidebar_move_selected_background(accent: Hsla, is_dark: bool) -> Hsla {
    if is_dark {
        accent.lighten(0.30)
    } else {
        accent.darken(0.12)
    }
}

fn sidebar_workspace_focus_border(accent: Hsla, is_dark: bool) -> Hsla {
    if is_dark {
        accent.lighten(0.46)
    } else {
        accent.darken(0.14)
    }
}

fn sidebar_selection_indicator(state: SidebarSelectionState, cx: &App) -> AnyElement {
    div()
        .size(px(14.0))
        .flex_none()
        .items_center()
        .justify_center()
        .rounded(px(3.0))
        .border_1()
        .border_color(if state == SidebarSelectionState::Unchecked {
            cx.theme().sidebar_foreground.opacity(0.42)
        } else {
            cx.theme().primary
        })
        .bg(if state == SidebarSelectionState::Unchecked {
            cx.theme().transparent
        } else {
            cx.theme().primary
        })
        .text_color(cx.theme().primary_foreground)
        .when(state == SidebarSelectionState::Checked, |this| {
            this.child(Icon::new(IconName::Check).size(px(10.0)))
        })
        .when(state == SidebarSelectionState::Indeterminate, |this| {
            this.child(
                div()
                    .w(px(8.0))
                    .h(px(1.5))
                    .bg(cx.theme().primary_foreground),
            )
        })
        .into_any_element()
}

fn runtime_selection_cancellation_is_pending(
    selected_session_id: Option<&VibexSessionId>,
    pending_session_ids: &BTreeSet<String>,
) -> bool {
    selected_session_id.is_some_and(|session_id| pending_session_ids.contains(session_id.as_str()))
}

fn catalog_has_runtime_selection(
    catalog: &SessionRuntimeOptionCatalog,
    selection: &SessionRuntimeSelection,
) -> bool {
    catalog.options.iter().any(|option| {
        option.availability == vibex_core::RuntimeOptionAvailability::Available
            && option.selection.agent_id == selection.agent_id
            && option.selection.auth_source == selection.auth_source
            && option.selection.model == selection.model
            && selection.reasoning_effort.as_ref().is_none_or(|value| {
                option
                    .reasoning_efforts
                    .iter()
                    .any(|candidate| &candidate.value == value)
            })
            && selection.mode_id.as_ref().is_none_or(|value| {
                option
                    .modes
                    .iter()
                    .any(|candidate| &candidate.value == value)
            })
            && selection.config_values.iter().all(|(key, value)| {
                option
                    .features
                    .iter()
                    .find(|feature| &feature.id == key)
                    .is_some_and(|feature| feature.accepts_value(value))
            })
    })
}

fn runtime_selection_identity_matches(
    left: &SessionRuntimeSelection,
    right: &SessionRuntimeSelection,
) -> bool {
    left.agent_id == right.agent_id
        && left.auth_source == right.auth_source
        && left.model == right.model
}

fn runtime_reasoning_effort_value(selection: Option<&SessionRuntimeSelection>) -> String {
    selection
        .and_then(|selection| selection.reasoning_effort.clone())
        .unwrap_or_default()
}

fn runtime_feature_for_selection<'a>(
    catalog: &'a SessionRuntimeOptionCatalog,
    selection: &SessionRuntimeSelection,
    feature_id: &str,
) -> Option<&'a SessionRuntimeFeature> {
    catalog
        .options
        .iter()
        .find(|option| {
            option.availability == vibex_core::RuntimeOptionAvailability::Available
                && option.selection.agent_id == selection.agent_id
                && option.selection.auth_source == selection.auth_source
                && option.selection.model == selection.model
        })?
        .features
        .iter()
        .find(|feature| feature.id == feature_id)
}

fn runtime_feature_values(feature: &SessionRuntimeFeature) -> Vec<vibex_core::SessionConfigValue> {
    let mut values = feature.values.clone();
    for value in [
        feature.default_value.as_ref(),
        feature.current_value.as_ref(),
    ]
    .into_iter()
    .flatten()
    {
        if !values
            .iter()
            .any(|candidate| candidate.value == value.value)
        {
            values.push(value.clone());
        }
    }
    values
}

fn runtime_feature_tooltip(
    feature: &SessionRuntimeFeature,
    current: Option<&vibex_core::SessionConfigValue>,
) -> String {
    let current = current.map(|value| value.label.clone().unwrap_or_else(|| value.value.clone()));
    match (feature.description.as_deref(), current) {
        (Some(description), Some(current)) => {
            format!("{}: {current}\n{description}", feature.label)
        }
        (Some(description), None) => format!("{}\n{description}", feature.label),
        (None, Some(current)) => format!("{}: {current}", feature.label),
        (None, None) => feature.label.clone(),
    }
}

#[cfg(test)]
fn default_new_session_runtime_selection(
    catalog: &SessionRuntimeOptionCatalog,
    preferred: Option<&SessionRuntimeSelection>,
) -> Option<SessionRuntimeSelection> {
    if let Some(preferred) =
        preferred.filter(|selection| catalog_has_runtime_selection(catalog, selection))
    {
        return Some(preferred.clone());
    }
    let available = catalog
        .options
        .iter()
        .filter(|option| option.availability == vibex_core::RuntimeOptionAvailability::Available);
    available
        .clone()
        .find(|option| {
            let identity = format!("{} {}", option.selection.agent_id, option.agent_label)
                .to_ascii_lowercase();
            identity.contains("codex") || identity.contains("openai")
        })
        .or_else(|| available.into_iter().next())
        .map(|option| option.selection.clone())
}

fn default_new_session_agent_id(
    agents: &[AgentSnapshotEntry],
    preferred: Option<&AgentId>,
) -> Option<AgentId> {
    let mut enabled = agents
        .iter()
        .filter(|agent| is_new_session_agent_available(agent))
        .collect::<Vec<_>>();
    enabled.sort_by_key(|agent| agent.order_index);
    preferred
        .filter(|preferred| enabled.iter().any(|agent| &agent.id == *preferred))
        .cloned()
        .or_else(|| {
            enabled
                .iter()
                .find(|agent| {
                    agent.id.as_str().eq_ignore_ascii_case("codex")
                        || agent.label.to_ascii_lowercase().contains("codex")
                })
                .map(|agent| agent.id.clone())
        })
        .or_else(|| enabled.first().map(|agent| agent.id.clone()))
}

fn new_session_runtime_selection_for_agent(
    catalog: &SessionRuntimeOptionCatalog,
    agent_id: Option<&AgentId>,
    preferred: Option<&SessionRuntimeSelection>,
) -> Option<SessionRuntimeSelection> {
    if let Some(agent_id) = agent_id {
        if let Some(preferred) = preferred.filter(|selection| {
            &selection.agent_id == agent_id && catalog_has_runtime_selection(catalog, selection)
        }) {
            return Some(preferred.clone());
        }
        if let Some(option) = catalog.options.iter().find(|option| {
            option.availability == vibex_core::RuntimeOptionAvailability::Available
                && &option.selection.agent_id == agent_id
        }) {
            return Some(option.selection.clone());
        }
        return None;
    }
    None
}

fn new_session_runtime_preference_for_agent(
    agent_id: &AgentId,
    draft: Option<&SessionRuntimeSelection>,
    remembered: &BTreeMap<AgentId, SessionRuntimeSelection>,
    active_session: Option<&SessionRuntimeSelection>,
) -> Option<SessionRuntimeSelection> {
    let draft = draft.filter(|selection| &selection.agent_id == agent_id);
    let remembered = remembered.get(agent_id);
    draft
        .filter(|draft| {
            remembered
                .is_none_or(|remembered| draft_preserves_remembered_runtime(draft, remembered))
        })
        .or(remembered)
        .or_else(|| active_session.filter(|selection| &selection.agent_id == agent_id))
        .cloned()
}

fn draft_preserves_remembered_runtime(
    draft: &SessionRuntimeSelection,
    remembered: &SessionRuntimeSelection,
) -> bool {
    draft.agent_id == remembered.agent_id
        && draft.auth_source == remembered.auth_source
        && draft.model == remembered.model
        && draft.reasoning_effort == remembered.reasoning_effort
        && draft.mode_id == remembered.mode_id
        && remembered
            .config_values
            .iter()
            .all(|(key, value)| draft.config_values.get(key) == Some(value))
}

fn persisted_runtime_selection(
    catalog: Option<&SessionRuntimeOptionCatalog>,
    selection: &SessionRuntimeSelection,
) -> SessionRuntimeSelection {
    let mut persisted = selection.clone();
    persisted.config_values.retain(|key, value| {
        catalog
            .and_then(|catalog| runtime_feature_for_selection(catalog, selection, key))
            .is_some_and(|feature| {
                matches!(
                    feature.kind,
                    SessionRuntimeFeatureKind::Toggle | SessionRuntimeFeatureKind::Select
                ) && feature.accepts_value(value)
            })
    });
    persisted
}

fn is_new_session_agent_available(agent: &AgentSnapshotEntry) -> bool {
    vibex_core::is_user_visible_agent(&agent.id)
        && agent.added
        && agent.enabled
        && agent.installed
        && agent.deleted_at_ms.is_none()
}

/// Resolves a composer trigger through the authority.
///
/// The Agent catalogue, the workspace file tree and the workspace Skills all
/// live with whichever runtime owns the workspace, so the composite is one
/// backend read instead of three local ones.
async fn discover_desktop_composer_commands(
    backend: BackendFacade,
    request: AgentCommandDiscoverRequest,
) -> vibex_core::VibexResult<AgentCommandDiscoverResponse> {
    let discovery = backend
        .agent()
        .discover_agent_commands(request)
        .await
        .map_err(|error| {
            vibex_core::VibexError::new(
                vibex_core::ErrorCategory::Storage,
                error.code,
                error.message,
            )
        })?;
    Ok(discovery.response)
}

fn floor_char_boundary(text: &str, offset: usize) -> usize {
    let mut offset = offset.min(text.len());
    while !text.is_char_boundary(offset) {
        offset -= 1;
    }
    offset
}

fn composer_trigger_for_selection(text: &str, selection: Range<usize>) -> Option<ComposerTrigger> {
    if selection.start != selection.end {
        return None;
    }
    let caret_byte = floor_char_boundary(text, selection.end);
    let caret_character = text[..caret_byte].chars().count();
    composer_trigger_at(text, caret_character)
}

fn character_offset_to_byte(text: &str, offset: usize) -> usize {
    text.char_indices()
        .nth(offset)
        .map(|(index, _)| index)
        .unwrap_or(text.len())
}

fn parse_slash_command_invocation(text: &str) -> Option<(String, Option<String>)> {
    let command_text = text.trim();
    let remainder = command_text.strip_prefix('/')?;
    let command_end = remainder
        .find(char::is_whitespace)
        .unwrap_or(remainder.len());
    let command_name = &remainder[..command_end];
    if command_name.is_empty() || command_name.contains('/') {
        return None;
    }
    let arguments = remainder[command_end..].trim().to_string();
    let arguments = (!arguments.is_empty()).then_some(arguments);
    Some((command_name.to_string(), arguments))
}

fn is_executable_command_source(entry: &AgentCommandEntry) -> bool {
    matches!(
        entry.source_kind,
        AgentCommandSourceKind::Provider | AgentCommandSourceKind::Prompt
    )
}

fn command_entry_matches_draft(text: &str, entry: Option<&AgentCommandEntry>) -> bool {
    let Some(entry) = entry else {
        return false;
    };
    if !is_executable_command_source(entry) || entry.trigger != AgentCommandTrigger::Slash {
        return false;
    }
    let Some((command_name, _)) = parse_slash_command_invocation(text) else {
        return false;
    };
    entry
        .command_name
        .as_deref()
        .is_none_or(|entry_name| entry_name == command_name)
}

fn resolve_composer_command_invocation(
    text: &str,
    entry: Option<&AgentCommandEntry>,
    allow_manual_provider_slash: bool,
) -> Option<ComposerCommandInvocation> {
    let (command_name, arguments) = parse_slash_command_invocation(text)?;
    if let Some(entry) = entry {
        if !command_entry_matches_draft(text, Some(entry)) {
            return None;
        }
        return Some(ComposerCommandInvocation {
            command_id: Some(entry.id.clone()),
            trigger: entry.trigger,
            source_kind: entry.source_kind,
            command_text: text.trim().to_string(),
            command_name: Some(command_name),
            arguments,
            prompt_id: entry.prompt_id.clone(),
        });
    }
    allow_manual_provider_slash.then(|| ComposerCommandInvocation {
        command_id: None,
        trigger: AgentCommandTrigger::Slash,
        source_kind: AgentCommandSourceKind::Provider,
        command_text: text.trim().to_string(),
        command_name: Some(command_name),
        arguments,
        prompt_id: None,
    })
}

fn command_source_icon(source_kind: AgentCommandSourceKind) -> IconName {
    match source_kind {
        AgentCommandSourceKind::Provider => IconName::SquareTerminal,
        AgentCommandSourceKind::Prompt => IconName::BookOpen,
        AgentCommandSourceKind::Skill => IconName::Bot,
        AgentCommandSourceKind::Reference => IconName::File,
        AgentCommandSourceKind::ClientBuiltin => IconName::Settings2,
    }
}

fn command_source_label(source_kind: AgentCommandSourceKind) -> &'static str {
    match source_kind {
        AgentCommandSourceKind::Provider => "Provider",
        AgentCommandSourceKind::Prompt => "Prompt",
        AgentCommandSourceKind::Skill => "Skill",
        AgentCommandSourceKind::Reference => "Reference",
        AgentCommandSourceKind::ClientBuiltin => "Built-in",
    }
}

fn attachment_mime_type(path: &Path) -> Option<String> {
    path.extension()
        .and_then(|extension| extension.to_str())
        .and_then(|extension| match extension.to_ascii_lowercase().as_str() {
            "png" => Some("image/png"),
            "jpg" | "jpeg" => Some("image/jpeg"),
            "gif" => Some("image/gif"),
            "webp" => Some("image/webp"),
            "svg" => Some("image/svg+xml"),
            "bmp" => Some("image/bmp"),
            "tif" | "tiff" => Some("image/tiff"),
            "ico" => Some("image/ico"),
            "pbm" | "pgm" | "ppm" | "pnm" => Some("image/x-portable-anymap"),
            _ => None,
        })
        .map(str::to_string)
}

fn inline_composer_attachment_marker(serial: u64) -> String {
    format!(
        "{COMPOSER_INLINE_ATTACHMENT_PREFIX}{serial}{COMPOSER_INLINE_ATTACHMENT_MARKER_RESERVE}{COMPOSER_INLINE_ATTACHMENT_SUFFIX}"
    )
}

fn inline_composer_attachment_insertion(marker: &str) -> String {
    format!(" {marker} ")
}

fn inline_composer_attachment_padded_range(text: &str, range: Range<usize>) -> Range<usize> {
    let bytes = text.as_bytes();
    let start = range
        .start
        .checked_sub(1)
        .filter(|start| bytes.get(*start) == Some(&b' '))
        .unwrap_or(range.start);
    let end = if bytes.get(range.end) == Some(&b' ') {
        range.end + 1
    } else {
        range.end
    };
    start..end
}

fn composer_buffer_row_for_offset(text: &str, offset: usize) -> usize {
    text.as_bytes()[..offset.min(text.len())]
        .iter()
        .filter(|byte| **byte == b'\n')
        .count()
}

fn composer_attachment_bounds_are_visible(
    bounds: Bounds<Pixels>,
    input_bounds: Bounds<Pixels>,
) -> bool {
    bounds.intersects(&input_bounds)
        && bounds.top() >= input_bounds.top()
        && bounds.bottom() <= input_bounds.bottom()
}

fn composer_submission_payload(
    raw_text: &str,
    inline_attachments: &[InlineComposerAttachment],
) -> (String, Vec<MessageAttachment>) {
    let mut positioned = inline_attachments
        .iter()
        .filter_map(|item| {
            item.range_in(raw_text).map(|range| {
                (
                    inline_composer_attachment_padded_range(raw_text, range),
                    item,
                )
            })
        })
        .collect::<Vec<_>>();
    positioned.sort_by_key(|(range, _)| range.start);

    let mut text = String::with_capacity(raw_text.len());
    let mut attachments = Vec::with_capacity(positioned.len());
    let mut cursor = 0;
    for (range, item) in positioned {
        if range.start < cursor {
            continue;
        }
        text.push_str(&raw_text[cursor..range.start]);
        let inline_text_offset = u32::try_from(text.encode_utf16().count()).unwrap_or(u32::MAX);
        attachments.push(MessageAttachment {
            label: item.attachment.label.clone(),
            mime_type: item.attachment.mime_type.clone(),
            uri: item
                .attachment
                .path
                .as_ref()
                .map(|path| format!("file://{path}")),
            inline_text_offset: Some(inline_text_offset),
        });
        let previous = text.chars().next_back();
        let next = raw_text[range.end..].chars().next();
        if previous.is_some_and(|character| !character.is_whitespace())
            && next.is_some_and(|character| !character.is_whitespace())
        {
            text.push(' ');
        }
        cursor = range.end;
    }
    text.push_str(&raw_text[cursor..]);
    (text, attachments)
}

fn utf16_offset_to_byte_index(text: &str, offset: usize) -> usize {
    if offset == 0 {
        return 0;
    }
    let mut utf16_cursor = 0;
    for (byte_index, character) in text.char_indices() {
        let next_utf16_cursor = utf16_cursor + character.len_utf16();
        if offset < next_utf16_cursor {
            return byte_index;
        }
        if offset == next_utf16_cursor {
            return byte_index + character.len_utf8();
        }
        utf16_cursor = next_utf16_cursor;
    }
    text.len()
}

fn user_message_inline_segments(
    text: &str,
    attachments: &[MessageAttachment],
) -> Vec<UserMessageInlineSegment> {
    let mut positioned = attachments
        .iter()
        .cloned()
        .enumerate()
        .filter_map(|(index, attachment)| {
            attachment
                .inline_text_offset
                .map(|offset| (offset as usize, index, attachment))
        })
        .collect::<Vec<_>>();
    positioned.sort_by_key(|(offset, index, _)| (*offset, *index));
    let positioned_indexes = positioned
        .iter()
        .map(|(_, index, _)| *index)
        .collect::<BTreeSet<_>>();
    let mut segments = Vec::new();
    let mut cursor = 0;

    for (offset, _, attachment) in positioned {
        let attachment_byte = utf16_offset_to_byte_index(text, offset).max(cursor);
        if attachment_byte > cursor {
            segments.push(UserMessageInlineSegment::Text(
                text[cursor..attachment_byte].to_string(),
            ));
        }
        segments.push(UserMessageInlineSegment::Attachment(attachment));
        cursor = attachment_byte;
        if text[cursor..].starts_with(' ') {
            cursor += 1;
        }
    }

    if cursor < text.len() {
        segments.push(UserMessageInlineSegment::Text(text[cursor..].to_string()));
    }
    for (index, attachment) in attachments.iter().cloned().enumerate() {
        if !positioned_indexes.contains(&index) {
            segments.push(UserMessageInlineSegment::Attachment(attachment));
        }
    }
    if segments.is_empty() {
        segments.push(UserMessageInlineSegment::Text(String::new()));
    }
    segments
}

fn message_attachment_is_image(attachment: &MessageAttachment) -> bool {
    composer_attachment_from_message(attachment, String::new()).is_image()
}

fn user_message_clipboard_plain_text(text: &str, attachments: &[MessageAttachment]) -> String {
    let mut output = String::with_capacity(text.len() + attachments.len() * "image".len());
    let mut image_needs_trailing_space = false;
    for segment in user_message_inline_segments(text, attachments) {
        match segment {
            UserMessageInlineSegment::Text(value) => {
                if image_needs_trailing_space
                    && value
                        .chars()
                        .next()
                        .is_some_and(|character| !character.is_whitespace())
                {
                    output.push(' ');
                }
                output.push_str(&value);
                image_needs_trailing_space = false;
            }
            UserMessageInlineSegment::Attachment(_) => {
                if output
                    .chars()
                    .next_back()
                    .is_some_and(|character| !character.is_whitespace())
                {
                    output.push(' ');
                }
                output.push_str("image");
                image_needs_trailing_space = true;
            }
        }
    }
    output
}

fn user_message_clipboard_item(text: &str, attachments: &[MessageAttachment]) -> ClipboardItem {
    let image_attachments = attachments
        .iter()
        .filter(|attachment| message_attachment_is_image(attachment))
        .take(VIBEX_MESSAGE_CLIPBOARD_MAX_ATTACHMENTS)
        .cloned()
        .collect::<Vec<_>>();
    if image_attachments.is_empty() {
        return ClipboardItem::new_string(text.to_string());
    }
    let plain_text = user_message_clipboard_plain_text(text, &image_attachments);
    ClipboardItem::new_string_with_json_metadata(
        plain_text,
        VibexMessageClipboard::new(text.to_string(), image_attachments),
    )
}

fn inline_composer_clipboard_item(
    raw_text: &str,
    inline_attachments: &[InlineComposerAttachment],
    selection: Range<usize>,
) -> Option<ClipboardItem> {
    let selected_text = raw_text.get(selection.clone())?;
    let selected_attachments = inline_attachments
        .iter()
        .filter_map(|attachment| {
            let range = attachment.range_in(raw_text)?;
            (range.start >= selection.start && range.end <= selection.end).then_some(attachment)
        })
        .cloned()
        .collect::<Vec<_>>();
    if selected_attachments.is_empty()
        || selected_attachments.len() > VIBEX_MESSAGE_CLIPBOARD_MAX_ATTACHMENTS
        || selected_attachments.iter().any(|attachment| {
            !attachment.attachment.is_image() || attachment.attachment.path.is_none()
        })
    {
        return None;
    }

    let (text, attachments) = composer_submission_payload(selected_text, &selected_attachments);
    (!attachments.is_empty()).then(|| {
        let plain_text = user_message_clipboard_plain_text(&text, &attachments);
        ClipboardItem::new_string_with_json_metadata(
            plain_text,
            VibexMessageClipboard::new(text, attachments),
        )
    })
}

fn composer_queue_edit_insertion(
    text: &str,
    attachments: &[MessageAttachment],
    mut serial: u64,
) -> (String, Vec<InlineComposerAttachment>, u64) {
    let segments = user_message_inline_segments(text, attachments);
    let mut insertion = String::with_capacity(text.len());
    let mut inline_attachments = Vec::with_capacity(attachments.len());
    for segment in segments {
        match segment {
            UserMessageInlineSegment::Text(value) => insertion.push_str(&value),
            UserMessageInlineSegment::Attachment(attachment) => {
                serial = serial.saturating_add(1);
                let marker = inline_composer_attachment_marker(serial);
                let mut composer_attachment =
                    composer_attachment_from_message(&attachment, format!("attachment:{serial}"));
                composer_attachment.id = format!("attachment:{serial}");
                insertion.push_str(&inline_composer_attachment_insertion(&marker));
                inline_attachments.push(InlineComposerAttachment {
                    attachment: composer_attachment,
                    marker,
                });
            }
        }
    }
    (insertion, inline_attachments, serial)
}

fn vibex_message_composer_insertion(
    text: &str,
    attachments: &[MessageAttachment],
    mut serial: u64,
) -> Option<(String, Vec<InlineComposerAttachment>, u64)> {
    if attachments.is_empty() || attachments.len() > VIBEX_MESSAGE_CLIPBOARD_MAX_ATTACHMENTS {
        return None;
    }
    let mut insertion = String::with_capacity(text.len());
    let mut inline_attachments = Vec::with_capacity(attachments.len());
    for segment in user_message_inline_segments(text, attachments) {
        match segment {
            UserMessageInlineSegment::Text(value) => insertion.push_str(&value),
            UserMessageInlineSegment::Attachment(attachment) => {
                let mut composer_attachment =
                    composer_attachment_from_message(&attachment, String::new());
                if !composer_attachment.is_image() || composer_attachment.path.is_none() {
                    return None;
                }
                serial = serial.saturating_add(1);
                let marker = inline_composer_attachment_marker(serial);
                composer_attachment.id = format!("attachment:{serial}");
                insertion.push_str(&inline_composer_attachment_insertion(&marker));
                inline_attachments.push(InlineComposerAttachment {
                    attachment: composer_attachment,
                    marker,
                });
            }
        }
    }
    (!inline_attachments.is_empty()).then_some((insertion, inline_attachments, serial))
}

fn attachment_local_path(uri: &str) -> Option<String> {
    let uri = uri.trim();
    if uri.is_empty() {
        return None;
    }
    if let Ok(url) = url::Url::parse(uri)
        && url.scheme() == "file"
        && let Ok(path) = url.to_file_path()
    {
        return Some(path.to_string_lossy().into_owned());
    }
    if let Some(path) = uri.strip_prefix("file://") {
        return Some(path.to_string());
    }
    std::path::Path::new(uri)
        .is_absolute()
        .then(|| uri.to_string())
}

fn composer_attachment_from_message(
    attachment: &MessageAttachment,
    id: String,
) -> ComposerAttachment {
    ComposerAttachment {
        id,
        label: attachment.label.clone(),
        path: attachment.uri.as_deref().and_then(attachment_local_path),
        mime_type: attachment.mime_type.clone(),
    }
}

fn safe_attachment_file_name(label: &str, source: &str) -> String {
    let mut name = label
        .trim()
        .chars()
        .map(|character| {
            if matches!(
                character,
                '\\' | '/' | ':' | '*' | '?' | '"' | '<' | '>' | '|'
            ) {
                '-'
            } else {
                character
            }
        })
        .collect::<String>();
    if name.is_empty() {
        name = "image".into();
    }
    if std::path::Path::new(&name).extension().is_none()
        && let Some(extension) = std::path::Path::new(source)
            .extension()
            .and_then(|extension| extension.to_str())
    {
        name.push('.');
        name.push_str(extension);
    }
    name
}

fn edited_attachment_file_name(label: &str) -> String {
    let label = label.trim();
    let stem = Path::new(label)
        .file_stem()
        .and_then(|stem| stem.to_str())
        .filter(|stem| !stem.is_empty())
        .unwrap_or("image");
    format!("{stem}.png")
}

fn attachment_preview_image_format(
    path: &std::path::Path,
    mime_type: Option<&str>,
) -> Option<ImageFormat> {
    mime_type.and_then(ImageFormat::from_mime_type).or_else(|| {
        let extension = path.extension()?.to_str()?.to_ascii_lowercase();
        match extension.as_str() {
            "png" => Some(ImageFormat::Png),
            "jpg" | "jpeg" => Some(ImageFormat::Jpeg),
            "gif" => Some(ImageFormat::Gif),
            "webp" => Some(ImageFormat::Webp),
            "svg" => Some(ImageFormat::Svg),
            "bmp" => Some(ImageFormat::Bmp),
            "tif" | "tiff" => Some(ImageFormat::Tiff),
            "ico" => Some(ImageFormat::Ico),
            "pbm" | "pgm" | "ppm" | "pnm" => Some(ImageFormat::Pnm),
            _ => None,
        }
    })
}

fn encode_editor_image(image: &image::RgbaImage) -> image::ImageResult<Vec<u8>> {
    let mut bytes = Cursor::new(Vec::new());
    image::DynamicImage::ImageRgba8(image.clone()).write_to(&mut bytes, image::ImageFormat::Png)?;
    Ok(bytes.into_inner())
}

fn decode_attachment_editor_image(path: &Path) -> image::ImageResult<image::RgbaImage> {
    let mut decoder = image::ImageReader::open(path)?
        .with_guessed_format()?
        .into_decoder()?;
    let orientation = decoder.orientation()?;
    let mut image = image::DynamicImage::from_decoder(decoder)?;
    image.apply_orientation(orientation);
    Ok(image.to_rgba8())
}

fn fitted_attachment_preview_size(
    intrinsic_size: Option<(u32, u32)>,
    max_width: f32,
    max_height: f32,
) -> (f32, f32) {
    let Some((width, height)) = intrinsic_size.filter(|(width, height)| *width > 0 && *height > 0)
    else {
        return (max_width, max_height);
    };
    let width = width as f32;
    let height = height as f32;
    let scale = (max_width / width).min(max_height / height).min(1.0);
    (width * scale, height * scale)
}

fn attachment_image_preview_layout(
    intrinsic_size: Option<(u32, u32)>,
    zoom: f32,
    viewport_width: f32,
    viewport_height: f32,
) -> AttachmentImagePreviewLayout {
    let viewport_width = (viewport_width - IMAGE_PREVIEW_HORIZONTAL_PADDING * 2.0).max(80.0);
    let viewport_height = (viewport_height - IMAGE_PREVIEW_VERTICAL_PADDING * 2.0).max(80.0);
    let (base_width, base_height) =
        fitted_attachment_preview_size(intrinsic_size, viewport_width, viewport_height);
    AttachmentImagePreviewLayout {
        viewport_width,
        viewport_height,
        image_width: base_width * zoom,
        image_height: base_height * zoom,
    }
}

fn composer_image_hover_preview_max_size(viewport_width: f32, viewport_height: f32) -> (f32, f32) {
    (
        (viewport_width - COMPOSER_IMAGE_HOVER_PREVIEW_MARGIN * 2.0)
            .clamp(160.0, COMPOSER_IMAGE_HOVER_PREVIEW_MAX_WIDTH),
        (viewport_height - COMPOSER_IMAGE_HOVER_PREVIEW_MARGIN * 2.0)
            .clamp(120.0, COMPOSER_IMAGE_HOVER_PREVIEW_MAX_HEIGHT),
    )
}

fn clamp_attachment_preview_zoom(zoom: f32) -> f32 {
    zoom.clamp(IMAGE_PREVIEW_MIN_ZOOM, IMAGE_PREVIEW_MAX_ZOOM)
}

fn clamp_attachment_preview_pan(
    pan_x: f32,
    pan_y: f32,
    image_width: f32,
    image_height: f32,
    viewport_width: f32,
    viewport_height: f32,
) -> (f32, f32) {
    let max_x = ((image_width - viewport_width) / 2.0).max(0.0);
    let max_y = ((image_height - viewport_height) / 2.0).max(0.0);
    (pan_x.clamp(-max_x, max_x), pan_y.clamp(-max_y, max_y))
}

fn session_title_from_first_message(message: &str) -> Option<String> {
    normalize_agent_session_title(message)
}

/// The manager persists a newly created session with this default title when
/// the creation request carries no explicit title (the desktop keeps the
/// prompt-derived title unlocked so a later ACP title can replace it). Keep a
/// single source of truth for the desktop so optimistic titles can recognize
/// — and outlast — the fallback snapshot.
fn agent_session_fallback_title(agent_id: impl std::fmt::Display) -> String {
    format!("{agent_id} session")
}

fn title_bar_session_context_visible(
    active_tab: &str,
    new_session_open: bool,
    settings_open: bool,
    has_selected_session: bool,
) -> bool {
    active_tab == "agent" && !new_session_open && !settings_open && has_selected_session
}

fn truncate_title_bar_session_menu_title(title: &str) -> String {
    let characters = title.chars().collect::<Vec<_>>();
    if characters.len() <= TITLE_BAR_SESSION_MENU_TITLE_MAX_CHARS {
        return title.to_string();
    }
    characters[..TITLE_BAR_SESSION_MENU_TITLE_MAX_CHARS - 3]
        .iter()
        .collect::<String>()
        + "..."
}

fn worktree_assistance_prompt(operation: &GitWorktreeOperationRecord) -> String {
    const CONFLICT_LIMIT: usize = 256;
    const PROMPT_CHAR_LIMIT: usize = 64 * 1024;
    let source_branch = operation.branch.as_deref().unwrap_or("source");
    let target_branch = operation
        .detail
        .target_branch
        .as_deref()
        .unwrap_or("target");
    let source_head = operation
        .detail
        .expected_source_head
        .as_deref()
        .unwrap_or("unknown");
    let target_head = operation
        .detail
        .expected_target_head
        .as_deref()
        .unwrap_or("unknown");
    let mut lines = vec![
        "Help resolve the active Vibex-managed Git integration in this Workspace.".to_string(),
        format!("Operation: {}", operation.operation_id.as_str()),
        format!("Source: {source_branch} at {source_head}"),
        format!("Target: {target_branch} at {target_head}"),
        format!(
            "Strategy: {}",
            match operation.detail.merge_strategy {
                Some(vibex_core::GitWorktreeMergeStrategy::NoFfMerge) => "no-ff merge",
                Some(vibex_core::GitWorktreeMergeStrategy::RebaseAndMerge) => {
                    "rebase and fast-forward"
                }
                Some(vibex_core::GitWorktreeMergeStrategy::Unknown) | None => "unknown",
            }
        ),
        String::new(),
        "Conflict files:".to_string(),
    ];
    lines.extend(
        operation
            .detail
            .conflicts
            .iter()
            .take(CONFLICT_LIMIT)
            .map(|conflict| {
                format!(
                    "- {} [{}{}]",
                    conflict.path,
                    worktree_assistance_conflict_kind(conflict.kind),
                    if conflict.binary { ", binary" } else { "" }
                )
            }),
    );
    if operation.detail.conflicts.len() > CONFLICT_LIMIT {
        lines.push(format!(
            "- ... {} additional conflict(s) omitted from this bounded context",
            operation.detail.conflicts.len() - CONFLICT_LIMIT
        ));
    }
    lines.extend([
        String::new(),
        "Inspect the index and working tree, edit the resolution, and explain what you changed. You may use normal file and terminal tools in this Workspace.".to_string(),
        "Do not run git merge --continue, git merge --abort, commit the merge, reset, checkout another branch, archive, or discard the Worktree. The user owns staging review and final continue/abort through Vibex.".to_string(),
    ]);
    lines.join("\n").chars().take(PROMPT_CHAR_LIMIT).collect()
}

fn worktree_assistance_conflict_kind(kind: GitWorktreeConflictKind) -> &'static str {
    match kind {
        GitWorktreeConflictKind::BothModified => "both_modified",
        GitWorktreeConflictKind::BothAdded => "both_added",
        GitWorktreeConflictKind::DeletedBySource => "deleted_by_source",
        GitWorktreeConflictKind::DeletedByTarget => "deleted_by_target",
        GitWorktreeConflictKind::Binary => "binary",
        GitWorktreeConflictKind::Other => "other",
        GitWorktreeConflictKind::Unknown => "unknown",
    }
}

/// Loads the authority's workspaces as the project/workspace pairs the
/// workbench keeps in memory.
async fn list_workspace_records(
    backend: &BackendFacade,
) -> Option<Vec<(ProjectRecord, WorkspaceRecord)>> {
    backend
        .workspace()
        .list_workspaces()
        .await
        .ok()
        .map(|summaries| {
            summaries
                .into_iter()
                .map(|summary| (summary.project, summary.workspace))
                .collect()
        })
}

