fn wrap_runtime_provider_model_selection(index: usize, delta: isize, count: usize) -> usize {
    if count == 0 {
        return 0;
    }
    if delta < 0 {
        let steps = delta.unsigned_abs() % count;
        (index + count - steps) % count
    } else {
        index.saturating_add(delta as usize) % count
    }
}

