#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SidebarWorkspaceStatus {
    Running,
    Error,
    NeedsInput,
    UnreadCompletion,
    Complete,
}

fn sidebar_workspace_status(
    summary: vibex_desktop_model::WorkspaceAgentSummary,
    lifecycle_running: bool,
    lifecycle_error: bool,
    has_unread_completion: bool,
    awaiting_user: bool,
    turn_pending: bool,
) -> SidebarWorkspaceStatus {
    // A workspace holding a session that cannot move without the user is more
    // actionable than one that is merely busy, so the call to action wins over
    // the progress spinner.
    if awaiting_user || summary.needs_input > 0 {
        SidebarWorkspaceStatus::NeedsInput
    } else if summary.running > 0 || lifecycle_running || turn_pending {
        // `turn_pending` covers the window where the local dispatch is
        // optimistic and the summary still counts the session's previous
        // (possibly failed) state, so the workspace row agrees with the
        // session row it aggregates.
        SidebarWorkspaceStatus::Running
    } else if lifecycle_error || summary.failed > 0 {
        SidebarWorkspaceStatus::Error
    } else if has_unread_completion {
        SidebarWorkspaceStatus::UnreadCompletion
    } else {
        SidebarWorkspaceStatus::Complete
    }
}

/// The indicator an aggregate row shows for the sessions it stands for.
///
/// A workspace row and a collapsed group row answer the same question — "what
/// is the most actionable thing among my sessions" — so they draw it the same
/// way.
///
/// `auto_continue_enabled` recolors only the running ring, the same way a
/// session row's spinner turns green when that session continues on its own.
/// The other states keep their own colors: the ring is the one mark that says
/// "still working", so it is also the one mark that can say "and it will keep
/// going by itself".
fn sidebar_aggregate_status_indicator(
    status: SidebarWorkspaceStatus,
    auto_continue_enabled: bool,
    cx: &App,
) -> AnyElement {
    match status {
        SidebarWorkspaceStatus::Running => Spinner::status_indicator()
            .icon(Icon::new(IconName::LoaderCircle))
            .color(if auto_continue_enabled {
                cx.theme().success
            } else {
                cx.theme().primary
            })
            .xsmall()
            .into_any_element(),
        SidebarWorkspaceStatus::Error => sidebar_status_dot(cx.theme().danger),
        SidebarWorkspaceStatus::NeedsInput => sidebar_attention_glyph(cx).into_any_element(),
        SidebarWorkspaceStatus::UnreadCompletion => sidebar_status_dot(cx.theme().success),
        SidebarWorkspaceStatus::Complete => {
            sidebar_status_dot(cx.theme().sidebar_foreground.opacity(0.28))
        }
    }
}

fn sidebar_session_status_indicator(
    state: AgentSessionState,
    auto_continue_enabled: bool,
    cx: &App,
) -> AnyElement {
    match state {
        AgentSessionState::Running | AgentSessionState::Initializing => Spinner::status_indicator()
            .icon(Icon::new(IconName::LoaderCircle))
            .color(if auto_continue_enabled {
                cx.theme().success
            } else {
                cx.theme().primary
            })
            .xsmall()
            .into_any_element(),
        AgentSessionState::NeedsInput => sidebar_attention_glyph(cx).into_any_element(),
        AgentSessionState::Error => sidebar_status_dot(cx.theme().danger),
        AgentSessionState::Archived | AgentSessionState::Closed => {
            sidebar_status_dot(cx.theme().sidebar_foreground.opacity(0.35))
        }
        AgentSessionState::Idle => sidebar_status_dot(cx.theme().success.opacity(0.78)),
    }
}

/// Projects the state a sidebar row shows.
///
/// A locally dispatched turn is optimistic, so the row may show progress before
/// the authority reports `Running`. That optimism must not hide a session the
/// authority already parked on the user: the Agent is not working, it is
/// waiting for an answer.
///
/// A stale `Error` snapshot is a different case. A session that failed and was
/// then asked to work again keeps the failed state until the authority admits
/// the new turn, and the submission can spend a long time preparing its runtime
/// first. The rest of the surface (the Composer's generation status and the
/// live timeline turn) already treats the local dispatch as running, so the row
/// must not contradict them with a failure dot that no longer applies.
fn sidebar_session_display_state(
    persisted_state: AgentSessionState,
    locally_pending: bool,
) -> AgentSessionState {
    if locally_pending && persisted_state != AgentSessionState::NeedsInput {
        AgentSessionState::Running
    } else {
        persisted_state
    }
}

fn format_sidebar_session_time(
    timestamp_ms: i64,
    locale: locale::ResolvedLocale,
    strings: &'static Strings,
) -> String {
    let Some(local_time) = chrono::DateTime::<chrono::Utc>::from_timestamp_millis(timestamp_ms)
        .map(|timestamp| timestamp.with_timezone(&chrono::Local).naive_local())
    else {
        return String::new();
    };
    format_sidebar_session_time_at(
        local_time,
        chrono::Local::now().naive_local(),
        locale,
        strings,
    )
}

fn format_sidebar_session_time_at(
    local_time: chrono::NaiveDateTime,
    now: chrono::NaiveDateTime,
    locale: locale::ResolvedLocale,
    strings: &'static Strings,
) -> String {
    let days = now
        .date()
        .signed_duration_since(local_time.date())
        .num_days();
    if days <= 0 {
        return local_time.format("%H:%M").to_string();
    }
    if days == 1 {
        return strings.sidebar_yesterday.to_string();
    }
    if days < 7 {
        return match locale {
            locale::ResolvedLocale::En => format!("{days} days ago"),
            locale::ResolvedLocale::ZhCn => format!("{days} 天前"),
            locale::ResolvedLocale::ZhTw => format!("{days} 天前"),
        };
    }
    if days < 30 {
        let weeks = days / 7;
        return match locale {
            locale::ResolvedLocale::En => format!("{weeks} weeks ago"),
            locale::ResolvedLocale::ZhCn => format!("{weeks} 周前"),
            locale::ResolvedLocale::ZhTw => format!("{weeks} 週前"),
        };
    }
    local_time.format("%m/%d").to_string()
}

#[cfg(test)]
fn project_workspace_matches_search(
    project: &ProjectRecord,
    workspace: &WorkspaceRecord,
    normalized_query: &str,
) -> bool {
    normalized_query.is_empty()
        || [&project.name, &project.root_path, &workspace.root_path]
            .into_iter()
            .any(|value| value.to_lowercase().contains(normalized_query))
}

fn workspace_display_name(workspace_root: &str) -> String {
    std::path::Path::new(workspace_root)
        .file_name()
        .and_then(|name| name.to_str())
        .filter(|name| !name.is_empty())
        .unwrap_or(workspace_root)
        .to_string()
}

/// A caption button a client-side-decorated window can draw in its title bar.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum WindowControl {
    Minimize,
    Maximize,
    Close,
}

impl WindowControl {
    const fn element_id(self) -> &'static str {
        match self {
            Self::Minimize => "window-minimize",
            Self::Maximize => "window-maximize",
            Self::Close => "window-close",
        }
    }

    /// The system hit area Windows uses to run the caption command itself.
    const fn area(self) -> WindowControlArea {
        match self {
            Self::Minimize => WindowControlArea::Min,
            Self::Maximize => WindowControlArea::Max,
            Self::Close => WindowControlArea::Close,
        }
    }
}

/// Which edge of the title bar a caption cluster sits on.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum WindowControlSide {
    Left,
    Right,
}

/// The platform whose caption conventions the window follows.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum WindowControlPlatform {
    Linux,
    Windows,
    Macos,
    Web,
}

/// The caption buttons Vibex draws, split by title-bar edge.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
struct WindowControlLayout {
    left: Vec<WindowControl>,
    right: Vec<WindowControl>,
}

impl WindowControlLayout {
    /// The GNOME default order, used when the desktop expresses no preference.
    fn right_trio() -> Self {
        Self {
            left: Vec::new(),
            right: vec![
                WindowControl::Minimize,
                WindowControl::Maximize,
                WindowControl::Close,
            ],
        }
    }

    /// Drops buttons the window cannot perform. Closing always survives: a
    /// window can be removed even when the platform advertises nothing else.
    fn retain_supported(&mut self, capabilities: WindowControls) {
        let supported = |control: &WindowControl| match control {
            WindowControl::Minimize => capabilities.minimize,
            WindowControl::Maximize => capabilities.maximize,
            WindowControl::Close => true,
        };
        self.left.retain(supported);
        self.right.retain(supported);
    }
}

fn current_window_control_platform() -> WindowControlPlatform {
    if cfg!(target_os = "macos") {
        WindowControlPlatform::Macos
    } else if cfg!(target_os = "windows") {
        WindowControlPlatform::Windows
    } else if cfg!(target_family = "wasm") {
        WindowControlPlatform::Web
    } else {
        WindowControlPlatform::Linux
    }
}

/// Parses a desktop caption layout such as `appmenu:close` or
/// `:minimize,maximize,close` (GTK's `gtk-decoration-layout`).
///
/// The value is `left:right`, where each side is a comma-separated list of
/// button names. `None` means the value is not a layout Vibex can honor and the
/// caller keeps the platform default. Slots Vibex has no equivalent for
/// (`icon`, `appmenu`, `menu`, `spacer*`) are skipped, because desktops append
/// their own slots to the layout.
fn parse_window_control_layout(value: &str) -> Option<WindowControlLayout> {
    let (left, right) = value.split_once(':')?;
    Some(WindowControlLayout {
        left: parse_window_control_side(left),
        right: parse_window_control_side(right),
    })
}

fn parse_window_control_side(value: &str) -> Vec<WindowControl> {
    value
        .split(',')
        .filter_map(|entry| match entry.trim() {
            "minimize" => Some(WindowControl::Minimize),
            "maximize" => Some(WindowControl::Maximize),
            "close" => Some(WindowControl::Close),
            _ => None,
        })
        .collect()
}

/// Decides which caption buttons the workbench draws, following whoever owns the
/// caption on this platform.
///
/// Vibex never duplicates decoration the platform already draws. macOS keeps its
/// AppKit traffic lights, and a Linux compositor that answered the
/// `xdg-decoration` negotiation with server-side decorations paints its own, so
/// both get nothing. Linux draws the buttons the desktop asked for only when the
/// compositor negotiated client-side decorations; Windows keeps the right-hand
/// trio because GPUI turns those into system hit areas (`WindowControlArea`)
/// rather than negotiating decoration ownership.
fn resolve_window_controls(
    platform: WindowControlPlatform,
    client_decorated: bool,
    desktop_layout: Option<&str>,
    capabilities: WindowControls,
) -> WindowControlLayout {
    let mut layout = match platform {
        WindowControlPlatform::Macos | WindowControlPlatform::Web => WindowControlLayout::default(),
        WindowControlPlatform::Windows => WindowControlLayout::right_trio(),
        WindowControlPlatform::Linux => {
            if !client_decorated {
                WindowControlLayout::default()
            } else {
                desktop_layout
                    .and_then(parse_window_control_layout)
                    .unwrap_or_else(WindowControlLayout::right_trio)
            }
        }
    };
    layout.retain_supported(capabilities);
    layout
}

/// The caption layout for this window: the platform's ownership of the caption
/// plus, on Linux, the desktop's own button layout.
fn window_control_layout(window: &Window) -> WindowControlLayout {
    #[cfg(target_os = "linux")]
    let desktop_layout = linux_window_control_layout();
    #[cfg(not(target_os = "linux"))]
    let desktop_layout: Option<String> = None;

    resolve_window_controls(
        current_window_control_platform(),
        matches!(window.window_decorations(), Decorations::Client { .. }),
        desktop_layout.as_deref(),
        window.window_controls(),
    )
}

/// Reads the desktop's caption layout from GTK, where GNOME, KDE, XFCE, and
/// `~/.config/gtk-3.0/settings.ini` publish it.
///
/// GTK settings may only be read on the thread that initialized GTK, so an
/// uninitialized or foreign thread falls back to the default order.
#[cfg(target_os = "linux")]
fn linux_window_control_layout() -> Option<String> {
    use gtk::prelude::GtkSettingsExt as _;

    if !gtk::is_initialized() || !gtk::is_initialized_main_thread() {
        return None;
    }
    let layout = gtk::Settings::default()?.gtk_decoration_layout()?;
    let layout = layout.to_string();
    (!layout.trim().is_empty()).then_some(layout)
}

fn window_control_icon(control: WindowControl, maximized: bool) -> IconName {
    match control {
        WindowControl::Minimize => IconName::Minus,
        WindowControl::Maximize if maximized => IconName::WindowRestore,
        WindowControl::Maximize => IconName::WindowMaximize,
        WindowControl::Close => IconName::Close,
    }
}

/// One caption cluster. Its border faces the window content, so the cluster
/// reads as attached to the edge it sits on.
fn workbench_window_controls(
    side: WindowControlSide,
    controls: &[WindowControl],
    wide: bool,
    maximized: bool,
    cx: &App,
) -> AnyElement {
    let control_width = if wide {
        TITLE_BAR_WIDE_WINDOW_CONTROL_WIDTH
    } else {
        TITLE_BAR_NARROW_WINDOW_CONTROL_WIDTH
    };
    let element_id = match side {
        WindowControlSide::Left => "window-controls-left",
        WindowControlSide::Right => "window-controls-right",
    };

    h_flex()
        .id(element_id)
        .h_full()
        .flex_none()
        .items_stretch()
        .when(side == WindowControlSide::Left, |this| this.border_r_1())
        .when(side == WindowControlSide::Right, |this| this.border_l_1())
        .border_color(cx.theme().border)
        .bg(cx.theme().background)
        .children(
            controls
                .iter()
                .map(|control| window_control_button(*control, control_width, maximized, cx)),
        )
        .into_any_element()
}

fn window_control_button(
    control: WindowControl,
    width: f32,
    maximized: bool,
    cx: &App,
) -> AnyElement {
    let theme = cx.theme();
    let label = match control {
        WindowControl::Minimize => locale::text("Minimize", "最小化", "最小化"),
        WindowControl::Maximize if maximized => locale::text("Restore", "还原", "還原"),
        WindowControl::Maximize => locale::text("Maximize", "最大化", "最大化"),
        WindowControl::Close => locale::text("Close window", "关闭窗口", "關閉視窗"),
    };
    let closes_window = control == WindowControl::Close;
    let foreground = theme.foreground.opacity(0.7);
    let hover_background = if closes_window {
        theme.danger
    } else {
        theme.sidebar_accent
    };
    let hover_foreground = if closes_window {
        theme.danger_foreground
    } else {
        theme.sidebar_accent_foreground
    };
    let active_background = if closes_window {
        theme.danger
    } else {
        theme.sidebar_accent.opacity(0.8)
    };

    div()
        .id(control.element_id())
        .flex()
        .h_full()
        .w(px(width))
        .flex_none()
        .items_center()
        .justify_center()
        .text_color(foreground)
        .role(Role::Button)
        .aria_label(label)
        .tooltip(move |window, cx| Tooltip::new(label).build(window, cx))
        .hover(move |style| style.bg(hover_background).text_color(hover_foreground))
        .active(move |style| style.bg(active_background).text_color(hover_foreground))
        .when(cfg!(target_os = "windows"), |this| {
            this.window_control_area(control.area())
        })
        .when(!cfg!(target_os = "windows"), |this| {
            this.on_mouse_down(MouseButton::Left, |_, window, cx| {
                window.prevent_default();
                cx.stop_propagation();
            })
            .on_click(move |_, window, cx| {
                cx.stop_propagation();
                match control {
                    WindowControl::Minimize => window.minimize_window(),
                    WindowControl::Maximize => window.zoom_window(),
                    WindowControl::Close => window.remove_window(),
                }
            })
        })
        .child(Icon::new(window_control_icon(control, maximized)).size(px(16.0)))
        .into_any_element()
}

fn context_window_usage_fraction(usage: &AgentTokenUsage) -> Option<f32> {
    let used = usage.context_window_used_tokens?;
    let size = usage.context_window_size_tokens?;
    if size == 0 {
        return None;
    }
    Some(((used as f64 / size as f64).clamp(0.0, 1.0)) as f32)
}

fn cache_hit_fraction(usage: &AgentTokenUsage) -> Option<f32> {
    let input = usage.input_tokens?;
    let cached = usage.cached_read_tokens?;
    let total = input.saturating_add(cached);
    if total == 0 {
        return Some(0.0);
    }
    Some((cached as f64 / total as f64) as f32)
}

fn token_usage_percent(fraction: f32) -> u32 {
    (fraction.clamp(0.0, 1.0) * 100.0).round() as u32
}

fn format_compact_tokens(tokens: u64) -> String {
    if tokens >= 1_000_000 {
        format!("{:.1}m", tokens as f64 / 1_000_000.0)
    } else if tokens >= 1_000 {
        format!("{:.1}k", tokens as f64 / 1_000.0)
    } else {
        tokens.to_string()
    }
}

fn render_cache_token_ring(usage: Option<&AgentTokenUsage>, cx: &mut App) -> AnyElement {
    let is_dark = cx.theme().is_dark();
    let context_fraction = usage.and_then(context_window_usage_fraction);
    // `ProgressCircle` paints its track from the progress color at reduced
    // opacity, so the unreported state keeps the full muted-foreground tone to
    // leave a visible empty ring.
    let progress_color = match context_fraction {
        Some(fraction) if fraction > 0.9 => theme::semantic_color("destructive", is_dark),
        Some(fraction) if fraction >= 0.7 => theme::semantic_color("warning", is_dark),
        _ => theme::semantic_color("muted-foreground", is_dark),
    };
    let context_percent = context_fraction.unwrap_or(0.0).clamp(0.0, 1.0) * 100.0;
    let overview_label = locale::text("Token usage", "Token 使用情况", "Token 使用情況");
    let context_value = match usage.and_then(|usage| {
        Some((
            context_window_usage_fraction(usage)?,
            usage.context_window_used_tokens?,
            usage.context_window_size_tokens?,
        ))
    }) {
        Some((fraction, used, size)) => match locale::current_locale() {
            locale::ResolvedLocale::En => format!(
                "Context {}% · {} / {}",
                token_usage_percent(fraction),
                format_compact_tokens(used),
                format_compact_tokens(size)
            ),
            locale::ResolvedLocale::ZhCn => format!(
                "上下文 {}% · {} / {}",
                token_usage_percent(fraction),
                format_compact_tokens(used),
                format_compact_tokens(size)
            ),
            locale::ResolvedLocale::ZhTw => format!(
                "上下文 {}% · {} / {}",
                token_usage_percent(fraction),
                format_compact_tokens(used),
                format_compact_tokens(size)
            ),
        },
        None => locale::text(
            "Context window not reported",
            "Agent 未上报上下文窗口",
            "Agent 未回報上下文視窗",
        )
        .to_string(),
    };
    let cache_value = match usage {
        Some(usage) if usage.cached_read_tokens.is_some() => {
            let cached_read = usage.cached_read_tokens.unwrap_or_default();
            let cached_write = usage.cached_write_tokens;
            let hit_prefix = cache_hit_fraction(usage)
                .map(|fraction| format!("{}% · ", token_usage_percent(fraction)))
                .unwrap_or_default();
            match (locale::current_locale(), cached_write) {
                (locale::ResolvedLocale::En, Some(written)) => format!(
                    "Cache {hit_prefix}{} read · {} written",
                    format_compact_tokens(cached_read),
                    format_compact_tokens(written)
                ),
                (locale::ResolvedLocale::En, None) => {
                    format!(
                        "Cache {hit_prefix}{} read",
                        format_compact_tokens(cached_read)
                    )
                }
                (locale::ResolvedLocale::ZhCn, Some(written)) => format!(
                    "缓存 {hit_prefix}读取 {} · 写入 {}",
                    format_compact_tokens(cached_read),
                    format_compact_tokens(written)
                ),
                (locale::ResolvedLocale::ZhCn, None) => format!(
                    "缓存 {hit_prefix}读取 {}",
                    format_compact_tokens(cached_read)
                ),
                (locale::ResolvedLocale::ZhTw, Some(written)) => format!(
                    "快取 {hit_prefix}讀取 {} · 寫入 {}",
                    format_compact_tokens(cached_read),
                    format_compact_tokens(written)
                ),
                (locale::ResolvedLocale::ZhTw, None) => format!(
                    "快取 {hit_prefix}讀取 {}",
                    format_compact_tokens(cached_read)
                ),
            }
        }
        _ => locale::text(
            "Cache usage not reported",
            "Agent 未上报缓存用量",
            "Agent 未回報快取用量",
        )
        .to_string(),
    };
    div()
        .id("composer-cache-token-ring")
        .flex_none()
        .size(px(28.0))
        .flex()
        .items_center()
        .justify_center()
        .child(
            ProgressCircle::new("composer-cache-token-ring-progress")
                .value(context_percent)
                .color(progress_color),
        )
        .tooltip(move |window, cx| {
            let context_value = context_value.clone();
            let cache_value = cache_value.clone();
            Tooltip::element(move |_, cx| {
                v_flex()
                    .gap(px(2.0))
                    .text_xs()
                    .child(div().font_medium().child(overview_label))
                    .child(
                        div()
                            .text_color(cx.theme().popover_foreground.opacity(0.75))
                            .child(context_value.clone()),
                    )
                    .child(
                        div()
                            .text_color(cx.theme().popover_foreground.opacity(0.75))
                            .child(cache_value.clone()),
                    )
            })
            .build(window, cx)
        })
        .into_any_element()
}

// Tauri parity: `MobilePairIcon` gradient stops oklch(0.7 0.24 25) / (0.84 0.22 90) /
// (0.76 0.22 150) / (0.72 0.22 220) converted to sRGB.
const MOBILE_PAIR_GRADIENT: [u32; 4] = [0xff464a, 0xffc000, 0x00d55e, 0x00beff];
const MOBILE_PAIR_GRADIENT_DURATION: Duration = Duration::from_millis(2400);

fn mobile_pair_gradient_color(position: f32) -> Hsla {
    let wrapped = position.rem_euclid(MOBILE_PAIR_GRADIENT.len() as f32);
    let index = wrapped.floor() as usize % MOBILE_PAIR_GRADIENT.len();
    let next = (index + 1) % MOBILE_PAIR_GRADIENT.len();
    let fraction = wrapped.fract();
    let from = rgb(MOBILE_PAIR_GRADIENT[index]);
    let to = rgb(MOBILE_PAIR_GRADIENT[next]);
    Hsla::from(Rgba {
        r: from.r + (to.r - from.r) * fraction,
        g: from.g + (to.g - from.g) * fraction,
        b: from.b + (to.b - from.b) * fraction,
        a: 1.0,
    })
}

fn composite_over(source: Hsla, destination: Hsla) -> Hsla {
    let source = Rgba::from(source);
    let destination = Rgba::from(destination);
    let alpha = source.a;
    Hsla::from(Rgba {
        r: source.r * alpha + destination.r * (1.0 - alpha),
        g: source.g * alpha + destination.g * (1.0 - alpha),
        b: source.b * alpha + destination.b * (1.0 - alpha),
        a: 1.0,
    })
}

fn mobile_pair_icon(hovered: bool, cx: &App) -> AnyElement {
    // Tauri parity: 24-unit viewBox phone at 20px display size — outer bounds
    // 13.33 x 18.33, stroke 1.67, corner radius 2.5, dot centered near the bottom.
    let width = px(13.33);
    let height = px(18.33);
    let border = px(1.67);
    let radius = px(2.5);
    let dot_size = px(1.8);
    let dot_left = px((13.33 - 1.8) / 2.0);
    let dot_bottom = px(2.4);
    let foreground = cx.theme().foreground;
    if !hovered {
        return div()
            .relative()
            .w(width)
            .h(height)
            .rounded(radius)
            .border(border)
            .border_color(foreground.opacity(0.75))
            .child(
                div()
                    .absolute()
                    .bottom(px(2.4 - 1.67))
                    .left(px((13.33 - 1.8) / 2.0 - 1.67))
                    .size(dot_size)
                    .rounded_full()
                    .bg(foreground.opacity(0.75)),
            )
            .into_any_element();
    }
    // Hover: the border fades into a moving four-stop gradient (Tauri animates the
    // gradient transform over 2.4s). Simulated with a gradient-filled outer layer
    // and an interior filled with the ghost-hover background composited over the
    // title bar, leaving a 1.67px gradient ring.
    let hover_background = if cx.theme().is_dark() {
        cx.theme().secondary.lighten(0.1).opacity(0.8)
    } else {
        cx.theme().secondary.darken(0.1).opacity(0.8)
    };
    let interior = composite_over(hover_background, cx.theme().sidebar);
    div()
        .relative()
        .w(width)
        .h(height)
        .child(
            div().absolute().inset_0().rounded(radius).with_animation(
                "mobile-pair-gradient",
                Animation::new(MOBILE_PAIR_GRADIENT_DURATION)
                    .repeat()
                    .with_max_fps(REPEATING_ANIMATION_MAX_FPS),
                move |this, delta| {
                    let position = delta * MOBILE_PAIR_GRADIENT.len() as f32;
                    this.bg(linear_gradient(
                        135.0,
                        linear_color_stop(mobile_pair_gradient_color(position), 0.0),
                        linear_color_stop(mobile_pair_gradient_color(position + 1.0), 1.0),
                    ))
                },
            ),
        )
        .child(
            div()
                .absolute()
                .top(border)
                .left(border)
                .right(border)
                .bottom(border)
                .rounded(px(1.2))
                .bg(interior),
        )
        .child(
            div()
                .absolute()
                .bottom(dot_bottom)
                .left(dot_left)
                .size(dot_size)
                .rounded_full()
                .bg(foreground.opacity(0.9)),
        )
        .into_any_element()
}

