    fn set_locale(&mut self, mode: LocaleMode, window: &mut Window, cx: &mut Context<Self>) {
        let _ = self
            .workbench
            .update(cx, |this, cx| this.set_locale(mode, window, cx));
        let settings = cx.weak_entity();
        window.defer(cx, move |window, cx| {
            let _ = settings.update(cx, |this, cx| {
                let appearance = this.appearance(cx);
                let session = this.session(cx);
                let terminal_preferences = this.terminal_preferences(cx);
                let network_proxy = this.network_proxy(cx);
                this.sync_controls(
                    &appearance,
                    &session,
                    &terminal_preferences,
                    &network_proxy,
                    window,
                    cx,
                );
            });
        });
        cx.notify();
    }

