    #[test]
    fn shimmer_scan_reaches_each_glyph_and_falls_back_to_the_base_color() {
        let base = Hsla {
            h: 0.0,
            s: 0.0,
            l: 0.25,
            a: 0.75,
        };
        let glow = Hsla {
            h: 0.0,
            s: 0.0,
            l: 1.0,
            a: 1.0,
        };

        assert_eq!(shimmer_color(base, glow, 0.5, 0.5, 0.42), glow);
        assert_eq!(shimmer_color(base, glow, 0.0, 1.0, 0.42), base);
        assert_eq!(shimmer_scan_position(0.0, 0.0, 1.0), -0.35);
    }

    #[test]
    fn agent_thinking_indicator_shimmers_without_scrolling_and_keeps_full_tooltip() {
        let source = include_str!("app.rs");
        let renderer = source
            .split_once("fn render_agent_thinking_indicator(")
            .and_then(|(_, tail)| tail.split_once("\nfn tool_card_projection("))
            .map(|(body, _)| body)
            .expect("thinking indicator renderer should remain inspectable");

        assert!(renderer.contains("ShimmerText::new(label)"));
        assert!(renderer.contains("truncate_agent_thinking_label(label)"));
        assert!(renderer.contains("AGENT_THINKING_SHIMMER_SWEEP"));
        assert!(renderer.contains("AGENT_THINKING_SHIMMER_SPREAD"));
        assert!(!renderer.contains("ScrollHandle"));
        assert!(!renderer.contains("set_offset"));
        assert!(!renderer.contains("overflow_x_scroll"));
        assert!(renderer.contains("Tooltip::new(tooltip.clone())"));
        // The sweep repeats for as long as it is mounted, so it only runs for a
        // turn that is actually in flight. A row's `streaming` flag outlives an
        // interrupted turn, and a shimmer left running there kept every pane
        // holding that session repainting at frame rate.
        assert!(renderer.contains("let body: AnyElement = if live {"));
        let production = source
            .split_once("\n#[cfg(test)]\nmod tests {")
            .map(|(body, _)| body)
            .unwrap_or(source);
        assert_eq!(
            production
                .matches("let live = self.borrowed_session_turn_is_live();")
                .count(),
            3,
            "every shimmer site must ask whether the turn is actually live"
        );
        let live = source
            .split_once("    fn borrowed_session_turn_is_live(")
            .and_then(|(_, tail)| tail.split_once("\n    fn live_turn_pending("))
            .map(|(body, _)| body)
            .expect("the live-turn helper should remain inspectable");
        assert!(live.contains("agent_turn_is_active"));
        assert!(live.contains("self.live_agent_session_state()"));
    }

