    #[test]
    fn conversation_find_registers_local_search_navigation_and_focus_order() {
        let source = include_str!("app.rs");
        let shortcuts = source
            .split_once("const FOUNDATION_SHORTCUTS")
            .and_then(|(_, tail)| tail.split_once("fn shortcut_action_label"))
            .map(|(body, _)| body)
            .expect("foundation shortcuts should remain inspectable");
        assert!(shortcuts.contains("(\"open_conversation_find\", \"cmd-f\")"));

        let workbench = source
            .split_once(".id(\"vibex-foundation\")")
            .and_then(|(_, tail)| tail.split_once(".on_drag_move("))
            .map(|(body, _)| body)
            .expect("workbench keyboard handlers should remain inspectable");
        assert!(workbench.contains(".capture_key_down("));
        assert!(workbench.contains("modifiers.control || modifiers.platform"));
        assert!(workbench.contains("this.open_conversation_find(window, cx)"));

        // Find follows the keyboard. The file editor binds the same chord for
        // its own find, but this workbench's binding is registered after the
        // component's and therefore outranks it, so the editor has to be asked
        // first or the conversation's find opens over the file being read.
        let opener = source
            .split_once("    fn open_conversation_find(")
            .and_then(|(_, tail)| tail.split_once("\n    fn close_conversation_find("))
            .map(|(body, _)| body)
            .expect("conversation find opener should remain inspectable");
        let delegate = opener
            .find("workbench.open_focused_editor_find(window, cx)")
            .expect("the opener should offer the chord to the focused editor");
        let context = opener
            .find("if !self.conversation_context_active() {")
            .expect("the opener should still require a conversation");
        assert!(delegate < context);

        let renderer = source
            .split_once("    fn render_conversation_find(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_timeline_turn("))
            .map(|(body, _)| body)
            .expect("conversation find renderer should remain inspectable");
        let input = renderer
            .find("Input::new(&self.conversation_find)")
            .expect("find input should render");
        let previous = renderer
            .find("Button::new(\"conversation-find-previous\")")
            .expect("previous control should render");
        let next = renderer
            .find("Button::new(\"conversation-find-next\")")
            .expect("next control should render");
        let close = renderer
            .find("Button::new(\"conversation-find-close\")")
            .expect("close control should render");
        assert!(input < previous && previous < next && next < close);
        assert!(renderer.contains("self.conversation_find_matches(cx).len()"));

        let highlights = source
            .split_once("    fn session_search_highlight_for_rows")
            .and_then(|(_, tail)| tail.split_once("\n    fn session_search_highlighted_row_text"))
            .map(|(body, _)| body)
            .expect("timeline highlighting should remain inspectable");
        assert!(highlights.contains("self.conversation_find_open"));
        assert!(highlights.contains("session_search_match_ranges"));
        // Tool activity is not searchable, so a query that only appears in it
        // must not tint the row.
        assert!(highlights.contains("timeline_row_is_search_text(row.kind)"));
        // A group pane highlights only when it is the conversation the bar
        // searches, which is the one the borrowed view belongs to.
        assert!(
            highlights
                .contains("self.timeline.session_id.as_ref() == self.selected_session_id.as_ref()")
        );

        let reveal = source
            .split_once("    fn highlight_session_search_rows(")
            .and_then(|(_, tail)| {
                tail.split_once("\n    fn session_search_reveal_pending_for_rows(")
            })
            .map(|(body, _)| body)
            .expect("timeline reveal wrapper should remain inspectable");
        // The wrapper exists to scroll the active match into view; it must not
        // paint a background, which used to bury the keyword in a yellow block.
        assert!(!reveal.contains(".bg("));
        assert!(reveal.contains(".on_prepaint("));
    }

    #[test]
    fn session_search_match_ranges_highlight_all_case_insensitive_unicode_matches() {
        let text = "Alpha alpha İSTANBUL";
        let matches = session_search_match_ranges(text, "ALPHA")
            .into_iter()
            .map(|range| &text[range])
            .collect::<Vec<_>>();
        assert_eq!(matches, ["Alpha", "alpha"]);

        let unicode_match = session_search_match_ranges(text, "i")
            .into_iter()
            .next()
            .expect("lowercase expansion should map back to the original character");
        assert_eq!(&text[unicode_match], "İ");
    }

    #[test]
    fn session_search_match_ranges_search_in_place_when_folding_cannot_move_offsets() {
        // ASCII documents are matched case-insensitively without folding a
        // copy of the text.
        let text = "Read the README, then read the docs";
        let matches = session_search_match_ranges(text, "read")
            .into_iter()
            .map(|range| &text[range])
            .collect::<Vec<_>>();
        assert_eq!(matches, ["Read", "READ", "read"]);

        let limited = session_search_match_ranges_with_limit(text, "read", 2);
        assert_eq!(limited.len(), 2);

        // Case-less documents fold to themselves, so they match in place too.
        let text = "会话搜索索引: 搜索会话和消息内容";
        let matches = session_search_match_ranges(text, "搜索")
            .into_iter()
            .map(|range| &text[range])
            .collect::<Vec<_>>();
        assert_eq!(matches, ["搜索", "搜索"]);
    }

    #[test]
    fn compact_session_search_text_collapses_whitespace_without_a_word_vector() {
        assert_eq!(compact_session_search_text("  a\n\n b\tc  "), "a b c");
        assert_eq!(compact_session_search_text("   "), "");
    }

    #[test]
    fn session_search_reveal_delta_scrolls_the_match_just_into_view() {
        let viewport = Bounds::new(point(px(0.0), px(100.0)), size(px(600.0), px(400.0)));
        let row = |top: f32, height: f32| {
            Bounds::new(point(px(0.0), px(top)), size(px(600.0), px(height)))
        };

        // Already visible, including inside the reveal margin: nothing moves,
        // and a row that fits ignores where inside it the keyword sits.
        for aim in [0.0, 0.5, 1.0] {
            assert_eq!(
                session_search_reveal_delta(row(200.0, 60.0), viewport, aim),
                px(0.0)
            );
            assert_eq!(
                session_search_reveal_delta(row(130.0, 60.0), viewport, aim),
                px(0.0)
            );
        }

        // Above the viewport scrolls down, below it scrolls up, and both land
        // the row on the margin rather than on the edge.
        assert_eq!(
            session_search_reveal_delta(row(40.0, 60.0), viewport, 0.0),
            px(84.0)
        );
        assert_eq!(
            session_search_reveal_delta(row(470.0, 60.0), viewport, 0.0),
            px(-54.0)
        );

        // A row taller than the viewport cannot be shown whole, so the reveal
        // aims the keyword at the upper quarter of the viewport: the estimate
        // is where the match sits in the row's text.
        assert_eq!(
            session_search_reveal_delta(row(300.0, 900.0), viewport, 0.0),
            px(-88.0)
        );
        assert_eq!(
            session_search_reveal_delta(row(300.0, 900.0), viewport, 0.5),
            px(-538.0)
        );
        assert_eq!(
            session_search_reveal_delta(row(300.0, 900.0), viewport, 1.0),
            px(-988.0)
        );
    }

    #[test]
    fn session_search_match_aim_measures_characters_not_bytes() {
        // "目标" starts two characters into a six-character row, but two bytes
        // into a ten-byte one: the aim has to follow the characters, or a CJK
        // row would reveal the wrong line.
        let text = "ab目标cd";
        assert!((session_search_match_aim(text, "目标", 0) - 1.0 / 3.0).abs() < 1e-6);
        assert_eq!(session_search_match_aim(text, "ab", 0), 0.0);
        assert_eq!(session_search_match_aim(text, "missing", 0), 0.0);
        assert_eq!(session_search_match_aim("", "目标", 0), 0.0);
    }

    #[test]
    fn session_search_match_aim_walks_the_ordinal_through_one_row() {
        // Two hits in one row aim at different lines, so stepping to the next
        // match moves inside a message instead of standing still on its first
        // occurrence.
        let text = "目标一二三四五六七八九十目标";
        let first = session_search_match_aim(text, "目标", 0);
        let second = session_search_match_aim(text, "目标", 1);
        assert_eq!(first, 0.0);
        assert!(second > 0.7, "second hit should sit near the end: {second}");

        // An ordinal past the row's hits falls back to the first one rather
        // than dropping the highlight.
        assert_eq!(session_search_match_aim(text, "目标", 9), first);
    }

    #[test]
    fn session_search_documents_keep_timeline_jump_identity() {
        let session_id = VibexSessionId::parse("session_search").unwrap();
        let user_item_id = TimelineItemId::new();
        let agent_item_id = TimelineItemId::new();
        let timeline_item = |id: TimelineItemId,
                             sequence: i64,
                             timestamp_ms: i64,
                             source: TimelineSource,
                             payload: TimelinePayload| {
            let kind = payload.kind();
            TimelineItem {
                id,
                session_id: session_id.clone(),
                sequence,
                timestamp_ms,
                source,
                kind,
                correlation_id: None,
                provider_correlation_id: None,
                redaction_state: TimelineRedactionState::None,
                execution_attribution: None,
                payload,
            }
        };
        let documents = session_search_documents(&[
            timeline_item(
                user_item_id.clone(),
                7,
                100,
                TimelineSource::User,
                TimelinePayload::UserMessage(UserMessagePayload {
                    text: "查找这段用户内容".into(),
                    attachments: Vec::new(),
                    ..Default::default()
                }),
            ),
            timeline_item(
                agent_item_id.clone(),
                8,
                120,
                TimelineSource::Agent,
                TimelinePayload::AgentMessage(AgentMessagePayload {
                    text: "这是对应的回答".into(),
                    is_final: true,
                }),
            ),
            timeline_item(
                TimelineItemId::new(),
                9,
                140,
                TimelineSource::Agent,
                TimelinePayload::ToolCall(vibex_core::ToolCallPayload {
                    tool_call_id: "call-1".into(),
                    tool_name: "job_output".into(),
                    status: vibex_core::ToolCallStatus::Completed,
                    summary: "job_output 找到了 查找这段用户内容".into(),
                    input_summary: None,
                    output_summary: None,
                    raw_extension: None,
                }),
            ),
        ]);

        // Tool activity is not searchable content: the tool call above repeats
        // the user's query, and it still produces no document to match on.
        assert_eq!(documents.len(), 2);
        assert_eq!(documents[0].item_id.as_deref(), Some(user_item_id.as_str()));
        assert_eq!(documents[0].first_sequence, 7);
        assert_eq!(documents[0].timestamp_ms, 100);
        assert!(documents[0].text.contains("查找这段用户内容"));
        assert_eq!(
            documents[1].item_id.as_deref(),
            Some(agent_item_id.as_str())
        );
        assert_eq!(documents[0].turn_id, documents[1].turn_id);
    }

    #[test]
    fn command_palette_replaces_the_sidebar_search_with_workbench_chrome() {
        let source = include_str!("app.rs");
        let sidebar = source
            .split_once("    fn render_agent_sidebar(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_sidebar_project("))
            .map(|(body, _)| body)
            .expect("sidebar renderer should remain inspectable");
        assert!(!sidebar.contains("Input::new(&self.session_search)"));
        // The palette searches sessions, settings, and actions, so its entry
        // point sits in the title bar with the other workbench-wide controls
        // rather than inside one project's toolbar.
        assert!(!sidebar.contains("sidebar-search-sessions"));

        let title_bar = source
            .split_once("    fn render_title_bar(")
            .and_then(|(_, tail)| tail.split_once("\n    fn build_title_session_menu("))
            .map(|(body, _)| body)
            .expect("title bar should remain inspectable");
        let search = title_bar
            .find("Button::new(\"open-command-palette\")")
            .expect("the palette trigger should be in the title bar");
        let runtime = title_bar
            .find(".id(\"runtime-manager-hover\")")
            .expect("the runtime control should be in the title bar");
        assert!(
            search < runtime,
            "the palette trigger belongs immediately before the runtime control"
        );
        assert!(title_bar.contains("this.toggle_command_palette(window, cx)"));

        let overlay = source
            .split_once("    fn render_command_palette_overlay(")
            .and_then(|(_, tail)| tail.split_once("\n    fn update_docked_panel_animation("))
            .map(|(body, _)| body)
            .expect("palette overlay should remain inspectable");
        assert!(overlay.contains("Command::new(&self.command_palette)"));
        assert!(overlay.contains(".absolute()"));
        assert!(overlay.contains(".inset_0()"));
        // The command surface paints its own background, and GPUI only clips
        // children to a square, so it has to round the frame's corners itself.
        assert!(overlay.contains(".rounded(px(COMMAND_PALETTE_DIALOG_CONTENT_RADIUS))"));
        assert!(overlay.contains(".rounded(px(COMMAND_PALETTE_DIALOG_RADIUS))"));
        assert!(overlay.contains("CommandGroup::new()"));
        assert!(overlay.contains("skeleton_session_search(cx)"));
        assert!(overlay.contains("strings.command_palette_hint"));
        assert!(!overlay.contains("count_label"));
        // Matched rows tint the keyword through their Markdown views, and the
        // find bar's current match is marked active so it paints stronger.
        assert!(source.contains(".search_query("));
        assert!(source.contains(".search_active("));
        assert!(source.contains("MarkdownView::new("));

        let rows = source
            .split_once("fn command_palette_row(")
            .and_then(|(_, tail)| tail.split_once("\nfn wrap_settings_search_selection("))
            .map(|(body, _)| body)
            .expect("palette row builder should remain inspectable");
        assert!(rows.contains("session_search_highlighted_text"));
        assert!(rows.contains("agent_brand_icon"));
        assert!(rows.contains("settings_section_label"));
        assert!(rows.contains("command_palette_action(action)"));

        let workbench_render = source
            .split_once("impl Render for VibexWorkbench")
            .map(|(_, body)| body)
            .expect("workbench renderer should remain inspectable");
        assert!(workbench_render.contains("clear_session_search_highlight"));

        let load = source
            .split_once("    fn load_agent_session_timeline(")
            .and_then(|(_, tail)| tail.split_once("\n    fn refresh_selected_agent_timeline("))
            .map(|(body, _)| body)
            .expect("timeline loader should remain inspectable");
        let jump = load
            .find("this.apply_pending_session_search_jump(cx)")
            .expect("search jump should run after timeline loading");
        let bottom = load
            .find("this.request_timeline_scroll_to_latest()")
            .expect("normal timeline loading should still follow the bottom");
        assert!(jump < bottom);
    }

    #[test]
    fn token_usage_overview_calculates_context_and_cache_independently() {
        let usage = AgentTokenUsage {
            input_tokens: Some(600),
            cached_read_tokens: Some(1_400),
            context_window_used_tokens: Some(50_000),
            context_window_size_tokens: Some(200_000),
            ..AgentTokenUsage::default()
        };

        assert_eq!(context_window_usage_fraction(&usage), Some(0.25));
        assert_eq!(cache_hit_fraction(&usage), Some(0.7));
        assert_eq!(token_usage_percent(0.256), 26);
    }

    #[test]
    fn token_usage_overview_clamps_overflow_and_handles_missing_data() {
        let overflow = AgentTokenUsage {
            context_window_used_tokens: Some(250_000),
            context_window_size_tokens: Some(200_000),
            ..AgentTokenUsage::default()
        };
        assert_eq!(context_window_usage_fraction(&overflow), Some(1.0));
        assert_eq!(cache_hit_fraction(&overflow), None);

        let empty_cache = AgentTokenUsage {
            input_tokens: Some(0),
            cached_read_tokens: Some(0),
            ..AgentTokenUsage::default()
        };
        assert_eq!(cache_hit_fraction(&empty_cache), Some(0.0));
        assert_eq!(format_compact_tokens(999), "999");
        assert_eq!(format_compact_tokens(12_500), "12.5k");
        assert_eq!(format_compact_tokens(2_000_000), "2.0m");
    }

