    #[test]
    fn composer_command_detection_requires_a_collapsed_selection() {
        let text = "prefix @src/文件";
        let caret = text.len();
        let trigger = composer_trigger_for_selection(text, caret..caret).unwrap();
        assert_eq!(trigger.query, "src/文件");
        assert!(composer_trigger_for_selection(text, 7..caret).is_none());
    }

    #[test]
    fn selected_slash_entry_controls_command_execution_identity() {
        let prompt = command_entry(
            AgentCommandSourceKind::Prompt,
            AgentCommandTrigger::Slash,
            Some("review"),
        );
        let invocation =
            resolve_composer_command_invocation("/review staged", Some(&prompt), false).unwrap();
        assert_eq!(invocation.command_id.as_deref(), Some("command:test"));
        assert_eq!(invocation.source_kind, AgentCommandSourceKind::Prompt);
        assert_eq!(invocation.arguments.as_deref(), Some("staged"));
        assert!(command_entry_matches_draft("/review staged", Some(&prompt)));
        assert!(!command_entry_matches_draft("/other staged", Some(&prompt)));

        let reference = command_entry(
            AgentCommandSourceKind::Reference,
            AgentCommandTrigger::Mention,
            None,
        );
        assert!(resolve_composer_command_invocation("/review", Some(&reference), true).is_none());
    }

    #[test]
    fn manual_slash_execution_requires_provider_capability() {
        assert!(resolve_composer_command_invocation("/review", None, false).is_none());
        let invocation = resolve_composer_command_invocation("/review", None, true).unwrap();
        assert_eq!(invocation.command_id, None);
        assert_eq!(invocation.source_kind, AgentCommandSourceKind::Provider);
        assert_eq!(invocation.command_name.as_deref(), Some("review"));
    }

    fn new_session_runtime_option(agent: &str, label: &str) -> SessionRuntimeOption {
        let agent_id = AgentId::parse(agent).unwrap();
        SessionRuntimeOption {
            selection: SessionRuntimeSelection::provider(
                agent_id,
                ProviderProfileId::parse(format!("provider_{agent}")).unwrap(),
                format!("{agent}_model"),
            ),
            agent_label: label.into(),
            auth_source_label: format!("{label} profile"),
            model_label: format!("{label} model"),
            reasoning_efforts: vec![SessionConfigValue {
                value: "high".into(),
                label: Some("High".into()),
            }],
            modes: vec![SessionConfigValue {
                value: "default".into(),
                label: Some("Default".into()),
            }],
            features: Vec::new(),
            availability: RuntimeOptionAvailability::Available,
        }
    }

    fn runtime_profile_summary(
        agent_id: AgentId,
        configured_models: Vec<vibex_core::ProviderConfiguredModel>,
    ) -> ProviderProfileSummary {
        ProviderProfileSummary {
            id: ProviderProfileId::new(),
            agent_id,
            kind: vibex_core::ProviderKind::Acp,
            display_name: "Test provider".into(),
            status: ProviderProfileStatus::Enabled,
            account_alias: None,
            default_model: None,
            configured_models,
            secret_setup_state: vibex_core::ProviderSecretSetupState::Available,
            updated_at_ms: 1,
        }
    }

    fn inline_composer_attachment(serial: u64, label: &str) -> InlineComposerAttachment {
        InlineComposerAttachment {
            attachment: ComposerAttachment {
                id: format!("attachment:{serial}"),
                label: label.into(),
                path: Some(format!("/tmp/{label}.png")),
                mime_type: Some("image/png".into()),
            },
            marker: inline_composer_attachment_marker(serial),
        }
    }

    fn message_attachment(label: &str, inline_text_offset: Option<u32>) -> MessageAttachment {
        MessageAttachment {
            label: label.into(),
            mime_type: Some("image/png".into()),
            uri: Some(format!("file:///tmp/{label}.png")),
            inline_text_offset,
        }
    }

    fn terminal_session(id: &str, workspace_id: &WorkspaceId) -> TerminalSession {
        TerminalSession {
            id: TerminalId::parse(id).unwrap(),
            workspace_id: workspace_id.clone(),
            title: id.to_string(),
            shell: "/bin/sh".to_string(),
            cwd: "/tmp".to_string(),
            rows: 24,
            cols: 80,
            status: TerminalStatus::Running,
            created_at_ms: 1,
            updated_at_ms: 1,
            closed_at_ms: None,
        }
    }

    #[tokio::test]
    async fn new_session_is_announced_before_initial_message_finishes() {
        let (created_tx, mut created_rx) = mpsc::unbounded_channel();
        let (release_tx, release_rx) = tokio::sync::oneshot::channel();
        let submission = tokio::spawn(announce_created_session_before_initial_message(
            created_tx,
            "session-created",
            Some(async move {
                release_rx.await.expect("submission release signal");
                Ok::<_, vibex_core::VibexError>(())
            }),
        ));

        assert_eq!(created_rx.recv().await, Some("session-created"));
        assert!(!submission.is_finished());

        release_tx.send(()).expect("release initial message");
        assert!(submission.await.expect("submission task").is_none());
    }

    #[test]
    fn initial_message_interrupt_is_not_reported_as_a_failure() {
        let interrupted = vibex_core::VibexError::conflict(
            "message_submission_interrupted_before_dispatch",
            "message submission was cancelled before dispatch",
        );
        assert_eq!(initial_message_failure_note(&interrupted), None);

        let failed = vibex_core::VibexError::provider("provider_failed", "provider failed");
        assert_eq!(
            initial_message_failure_note(&failed).as_deref(),
            Some("Session created; initial message failed: provider_failed: provider failed")
        );
    }

    #[test]
    fn fork_session_navigates_after_persistence_before_runtime_completion() {
        let source = include_str!("app.rs");
        let fork = source
            .split_once("    fn fork_session_at(")
            .and_then(|(_, tail)| tail.split_once("\n    fn begin_inline_user_message_edit("))
            .map(|(body, _)| body)
            .expect("fork session action should remain inspectable");

        let created = fork
            .find("created_rx.recv().await")
            .expect("fork should receive the durable session snapshot");
        let completed = fork
            .find("runner.await")
            .expect("fork should still observe final runtime initialization");

        assert!(fork.contains(".fork_session_with_created_callback("));
        assert!(created < completed);
        assert!(fork.contains("this.select_session_with_history(session_id, false, cx)"));
        assert!(fork.contains("Fork created. Preparing its runtime..."));
        assert!(fork.contains("Forked session is ready"));
    }

