    #[test]
    fn session_mutation_completions_release_the_action_lock_before_generation_fencing() {
        let source = include_str!("app.rs");
        let generation_fence = "if this.session_generation != generation {";
        let mutation_completions = [
            (
                "    fn rename_session(",
                "\n    fn confirm_delete_session(",
                "session rename",
                "let active = this.session_generation == generation;",
            ),
            (
                "    pub(crate) fn create_composer_terminal(",
                "\n    pub(crate) fn create_preview_terminal(",
                "composer terminal creation",
                generation_fence,
            ),
            (
                "    pub(crate) fn create_preview_terminal(",
                "\n    fn kill_composer_terminal(",
                "preview terminal creation",
                generation_fence,
            ),
            (
                "    fn kill_composer_terminals(",
                "\n    fn switch_composer_terminal_shell(",
                "composer terminal teardown",
                generation_fence,
            ),
            (
                "    fn switch_composer_terminal_shell(",
                "\n    fn prompt_rename_composer_terminal(",
                "terminal shell switch",
                generation_fence,
            ),
            (
                "    fn resolve_permission(",
                "\n    fn elicitation_input_key(",
                "permission resolution",
                generation_fence,
            ),
            (
                "    fn resolve_elicitation(",
                "\n    fn interrupt_session(",
                "elicitation resolution",
                generation_fence,
            ),
            (
                "    fn interrupt_session_with_queue_behavior(",
                "\n    fn continue_session(",
                "session interrupt",
                "this.selected_session_id.as_ref() != Some(&interrupted_session_id)",
            ),
        ];

        for (start, end, label, fence) in mutation_completions {
            let completion = source
                .split_once(start)
                .and_then(|(_, tail)| tail.split_once(end))
                .map(|(body, _)| body)
                .unwrap_or_else(|| panic!("{label} completion should remain inspectable"));
            let release = completion
                .find("this.agent_action_pending = false;")
                .unwrap_or_else(|| panic!("{label} must release its action lock"));
            let fence = completion
                .find(fence)
                .unwrap_or_else(|| panic!("{label} must fence active-view updates"));

            assert!(
                release < fence,
                "{label} must release its operation lock even after navigation changes generation"
            );
        }
    }

    #[test]
    fn fork_session_releases_the_action_lock_after_its_runtime_settles() {
        let source = include_str!("app.rs");
        let fork = source
            .split_once("    fn fork_session_at(")
            .and_then(|(_, tail)| tail.split_once("\n    fn begin_inline_user_message_edit("))
            .map(|(body, _)| body)
            .expect("fork session action should remain inspectable");
        let completion = fork
            .split_once("                let outcome = runner.await;")
            .map(|(_, body)| body)
            .expect("fork completion should remain inspectable");

        let release = completion
            .find("this.agent_action_pending = false;")
            .expect("the fork must release the window-wide action lock");
        let outcome = completion
            .find("match outcome {")
            .expect("the fork completion should branch on its outcome");

        assert!(
            release < outcome,
            "the fork must release its action lock before any outcome branch"
        );
        assert!(
            !completion[..release].contains("announced_session_id"),
            "an announced fork navigates to the new session, so a release fenced to the \
             announcement leaves every composer loading until the app restarts"
        );
    }

    #[test]
    fn session_switch_reuses_cached_timeline_projections_without_deep_clones() {
        let source = include_str!("app.rs");
        let view = source
            .split_once("pub struct SessionView {")
            .and_then(|(_, tail)| tail.split_once("\n}"))
            .map(|(body, _)| body)
            .expect("the session view should remain inspectable");
        assert!(view.contains("timeline_row_sizes: Rc<Vec<Size<gpui::Pixels>>>"));
        assert!(view.contains("timeline_measured_turn_layout_signatures"));
        assert!(view.contains("timeline_layout_width: Option<f32>"));
        assert!(view.contains("conversation_turns_cache: Rc<Vec<Rc<TimelineConversationTurn>>>"));
        // The view is complete: nothing a session needs may live outside it, or
        // two panes would share it.
        for field in [
            "timeline: TimelineModel",
            "timeline_scroll: VirtualListScrollHandle",
            "timeline_follow: TimelineFollowState",
            "streaming_row_state",
            "runtime_selection",
            "agent_loading",
            "collapsed_timeline_rows",
            "reasoning_expansion",
        ] {
            assert!(view.contains(field), "SessionView is missing {field}");
        }

        // Switching sessions moves the whole view; it never rebuilds one field
        // at a time, so a switch cannot lose or mix any of it.
        let borrow = source
            .split_once("    fn borrow_session_view(")
            .and_then(|(_, tail)| {
                tail.split_once("\n    /// Whether `session_id` already owns a view")
            })
            .map(|(body, _)| body)
            .expect("borrowing a session view should remain inspectable");
        assert!(borrow.contains("std::mem::replace("));
        assert!(borrow.contains("self.session_views.remove(&key)"));
        assert!(borrow.contains("self.store_session_view(previous_key, previous)"));
        assert!(!borrow.contains("self.timeline.clone()"));
        assert!(!borrow.contains("mem::take(&mut self.timeline)"));

        let release = source
            .split_once("    fn release_session_view(")
            .and_then(|(_, tail)| {
                tail.split_once("\n    /// Applies a newly loaded authoritative timeline")
            })
            .map(|(body, _)| body)
            .expect("releasing a session view should remain inspectable");
        assert!(release.contains("self.borrow_session_view(&primary)"));

        // The geometry of a view that changed shape is re-derived from its own
        // measurements, not from whichever session was borrowed before.
        let geometry = source
            .split_once("    fn refresh_borrowed_view_geometry(")
            .and_then(|(_, tail)| {
                tail.split_once("\n    /// Refetches one session's authoritative timeline")
            })
            .map(|(body, _)| body)
            .expect("view geometry refresh should remain inspectable");
        assert!(geometry.contains("self.streaming_timeline_row_state(turn)"));
        assert!(geometry.contains("self.invalidate_timeline_turn_measurement(&turn_id);"));
        assert!(geometry.contains("self.timeline_estimated_turn_heights.remove(&turn_id);"));
        assert!(geometry.contains("self.rebuild_timeline_sizes();"));
        assert!(geometry.contains("cached_timeline_layout_width"));
        // Only a real layout change may drop the measured row extents: the
        // turns cache key also moves for view-local session state, and
        // re-estimating the whole table there would scroll the restored view.
        let layout_change = geometry
            .find("let geometry_changed = layout_width_changed || content_width_changed;")
            .expect("view geometry should separate layout changes from projection changes");
        let invalidate = geometry
            .find("self.invalidate_timeline_layout_measurements();")
            .expect("a layout change should still invalidate the measurements");
        assert!(layout_change < invalidate);
        assert!(geometry.contains("if geometry_changed || turns_cache_changed {"));
        assert!(geometry.contains("self.timeline_scroll_anchor_pending ="));
        assert!(geometry.contains("!self.timeline_follow.following_bottom"));

        let selection = source
            .split_once("    fn select_session_with_history(")
            .and_then(|(_, tail)| tail.split_once("\n    fn load_agent_session_timeline("))
            .map(|(body, _)| body)
            .expect("session selection should remain inspectable");
        assert!(selection.contains("self.borrow_session_view(&session_id)"));
        assert!(selection.contains("self.timeline_scroll_anchor_pending = false;"));
        assert!(!selection.contains("latest_timeline_turn_ended_normally"));
        assert!(!selection.contains("cache_auto_continue_turn_status"));

        let authoritative_load = source
            .split_once("    fn load_agent_session_timeline(")
            .and_then(|(_, tail)| tail.split_once("\n    fn refresh_selected_agent_timeline("))
            .map(|(body, _)| body)
            .expect("authoritative timeline load should remain inspectable");
        assert!(authoritative_load.contains("latest_timeline_turn_ended_normally"));
        assert!(authoritative_load.contains("cache_auto_continue_turn_status"));
    }

    #[test]
    fn session_switch_restores_the_anchored_timeline_position() {
        // The anchor helpers are exact inverses while the row table is
        // unchanged, which is what lets a switch back paint the same
        // conversation content in its first frame.
        let row_heights = [100.0, 200.0, 300.0];
        assert_eq!(
            timeline_scroll_anchor_from_offset(&row_heights, 0.0, 16.0),
            Some((0, -16.0))
        );
        assert_eq!(
            timeline_scroll_anchor_from_offset(&row_heights, -200.0, 16.0),
            Some((1, 84.0))
        );
        assert_eq!(
            timeline_scroll_anchor_from_offset(&row_heights, -600.0, 16.0),
            Some((2, 284.0))
        );
        assert_eq!(timeline_scroll_anchor_from_offset(&[], 0.0, 16.0), None);
        for (row_index, offset_in_row) in [(0, -16.0), (1, 84.0), (2, 284.0)] {
            let offset_y =
                timeline_scroll_offset_for_anchor(&row_heights, row_index, offset_in_row, 16.0)
                    .expect("a row in the table resolves an offset");
            assert_eq!(
                timeline_scroll_anchor_from_offset(&row_heights, offset_y, 16.0),
                Some((row_index, offset_in_row))
            );
        }
        assert_eq!(
            timeline_scroll_offset_for_anchor(&row_heights, 3, 0.0, 16.0),
            None
        );

        let source = include_str!("app.rs");
        let apply = source
            .split_once("    fn apply_pending_timeline_scroll(")
            .and_then(|(_, tail)| tail.split_once("\n    fn timeline_row_heights("))
            .map(|(body, _)| body)
            .expect("pending timeline scroll should remain inspectable");
        assert!(apply.contains("self.apply_timeline_scroll_anchor();"));

        let capture = source
            .split_once("    fn capture_timeline_scroll_anchor(")
            .and_then(|(_, tail)| tail.split_once("\n    /// Put the captured anchor back"))
            .map(|(body, _)| body)
            .expect("timeline anchor capture should remain inspectable");
        assert!(capture.contains("self.timeline_follow.following_bottom"));
        assert!(
            capture
                .contains("self.timeline_row_sizes.len() != self.conversation_turns_cache.len()")
        );
        assert!(capture.contains(".preserve_anchor(turn_id, offset_in_row.round() as i32);"));

        let workbench = source
            .split_once("    fn render_agent_workbench(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_runtime_controls("))
            .map(|(body, _)| body)
            .expect("agent workbench renderer should remain inspectable");
        let padding = workbench
            .find("self.timeline_list_padding_top_px = f32::from(window.rem_size());")
            .expect("the list's rem-based top padding should be tracked");
        let scroll = workbench
            .find("self.apply_pending_timeline_scroll();")
            .expect("pending scroll work should remain applied");
        assert!(padding < scroll);

        // Both authorities must anchor the reader before their authoritative
        // replacement invalidates the measured extents.
        for (loader, next) in [
            (
                "    fn load_agent_session_timeline(",
                "\n    fn refresh_selected_agent_timeline(",
            ),
            (
                "    fn load_agent_session_timeline_remote(",
                "\n    fn load_agent_session_timeline(",
            ),
        ] {
            let body = source
                .split_once(loader)
                .and_then(|(_, tail)| tail.split_once(next))
                .map(|(body, _)| body)
                .unwrap_or_else(|| panic!("{loader} should remain inspectable"));
            let capture = body
                .find("this.capture_timeline_scroll_anchor();")
                .expect("the reader's position should be captured before the replacement");
            let replace = body
                .find("this.timeline\n                                .replace_authoritative(")
                .expect("the authoritative replacement should remain inspectable");
            assert!(capture < replace);
            assert!(body.contains("this.timeline_scroll_anchor_pending = true;"));
        }
    }

