    #[test]
    fn startup_loading_overlay_waits_for_initial_session_history() {
        let source = include_str!("app.rs");
        let startup_initializer = ["startup_loading:", " true"].concat();
        let startup_reopen_assignment = ["startup_loading", " = true"].concat();
        assert_eq!(source.matches(&startup_initializer).count(), 1);
        assert!(!source.contains(&startup_reopen_assignment));

        let overview = source
            .split_once("    fn load_agent_overview(")
            .and_then(|(_, tail)| tail.split_once("\n    fn load_agent_runtime_catalog("))
            .map(|(body, _)| body)
            .expect("agent overview should remain inspectable");
        assert!(overview.contains("this.finish_startup_loading(cx);"));

        let timeline = source
            .split_once("    fn load_agent_session_timeline(")
            .and_then(|(_, tail)| tail.split_once("\n    fn load_agent_session_projection("))
            .map(|(body, _)| body)
            .expect("session timeline loader should remain inspectable");
        let history_loaded = timeline
            .find("replace_authoritative(session_id.clone(), items);")
            .expect("authoritative session history should be installed");
        let release = timeline
            .rfind("this.finish_startup_loading(cx);")
            .expect("session history completion should release the startup overlay");
        assert!(history_loaded < release);

        let boot = source
            .split_once("    fn begin_runtime_start(")
            .and_then(|(_, tail)| tail.split_once("\n    fn finish_startup_loading("))
            .map(|(body, _)| body)
            .expect("runtime startup should remain inspectable");
        assert!(boot.contains("self.finish_startup_loading(cx);"));
        assert!(boot.contains("this.finish_startup_loading(cx);"));

        // Both authorities reach Ready through an install path that restores
        // the Agent overview before it releases the startup overlay. A parked
        // embedded runtime is reinstalled without a boot, so the ordering
        // guard has to cover the install path rather than the boot path.
        for install in [
            "    fn install_local_runtime(",
            "    fn install_remote_client(",
        ] {
            let body = source
                .split_once(install)
                .and_then(|(_, tail)| tail.split_once("\n    fn "))
                .map(|(body, _)| body)
                .unwrap_or_else(|| panic!("{install} should remain inspectable"));
            let ready = body
                .find("RuntimeStatus::Ready;")
                .unwrap_or_else(|| panic!("{install} should reach Ready"));
            let overview = body
                .find(".load_agent_overview(cx);")
                .unwrap_or_else(|| panic!("{install} should restore the agent overview"));
            let release = body
                .rfind(".finish_startup_loading(cx);")
                .unwrap_or_else(|| panic!("{install} should release the startup overlay"));
            assert!(
                ready < release,
                "{install} must reach Ready before releasing"
            );
            assert!(
                overview < release,
                "{install} must restore the agent overview before releasing the overlay"
            );
        }

        let selection = source
            .split_once("    fn select_session_with_history(")
            .and_then(|(_, tail)| tail.split_once("\n    fn load_agent_session_timeline("))
            .map(|(body, _)| body)
            .expect("session selection should remain inspectable");
        assert!(!selection.contains(&startup_reopen_assignment));
        let render = source
            .split_once("impl Render for VibexWorkbench")
            .and_then(|(_, tail)| tail.split_once("\npub fn bind_foundation_keys("))
            .map(|(body, _)| body)
            .expect("workbench renderer should remain inspectable");
        assert!(
            render.contains("startup_loading_overlay(self.startup_loading_indicator_visible, cx)")
        );
    }

