    #[test]
    fn sidebar_animation_keeps_content_mounted_until_close_finishes() {
        let mut state = SidebarAnimationState::new(320.0, 0.0, true);

        assert!(state.needs_update(320.0, 0.0, false, true));
        let request = state.update_target(320.0, 0.0, false, true).unwrap();

        assert_eq!(state.from_value, 320.0);
        assert_eq!(state.target_value, 0.0);
        assert_eq!(state.from_opacity, 1.0);
        assert_eq!(state.target_opacity, 0.0);
        assert!(state.render_child);
        assert!(state.hide_scheduled);
        assert!(!state.finish_hide(request.wrapping_add(1)));
        assert!(state.finish_hide(request));
        assert!(!state.render_child);
    }

