    #[test]
    fn floating_sidebar_slides_in_and_keeps_its_mode_while_closing() {
        let mut state = SidebarFloatingAnimationState::new(320.0, None);
        let hover_preview = Some(SidebarFloatingPresentation::HoverPreview);

        assert!(state.needs_update(320.0, hover_preview, true));
        assert_eq!(state.update_target(320.0, hover_preview, true), None,);
        assert_eq!(state.animation.from_value, -320.0);
        assert_eq!(state.animation.target_value, 0.0);
        assert_eq!(state.animation.from_opacity, 0.0);
        assert_eq!(state.animation.target_opacity, 1.0);
        assert!(state.animation.render_child);

        assert_eq!(
            state.update_target(320.0, Some(SidebarFloatingPresentation::Drawer), true),
            None,
        );
        let request = state.update_target(320.0, None, true).unwrap();
        assert_eq!(state.animation.from_value, 0.0);
        assert_eq!(state.animation.target_value, -320.0);
        assert_eq!(state.presentation, SidebarFloatingPresentation::Drawer);
        assert!(state.animation.render_child);
        assert!(state.finish_hide(request));
        assert!(!state.animation.render_child);
    }

