    #[test]
    fn agent_brand_assets_match_tauri_identity_priority_and_theme_behavior() {
        assert_eq!(
            agent_brand_asset("OpenCode Gemini"),
            Some(AgentBrandAsset {
                path: "icons/vibex/opencode.svg",
                uses_current_color: false,
            }),
        );
        assert_eq!(
            agent_brand_asset("Google Gemini"),
            Some(AgentBrandAsset {
                path: "icons/vibex/gemini.svg",
                uses_current_color: false,
            }),
        );
        assert_eq!(
            agent_brand_asset("GitHub Copilot"),
            Some(AgentBrandAsset {
                path: "icons/vibex/copilot.svg",
                uses_current_color: true,
            }),
        );
        assert_eq!(
            agent_brand_asset("OpenAI Codex"),
            Some(AgentBrandAsset {
                path: "icons/vibex/openai.svg",
                uses_current_color: true,
            }),
        );
        assert_eq!(agent_brand_asset("custom acp"), None);

        let mut custom = AgentSnapshotEntry::from_definition(
            vibex_core::builtin_agent_definitions().first().unwrap(),
            None,
            None,
        );
        custom.id = AgentId::parse("custom-acp").unwrap();
        custom.label = "Custom Agent".into();
        custom.command = Some(vibex_core::AgentCommandConfig {
            command: "opencode".into(),
            args: Vec::new(),
        });
        custom.params = serde_json::json!({ "preset": "gemini" });
        assert_eq!(
            agent_brand_asset(&agent_brand_identity(&custom)),
            Some(AgentBrandAsset {
                path: "icons/vibex/opencode.svg",
                uses_current_color: false,
            }),
        );

        custom.command = None;
        assert_eq!(
            agent_brand_asset(&agent_brand_identity(&custom)),
            Some(AgentBrandAsset {
                path: "icons/vibex/gemini.svg",
                uses_current_color: false,
            }),
        );
    }

