    #[test]
    fn sidebar_session_time_uses_local_calendar_days() {
        let at = |day, hour, minute| {
            chrono::NaiveDate::from_ymd_opt(2026, 8, day)
                .unwrap()
                .and_hms_opt(hour, minute, 0)
                .unwrap()
        };
        let now = at(18, 0, 1);

        assert_eq!(
            format_sidebar_session_time_at(
                at(17, 23, 59),
                now,
                locale::ResolvedLocale::ZhCn,
                locale::strings(locale::ResolvedLocale::ZhCn),
            ),
            "昨天"
        );
        assert_eq!(
            format_sidebar_session_time_at(
                at(18, 0, 0),
                now,
                locale::ResolvedLocale::En,
                locale::strings(locale::ResolvedLocale::En),
            ),
            "00:00"
        );
        assert_eq!(
            format_sidebar_session_time_at(
                at(16, 23, 59),
                now,
                locale::ResolvedLocale::En,
                locale::strings(locale::ResolvedLocale::En),
            ),
            "2 days ago"
        );
    }

    #[test]
    fn sidebar_session_display_state_projects_each_locally_pending_turn() {
        assert_eq!(
            sidebar_session_display_state(AgentSessionState::Idle, true),
            AgentSessionState::Running
        );
        assert_eq!(
            sidebar_session_display_state(AgentSessionState::Idle, false),
            AgentSessionState::Idle
        );
        assert_eq!(
            sidebar_session_display_state(AgentSessionState::Error, false),
            AgentSessionState::Error
        );
        assert_eq!(
            sidebar_session_display_state(AgentSessionState::Running, false),
            AgentSessionState::Running
        );
        // An optimistic local turn must not cover a session that is already
        // parked on the user, or the row would spin while waiting for an
        // answer that only the user can give.
        assert_eq!(
            sidebar_session_display_state(AgentSessionState::NeedsInput, true),
            AgentSessionState::NeedsInput
        );
        // A failed session that is asked to work again stops reading as failed
        // as soon as the local dispatch exists: the failure belongs to the
        // previous turn, and the replacement turn can spend a while preparing
        // its runtime before the authority reports `Running`.
        assert_eq!(
            sidebar_session_display_state(AgentSessionState::Error, true),
            AgentSessionState::Running
        );
    }

