        assert!(sidebar_session.contains(
            "&& !session_has_error\n                                            && !auto_continue_paused,\n                                        |this| this.child(time_label)"
        ));
        assert!(sidebar_session.contains(
            ".when(session_has_error, |this| {\n                                this.child(sidebar_status_dot(cx.theme().danger))"
        ));
