        assert!(sidebar_session.contains(".group_hover(&hover_group, |style| style.visible())"));
        assert!(sidebar_session.contains(
            "state_label.is_none()\n                                            && !has_unread_completion\n                                            && !session_has_error\n                                            && !auto_continue_paused"
        ));
