    #[test]
    fn timeline_follow_resumes_only_after_scroll_is_idle_near_bottom() {
        assert_eq!(timeline_distance_to_bottom(-900.0, 1_000.0), 100.0);
        assert_eq!(timeline_distance_to_bottom(-1_010.0, 1_000.0), 0.0);
        assert!(timeline_should_resume_follow_after_scroll_idle(
            true,
            AGENT_TIMELINE_NEAR_BOTTOM_THRESHOLD_PX,
            false,
        ));
        assert!(!timeline_should_resume_follow_after_scroll_idle(
            true,
            AGENT_TIMELINE_NEAR_BOTTOM_THRESHOLD_PX + 1.0,
            false,
        ));
        assert!(!timeline_should_resume_follow_after_scroll_idle(
            true, 0.0, true
        ));
        // A short timeline can be within the near-bottom threshold even at its
        // top. Scrolling upward must preserve that explicit reading position.
        assert!(!timeline_should_resume_follow_after_scroll_idle(
            false,
            AGENT_TIMELINE_NEAR_BOTTOM_THRESHOLD_PX / 2.0,
            false,
        ));
    }

