    #[test]
    fn continuation_clears_stale_errors_and_reconciles_the_session_snapshot() {
        let source = include_str!("app.rs");
        let continuation = source
            .split_once("    fn continue_session(")
            .and_then(|(_, tail)| tail.split_once("\n    fn fork_session_at("))
            .map(|(body, _)| body)
            .expect("continuation action should remain inspectable");

        assert!(continuation.contains("self.set_session_turn_pending(&session_id, true);"));
        assert!(continuation.contains("self.agent_error = None;"));
        let notify = continuation
            .find("cx.notify();")
            .expect("continuation should repaint immediately");
        let dispatch = continuation
            .find("let runner = gpui_tokio::Tokio::spawn")
            .expect("continuation should remain asynchronous");
        assert!(notify < dispatch);
        assert!(
            continuation.contains(".open_session(session_id.clone())\n                .await")
                || continuation.contains("open_session(session_id.clone())"),
            "continuation should reconcile the session snapshot through the backend"
        );
        assert!(continuation.contains("this.upsert_session_snapshot(session.clone());"));
        let clear = continuation
            .find("this.set_session_turn_pending(&continued_session_id, false);")
            .expect("continuation should clear its per-session pending state");
        let completion_fence = continuation
            .find("if !agent_turn_completion_is_active(")
            .expect("continuation completion should remain session-fenced");
        assert!(clear < completion_fence);
        assert!(continuation.contains("composer_queue_ready_after_continuation_session_ids"));
        assert!(continuation.contains("self.resume_auto_continue(&session_id, cx);"));
        assert!(source.contains("flush_composer_queue_dispatches_after_continuation"));
    }

    #[test]
    fn auto_continue_starts_once_for_each_incomplete_turn_snapshot() {
        assert!(auto_continue_should_start(
            true,
            AgentSessionState::Error,
            Some(false),
            false,
            false,
            None,
            42,
            false
        ));
        assert!(!auto_continue_should_start(
            true,
            AgentSessionState::Error,
            Some(true),
            false,
            false,
            None,
            42,
            false
        ));
        assert!(auto_continue_should_start(
            true,
            AgentSessionState::Idle,
            Some(false),
            false,
            false,
            None,
            42,
            false
        ));
        assert!(!auto_continue_should_start(
            true,
            AgentSessionState::Idle,
            None,
            false,
            false,
            None,
            42,
            false
        ));
        assert!(!auto_continue_should_start(
            false,
            AgentSessionState::Error,
            Some(false),
            false,
            false,
            None,
            42,
            false
        ));
        assert!(!auto_continue_should_start(
            true,
            AgentSessionState::Running,
            Some(false),
            true,
            false,
            None,
            42,
            false
        ));
        assert!(!auto_continue_should_start(
            true,
            AgentSessionState::Error,
            Some(false),
            false,
            true,
            None,
            42,
            false
        ));
        assert!(!auto_continue_should_start(
            true,
            AgentSessionState::Error,
            Some(false),
            false,
            false,
            Some(42),
            42,
            false
        ));
        assert!(auto_continue_should_start(
            true,
            AgentSessionState::Error,
            Some(false),
            false,
            false,
            Some(41),
            42,
            false
        ));
        assert!(!auto_continue_should_start(
            true,
            AgentSessionState::Error,
            Some(false),
            false,
            false,
            Some(41),
            42,
            true
        ));
    }

