    #[test]
    fn auto_continue_ui_supports_session_scoping_countdown_and_pause() {
        let source = include_str!("app.rs");
        assert!(source.contains("auto_continue_default_project_ids"));
        let state = source
            .split_once("    fn auto_continue_enabled(")
            .and_then(|(_, tail)| tail.split_once("\n    fn sidebar_workspace_groups("))
            .map(|(body, _)| body)
            .expect("auto-continue state should remain inspectable");
        assert!(state.contains("auto_continue_session_ids"));
        assert!(state.contains("auto_continue_paused_session_ids"));
        assert!(state.contains("auto_continue_paused_turn_session_ids"));
        assert!(state.contains("auto_continue_turn_statuses"));
        assert!(state.contains("probe_auto_continue_turn_status"));
        assert!(state.contains("session_updated_at_ms"));
        assert!(state.contains("AUTO_CONTINUE_COUNTDOWN_SECONDS"));
        assert!(state.contains("this.tick_auto_continue_countdown"));
        assert!(state.contains("self.pause_auto_continue(&session_id, cx);"));
        assert!(state.contains("self.continue_session_by_id("));
        assert!(state.contains("fn resume_auto_continue("));

        let pause = source
            .split_once("    fn pause_auto_continue(")
            .and_then(|(_, tail)| tail.split_once("\n    fn activate_continue_button("))
            .map(|(body, _)| body)
            .expect("manual auto-continue pause should remain inspectable");
        // Pausing suspends auto-continue while keeping the persisted
        // preference: a restart must not silently resume the countdown.
        assert!(pause.contains("auto_continue_paused_session_ids"));
        assert!(!pause.contains("set_auto_continue_enabled"));
        assert!(pause.contains("fn resume_auto_continue("));

        let interrupt = source
            .split_once("    fn interrupt_session_with_queue_behavior(")
            .and_then(|(_, tail)| tail.split_once("\n    fn continue_session("))
            .map(|(body, _)| body)
            .expect("manual interruption should remain inspectable");
        assert!(interrupt.contains("self.pause_auto_continue(&session_id, cx)"));
        assert!(!interrupt.contains("set_auto_continue_enabled"));

        let composer = source
            .split_once("    fn render_composer(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_runtime_failure("))
            .map(|(body, _)| body)
            .expect("composer renderer should remain inspectable");
        assert!(composer.contains("Switch::new(\"auto-continue-agent\")"));
        assert!(composer.contains(".checked(auto_continue_enabled)"));
        assert!(composer.contains("button.icon(IconName::Pause)"));
        assert!(composer.contains("auto_continue_countdown_label"));
        assert!(composer.contains("continuation_available"));
        assert!(composer.contains("auto_continue_remaining.is_none()"));
        assert!(composer.contains("this.activate_continue_button(cx)"));
        // Rendering reads what the event paths cached; it never drives the
        // probe itself. A session group renders a composer per pane, so syncing
        // here re-entered the probe once per pane, per frame, and the probe's
        // completion repainted the window — the workbench never reached an idle
        // frame and the wasted work grew with the number of panes.
        assert!(!composer.contains("sync_auto_continue_for_session"));
        assert!(composer.contains("cached_auto_continue_turn_status"));
        let probe = source
            .split_once("    fn probe_auto_continue_turn_status(")
            .and_then(|(_, tail)| tail.split_once("\n    fn set_auto_continue_enabled("))
            .map(|(body, _)| body)
            .expect("the completion probe should remain inspectable");
        // A probe that cannot answer for a revision is retried on a backoff,
        // not once per sync.
        assert!(probe.contains("auto_continue_probe_attempts"));
        assert!(probe.contains("AUTO_CONTINUE_PROBE_RETRY_BACKOFF"));

        let sidebar = source
            .split_once("    fn render_sidebar_session(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_runtime_choice_popover("))
            .map(|(body, _)| body)
            .expect("sidebar session renderer should remain inspectable");
        assert!(sidebar.contains("let context_auto_continue_id = session.id.clone();"));
        assert!(sidebar.contains("PopupMenuItem::new(auto_continue_label)"));
        assert!(sidebar.contains(".checked(auto_continue_enabled)"));
        assert!(sidebar.contains("this.set_auto_continue_enabled("));
        assert!(sidebar.contains("icons/vibex/pause.svg"));
        assert!(sidebar.contains("auto_continue_paused"));

        let project = source
            .split_once("    fn render_sidebar_project(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_sidebar_workspace("))
            .map(|(body, _)| body)
            .expect("sidebar project renderer should remain inspectable");
        let project_menu = source
            .split_once("    fn build_sidebar_project_menu(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_sidebar_project("))
            .map(|(body, _)| body)
            .expect("project menu builder should remain inspectable");
        assert!(project_menu.contains("PopupMenuItem::new(auto_continue_label)"));
        assert!(project_menu.contains(".checked(auto_continue_enabled)"));
        assert!(project_menu.contains("this.set_project_auto_continue_enabled("));
        assert!(project.contains("Self::build_sidebar_project_menu("));

        let project_toggle = source
            .split_once("    fn set_project_auto_continue_enabled(")
            .and_then(|(_, tail)| tail.split_once("\n    fn auto_continue_enabled("))
            .map(|(body, _)| body)
            .expect("project auto-continue toggle should remain inspectable");
        assert!(project_toggle.contains("session.project_id.as_str() == project_id.as_str()"));
        assert!(project_toggle.contains("self.set_auto_continue_enabled(session_id, true, cx)"));
        assert!(project_toggle.contains("self.ui_state.session.auto_continue_project_ids"));
        assert!(project_toggle.contains("self.queue_ui_state()"));

        let upsert = source
            .split_once("    fn upsert_session_snapshot(")
            .and_then(|(_, tail)| tail.split_once("\n    fn session_turn_pending("))
            .map(|(body, _)| body)
            .expect("session snapshot reconciliation should remain inspectable");
        assert!(upsert.contains("self.project_auto_continue_enabled(&session.project_id)"));
        assert!(upsert.contains("auto_continue_session_overrides"));
        assert!(upsert.contains("self.auto_continue_session_ids"));
        assert!(upsert.contains("existing_state != session.state"));

        let pending = source
            .split_once("    fn set_session_turn_pending(")
            .and_then(|(_, tail)| tail.split_once("\n    fn project_auto_continue_enabled("))
            .map(|(body, _)| body)
            .expect("turn-pending reconciliation should remain inspectable");
        assert!(pending.contains("self.auto_continue_handled_turns.remove"));
        assert!(pending.contains("self.auto_continue_turn_statuses.remove"));
        assert!(pending.contains("self.auto_continue_probe_tasks.remove"));
        assert!(pending.contains("self.cancel_auto_continue_countdown(session_id)"));

        let session_toggle = source
            .split_once("    fn set_auto_continue_enabled(")
            .and_then(|(_, tail)| tail.split_once("\n    fn sync_auto_continue_for_session("))
            .map(|(body, _)| body)
            .expect("session auto-continue toggle should remain inspectable");
        assert!(session_toggle.contains("auto_continue_session_overrides"));
        assert!(session_toggle.contains("self.queue_ui_state()"));
    }

    #[test]
    fn failed_composer_submission_reconciles_session_before_auto_continue() {
        let source = include_str!("app.rs");
        let dispatch = source
            .split_once("    fn dispatch_composer_message(")
            .and_then(|(_, tail)| {
                tail.split_once("\n    fn maybe_dispatch_next_composer_queue_message(")
            })
            .map(|(body, _)| body)
            .expect("Composer dispatch should remain inspectable");

        assert!(!dispatch.contains("outcome?;"));
        assert!(dispatch.contains("let session = runtime"));
        assert!(dispatch.contains("(outcome, session)"));
        assert!(dispatch.contains("if let Ok((_, Some(session))) = &outcome"));
        assert!(dispatch.contains("Ok((Err(error), _))"));

        let reconcile = dispatch
            .find("this.upsert_session_snapshot(session.clone());")
            .expect("the authoritative session snapshot should be reconciled");
        let clear_pending = dispatch
            .find("this.set_session_turn_pending(&submitted_session_id, false);")
            .expect("the local pending state should be cleared");
        let auto_continue = dispatch
            .find("this.sync_auto_continue_for_session(&submitted_session_id, cx);")
            .expect("auto continue should observe the reconciled error state");
        assert!(reconcile < clear_pending && clear_pending < auto_continue);

        // A new user message reactivates the session, so it must clear the
        // persisted auto-continue pause after the turn becomes pending.
        let turn_pending = dispatch
            .find("self.set_session_turn_pending(&session_id, true);")
            .expect("the new turn should become pending");
        let resume = dispatch
            .find("self.resume_auto_continue(&session_id, cx);")
            .expect("a new message should lift a persisted auto-continue pause");
        assert!(turn_pending < resume);
    }

    #[test]
    fn composer_submission_projects_user_turn_before_background_runtime_wait() {
        let source = include_str!("app.rs");
        let dispatch = source
            .split_once("    fn dispatch_composer_message(")
            .and_then(|(_, tail)| {
                tail.split_once("\n    fn maybe_dispatch_next_composer_queue_message(")
            })
            .map(|(body, _)| body)
            .expect("Composer dispatch should remain inspectable");

        let pending = dispatch
            .find("self.set_session_turn_pending(&session_id, true);")
            .expect("submission should immediately project the Agent as running");
        let optimistic = dispatch
            .find("self.install_optimistic_user_message(optimistic_message);")
            .expect("submission should immediately project the user message");
        let repaint = dispatch[pending..]
            .find("cx.notify();")
            .map(|offset| pending + offset)
            .expect("the optimistic projection should request an immediate repaint");
        let background = dispatch
            .find("let runner = gpui_tokio::Tokio::spawn(cx, async move")
            .expect("runtime preparation and prompt dispatch should stay in the background");

        assert!(pending < optimistic);
        assert!(optimistic < repaint);
        assert!(repaint < background);
        assert!(!dispatch.contains("discard_optimistic_user_message"));
    }

