    #[test]
    fn created_session_consumes_its_draft_before_the_initial_turn_completes() {
        let source = include_str!("app.rs");
        let submit = source
            .split_once("    fn submit_new_session(")
            .and_then(|(_, tail)| tail.split_once("\n    fn choose_runtime_selection("))
            .map(|(body, _)| body)
            .expect("new-session submission should remain inspectable");
        let session_ready = submit
            .rfind("NewSessionCreateSignal::SessionReady(")
            .expect("the authoritative session should be handled before its initial turn");
        let clear = submit
            .find("this.clear_submitted_new_session_draft(window, cx);")
            .expect("the submitted new-session draft should be consumed");
        let turn_completion = submit
            .find("let outcome = runner.await;")
            .expect("initial-turn completion should remain asynchronous");

        assert!(session_ready < clear && clear < turn_completion);
        assert!(!submit[turn_completion..].contains("clear_submitted_new_session_draft"));

        let immediate_clear = submit
            .find("self.clear_new_session_message_draft(window, cx);")
            .expect("submission should clear the captured message draft immediately");
        let dispatch = submit
            .find("let runner = gpui_tokio::Tokio::spawn")
            .expect("session creation should remain asynchronous");
        assert!(immediate_clear < dispatch);
        assert_eq!(
            submit
                .matches("self.clear_new_session_message_draft(window, cx);")
                .count(),
            1
        );
        assert_eq!(
            submit.matches("this.fail_pending_new_session(").count(),
            2,
            "both session-creation failure paths should restore the draft"
        );
        let initial_message_failure = submit
            .split_once("if let Some(error) = initial_message_error")
            .and_then(|(_, tail)| tail.split_once("this.reconcile_sidebar_state();"))
            .map(|(body, _)| body)
            .expect("initial-message failure handling should remain inspectable");
        assert!(initial_message_failure.contains("this.runtime_note"));
        assert!(
            !initial_message_failure.contains("discard_optimistic_user_message"),
            "a created session must keep the captured user message visible when initialization fails"
        );
        assert!(!initial_message_failure.contains("composer_input"));
        assert!(!initial_message_failure.contains("draft_raw_text"));
        assert!(!initial_message_failure.contains("draft_attachments"));
        assert!(!initial_message_failure.contains("draft_command_entry"));

        let clear_draft = source
            .split_once("    fn clear_submitted_new_session_draft(")
            .and_then(|(_, tail)| tail.split_once("\n    fn current_checkout_for_project("))
            .map(|(body, _)| body)
            .expect("submitted draft cleanup should remain inspectable");
        assert!(clear_draft.contains("self.clear_new_session_message_draft(window, cx);"));
        assert!(clear_draft.contains("self.new_session_draft_initialized = false;"));
        assert!(clear_draft.contains("self.new_session_workspace.reset_after_success();"));
        assert!(clear_draft.contains("self.new_session_attachments.clear();"));
        assert!(clear_draft.contains("self.new_session_command_entry = None;"));
        assert!(clear_draft.contains("input.set_value(\"\", window, cx)"));
        assert!(clear_draft.contains("self.new_session_attachments = attachments;"));
        assert!(clear_draft.contains("self.new_session_command_entry = command_entry;"));
    }

    #[test]
    fn new_session_submission_opens_the_conversation_before_background_creation() {
        let source = include_str!("app.rs");
        let submit = source
            .split_once("    fn submit_new_session(")
            .and_then(|(_, tail)| tail.split_once("\n    fn choose_runtime_selection("))
            .map(|(body, _)| body)
            .expect("new-session submission should remain inspectable");
        let optimistic_message = submit
            .find("let optimistic_message =")
            .expect("the first user message should be projected optimistically");
        let open = submit
            .find("self.open_pending_new_session(")
            .expect("submission should immediately open the pending conversation");
        let background_creation = submit
            .find("let runner = gpui_tokio::Tokio::spawn")
            .expect("authoritative creation should remain asynchronous");

        assert!(optimistic_message < open && open < background_creation);
        assert!(submit.contains("defer_runtime_materialization: deferred_creation"));
        assert!(submit.contains(".create_session("));
        assert!(
            !submit.contains("self.runtime.clone()")
                && !submit.contains("create_session_with_id(")
                && !submit.contains("create_session_deferred_with_id("),
            "new-session creation must drive the authority facade in both modes"
        );

        let pending_open = source
            .split_once("    fn open_pending_new_session(")
            .and_then(|(_, tail)| tail.split_once("\n    fn update_pending_new_session_workspace("))
            .map(|(body, _)| body)
            .expect("pending-session navigation should remain inspectable");
        let selection = source
            .split_once("    fn select_session_with_history(")
            .and_then(|(_, tail)| tail.split_once("\n    fn load_agent_session_timeline("))
            .map(|(body, _)| body)
            .expect("pending-session selection should remain inspectable");
        assert!(selection.contains("self.clear_sidebar_move_selection();"));
        let snapshot = pending_open
            .find("self.upsert_session_snapshot(session);")
            .expect("the pending Session should enter the sidebar source immediately");
        let reconcile = pending_open
            .find("self.reconcile_sidebar_state();")
            .expect("the pending Session should be ordered before its first sidebar render");
        let select = pending_open
            .find("self.select_session_with_history(session_id, false, cx);")
            .expect("the pending Session should be selected immediately");
        assert!(snapshot < reconcile && reconcile < select);
        assert!(pending_open.contains("self.select_session_with_history(session_id, false, cx);"));
        assert!(pending_open.contains("self.install_optimistic_user_message(message);"));
        assert!(pending_open.contains("self.set_session_turn_pending(&session_id, true);"));
        assert!(pending_open.contains("self.agent_loading = false;"));
        assert!(!pending_open.contains("self.agent_action_pending = true;"));
    }

