    #[test]
    fn background_agent_turns_do_not_hold_the_short_action_lock() {
        let source = include_str!("app.rs");
        let submit = source
            .split_once("    fn submit_composer(")
            .and_then(|(_, tail)| tail.split_once("\n    fn start_submission_poll("))
            .map(|(body, _)| body)
            .expect("composer submission should remain inspectable");
        assert!(submit.contains("if self.agent_action_pending && !session_running"));
        assert!(submit.contains("if session_running || queue_paused || queue_has_messages"));
        assert!(submit.contains("self.composer_queue.push(message);"));
        assert!(submit.contains("self.set_session_turn_pending(&session_id, true);"));
        assert!(submit.contains("ComposerQueueDispatchBehavior::AfterCompletion"));
        let clear = submit
            .find("this.set_session_turn_pending(&submitted_session_id, false);")
            .expect("submission should clear its per-session pending state");
        let completion_fence = submit
            .find("let active = agent_turn_completion_is_active(")
            .expect("submission completion should remain session-fenced");
        assert!(clear < completion_fence);
        assert!(!submit.contains("self.agent_action_pending = true;"));
        assert!(submit.contains(".detach();"));

        let open_new_session = source
            .split_once("    fn open_new_session(")
            .and_then(|(_, tail)| tail.split_once("\n    fn clear_submitted_new_session_draft("))
            .map(|(body, _)| body)
            .expect("new-session navigation should remain inspectable");
        assert!(!open_new_session.contains("if self.agent_action_pending"));
        assert!(!open_new_session.contains("agent_turn_pending"));

        let new_session_submit = source
            .split_once("    fn submit_new_session(")
            .and_then(|(_, tail)| tail.split_once("\n    fn choose_runtime_selection("))
            .map(|(body, _)| body)
            .expect("new-session submission should remain inspectable");
        assert!(new_session_submit.contains("self.pending_new_session.is_some()"));

        let sidebar = source
            .split_once("    fn render_agent_sidebar(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_sidebar_project("))
            .map(|(body, _)| body)
            .expect("sidebar should remain inspectable");
        let new_session_button = sidebar
            .split_once("Button::new(\"sidebar-new-session\")")
            .and_then(|(_, tail)| tail.split_once("Button::new(\"sidebar-config-center\")"))
            .map(|(body, _)| body)
            .expect("sidebar New Session button should remain inspectable");
        assert!(!new_session_button.contains(".disabled(self.agent_action_pending)"));

        let runtime_switch = source
            .split_once("    fn request_runtime_selection(")
            .and_then(|(_, tail)| tail.split_once("\n    fn cancel_runtime_switch("))
            .map(|(body, _)| body)
            .expect("runtime selection should remain inspectable");
        assert!(!runtime_switch.contains("if self.agent_action_pending"));
        assert!(!runtime_switch.contains("agent_turn_pending"));
        assert!(runtime_switch.contains("self.optimistic_runtime_selections"));
        assert!(runtime_switch.contains("request_pending_runtime_selection"));
    }

    #[test]
    fn runtime_cancellation_blocks_only_its_own_session_controls() {
        let first = VibexSessionId::parse("session_first").unwrap();
        let second = VibexSessionId::parse("session_second").unwrap();
        let pending = BTreeSet::from([first.as_str().to_string()]);

        assert!(runtime_selection_cancellation_is_pending(
            Some(&first),
            &pending
        ));
        assert!(!runtime_selection_cancellation_is_pending(
            Some(&second),
            &pending
        ));
        assert!(!runtime_selection_cancellation_is_pending(None, &pending));

        let source = include_str!("app.rs");
        let cancel = source
            .split_once("    fn cancel_runtime_switch(")
            .and_then(|(_, tail)| tail.split_once("\n    fn begin_sidebar_rename("))
            .map(|(body, _)| body)
            .expect("runtime cancellation should remain inspectable");
        assert!(!cancel.contains("self.agent_action_pending"));
        assert!(!cancel.contains("this.agent_action_pending"));
        let release = cancel
            .find("this.runtime_selection_cancellations_in_flight")
            .expect("the per-session cancellation lock should be released");
        let active_fence = cancel
            .find("let active = this.session_generation == generation")
            .expect("results should remain fenced to the active session");
        assert!(release < active_fence);
    }

