    #[test]
    fn composer_queue_reorders_only_within_a_session_and_steer_promotes_the_message() {
        let selection = SessionRuntimeSelection::provider(
            AgentId::parse("agent-queue").unwrap(),
            ProviderProfileId::parse("provider_queue").unwrap(),
            "model-queue",
        );
        let queued = |id, session: &str| ComposerQueueMessage {
            id,
            session_id: VibexSessionId::parse(session).unwrap(),
            desired_runtime: selection.clone(),
            text: format!("message {id}"),
            attachments: Vec::new(),
            command_invocation: None,
        };
        let mut queue = vec![
            queued(1, "session_queue_a"),
            queued(4, "session_queue_b"),
            queued(2, "session_queue_a"),
            queued(3, "session_queue_a"),
        ];

        assert!(reorder_composer_queue_message(&mut queue, 3, 1, false));
        assert_eq!(
            queue
                .iter()
                .filter(|message| message.session_id.as_str() == "session_queue_a")
                .map(|message| message.id)
                .collect::<Vec<_>>(),
            [3, 1, 2]
        );
        assert!(!reorder_composer_queue_message(&mut queue, 1, 4, true));
        assert_eq!(
            promote_composer_queue_message(&mut queue, 2)
                .expect("queued message should be promoted")
                .as_str(),
            "session_queue_a"
        );
        assert_eq!(
            queue
                .iter()
                .filter(|message| message.session_id.as_str() == "session_queue_a")
                .map(|message| message.id)
                .collect::<Vec<_>>(),
            [2, 3, 1]
        );
    }

