    #[gpui::test]
    fn runtime_selector_row_maps_mouse_wheel_to_hidden_horizontal_scroll(cx: &mut TestAppContext) {
        let scroll = gpui::ScrollHandle::new();
        let observed_scroll = scroll.clone();
        let (_, cx) = cx.add_window_view(|_, _| RuntimeSelectorScrollProbe { scroll });

        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
        cx.simulate_event(ScrollWheelEvent {
            position: point(px(80.0), px(20.0)),
            delta: ScrollDelta::Pixels(point(px(0.0), px(-120.0))),
            modifiers: Default::default(),
            touch_phase: gpui::TouchPhase::Moved,
        });
        cx.run_until_parked();

        assert!(
            observed_scroll.offset().x < px(0.0),
            "horizontal offset: {:?}",
            observed_scroll.offset().x
        );

        let source = include_str!("app.rs");
        let composer = source
            .split_once("    fn render_composer(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_runtime_failure("))
            .map(|(body, _)| body)
            .expect("composer renderer should remain inspectable");
        assert!(composer.contains(".overflow_x_scroll()"));
        assert!(!composer.contains(".overflow_x_scrollbar()"));
    }

    #[test]
    fn scroll_reveal_delta_only_moves_offscreen_children() {
        let viewport = Bounds {
            origin: point(px(100.0), px(40.0)),
            size: size(px(160.0), px(32.0)),
        };
        let visible = Bounds {
            origin: point(px(120.0), px(40.0)),
            size: size(px(32.0), px(32.0)),
        };
        let past_trailing_edge = Bounds {
            origin: point(px(240.0), px(40.0)),
            size: size(px(32.0), px(32.0)),
        };
        let before_leading_edge = Bounds {
            origin: point(px(60.0), px(40.0)),
            size: size(px(32.0), px(32.0)),
        };
        let below_viewport = Bounds {
            origin: point(px(120.0), px(80.0)),
            size: size(px(32.0), px(32.0)),
        };

        assert_eq!(
            scroll_reveal_delta(viewport, visible, RevealAxis::Horizontal),
            None
        );
        assert_eq!(
            scroll_reveal_delta(viewport, past_trailing_edge, RevealAxis::Horizontal),
            Some(px(-12.0))
        );
        assert_eq!(
            scroll_reveal_delta(viewport, before_leading_edge, RevealAxis::Horizontal),
            Some(px(40.0))
        );
        assert_eq!(
            scroll_reveal_delta(viewport, below_viewport, RevealAxis::Vertical),
            Some(px(-40.0))
        );
    }

