    /// Every pane renders a complete conversation because every member owns a
    /// complete view: the group opens one per member, loads the ones that have
    /// no timeline yet, and never hands a pane another session's view.
    #[test]
    fn group_panes_materialize_views_and_resolve_requests_for_their_own_session() {
        let source = include_str!("app.rs");

        let ensure = source
            .split_once("    fn ensure_session_group_views(")
            .and_then(|(_, tail)| {
                tail.split_once("\n    /// Points the group workspace at the session")
            })
            .map(|(body, _)| body)
            .expect("group view materialization should remain inspectable");
        // Every member gets a view, and every view without a timeline is loaded.
        assert!(ensure.contains("self.ensure_session_view(&session_id);"));
        assert!(ensure.contains("self.ensure_session_group_view_loaded(&session_id, cx);"));

        let load = source
            .split_once("    fn load_session_group_view(")
            .and_then(|(_, tail)| {
                tail.split_once("\n    /// Releases the views of sessions that just left a group.")
            })
            .map(|(body, _)| body)
            .expect("group view loading should remain inspectable");
        assert!(load.contains("fetch_authoritative_timeline_via_backend("));
        assert!(load.contains("session_group_view_loads"));
        assert!(load.contains("this.adopt_session_view_timeline(session_id, items);"));
        // The load is keyed by session id, so it cannot land in another view.
        assert!(!load.contains("session_generation"));

        let adopt = source
            .split_once("    fn adopt_session_view_timeline(")
            .and_then(|(_, tail)| {
                tail.split_once("\n    /// Re-derives the geometry of the borrowed view")
            })
            .map(|(body, _)| body)
            .expect("adopting a loaded timeline should remain inspectable");
        assert!(adopt.contains("replace_authoritative(session_id.clone(), items)"));
        assert!(adopt.contains("self.ensure_session_view(&session_id);"));
        assert!(adopt.contains("self.with_session_view(&session_id"));

        // The workspace materializes the member views before it lays out panes.
        let workspace = source
            .split_once("    fn render_session_group_workspace(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_session_group_node("))
            .map(|(body, _)| body)
            .expect("group workspace should remain inspectable");
        assert!(workspace.contains("self.ensure_session_group_views(group_id, cx);"));

        // The approval card captures its own session at paint time.
        let actions = source
            .split_once("    fn render_permission_response_actions(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_user_message_inline_content("))
            .map(|(body, _)| body)
            .expect("permission actions should remain inspectable");
        assert!(actions.contains("let resolve_session_id = self.timeline.session_id.clone();"));
        assert!(
            actions.contains("this.resolve_permission(\n                            session_id,")
        );
    }

    /// Every pane renders the same composer as the main workbench, reading its
    /// own session's view, so several sessions can be driven at once.
    #[test]
    fn every_group_pane_renders_the_real_composer_for_its_own_session() {
        let source = include_str!("app.rs");

        // The pane reuses the workbench composer instead of a second, simpler
        // one: there is exactly one composer implementation.
        let wrapper = source
            .split_once("\n    fn session_group_pane_with_composer(")
            .and_then(|(_, tail)| tail.split_once("\n    /// Gives every group member"))
            .map(|(body, _)| body)
            .expect("pane composer wrapper should remain inspectable");
        assert!(wrapper.contains("composer: AnyElement"));
        assert!(!source.contains("\n    fn render_session_group_pane_composer("));
        assert!(!source.contains("\n    fn composer_input_for("));

        // Composing targets the pane's own session: the send path reads the
        // borrowed view's session, not the sidebar selection.
        let submit = source
            .split_once("\n    fn submit_composer(")
            .and_then(|(_, tail)| tail.split_once("\n    fn take_composer_message("))
            .map(|(body, _)| body)
            .expect("composer submission should remain inspectable");
        assert!(submit.contains(".view_session_id"));
        assert!(!submit.contains("selected_session_id"));

        let take = source
            .split_once("\n    fn take_composer_message(")
            .and_then(|(_, tail)| tail.split_once("\n    /// Remote twin of"))
            .map(|(body, _)| body)
            .expect("composer message assembly should remain inspectable");
        assert!(take.contains("self.view_session_id.clone()?"));

        // Stopping acts on the borrowed view's session too.
        let interrupt = source
            .split_once("\n    fn interrupt_session_with_queue_behavior(")
            .and_then(|(_, tail)| tail.split_once("\n    fn continue_session("))
            .map(|(body, _)| body)
            .expect("interrupt should remain inspectable");
        assert!(interrupt.contains(".view_session_id.clone()"));

        // Every pane, focused or not, renders its own view and its own
        // composer. Focus decides the keyboard, never the content.
        let content = source
            .split_once("\n    fn render_session_group_pane_content(")
            .and_then(|(_, tail)| {
                tail.split_once("\n    /// Puts a pane's own composer under its conversation.")
            })
            .map(|(body, _)| body)
            .expect("group pane content should remain inspectable");
        // A pane borrows its own view for the render pass without re-weighing
        // it: the workspace hands every pane back through one weighed release
        // once the tree is built, and weighing per pane walked the previously
        // borrowed view's whole timeline once per pane, per frame.
        assert!(content.contains("self.borrow_session_view_unweighed(&pane_session_id)"));
        assert!(!content.contains("self.borrow_session_view(&pane_session_id)"));
        assert!(content.contains("self.render_agent_workbench_for(false, window, cx)"));
        // The composer is built while the pane's own view is borrowed.
        // Re-borrowing the primary between panes made a split store and reload a
        // view twice for every pane, every frame.
        assert!(content.contains("let composer = self.render_composer(window, cx, focused);"));
        // The find bar is built in the same borrow, and only for the focused
        // pane: it searches that pane's conversation, so a bar in every pane
        // would put two live inputs on one query.
        assert!(content.contains("let conversation_find = focused"));
        assert!(content.contains(".then(|| self.render_conversation_find(cx))"));
        assert!(!content.contains("self.release_session_view();"));
        assert!(
            content.contains(
                "session_group_pane_with_composer(conversation, conversation_find, composer, window, cx)"
            )
        );
        // The pane owns its element tree behind a cached view boundary, so it
        // also hands its own borrow back; the workspace only drops the views of
        // panes the layout no longer has.
        let pane_view = source
            .split_once("impl Render for SessionGroupPaneView {")
            .and_then(|(_, tail)| tail.split_once("\n/// Where a session tab would land"))
            .map(|(body, _)| body)
            .expect("the pane view should remain inspectable");
        assert!(pane_view.contains("this.render_session_group_pane(&group_id, pane, window, cx)"));
        assert!(pane_view.contains("this.release_session_view_unweighed();"));
        let workspace = source
            .split_once("    fn render_session_group_workspace(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_session_group_node("))
            .map(|(body, _)| body)
            .expect("group workspace should remain inspectable");
        assert!(
            workspace.contains("self.session_group_pane_views\n            .retain(|pane_id, _|")
        );
        assert!(workspace.contains("self.render_session_group_node(&group_id, node, cx)"));
        assert!(!workspace.contains("self.release_session_view();"));
        // The rendered conversation is the pane's own session, never whatever
        // view happens to be borrowed.
        assert!(!content.contains("selected_session_id"));
        assert!(!content.contains("agent_session_view_cache"));
    }

    /// A pane lays out and paints its rows after the render pass handed its
    /// view back, so the row renderer borrows that view again.
    ///
    /// Without it every row a non-focused pane painted resolved its payloads,
    /// its expansion state and its measured heights against the focused
    /// session's view: the process run kept the first estimates, the slack it
    /// left painted as a blank band, and switching focus rewrote the layout
    /// because the measurements landed in whichever view was borrowed.
    #[test]
    fn group_pane_rows_render_against_the_panes_own_view() {
        let source = include_str!("app.rs");

        // The virtual list closure carries the pane's session and borrows it
        // for the whole row build, which is where the payload lookups and the
        // height estimates happen.
        let timeline = source
            .split_once(
                "        let timeline_render_session_id = self.timeline.session_id.clone();",
            )
            .and_then(|(_, tail)| {
                tail.split_once(
                    "\n            .when_some(turn_preview_rail, |this, rail| this.child(rail));",
                )
            })
            .map(|(body, _)| body)
            .expect("the timeline surface should remain inspectable");
        assert!(timeline.contains("this.with_session_view_for_render("));
        assert!(timeline.contains("timeline_render_session_id.as_ref(),"));
        let borrows = timeline
            .find("this.with_session_view_for_render(")
            .expect("the row build should borrow the pane's view");
        let renders = timeline
            .find("this.render_timeline_turn(")
            .expect("the row build should render the pane's turn");
        assert!(borrows < renders);

        // The windowed process run builds its units and records what they
        // measured during prepaint too, so it carries the session as well.
        let run = source
            .split_once("struct TimelineProcessRun {")
            .and_then(|(_, tail)| tail.split_once("\nimpl TimelineProcessRun {"))
            .map(|(body, _)| body)
            .expect("the process run should remain inspectable");
        assert!(run.contains("session_id: Option<VibexSessionId>,"));

        let build = source
            .split_once("                build_unit: Box::new(move |index, window, cx| {")
            .and_then(|(_, tail)| tail.split_once("\n    fn command_permission_rows_are_linked("))
            .map(|(body, _)| body)
            .expect("the process unit builder should remain inspectable");
        assert!(build.contains("this.with_session_view_for_render(build_session_id.as_ref(),"));

        let prepaint = source
            .split_once("        if !measurements.is_empty() {")
            .and_then(|(_, tail)| tail.split_once("\n    fn paint(\n        &mut self,"))
            .map(|(body, _)| body)
            .expect("the process run prepaint should remain inspectable");
        assert!(prepaint.contains("this.with_session_view_for_render(session_id.as_ref(),"));
        assert!(
            prepaint
                .contains("this.record_timeline_process_unit_heights(&units, &measurements, cx)")
        );

        // The swap is unweighed: it happens once per rendered row, and the
        // render pass already weighs every view it hands back.
        let swap = source
            .split_once("    fn with_session_view_for_render<R>(")
            .and_then(|(_, tail)| {
                tail.split_once("\n    /// Hands the borrowed view back to the store")
            })
            .map(|(body, _)| body)
            .expect("the render borrow should remain inspectable");
        assert!(swap.contains("self.borrow_session_view_unweighed(session_id)"));
        assert!(swap.contains("self.release_session_view_unweighed();"));

        let insert = source
            .split_once("    fn insert_session_view(&mut self, key: String, entry: SessionView) {")
            .and_then(|(_, tail)| {
                tail.split_once("\n    /// Sessions whose view must survive eviction")
            })
            .map(|(body, _)| body)
            .expect("the transient insert should remain inspectable");
        assert!(insert.contains("self.session_views.insert(key.clone(), entry);"));
        assert!(!insert.contains("calculate_estimated_resident_bytes"));
        assert!(!insert.contains("pinned_session_view_ids"));
        assert!(!insert.contains("insert_bounded_session_view_with_pins"));

        // The timeline resolves its workspace from the view it renders, so a
        // pane never shows the focused pane's checkout or Agent.
        let file_changes = source
            .split_once("    fn agent_turn_file_changes_cached(")
            .and_then(|(_, tail)| tail.split_once("\n    /// File snapshots can be large,"))
            .map(|(body, _)| body)
            .expect("the turn file changes projection should remain inspectable");
        assert!(file_changes.contains("self\n            .view_session()"));
        assert!(!file_changes.contains("selected_session()"));

        let status = source
            .split_once("    fn render_agent_generation_status(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_runtime_controls("))
            .map(|(body, _)| body)
            .expect("the generation status renderer should remain inspectable");
        assert!(status.contains("self\n            .view_runtime_selection()"));

        // The composer renders for the borrowed view too: its cascade, its send
        // gate and its auto-continue countdown belong to the pane's own session,
        // not to whichever pane the sidebar selected.
        let composer = source
            .split_once("    fn render_composer(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_runtime_failure("))
            .map(|(body, _)| body)
            .expect("the composer renderer should remain inspectable");
        assert!(composer.contains("let selected_runtime = self.view_runtime_selection();"));
        assert!(!composer.contains("self.selected_runtime_selection()"));
        assert!(composer.contains("self.auto_continue_enabled(session_id)"));
        assert!(composer.contains("self.auto_continue_remaining_seconds(session_id)"));
    }

    /// There is exactly one copy of a session's view, and a fetch may only fill
    /// a view that has no timeline yet: a stale fetched copy must never replace
    /// the live view a pane is showing.
    #[test]
    fn a_session_view_is_filled_once_and_never_overwritten_by_a_stale_fetch() {
        let source = include_str!("app.rs");

        let load = source
            .split_once("    fn load_session_group_view(")
            .and_then(|(_, tail)| {
                tail.split_once("\n    /// Releases the views of sessions that just left a group.")
            })
            .map(|(body, _)| body)
            .expect("group view loading should remain inspectable");
        // A view that already has a timeline is only reloaded when the caller
        // asks for a forced catch-up. The guard runs for every group member on
        // every frame, so it looks the session up borrowed and only allocates an
        // owned key when a fetch is really queued.
        assert!(load.contains("if loaded && !force {"));
        assert!(load.contains("self.session_group_view_loads.contains(session_id.as_str())"));
        assert!(load.contains(
            "self.session_group_view_loads\n            .insert(session_id.as_str().to_string());"
        ));

        // The store keeps one entry per session; borrowing removes it and
        // releasing puts the very same entry back.
        let borrow = source
            .split_once("    fn borrow_session_view(")
            .and_then(|(_, tail)| {
                tail.split_once("\n    /// Whether `session_id` already owns a view")
            })
            .map(|(body, _)| body)
            .expect("view borrowing should remain inspectable");
        assert!(borrow.contains("self.session_views.remove(&key)"));
        assert!(borrow.contains("self.store_session_view(previous_key, previous)"));
        assert!(!borrow.contains(".cloned()"));
        assert!(!borrow.contains("contains_key"));
    }

    /// Selecting a member row has to move the group workspace with it, or the
    /// pane keeps painting another session's live view under its tab strip.
    #[test]
    fn selecting_a_group_member_focuses_its_pane_and_tab() {
        let source = include_str!("app.rs");
        let selection = source
            .split_once("    fn select_session_with_history(")
            .and_then(|(_, tail)| tail.split_once("\n    fn load_agent_session_timeline_remote("))
            .map(|(body, _)| body)
            .expect("session selection should remain inspectable");
        assert!(selection.contains("self.sync_session_group_focus(&session_id);"));

        let sync = source
            .split_once("    fn sync_session_group_focus(")
            .and_then(|(_, tail)| tail.split_once("\n    fn focus_session_group_pane("))
            .map(|(body, _)| body)
            .expect("group focus sync should remain inspectable");
        assert!(sync.contains("pane_containing_session(session_id.as_str())"));
        assert!(sync.contains("group.focused_pane_id = pane_id.clone();"));
        assert!(sync.contains("group.layout.focus_session(&pane_id, session_id.as_str());"));
        // A maximized workspace paints one pane, so the maximization has to
        // follow the selection.
        assert!(sync.contains("group.maximized_pane_id = Some(pane_id);"));

        // Selecting a session borrows that session's own view, so the
        // selection and the rendered conversation cannot disagree.
        let selection = source
            .split_once("    fn select_session_with_history(")
            .and_then(|(_, tail)| tail.split_once("\n    fn load_agent_session_timeline_remote("))
            .map(|(body, _)| body)
            .expect("session selection should remain inspectable");
        assert!(selection.contains("let had_view = self.borrow_session_view(&session_id);"));
        assert!(!selection.contains("stash_current_agent_session_view"));

        // A pane is focused only when its *active* tab is the selected session,
        // so the highlighted tab and the conversation always agree.
        let pane = source
            .split_once("    fn render_session_group_pane(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_session_group_pane_content("))
            .map(|(body, _)| body)
            .expect("group pane renderer should remain inspectable");
        assert!(pane.contains("active_session_id.as_deref() == Some(selected.as_str())"));
        assert!(!pane.contains("pane.session_ids\n                .iter()\n                .any"));
    }

    /// A group pane's strip is the preview strip's sibling: the same metrics,
    /// the same horizontal scroll and the same drag-to-reorder. A pane can hold
    /// more tabs than fit, and the tabs are the only way to reach the ones it is
    /// not showing.
    #[test]
    fn group_pane_tab_strip_scrolls_and_reorders_like_the_preview_strip() {
        let source = include_str!("app.rs");
        let strip = source
            .split_once("    fn render_session_group_pane(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_session_group_pane_content("))
            .map(|(body, _)| body)
            .expect("group pane renderer should remain inspectable");

        assert!(strip.contains(".overflow_x_scroll()"));
        assert!(strip.contains(".track_scroll(&tab_scroll)"));
        assert!(strip.contains("restrict_scroll_to_axis"));
        // The active tab has to be reachable without the user scrolling for it.
        assert!(strip.contains("tab_scroll.scroll_to_item(index)"));
        // A tab dropped on a sibling tab names its landing slot.
        assert!(strip.contains("SessionGroupTabDropTarget"));
        assert!(strip.contains("this.reorder_session_group_tab("));

        let reorder = source
            .split_once("    fn reorder_session_group_tab(")
            .and_then(|(_, tail)| {
                tail.split_once("\n    /// Records which edge of which pane a drag is hovering")
            })
            .map(|(body, _)| body)
            .expect("group tab reorder should remain inspectable");
        // One gesture covers both a reorder inside a pane and a move into
        // another pane's strip.
        assert!(reorder.contains("move_session_to_pane(session_id, pane_id)"));
        assert!(reorder.contains("reorder_pane_session("));
        assert!(reorder.contains("self.queue_ui_state();"));
    }

    /// The group pane's tab menu is the preview tab's menu minus the pane-only
