    #[test]
    fn title_bar_navigation_route_tracks_restorable_workbench_state() {
        let mut ui_state = DesktopUiStateV1::default();
        ui_state.workbench.active_tab = "management".to_string();
        ui_state.workbench.selected_workspace_id = Some("workspace_title_bar".to_string());
        ui_state.workbench.selected_file_path = Some("src/app.rs".to_string());
        ui_state.workbench.selected_git_path = Some("src/lib.rs".to_string());
        ui_state.terminal.selected_terminal_id = Some("terminal_title_bar".to_string());
        ui_state.workbench.right_rail_visible = false;
        let session_id = VibexSessionId::parse("session_title_bar").unwrap();

        let route = workbench_route(&ui_state, Some(&session_id));

        assert_eq!(route.workspace_id.as_deref(), Some("workspace_title_bar"));
        assert_eq!(route.session_id.as_deref(), Some("session_title_bar"));
        assert_eq!(route.primary_tab, "management");
        assert!(route.right_rail.is_empty());
        assert_eq!(route.selected_file_path.as_deref(), Some("src/app.rs"));
        assert_eq!(route.selected_git_path.as_deref(), Some("src/lib.rs"));
        assert_eq!(
            route.selected_terminal_id.as_deref(),
            Some("terminal_title_bar")
        );

        ui_state.workbench.right_rail_visible = true;
        ui_state.right_rail.selected_activity_id = Some("rail_plugin_custom_web".into());
        assert_eq!(
            workbench_route(&ui_state, Some(&session_id)).right_rail,
            "rail_plugin_custom_web"
        );
    }

    #[test]
    fn html_data_image_capture_is_bounded_to_base64_images() {
        let encoded = BASE64_STANDARD.encode([137_u8, 80, 78, 71]);
        let html = format!(r#"<p><img src="data:image/png;base64,{encoded}"></p>"#);
        let (format, bytes) = decode_html_data_image(&html).expect("image data should decode");
        assert_eq!(format, gpui::ImageFormat::Png);
        assert_eq!(bytes, [137_u8, 80, 78, 71]);
        assert!(decode_html_data_image("<p>plain text</p>").is_none());
        assert!(decode_html_data_image("data:image/png;base64,not-base64!").is_none());
    }

    #[test]
    fn timeline_body_height_estimate_expands_for_long_markdown() {
        assert_eq!(estimated_wrapped_lines("", 72), 1);
        assert_eq!(estimated_wrapped_lines("short", 72), 1);
        assert_eq!(estimated_wrapped_lines(&"x".repeat(73), 72), 2);
        assert_eq!(estimated_wrapped_lines(&"line\n".repeat(40), 72), 40);
        assert!(estimated_markdown_body_height(&"line\n".repeat(40), 72) > 288.0);
        // Detail pre blocks stay bounded by their 160px max height.
        assert_eq!(estimated_pre_block_height(&"line\n".repeat(40)), 160.0);
        assert_eq!(estimated_pre_block_height("one line"), 36.0);
    }

