    #[test]
    fn user_message_bubble_shrinks_inside_the_timeline_width_contract() {
        let source = include_str!("app.rs");
        let row = source
            .split_once("    fn render_user_message_row(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_agent_message_row("))
            .map(|(body, _)| body)
            .expect("user-message row should remain inspectable");
        let helper = source
            .split_once("fn render_user_message_bubble(")
            .and_then(|(_, tail)| tail.split_once("\n}\n\n#[cfg(test)]"))
            .map(|(body, _)| body)
            .expect("user-message bubble helper should remain inspectable");

        // The 78% width contract stays on the definite-width row wrapper;
        // the bubble hugs its content and shrinks under that constraint.
        assert!(row.contains(".w(relative(USER_MESSAGE_COLUMN_WIDTH_RATIO))"));
        assert!(!row.contains(".max_w(relative(USER_MESSAGE_COLUMN_WIDTH_RATIO))"));
        assert!(helper.contains("Bubble::new()"));
        assert!(helper.contains("MessageAlignment::End"));
        assert!(helper.contains("BubbleContent::new()"));
        assert!(helper.contains(".flex_shrink(1.0)"));
        assert!(helper.contains(".max_w_full()"));
        assert!(helper.contains(".rounded(px(12.0))"));
        assert!(!helper.contains(".overflow_y_scrollbar()"));
        // A queued delivery rides the library reaction region on the bubble's
        // lower edge, never a chip above it or a tinted bubble edge.
        // Every edge mark — the queued delivery and the goal badge — rides the
        // library reaction region on the bubble's lower edge, never a chip
        // above it, a glyph in the body, or a tinted bubble edge.
        assert!(row.contains("render_user_message_edge_reactions"));
        assert!(!row.contains("render_user_message_delivery_hint"));
        assert!(!row.contains(".border_color("));
        assert!(helper.contains("edge_reactions"));
        assert!(helper.contains(".reactions("));
        assert!(helper.contains("USER_MESSAGE_EDGE_REACTION_HANG"));
        assert!(!helper.contains("border_1"));
        assert!(!helper.contains("border_color"));
    }

    #[test]
    fn user_message_delivery_marker_colors_the_edge_reaction_by_delivery() {
        let source = include_str!("app.rs");
        let marker = source
            .split_once("fn render_user_message_delivery_button(")
            .and_then(|(_, tail)| tail.split_once("\nfn render_user_message_bubble("))
            .map(|(body, _)| body)
            .expect("delivery marker helper should remain inspectable");

        // The two deliveries stay distinguishable by glyph, by hue on the
        // glyph, and by the library tooltip that carries the label the old chip
        // printed. The mark is an icon-only ghost button inside the bubble's
        // reaction region, not a hand-rolled tooltip host.
        assert!(marker.contains("BubbleReactions::new()"));
        assert!(marker.contains("Button::new("));
        assert!(marker.contains(".ghost()"));
        assert!(marker.contains(".xsmall()"));
        assert!(marker.contains("icons/vibex/corner-down-right.svg"));
        assert!(marker.contains("icons/vibex/rotate-ccw.svg"));
        assert!(marker.contains("cx.theme().success"));
        assert!(marker.contains("cx.theme().warning"));
        assert!(marker.contains(".tooltip("));
        assert!(marker.contains(".accessibility_label("));
        assert!(marker.contains(".text_color(accent)"));
        assert!(!marker.contains("Tooltip::new"));
    }

    #[test]
    fn opened_session_view_cache_is_bounded_and_refreshes_recency() {
        assert_eq!(AGENT_SESSION_VIEW_CACHE_LIMIT, 6);
        assert_eq!(AGENT_SESSION_VIEW_CACHE_BYTES, 128 * 1024 * 1024);
        let pinned = BTreeSet::new();
        let mut cache = BTreeMap::new();
        let mut lru = VecDeque::new();
        insert_bounded_session_view_with_pins(
            &mut cache,
            &mut lru,
            "session_a".into(),
            1,
            SessionViewBudget {
                limit: 2,
                max_bytes: usize::MAX,
            },
            |_| 1,
            &pinned,
        );
        insert_bounded_session_view_with_pins(
            &mut cache,
            &mut lru,
            "session_b".into(),
            2,
            SessionViewBudget {
                limit: 2,
                max_bytes: usize::MAX,
            },
            |_| 1,
            &pinned,
        );
        touch_session_view_lru(&mut lru, "session_a");
        insert_bounded_session_view_with_pins(
            &mut cache,
            &mut lru,
            "session_c".into(),
            3,
            SessionViewBudget {
                limit: 2,
                max_bytes: usize::MAX,
            },
            |_| 1,
            &pinned,
        );

        assert_eq!(
            lru.into_iter().collect::<Vec<_>>(),
            ["session_a", "session_c"]
        );
        assert_eq!(cache.get("session_a"), Some(&1));
        assert_eq!(cache.get("session_b"), None);
        assert_eq!(cache.get("session_c"), Some(&3));
    }

    /// A pinned view belongs to a session a pane is showing, so eviction has to
    /// skip it even when it is the least recently used entry.
    #[test]
    fn pinned_session_views_survive_eviction() {
        let pinned = ["session_a".to_string()]
            .into_iter()
            .collect::<BTreeSet<_>>();
        let mut cache = BTreeMap::new();
        let mut lru = VecDeque::new();
        for key in ["session_a", "session_b", "session_c"] {
            insert_bounded_session_view_with_pins(
                &mut cache,
                &mut lru,
                key.into(),
                key,
                SessionViewBudget {
                    limit: 2,
                    max_bytes: usize::MAX,
                },
                |_| 1,
                &pinned,
            );
        }
        assert_eq!(cache.get("session_a"), Some(&"session_a"));
        assert_eq!(cache.get("session_b"), None);
        assert_eq!(cache.get("session_c"), Some(&"session_c"));
    }

    #[test]
    fn opened_session_view_cache_enforces_a_total_byte_budget() {
        let pinned = BTreeSet::new();
        let mut cache = BTreeMap::new();
        let mut lru = VecDeque::new();
        for (key, bytes) in [("session_a", 4_usize), ("session_b", 4), ("session_c", 7)] {
            insert_bounded_session_view_with_pins(
                &mut cache,
                &mut lru,
                key.into(),
                bytes,
                SessionViewBudget {
                    limit: 6,
                    max_bytes: 10,
                },
                |bytes| *bytes,
                &pinned,
            );
        }
        assert_eq!(
            lru.iter().map(String::as_str).collect::<Vec<_>>(),
            ["session_c"]
        );
        assert_eq!(cache.get("session_c"), Some(&7));

        insert_bounded_session_view_with_pins(
            &mut cache,
            &mut lru,
            "session_oversized".into(),
            11,
            SessionViewBudget {
                limit: 6,
                max_bytes: 10,
            },
            |bytes| *bytes,
            &pinned,
        );
        assert!(!cache.contains_key("session_oversized"));
        assert_eq!(cache.get("session_c"), Some(&7));
    }

    /// The store is on the borrow/release path a split walks twice per pane per
    /// frame, so it must not re-walk every cached view's timeline to weigh them.
    /// A stored view is frozen, so its footprint is refreshed once on the way in
    /// and the eviction pass only sums cached numbers.
    #[test]
    fn storing_a_session_view_weighs_cached_views_without_rescanning_them() {
        let source = include_str!("app.rs");
        let store = source
            .split_once(
                "    fn store_session_view(&mut self, key: String, mut entry: SessionView) {",
            )
            .and_then(|(_, tail)| {
                tail.split_once("\n    /// Sessions whose view must survive eviction")
            })
            .map(|(body, _)| body)
            .expect("the session view store should remain inspectable");
        // The footprint is measured exactly once, for the incoming view.
        assert_eq!(
            store
                .matches("calculate_estimated_resident_bytes()")
                .count(),
            1
        );
        assert!(store.contains("entry.resident_bytes = "));
        // The eviction pass weighs cached entries from their stored number.
        assert!(store.contains("|entry| entry.resident_bytes,"));
        // The pinned set is only built when the store can actually evict.
        assert!(store.contains("let may_evict ="));
        assert!(store.contains("BTreeSet::new()"));

        let insert = source
            .split_once("fn insert_bounded_session_view_with_pins<T>(")
            .and_then(|(_, tail)| tail.split_once("\nfn insert_bounded_timeline_projection<T>("))
            .map(|(body, _)| body)
            .expect("the bounded session view store should remain inspectable");
        assert!(insert.contains(".map(&weight)"));
        assert!(!insert.contains("calculate_estimated_resident_bytes"));
    }

